# -*- coding: utf-8 -*-
"""105 декораций ролика «18 ноября — День Ионы».

Каждая — функция времени f(t) -> svg. Все нарисованы ЗАНОВО под этот текст
(R-0019): ни один кадр не взят у «13», «14», «15» и «16 ноября».
Его правила 14.11: настоящий кадр лежит ВНУТРИ сцены (метка mesto_stoka),
сцены не пустые, предметы узнаваемые, в каждой сцене живой огонёк.

СОБИРАЕТСЯ sobrat_lok.py из частей — руками этот файл не правят.
"""
import math, random
from baza import *
import anim as A

# ═══ из lok_obshchee.py ═══
_RUKI = []        # точки крепления внешних рук, набираются первым проходом
_SOBRANO = None   # готовый список для второго прохода (None = проход первый)
_NICH = []        # руки, объявленные ничьими (крупный план кистей)
_FIGURY = []      # (x, плечо, погашено, ширина, рост) — для гейта
_PRIKLEENO = []   # какие внешние руки сели на плечо фигуры — для гейта


def ruki_sbros():
    """Начать первый проход: забыть прежние руки."""
    global _RUKI, _SOBRANO
    _RUKI, _SOBRANO = [], None
    del _FIGURY[:], _PRIKLEENO[:], _NICH[:]


def ruki_gotovo():
    """Закрыть первый проход: со следующего вызова figura прячет рукава."""
    global _SOBRANO
    _SOBRANO = list(_RUKI)
    del _FIGURY[:], _PRIKLEENO[:]     # фигуры первого прохода не считаем


def ruki_spisok():
    """Что собрано первым проходом (для гейта anatomiya.py)."""
    return list(_RUKI)


def anatomiya_svodka():
    """Для гейта: фигуры, внешние руки и руки, не севшие ни на одно плечо.

    Сирота ДЕЛИТСЯ НАДВОЕ, и это важно:
    · «на фигуре» — рука растёт из туловища мимо плеча. Это и есть третья
      рука (R-0051), сборка с такой рукой не идёт;
    · «вне фигур» — крупный план кистей там, где человека в кадре нет
      (руки держат шапку, тянут ухват). Это норма, только отчёт.
    """
    siroty = [r for r in _RUKI if r not in _PRIKLEENO]
    na_figure = []
    for hx, hy in siroty:
        for fx, fpl, _p, w_, h_ in _FIGURY:
            if abs(hx - fx) <= w_ * .70 and -h_ * .10 <= hy - fpl <= h_ * .62:
                na_figure.append((hx, hy, fx, fpl))
                break
    return {"figur": len(_FIGURY), "ruk": len(_RUKI), "nichih": len(_NICH),
            "pogasheno": sum(f[2] for f in _FIGURY), "siroty": siroty,
            "na_figure": na_figure,
            "bez_svoih": [f for f in _FIGURY if f[2] >= 2]}


def scena(fn, t):
    """Собрать сцену в два прохода — иначе у фигуры вырастает третья рука."""
    ruki_sbros()
    fn(t)
    ruki_gotovo()
    out = fn(t)
    global _SOBRANO
    _SOBRANO = None
    return out


def figura(x, y, h_, t, col="#1b1822", kant="#cfe4f5", platok=False, ph=.0,
           profil=False, op=1.0, tulup=False, naklon=0.0, boroda=False,
           shapka=False, lico=True, koja="#f0cfae"):
    """ЧЕЛОВЕК, А НЕ СИЛУЭТ. Его правило R-0047: человек должен опознаваться с
    первого взгляда. Поэтому у фигуры есть лицо (глаза с бликом, брови, нос,
    румянец), одежда с поясом и оторочкой, рукава и обувь, а у головы —
    платок, шапка или волосы с бородой.

    x, y — середина и уровень пола, h_ — полный рост. Кант обязателен: тёмная
    фигура без канта сливается с тёмным фоном избы.
    """
    w_ = h_ * .42
    hh = h_ * .145                      # радиус головы
    gy = y - h_ * .845                  # центр головы
    dy = 3.0 * A.w(t, .62, ph)          # дыхание
    ug = naklon * A.w(t, 1.4, ph)
    sgn = 1 if not profil else 1
    s = (f'<g transform="translate(0,{dy:.1f}) rotate({ug:.2f} {x:.0f} {y:.0f})"'
         f' opacity="{op:.2f}">')
    s += ten(x, y + h_ * .012, w_ * .62, h_ * .022, .45)
    # обувь: два валенка
    for i in (-1, 1):
        s += (f'<path d="M{x+i*w_*.22-w_*.11:.0f},{y-h_*.085:.0f} h{w_*.22:.0f}'
              f' v{h_*.062:.0f} q0,{h_*.025:.0f} {-w_*.07:.0f},{h_*.025:.0f}'
              f' h{-w_*.09:.0f} q{-w_*.06:.0f},0 {-w_*.06:.0f},{-h_*.025:.0f} Z"'
              f' fill="#3b2f26" stroke="{K}" stroke-width="{max(2, h_*.011):.1f}"/>')
    # одежда: трапеция от плеч до подола
    plech = y - h_ * .66
    pod = y - h_ * .07
    s += (f'<path d="M{x-w_*.33:.0f},{plech:.0f} q{w_*.33:.0f},{-h_*.055:.0f} {w_*.66:.0f},0'
          f' L{x+w_*.56:.0f},{pod:.0f} q{-w_*.56:.0f},{h_*.045:.0f} {-w_*1.12:.0f},0 Z"'
          f' fill="{col}" stroke="{K}" stroke-width="{max(2, h_*.012):.1f}"/>')
    # пояс и оторочка подола — без них одежда читается мешком
    s += (f'<path d="M{x-w_*.46:.0f},{y-h_*.40:.0f} q{w_*.46:.0f},{h_*.03:.0f} {w_*.92:.0f},0"'
          f' fill="none" stroke="{MED}" stroke-width="{max(3, h_*.022):.1f}" opacity=".9"/>')
    s += (f'<path d="M{x-w_*.56:.0f},{pod-h_*.03:.0f} q{w_*.56:.0f},{h_*.045:.0f} {w_*1.12:.0f},0"'
          f' fill="none" stroke="{kant}" stroke-width="{max(2, h_*.012):.1f}" opacity=".45"/>')
    if tulup:                           # тулуп: опушка по вороту и запах
        s += (f'<ellipse cx="{x:.0f}" cy="{plech+h_*.01:.0f}" rx="{w_*.40:.0f}"'
              f' ry="{h_*.035:.0f}" fill="{kant}" opacity=".55"/>')
        s += (f'<path d="M{x:.0f},{plech+h_*.03:.0f} L{x+w_*.10:.0f},{pod-h_*.02:.0f}"'
              f' stroke="{K}" stroke-width="{max(2, h_*.009):.1f}" opacity=".6" fill="none"/>')
    # рукава вдоль тела, живые. Рукав НЕ рисуется на том плече, откуда сцена
    # уже вывела свою руку через rukav(): иначе у человека три руки (R-0051).
    _pog = 0
    for i in (-1, 1):
        rx = x + i * w_ * .40
        sel = [(hx, hy) for hx, hy in (_SOBRANO or ())
               if abs(hx - rx) <= w_ * .80 and abs(hy - (plech + h_ * .02)) <= h_ * .30]
        if sel:
            _pog += 1
            for r in sel:
                if r not in _PRIKLEENO:
                    _PRIKLEENO.append(r)
            continue
        a = i * (12 + 5 * A.w(t, 1.9, ph + (0 if i < 0 else .4)))
        s += (f'<g transform="rotate({a:.1f} {rx:.0f} {plech+h_*.02:.0f})">'
              f'<rect x="{rx-w_*.11:.0f}" y="{plech+h_*.01:.0f}" width="{w_*.22:.0f}"'
              f' height="{h_*.40:.0f}" rx="{w_*.11:.0f}" fill="{col}" stroke="{K}"'
              f' stroke-width="{max(2, h_*.011):.1f}"/>'
              f'<rect x="{rx-w_*.10:.0f}" y="{plech+h_*.34:.0f}" width="{w_*.20:.0f}"'
              f' height="{h_*.045:.0f}" rx="{w_*.02:.0f}" fill="{kant}" opacity=".5"/></g>')
    # ПОДЛОЖКА УБОРА — до головы, иначе платок и шапка закрывают лицо
    if platok:
        s += (f'<path d="M{x-hh*1.22:.0f},{gy-hh*.04:.0f} a{hh*1.22:.0f},{hh*1.26:.0f} 0 0 1'
              f' {hh*2.44:.0f},0 q{-hh*.10:.0f},{hh*1.40:.0f} {-hh*1.22:.0f},{hh*1.62:.0f}'
              f' q{-hh*1.12:.0f},{-hh*.22:.0f} {-hh*1.22:.0f},{-hh*1.62:.0f} Z"'
              f' fill="{TKAN}" stroke="{K}" stroke-width="{max(2, h_*.011):.1f}"/>')
    # шея и голова
    s += (f'<rect x="{x-hh*.34:.0f}" y="{gy+hh*.72:.0f}" width="{hh*.68:.0f}"'
          f' height="{hh*.55:.0f}" fill="{koja}" stroke="{K}" stroke-width="{max(2, h_*.01):.1f}"/>')
    s += (f'<ellipse cx="{x:.0f}" cy="{gy:.0f}" rx="{hh:.0f}" ry="{hh*1.06:.0f}"'
          f' fill="{koja}" stroke="{K}" stroke-width="{max(2, h_*.012):.1f}"/>')
    if lico and hh > 9:
        gl = hh * .30 if not profil else hh * .40
        mig = 1 if not A.blink(t, 4.1 + (ph * 3 % 2), ph) else 0
        for i in ((1,) if profil else (-1, 1)):
            ex = x + (gl if profil else i * gl)
            if mig:
                s += (f'<ellipse cx="{ex:.0f}" cy="{gy-hh*.08:.0f}" rx="{hh*.13:.0f}"'
                      f' ry="{hh*.16:.0f}" fill="#2b2118"/>')
                s += (f'<circle cx="{ex+hh*.05:.0f}" cy="{gy-hh*.14:.0f}" r="{hh*.05:.0f}"'
                      f' fill="#ffffff" opacity=".9"/>')
            else:
                s += (f'<path d="M{ex-hh*.14:.0f},{gy-hh*.08:.0f} q{hh*.14:.0f},{hh*.10:.0f}'
                      f' {hh*.28:.0f},0" fill="none" stroke="#2b2118"'
                      f' stroke-width="{max(2, hh*.10):.1f}" stroke-linecap="round"/>')
            s += (f'<path d="M{ex-hh*.18:.0f},{gy-hh*.33:.0f} q{hh*.18:.0f},{-hh*.12:.0f}'
                  f' {hh*.36:.0f},0" fill="none" stroke="#4a3526"'
                  f' stroke-width="{max(2, hh*.08):.1f}" stroke-linecap="round"/>')
        # нос и рот
        if profil:
            s += (f'<path d="M{x+hh*.72:.0f},{gy+hh*.02:.0f} l{hh*.22:.0f},{hh*.16:.0f}'
                  f' l{-hh*.22:.0f},{hh*.06:.0f}" fill="{koja}" stroke="{K}"'
                  f' stroke-width="{max(2, hh*.08):.1f}" stroke-linejoin="round"/>')
        else:
            s += (f'<path d="M{x:.0f},{gy-hh*.02:.0f} l{-hh*.08:.0f},{hh*.26:.0f}'
                  f' q{hh*.08:.0f},{hh*.06:.0f} {hh*.16:.0f},0" fill="none" stroke="#b08763"'
                  f' stroke-width="{max(2, hh*.08):.1f}" stroke-linecap="round"/>')
        s += (f'<path d="M{x-hh*.20:.0f},{gy+hh*.46:.0f} q{hh*.20:.0f},{hh*.20:.0f}'
              f' {hh*.40:.0f},0" fill="none" stroke="#9c4a3c"'
              f' stroke-width="{max(2, hh*.10):.1f}" stroke-linecap="round"/>')
        for i in (-1, 1):               # румянец
            s += (f'<ellipse cx="{x+i*hh*.56:.0f}" cy="{gy+hh*.28:.0f}" rx="{hh*.20:.0f}"'
                  f' ry="{hh*.13:.0f}" fill="#e08a74" opacity=".35"/>')
    if boroda:
        # Борода начинается НИЖЕ РТА и расчёсана прядями: сплошное светлое
        # пятно от подбородка читалось как повязка на пол-лица (осмотр 14.11).
        s += (f'<path d="M{x-hh*.80:.0f},{gy+hh*.62:.0f} q{hh*.14:.0f},{hh*1.10:.0f}'
              f' {hh*.80:.0f},{hh*1.26:.0f} q{hh*.66:.0f},{-hh*.16:.0f} {hh*.80:.0f},{-hh*1.26:.0f}'
              f' q{-hh*.80:.0f},{hh*.34:.0f} {-hh*1.60:.0f},0 Z" fill="#ded3c4"'
              f' stroke="{K}" stroke-width="{max(2, h_*.009):.1f}"/>')
        for i in (-1, 0, 1):            # пряди
            s += (f'<path d="M{x+i*hh*.36:.0f},{gy+hh*.76:.0f} q{i*hh*.10:.0f},{hh*.52:.0f}'
                  f' {i*hh*.06:.0f},{hh*.92:.0f}" fill="none" stroke="#b9ab99"'
                  f' stroke-width="{max(2, hh*.07):.1f}" opacity=".75"/>')
        # усы — две дуги по сторонам от рта, рот остаётся виден
        for i in (-1, 1):
            s += (f'<path d="M{x:.0f},{gy+hh*.40:.0f} q{i*hh*.30:.0f},{-hh*.04:.0f}'
                  f' {i*hh*.52:.0f},{hh*.18:.0f}" fill="none" stroke="#ded3c4"'
                  f' stroke-width="{max(2, hh*.14):.1f}" stroke-linecap="round"/>')
    if not platok and not shapka and not tulup:      # волосы шапкой поверх головы
        s += (f'<path d="M{x-hh*1.02:.0f},{gy-hh*.02:.0f} a{hh*1.02:.0f},{hh*1.08:.0f} 0 0 1'
              f' {hh*2.04:.0f},0 q{-hh*.26:.0f},{-hh*.30:.0f} {-hh*.72:.0f},{-hh*.18:.0f}'
              f' q{-hh*.40:.0f},{hh*.10:.0f} {-hh*1.32:.0f},{hh*.18:.0f} Z"'
              f' fill="#4a3526" stroke="{K}" stroke-width="{max(2, h_*.009):.1f}"/>')
    if platok:                          # передние края платка и узелок
        for i in (-1, 1):
            s += (f'<path d="M{x+i*hh*1.18:.0f},{gy-hh*.10:.0f} q{-i*hh*.16:.0f},{hh*1.10:.0f}'
                  f' {i*hh*.04:.0f},{hh*1.62:.0f} q{-i*hh*.34:.0f},{-hh*.10:.0f}'
                  f' {-i*hh*.30:.0f},{-hh*1.58:.0f} Z" fill="{TKAN}" stroke="{K}"'
                  f' stroke-width="{max(2, h_*.009):.1f}"/>')
        s += (f'<ellipse cx="{x:.0f}" cy="{gy+hh*1.46:.0f}" rx="{hh*.34:.0f}"'
              f' ry="{hh*.24:.0f}" fill="{TKAN}" stroke="{K}"'
              f' stroke-width="{max(2, h_*.009):.1f}"/>')
        s += (f'<path d="M{x-hh*.86:.0f},{gy-hh*.42:.0f} q{hh*.86:.0f},{-hh*.34:.0f}'
              f' {hh*1.72:.0f},0" fill="none" stroke="#f2e2c8"'
              f' stroke-width="{max(2, hh*.11):.1f}" opacity=".55"/>')
    elif shapka or tulup:               # тулья, околыш и меховые уши поверх головы
        s += (f'<path d="M{x-hh*1.14:.0f},{gy-hh*.42:.0f} a{hh*1.14:.0f},{hh*1.20:.0f} 0 0 1'
              f' {hh*2.28:.0f},0 Z" fill="#4a3a2c" stroke="{K}"'
              f' stroke-width="{max(2, h_*.011):.1f}"/>')
        for i in (-1, 1):
            s += (f'<ellipse cx="{x+i*hh*1.10:.0f}" cy="{gy+hh*.10:.0f}" rx="{hh*.24:.0f}"'
                  f' ry="{hh*.44:.0f}" fill="#8a6a4a" stroke="{K}"'
                  f' stroke-width="{max(2, h_*.009):.1f}"/>')
        # околыш идёт ПО ЛБУ, выше глаз: прежде он садился ровно на линию
        # глаз и лицо оставалось без мимики (осмотр 14.11, 20 планов)
        s += (f'<rect x="{x-hh*1.16:.0f}" y="{gy-hh*.62:.0f}" width="{hh*2.32:.0f}"'
              f' height="{hh*.32:.0f}" rx="{hh*.14:.0f}" fill="#8a6a4a" stroke="{K}"'
              f' stroke-width="{max(2, h_*.009):.1f}"/>')
    # светлый кант по плечам: отделяет фигуру от тёмного фона
    s += (f'<path d="M{x-w_*.33:.0f},{plech:.0f} q{w_*.33:.0f},{-h_*.055:.0f} {w_*.66:.0f},0"'
          f' fill="none" stroke="{kant}" stroke-width="{max(2, h_*.014):.1f}" opacity=".75"'
          f' stroke-linecap="round"/>')
    _FIGURY.append((round(x, 1), round(plech, 1), _pog, round(w_, 1), round(h_, 1)))
    return s + '</g>'


def rukav(x, y, dl, ug, t, col="#2a2430", kant="#cfe4f5", ph=.0, amp=7.0,
          nichya=False):
    """Рукав без кисти: правило проекта — рук в кадре не рисуем, работает
    сам предмет. Рукав ходит, предмет на его конце двигают отдельно.

    nichya=True — рука НИЧЬЯ: крупный план кистей, человека в кадре нет
    (руки держат шапку, хлопают в ладоши мимо моли). Такая рука не гасит
    рукав соседней фигуры и не считается третьей рукой в гейте anatomiya.py.
    """
    a = math.radians(ug + amp * A.w(t, .9, ph))
    x2, y2 = x + dl * math.cos(a), y + dl * math.sin(a)
    if _SOBRANO is None:                # первый проход: запомнили плечо
        (_NICH if nichya else _RUKI).append((x, y))
    return (f'<line x1="{x:.0f}" y1="{y:.0f}" x2="{x2:.0f}" y2="{y2:.0f}"'
            f' stroke="{col}" stroke-width="{max(14, dl*.19):.0f}" stroke-linecap="round"/>'
            f'<line x1="{x:.0f}" y1="{y:.0f}" x2="{x2:.0f}" y2="{y2:.0f}"'
            f' stroke="{kant}" stroke-width="3" opacity=".30"/>'), (x2, y2)


def mokryy_sneg(t, n=34, seed=5, op=.7, sp=1.0):
    """Первый мокрый снег: падает тяжело, почти без вихря, кое-где каплей."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        x0 = rnd.random() * W
        k = ((t * .19 * sp) + rnd.random()) % 1.0
        y = -60 + k * (H + 120)
        r = 3.4 + rnd.random() * 4.6
        dx = 16 * A.w(t, 2.6 + rnd.random(), rnd.random())
        if i % 5 == 0:                  # капля-ляпка
            s += (f'<ellipse cx="{x0+dx:.0f}" cy="{y:.0f}" rx="{r*.7:.1f}" ry="{r*1.5:.1f}"'
                  f' fill="#e7f1fb" opacity="{op*.8:.2f}"/>')
        else:
            s += (f'<circle cx="{x0+dx:.0f}" cy="{y:.0f}" r="{r:.1f}" fill="#f2f8ff"'
                  f' opacity="{op:.2f}"/>')
    return s


def goloe_derevo(x, base, h_, t, seed=3, vetok=7, kant="#2a2b33", inej_=False):
    """Голое дерево поздней осени: ствол и ветки качаются целиком."""
    rnd = random.Random(seed)
    sway = 2.6 * A.w(t, 3.4, seed * .11)
    s = f'<g transform="rotate({sway:.2f} {x:.0f} {base:.0f})">'
    s += (f'<path d="M{x-h_*.045:.0f},{base:.0f} L{x-h_*.018:.0f},{base-h_:.0f}'
          f' L{x+h_*.018:.0f},{base-h_:.0f} L{x+h_*.045:.0f},{base:.0f} Z"'
          f' fill="url(#derev)" {o(5)}/>')
    for i in range(vetok):
        p = .35 + .6 * (i / max(1, vetok - 1))
        yy = base - h_ * p
        sgn = -1 if i % 2 else 1
        dl = h_ * (.30 - .16 * p) * (.8 + rnd.random() * .5)
        s += (f'<path d="M{x:.0f},{yy:.0f} q{sgn*dl*.6:.0f},{-dl*.28:.0f}'
              f' {sgn*dl:.0f},{-dl*.52:.0f}" fill="none" stroke="{kant}"'
              f' stroke-width="{max(3, 9-i):.0f}" stroke-linecap="round"/>')
        if inej_:
            s += (f'<path d="M{x:.0f},{yy:.0f} q{sgn*dl*.6:.0f},{-dl*.28:.0f}'
                  f' {sgn*dl:.0f},{-dl*.52:.0f}" fill="none" stroke="#e9f4ff"'
                  f' stroke-width="3" opacity=".55"/>')
    return s + '</g>'


def gryaz_polosa(y, h_=70, col="#4a4038", op=1.0):
    """Голая мокрая земля: ноябрь без снега, блестящая колея."""
    s = (f'<rect x="0" y="{y:.0f}" width="{W}" height="{h_+40:.0f}" fill="{col}"'
         f' opacity="{op:.2f}"/>')
    for i in range(7):
        s += (f'<ellipse cx="{120+i*280}" cy="{y+h_*.5+((i%3)-1)*14:.0f}"'
              f' rx="{90+i*9}" ry="{10+(i%3)*4}" fill="#6a7a84" opacity=".34"/>')
    return s


def luchina(x, y, t, s_=1.0, ph=.0):
    """Лучина — тонкая щепка, горит вместо лампы. Огонёк мелкий и живой."""
    s = (f'<path d="M{x:.0f},{y:.0f} l{-6*s_:.0f},{-70*s_:.0f} l{9*s_:.0f},{2*s_:.0f}'
         f' l{5*s_:.0f},{68*s_:.0f} Z" fill="url(#derev)" {o(3)}/>')
    s += ogon(x - 2 * s_, y - 74 * s_, t, .34 * s_, ph, 3)
    s += teplo(x, y - 70 * s_, 150 * s_, 130 * s_, .5)
    return s


def podkova(x, y, s_=1.0, t=0.0, col="url(#zhel)"):
    """Подкова-оберег над дверью: железо, четыре гвоздя, слабый отблеск."""
    r = 44 * s_
    s = (f'<path d="M{x-r:.0f},{y+r*.5:.0f} A{r:.0f},{r:.0f} 0 1 1 {x+r:.0f},{y+r*.5:.0f}"'
         f' fill="none" stroke="{col}" stroke-width="{20*s_:.0f}" stroke-linecap="round"/>')
    s += (f'<path d="M{x-r:.0f},{y+r*.5:.0f} A{r:.0f},{r:.0f} 0 1 1 {x+r:.0f},{y+r*.5:.0f}"'
          f' fill="none" {o(4)}/>')
    for i in range(4):
        a = math.radians(210 + i * 40)
        s += (f'<circle cx="{x+r*.98*math.cos(a):.0f}" cy="{y+r*.5-r*.98*math.sin(a)*-1:.0f}"'
              f' r="{3.4*s_:.1f}" fill="{K}"/>')
    bl = .3 + .25 * (0.5 + 0.5 * A.w(t, 3.6))
    s += (f'<circle cx="{x-r*.5:.0f}" cy="{y-r*.3:.0f}" r="{6*s_:.0f}" fill="#eaf4ff"'
          f' opacity="{bl:.2f}"/>')
    return s


def grozd_ryabiny(x, y, t, s_=1.0, n=14, seed=4, ph=.0):
    """Гроздь рябины: ягоды качаются кистью, пара ягод тёмная, иней искрой."""
    rnd = random.Random(seed)
    sway = 3.0 * A.w(t, 2.6, ph)
    s = f'<g transform="translate({sway:.1f},0)">'
    s += (f'<path d="M{x:.0f},{y-70*s_:.0f} q{6*s_:.0f},{34*s_:.0f} {2*s_:.0f},{54*s_:.0f}"'
          f' fill="none" stroke="{ZEL}" stroke-width="{5*s_:.0f}"/>')
    for i in range(n):
        a = rnd.uniform(0, 6.28)
        rr = rnd.uniform(.2, 1.0) * 46 * s_
        cx, cy = x + math.cos(a) * rr, y + math.sin(a) * rr * .8
        col = "#8e2a1c" if i % 6 == 0 else KRAS
        s += (f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="{(8.5+rnd.random()*3)*s_:.1f}"'
              f' fill="{col}" {o(2)}/>')
        s += (f'<circle cx="{cx-3*s_:.0f}" cy="{cy-3*s_:.0f}" r="{2.4*s_:.1f}"'
              f' fill="#ffd0b0" opacity=".55"/>')
    return s + '</g>'


def tusklaya_lampochka(x, y, t, s_=1.0, abazhur=True):
    """Современная лампочка под потолком: мигает на вводе, тёплое пятно."""
    mig = 1.0 if ((t * 1.7) % 1.0) > .06 else .55
    s = (f'<line x1="{x:.0f}" y1="{y-150*s_:.0f}" x2="{x:.0f}" y2="{y-34*s_:.0f}"'
         f' stroke="#30343a" stroke-width="{5*s_:.0f}"/>')
    if abazhur:
        s += (f'<path d="M{x-62*s_:.0f},{y:.0f} L{x-30*s_:.0f},{y-44*s_:.0f}'
              f' L{x+30*s_:.0f},{y-44*s_:.0f} L{x+62*s_:.0f},{y:.0f} Z"'
              f' fill="url(#krem)" {o(5)}/>')
    s += (f'<circle cx="{x:.0f}" cy="{y+14*s_:.0f}" r="{17*s_:.0f}" fill="{SVET}"'
          f' opacity="{mig:.2f}"/>')
    s += teplo(x, y + 30 * s_, 400 * s_, 330 * s_, .46 * mig)
    return s


def para_izo_rta(x, y, t, ph=0.0, s_=1.0, op=.5):
    """Пар изо рта: три облачка рождаются и тают. Без него холод не читается."""
    s = ""
    for i in range(3):
        k = ((t * .5 + ph + i * .33) % 1.0)
        r = (14 + 44 * k) * s_
        s += (f'<ellipse cx="{x + 48*k*s_:.0f}" cy="{y - 26*k*s_:.0f}"'
              f' rx="{r:.0f}" ry="{r*.64:.0f}" fill="#eaf4ff"'
              f' opacity="{op*(1-k)*(1-k):.2f}"/>')
    return s


def kirpich_ustya(x, y, w_, h_, t, zharko=True):
    """Кирпичная ОБВЯЗКА устья печи: кладка идёт рамкой ВОКРУГ проёма, а сам
    проём остаётся пустым — туда ложится нарисованный огонь и настоящий кадр.
    Прежняя сплошная кладка закрашивала проём целиком (поймано 14.11)."""
    p_ = 44
    s = kladka(x - p_, y - p_, w_ + 2 * p_, p_ + 8, 54, "url(#pech)")          # верх
    s += kladka(x - p_, y + h_ - 8, w_ + 2 * p_, p_ + 36, 54, "url(#pech)")    # низ
    s += kladka(x - p_, y, p_ + 6, h_, 54, "url(#pech)")                        # слева
    s += kladka(x + w_ - 6, y, p_ + 6, h_, 54, "url(#pech)")                    # справа
    s += (f'<rect x="{x-p_:.0f}" y="{y-p_:.0f}" width="{w_+2*p_:.0f}"'
          f' height="{h_+2*p_+28:.0f}" fill="none" {o(6)}/>')
    if zharko:
        s += teplo(x + w_ / 2, y + h_ * .72, w_ * .95, h_ * .9, .50)
        s += (f'<ellipse cx="{x+w_/2:.0f}" cy="{y+h_:.0f}" rx="{w_*.6:.0f}"'
              f' ry="{26+8*A.w(t,1.7):.0f}" fill="{ORA}" opacity=".28"/>')
    return s


def sumerki_fon(t, pozdnie=True):
    """Фон ноябрьских сумерек: небо, дальняя мокрая земля, тонкий туман."""
    s = f'<rect width="{W}" height="{H}" fill="url(#{"nsumer" if pozdnie else "nden"})"/>'
    # ВНИМАНИЕ: nebo и oblaka в baza.py уже обёрнуты в свой слой (_sloy),
    # второй SL поверх запрещён — поймано на части 1.
    s += nebo("sumer" if pozdnie else "den", t, pozdnie, 11)
    s += oblaka(t, 150, 4, 5, .34, "#cdd7e4", 13.0)
    return s


# ═══════════════════════════════════════════════════════════════════
# ОБЩИЕ КИРПИЧИКИ РОЛИКА «18 ноября — День Ионы» (перенесены из chast1
# 15.11, чтобы порции 2 и 3 рисовали ТЕМИ ЖЕ руками и вещами, а не
# изобретали заново — на первой порции именно самодельные руки дали
# бруски сквозь тело и лицо).
#   _ruka / _ruka_ekr / _ruka_so_sgibom — рука ТОЛЬКО от плеча, угол в
#     наружном коридоре −58°…+88°, с оплечьем: в голову и грудь своей
#     фигуры не попадает ни при каких числах;
#   _venik_v_ruke — веник держится ЗА ЧЕРЕНОК, а не висит рядом;
#   остальное — обжитые мелочи двора, улицы, горницы и города.
# ═══════════════════════════════════════════════════════════════════

def _zemlya(y0, h_=480, col="#4a4038", op=1.0):
    """Широкая полоса земли/пола/воды внизу кадра: крупный предмет (R-0047)
    и опора под ногами одним движением."""
    return f'<rect x="0" y="{y0:.0f}" width="{W}" height="{h_:.0f}" fill="{col}" opacity="{op:.2f}"/>'


def _plecho(x, y, h_, storona):
    """Точка плеча figura(x,y,h_,...) для rukav(): -1 левое плечо, 1 правое."""
    w_ = h_ * .42
    return x + storona * w_ * .40, y - h_ * .66 + h_ * .02


def _trava(rnd, n, y0, y1, col=ZEL2):
    s = ""
    for _ in range(n):
        gx = rnd.uniform(30, W - 30); gy = rnd.uniform(y0, y1)
        h2 = rnd.uniform(26, 56)
        s += (f'<path d="M{gx:.0f},{gy:.0f} q{rnd.uniform(-14,14):.0f},{-h2:.0f}'
              f' {rnd.uniform(-8,8):.0f},{-h2*1.3:.0f}" fill="none" stroke="{col}"'
              f' stroke-width="5" opacity=".6"/>')
    return s


def _zabor_dosok(x, y, w_, h_, seed=5, step=58, col="url(#derev)"):
    """Дощатый забор: каждая доска отдельная, с зазором и прожилиной, две
    поперечины. Забор держит средний план там, где иначе пустое небо."""
    rnd = random.Random(seed)
    s = ""
    n = max(3, int(w_ // step))
    for i in range(n):
        bx = x + i * step
        dh = h_ * rnd.uniform(.90, 1.0)
        ty = y + (h_ - dh)
        s += (f'<rect x="{bx:.0f}" y="{ty:.0f}" width="{step-14:.0f}" height="{dh:.0f}"'
              f' rx="6" fill="{col}" {o(4)}/>'
              f'<line x1="{bx+9:.0f}" y1="{ty+22:.0f}" x2="{bx+9:.0f}" y2="{y+h_-20:.0f}"'
              f' stroke="#2c1f14" stroke-width="3" opacity=".45"/>')
    for k in (.28, .76):
        s += (f'<rect x="{x-10:.0f}" y="{y+h_*k:.0f}" width="{w_+20:.0f}" height="18"'
              f' rx="6" fill="#3f2d1c" {o(4)}/>')
    return s


def _polenica(x, y, w_, h_, seed=7, r=27):
    """Поленница под навесом: колотые поленья торцами, разного калибра и
    тона, в рядах вперевязку; у части виден клин раскола."""
    rnd = random.Random(seed)
    tona = ["url(#derev)", "#6b4e30", "#7b5c38", "#5a4228", "#8a6a44"]
    s = (f'<rect x="{x-10:.0f}" y="{y+h_:.0f}" width="{w_+20:.0f}" height="20" rx="6"'
         f' fill="#33261a" {o(4)}/>')
    ry = max(1, int(h_ // (r * 1.78)))
    rx = max(1, int(w_ // (r * 1.86)))
    for j in range(ry):
        for i in range(rx):
            rr = r * rnd.uniform(.76, 1.12)
            cx = x + r + i * r * 1.86 + (r * .52 if j % 2 else 0) + rnd.uniform(-4, 4)
            cy = y + h_ - r - j * r * 1.78 + rnd.uniform(-5, 5)
            if cx > x + w_ - r * .4:
                continue
            s += (f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="{rr:.0f}"'
                  f' fill="{tona[rnd.randrange(len(tona))]}" {o(4)}/>')
            if rnd.random() < .45:
                s += (f'<path d="M{cx-rr*.72:.0f},{cy-rr*.30:.0f}'
                      f' Q{cx:.0f},{cy+rr*.16:.0f} {cx+rr*.66:.0f},{cy-rr*.40:.0f}"'
                      f' fill="none" stroke="#5e442a" stroke-width="4" opacity=".7"/>')
            else:
                s += (f'<path d="M{cx-rr*.86:.0f},{cy-rr*.20:.0f}'
                      f' L{cx+rr*.20:.0f},{cy+rr*.14:.0f}'
                      f' L{cx+rr*.10:.0f},{cy-rr*.80:.0f} Z" fill="#8f7048"'
                      f' opacity=".55"/>')
            if rnd.random() < .28:
                s += (f'<line x1="{cx:.0f}" y1="{cy-rr*.76:.0f}" x2="{cx+rr*.18:.0f}"'
                      f' y2="{cy+rr*.76:.0f}" stroke="#432f1c" stroke-width="4"'
                      f' opacity=".65"/>')
    s += (f'<rect x="{x-24:.0f}" y="{y-26:.0f}" width="{w_+48:.0f}" height="26" rx="8"'
          f' fill="#4a3826" {o(5)}/>')
    return s


def _dvorovaya_utvar(x, y, w_, t, seed=9, nabor=None):
    """Дворовая утварь в рост полметра: кадка, вёдра, корзина, мешок, короб.
    Ставится НА землю у стены — та самая «сопутствующая вещь»."""
    rnd = random.Random(seed)
    veschi = nabor or ["kadka", "vedro", "korzina", "meshok", "korob", "vedro"]
    s = ""
    step = w_ / max(1, len(veschi))
    for i, v in enumerate(veschi):
        vx = x + step * (i + .5) + rnd.uniform(-14, 14)
        k = rnd.uniform(.86, 1.12)
        if v == "kadka":
            h2, w2 = 150 * k, 124 * k
            s += (f'<path d="M{vx-w2/2:.0f},{y-h2:.0f} L{vx+w2/2:.0f},{y-h2:.0f}'
                  f' L{vx+w2*.42:.0f},{y:.0f} L{vx-w2*.42:.0f},{y:.0f} Z"'
                  f' fill="url(#derev)" {o(5)}/>'
                  f'<rect x="{vx-w2/2-4:.0f}" y="{y-h2*.86:.0f}" width="{w2+8:.0f}" height="14"'
                  f' rx="5" fill="{ZHELEZ}" {o(3)}/>'
                  f'<rect x="{vx-w2*.46:.0f}" y="{y-h2*.26:.0f}" width="{w2*.92:.0f}"'
                  f' height="14" rx="5" fill="{ZHELEZ}" {o(3)}/>'
                  f'<ellipse cx="{vx:.0f}" cy="{y-h2:.0f}" rx="{w2/2:.0f}" ry="{w2*.15:.0f}"'
                  f' fill="#2a1d12" {o(4)}/>')
        elif v == "vedro":
            h2, w2 = 112 * k, 96 * k
            s += (f'<path d="M{vx-w2/2:.0f},{y-h2:.0f} L{vx+w2/2:.0f},{y-h2:.0f}'
                  f' L{vx+w2*.36:.0f},{y:.0f} L{vx-w2*.36:.0f},{y:.0f} Z"'
                  f' fill="url(#zhel)" {o(5)}/>'
                  f'<path d="M{vx-w2/2:.0f},{y-h2:.0f} Q{vx:.0f},{y-h2-w2*.6:.0f}'
                  f' {vx+w2/2:.0f},{y-h2:.0f}" fill="none" stroke="{ZHELEZ}" stroke-width="7"/>'
                  f'<ellipse cx="{vx:.0f}" cy="{y-h2:.0f}" rx="{w2/2:.0f}" ry="{w2*.16:.0f}"'
                  f' fill="#2f3337" {o(4)}/>')
        elif v == "korzina":
            h2, w2 = 108 * k, 136 * k
            s += (f'<path d="M{vx-w2/2:.0f},{y-h2:.0f} L{vx+w2/2:.0f},{y-h2:.0f}'
                  f' L{vx+w2*.34:.0f},{y:.0f} L{vx-w2*.34:.0f},{y:.0f} Z"'
                  f' fill="url(#solom)" {o(5)}/>')
            for q in range(3):
                yy = y - h2 * .74 + q * h2 * .26
                s += (f'<path d="M{vx-w2*.44:.0f},{yy:.0f} Q{vx:.0f},{yy+16:.0f}'
                      f' {vx+w2*.44:.0f},{yy:.0f}" fill="none" stroke="#8a6a3c"'
                      f' stroke-width="5" opacity=".8"/>')
            s += (f'<path d="M{vx-w2*.4:.0f},{y-h2:.0f} Q{vx:.0f},{y-h2-w2*.5:.0f}'
                  f' {vx+w2*.4:.0f},{y-h2:.0f}" fill="none" stroke="#8a6a3c" stroke-width="8"/>')
        elif v == "meshok":
            h2, w2 = 134 * k, 108 * k
            s += (f'<path d="M{vx-w2/2:.0f},{y:.0f} Q{vx-w2*.56:.0f},{y-h2*.62:.0f}'
                  f' {vx-w2*.2:.0f},{y-h2:.0f} Q{vx:.0f},{y-h2-16:.0f}'
                  f' {vx+w2*.2:.0f},{y-h2:.0f} Q{vx+w2*.56:.0f},{y-h2*.62:.0f}'
                  f' {vx+w2/2:.0f},{y:.0f} Z" fill="url(#krem)" {o(5)}/>'
                  f'<path d="M{vx-w2*.2:.0f},{y-h2:.0f} Q{vx:.0f},{y-h2-18:.0f}'
                  f' {vx+w2*.2:.0f},{y-h2:.0f}" fill="none" stroke="#8a7a58" stroke-width="6"/>')
        elif v == "korob":
            h2, w2 = 102 * k, 150 * k
            s += (f'<rect x="{vx-w2/2:.0f}" y="{y-h2:.0f}" width="{w2:.0f}" height="{h2:.0f}"'
                  f' rx="8" fill="url(#derev)" {o(5)}/>'
                  f'<rect x="{vx-w2/2:.0f}" y="{y-h2:.0f}" width="{w2:.0f}" height="20" rx="6"'
                  f' fill="#5b4328" {o(4)}/>'
                  f'<line x1="{vx-w2*.3:.0f}" y1="{y-h2+22:.0f}" x2="{vx-w2*.3:.0f}"'
                  f' y2="{y-6:.0f}" stroke="#3a2a1a" stroke-width="4" opacity=".6"/>')
        else:
            h2, w2 = 96 * k, 118 * k
            s += (f'<ellipse cx="{vx:.0f}" cy="{y-h2*.5:.0f}" rx="{w2*.46:.0f}"'
                  f' ry="{h2*.5:.0f}" fill="url(#glina)" {o(5)}/>')
        s += ten(vx, y + 6, w2 * .56, 13, .45)
    return s


def _polka_s_utvaryu(x, y, w_, t, seed=11, n=5):
    """Полка на стене и посуда НА ней: горшки, крынки, миски, короб, связка
    трав. Мелочь кладётся на предмет, а не рассыпается по полу."""
    rnd = random.Random(seed)
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="20" rx="6"'
         f' fill="url(#derev)" {o(5)}/>'
         f'<rect x="{x+22:.0f}" y="{y+20:.0f}" width="22" height="34" fill="#4a3522" {o(4)}/>'
         f'<rect x="{x+w_-44:.0f}" y="{y+20:.0f}" width="22" height="34" fill="#4a3522" {o(4)}/>')
    step = (w_ - 60) / max(1, n)
    for i in range(n):
        px = x + 40 + step * i + step * .5
        vid = rnd.randrange(4)
        h2 = rnd.uniform(78, 124)
        if vid == 0:
            s += (f'<path d="M{px-34:.0f},{y:.0f} Q{px-48:.0f},{y-h2*.5:.0f}'
                  f' {px-30:.0f},{y-h2:.0f} L{px+30:.0f},{y-h2:.0f}'
                  f' Q{px+48:.0f},{y-h2*.5:.0f} {px+34:.0f},{y:.0f} Z"'
                  f' fill="url(#glina)" {o(5)}/>'
                  f'<ellipse cx="{px:.0f}" cy="{y-h2:.0f}" rx="34" ry="11" fill="#6d4e32" {o(4)}/>')
        elif vid == 1:
            s += (f'<path d="M{px-30:.0f},{y:.0f} L{px-24:.0f},{y-h2*.62:.0f}'
                  f' Q{px:.0f},{y-h2*.86:.0f} {px+24:.0f},{y-h2*.62:.0f}'
                  f' L{px+30:.0f},{y:.0f} Z" fill="url(#krem)" {o(5)}/>'
                  f'<rect x="{px-22:.0f}" y="{y-h2:.0f}" width="44" height="18" rx="7"'
                  f' fill="#9a8a68" {o(4)}/>')
        elif vid == 2:
            s += (f'<path d="M{px-44:.0f},{y-h2*.42:.0f} Q{px:.0f},{y+14:.0f}'
                  f' {px+44:.0f},{y-h2*.42:.0f} L{px+36:.0f},{y-h2*.6:.0f}'
                  f' Q{px:.0f},{y-h2*.2:.0f} {px-36:.0f},{y-h2*.6:.0f} Z"'
                  f' fill="url(#zhel)" {o(5)}/>')
        else:
            s += (f'<rect x="{px-38:.0f}" y="{y-h2:.0f}" width="76" height="{h2:.0f}" rx="7"'
                  f' fill="url(#derev)" {o(5)}/>'
                  f'<line x1="{px-38:.0f}" y1="{y-h2*.5:.0f}" x2="{px+38:.0f}"'
                  f' y2="{y-h2*.5:.0f}" stroke="#3a2a1a" stroke-width="4" opacity=".6"/>')
    kach = 3.0 * A.w(t, 3.4, .2)
    tx = x + w_ - 36
    s += (f'<g transform="rotate({kach:.1f} {tx:.0f} {y:.0f})">'
          f'<path d="M{tx-10:.0f},{y:.0f} L{tx+2:.0f},{y+74:.0f} L{tx+18:.0f},{y:.0f} Z"'
          f' fill="#6f7a44" {o(4)}/>'
          f'<line x1="{tx+0:.0f}" y1="{y+26:.0f}" x2="{tx-20:.0f}" y2="{y+48:.0f}"'
          f' stroke="#6f7a44" stroke-width="5"/>'
          f'<line x1="{tx+8:.0f}" y1="{y+46:.0f}" x2="{tx+28:.0f}" y2="{y+66:.0f}"'
          f' stroke="#6f7a44" stroke-width="5"/></g>')
    return s


def _derevnya_ryad(base, t, seed=7, mesta=((300, 440), (880, 380), (1560, 500))):
    """Ряд изб разной величины по дальнему плану — улица, а не пустое поле."""
    s = ""
    for i, (mx, mw) in enumerate(mesta):
        s += izba_snaruzhi(mx, base + (i % 2) * 16, mw, t, svet=True, truba=True,
                           seed=seed + i * 3)
    return s


def _bulyzhnik(y0, y1, seed=13, n=90, col="#5a5248"):
    """Булыжная мостовая: камни рядами, ближе к низу крупнее."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        p = rnd.random()
        cy = y0 + (y1 - y0) * (p ** .7)
        r = 20 + 44 * ((cy - y0) / max(1, y1 - y0))
        cx = rnd.uniform(-30, W + 30)
        tn = rnd.uniform(-.08, .08)
        s += (f'<ellipse cx="{cx:.0f}" cy="{cy:.0f}" rx="{r*1.22:.0f}" ry="{r*.72:.0f}"'
              f' fill="{col}" opacity="{.85+tn:.2f}" {o(3)}/>'
              f'<ellipse cx="{cx-r*.22:.0f}" cy="{cy-r*.2:.0f}" rx="{r*.56:.0f}"'
              f' ry="{r*.3:.0f}" fill="#6e665b" opacity=".45"/>')
    return s


def _listya(seed, n, y0, y1, cols=("#9a5a28", "#b4762f", "#7d4a24", "#c08a3a")):
    """Палая листва поздней осени — лежит НА земле, пятном не висит."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        lx, ly = rnd.uniform(0, W), rnd.uniform(y0, y1)
        r = rnd.uniform(17, 31)
        ug = rnd.uniform(0, 360)
        s += (f'<g transform="rotate({ug:.0f} {lx:.0f} {ly:.0f})">'
              f'<path d="M{lx-r:.0f},{ly:.0f} Q{lx:.0f},{ly-r*.86:.0f} {lx+r:.0f},{ly:.0f}'
              f' Q{lx:.0f},{ly+r*.86:.0f} {lx-r:.0f},{ly:.0f} Z"'
              f' fill="{cols[i%len(cols)]}" opacity=".9" {o(2)}/>'
              f'<line x1="{lx-r:.0f}" y1="{ly:.0f}" x2="{lx+r:.0f}" y2="{ly:.0f}"'
              f' stroke="#6a4120" stroke-width="2" opacity=".7"/></g>')
    return s


def _vetka_pered(x, y, dl, ug, t, seed=3, col="#241c16", vetok=6):
    """Ветка у самого объектива: держит ближний план и качается целиком."""
    rnd = random.Random(seed)
    kach = 1.6 * A.w(t, 4.2, .3)
    r = math.radians(ug)
    x2, y2 = x + dl * math.cos(r), y + dl * math.sin(r)
    s = (f'<g transform="rotate({kach:.2f} {x:.0f} {y:.0f})">'
         f'<path d="M{x:.0f},{y:.0f} Q{(x+x2)/2:.0f},{(y+y2)/2-40:.0f} {x2:.0f},{y2:.0f}"'
         f' fill="none" stroke="{col}" stroke-width="22" stroke-linecap="round"/>')
    for i in range(vetok):
        p = .18 + .76 * i / max(1, vetok - 1)
        bx = x + (x2 - x) * p
        by = y + (y2 - y) * p - 40 * math.sin(math.pi * p)
        dl2 = rnd.uniform(70, 140)
        a2 = r + rnd.uniform(-1.1, 1.1)
        s += (f'<line x1="{bx:.0f}" y1="{by:.0f}" x2="{bx+dl2*math.cos(a2):.0f}"'
              f' y2="{by+dl2*math.sin(a2):.0f}" stroke="{col}" stroke-width="10"'
              f' stroke-linecap="round"/>')
    s += "</g>"
    return s


def _stolb_pered(x, w_, col="#1d1611", ot=0, do=H):
    """Столб/косяк у самого края кадра — ближний план, ради объёма."""
    return (f'<rect x="{x:.0f}" y="{ot:.0f}" width="{w_:.0f}" height="{do-ot:.0f}"'
            f' fill="{col}" {o(6)}/>'
            f'<rect x="{x+w_*.18:.0f}" y="{ot:.0f}" width="{w_*.2:.0f}" height="{do-ot:.0f}"'
            f' fill="#2e2219" opacity=".7"/>')


def _kryl_co(x, y, w_, h_, t, stup=3, peril=True, naves=False):
    """Крыльцо: настил, ступени, столбы, перила с балясинами, при нужде навес."""
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="34" rx="6"'
         f' fill="url(#derev)" {o(5)}/>'
         f'<rect x="{x+10:.0f}" y="{y+34:.0f}" width="{w_-20:.0f}" height="{h_:.0f}"'
         f' fill="#3a2b1c" {o(4)}/>')
    for i in range(stup):
        sw = w_ * (.62 - .1 * i)
        sx = x + w_ * .5 - sw * .5
        s += (f'<rect x="{sx:.0f}" y="{y+34+h_*(i+1)/(stup+1):.0f}" width="{sw:.0f}"'
              f' height="26" rx="5" fill="url(#derev)" {o(4)}/>')
    if peril:
        for px in (x + 14, x + w_ - 40):
            s += (f'<rect x="{px:.0f}" y="{y-130:.0f}" width="26" height="140" rx="6"'
                  f' fill="#4e3a24" {o(4)}/>')
        s += (f'<rect x="{x+8:.0f}" y="{y-134:.0f}" width="{w_-14:.0f}" height="20" rx="7"'
              f' fill="#5b4428" {o(5)}/>')
        for i in range(5):
            bx = x + 54 + i * (w_ - 118) / 4.0
            s += (f'<path d="M{bx:.0f},{y-114:.0f} Q{bx+16:.0f},{y-92:.0f}'
                  f' {bx:.0f},{y-70:.0f} Q{bx-16:.0f},{y-48:.0f} {bx:.0f},{y-24:.0f}'
                  f' L{bx+16:.0f},{y-24:.0f} Q{bx:.0f},{y-48:.0f} {bx+16:.0f},{y-70:.0f}'
                  f' Q{bx+32:.0f},{y-92:.0f} {bx+16:.0f},{y-114:.0f} Z"'
                  f' fill="#6a5030" {o(3)}/>')
    if naves:
        s += (f'<path d="M{x-34:.0f},{y-250:.0f} L{x+w_/2:.0f},{y-320:.0f}'
              f' L{x+w_+34:.0f},{y-250:.0f} Z" fill="#4a3a28" {o(5)}/>'
              f'<rect x="{x-40:.0f}" y="{y-256:.0f}" width="{w_+80:.0f}" height="22" rx="7"'
              f' fill="#5c4830" {o(4)}/>')
    return s


def _koleya(y, seed=21, n=2):
    """След тележного колеса на мёрзлой земле: две колеи и ледок в них."""
    s = ""
    for i in range(n):
        yy = y + i * 62
        s += (f'<path d="M-40,{yy:.0f} Q480,{yy-30-i*8:.0f} 1000,{yy-10:.0f}'
              f' Q1500,{yy+6:.0f} 1960,{yy-14:.0f}" fill="none" stroke="#3a3028"'
              f' stroke-width="{26-i*5}" opacity=".8"/>'
              f'<path d="M-40,{yy-8:.0f} Q480,{yy-38-i*8:.0f} 1000,{yy-18:.0f}'
              f' Q1500,{yy-2:.0f} 1960,{yy-22:.0f}" fill="none" stroke="#7d8f9c"'
              f' stroke-width="5" opacity=".45"/>')
    return s


def _stena_gornicy(t, seed=5, venec=True, pol_y=760, bok=True):
    """Задник горницы: бревенчатая стена во весь кадр, матица, венцы по углам,
    половицы и плинтус. Это фон — плотность на нём набирается предметами."""
    s = brevna(0, 0, W, pol_y + 40, 96)
    if venec:
        s += (f'<rect x="0" y="{pol_y-10:.0f}" width="{W}" height="26" fill="#3b2a1a"'
              f' opacity=".9"/>'
              f'<rect x="0" y="86" width="{W}" height="28" fill="#4a3522" opacity=".55"/>')
    s += polovicy(pol_y + 30)
    if bok:
        s += (f'<rect x="0" y="0" width="86" height="{pol_y+40:.0f}" fill="#241a11"'
              f' opacity=".55"/>'
              f'<rect x="{W-86}" y="0" width="86" height="{pol_y+40:.0f}" fill="#241a11"'
              f' opacity=".55"/>')
    return s


def _zemlya_faktura(y0, y1, seed=3, n=16, kom="#3f3326"):
    """Мёрзлая земля вблизи: комья, камни, проплешины, лужицы с ледком —
    чтобы полоса земли не читалась крашеной доской."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        gx, gy = rnd.uniform(-40, W + 40), rnd.uniform(y0, y1)
        rx_ = rnd.uniform(70, 190)
        s += (f'<ellipse cx="{gx:.0f}" cy="{gy:.0f}" rx="{rx_:.0f}" ry="{rx_*.26:.0f}"'
              f' fill="{kom}" opacity="{rnd.uniform(.30,.5):.2f}"/>')
        if rnd.random() < .4:
            s += (f'<ellipse cx="{gx+rnd.uniform(-40,40):.0f}" cy="{gy+18:.0f}"'
                  f' rx="{rx_*.44:.0f}" ry="{rx_*.13:.0f}" fill="#6d7f8c"'
                  f' opacity=".45"/>')
        if rnd.random() < .34:
            r2 = rnd.uniform(16, 34)
            s += (f'<ellipse cx="{gx+rnd.uniform(-70,70):.0f}" cy="{gy-6:.0f}"'
                  f' rx="{r2:.0f}" ry="{r2*.72:.0f}" fill="#6a6256" {o(2)}/>')
    return s


def _venik(vx, vy, h2, t, col, tryap, birka=False, rastr=.0, ph=.0, s_=1.0,
           seed=None):
    """Веник, который видно со стоп-кадра (R-0047): прутья веером, перевязь,
    ручка, обмахрённый низ. Качается целиком."""
    rr = random.Random(seed if seed is not None else int(vx))
    kach = 3.4 * A.w(t, 2.2, ph)
    g = f'<g transform="rotate({kach:.1f} {vx:.0f} {vy:.0f})">'
    n = 23
    for i in range(n):
        p = (i / (n - 1.0)) - .5
        raz = (1.0 + rastr * rr.uniform(0, 1.6))
        ex = vx + p * 180 * s_ * raz
        ey = vy - h2 + rr.uniform(-30, 20) * raz
        g += (f'<path d="M{vx+p*34*s_:.0f},{vy-h2*.40:.0f}'
              f' Q{vx+p*118*s_:.0f},{vy-h2*.76:.0f} {ex:.0f},{ey:.0f}"'
              f' fill="none" stroke="{col}" stroke-width="{9*s_:.0f}"'
              f' stroke-linecap="round" opacity=".92"/>')
    g += (f'<rect x="{vx-28*s_:.0f}" y="{vy-h2*.42:.0f}" width="{56*s_:.0f}"'
          f' height="{h2*.46:.0f}" rx="18" fill="url(#derev)" {o(5)}/>'
          f'<rect x="{vx-44*s_:.0f}" y="{vy-h2*.50:.0f}" width="{88*s_:.0f}"'
          f' height="{34*s_:.0f}" rx="12" fill="{tryap}" {o(4)}/>'
          f'<rect x="{vx-40*s_:.0f}" y="{vy-h2*.28:.0f}" width="{80*s_:.0f}"'
          f' height="{24*s_:.0f}" rx="10" fill="#8a6a3c" {o(3)}/>')
    if tryap == "#b8352c":
        tr = 8 * A.w(t, 1.7, ph + .5)
        g += (f'<path d="M{vx+40*s_:.0f},{vy-h2*.48:.0f}'
              f' Q{vx+86*s_+tr:.0f},{vy-h2*.42:.0f} {vx+70*s_:.0f},{vy-h2*.30:.0f} Z"'
              f' fill="#b8352c" {o(3)}/>')
    if birka:
        bk = 4 * A.w(t, 1.8, ph + .3)
        g += (f'<g transform="rotate({bk:.1f} {vx+34*s_:.0f} {vy-h2*.28:.0f})">'
              f'<line x1="{vx+34*s_:.0f}" y1="{vy-h2*.28:.0f}" x2="{vx+52*s_:.0f}"'
              f' y2="{vy-h2*.14:.0f}" stroke="#cbbb98" stroke-width="4"/>'
              f'<rect x="{vx+34*s_:.0f}" y="{vy-h2*.14:.0f}" width="{52*s_:.0f}"'
              f' height="{68*s_:.0f}" rx="8" fill="#efe4c8" {o(4)}/>'
              f'<path d="M{vx+44*s_:.0f},{vy-h2*.14+30*s_:.0f}'
              f' Q{vx+58*s_:.0f},{vy-h2*.14+20*s_:.0f}'
              f' {vx+74*s_:.0f},{vy-h2*.14+30*s_:.0f}" fill="none" stroke="#9a8a68"'
              f' stroke-width="4"/></g>')
    g += "</g>"
    return g


def _venik_v_ruke(ex, ey, h2, t, col="#4b3f28", tryap="#5a4a2e", ug=96.0, s_=.9,
                  seed=None, rastr=.25, ph=.0):
    """ВЕНИК В РУКЕ ДЕРЖИТСЯ ЗА ЧЕРЕНОК. Осмотр 15.11: «веник висит в воздухе
    без руки» и «черенок веника лежит поперёк лица» — сцены ставили веник
    смещённым на 180-330 px ниже кисти, то есть ни одним концом её не
    касались, да ещё прутьями к хозяйке.

    `_venik()` рисует прутья СВЕРХУ (от vy-h2 до vy-h2*.42), а черенок снизу,
    и его нижний конец приходится ровно на vy. Значит кисть — это vy, и
    остаётся только повернуть: `ug` — куда смотрят ПРУТЬЯ в экранных
    градусах (96 — вниз и чуть вперёд, -40 — вверх-вправо, 196 — влево).
    Прутья всегда уводятся ОТ фигуры, а не на неё.
    """
    return (f'<g transform="rotate({ug + 90:.1f} {ex:.0f} {ey:.0f})">'
            + _venik(ex, ey, h2, t, col, tryap, False, rastr, ph, s_, seed)
            + "</g>")


def _gorodskoy_hlam(x, y, w_, t, seed=7, nabor=None):
    """Двор у подъезда: столбик-ограждение, ящик, картонная коробка, пакет,
    куст в кадке, велосипед у стены. Городская «сопутствующая вещь»."""
    rnd = random.Random(seed)
    veschi = nabor or ["stolbik", "yaschik", "korobka", "kust", "velik", "stolbik"]
    s = ""
    step = w_ / max(1, len(veschi))
    for i, v in enumerate(veschi):
        vx = x + step * (i + .5) + rnd.uniform(-12, 12)
        if v == "stolbik":
            s += (f'<rect x="{vx-20:.0f}" y="{y-180:.0f}" width="40" height="180" rx="14"'
                  f' fill="#4a5055" {o(5)}/>'
                  f'<rect x="{vx-26:.0f}" y="{y-192:.0f}" width="52" height="20" rx="9"'
                  f' fill="#6a7278" {o(3)}/>'
                  f'<rect x="{vx-20:.0f}" y="{y-120:.0f}" width="40" height="18"'
                  f' fill="#c0c6ca" opacity=".8"/>')
        elif v == "yaschik":
            s += (f'<rect x="{vx-86:.0f}" y="{y-140:.0f}" width="172" height="140"'
                  f' rx="8" fill="#6b5a3c" {o(5)}/>')
            for k in range(3):
                s += (f'<rect x="{vx-80:.0f}" y="{y-132+k*46:.0f}" width="160"'
                      f' height="30" rx="5" fill="#7d6a44" {o(3)}/>')
        elif v == "korobka":
            s += (f'<rect x="{vx-78:.0f}" y="{y-128:.0f}" width="156" height="128"'
                  f' rx="6" fill="#a98a5e" {o(5)}/>'
                  f'<path d="M{vx-78:.0f},{y-128:.0f} L{vx:.0f},{y-156:.0f}'
                  f' L{vx+78:.0f},{y-128:.0f}" fill="none" stroke="#8a6c44"'
                  f' stroke-width="7"/>'
                  f'<line x1="{vx:.0f}" y1="{y-128:.0f}" x2="{vx:.0f}" y2="{y-6:.0f}"'
                  f' stroke="#8a6c44" stroke-width="5" opacity=".8"/>')
        elif v == "kust":
            s += (f'<path d="M{vx-70:.0f},{y:.0f} L{vx-56:.0f},{y-110:.0f}'
                  f' L{vx+56:.0f},{y-110:.0f} L{vx+70:.0f},{y:.0f} Z" fill="#5a5c60"'
                  f' {o(5)}/>')
            for k in range(7):
                a = math.radians(-160 + k * 26)
                dl = 120 + (k % 3) * 34
                kach = 2.0 * A.w(t, 3.2 + k * .2, k * .3)
                s += (f'<line x1="{vx:.0f}" y1="{y-110:.0f}"'
                      f' x2="{vx+dl*math.cos(a)+kach:.0f}"'
                      f' y2="{y-110+dl*math.sin(a):.0f}" stroke="#4e4436"'
                      f' stroke-width="7" stroke-linecap="round"/>')
        elif v == "velik":
            s += (f'<circle cx="{vx-76:.0f}" cy="{y-70:.0f}" r="70" fill="none"'
                  f' stroke="#2f3338" stroke-width="12"/>'
                  f'<circle cx="{vx+76:.0f}" cy="{y-70:.0f}" r="70" fill="none"'
                  f' stroke="#2f3338" stroke-width="12"/>'
                  f'<path d="M{vx-76:.0f},{y-70:.0f} L{vx-10:.0f},{y-70:.0f}'
                  f' L{vx+20:.0f},{y-170:.0f} L{vx-50:.0f},{y-170:.0f} Z" fill="none"'
                  f' stroke="#8a4a4a" stroke-width="11"/>'
                  f'<path d="M{vx+76:.0f},{y-70:.0f} L{vx+20:.0f},{y-170:.0f}"'
                  f' stroke="#8a4a4a" stroke-width="11" fill="none"/>'
                  f'<path d="M{vx-50:.0f},{y-170:.0f} L{vx-66:.0f},{y-196:.0f}'
                  f' L{vx-26:.0f},{y-196:.0f}" fill="none" stroke="#2f3338"'
                  f' stroke-width="9"/>'
                  f'<rect x="{vx+2:.0f}" y="{y-198:.0f}" width="44" height="18" rx="8"'
                  f' fill="#2f3338" {o(2)}/>')
        else:
            s += (f'<ellipse cx="{vx:.0f}" cy="{y-50:.0f}" rx="60" ry="50"'
                  f' fill="#8a8c90" opacity=".8" {o(3)}/>')
        s += ten(vx, y + 6, 70, 14, .4)
    return s


def _tryumo(x, y, w_, h_, t, seed=3):
    """Старое трюмо: три зеркала в резных рамах, подзеркальник на точёных
    ножках, отражение тёплой лампы в каждом стекле."""
    s = ""
    # подзеркальник
    s += (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="46" rx="10"'
          f' fill="url(#derev)" {o(6)}/>'
          f'<rect x="{x+16:.0f}" y="{y+46:.0f}" width="{w_-32:.0f}" height="26"'
          f' fill="#3a2a1a" opacity=".8"/>')
    for px in (x + 40, x + w_ - 76):
        s += (f'<rect x="{px:.0f}" y="{y+72:.0f}" width="36" height="200" rx="12"'
              f' fill="#4a3522" {o(4)}/>'
              f'<ellipse cx="{px+18:.0f}" cy="{y+136:.0f}" rx="28" ry="18"'
              f' fill="#5e442a" {o(3)}/>')
    s += (f'<rect x="{x+90:.0f}" y="{y+120:.0f}" width="{w_-180:.0f}" height="110"'
          f' rx="8" fill="url(#dosk)" {o(4)}/>'
          f'<rect x="{x+90:.0f}" y="{y+166:.0f}" width="{w_-180:.0f}" height="12"'
          f' fill="#3a2a1a" opacity=".7"/>'
          f'<circle cx="{x+w_*.34:.0f}" cy="{y+196:.0f}" r="14" fill="{ZHELEZ}" {o(2)}/>'
          f'<circle cx="{x+w_*.66:.0f}" cy="{y+196:.0f}" r="14" fill="{ZHELEZ}" {o(2)}/>')
    # три зеркала
    for i, (mx, mw, mh) in enumerate((
            (x + 40, w_ * .26, h_ * .72), (x + w_ * .34, w_ * .32, h_),
            (x + w_ * .70, w_ * .26, h_ * .72))):
        ug = (-9, 0, 9)[i]
        s += (f'<g transform="rotate({ug} {mx+mw/2:.0f} {y:.0f})">'
              f'<path d="M{mx-14:.0f},{y:.0f} L{mx-14:.0f},{y-mh+60:.0f}'
              f' Q{mx+mw/2:.0f},{y-mh-50:.0f} {mx+mw+14:.0f},{y-mh+60:.0f}'
              f' L{mx+mw+14:.0f},{y:.0f} Z" fill="#5b4428" {o(6)}/>'
              f'<path d="M{mx:.0f},{y-8:.0f} L{mx:.0f},{y-mh+66:.0f}'
              f' Q{mx+mw/2:.0f},{y-mh-30:.0f} {mx+mw:.0f},{y-mh+66:.0f}'
              f' L{mx+mw:.0f},{y-8:.0f} Z" fill="#30404a" {o(3)}/>'
              f'<path d="M{mx+12:.0f},{y-20:.0f} L{mx+mw*.46:.0f},{y-mh+40:.0f}'
              f' L{mx+mw*.70:.0f},{y-mh+40:.0f} L{mx+mw*.30:.0f},{y-20:.0f} Z"'
              f' fill="#8fb0c4" opacity=".28"/>'
              f'<ellipse cx="{mx+mw*.5:.0f}" cy="{y-mh*.42:.0f}" rx="{mw*.22:.0f}"'
              f' ry="{mh*.14:.0f}" fill="#ffd98a"'
              f' opacity="{.22+.08*abs(A.w(t,2.4,i*.3)):.2f}"/></g>')
    return s


def _asfalt(y0, y1, seed=3, listvy=26):
    """Городской тротуар: плитка швами, бордюр, лужица, палая листва."""
    rnd = random.Random(seed)
    s = (f'<rect x="0" y="{y0:.0f}" width="{W}" height="{y1-y0:.0f}" fill="#4e4f52"/>'
         f'<rect x="0" y="{y0:.0f}" width="{W}" height="30" fill="#62646a"'
         f' opacity=".85"/>')
    ry = 0
    yy = y0 + 40
    while yy < y1:
        sh = 120 + (yy - y0) * .34
        s += (f'<line x1="0" y1="{yy:.0f}" x2="{W}" y2="{yy:.0f}" stroke="#3c3d40"'
              f' stroke-width="4" opacity=".8"/>')
        xx = -((ry % 2) * sh / 2)
        while xx < W:
            s += (f'<line x1="{xx:.0f}" y1="{yy:.0f}" x2="{xx:.0f}" y2="{yy+sh:.0f}"'
                  f' stroke="#3c3d40" stroke-width="4" opacity=".7"/>')
            xx += sh
        yy += sh
        ry += 1
    s += (f'<ellipse cx="{rnd.uniform(300,1600):.0f}" cy="{(y0+y1)/2+90:.0f}" rx="210"'
          f' ry="46" fill="#6d7f8c" opacity=".45"/>')
    s += _listya(seed + 7, listvy, y0 + 30, y1)
    return s


def _stennoe_hozyaystvo(x, y, t, seed=3):
    """Что всегда висит на стене амбара или сарая: грабли, коса, хомут,
    серп, верёвочный моток, скоба и пила. Узнаваемые силуэты в рост человека."""
    rnd = random.Random(seed)
    s = ""
    # грабли
    gx = x + 40
    kach = 1.4 * A.w(t, 4.6, .1)
    s += (f'<g transform="rotate({kach:.2f} {gx:.0f} {y+430:.0f})">'
          f'<rect x="{gx-9:.0f}" y="{y:.0f}" width="18" height="430" rx="8"'
          f' fill="url(#derev)" {o(4)}/>'
          f'<rect x="{gx-86:.0f}" y="{y:.0f}" width="172" height="22" rx="8"'
          f' fill="#5b4428" {o(4)}/>')
    for i in range(7):
        s += (f'<line x1="{gx-76+i*25:.0f}" y1="{y+20:.0f}" x2="{gx-76+i*25:.0f}"'
              f' y2="{y+66:.0f}" stroke="#4a3522" stroke-width="8"/>')
    s += "</g>"
    # коса
    kx = x + 240
    s += (f'<line x1="{kx:.0f}" y1="{y+30:.0f}" x2="{kx+40:.0f}" y2="{y+450:.0f}"'
          f' stroke="url(#derev)" stroke-width="18" stroke-linecap="round"/>'
          f'<path d="M{kx:.0f},{y+34:.0f} Q{kx-130:.0f},{y+90:.0f}'
          f' {kx-186:.0f},{y+196:.0f} Q{kx-110:.0f},{y+112:.0f} {kx-4:.0f},{y+62:.0f} Z"'
          f' fill="url(#zhel)" {o(5)}/>'
          f'<rect x="{kx+18:.0f}" y="{y+210:.0f}" width="40" height="18" rx="7"'
          f' fill="#5b4428" {o(3)}/>')
    # хомут
    hx, hy = x + 420, y + 150
    s += (f'<path d="M{hx:.0f},{hy-110:.0f} Q{hx+116:.0f},{hy-70:.0f}'
          f' {hx+106:.0f},{hy+70:.0f} Q{hx+56:.0f},{hy+170:.0f}'
          f' {hx-6:.0f},{hy+170:.0f} Q{hx-68:.0f},{hy+170:.0f}'
          f' {hx-118:.0f},{hy+70:.0f} Q{hx-128:.0f},{hy-70:.0f} {hx:.0f},{hy-110:.0f} Z"'
          f' fill="#5e442a" {o(6)}/>'
          f'<path d="M{hx:.0f},{hy-62:.0f} Q{hx+72:.0f},{hy-32:.0f}'
          f' {hx+64:.0f},{hy+62:.0f} Q{hx+32:.0f},{hy+120:.0f}'
          f' {hx-6:.0f},{hy+120:.0f} Q{hx-44:.0f},{hy+120:.0f}'
          f' {hx-76:.0f},{hy+62:.0f} Q{hx-84:.0f},{hy-32:.0f} {hx:.0f},{hy-62:.0f} Z"'
          f' fill="#2e2118" {o(4)}/>'
          f'<rect x="{hx-18:.0f}" y="{hy-128:.0f}" width="36" height="26" rx="9"'
          f' fill="{ZHELEZ}" {o(3)}/>')
    # моток верёвки
    vx, vy = x + 600, y + 120
    for i in range(4):
        s += (f'<circle cx="{vx:.0f}" cy="{vy:.0f}" r="{74-i*16:.0f}" fill="none"'
              f' stroke="#9a8a68" stroke-width="13" opacity=".9"/>')
    # серп
    sx_, sy_ = x + 760, y + 110
    s += (f'<path d="M{sx_:.0f},{sy_:.0f} Q{sx_+110:.0f},{sy_+20:.0f}'
          f' {sx_+120:.0f},{sy_+140:.0f} Q{sx_+86:.0f},{sy_+48:.0f} {sx_:.0f},{sy_+30:.0f} Z"'
          f' fill="url(#zhel)" {o(5)}/>'
          f'<rect x="{sx_-56:.0f}" y="{sy_-10:.0f}" width="60" height="26" rx="11"'
          f' fill="url(#derev)" {o(4)}/>')
    # пила
    px_, py_ = x + 880, y + 320
    s += (f'<path d="M{px_:.0f},{py_:.0f} L{px_+280:.0f},{py_+40:.0f}'
          f' L{px_+280:.0f},{py_+88:.0f} L{px_:.0f},{py_+48:.0f} Z" fill="url(#zhel)"'
          f' {o(5)}/>')
    for i in range(11):
        s += (f'<path d="M{px_+10+i*25:.0f},{py_+50+i*3.6:.0f}'
              f' L{px_+22+i*25:.0f},{py_+72+i*3.6:.0f}'
              f' L{px_+34+i*25:.0f},{py_+52+i*3.6:.0f} Z" fill="#cfd8e0" opacity=".9"/>')
    s += (f'<rect x="{px_-46:.0f}" y="{py_-10:.0f}" width="50" height="70" rx="12"'
          f' fill="url(#derev)" {o(4)}/>')
    return s


def _kadushki_i_grabli(x, y, t, seed=5):
    """Угол двора: кадушка с водой и ледком, пара вёдер, корзина с репой,
    охапка хвороста и воткнутая лопата. Ставится у ног, держит низ кадра."""
    rnd = random.Random(seed)
    s = _dvorovaya_utvar(x, y, 420, t, seed, ["kadka", "vedro", "korzina"])
    # ЛЕДОК В КАДУШКЕ — ВОДА И КОЛОТЫЕ ПЛАСТИНЫ, А НЕ БЕЛАЯ ТРУБКА. Осмотр
    # 15.11: бледный овал #9fc4da с жёсткой чертой #e4f1fa во всю ширину
    # лежал на тёмном устье кадки и читался костью, лампой-трубкой или
    # скалкой. Теперь сначала тёмная вода, потом льдины с трещиной и
    # притопленным краем, а блик разбит на короткие искры.
    s += (f'<ellipse cx="{x+54:.0f}" cy="{y-150:.0f}" rx="58" ry="18"'
          f' fill="#2b4450" {o(0)}/>'
          f'<ellipse cx="{x+54:.0f}" cy="{y-151:.0f}" rx="50" ry="14"'
          f' fill="#3d5f6b" opacity=".9"/>'
          f'<path d="M{x+10:.0f},{y-152:.0f} Q{x+32:.0f},{y-164:.0f}'
          f' {x+56:.0f},{y-157:.0f} Q{x+76:.0f},{y-150:.0f} {x+60:.0f},{y-142:.0f}'
          f' Q{x+30:.0f},{y-140:.0f} {x+10:.0f},{y-152:.0f} Z" fill="#8fb6cc"'
          f' stroke="#5c7f90" stroke-width="3"/>'
          f'<path d="M{x+62:.0f},{y-160:.0f} Q{x+84:.0f},{y-156:.0f}'
          f' {x+96:.0f},{y-148:.0f} Q{x+80:.0f},{y-142:.0f} {x+62:.0f},{y-148:.0f} Z"'
          f' fill="#a2c6d8" stroke="#5c7f90" stroke-width="3"/>'
          f'<path d="M{x+34:.0f},{y-160:.0f} L{x+46:.0f},{y-146:.0f}'
          f' L{x+40:.0f},{y-141:.0f}" fill="none" stroke="#5c7f90"'
          f' stroke-width="3" opacity=".9"/>'
          f'<path d="M{x+22:.0f},{y-156:.0f} l10,-2 M{x+68:.0f},{y-153:.0f} l9,-2'
          f' M{x+48:.0f},{y-162:.0f} l8,-1" stroke="#e8f4fb" stroke-width="4"'
          f' opacity=".75" stroke-linecap="round"/>')
    # репа в корзине
    for i in range(5):
        rx_ = x + 300 + rnd.uniform(-44, 44)
        ry_ = y - 112 + rnd.uniform(-14, 10)
        s += (f'<circle cx="{rx_:.0f}" cy="{ry_:.0f}" r="{22+rnd.uniform(0,8):.0f}"'
              f' fill="#c9b07a" {o(3)}/>'
              f'<path d="M{rx_:.0f},{ry_-24:.0f} L{rx_+8:.0f},{ry_-48:.0f}"'
              f' stroke="#6f7a44" stroke-width="5"/>')
    # охапка хвороста
    hx = x + 400
    for i in range(9):
        a = math.radians(-66 + i * 9)
        s += (f'<line x1="{hx:.0f}" y1="{y-6:.0f}" x2="{hx+170*math.cos(a):.0f}"'
              f' y2="{y-6+170*math.sin(a):.0f}" stroke="#5e472e" stroke-width="7"'
              f' stroke-linecap="round" opacity=".9"/>')
    # лопата воткнута
    lx = x - 40
    s += (f'<line x1="{lx:.0f}" y1="{y-320:.0f}" x2="{lx+16:.0f}" y2="{y-70:.0f}"'
          f' stroke="url(#derev)" stroke-width="17" stroke-linecap="round"/>'
          f'<path d="M{lx+2:.0f},{y-74:.0f} L{lx+56:.0f},{y-58:.0f}'
          f' L{lx+42:.0f},{y+8:.0f} L{lx-18:.0f},{y-4:.0f} Z" fill="url(#zhel)" {o(5)}/>'
          f'<path d="M{lx-6:.0f},{y-320:.0f} L{lx+6:.0f},{y-350:.0f}'
          f' L{lx+26:.0f},{y-320:.0f} Z" fill="#5b4428" {o(3)}/>')
    return s


def _lavka_krupno(x, y, w_, t, h_=120, spinka=False):
    """Лавка вдоль стены: толстая доска, точёные ножки, подзор, тень под ней."""
    s = (f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="38" rx="8"'
         f' fill="url(#dosk)" {o(6)}/>'
         f'<rect x="{x:.0f}" y="{y-h_+38:.0f}" width="{w_:.0f}" height="16"'
         f' fill="#3a2a1a" opacity=".75"/>')
    for i in range(2):
        px = x + 24 + i * (w_ - 86)
        s += (f'<rect x="{px:.0f}" y="{y-h_+54:.0f}" width="52" height="{h_-54:.0f}"'
              f' rx="9" fill="#4a3522" {o(4)}/>'
              f'<ellipse cx="{px+26:.0f}" cy="{y-h_+90:.0f}" rx="32" ry="16"'
              f' fill="#5e442a" {o(3)}/>')
    s += (f'<rect x="{x+70:.0f}" y="{y-h_+58:.0f}" width="{w_-140:.0f}" height="22"'
          f' rx="8" fill="#4a3522" {o(3)}/>')
    if spinka:
        s += (f'<rect x="{x+10:.0f}" y="{y-h_-150:.0f}" width="{w_-20:.0f}" height="26"'
              f' rx="9" fill="#5b4428" {o(5)}/>')
        for i in range(5):
            bx = x + 50 + i * (w_ - 120) / 4.0
            s += (f'<rect x="{bx:.0f}" y="{y-h_-150:.0f}" width="20" height="152"'
                  f' rx="7" fill="#6a5030" {o(3)}/>')
    s += ten(x + w_ / 2, y + 6, w_ * .48, 16, .45)
    return s


def _stena_ambara(x, y, w_, h_, t, vorota=True, seed=3):
    """Бревенчатая стена амбара: венцы, затёсы, скоба, ворота на полозе."""
    s = brevna(x, y, w_, h_, 94)
    s += f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}" fill="none" {o(9)}/>'
    for bx in (x - 18, x + w_ - 36):
        s += (f'<rect x="{bx:.0f}" y="{y-10:.0f}" width="54" height="{h_+20:.0f}" rx="8"'
              f' fill="#3b2a1a" {o(5)}/>')
    if vorota:
        vx, vw = x + w_ * .54, w_ * .34
        s += (f'<rect x="{vx:.0f}" y="{y+h_*.22:.0f}" width="{vw:.0f}"'
              f' height="{h_*.78:.0f}" rx="8" fill="url(#derev)" {o(6)}/>')
        for i in range(5):
            s += (f'<rect x="{vx+12+i*(vw-32)/5:.0f}" y="{y+h_*.24:.0f}"'
                  f' width="{(vw-32)/6:.0f}" height="{h_*.74:.0f}" rx="6"'
                  f' fill="#6a5030" {o(3)}/>')
        s += (f'<path d="M{vx:.0f},{y+h_*.36:.0f} L{vx+vw:.0f},{y+h_*.70:.0f}'
              f' M{vx+vw:.0f},{y+h_*.36:.0f} L{vx:.0f},{y+h_*.70:.0f}" fill="none"'
              f' stroke="#4a3522" stroke-width="16"/>'
              f'<rect x="{vx-20:.0f}" y="{y+h_*.18:.0f}" width="{vw+40:.0f}" height="26"'
              f' rx="9" fill="{ZHELEZ}" {o(4)}/>'
              f'<circle cx="{vx+vw*.5:.0f}" cy="{y+h_*.56:.0f}" r="26" fill="{ZHELEZ}"'
              f' {o(4)}/>')
    return s


def _vid_za_proemom(put, t, kind="reka", seed=5, cx0=960):
    """Нарисованный вид ЗА проёмом — чтобы без стока сцена была целой, а за
    стеклом не чернела дыра (грабли №8). Клипуется контуром самого проёма."""
    rnd = random.Random(seed)
    cid = "vid%d" % seed
    s = (f'<clipPath id="{cid}"><path d="{put}"/></clipPath>'
         f'<g clip-path="url(#{cid})">')
    if kind == "reka":
        s += (f'<rect x="0" y="0" width="{W}" height="{H}" fill="#8a97a2"/>'
              f'<rect x="0" y="0" width="{W}" height="520" fill="#9fb0bc"/>'
              f'<path d="M0,520 L{W},520 L{W},{H} L0,{H} Z" fill="url(#voda)"/>')
        for i in range(7):                                     # лесистый берег
            bx = i * 300 + rnd.uniform(-60, 60)
            s += (f'<path d="M{bx-200:.0f},522 Q{bx-60:.0f},{470-rnd.uniform(0,40):.0f}'
                  f' {bx+40:.0f},{486:.0f} Q{bx+150:.0f},{452:.0f} {bx+280:.0f},522 Z"'
                  f' fill="#4e5a4a" opacity=".9"/>')
        for i in range(14):                                    # блики на воде
            wy = 540 + i * 34
            dl = 120 + (i % 4) * 90
            wx = rnd.uniform(0, W) + 26 * A.w(t, 5.0 + i * .3, i * .2)
            s += (f'<rect x="{wx:.0f}" y="{wy:.0f}" width="{dl:.0f}" height="7" rx="3"'
                  f' fill="#d7e6ef" opacity="{.18+.14*abs(A.w(t,3.0,i*.3)):.2f}"/>')
    elif kind == "zarya":
        s += (f'<rect x="0" y="0" width="{W}" height="{H}" fill="url(#zakat)"/>'
              f'<rect x="0" y="560" width="{W}" height="{H-560}" fill="#6e5f46"/>')
        sol = 1.0 + .08 * abs(A.w(t, 3.2, .1))
        s += (f'<circle cx="{cx0:.0f}" cy="548" r="{150*sol:.0f}" fill="#ffd79a"'
              f' opacity=".85"/>'
              f'<circle cx="{cx0:.0f}" cy="548" r="{250*sol:.0f}" fill="#ffc07a"'
              f' opacity=".3"/>')
        for i in range(9):
            fy = 570 + i * 46
            s += (f'<path d="M-40,{fy:.0f} Q480,{fy-18:.0f} 960,{fy+8:.0f}'
                  f' Q1440,{fy+26:.0f} 1960,{fy-6:.0f}" fill="none" stroke="#7d6b4c"'
                  f' stroke-width="{7+i}" opacity=".45"/>')
        for i in range(5):                                     # полосы тумана
            my = 520 + i * 58
            s += (f'<rect x="{-200+((t*8+i*280)%2400):.0f}" y="{my:.0f}" width="620"'
                  f' height="26" rx="13" fill="#e8dcc8" opacity=".38"/>')
    elif kind == "les":
        s += (f'<rect x="0" y="0" width="{W}" height="{H}" fill="#8e9a96"/>'
              f'<rect x="0" y="700" width="{W}" height="{H-700}" fill="#5c5744"/>')
        for sl, col, hh in ((0, "#6b7a6c", 300), (1, "#4e5c50", 420), (2, "#3a4740", 540)):
            for i in range(9):
                ex = i * 230 - 60 + sl * 70 + 10 * A.w(t, 6.0 + sl, i * .2)
                eb = 700 + sl * 20
                s += (f'<path d="M{ex:.0f},{eb:.0f} L{ex+70:.0f},{eb-hh:.0f}'
                      f' L{ex+140:.0f},{eb:.0f} Z" fill="{col}" opacity=".95"/>')
        for i in range(4):
            my = 560 + i * 70
            s += (f'<rect x="{-200+((t*10+i*320)%2500):.0f}" y="{my:.0f}" width="760"'
                  f' height="34" rx="17" fill="#dce4e2" opacity=".32"/>')
    elif kind == "ulica":
        s += (f'<rect x="0" y="0" width="{W}" height="{H}" fill="#1b2232"/>'
              f'<rect x="0" y="720" width="{W}" height="{H-720}" fill="#2b3240"/>')
        for i in range(10):
            dx_ = i * 210 - 40
            s += (f'<rect x="{dx_:.0f}" y="{260+(i%3)*60:.0f}" width="150"'
                  f' height="{460-(i%3)*60:.0f}" fill="#2a3champ"/>'.replace("champ", "140"))
            for k in range(5):
                if (i + k) % 2:
                    s += (f'<rect x="{dx_+18+(k%2)*70:.0f}" y="{300+(i%3)*60+k*74:.0f}"'
                          f' width="52" height="50" rx="5" fill="#ffd98a"'
                          f' opacity="{.5+.3*abs(A.w(t,4.0,i*.2+k*.1)):.2f}"/>')
        for i in range(7):
            fx_ = 110 + i * 280
            s += (f'<circle cx="{fx_:.0f}" cy="{660:.0f}" r="{40+14*abs(A.w(t,3.0,i*.3)):.0f}"'
                  f' fill="#ffe0a0" opacity=".55"/>'
                  f'<rect x="{fx_-6:.0f}" y="660" width="12" height="180" fill="#20252e"/>')
    s += "</g>"
    return s


def _moneta_krupno(cx, cy, r, t, ph=.0, med=True, profil=True, plosko=.0):
    """Монета, которую видно со стоп-кадра (R-0047): поле, гурт насечкой,
    внутренний ободок, рельефный профиль головы, венок, бегущий блик и тень.
    plosko 0..1 — насколько монета ЛЕЖИТ: кружок сплющивается в эллипс."""
    bl = .5 + .5 * A.w(t, 1.9, ph)
    col = "url(#med)" if med else "url(#zhel)"
    szh = 1.0 - .58 * plosko
    g0 = (f'<g transform="translate({cx:.0f} {cy:.0f}) scale(1 {szh:.3f})'
          f' translate({-cx:.0f} {-cy:.0f})">')
    s = ten(cx, cy + r * .72 * szh + 10, r * 1.1, r * .20, .5)
    s += g0
    s += (f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="{r:.0f}" fill="{col}" {o(7)}/>'
          f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="{r*.88:.0f}" fill="none"'
          f' stroke="#8a5a22" stroke-width="7" opacity=".8"/>'
          f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="{r*.76:.0f}" fill="none"'
          f' stroke="#d6a358" stroke-width="5" opacity=".65"/>')
    for i in range(34):
        a = math.radians(i * 360 / 34.0)
        s += (f'<line x1="{cx+r*.9*math.cos(a):.0f}" y1="{cy+r*.9*math.sin(a):.0f}"'
              f' x2="{cx+r*1.0*math.cos(a):.0f}" y2="{cy+r*1.0*math.sin(a):.0f}"'
              f' stroke="#7a4d1c" stroke-width="5" opacity=".75"/>')
    if profil and r >= 48:
        for i in range(11):
            a = math.radians(118 + i * 124 / 10.0)
            lx, ly = cx + r * .82 * math.cos(a), cy + r * .82 * math.sin(a)
            s += (f'<ellipse cx="{lx:.0f}" cy="{ly:.0f}" rx="{r*.09:.0f}"'
                  f' ry="{r*.045:.0f}" transform="rotate({math.degrees(a)+90:.0f}'
                  f' {lx:.0f} {ly:.0f})" fill="#b57c33" opacity=".85"/>')
        s += (f'<path d="M{cx-r*.30:.0f},{cy+r*.56:.0f}'
              f' L{cx-r*.26:.0f},{cy+r*.08:.0f}'
              f' Q{cx-r*.30:.0f},{cy-r*.34:.0f} {cx-r*.02:.0f},{cy-r*.46:.0f}'
              f' Q{cx+r*.22:.0f},{cy-r*.52:.0f} {cx+r*.26:.0f},{cy-r*.26:.0f}'
              f' L{cx+r*.38:.0f},{cy-r*.02:.0f} L{cx+r*.24:.0f},{cy+r*.04:.0f}'
              f' L{cx+r*.26:.0f},{cy+r*.14:.0f} L{cx+r*.14:.0f},{cy+r*.18:.0f}'
              f' Q{cx+r*.20:.0f},{cy+r*.34:.0f} {cx+r*.02:.0f},{cy+r*.38:.0f}'
              f' L{cx+r*.06:.0f},{cy+r*.56:.0f} Z" fill="#a86a28" {o(4)}/>'
              f'<path d="M{cx-r*.24:.0f},{cy-r*.30:.0f}'
              f' Q{cx-r*.02:.0f},{cy-r*.46:.0f} {cx+r*.22:.0f},{cy-r*.28:.0f}"'
              f' fill="none" stroke="#d8a357" stroke-width="{max(3,r*.05):.0f}"'
              f' opacity=".85"/>'
              f'<circle cx="{cx+r*.10:.0f}" cy="{cy-r*.20:.0f}" r="{max(2,r*.045):.0f}"'
              f' fill="#6d4116"/>'
              f'<path d="M{cx+r*.10:.0f},{cy+r*.08:.0f} L{cx+r*.22:.0f},{cy+r*.08:.0f}"'
              f' stroke="#6d4116" stroke-width="{max(2,r*.035):.0f}"/>')
    elif profil:
        s += (f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="{r*.40:.0f}" fill="#a86a28" {o(3)}/>')
    s += (f'<path d="M{cx-r*.72:.0f},{cy-r*.40:.0f} Q{cx-r*.16:.0f},{cy-r*.90:.0f}'
          f' {cx+r*.50:.0f},{cy-r*.58:.0f}" fill="none" stroke="#fff3cf"'
          f' stroke-width="{r*.15:.0f}" stroke-linecap="round" opacity="{.30+bl*.42:.2f}"/>')
    s += "</g>"
    for i in range(4):
        a = math.radians(42 + i * 76 + 40 * A.w(t, 2.6, ph + i * .2))
        rr = r * (1.16 + .16 * i)
        s += (f'<circle cx="{cx+rr*math.cos(a):.0f}"'
              f' cy="{cy+rr*math.sin(a)*szh:.0f}" r="{6+i*2}" fill="#fff0c4"'
              f' opacity="{.25+bl*.45:.2f}"/>')
    return s


def _inej(seed, n, y0, y1, col="#cfe4f5"):
    """Иней на мёрзлой земле: искры-крестики, вспыхивают по сетке."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        ix, iy = rnd.uniform(0, W), rnd.uniform(y0, y1)
        r = rnd.uniform(7, 15)
        s += (f'<line x1="{ix-r:.0f}" y1="{iy:.0f}" x2="{ix+r:.0f}" y2="{iy:.0f}"'
              f' stroke="{col}" stroke-width="3" opacity=".55"/>'
              f'<line x1="{ix:.0f}" y1="{iy-r:.0f}" x2="{ix:.0f}" y2="{iy+r:.0f}"'
              f' stroke="{col}" stroke-width="3" opacity=".55"/>')
    return s


def _podorozhnik(x, y, s_=1.0, t=0.0, ph=.0, n=5, col="#6f7a44"):
    """Куст подорожника: широкие листья розеткой и стрелка-колос."""
    s = ""
    for i in range(n):
        a = math.radians(-168 + i * (336.0 / max(1, n - 1)) + 6 * A.w(t, 3.2, ph + i * .2))
        dl = 86 * s_ * (.8 + .2 * (i % 2))
        ex, ey = x + dl * math.cos(a), y + dl * math.sin(a) * .5
        s += (f'<path d="M{x:.0f},{y:.0f} Q{(x+ex)/2:.0f},{(y+ey)/2-34*s_:.0f}'
              f' {ex:.0f},{ey:.0f} Q{(x+ex)/2:.0f},{(y+ey)/2+22*s_:.0f} {x:.0f},{y:.0f} Z"'
              f' fill="{col}" {o(3)}/>')
    s += (f'<line x1="{x:.0f}" y1="{y:.0f}" x2="{x+8*s_:.0f}" y2="{y-130*s_:.0f}"'
          f' stroke="#7f8a52" stroke-width="{5*s_:.0f}"/>'
          f'<ellipse cx="{x+8*s_:.0f}" cy="{y-142*s_:.0f}" rx="{9*s_:.0f}" ry="{26*s_:.0f}"'
          f' fill="#8a7a46" {o(2)}/>')
    return s


def _ruka(fx, fy, fh, storona, dl, ug, t, col="#2a2430", kant="#cfe4f5",
          ph=.0, amp=6.0):
    """РУКА ОТ ПЛЕЧА И ТОЛЬКО НАРУЖУ. Осмотр 15.11 глазами: рукав рисовался
    прямой палкой, рос из корпуса мимо плеча и шёл через грудь, подбородок и
    лицо («позу распятие» и «брусок через глаза» видно в кадре, числами не
    ловится). Лечение держит КОД, а не памятка:

    · точка начала берётся у `_plecho()` этой же фигуры — из корпуса рука
      вырасти не может;
    · угол задаётся в НАРУЖНОЙ системе: 0 — прямо в сторону от тела,
      +90 — вниз, -90 — вверх. Внутрь, к оси тела, повернуть нельзя: знак
      подставляет сторона плеча;
    · коридор -58°..+88°: выше рука задирается к своему лицу, ниже она
      заваливается внутрь, к подолу, и ложится на грудь.

    Отсюда и свойство, которое проверяется по координатам: конец рукава
    всегда дальше от оси тела, чем плечо, значит в прямоугольник головы и
    груди он не попадает НИ ПРИ КАКИХ числах.

    Возвращает (svg, (конец рукава), (плечо)).
    """
    px, py = _plecho(fx, fy, fh, storona)
    ug = max(-58.0, min(88.0, float(ug)))
    a = ug if storona > 0 else 180.0 - ug
    ruk, (ex, ey) = rukav(px, py, dl, a, t, col, kant, ph, amp)
    # ОПЛЕЧЬЕ. Осмотр 15.11, второй заход: `_plecho` держит точку на w*.40, а
    # верхний край одежды кончается на w*.33 — между ними 17 px пустоты, и
    # рукав толщиной 33 px висел РЯДОМ с фигурой отдельной палкой с
    # набалдашником-скруглением на конце («ни за что не держится»). Зазор
    # закрывается накладкой у плеча: она принадлежит ПЛЕЧУ, поэтому обещание
    # «конец рукава не попадает в голову и грудь» остаётся в силе.
    w_ = fh * .42
    plech = fy - fh * .66
    tol = max(14.0, dl * .19)
    opl = (f'<ellipse cx="{fx + storona * w_ * .345:.0f}"'
           f' cy="{plech + fh * .018:.0f}" rx="{w_ * .135:.0f}"'
           f' ry="{tol * .62:.0f}" fill="{col}" stroke="{K}"'
           f' stroke-width="{max(2, fh * .011):.1f}"/>'
           f'<path d="M{fx + storona * w_ * .22:.0f},{plech - fh * .004:.0f}'
           f' Q{fx + storona * w_ * .34:.0f},{plech - fh * .030:.0f}'
           f' {fx + storona * w_ * .46:.0f},{plech + fh * .010:.0f}"'
           f' fill="none" stroke="{kant}" stroke-width="{max(2, fh * .012):.1f}"'
           f' opacity=".7" stroke-linecap="round"/>')
    return opl + ruk, (ex, ey), (px, py)


def _ruka_ekr(fx, fy, fh, storona, dl, ug_ekran, t, col="#2a2430", kant="#cfe4f5",
              ph=.0, amp=6.0):
    """Тот же `_ruka`, но угол задан в ЭКРАННЫХ градусах, как у `rukav()`.

    Нужен, чтобы перевести на безопасную руку все сцены разом, не переписывая
    каждую позу числами: экранный угол сводится к наружному (для левого плеча
    это 180 - угол), а дальше работает коридор `_ruka`. Где поза и так была
    наружу, кадр не меняется ни на пиксель; где рукав шёл поперёк тела, он
    прижимается к ближайшей честной позе.
    """
    u = float(ug_ekran) if storona > 0 else 180.0 - float(ug_ekran)
    u = (u + 180.0) % 360.0 - 180.0
    return _ruka(fx, fy, fh, storona, dl, u, t, col, kant, ph, amp)


def _ruka_so_sgibom(fx, fy, fh, storona, dl1, ug1, dl2, ug2, t, col="#2a2430",
                    kant="#cfe4f5", ph=.0, amp=6.0):
    """РУКА СО СГИБОМ В ЛОКТЕ. Прямой рукав в полроста читается БРУСКОМ, даже
    когда он честно идёт от плеча и никого не пересекает (осмотр 15.11:
    «длинная прямая рука-брусок по диагонали»). Лечение — два звена: плечевая
    часть от плеча, предплечье от локтя под своим углом.

    Углы оба в НАРУЖНОЙ системе `_ruka` и оба зажаты тем же коридором, поэтому
    предплечье уходит ещё дальше от оси тела, чем локоть: в голову и грудь
    кисть не попадает так же надёжно, как у прямой руки.
    """
    ruk, (ex, ey), (px, py) = _ruka(fx, fy, fh, storona, dl1, ug1, t, col, kant,
                                    ph, amp)
    u2 = max(-58.0, min(88.0, float(ug2)))
    a2 = u2 if storona > 0 else 180.0 - u2
    pre, (kx, ky) = rukav(ex, ey, dl2, a2, t, col, kant, ph + .3, amp * .7, True)
    lok = (f'<circle cx="{ex:.0f}" cy="{ey:.0f}" r="{max(9, dl1 * .11):.0f}"'
           f' fill="{col}" stroke="{K}" stroke-width="{max(2, fh * .010):.1f}"/>')
    return ruk + lok + pre, (kx, ky), (px, py)


def _predmet_naruzhu(fx, fh, ex, w_pred):
    """Сдвиг предмета, чтобы его габарит не налез на свою же фигуру.

    Предмет начинается от конца рукава; если его половина достаёт до оси
    тела — отодвигаем наружу ровно настолько, насколько не хватает.
    """
    st = 1 if ex >= fx else -1
    nado = fh * .42 * .52 + w_pred * .5
    est = abs(ex - fx)
    return st * max(.0, nado - est)


def _sledy(x0, y0, x1, y1, n=7, seed=3, col="#33281d", s_=1.0):
    """Цепочка следов валенок, уходящая в глубину: НАСТОЯЩАЯ вещь в нижней
    трети, а не полупрозрачное пятно (за пятна работу уже отклоняли).
    Каждый след — вдавленный овал с бортиком и рубчиком подошвы."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        p = i / max(1, n - 1.0)
        sx = x0 + (x1 - x0) * p + rnd.uniform(-10, 10)
        sy = y0 + (y1 - y0) * p
        k = s_ * (1.0 - .52 * p)
        bok = 34 * k * (1 if i % 2 else -1)
        rx_, ry_ = 40 * k, 20 * k
        s += (f'<ellipse cx="{sx+bok:.0f}" cy="{sy:.0f}" rx="{rx_:.0f}" ry="{ry_:.0f}"'
              f' fill="{col}" opacity=".92"/>'
              f'<ellipse cx="{sx+bok:.0f}" cy="{sy-ry_*.26:.0f}" rx="{rx_*.86:.0f}"'
              f' ry="{ry_*.72:.0f}" fill="#241b12" opacity=".85"/>')
        for j in range(3):
            s += (f'<line x1="{sx+bok-rx_*.6:.0f}" y1="{sy-ry_*.4+j*ry_*.5:.0f}"'
                  f' x2="{sx+bok+rx_*.6:.0f}" y2="{sy-ry_*.4+j*ry_*.5:.0f}"'
                  f' stroke="#6b5a44" stroke-width="{max(2,3*k):.0f}" opacity=".5"/>')
        s += (f'<path d="M{sx+bok-rx_:.0f},{sy+ry_*.2:.0f} a{rx_:.0f},{ry_:.0f} 0 0 0'
              f' {rx_*2:.0f},0" fill="none" stroke="#cfe4f5" stroke-width="{max(2,3*k):.0f}"'
              f' opacity=".45"/>')
    return s


def _luzha(cx, cy, rx, t, ph=.0, ry=None, otraz="#7e97ad"):
    """Лужа с ОТРАЖЕНИЕМ: вода, перевёрнутое небо в ней, кромка грязи и
    дрожь по поверхности. Настоящая вещь нижней трети."""
    ry = ry if ry is not None else rx * .34
    dr = 1.0 + .04 * A.w(t, 1.1, ph)
    s = (f'<ellipse cx="{cx:.0f}" cy="{cy:.0f}" rx="{rx*1.06:.0f}" ry="{ry*1.16:.0f}"'
         f' fill="#2e2317" opacity=".9"/>'
         f'<ellipse cx="{cx:.0f}" cy="{cy:.0f}" rx="{rx:.0f}" ry="{ry:.0f}"'
         f' fill="{otraz}" opacity=".88"/>'
         f'<ellipse cx="{cx:.0f}" cy="{cy:.0f}" rx="{rx*.92:.0f}" ry="{ry*.84:.0f}"'
         f' fill="#4a5f72" opacity=".55"/>')
    for i in range(3):
        yy = cy - ry * .40 + i * ry * .42
        s += (f'<ellipse cx="{cx+rx*.10*(1 if i%2 else -1):.0f}" cy="{yy:.0f}"'
              f' rx="{rx*(.72-i*.16)*dr:.0f}" ry="{ry*.13:.0f}" fill="#cfe4f5"'
              f' opacity="{.50-i*.12:.2f}"/>')
    s += (f'<ellipse cx="{cx-rx*.34:.0f}" cy="{cy-ry*.18:.0f}" rx="{rx*.20:.0f}"'
          f' ry="{ry*.26:.0f}" fill="#eaf3fb" opacity=".45"/>')
    for i in range(5):
        a = math.radians(i * 72 + 14)
        s += (f'<ellipse cx="{cx+rx*1.02*math.cos(a):.0f}" cy="{cy+ry*1.08*math.sin(a):.0f}"'
              f' rx="{rx*.13:.0f}" ry="{ry*.22:.0f}" fill="#3f3122" opacity=".8"/>')
    return s


def _iriska(cx, cy, s_=1.0, ug=0.0, col="#8a5a22", fant="#efe2c2"):
    """ИРИСКА — ПОДУШЕЧКА В ФАНТИКЕ, А НЕ МОНЕТКА. Осмотр 15.11: в окошке
    ларька и в коробке на полке конфеты были нарисованы жёлтыми кружками и
    читались мелочью. Здесь: тёмная подушечка с мягкими рёбрами, светлый
    фантик скрученными концами по сторонам и косая полоска-надрыв."""
    w_, h_ = 54 * s_, 36 * s_
    return (f'<g transform="rotate({ug:.0f} {cx:.0f} {cy:.0f})">'
            f'<path d="M{cx-w_:.0f},{cy:.0f} L{cx-w_*.56:.0f},{cy-h_*.86:.0f}'
            f' L{cx-w_*.50:.0f},{cy+h_*.10:.0f} L{cx-w_*.62:.0f},{cy+h_*.90:.0f} Z"'
            f' fill="{fant}" {o(3)}/>'
            f'<path d="M{cx+w_:.0f},{cy:.0f} L{cx+w_*.56:.0f},{cy-h_*.90:.0f}'
            f' L{cx+w_*.50:.0f},{cy+h_*.06:.0f} L{cx+w_*.62:.0f},{cy+h_*.86:.0f} Z"'
            f' fill="{fant}" {o(3)}/>'
            f'<path d="M{cx-w_*.58:.0f},{cy-h_*.72:.0f}'
            f' Q{cx:.0f},{cy-h_*.98:.0f} {cx+w_*.58:.0f},{cy-h_*.72:.0f}'
            f' Q{cx+w_*.70:.0f},{cy:.0f} {cx+w_*.58:.0f},{cy+h_*.72:.0f}'
            f' Q{cx:.0f},{cy+h_*.98:.0f} {cx-w_*.58:.0f},{cy+h_*.72:.0f}'
            f' Q{cx-w_*.70:.0f},{cy:.0f} {cx-w_*.58:.0f},{cy-h_*.72:.0f} Z"'
            f' fill="{col}" {o(4)}/>'
            f'<path d="M{cx-w_*.34:.0f},{cy-h_*.60:.0f} L{cx-w_*.06:.0f},{cy+h_*.62:.0f}"'
            f' stroke="{fant}" stroke-width="{max(3,5*s_):.0f}" opacity=".75"/>'
            f'<path d="M{cx-w_*.40:.0f},{cy-h_*.30:.0f}'
            f' Q{cx:.0f},{cy-h_*.52:.0f} {cx+w_*.40:.0f},{cy-h_*.30:.0f}" fill="none"'
            f' stroke="#c99a52" stroke-width="{max(2,4*s_):.0f}" opacity=".7"/>'
            f'<path d="M{cx-w_*.44:.0f},{cy+h_*.34:.0f}'
            f' Q{cx:.0f},{cy+h_*.56:.0f} {cx+w_*.44:.0f},{cy+h_*.34:.0f}" fill="none"'
            f' stroke="#5e3c14" stroke-width="{max(2,4*s_):.0f}" opacity=".7"/></g>')


def _kucha_listev(x, y, w_, seed=5, h_=78):
    """СГРЕБЁННАЯ куча листьев: горка с черенками, а не россыпь по всему
    кадру. Ставится у стены, у крыльца, под деревом."""
    rnd = random.Random(seed)
    cols = ("#9a5a28", "#b4762f", "#7d4a24", "#c08a3a", "#6e4420")
    s = (f'<path d="M{x-w_*.5:.0f},{y:.0f} Q{x-w_*.30:.0f},{y-h_:.0f} {x:.0f},{y-h_*.92:.0f}'
         f' Q{x+w_*.32:.0f},{y-h_*.86:.0f} {x+w_*.5:.0f},{y:.0f} Z"'
         f' fill="#6b4320" {o(5)}/>')
    for i in range(26):
        lx = x + rnd.uniform(-w_ * .50, w_ * .50)
        ly = y - rnd.uniform(0, h_ * .92) * (1 - abs(lx - x) / (w_ * .55))
        r = rnd.uniform(16, 30)
        a = rnd.uniform(-70, 70)
        s += (f'<g transform="rotate({a:.0f} {lx:.0f} {ly:.0f})">'
              f'<path d="M{lx:.0f},{ly:.0f} q{r*.8:.0f},{-r*.7:.0f} {r*1.7:.0f},0'
              f' q{-r*.8:.0f},{r*.7:.0f} {-r*1.7:.0f},0 Z"'
              f' fill="{cols[rnd.randrange(len(cols))]}" {o(3)}/>'
              f'<line x1="{lx:.0f}" y1="{ly:.0f}" x2="{lx-r*.5:.0f}" y2="{ly+r*.2:.0f}"'
              f' stroke="#4e3418" stroke-width="3"/></g>')
    return s


def _kot_zhivoy(x, y, t, s_=1.0, col="#3b3430", ph=.0, polosy=True, spit=False):
    """КОТ, КОТОРЫЙ ЧИТАЕТСЯ КОТОМ. Осмотр 15.11: тёмное пятно с двумя
    точками. Здесь — хвост трубой с кольцами, два уха с розовой изнанкой,
    четыре лапы, белая грудка и морда с усами."""
    hv = 9 * A.w(t, 2.4, ph)
    uh = 5 * A.w(t, 1.7, ph + .3)
    s = ten(x, y + 8 * s_, 86 * s_, 15 * s_, .45)
    # четыре лапы — две передние, две задние
    for dx, w2 in ((-54, 20), (-26, 18), (34, 20), (58, 18)):
        s += (f'<rect x="{x+dx*s_-w2*s_*.5:.0f}" y="{y-34*s_:.0f}" width="{w2*s_:.0f}"'
              f' height="{36*s_:.0f}" rx="{w2*s_*.45:.0f}" fill="{col}" {o(4)}/>'
              f'<ellipse cx="{x+dx*s_:.0f}" cy="{y:.0f}" rx="{w2*s_*.72:.0f}"'
              f' ry="{8*s_:.0f}" fill="#241f1c" {o(3)}/>')
    # хвост трубой
    s += (f'<g transform="rotate({hv:.1f} {x-62*s_:.0f} {y-42*s_:.0f})">'
          f'<path d="M{x-62*s_:.0f},{y-42*s_:.0f} q{-30*s_:.0f},{-46*s_:.0f}'
          f' {-6*s_:.0f},{-108*s_:.0f}" fill="none" stroke="{col}"'
          f' stroke-width="{24*s_:.0f}" stroke-linecap="round"/>')
    for i in range(3):
        s += (f'<line x1="{x-80*s_+i*4*s_:.0f}" y1="{y-78*s_-i*26*s_:.0f}"'
              f' x2="{x-56*s_+i*4*s_:.0f}" y2="{y-84*s_-i*26*s_:.0f}"'
              f' stroke="#8f857c" stroke-width="{7*s_:.0f}" opacity=".6"/>')
    s += (f'<circle cx="{x-68*s_:.0f}" cy="{y-150*s_:.0f}" r="{12*s_:.0f}"'
          f' fill="#cfc6bb" opacity=".7"/></g>')
    # корпус и белая грудка
    s += (f'<ellipse cx="{x:.0f}" cy="{y-56*s_:.0f}" rx="{82*s_:.0f}" ry="{44*s_:.0f}"'
          f' fill="{col}" {o(6)}/>')
    if polosy:
        for i in range(4):
            s += (f'<path d="M{x-46*s_+i*28*s_:.0f},{y-92*s_:.0f} q{8*s_:.0f},{30*s_:.0f}'
                  f' {2*s_:.0f},{58*s_:.0f}" fill="none" stroke="#6a6058"'
                  f' stroke-width="{9*s_:.0f}" opacity=".55"/>')
    s += (f'<ellipse cx="{x+44*s_:.0f}" cy="{y-44*s_:.0f}" rx="{26*s_:.0f}"'
          f' ry="{30*s_:.0f}" fill="#e7ded2" opacity=".85"/>')
    hx, hy = x + 62 * s_, y - 106 * s_
    for sgn in (-1, 1):                 # уши с розовой изнанкой
        s += (f'<g transform="rotate({uh*sgn:.1f} {hx:.0f} {hy:.0f})">'
              f'<path d="M{hx+sgn*26*s_:.0f},{hy-20*s_:.0f} l{sgn*8*s_:.0f},{-36*s_:.0f}'
              f' l{-sgn*34*s_:.0f},{12*s_:.0f} Z" fill="{col}" {o(4)}/>'
              f'<path d="M{hx+sgn*24*s_:.0f},{hy-24*s_:.0f} l{sgn*5*s_:.0f},{-20*s_:.0f}'
              f' l{-sgn*19*s_:.0f},{7*s_:.0f} Z" fill="#c08a8a" opacity=".8"/></g>')
    s += (f'<circle cx="{hx:.0f}" cy="{hy:.0f}" r="{40*s_:.0f}" fill="{col}" {o(6)}/>'
          f'<ellipse cx="{hx+10*s_:.0f}" cy="{hy+18*s_:.0f}" rx="{24*s_:.0f}"'
          f' ry="{16*s_:.0f}" fill="#e7ded2" opacity=".8"/>')
    for dx in (-14, 16):                # глаза
        if spit or A.blink(t, 4.6, ph + .2):
            s += (f'<path d="M{hx+dx*s_-11*s_:.0f},{hy-4*s_:.0f}'
                  f' q{11*s_:.0f},{7*s_:.0f} {22*s_:.0f},0" fill="none" stroke="{K}"'
                  f' stroke-width="{max(2,4*s_):.0f}" stroke-linecap="round"/>')
        else:
            s += (f'<ellipse cx="{hx+dx*s_:.0f}" cy="{hy-4*s_:.0f}" rx="{9*s_:.0f}"'
                  f' ry="{11*s_:.0f}" fill="#d8e86a"/>'
                  f'<ellipse cx="{hx+dx*s_:.0f}" cy="{hy-4*s_:.0f}" rx="{3.2*s_:.0f}"'
                  f' ry="{10*s_:.0f}" fill="{K}"/>')
    s += (f'<path d="M{hx+6*s_:.0f},{hy+12*s_:.0f} l{8*s_:.0f},{6*s_:.0f}'
          f' l{-8*s_:.0f},{5*s_:.0f} Z" fill="#c07a74" {o(2)}/>')
    for i, dy in enumerate((-4, 4)):    # усы
        for sgn in (-1, 1):
            s += (f'<line x1="{hx+sgn*8*s_:.0f}" y1="{hy+16*s_+dy*s_:.0f}"'
                  f' x2="{hx+sgn*48*s_:.0f}" y2="{hy+10*s_+dy*2.4*s_:.0f}"'
                  f' stroke="#e7ded2" stroke-width="{3*s_:.0f}" opacity=".8"/>')
    return s


def _yaschiki(x, y, t, seed=7, n=3, s_=1.0):
    """Штабель ящиков и короб у стены: вещи в рост человека по пояс."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        w2 = (150 + rnd.uniform(-20, 28)) * s_
        h2 = (110 + rnd.uniform(-14, 22)) * s_
        bx = x + i * w2 * .96
        by = y - (h2 if i % 2 == 0 else h2 * 1.9)
        s += (f'<rect x="{bx:.0f}" y="{by:.0f}" width="{w2:.0f}" height="{h2:.0f}"'
              f' rx="7" fill="url(#derev)" {o(5)}/>')
        for j in range(3):
            s += (f'<line x1="{bx+6:.0f}" y1="{by+h2*(j+1)/4.0:.0f}"'
                  f' x2="{bx+w2-6:.0f}" y2="{by+h2*(j+1)/4.0:.0f}"'
                  f' stroke="#3c2a1a" stroke-width="4" opacity=".6"/>')
        s += (f'<rect x="{bx+w2*.18:.0f}" y="{by+h2*.22:.0f}" width="{w2*.64:.0f}"'
              f' height="{h2*.30:.0f}" rx="5" fill="#8a6a44" opacity=".5"/>')
        if i % 2 == 0:
            s += (f'<rect x="{bx:.0f}" y="{by-h2*.84:.0f}" width="{w2:.0f}"'
                  f' height="{h2*.84:.0f}" rx="7" fill="#5a4228" {o(5)}/>')
    return s


# ═══ из chast1.py ═══
def moneta_na_tropinke(t):
    """Утоптанная тропинка в инее, медяк в четверть кадра, бабушка с бидоном
    останавливается над ним. Вокруг — живая деревня: избы, заборы, колея."""
    rnd = random.Random(101)
    gor = 500
    s = nebo("sumer", t, True, 11)
    s += oblaka(t, 150, 5, 7, .4)
    s += SL(Z_DAL, _derevnya_ryad(gor, t, 7, ((150, 330), (470, 270), (1760, 300))))
    s += SL(Z_DAL, goloe_derevo(760, gor + 30, 720, t, 4, 10, "#2a2b33", True)
            + goloe_derevo(1200, gor + 22, 560, t, 9, 9, "#2a2b33", True)
            + goloe_derevo(1480, gor + 14, 400, t, 14, 7, "#2a2b33", True))
    sta = ""
    for i in range(9):
        bx_ = 420 + i * 130 + 30 * math.sin(t * .5 + i)
        by_ = 210 + (i % 4) * 46 + 12 * A.w(t, 2.0, i * .3)
        sta += ptica(bx_, by_, t, .9, "#4a4a52", i * .2)
    s += SL(Z_DAL, sta)
    s += SL(Z_DAL, _zabor_dosok(-20, 356, 1040, 200, 5, 52)
            + _zabor_dosok(1180, 368, 760, 196, 8, 54))
    s += SL(Z_DAL, teplo(470, gor - 110, 230, 170, .42))

    zem = f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor}" fill="#4c3b2a"/>'
    zem += (f'<path d="M-40,{gor+70:.0f} Q500,{gor+20:.0f} 1020,{gor+96:.0f}'
            f' Q1520,{gor+170:.0f} 1960,{gor+120:.0f} L1960,1080 L-40,1080 Z"'
            f' fill="#5d4830" {o(0)}/>')
    zem += _koleya(gor + 180, 21, 2)
    zem += _listya(23, 34, gor + 90, 1060)
    zem += _trava(rnd, 16, gor + 60, 1050)
    zem += _inej(31, 48, gor + 60, 1060)
    zem += _podorozhnik(300, 960, 1.5, t, .2)
    zem += _podorozhnik(1640, 880, 1.1, t, .6)
    zem += kartoshka(1560, 1010, t, 5, 6, .9)
    s += SL(Z_SRED, zem)
    s += SL(Z_SRED, _dvorovaya_utvar(70, 700, 420, t, 9, ["korzina", "vedro", "korob"]))
    s += SL(Z_SRED, _polenica(1480, 620, 380, 190, 7, 24))
    # после того как монета ужалась до трети роста, в середине кадра
    # освободилось место — закрываю его вещами, а не пустотой
    s += SL(Z_SRED, _dvorovaya_utvar(880, 800, 380, t, 357,
                                     ["korzina", "vedro", "meshok"]))
    s += SL(Z_SRED, _kucha_listev(500, 906, 268, 359, 86)
            + kartoshka(1010, 944, t, 7, 361, 1.05)
            + _sledy(210, 1046, 606, 892, 6, 363, "#33281d", 1.1))

    # МОНЕТА — ТРЕТЬ РОСТА ФИГУРЫ (осмотр 15.11, второй заход: 428 px всё
    # ещё читались половиной роста). Диаметр 292 при росте 880 и голове 270 —
    # чуть больше головы, меньше трети человека.
    s += SL(Z_SRED, _moneta_krupno(706, 862, 146, t, .1))

    fx, fy, fh = 1400, 1076, 880
    stop = A.ease(A.seg(t, .4, 1.1))
    fig = figura(fx - 40 * (1 - stop), fy, fh, t, col="#30323e", kant="#cfe4f5",
                 platok=True, tulup=True, ph=.3)
    ruk, (rx2, ry2), (psx, psy) = _ruka(fx, fy, fh, 1, fh * .44, 74, t,
                                        "#30323e", "#cfe4f5", .3, 9.0)
    fig += ruk
    bid = 10 * A.w(t, 1.3, .2)
    fig += (f'<g transform="rotate({bid:.1f} {rx2:.0f} {ry2:.0f})">'
            f'<rect x="{rx2-42:.0f}" y="{ry2:.0f}" width="84" height="112" rx="10"'
            f' fill="url(#zhel)" {o(5)}/>'
            f'<rect x="{rx2-50:.0f}" y="{ry2-14:.0f}" width="100" height="22" rx="8"'
            f' fill="{ZHELEZ}" {o(4)}/>'
            f'<path d="M{rx2-30:.0f},{ry2-14:.0f} Q{rx2:.0f},{ry2-62:.0f}'
            f' {rx2+30:.0f},{ry2-14:.0f}" fill="none" stroke="{ZHELEZ}" stroke-width="8"/>'
            f'<line x1="{rx2-34:.0f}" y1="{ry2+56:.0f}" x2="{rx2+34:.0f}" y2="{ry2+56:.0f}"'
            f' stroke="#2f3337" stroke-width="6" opacity=".7"/></g>')
    ruk2, (lx2, ly2), (plx, ply) = _ruka(fx, fy, fh, -1, fh * .22, -52, t,
                                         "#30323e", "#cfe4f5", .7, 5.0)
    fig += ruk2
    fig += (f'<path d="M{lx2-18:.0f},{ly2-6:.0f} Q{lx2:.0f},{ly2+34:.0f}'
            f' {lx2+22:.0f},{ly2-4:.0f}" fill="none" stroke="#6d4a52" stroke-width="12"/>')
    fig += para_izo_rta(fx - 54, fy - fh * .80, t, .2, 1.1, .55)
    s += SL(Z_SRED, fig)
    s += SL(Z_SRED, ten(fx, fy + 8, 186, 30, .5))
    # НИЖНЯЯ ТРЕТЬ — НАСТОЯЩИМИ ВЕЩАМИ: следы к монете, лужа с отражением,
    # сгребённые листья, кот у поленницы. Счётчик низ не меряет, глаз меряет.
    s += SL(Z_SRED, _sledy(1760, 1070, 1180, 862, 7, 41, "#33281d", 1.25)
            + _luzha(430, 1012, 196, t, .3)
            + _kucha_listev(1066, 1062, 300, 43, 94)
            + _kot_zhivoy(206, 902, t, .86, "#2f2a26", .4))

    s += SL(Z_PERED, _vetka_pered(-60, 120, 820, 22, t, 3, "#241c16", 7))
    s += SL(Z_LETIT, mokryy_sneg(t, 20, 5, .5, .8))
    s += ramka_pp("levo")
    s += vinetka(.42)
    return s


def monety_do_samoy_kalitki(t):
    """Тропинка сверху: медяки лежат дорожкой, как крошки, и ведут к резной
    калитке. Между ними бусина, пуговица и колечко. Петух на заборе тянет шею."""
    rnd = random.Random(102)
    gor = 400
    s = nebo("rassv", t, False, 13)
    s += oblaka(t, 120, 5, 9, .42)
    s += SL(Z_DAL, _derevnya_ryad(gor, t, 11, ((170, 380), (520, 300), (1700, 420))))
    s += SL(Z_DAL, goloe_derevo(1340, gor + 10, 420, t, 6, 8, "#2a2b33", True)
            + goloe_derevo(230, gor + 20, 300, t, 16, 6, "#2a2b33", True))
    s += SL(Z_DAL, _zabor_dosok(-20, 272, 1060, 216, 4, 54)
            + _zabor_dosok(1180, 280, 780, 212, 6, 56))
    s += SL(Z_DAL, teplo(520, gor - 120, 220, 170, .40))

    zem = f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor}" fill="#4a3a29"/>'
    zem += (f'<path d="M-40,1080 Q420,{gor+300:.0f} 700,{gor+80:.0f}'
            f' L1180,{gor+80:.0f} Q1480,{gor+300:.0f} 1960,1080 Z" fill="#6a5236" {o(0)}/>')
    zem += _zemlya_faktura(gor + 90, 1060, 51, 18)
    zem += _koleya(880, 24, 2)
    zem += _listya(25, 34, gor + 80, 1060)
    zem += _trava(rnd, 16, gor + 60, 1050)
    zem += _inej(33, 48, gor + 70, 1060)
    zem += _podorozhnik(1790, 980, 1.6, t, .4)
    zem += _podorozhnik(110, 900, 1.3, t, .8)
    s += SL(Z_SRED, zem)

    kx, ky, kw, kh = 760, 250, 390, 360
    kach = 2.2 * A.w(t, 3.0, .1)
    kal = (f'<g transform="rotate({kach:.1f} {kx:.0f} {ky+kh:.0f})">'
           f'<rect x="{kx:.0f}" y="{ky:.0f}" width="{kw:.0f}" height="{kh:.0f}" rx="10"'
           f' fill="url(#derev)" {o(6)}/>')
    for i in range(6):
        bx = kx + 24 + i * (kw - 60) / 5.0
        kal += (f'<rect x="{bx:.0f}" y="{ky+14:.0f}" width="34" height="{kh-28:.0f}"'
                f' rx="6" fill="#6a5030" {o(3)}/>')
    kal += (f'<path d="M{kx:.0f},{ky+50:.0f} L{kx+kw:.0f},{ky+190:.0f}'
            f' M{kx+kw:.0f},{ky+50:.0f} L{kx:.0f},{ky+190:.0f}" fill="none"'
            f' stroke="#4a3522" stroke-width="16"/>')
    for i in range(8):
        gx = kx + 8 + i * (kw - 16) / 7.0
        kal += (f'<path d="M{gx:.0f},{ky:.0f} Q{gx+16:.0f},{ky-42:.0f}'
                f' {gx+32:.0f},{ky:.0f} Z" fill="#6a5030" {o(3)}/>')
    kal += (f'<circle cx="{kx+kw-46:.0f}" cy="{ky+kh*.5:.0f}" r="18" fill="{ZHELEZ}" {o(3)}/>'
            f'</g>')
    for bx in (kx - 54, kx + kw + 10):
        kal += (f'<rect x="{bx:.0f}" y="{ky-56:.0f}" width="54" height="{kh+150:.0f}"'
                f' rx="8" fill="#3f2d1c" {o(6)}/>'
                f'<path d="M{bx-18:.0f},{ky-56:.0f} L{bx+27:.0f},{ky-112:.0f}'
                f' L{bx+72:.0f},{ky-56:.0f} Z" fill="#4e3a24" {o(5)}/>')
    s += SL(Z_SRED, kal)
    s += SL(Z_SRED, teplo(kx + kw * .5, ky + kh * .5, 300, 230, .38))

    # дорожка медяков: лежат ПЛАШМЯ и сходятся к калитке по перспективе
    dor = ""
    for i in range(13):
        p = i / 12.0
        mx = 1430 + (kx + kw * .5 - 1430) * (p ** .80) + (330 - 390 * p) * math.sin(p * 6.1)
        my = 1066 - (1066 - (ky + kh + 24)) * (p ** .70)
        r = 98 - 76 * p
        vsp = max(.0, 1 - abs(((t * .9) % 1.0) - p) * 5.4)
        dor += _moneta_krupno(mx, my, r, t, i * .17, True, r > 44, .74)
        if vsp > 0:
            dor += (f'<ellipse cx="{mx:.0f}" cy="{my:.0f}" rx="{r*1.8:.0f}"'
                    f' ry="{r*.8:.0f}" fill="#ffe9ac" opacity="{vsp*.34:.2f}"/>')
    dor += (f'<ellipse cx="560" cy="968" rx="32" ry="24" fill="#6fa0c4" {o(4)}/>'
            f'<circle cx="550" cy="958" r="10" fill="#cfe9fb" opacity=".8"/>'
            f'<ellipse cx="1420" cy="900" rx="40" ry="18" fill="#e8e2d2" {o(4)}/>'
            f'<ellipse cx="1420" cy="900" rx="17" ry="8" fill="none" stroke="#b9ae95"'
            f' stroke-width="5"/>'
            f'<ellipse cx="420" cy="804" rx="36" ry="16" fill="none" stroke="url(#med)"'
            f' stroke-width="12"/>')
    s += SL(Z_SRED, dor)
    s += SL(Z_SRED, _polenica(40, 620, 380, 270, 12, 26))
    s += SL(Z_SRED, _dvorovaya_utvar(1180, 1056, 420, t, 14,
                                     ["kadka", "vedro", "korzina"]))

    # ЖИВОЙ ЧЕЛОВЕК В КАДРЕ (осмотр 15.11: сцена была совсем без фигуры —
    # дорожка медяков вела к калитке, и подобрать их было некому) и НИЖНЯЯ
    # ТРЕТЬ настоящими вещами: следы по тропе, лужа с отражением калитки,
    # сгребённые листья у столба, кот у поленницы, ящики под забором.
    fx, fy, fh = 1636, 1058, 790
    sh_ = 26 * A.w(t, .7, .2)
    fig = figura(fx + sh_, fy, fh, t, col="#3b3446", kant="#cfe4f5",
                 platok=True, tulup=True, ph=.25)
    rk, (kzx, kzy), _ = _ruka(fx, fy, fh, -1, fh * .40, 72, t,
                              "#3b3446", "#cfe4f5", .2, 6)
    fig += rk
    kch = 7 * A.w(t, 1.2, .4)
    fig += (f'<g transform="rotate({kch:.1f} {kzx:.0f} {kzy:.0f})">'
            f'<path d="M{kzx-74:.0f},{kzy+10:.0f} L{kzx+74:.0f},{kzy+10:.0f}'
            f' L{kzx+56:.0f},{kzy+138:.0f} L{kzx-56:.0f},{kzy+138:.0f} Z"'
            f' fill="url(#derev)" {o(5)}/>')
    for i in range(5):
        fig += (f'<line x1="{kzx-70+i*6:.0f}" y1="{kzy+22+i*24:.0f}"'
                f' x2="{kzx+70-i*6:.0f}" y2="{kzy+22+i*24:.0f}"'
                f' stroke="#4e3a24" stroke-width="5" opacity=".7"/>')
    fig += (f'<path d="M{kzx-72:.0f},{kzy+12:.0f} Q{kzx:.0f},{kzy-66:.0f}'
            f' {kzx+72:.0f},{kzy+12:.0f}" fill="none" stroke="#5a4228"'
            f' stroke-width="11"/>'
            f'<ellipse cx="{kzx-24:.0f}" cy="{kzy+18:.0f}" rx="34" ry="18"'
            f' fill="#7d4a24" {o(3)}/>'
            f'<ellipse cx="{kzx+28:.0f}" cy="{kzy+14:.0f}" rx="30" ry="16"'
            f' fill="#9a5a28" {o(3)}/></g>')
    rk2, _, _ = _ruka(fx, fy, fh, 1, fh * .34, 86, t, "#3b3446", "#cfe4f5", .6, 5)
    fig += rk2
    fig += para_izo_rta(fx - 48, fy - fh * .80, t, .4, 1.0, .5)
    s += SL(Z_SRED, fig)
    s += SL(Z_SRED, ten(fx, fy + 8, 168, 28, .5))
    s += SL(Z_SRED, _sledy(1500, 1072, 1030, 666, 7, 57, "#2f2518", 1.2)
            + _luzha(300, 1016, 182, t, .5)
            + _kucha_listev(690, 1036, 272, 59, 86)
            + _kot_zhivoy(1010, 974, t, .78, "#4a423a", .6)
            + _yaschiki(1700, 790, t, 61, 2, .8))
    s += SL(Z_SRED, _dvorovaya_utvar(250, 744, 360, t, 345, ["korob", "meshok"]))
    s += SL(Z_SRED, _kadushki_i_grabli(60, 1072, t, 347))
    s += SL(Z_SRED, _listya(349, 30, 820, 1060))

    px, py = 1320, 292
    shea = 26 * A.ease(abs(A.w(t, 2.2, .0)))
    pet = (f'<ellipse cx="{px:.0f}" cy="{py-74:.0f}" rx="86" ry="62" fill="#8d4a2a" {o(5)}/>'
           f'<path d="M{px-78:.0f},{py-52:.0f} Q{px-140:.0f},{py-92:.0f}'
           f' {px-74:.0f},{py-150:.0f} Q{px-30:.0f},{py-120:.0f} {px-38:.0f},{py-64:.0f} Z"'
           f' fill="#5e2f1a" {o(4)}/>'
           f'<path d="M{px+52:.0f},{py-100:.0f} Q{px+92+shea:.0f},{py-128-shea:.0f}'
           f' {px+96+shea:.0f},{py-186-shea:.0f} L{px+58+shea:.0f},{py-188-shea:.0f}'
           f' Q{px+56:.0f},{py-134:.0f} {px+30:.0f},{py-94:.0f} Z" fill="#9c5630" {o(4)}/>'
           f'<circle cx="{px+80+shea:.0f}" cy="{py-202-shea:.0f}" r="34" fill="#a85c33"'
           f' {o(4)}/>'
           f'<circle cx="{px+94+shea:.0f}" cy="{py-210-shea:.0f}" r="6" fill="#120c08"/>'
           f'<path d="M{px+112+shea:.0f},{py-202-shea:.0f} L{px+156+shea:.0f},'
           f'{py-192-shea:.0f} L{px+112+shea:.0f},{py-182-shea:.0f} Z" fill="#d8a14a"'
           f' {o(3)}/>'
           f'<path d="M{px+60+shea:.0f},{py-234-shea:.0f} Q{px+76+shea:.0f},'
           f'{py-276-shea:.0f} {px+96+shea:.0f},{py-234-shea:.0f}'
           f' Q{px+112+shea:.0f},{py-268-shea:.0f} {px+124+shea:.0f},{py-228-shea:.0f} Z"'
           f' fill="{KRAS}" {o(3)}/>'
           f'<path d="M{px+74+shea:.0f},{py-178-shea:.0f} Q{px+86+shea:.0f},'
           f'{py-152-shea:.0f} {px+98+shea:.0f},{py-178-shea:.0f} Z" fill="{KRAS}" {o(2)}/>'
           f'<path d="M{px-70:.0f},{py-96:.0f} Q{px-10:.0f},{py-150:.0f}'
           f' {px+30:.0f},{py-104:.0f}" fill="none" stroke="#b5682f" stroke-width="10"'
           f' opacity=".8"/>'
           f'<line x1="{px-14:.0f}" y1="{py-18:.0f}" x2="{px-14:.0f}" y2="{py+30:.0f}"'
           f' stroke="#d8a14a" stroke-width="9"/>'
           f'<line x1="{px+28:.0f}" y1="{py-18:.0f}" x2="{px+28:.0f}" y2="{py+30:.0f}"'
           f' stroke="#d8a14a" stroke-width="9"/>')
    s += SL(Z_SRED, pet)
    s += SL(Z_DAL, dym(520, 250, t, 5, .26, 300, .36, "#d3dae2", .9)
            + dym(1700, 210, t, 4, .22, 260, .30, "#d3dae2", .8))
    s += SL(Z_PERED, _stolb_pered(-10, 110, "#1d1611", 0, H))
    s += SL(Z_LETIT, mokryy_sneg(t, 16, 7, .45, .7))
    s += ramka_pp("pravo")
    s += vinetka(.42)
    return s


def kalitka_na_zare(t):
    """Распахнутая резная калитка справа, за ней настоящая заря. Девушка в
    тулупчике широким взмахом бросает за калитку горсть мелочи из плошки."""
    rnd = random.Random(103)
    gor = 600
    s = nebo("rassv", t, False, 5)
    s += oblaka(t, 110, 4, 3, .38)

    px_, py_, pw_, ph_ = 1150, 170, 770, 480
    put = kontur_proema(px_, py_, pw_, ph_, "arka")
    s += SL(Z_DAL, _vid_za_proemom(put, t, "zarya", 5, px_ + pw_ * .5)
            + mesto_stoka(px_, py_, pw_, ph_, "arka")
            + f'<path d="{put}" fill="none" stroke="#2a1d12" stroke-width="16"/>')

    ug = -22 + 3 * A.w(t, 4.0, .2)
    stv = (f'<g transform="rotate({ug:.1f} {px_-40:.0f} {py_+ph_:.0f})">'
           f'<rect x="{px_-300:.0f}" y="{py_+60:.0f}" width="270" height="{ph_-40:.0f}"'
           f' rx="10" fill="url(#derev)" {o(6)}/>')
    for i in range(4):
        stv += (f'<rect x="{px_-282+i*64:.0f}" y="{py_+78:.0f}" width="40"'
                f' height="{ph_-76:.0f}" rx="6" fill="#6a5030" {o(3)}/>')
    for i in range(6):
        gx = px_ - 296 + i * 46
        stv += (f'<path d="M{gx:.0f},{py_+60:.0f} Q{gx+12:.0f},{py_+20:.0f}'
                f' {gx+24:.0f},{py_+60:.0f} Z" fill="#6a5030" {o(3)}/>')
    stv += (f'<path d="M{px_-300:.0f},{py_+140:.0f} L{px_-30:.0f},{py_+320:.0f}'
            f' M{px_-30:.0f},{py_+140:.0f} L{px_-300:.0f},{py_+320:.0f}" fill="none"'
            f' stroke="#4a3522" stroke-width="16"/>'
            f'<circle cx="{px_-70:.0f}" cy="{py_+ph_*.52:.0f}" r="20" fill="{ZHELEZ}"'
            f' {o(3)}/></g>')
    for bx in (px_ - 60, px_ + pw_ + 6):
        stv += (f'<rect x="{bx:.0f}" y="{py_-60:.0f}" width="58" height="{ph_+200:.0f}"'
                f' rx="8" fill="#3b2a1a" {o(6)}/>'
                f'<path d="M{bx-18:.0f},{py_-60:.0f} L{bx+29:.0f},{py_-120:.0f}'
                f' L{bx+76:.0f},{py_-60:.0f} Z" fill="#4e3a24" {o(5)}/>')
    s += SL(Z_SRED, stv)

    s += SL(Z_DAL, brevna(-20, 60, 1000, 560, 92))
    s += SL(Z_DAL, okno_izby(110, 170, 310, 260, t, svet=True)
            + teplo(265, 300, 260, 210, .44))
    s += SL(Z_DAL, dver(520, 140, 290, 480, .0, "url(#derev)", True, False))
    s += SL(Z_DAL, podkova(664, 100, 1.6, t))
    s += SL(Z_DAL, _polka_s_utvaryu(70, 540, 400, t, 75, 3))
    s += SL(Z_DAL, ryabina(900, 560, t, 1.3, 5))

    zem = f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor}" fill="#4a3a29"/>'
    zem += (f'<path d="M-40,1080 Q440,{gor+230:.0f} 900,{gor+50:.0f}'
            f' L1500,{gor+50:.0f} Q1760,{gor+200:.0f} 1960,1080 Z" fill="#5e482f" {o(0)}/>')
    zem += _zemlya_faktura(gor + 70, 1060, 53, 16)
    zem += _listya(27, 30, gor + 50, 1060)
    zem += _trava(rnd, 12, gor + 40, 1050)
    zem += _inej(35, 36, gor + 50, 1060)
    s += SL(Z_SRED, zem)
    s += SL(Z_SRED, _kryl_co(40, 690, 500, 180, t, 3, True, False))
    s += SL(Z_SRED, _dvorovaya_utvar(50, 684, 460, t, 19, ["vedro", "vedro", "kadka"]))
    s += SL(Z_SRED, grozd_ryabiny(1880, 790, t, 1.6, 12, 4, .3))

    bx, by = 520, 1074
    vyg = 18 * A.ease(abs(A.w(t, 2.8, .3)))
    s += SL(Z_SRED, f'<rect x="{bx:.0f}" y="{by-250:.0f}" width="290" height="250" rx="10"'
                    f' fill="url(#derev)" {o(6)}/>'
                    f'<path d="M{bx-24:.0f},{by-250:.0f} L{bx+145:.0f},{by-344:.0f}'
                    f' L{bx+314:.0f},{by-250:.0f} Z" fill="#4e3a24" {o(5)}/>'
                    f'<ellipse cx="{bx+145:.0f}" cy="{by-112:.0f}" rx="76" ry="92"'
                    f' fill="#20170f" {o(4)}/>'
                    f'<ellipse cx="{bx+145-vyg:.0f}" cy="{by-106:.0f}" rx="50" ry="46"'
                    f' fill="#6b5236" {o(4)}/>'
                    f'<circle cx="{bx+127-vyg:.0f}" cy="{by-114:.0f}" r="6" fill="#120c08"/>'
                    f'<circle cx="{bx+163-vyg:.0f}" cy="{by-114:.0f}" r="6" fill="#120c08"/>'
                    f'<ellipse cx="{bx+146-vyg:.0f}" cy="{by-78:.0f}" rx="16" ry="11"'
                    f' fill="#2a1d12"/>'
                    f'<path d="M{bx+104-vyg:.0f},{by-140:.0f} L{bx+90-vyg:.0f},{by-176:.0f}'
                    f' L{bx+124-vyg:.0f},{by-156:.0f} Z" fill="#4e3a24" {o(3)}/>')

    fx, fy, fh = 840, 1046, 720
    vzm = A.ease(A.seg(t, .35, 1.2))
    fig = figura(fx, fy, fh, t, col="#6a4a32", kant="#ffd98a", platok=False, ph=.2,
                 tulup=True, naklon=5 * vzm)
    ruk, (rx2, ry2), (psx, psy) = _ruka(fx, fy, fh, 1, fh * .50, -54 + 92 * vzm,
                                        t, "#6a4a32", "#ffd98a", .1, 6)
    fig += ruk
    ruk2, (lx2, ly2), (plx, ply) = _ruka(fx, fy, fh, -1, fh * .46, 46, t,
                                         "#6a4a32", "#ffd98a", .5, 5)
    fig += ruk2
    # ПЛОШКА С МЕЛОЧЬЮ, А НЕ ТЁМНЫЙ КРУГ (осмотр 15.11: предмет в руке читался
    # кошкой или горшком). Теперь это широкая низкая плошка на 430 px —
    # главный предмет сцены, и мелочь в ней лежит горкой и видна поштучно.
    bcx = lx2 + _predmet_naruzhu(fx, fh, lx2, 430)
    bry = ly2 - 18
    fig += (f'<path d="M{bcx-215:.0f},{bry:.0f} Q{bcx-204:.0f},{bry+116:.0f}'
            f' {bcx:.0f},{bry+128:.0f} Q{bcx+204:.0f},{bry+116:.0f}'
            f' {bcx+215:.0f},{bry:.0f} Z" fill="url(#glina)" {o(6)}/>'
            f'<path d="M{bcx-180:.0f},{bry+54:.0f} Q{bcx:.0f},{bry+96:.0f}'
            f' {bcx+180:.0f},{bry+54:.0f}" fill="none" stroke="#8a6a44"'
            f' stroke-width="9" opacity=".6"/>'
            f'<ellipse cx="{bcx:.0f}" cy="{bry:.0f}" rx="215" ry="58"'
            f' fill="#3a2a18" {o(5)}/>'
            f'<ellipse cx="{bcx:.0f}" cy="{bry+4:.0f}" rx="188" ry="46"'
            f' fill="#1f160e" opacity=".85"/>'
            f'<ellipse cx="{bcx:.0f}" cy="{bry:.0f}" rx="215" ry="58" fill="none"'
            f' stroke="#d8b878" stroke-width="7" opacity=".7"/>')
    for i, (mdx, mdy, mr) in enumerate(((-126, 10, 46), (-54, 22, 50), (16, 14, 44),
                                        (84, 24, 48), (142, 6, 40),
                                        (-88, -18, 42), (48, -22, 44))):
        fig += _moneta_krupno(bcx + mdx, bry + mdy, mr, t, i * .18, True, False, .66)
    fig += (f'<ellipse cx="{bcx-70:.0f}" cy="{bry-12:.0f}" rx="86" ry="20"'
            f' fill="#ffeab4" opacity="{.18+.14*A.w(t,1.6,.3):.2f}"/>'
            f'<path d="M{lx2-30:.0f},{bry+8:.0f} q{30:.0f},{34:.0f} {62:.0f},{2:.0f}"'
            f' fill="none" stroke="#6a4a32" stroke-width="22"'
            f' stroke-linecap="round" opacity=".95"/>')
    kosa = 30 * vzm
    fig += (f'<path d="M{fx-fh*.14:.0f},{fy-fh*.78:.0f}'
            f' Q{fx-fh*.30-kosa:.0f},{fy-fh*.58:.0f} {fx-fh*.22-kosa*1.4:.0f},{fy-fh*.32:.0f}"'
            f' fill="none" stroke="#6b4a26" stroke-width="26" stroke-linecap="round"/>'
            f'<path d="M{fx+fh*.22:.0f},{fy-fh*.52:.0f}'
            f' Q{fx+fh*.34+kosa:.0f},{fy-fh*.30:.0f} {fx+fh*.26+kosa:.0f},{fy-fh*.10:.0f}"'
            f' fill="none" stroke="#7a5438" stroke-width="20" opacity=".8"/>')
    fig += para_izo_rta(fx + 46, fy - fh * .80, t, .1, 1.1, .5)
    s += SL(Z_SRED, fig + ten(fx, fy + 8, 152, 26, .5))

    let = ""
    for i in range(10):
        p = max(.0, min(1.0, (t * .62 + i * .07) % 1.0))
        mx = rx2 + (1086 - rx2) * p
        my = ry2 - 150 * math.sin(math.pi * p) + 520 * p * p
        let += _moneta_krupno(mx, my, 34, t, i * .2, True, False, .55 * p)
    s += SL(Z_SRED, let)
    s += SL(Z_PERED, _vetka_pered(-40, 70, 700, 24, t, 8, "#241c16", 6))
    s += SL(Z_LETIT, mokryy_sneg(t, 14, 9, .4, .7))
    s += ramka_pp("oba")
    s += vinetka(.40)
    return s


def prohozhiy_i_chuzhaya_prosba(t):
    """Дорога за калиткой: парень в картузе приседает на колено и поднимает
    монету, из неё вылетает светящееся письмо-голубок и садится ему на плечо.
    Девушки в окнах задёргивают занавески одна за другой."""
    rnd = random.Random(104)
    gor = 430
    s = nebo("sumer", t, True, 19)
    s += oblaka(t, 120, 5, 11, .4)
    s += SL(Z_DAL, _derevnya_ryad(gor, t, 21, ((140, 470), (620, 390), (1180, 340),
                                               (1700, 440))))
    s += SL(Z_DAL, goloe_derevo(960, gor + 12, 330, t, 3, 7, "#2a2b33", True))
    s += SL(Z_DAL, teplo(620, gor - 150, 230, 180, .40) + teplo(1180, gor - 130, 200, 150, .38))
    s += SL(Z_DAL, _zabor_dosok(-20, 342, 1020, 190, 23, 52)
            + _zabor_dosok(1140, 350, 820, 186, 25, 54))

    zem = f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor}" fill="#45382a"/>'
    zem += (f'<path d="M-40,1080 Q300,{gor+320:.0f} 660,{gor+56:.0f}'
            f' L1280,{gor+56:.0f} Q1640,{gor+320:.0f} 1960,1080 Z" fill="#5e4830" {o(0)}/>')
    zem += _zemlya_faktura(gor + 100, 1060, 59, 18)
    zem += _koleya(820, 26, 2)
    zem += _listya(29, 36, gor + 80, 1060)
    zem += _trava(rnd, 13, gor + 70, 1050)
    zem += _inej(37, 40, gor + 70, 1060)
    s += SL(Z_SRED, zem)

    # колодец-сруб и поленница по сторонам дороги
    kx, ky = 1700, 900
    kol = (f'<rect x="{kx-170:.0f}" y="{ky-220:.0f}" width="340" height="220" rx="8"'
           f' fill="url(#derev)" {o(6)}/>')
    for i in range(4):
        kol += (f'<rect x="{kx-170:.0f}" y="{ky-216+i*54:.0f}" width="340" height="48"'
                f' rx="8" fill="url(#brev)" {o(3)}/>')
    kol += (f'<rect x="{kx-192:.0f}" y="{ky-246:.0f}" width="384" height="30" rx="8"'
            f' fill="#5b4428" {o(5)}/>'
            f'<ellipse cx="{kx:.0f}" cy="{ky-246:.0f}" rx="150" ry="26" fill="#160f0a"'
            f' {o(3)}/>')
    s += SL(Z_SRED, kol)
    s += SL(Z_SRED, _polenica(80, 620, 420, 280, 27, 27))
    s += SL(Z_SRED, _dvorovaya_utvar(1180, 1064, 460, t, 29, ["kadka", "korzina", "meshok"]))

    # парень: приседает на левое колено, правой поднимает монету
    uh = A.ease(A.seg(t, 2.6, 1.8))
    fx = 820 + 420 * uh
    fy = 1040
    fh = 560 - 110 * (1 - uh)
    fig = figura(fx, fy, fh, t, col="#3b3346", kant="#ffd98a", ph=.2, shapka=True,
                 naklon=-14 * (1 - uh))
    # РУКИ ОТ ПЛЕЧА И НАРУЖУ: прежде левый рукав на подъёме доходил до угла
    # 74° и шёл прямой палкой через грудь — в кадре это читалось посохом,
    # проткнувшим корпус (осмотр 15.11).
    ruk, (rx2, ry2), (psx, psy) = _ruka(fx, fy, fh, 1, fh * .52, 76 - 44 * uh,
                                        t, "#3b3346", "#ffd98a", .1, 7)
    fig += ruk
    ruk2, _, (plx, ply) = _ruka(fx, fy, fh, -1, fh * .40, 96 - 26 * uh, t,
                                "#3b3346", "#ffd98a", .5, 5)
    fig += ruk2
    # колено на земле, пока не встал
    if uh < .9:
        fig += (f'<path d="M{fx-80:.0f},{fy-10:.0f} L{fx-10:.0f},{fy-170*(1-uh)-30:.0f}'
                f' L{fx+40:.0f},{fy-6:.0f} Z" fill="#3b3346" opacity="{1-uh:.2f}" {o(5)}/>')
    fig += para_izo_rta(fx + 50, fy - fh * .80, t, .3, 1.1, .5)
    s += SL(Z_SRED, fig + ten(fx, fy + 8, 120, 22, .45))
    s += SL(Z_SRED, _moneta_krupno(770, 990, 110, t, .3, True, True, .6))

    # письмо-голубок с сердечком садится на плечо
    gp = A.ease(A.seg(t, 1.3, 1.4))
    gx = 770 + (psx - 770) * gp
    gy = 990 + (psy - 50 - 990) * gp - 200 * math.sin(math.pi * gp)
    kr = 30 * A.w(t, .34, .0)
    gol = (f'<circle cx="{gx:.0f}" cy="{gy:.0f}" r="80" fill="#ffe9ac" opacity=".30"/>'
           f'<path d="M{gx-54:.0f},{gy:.0f} L{gx+54:.0f},{gy-26:.0f}'
           f' L{gx+54:.0f},{gy+26:.0f} Z" fill="#f6ecd4" {o(3)}/>'
           f'<path d="M{gx-14:.0f},{gy-12:.0f} Q{gx+16:.0f},{gy-62-kr:.0f}'
           f' {gx+52:.0f},{gy-22:.0f} Z" fill="#fff6dd" {o(3)}/>'
           f'<path d="M{gx-14:.0f},{gy+12:.0f} Q{gx+16:.0f},{gy+62+kr:.0f}'
           f' {gx+52:.0f},{gy+22:.0f} Z" fill="#f0e2c4" {o(3)}/>'
           f'<path d="M{gx+6:.0f},{gy-36:.0f} Q{gx+20:.0f},{gy-58:.0f}'
           f' {gx+34:.0f},{gy-36:.0f} Q{gx+46:.0f},{gy-16:.0f} {gx+20:.0f},{gy-2:.0f}'
           f' Q{gx-6:.0f},{gy-16:.0f} {gx+6:.0f},{gy-36:.0f} Z" fill="{KRAS}" {o(2)}/>')
    s += SL(Z_SRED, gol)

    # занавески в окнах задёргиваются по очереди
    zan = ""
    for i, (ox, oy) in enumerate(((548, gor - 200), (1116, gor - 170), (1646, gor - 210))):
        z = A.ease(A.seg(t, 1.0 + i * .4, .6))
        zan += (f'<rect x="{ox-10:.0f}" y="{oy-10:.0f}" width="132" height="150" rx="6"'
                f' fill="#4a3522" {o(4)}/>'
                f'<rect x="{ox:.0f}" y="{oy:.0f}" width="112" height="130" rx="5"'
                f' fill="#f2d79a" opacity="{.88-.55*z:.2f}" {o(3)}/>'
                f'<rect x="{ox:.0f}" y="{oy:.0f}" width="{56*z:.0f}" height="130"'
                f' fill="{TKAN}" {o(2)}/>'
                f'<rect x="{ox+112-56*z:.0f}" y="{oy:.0f}" width="{56*z:.0f}" height="130"'
                f' fill="{TKAN}" {o(2)}/>'
                f'<line x1="{ox+56:.0f}" y1="{oy:.0f}" x2="{ox+56:.0f}" y2="{oy+130:.0f}"'
                f' stroke="#4a3522" stroke-width="6"/>'
                f'<rect x="{ox-22:.0f}" y="{oy-26:.0f}" width="156" height="22" rx="6"'
                f' fill="#6a5030" {o(3)}/>')
    s += SL(Z_SRED, zan)
    s += SL(Z_PERED, _stolb_pered(1860, 120, "#1d1611", 0, H))
    s += SL(Z_LETIT, mokryy_sneg(t, 18, 11, .45, .8))
    s += ramka_pp("levo")
    s += vinetka(.42)
    return s


def muzh_zhena_i_moneta_u_kolodca(t):
    """Колодец с журавлём на пол-кадра: муж тянется к монете у сруба, жена
    держит его за рукав и показывает на ворону, севшую на журавль."""
    rnd = random.Random(105)
    gor = 460
    s = nebo("sumer", t, True, 29)
    s += oblaka(t, 120, 4, 13, .4)
    s += SL(Z_DAL, _derevnya_ryad(gor, t, 31, ((170, 420), (600, 330), (1800, 400))))
    s += SL(Z_DAL, goloe_derevo(420, gor + 14, 440, t, 5, 9, "#2a2b33", True)
            + goloe_derevo(1640, gor + 10, 300, t, 15, 7, "#2a2b33", True))
    s += SL(Z_DAL, _zabor_dosok(-20, 344, 1100, 200, 33, 52)
            + _zabor_dosok(1280, 352, 680, 196, 34, 54))
    s += SL(Z_DAL, teplo(600, gor - 130, 220, 170, .40))

    zem = f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor}" fill="#473626"/>'
    zem += (f'<path d="M-40,1080 Q420,{gor+300:.0f} 820,{gor+70:.0f}'
            f' L1160,{gor+70:.0f} Q1540,{gor+300:.0f} 1960,1080 Z" fill="#59452e" {o(0)}/>')
    zem += _zemlya_faktura(gor + 90, 1060, 55, 16)
    zem += _listya(39, 30, gor + 80, 1060)
    zem += _trava(rnd, 13, gor + 70, 1050)
    zem += _inej(41, 38, gor + 70, 1060)
    s += SL(Z_SRED, zem)

    # сруб колодца крупно
    kx, ky, kw = 900, 1010, 470
    kol = ""
    for i in range(6):
        kol += (f'<rect x="{kx-kw/2:.0f}" y="{ky-346+i*58:.0f}" width="{kw:.0f}"'
                f' height="54" rx="12" fill="url(#brev)" {o(5)}/>'
                f'<ellipse cx="{kx-kw/2+10:.0f}" cy="{ky-319+i*58:.0f}" rx="18" ry="26"'
                f' fill="#5e442a" {o(3)}/>'
                f'<ellipse cx="{kx+kw/2-10:.0f}" cy="{ky-319+i*58:.0f}" rx="18" ry="26"'
                f' fill="#5e442a" {o(3)}/>')
    kol += (f'<rect x="{kx-kw/2-30:.0f}" y="{ky-378:.0f}" width="{kw+60:.0f}" height="36"'
            f' rx="10" fill="#5b4428" {o(5)}/>'
            f'<ellipse cx="{kx:.0f}" cy="{ky-378:.0f}" rx="{kw*.44:.0f}" ry="42"'
            f' fill="#160f0a" {o(4)}/>'
            f'<ellipse cx="{kx:.0f}" cy="{ky-368:.0f}" rx="{kw*.34:.0f}" ry="30"'
            f' fill="#3b5560" opacity=".55"/>')
    s += SL(Z_SRED, kol)

    # журавль: столб, коромысло, шест, ведро на цепи
    jx, jy = 1420, 1020
    kach = 4.0 * A.w(t, 2.6, .1)
    jur = (f'<rect x="{jx-28:.0f}" y="{jy-620:.0f}" width="56" height="620" rx="10"'
           f' fill="#3f2d1c" {o(6)}/>'
           f'<path d="M{jx-70:.0f},{jy-40:.0f} L{jx-28:.0f},{jy-180:.0f}'
           f' M{jx+70:.0f},{jy-40:.0f} L{jx+28:.0f},{jy-180:.0f}" stroke="#3f2d1c"'
           f' stroke-width="20" fill="none"/>'
           f'<g transform="rotate({kach:.1f} {jx:.0f} {jy-620:.0f})">'
           f'<rect x="{jx-500:.0f}" y="{jy-652:.0f}" width="860" height="38" rx="12"'
           f' fill="#4e3a24" {o(5)}/>'
           f'<rect x="{jx+300:.0f}" y="{jy-680:.0f}" width="110" height="100" rx="14"'
           f' fill="#2f261c" {o(4)}/>'
           f'<line x1="{jx-472:.0f}" y1="{jy-614:.0f}" x2="{jx-458:.0f}" y2="{jy-360:.0f}"'
           f' stroke="{ZHELEZ}" stroke-width="8"/>'
           f'<path d="M{jx-512:.0f},{jy-360:.0f} L{jx-404:.0f},{jy-360:.0f}'
           f' L{jx-420:.0f},{jy-240:.0f} L{jx-496:.0f},{jy-240:.0f} Z" fill="url(#zhel)"'
           f' {o(5)}/>'
           f'<path d="M{jx-512:.0f},{jy-360:.0f} Q{jx-458:.0f},{jy-428:.0f}'
           f' {jx-404:.0f},{jy-360:.0f}" fill="none" stroke="{ZHELEZ}" stroke-width="8"/>'
           f'</g>')
    s += SL(Z_SRED, jur)

    # ворона садится на журавль
    vp = A.ease(A.seg(t, .6, 1.3))
    vx = 1900 - 440 * vp
    vy = 150 + (jy - 690 - 150) * vp
    kryl = 1 - vp
    vor = (f'<ellipse cx="{vx:.0f}" cy="{vy:.0f}" rx="72" ry="46" fill="#14110f" {o(3)}/>'
           f'<circle cx="{vx-62:.0f}" cy="{vy-24:.0f}" r="34" fill="#14110f" {o(3)}/>'
           f'<path d="M{vx-92:.0f},{vy-26:.0f} L{vx-150:.0f},{vy-12:.0f}'
           f' L{vx-92:.0f},{vy-2:.0f} Z" fill="#6a6258" {o(2)}/>'
           f'<circle cx="{vx-72:.0f}" cy="{vy-32:.0f}" r="5" fill="#d8cfbd"/>'
           f'<path d="M{vx+14:.0f},{vy-12:.0f} Q{vx+40:.0f},{vy-78-64*kryl:.0f}'
           f' {vx+112:.0f},{vy-34-38*kryl:.0f} Q{vx+64:.0f},{vy+6:.0f} {vx+14:.0f},{vy+8:.0f} Z"'
           f' fill="#1d1916" {o(2)}/>'
           f'<path d="M{vx+52:.0f},{vy+20:.0f} L{vx+146:.0f},{vy+52:.0f}'
           f' L{vx+58:.0f},{vy+44:.0f} Z" fill="#14110f" {o(2)}/>')
    s += SL(Z_SRED, vor)

    # муж тянется и выпрямляется
    mx, my, mh = 600, 1030, 560
    tyan = A.ease(abs(A.w(t, 2.4, .0)))
    muzh = figura(mx, my, mh, t, col="#2f2a38", kant="#cfe4f5", ph=.2, shapka=True,
                  naklon=-22 * tyan)
    # ОБЕ РУКИ ОТ ПЛЕЧА И НАРУЖУ. Было: правый рукав брусок, левый под 20°
    # шёл поперёк груди (осмотр 15.11 — «обе руки брусками, одна поперёк
    # груди»). Монета переехала к подножию сруба СПРАВА от мужа, чтобы
    # тянулся он наружу, а не через собственный корпус.
    ruk, (rx2, ry2), (mpx, mpy) = _ruka(mx, my, mh, 1, mh * .58, 52 + 26 * tyan,
                                        t, "#2f2a38", "#cfe4f5", .1, 7)
    muzh += ruk
    ruk2, _, (mlx, mly) = _ruka(mx, my, mh, -1, mh * .42, 82, t,
                                "#2f2a38", "#cfe4f5", .5, 5)
    muzh += ruk2
    muzh += para_izo_rta(mx + 48, my - mh * .80, t, .2, 1.1, .5)
    s += SL(Z_SRED, muzh)
    s += SL(Z_SRED, _moneta_krupno(886, 1032, 72, t, .4))

    # жена: правой показывает на ворону, левой держит ведро — за рукав мужа
    # она тянулась НАСКВОЗЬ своей груди, этого в кадре быть не должно
    zx, zy, zh = 260, 1050, 540
    zhena = figura(zx, zy, zh, t, col="#5a2f33", kant="#cfe4f5", platok=True, ph=.5)
    ruk3, (ux, uy), (zpx, zpy) = _ruka(zx, zy, zh, 1, zh * .54, -56, t,
                                       "#5a2f33", "#cfe4f5", .3, 6)
    zhena += ruk3
    ruk4, (vdx, vdy), (zlx, zly) = _ruka(zx, zy, zh, -1, zh * .46, 74, t,
                                         "#5a2f33", "#cfe4f5", .7, 5)
    zhena += ruk4
    vkach = 6 * A.w(t, 1.4, .3)
    zhena += (f'<g transform="rotate({vkach:.1f} {vdx:.0f} {vdy:.0f})">'
              f'<path d="M{vdx-62:.0f},{vdy+14:.0f} L{vdx+62:.0f},{vdy+14:.0f}'
              f' L{vdx+46:.0f},{vdy+136:.0f} L{vdx-46:.0f},{vdy+136:.0f} Z"'
              f' fill="url(#zhel)" {o(5)}/>'
              f'<rect x="{vdx-66:.0f}" y="{vdy+8:.0f}" width="132" height="20" rx="8"'
              f' fill="{ZHELEZ}" {o(3)}/>'
              f'<ellipse cx="{vdx:.0f}" cy="{vdy+30:.0f}" rx="48" ry="14"'
              f' fill="#3b5560" opacity=".6"/>'
              f'<path d="M{vdx-44:.0f},{vdy+10:.0f} Q{vdx:.0f},{vdy-54:.0f}'
              f' {vdx+44:.0f},{vdy+10:.0f}" fill="none" stroke="{ZHELEZ}"'
              f' stroke-width="9"/></g>')
    zhena += para_izo_rta(zx + 42, zy - zh * .80, t, .6, 1.1, .5)
    s += SL(Z_SRED, zhena)
    s += SL(Z_SRED, ten(mx, my + 8, 120, 22, .45) + ten(zx, zy + 8, 110, 20, .45))

    s += SL(Z_SRED, _dvorovaya_utvar(60, 1060, 320, t, 43, ["vedro", "vedro"]))
    kor = (f'<path d="M1020,700 Q1180,632 1360,702" fill="none" stroke="url(#derev)"'
           f' stroke-width="28" stroke-linecap="round"/>'
           f'<rect x="1006" y="688" width="36" height="52" rx="8" fill="#4a3522" {o(3)}/>'
           f'<rect x="1346" y="690" width="36" height="52" rx="8" fill="#4a3522" {o(3)}/>')
    s += SL(Z_SRED, kor)
    s += SL(Z_SRED, _polenica(1600, 540, 340, 260, 45, 26))
    s += SL(Z_DAL, izba_snaruzhi(1700, 700, 520, t, True, True, 46))
    s += SL(Z_SRED, _dvorovaya_utvar(760, 640, 300, t, 48, ["vedro", "krynka"]))
    s += SL(Z_SRED, _polka_s_utvaryu(1040, 560, 330, t, 49, 3))
    gr = ""
    for i, (gx_, gy_) in enumerate(((330, 352), (470, 350), (1560, 358))):
        kl = 6 * A.w(t, 2.4, i * .3)
        gr += (f'<ellipse cx="{gx_:.0f}" cy="{gy_-30:.0f}" rx="34" ry="22"'
               f' fill="#1b1714" {o(2)}/>'
               f'<circle cx="{gx_-28:.0f}" cy="{gy_-42:.0f}" r="16" fill="#1b1714" {o(2)}/>'
               f'<path d="M{gx_-42:.0f},{gy_-44:.0f} L{gx_-70:.0f},{gy_-38:.0f}'
               f' L{gx_-42:.0f},{gy_-32:.0f} Z" fill="#6a6258" {o(2)}/>'
               f'<path d="M{gx_+6:.0f},{gy_-36:.0f} Q{gx_+22:.0f},{gy_-62-kl:.0f}'
               f' {gx_+52:.0f},{gy_-42:.0f} Q{gx_+28:.0f},{gy_-22:.0f}'
               f' {gx_+6:.0f},{gy_-22:.0f} Z" fill="#241f1b" {o(2)}/>')
    s += SL(Z_SRED, gr)
    s += SL(Z_PERED, _vetka_pered(-40, 70, 760, 26, t, 47, "#241c16", 7))
    s += SL(Z_LETIT, mokryy_sneg(t, 18, 13, .45, .8))
    s += ramka_pp("oba")
    s += vinetka(.42)
    return s


def dva_venika_u_krylca(t):
    """Крыльцо избы и два веника НА ПОЛ-КАДРА: слева чужой, растрёпанный, с
    красной тряпицей, справа новенький жёлтый с биркой. Хозяйка тянется к
    обоим, отдёргивает руку и берёт из сеней свой, старый и тёмный."""
    rnd = random.Random(106)
    s = nebo("sumer", t, True, 23)
    s += oblaka(t, 120, 4, 15, .36)
    s += SL(Z_DAL, _derevnya_ryad(520, t, 51, ((120, 300), (1820, 280))))

    # стена избы за крыльцом
    s += SL(Z_DAL, brevna(240, 0, 1460, 700, 92)
            + f'<rect x="240" y="0" width="1460" height="700" fill="none" {o(10)}/>')
    s += SL(Z_DAL, okno_izby(1300, 120, 320, 270, t, svet=True)
            + teplo(1460, 256, 280, 230, .44))
    s += SL(Z_DAL, dver(420, 110, 300, 520, .22, "url(#derev)", True, False))
    s += SL(Z_DAL, podkova(570, 70, 1.6, t))
    s += SL(Z_DAL, _polka_s_utvaryu(800, 250, 440, t, 77, 3))

    zem = f'<rect x="0" y="760" width="{W}" height="320" fill="#473626"/>'
    zem += _zemlya_faktura(820, 1060, 61, 14)
    zem += _listya(55, 26, 820, 1060)
    zem += _inej(57, 32, 820, 1060)
    s += SL(Z_SRED, zem)
    s += SL(Z_SRED, _kryl_co(240, 700, 1200, 190, t, 3, True, False))

    def venik(vx, vy, h2, col, tryap, birka, rastr, ph, s_=1.0):
        kach = 3.4 * A.w(t, 2.2, ph)
        g = f'<g transform="rotate({kach:.1f} {vx:.0f} {vy:.0f})">'
        rr = random.Random(int(vx))
        n = 23
        for i in range(n):
            p = (i / (n - 1.0)) - .5
            raz = (1.0 + rastr * rr.uniform(0, 1.6))
            ex = vx + p * 180 * s_ * raz
            ey = vy - h2 + rr.uniform(-30, 20) * raz
            g += (f'<path d="M{vx+p*34*s_:.0f},{vy-h2*.40:.0f}'
                  f' Q{vx+p*118*s_:.0f},{vy-h2*.76:.0f} {ex:.0f},{ey:.0f}"'
                  f' fill="none" stroke="{col}" stroke-width="{9*s_:.0f}"'
                  f' stroke-linecap="round" opacity=".92"/>')
        g += (f'<rect x="{vx-28*s_:.0f}" y="{vy-h2*.42:.0f}" width="{56*s_:.0f}"'
              f' height="{h2*.46:.0f}" rx="18" fill="url(#derev)" {o(5)}/>'
              f'<rect x="{vx-44*s_:.0f}" y="{vy-h2*.50:.0f}" width="{88*s_:.0f}"'
              f' height="{34*s_:.0f}" rx="12" fill="{tryap}" {o(4)}/>'
              f'<rect x="{vx-40*s_:.0f}" y="{vy-h2*.28:.0f}" width="{80*s_:.0f}"'
              f' height="{24*s_:.0f}" rx="10" fill="#8a6a3c" {o(3)}/>')
        if tryap == "#b8352c":
            tr = 8 * A.w(t, 1.7, ph + .5)
            g += (f'<path d="M{vx+40*s_:.0f},{vy-h2*.48:.0f}'
                  f' Q{vx+86*s_+tr:.0f},{vy-h2*.42:.0f} {vx+70*s_:.0f},{vy-h2*.30:.0f} Z"'
                  f' fill="#b8352c" {o(3)}/>')
        if birka:
            bk = 4 * A.w(t, 1.8, ph + .3)
            g += (f'<g transform="rotate({bk:.1f} {vx+34*s_:.0f} {vy-h2*.28:.0f})">'
                  f'<line x1="{vx+34*s_:.0f}" y1="{vy-h2*.28:.0f}"'
                  f' x2="{vx+52*s_:.0f}" y2="{vy-h2*.14:.0f}" stroke="#cbbb98"'
                  f' stroke-width="4"/>'
                  f'<rect x="{vx+34*s_:.0f}" y="{vy-h2*.14:.0f}" width="{52*s_:.0f}"'
                  f' height="{68*s_:.0f}" rx="8" fill="#efe4c8" {o(4)}/>'
                  f'<path d="M{vx+44*s_:.0f},{vy-h2*.14+30*s_:.0f}'
                  f' Q{vx+58*s_:.0f},{vy-h2*.14+20*s_:.0f}'
                  f' {vx+74*s_:.0f},{vy-h2*.14+30*s_:.0f}" fill="none" stroke="#9a8a68"'
                  f' stroke-width="4"/></g>')
        g += "</g>"
        return g

    s += SL(Z_SRED, venik(560, 1000, 620, "#8a7246", "#b8352c", False, 1.0, .0, 1.25))
    s += SL(Z_SRED, venik(1080, 1000, 640, "url(#solom)", "#c8a24a", True, .0, .4, 1.25))
    s += SL(Z_SRED, f'<rect x="250" y="940" width="380" height="64" rx="10" fill="{RUSH}"'
                    f' {o(4)}/>'
                    f'<path d="M272,956 L612,956 M272,984 L612,984" stroke="{KRAS}"'
                    f' stroke-width="8" opacity=".7"/>')
    for i, lx in enumerate((760, 880)):
        s += SL(Z_SRED, f'<path d="M{lx:.0f},1030 Q{lx+48:.0f},974 {lx+96:.0f},1030'
                        f' Q{lx+48:.0f},1060 {lx:.0f},1030 Z" fill="url(#solom)" {o(4)}/>'
                        f'<path d="M{lx+16:.0f},1016 L{lx+80:.0f},1016" stroke="#8a6a3c"'
                        f' stroke-width="5"/>')
    s += SL(Z_SRED, _dvorovaya_utvar(1240, 1060, 330, t, 59, ["kadka", "vedro"]))
    s += SL(Z_SRED, _kucha_listev(1760, 1050, 300, 67, 96)
            + _luzha(960, 1058, 210, t, .2))
    s += SL(Z_SRED, _polenica(20, 760, 240, 220, 63, 25))

    # ФИГУРА ЦЕЛИКОМ В КАДРЕ И РУКИ НАРУЖУ. Было: хозяйка стояла у самого
    # правого края, указующая рука шла от ПРАВОГО плеча налево — прямым
    # бруском через подбородок и голову, а на дальней цели кисть уезжала за
    # холст. Теперь показывает ЛЕВАЯ рука (цели все слева), веник держит
    # правая, и обе уложены внутрь кадра (осмотр 15.11).
    fx, fy, fh = 1468, 1016, 620
    faza = (t * .55) % 1.0
    cel = 560 if faza < .34 else (1080 if faza < .68 else 300)
    otd = .5 + .5 * math.sin(faza * 3 * 2 * math.pi)
    fig = figura(fx, fy, fh, t, col="#4a3b2a", kant="#ffd98a", platok=True, ph=.2)
    lpx, lpy = _plecho(fx, fy, fh, -1)
    ang = math.degrees(math.atan2(820 - lpy, lpx - cel))
    ruk, _, _ = _ruka(fx, fy, fh, -1, fh * (.30 + .20 * otd), ang, t,
                      "#4a3b2a", "#ffd98a", .1, 6)
    fig += ruk
    ruk2, (bx, by), (rpx, rpy) = _ruka(fx, fy, fh, 1, fh * .34, 64, t,
                                       "#4a3b2a", "#ffd98a", .3, 5)
    fig += ruk2
    # веник держится ЗА ЧЕРЕНОК, прутья смотрят вниз-вперёд
    fig += (f'<g transform="rotate(168 {bx:.0f} {by:.0f})">'
            + venik(bx, by, 300, "#4b3f28", "#5a4a2e", False, .25, .7, .8) + "</g>")
    fig += para_izo_rta(fx - 48, fy - fh * .80, t, .4, 1.1, .5)
    s += SL(Z_SRED, fig + ten(fx, fy + 8, 140, 24, .45))
    s += SL(Z_PERED, _stolb_pered(-6, 100, "#1d1611", 0, H))
    s += SL(Z_LETIT, mokryy_sneg(t, 16, 17, .4, .7))
    s += ramka_pp("pravo")
    s += vinetka(.42)
    return s


def tri_otlozhennyh_dela(t):
    """Горница: стол с фартуком, подносом и караваем, дед в жилетке за столом
    отодвигает дело за делом. Ходики, окно с занавеской, полки с утварью."""
    rnd = random.Random(107)
    pol = 740
    s = _stena_gornicy(t, 5, True, pol)
    s += SL(Z_DAL, f'<rect x="0" y="86" width="{W}" height="30" fill="#3b2a1a" opacity=".8"/>'
                   f'<rect x="880" y="0" width="34" height="{pol:.0f}" fill="#4e3220"'
                   f' opacity=".75"/>')
    s += SL(Z_DAL, okno_izby(1320, 190, 360, 300, t, svet=False, moroz=.5))
    s += SL(Z_DAL, zanaveska(1320, 180, 170, 130, TKAN, t, 1)
            + zanaveska(1680, 180, 170, 130, TKAN, t, -1))
    s += SL(Z_DAL, hodiki(300, 180, t, 1.7))
    s += SL(Z_DAL, _polka_s_utvaryu(520, 300, 560, t, 11, 4))
    s += SL(Z_DAL, utvar_izby(1140, 330, 420, t, 7))
    s += SL(Z_SRED, lampa(960, 230, t, 1.5, True) + teplo(960, 420, 420, 320, .44))
    s += SL(Z_SRED, _polka_s_utvaryu(1180, 560, 560, t, 379, 4))
    s += SL(Z_SRED, _dvorovaya_utvar(980, 1070, 520, t, 381,
                                     ["kadka", "vedro", "korzina"]))
    s += SL(Z_SRED, f'<rect x="620" y="620" width="300" height="140" rx="10"'
                    f' fill="url(#derev)" {o(6)}/>'
                    f'<path d="M620,620 Q770,566 920,620 Z" fill="#5b4428" {o(5)}/>'
                    f'<rect x="610" y="658" width="320" height="18" rx="7"'
                    f' fill="{ZHELEZ}" {o(3)}/>')

    s += SL(Z_SRED, mebel_hlam(180, 900, 420, t, 13))
    s += SL(Z_SRED, lavka(1340, 930, 480))
    s += SL(Z_SRED, _kot_zhivoy(1500, 1040, t, 1.4, "#4a423c", .2, True, True))

    # стол во всю ширину кадра
    sx, sy, sw = 960, 880, 1320
    stl = (f'<rect x="{sx-sw/2:.0f}" y="{sy:.0f}" width="{sw:.0f}" height="46" rx="10"'
           f' fill="url(#dosk)" {o(6)}/>'
           f'<rect x="{sx-sw/2:.0f}" y="{sy+46:.0f}" width="{sw:.0f}" height="20"'
           f' fill="#3a2a1a" opacity=".8"/>')
    for px in (sx - sw / 2 + 60, sx + sw / 2 - 100):
        stl += (f'<rect x="{px:.0f}" y="{sy+66:.0f}" width="44" height="180" rx="8"'
                f' fill="#4a3522" {o(4)}/>')
    s += SL(Z_SRED, stl)

    sd1 = A.ease(A.seg(t, .5, 1.0))
    sd2 = A.ease(A.seg(t, 1.9, 1.0))
    sd3 = A.ease(A.seg(t, 3.3, 1.0))

    # 1. рабочий фартук с рукавицами
    f1x = 470 - 260 * sd1
    far = (f'<path d="M{f1x-90:.0f},{sy-24:.0f} L{f1x-60:.0f},{sy-186:.0f}'
           f' L{f1x+60:.0f},{sy-186:.0f} L{f1x+90:.0f},{sy-24:.0f} Z"'
           f' fill="#6b5a3c" opacity="{1-sd1*.5:.2f}" {o(5)}/>'
           f'<line x1="{f1x-60:.0f}" y1="{sy-186:.0f}" x2="{f1x-150:.0f}" y2="{sy-120:.0f}"'
           f' stroke="#6b5a3c" stroke-width="12" opacity="{1-sd1*.5:.2f}"/>'
           f'<line x1="{f1x+60:.0f}" y1="{sy-186:.0f}" x2="{f1x+150:.0f}" y2="{sy-120:.0f}"'
           f' stroke="#6b5a3c" stroke-width="12" opacity="{1-sd1*.5:.2f}"/>'
           f'<rect x="{f1x-56:.0f}" y="{sy-110:.0f}" width="112" height="60" rx="8"'
           f' fill="#584a30" opacity="{1-sd1*.5:.2f}" {o(3)}/>')
    for i, gx in enumerate((f1x - 120, f1x + 120)):
        far += (f'<path d="M{gx-36:.0f},{sy-20:.0f} L{gx-30:.0f},{sy-96:.0f}'
                f' Q{gx:.0f},{sy-124:.0f} {gx+30:.0f},{sy-96:.0f} L{gx+36:.0f},{sy-20:.0f} Z"'
                f' fill="#7a6342" opacity="{1-sd1*.5:.2f}" {o(4)}/>'
                f'<path d="M{gx+30:.0f},{sy-86:.0f} L{gx+58:.0f},{sy-66:.0f}'
                f' L{gx+40:.0f},{sy-44:.0f} Z" fill="#7a6342"'
                f' opacity="{1-sd1*.5:.2f}" {o(3)}/>')
    s += SL(Z_SRED, far)

    # 2. поднос с рушником и караваем
    f2x = 960 + 300 * sd2
    pod = (f'<ellipse cx="{f2x:.0f}" cy="{sy-14:.0f}" rx="210" ry="48" fill="url(#zhel)"'
           f' opacity="{1-sd2*.5:.2f}" {o(5)}/>'
           f'<path d="M{f2x-250:.0f},{sy-34:.0f} Q{f2x:.0f},{sy-86:.0f}'
           f' {f2x+250:.0f},{sy-34:.0f} L{f2x+250:.0f},{sy+4:.0f}'
           f' Q{f2x:.0f},{sy-44:.0f} {f2x-250:.0f},{sy+4:.0f} Z" fill="{RUSH}"'
           f' opacity="{1-sd2*.5:.2f}" {o(4)}/>')
    for i in range(6):
        ux = f2x - 220 + i * 88
        pod += (f'<path d="M{ux:.0f},{sy-30:.0f} L{ux+18:.0f},{sy-50:.0f}'
                f' L{ux+36:.0f},{sy-30:.0f} Z" fill="{KRAS}" opacity="{(1-sd2*.5)*.8:.2f}"/>')
    pod += karavay(f2x, sy - 50, 1.6, False)
    s += SL(Z_SRED, pod)

    # 3. две руки над столом, готовые к рукопожатию
    rx_, ry_ = 1310, sy - 110
    ruk1, _ = rukav(rx_ + 230, ry_ + 60, 210, 196, t, "#3a3142", "#cfe4f5", .2, 4, True)
    ruk3 = ruk1
    s += SL(Z_SRED, ruk3 + f'<ellipse cx="{rx_+30:.0f}" cy="{ry_+10:.0f}" rx="56" ry="34"'
                           f' fill="#3a3142" opacity="{1-sd3*.75:.2f}" {o(4)}/>')

    fx, fy, fh = 700, 846, 470
    ded = figura(fx, fy, fh, t, col="#3c3326", kant="#ffd98a", ph=.2, boroda=True)
    # Показывает на дела ПРАВАЯ рука (дела все справа от деда), левая просто
    # висит наружу. Было: левый рукав под -10° шёл прямой палкой через бороду
    # и голову на 163 px за ось тела (осмотр 15.11).
    ang = -4 - 26 * (sd1 + sd2 + sd3) / 3.0
    ruk, _, (dpx, dpy) = _ruka(fx, fy, fh, 1, fh * .52, ang, t,
                               "#3c3326", "#ffd98a", .1, 5)
    ded += ruk
    ruk2, _, (dlx, dly) = _ruka(fx, fy, fh, -1, fh * .46, 70 - 18 * sd3, t,
                                "#3c3326", "#ffd98a", .5, 4)
    ded += ruk2
    s += SL(Z_SRED, ded)
    s += SL(Z_SRED, krynka(240, sy - 10, 1.3) + monety(1700, sy - 20, t, 4, 3, 1.2))
    s += SL(Z_SRED, f'<path d="M460,1004 L1460,1004 L1600,1076 L320,1076 Z"'
                    f' fill="{RUSH}" {o(5)}/>'
                    f'<path d="M486,1030 L1472,1030 M466,1056 L1540,1056"'
                    f' stroke="{KRAS}" stroke-width="9" opacity=".6"/>')
    s += SL(Z_SRED, _dvorovaya_utvar(560, 1070, 560, t, 375,
                                     ["korzina", "kadka", "korob"]))
    s += SL(Z_DAL, _polka_s_utvaryu(540, 520, 520, t, 81, 4))
    s += SL(Z_DAL, utvar_izby(180, 420, 300, t, 9))
    s += SL(Z_SRED, _dvorovaya_utvar(100, 1040, 420, t, 83, ["kadka", "korob", "korzina"]))
    s += SL(Z_SRED, lavka(120, 980, 420))
    uhv = ""
    for i, ux in enumerate((1760, 1820, 1876)):
        uhv += (f'<rect x="{ux:.0f}" y="{520+i*18:.0f}" width="16" height="420" rx="7"'
                f' fill="url(#derev)" {o(3)}/>')
    uhv += (f'<path d="M1748,520 Q1768,476 1792,520" fill="none" stroke="{ZHELEZ}"'
            f' stroke-width="12"/>'
            f'<rect x="1806" y="500" width="34" height="44" rx="8" fill="{CHUGUN}" {o(3)}/>')
    s += SL(Z_SRED, uhv)
    s += SL(Z_PERED, _stolb_pered(1840, 120, "#140f0b", 0, H))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def torgovyy_gorod_na_reke(t):
    """Старинный деревянный город над рекой: бревенчатые стены с башнями,
    пристань с ладьями, торг с навесами, дымы над крышами. В проёме ворот —
    настоящая река. У ворот один стоит маленький мальчик."""
    rnd = random.Random(108)
    s = nebo("den", t, False, 37)
    s += oblaka(t, 130, 6, 19, .5)

    px_, py_, pw_, ph_ = 1110, 258, 770, 400
    put = kontur_proema(px_, py_, pw_, ph_, "arka")
    s += SL(Z_DAL, _vid_za_proemom(put, t, "reka", 9)
            + mesto_stoka(px_, py_, pw_, ph_, "arka")
            + f'<path d="{put}" fill="none" stroke="#2a1d12" stroke-width="18"/>')

    sten = ""
    for bx, bw in ((-20, 900), (1880, 80)):
        sten += (f'<rect x="{bx:.0f}" y="250" width="{bw:.0f}" height="510" rx="6"'
                 f' fill="url(#brev)" {o(6)}/>')
        for i in range(9):
            sten += (f'<rect x="{bx:.0f}" y="{256+i*56:.0f}" width="{bw:.0f}" height="48"'
                     f' rx="8" fill="url(#brev)" {o(3)}/>')
        for i in range(int(bw // 76)):
            zx = bx + 8 + i * 76
            sten += (f'<rect x="{zx:.0f}" y="196" width="58" height="58" rx="6"'
                     f' fill="#5b4428" {o(4)}/>')
        for i in range(int(bw // 160)):
            zx = bx + 40 + i * 160
            sten += (f'<rect x="{zx:.0f}" y="330" width="34" height="76" rx="6"'
                     f' fill="#1a120c" {o(3)}/>')
    for bx in (280, 1000):
        sten += (f'<rect x="{bx-130:.0f}" y="120" width="260" height="640" rx="8"'
                 f' fill="url(#brev)" {o(6)}/>')
        for i in range(10):
            sten += (f'<rect x="{bx-130:.0f}" y="{126+i*62:.0f}" width="260" height="54"'
                     f' rx="8" fill="url(#brev)" {o(3)}/>')
        sten += (f'<path d="M{bx-190:.0f},120 L{bx:.0f},-40 L{bx+190:.0f},120 Z"'
                 f' fill="#4a3a28" {o(5)}/>'
                 f'<rect x="{bx-200:.0f}" y="112" width="400" height="24" rx="8"'
                 f' fill="#5c4830" {o(4)}/>'
                 f'<rect x="{bx-66:.0f}" y="220" width="58" height="92" rx="8"'
                 f' fill="#1a120c" {o(4)}/>'
                 f'<rect x="{bx+14:.0f}" y="220" width="58" height="92" rx="8"'
                 f' fill="#1a120c" {o(4)}/>'
                 f'<rect x="{bx-66:.0f}" y="430" width="58" height="92" rx="8"'
                 f' fill="#1a120c" {o(4)}/>'
                 f'<rect x="{bx+14:.0f}" y="430" width="58" height="92" rx="8"'
                 f' fill="#1a120c" {o(4)}/>')
    # надвратный сруб и косяки проёма вместо створок
    sten += (f'<rect x="{px_-70:.0f}" y="{py_-120:.0f}" width="{pw_+140:.0f}"'
             f' height="140" rx="10" fill="url(#brev)" {o(6)}/>')
    for i in range(2):
        sten += (f'<rect x="{px_-70:.0f}" y="{py_-114+i*62:.0f}" width="{pw_+140:.0f}"'
                 f' height="54" rx="9" fill="url(#brev)" {o(3)}/>')
    for i in range(int((pw_ + 140) // 78)):
        sten += (f'<rect x="{px_-62+i*78:.0f}" y="{py_-178:.0f}" width="56" height="58"'
                 f' rx="6" fill="#5b4428" {o(4)}/>')
    sten += (f'<rect x="{px_-74:.0f}" y="{py_+10:.0f}" width="74"'
             f' height="{ph_+120:.0f}" rx="8" fill="#3b2a1a" {o(6)}/>'
             f'<rect x="{px_+pw_:.0f}" y="{py_+10:.0f}" width="74"'
             f' height="{ph_+120:.0f}" rx="8" fill="#3b2a1a" {o(6)}/>'
             f'<rect x="{px_-74:.0f}" y="{py_+ph_+90:.0f}" width="{pw_+148:.0f}"'
             f' height="34" rx="10" fill="#4e3a24" {o(5)}/>')
    for i in range(5):
        sten += (f'<circle cx="{px_-38:.0f}" cy="{py_+70+i*86:.0f}" r="14"'
                 f' fill="{ZHELEZ}" {o(3)}/>'
                 f'<circle cx="{px_+pw_+36:.0f}" cy="{py_+70+i*86:.0f}" r="14"'
                 f' fill="{ZHELEZ}" {o(3)}/>')
    s += SL(Z_SRED, sten)

    for i, dx in enumerate((280, 640, 1000, 1880)):
        s += SL(Z_SRED, dym(dx, 90 + (i % 2) * 50, t, 5, .24, 300, .34, "#d3dae2", .9))

    zem = f'<rect x="0" y="700" width="{W}" height="380" fill="#4e3f2c"/>'
    zem += f'<rect x="0" y="700" width="{W}" height="26" fill="#6a553a" opacity=".8"/>'
    zem += _zemlya_faktura(760, 1060, 57, 18)
    zem += _listya(61, 28, 740, 1060)
    s += SL(Z_SRED, zem)
    # торговый настил через всю середину: доски, бочки, короба, мешки
    nast = (f'<rect x="230" y="748" width="1460" height="54" rx="12"'
            f' fill="url(#dosk)" {o(7)}/>'
            f'<rect x="230" y="802" width="1460" height="26" fill="#3a2a1a"'
            f' opacity=".85"/>')
    for i in range(6):
        nast += (f'<rect x="{300+i*260:.0f}" y="828" width="48" height="160" rx="9"'
                 f' fill="#4a3522" {o(4)}/>')
    s += SL(Z_SRED, nast)
    s += SL(Z_SRED, _dvorovaya_utvar(300, 744, 560, t, 331,
                                     ["kadka", "korzina", "meshok"]))
    s += SL(Z_SRED, _dvorovaya_utvar(560, 744, 500, t, 333,
                                     ["korob", "kadka", "vedro"]))
    s += SL(Z_SRED, _polenica(260, 836, 300, 200, 335, 25))
    s += SL(Z_SRED, _polenica(1340, 836, 300, 200, 337, 25))

    pr = f'<rect x="-20" y="870" width="660" height="36" rx="8" fill="url(#derev)" {o(5)}/>'
    for i in range(6):
        pr += (f'<rect x="{20+i*118:.0f}" y="906" width="32" height="150" rx="6"'
               f' fill="#4a3522" {o(4)}/>')
    for i, (lx, ly, lw) in enumerate(((100, 1000, 460), (420, 1060, 400))):
        kach = 5 * A.w(t, 3.0 + i, i * .4)
        pr += (f'<g transform="rotate({kach:.1f} {lx+lw/2:.0f} {ly:.0f})">'
               f'<path d="M{lx:.0f},{ly:.0f} Q{lx+lw/2:.0f},{ly+78:.0f} {lx+lw:.0f},{ly:.0f}'
               f' L{lx+lw-34:.0f},{ly-50:.0f} L{lx+34:.0f},{ly-50:.0f} Z"'
               f' fill="url(#derev)" {o(5)}/>'
               f'<path d="M{lx:.0f},{ly:.0f} L{lx-38:.0f},{ly-92:.0f}" stroke="#4a3522"'
               f' stroke-width="18" fill="none"/>'
               f'<path d="M{lx+lw:.0f},{ly:.0f} L{lx+lw+38:.0f},{ly-92:.0f}"'
               f' stroke="#4a3522" stroke-width="18" fill="none"/>'
               f'<rect x="{lx+lw/2-12:.0f}" y="{ly-280:.0f}" width="24" height="236"'
               f' fill="#4a3522" {o(3)}/>'
               f'<path d="M{lx+lw/2:.0f},{ly-270:.0f} L{lx+lw/2+120:.0f},{ly-200:.0f}'
               f' L{lx+lw/2:.0f},{ly-140:.0f} Z" fill="{KREM}" opacity=".5" {o(3)}/></g>')
    s += SL(Z_SRED, pr)

    trg = ""
    for i in range(2):
        tx = 420 + i * 300
        trg += (f'<path d="M{tx-124:.0f},820 L{tx:.0f},744 L{tx+124:.0f},820 Z"'
                f' fill="#8a6a3c" {o(5)}/>'
                f'<rect x="{tx-118:.0f}" y="816" width="236" height="22" rx="6"'
                f' fill="#5b4428" {o(4)}/>'
                f'<rect x="{tx-104:.0f}" y="838" width="28" height="170" rx="6"'
                f' fill="#4a3522" {o(3)}/>'
                f'<rect x="{tx+76:.0f}" y="838" width="28" height="170" rx="6"'
                f' fill="#4a3522" {o(3)}/>'
                f'<rect x="{tx-118:.0f}" y="948" width="236" height="32" rx="7"'
                f' fill="url(#dosk)" {o(4)}/>')
    s += SL(Z_SRED, trg)
    s += SL(Z_SRED, _dvorovaya_utvar(360, 1058, 760, t, 63))
    s += SL(Z_SRED, _polenica(40, 640, 280, 220, 65, 24))
    s += SL(Z_SRED, _polka_s_utvaryu(430, 950, 440, t, 67, 4))
    s += SL(Z_SRED, _dvorovaya_utvar(200, 904, 480, t, 407, ["korob", "meshok"]))
    s += SL(Z_SRED, _polka_s_utvaryu(620, 620, 420, t, 351, 4))
    s += SL(Z_SRED, _polka_s_utvaryu(560, 700, 420, t, 383, 4))
    s += SL(Z_SRED, _dvorovaya_utvar(620, 1062, 620, t, 385,
                                     ["kadka", "korob", "meshok"]))
    s += SL(Z_SRED, _polenica(900, 820, 260, 180, 387, 24))
    s += SL(Z_SRED, _kadushki_i_grabli(420, 1070, t, 157))
    s += SL(Z_SRED, _lavka_krupno(640, 1076, 420, t, 150))
    seti = ""
    for i in range(3):
        sx_ = 70 + i * 190
        seti += (f'<path d="M{sx_:.0f},880 L{sx_+150:.0f},880 L{sx_+120:.0f},1020'
                 f' L{sx_+30:.0f},1020 Z" fill="#6a6250" opacity=".55" {o(3)}/>')
        for k in range(5):
            seti += (f'<line x1="{sx_+12+k*32:.0f}" y1="884" x2="{sx_+30+k*22:.0f}"'
                     f' y2="1016" stroke="#8a8068" stroke-width="3" opacity=".7"/>'
                     f'<line x1="{sx_+4:.0f}" y1="{896+k*26:.0f}" x2="{sx_+146:.0f}"'
                     f' y2="{896+k*26:.0f}" stroke="#8a8068" stroke-width="3"'
                     f' opacity=".7"/>')
    s += SL(Z_SRED, seti)
    ptic = ""
    for i in range(7):
        bx_ = ((t * 26 + i * 290) % 2300) - 180
        by_ = 110 + (i % 3) * 54 + 12 * A.w(t, 2.0, i * .3)
        ptic += ptica(bx_, by_, t, .9, "#4a4a52", i * .2)
    s += SL(Z_DAL, ptic)
    s += SL(Z_SRED, teplo(640, 860, 280, 200, .34))

    fx, fy, fh = 1300, 1012, 340
    mal = figura(fx, fy, fh, t, col="#8e8068", kant="#cfe4f5", ph=.3)
    r1, _, (mpx, mpy) = _ruka_ekr(fx, fy, fh, 1, fh * .44, 84, t, "#8e8068", "#cfe4f5", .2, 4)
    r2, _, (mpx2, mpy2) = _ruka_ekr(fx, fy, fh, -1, fh * .44, 96, t, "#8e8068", "#cfe4f5", .6, 4)
    mal += r1 + r2
    mal += para_izo_rta(fx + 30, fy - fh * .80, t, .1, .9, .5)
    s += SL(Z_SRED, mal + ten(fx, fy + 6, 78, 15, .45))
    s += SL(Z_PERED, _stolb_pered(1870, 110, "#1d1611", 0, H))
    s += SL(Z_LETIT, sneg_letit(t, 16, 21, .4, .7))
    s += ramka_pp("oba")
    s += vinetka(.42)
    return s


def torg_i_malchik_ivan(t):
    """Торговый ряд: бочки с мёдом, связки мехов, весы с гирями, горшки,
    калачи на шесте. Купец кладёт гирю, покупательница с корзиной, мальчик
    прижимает берестяную грамотку."""
    rnd = random.Random(109)
    s = nebo("den", t, False, 41)
    s += oblaka(t, 140, 5, 23, .45)
    s += SL(Z_DAL, _derevnya_ryad(480, t, 67, ((170, 330), (1760, 310))))

    # навес торгового ряда во всю ширину
    nav = (f'<path d="M190,430 L960,248 L1730,430 Z" fill="#8a6a3c" {o(6)}/>'
           f'<rect x="200" y="416" width="1520" height="28" rx="9" fill="#5b4428" {o(5)}/>')
    for i in range(6):
        nx = 60 + i * 370
        nav += (f'<rect x="{nx:.0f}" y="436" width="34" height="380" rx="8"'
                f' fill="#4a3522" {o(4)}/>')
    s += SL(Z_DAL, nav)

    zem = f'<rect x="0" y="790" width="{W}" height="290" fill="#4e3f2c"/>'
    zem += _listya(69, 22, 820, 1060)
    zem += _inej(71, 26, 830, 1060)
    s += SL(Z_SRED, zem)

    # прилавок
    pr = (f'<rect x="210" y="818" width="1480" height="58" rx="12"'
          f' fill="url(#dosk)" {o(7)}/>'
          f'<rect x="210" y="876" width="1480" height="26" fill="#3a2a1a" opacity=".85"/>')
    for px in (260, 740, 1180, 1600):
        pr += (f'<rect x="{px:.0f}" y="898" width="46" height="160" rx="8" fill="#4a3522"'
               f' {o(4)}/>')
    s += SL(Z_SRED, pr)

    # бочки с мёдом слева
    boch = ""
    for i, (bx, by, bs) in enumerate(((160, 820, 1.0), (330, 824, .84), (250, 1050, 1.1))):
        bw, bh = 170 * bs, 200 * bs
        boch += (f'<path d="M{bx-bw/2:.0f},{by-bh:.0f} Q{bx-bw*.68:.0f},{by-bh*.5:.0f}'
                 f' {bx-bw/2:.0f},{by:.0f} L{bx+bw/2:.0f},{by:.0f}'
                 f' Q{bx+bw*.68:.0f},{by-bh*.5:.0f} {bx+bw/2:.0f},{by-bh:.0f} Z"'
                 f' fill="url(#derev)" {o(5)}/>'
                 f'<rect x="{bx-bw*.62:.0f}" y="{by-bh*.78:.0f}" width="{bw*1.24:.0f}"'
                 f' height="18" rx="6" fill="{ZHELEZ}" {o(3)}/>'
                 f'<rect x="{bx-bw*.62:.0f}" y="{by-bh*.30:.0f}" width="{bw*1.24:.0f}"'
                 f' height="18" rx="6" fill="{ZHELEZ}" {o(3)}/>'
                 f'<ellipse cx="{bx:.0f}" cy="{by-bh:.0f}" rx="{bw/2:.0f}" ry="{bw*.17:.0f}"'
                 f' fill="url(#med)" {o(4)}/>')
    s += SL(Z_SRED, boch)

    # связки мехов на жерди
    meh = (f'<rect x="420" y="470" width="520" height="20" rx="7" fill="#4a3522" {o(4)}/>')
    for i in range(5):
        mx = 460 + i * 106
        kach = 3.0 * A.w(t, 2.6 + i * .2, i * .3)
        meh += (f'<g transform="rotate({kach:.1f} {mx:.0f} 486)">'
                f'<path d="M{mx-44:.0f},490 Q{mx-56:.0f},620 {mx-20:.0f},720'
                f' Q{mx:.0f},760 {mx+20:.0f},720 Q{mx+56:.0f},620 {mx+44:.0f},490 Z"'
                f' fill="{["#6b4a2c","#8a6a46","#4e3a28","#7a5a3a","#5e4630"][i]}" {o(4)}/>'
                f'<ellipse cx="{mx:.0f}" cy="{492:.0f}" rx="44" ry="18" fill="#3a2a1a" {o(3)}/>'
                f'<path d="M{mx-18:.0f},700 L{mx:.0f},762 L{mx+18:.0f},700 Z"'
                f' fill="#2e2118" {o(2)}/></g>')
    s += SL(Z_SRED, meh)

    # весы с гирями
    vx_, vy_ = 1180, 560
    gir = A.ease(A.seg(t, .4, 1.0))
    nak = 11 * gir
    ves = (f'<rect x="{vx_-12:.0f}" y="{vy_:.0f}" width="24" height="300" rx="8"'
           f' fill="{ZHELEZ}" {o(4)}/>'
           f'<g transform="rotate({nak:.1f} {vx_:.0f} {vy_:.0f})">'
           f'<rect x="{vx_-210:.0f}" y="{vy_-12:.0f}" width="420" height="20" rx="8"'
           f' fill="{ZHELEZ}" {o(4)}/>'
           f'<line x1="{vx_-196:.0f}" y1="{vy_:.0f}" x2="{vx_-196:.0f}" y2="{vy_+96:.0f}"'
           f' stroke="{ZHELEZ}" stroke-width="5"/>'
           f'<line x1="{vx_+196:.0f}" y1="{vy_:.0f}" x2="{vx_+196:.0f}" y2="{vy_+96:.0f}"'
           f' stroke="{ZHELEZ}" stroke-width="5"/>'
           f'<path d="M{vx_-276:.0f},{vy_+96:.0f} Q{vx_-196:.0f},{vy_+170:.0f}'
           f' {vx_-116:.0f},{vy_+96:.0f} Z" fill="url(#zhel)" {o(4)}/>'
           f'<path d="M{vx_+116:.0f},{vy_+96:.0f} Q{vx_+196:.0f},{vy_+170:.0f}'
           f' {vx_+276:.0f},{vy_+96:.0f} Z" fill="url(#zhel)" {o(4)}/>'
           f'<path d="M{vx_-224:.0f},{vy_+94:.0f} L{vx_-208:.0f},{vy_+28:.0f}'
           f' L{vx_-184:.0f},{vy_+28:.0f} L{vx_-168:.0f},{vy_+94:.0f} Z"'
           f' fill="{CHUGUN}" opacity="{gir:.2f}" {o(3)}/></g>')
    s += SL(Z_SRED, ves)

    # калачи на шесте
    kal = (f'<rect x="1480" y="500" width="400" height="18" rx="6" fill="#4a3522" {o(4)}/>')
    for i in range(5):
        cx = 1520 + i * 86
        kch = 4.0 * A.w(t, 2.2 + i * .3, i * .25)
        kal += (f'<g transform="rotate({kch:.1f} {cx:.0f} 510)">'
                f'<circle cx="{cx:.0f}" cy="{586:.0f}" r="52" fill="url(#solom)" {o(4)}/>'
                f'<circle cx="{cx:.0f}" cy="{586:.0f}" r="20" fill="#5a4328" {o(3)}/>'
                f'<line x1="{cx:.0f}" y1="510" x2="{cx:.0f}" y2="{560:.0f}"'
                f' stroke="#8a7a58" stroke-width="4"/></g>')
    s += SL(Z_SRED, kal)
    s += SL(Z_SRED, _polka_s_utvaryu(1420, 800, 480, t, 73, 4))
    zherdi = ""
    zherdi += (f'<rect x="250" y="300" width="1420" height="22" rx="9"'
               f' fill="#5b4428" {o(5)}/>'
               f'<rect x="330" y="214" width="1260" height="20" rx="8"'
               f' fill="#6a5030" {o(4)}/>')
    for i in range(9):
        zx_ = 60 + i * 220
        zherdi += (f'<line x1="{zx_:.0f}" y1="{410+abs(zx_-960)*0.17:.0f}"'
                   f' x2="{zx_+60:.0f}" y2="250" stroke="#5b4428" stroke-width="10"'
                   f' opacity=".8"/>')
    for i in range(8):
        hx2 = 360 + i * 170
        kc2 = 2.6 * A.w(t, 3.1, i * .27)
        zherdi += (f'<g transform="rotate({kc2:.1f} {hx2:.0f} 322)">'
                   f'<path d="M{hx2-26:.0f},322 L{hx2+26:.0f},322'
                   f' L{hx2+18:.0f},{416:.0f} L{hx2-18:.0f},{416:.0f} Z"'
                   f' fill="{["#8a6a46","#6b4a2c","#7a6342","#5e4630"][i%4]}" {o(3)}/>'
                   f'<ellipse cx="{hx2:.0f}" cy="324" rx="26" ry="9" fill="#3a2a1a"'
                   f' {o(2)}/></g>')
    for i in range(7):
        hx = 220 + i * 250
        hy = 300 + abs(hx - 960) * .13
        kch = 3.0 * A.w(t, 2.8, i * .3)
        zherdi += (f'<g transform="rotate({kch:.1f} {hx:.0f} {hy:.0f})">'
                   f'<path d="M{hx-30:.0f},{hy:.0f} L{hx+30:.0f},{hy:.0f}'
                   f' L{hx+20:.0f},{hy+110:.0f} L{hx-20:.0f},{hy+110:.0f} Z"'
                   f' fill="{["#7a6342","#6b4a2c","#8a6a46"][i%3]}" {o(3)}/>'
                   f'<line x1="{hx:.0f}" y1="{hy-30:.0f}" x2="{hx:.0f}" y2="{hy:.0f}"'
                   f' stroke="#8a7a58" stroke-width="4"/></g>')
    s += SL(Z_DAL, zherdi)
    s += SL(Z_SRED, _dvorovaya_utvar(60, 1058, 420, t, 79, ["korob", "meshok", "korzina"]))
    s += SL(Z_SRED, _dvorovaya_utvar(700, 816, 560, t, 397,
                                     ["korzina", "korob", "kadka"]))

    # купец за прилавком
    kx, ky, kh = 1180, 1040, 500
    kup = figura(kx, ky, kh, t, col="#4b3550", kant="#ffd98a", ph=.2, boroda=True)
    r1, _, (kpx, kpy) = _ruka_ekr(kx, ky, kh, 1, kh * .46, -58 + 30 * gir, t, "#4b3550",
                                  "#ffd98a", .1, 5)
    r2, _, (klx, kly) = _ruka_ekr(kx, ky, kh, -1, kh * .36, 42, t, "#4b3550", "#ffd98a", .5, 4)
    s += SL(Z_SRED, kup + r1 + r2)

    # покупательница с корзиной
    bx_, by_, bh_ = 560, 1050, 470
    pok = figura(bx_, by_, bh_, t, col="#3d4a3a", kant="#cfe4f5", platok=True, ph=.6)
    r3, (c1x, c1y), (ppx, ppy) = _ruka_ekr(bx_, by_, bh_, 1, bh_ * .36, 62, t, "#3d4a3a",
                                           "#cfe4f5", .3, 4)
    r4, (c2x, c2y), (plx2, ply2) = _ruka_ekr(bx_, by_, bh_, -1, bh_ * .36, 118, t, "#3d4a3a",
                                             "#cfe4f5", .7, 4)
    kor_y = (c1y + c2y) / 2 + 40
    pok += r3 + r4
    pok += (f'<path d="M{bx_-96:.0f},{kor_y:.0f} L{bx_+96:.0f},{kor_y:.0f}'
            f' L{bx_+66:.0f},{kor_y+118:.0f} L{bx_-66:.0f},{kor_y+118:.0f} Z"'
            f' fill="url(#solom)" {o(5)}/>'
            f'<path d="M{bx_-80:.0f},{kor_y:.0f} Q{bx_:.0f},{kor_y-96:.0f}'
            f' {bx_+80:.0f},{kor_y:.0f}" fill="none" stroke="#8a6a3c" stroke-width="9"/>')
    s += SL(Z_SRED, pok)

    # мальчик Иван с берестяной грамоткой
    mx_, my_, mh_ = 830, 1056, 330
    prizh = 6 * A.w(t, 1.6, .2)
    mal = figura(mx_, my_, mh_, t, col="#9a8c70", kant="#cfe4f5", ph=.4)
    r5, _, (m1x, m1y) = _ruka_ekr(mx_, my_, mh_, 1, mh_ * .34, 128, t, "#9a8c70", "#cfe4f5", .2, 4)
    r6, _, (m2x, m2y) = _ruka_ekr(mx_, my_, mh_, -1, mh_ * .34, 52, t, "#9a8c70", "#cfe4f5", .6, 4)
    mal += r5 + r6
    gy = my_ - mh_ * .46 + prizh
    mal += (f'<rect x="{mx_-54:.0f}" y="{gy:.0f}" width="108" height="76" rx="8"'
            f' fill="#cdb183" {o(4)}/>'
            f'<path d="M{mx_-40:.0f},{gy+22:.0f} Q{mx_-10:.0f},{gy+12:.0f}'
            f' {mx_+20:.0f},{gy+24:.0f} Q{mx_+40:.0f},{gy+32:.0f} {mx_+44:.0f},{gy+22:.0f}"'
            f' fill="none" stroke="#7a6038" stroke-width="4"/>'
            f'<path d="M{mx_-40:.0f},{gy+48:.0f} Q{mx_-6:.0f},{gy+38:.0f}'
            f' {mx_+26:.0f},{gy+50:.0f}" fill="none" stroke="#7a6038" stroke-width="4"/>')
    mal += para_izo_rta(mx_ + 30, my_ - mh_ * .80, t, .5, .8, .5)
    s += SL(Z_SRED, mal + ten(mx_, my_ + 6, 72, 14, .45))
    s += SL(Z_SRED, teplo(1180, 700, 300, 220, .36))
    s += SL(Z_PERED, _stolb_pered(-6, 96, "#1d1611", 0, H))
    s += SL(Z_LETIT, sneg_letit(t, 14, 27, .36, .6))
    s += ramka_pp("oba")
    s += vinetka(.42)
    return s


def dve_pustye_lavki(t):
    """Горница: у стены две лавки — на первой платок и веретено, на второй
    шапка и топор. Между ними стол с одной миской и ложкой. Мальчик сидит за
    столом на табурете, ноги не достают до пола. Свет гаснет над лавками."""
    rnd = random.Random(110)
    pol = 760
    s = _stena_gornicy(t, 7, True, pol)
    s += SL(Z_DAL, f'<rect x="620" y="0" width="30" height="{pol:.0f}" fill="#4e3220"'
                   f' opacity=".7"/>'
                   f'<rect x="1300" y="0" width="30" height="{pol:.0f}" fill="#4e3220"'
                   f' opacity=".7"/>')
    s += SL(Z_DAL, okno_izby(820, 150, 330, 280, t, svet=False, moroz=.55))
    s += SL(Z_DAL, zanaveska(820, 140, 160, 120, TKAN, t, 1)
            + zanaveska(1150, 140, 160, 120, TKAN, t, -1))
    s += SL(Z_DAL, _polka_s_utvaryu(180, 330, 420, t, 85, 3))
    s += SL(Z_DAL, _polka_s_utvaryu(620, 560, 540, t, 147, 4))
    s += SL(Z_DAL, _polka_s_utvaryu(460, 420, 480, t, 389, 4))
    s += SL(Z_SRED, _dvorovaya_utvar(620, 700, 500, t, 391,
                                     ["kadka", "korzina", "korob"]))
    s += SL(Z_DAL, utvar_izby(1420, 320, 420, t, 11))
    # якорь был 1180 — пила (x+880) и серп уезжали за правый край холста,
    # и половина снасти в кадр не попадала (тот же класс, что в сцене
    # прищуренной соседки; правило «поймал один — проверь все»)
    s += SL(Z_DAL, _stennoe_hozyaystvo(760, 150, t, 149))
    s += SL(Z_DAL, hodiki(1760, 200, t, 1.4))

    # печь углом слева
    s += SL(Z_SRED, pech(-110, 180, 420, 560, t, True, True, True))
    s += SL(Z_SRED, ugli(10, 560, 250, t, 8, 2) + teplo(150, 540, 330, 280, .40))
    s += SL(Z_SRED, dym(140, 190, t, 4, .24, 220, .28, "#d3dae2", .8))

    g1 = A.ease(A.seg(t, .6, 1.0))
    g2 = A.ease(A.seg(t, 2.1, 1.0))
    s += SL(Z_SRED, luch(560, 420, 360, 420, t, .22 * (1 - g1))
            + luch(1180, 420, 360, 420, t, .22 * (1 - g2)))

    # две лавки
    s += SL(Z_SRED, _lavka_krupno(300, 1010, 640, t, 230, True))
    s += SL(Z_SRED, _lavka_krupno(1220, 1010, 640, t, 230, True))
    s += SL(Z_SRED, _kadushki_i_grabli(60, 1056, t, 135))

    # на первой — платок и веретено с недопряденной нитью
    prov = 26 * g1
    l1 = (f'<path d="M340,772 Q450,700 620,764 Q500,842 368,826 Z" fill="#6d4a52" {o(6)}/>'
          f'<path d="M372,784 Q482,730 598,776" fill="none" stroke="{KRAS}"'
          f' stroke-width="9" opacity=".7"/>'
          f'<path d="M386,812 Q470,766 570,802" fill="none" stroke="#b07a86"'
          f' stroke-width="6" opacity=".6"/>'
          f'<path d="M700,780 L736,660 L772,780 L736,890 Z" fill="url(#derev)" {o(5)}/>'
          f'<ellipse cx="736" cy="816" rx="54" ry="28" fill="url(#solom)" {o(5)}/>'
          f'<path d="M736,660 Q812,{640+prov:.0f} 884,{690+prov*1.8:.0f}" fill="none"'
          f' stroke="{KREM}" stroke-width="8"/>'
          f'<ellipse cx="900" cy="{706+prov*1.8:.0f}" rx="56" ry="70" fill="url(#solom)"'
          f' opacity=".9" {o(5)}/>')
    s += SL(Z_SRED, l1)

    # на второй — мужская шапка и плотницкий топор
    l2 = (f'<path d="M1262,782 Q1290,672 1384,668 Q1480,672 1508,782 Z" fill="#3a3040"'
          f' {o(6)}/>'
          f'<rect x="1246" y="768" width="280" height="44" rx="20" fill="#5e4a3a" {o(5)}/>'
          f'<path d="M1262,720 Q1384,690 1508,720" fill="none" stroke="#50465c"'
          f' stroke-width="7" opacity=".7"/>'
          f'<rect x="1596" y="762" width="300" height="32" rx="13" fill="url(#derev)"'
          f' {o(5)}/>'
          f'<path d="M1600,776 L1548,700 L1470,726 L1480,812 L1556,830 Z"'
          f' fill="url(#zhel)" {o(6)}/>'
          f'<path d="M1490,744 L1540,730" stroke="#e6eef6" stroke-width="10"'
          f' opacity=".75"/>'
          f'<path d="M1480,812 Q1520,826 1556,830" fill="none" stroke="#8c99a4"'
          f' stroke-width="6" opacity=".7"/>')
    s += SL(Z_SRED, l2)

    # стол между лавками, миска и ложка
    s += SL(Z_SRED, stol(960, 880, 520, 32))
    s += SL(Z_SRED, f'<path d="M882,866 Q960,924 1038,866 L1024,842 Q960,886 896,842 Z"'
                    f' fill="url(#glina)" {o(5)}/>'
                    f'<ellipse cx="960" cy="862" rx="78" ry="22" fill="#6d4e32" {o(3)}/>'
                    f'<ellipse cx="1092" cy="868" rx="34" ry="16" fill="url(#derev)"'
                    f' {o(3)}/>'
                    f'<rect x="1118" y="860" width="110" height="14" rx="7"'
                    f' fill="url(#derev)" {o(3)}/>')

    # мальчик на табурете, ноги не достают до пола
    fx, fy, fh = 960, 1000, 300
    gol = 10 * g2
    s += SL(Z_SRED, f'<rect x="{fx-80:.0f}" y="{fy-60:.0f}" width="160" height="22" rx="8"'
                    f' fill="url(#dosk)" {o(5)}/>'
                    f'<rect x="{fx-62:.0f}" y="{fy-38:.0f}" width="26" height="38" rx="7"'
                    f' fill="#4a3522" {o(3)}/>'
                    f'<rect x="{fx+36:.0f}" y="{fy-38:.0f}" width="26" height="38" rx="7"'
                    f' fill="#4a3522" {o(3)}/>')
    mal = figura(fx, fy - 60, fh, t, col="#6e6250", kant="#ffd98a", ph=.3,
                 naklon=6 * g2)
    r1, _, (m1x, m1y) = _ruka_ekr(fx, fy - 60, fh, 1, fh * .36, 104, t, "#6e6250", "#ffd98a", .2,
                                  3)
    r2, _, (m2x, m2y) = _ruka_ekr(fx, fy - 60, fh, -1, fh * .36, 76, t, "#6e6250", "#ffd98a", .6,
                                  3)
    mal += r1 + r2
    s += SL(Z_SRED, mal)
    s += SL(Z_SRED, _kot_zhivoy(250, 1046, t, 1.5, "#4a423c", .5, True, True))
    s += SL(Z_SRED, mebel_hlam(1560, 1056, 400, t, 17))
    s += SL(Z_SRED, krynka(120, 1030, 1.4) + kartoshka(600, 1056, t, 7, 6, 1.1))
    # половик во всю середину пола
    s += SL(Z_SRED, f'<path d="M560,1006 L1400,1006 L1520,1076 L440,1076 Z"'
                    f' fill="{RUSH}" {o(5)}/>'
                    f'<path d="M580,1026 L1392,1026 M566,1050 L1428,1050"'
                    f' stroke="{KRAS}" stroke-width="9" opacity=".65"/>'
                    f'<path d="M600,1038 L1372,1038" stroke="#6a7a8a" stroke-width="6"'
                    f' opacity=".5"/>')
    # прялка в углу: донце, гребень, веретено
    prx, pry = 1700, 1000
    pkach = 2.2 * A.w(t, 3.2, .3)
    s += SL(Z_SRED, f'<g transform="rotate({pkach:.1f} {prx:.0f} {pry:.0f})">'
                    f'<rect x="{prx-110:.0f}" y="{pry-40:.0f}" width="230" height="36"'
                    f' rx="10" fill="url(#dosk)" {o(5)}/>'
                    f'<rect x="{prx-16:.0f}" y="{pry-420:.0f}" width="34" height="382"'
                    f' rx="12" fill="url(#derev)" {o(5)}/>'
                    f'<path d="M{prx-80:.0f},{pry-420:.0f} L{prx+112:.0f},{pry-420:.0f}'
                    f' L{prx+96:.0f},{pry-500:.0f} L{prx-64:.0f},{pry-500:.0f} Z"'
                    f' fill="#6a5030" {o(5)}/>')
    for i in range(7):
        s += SL(Z_SRED, f'<line x1="{prx-62+i*28:.0f}" y1="{pry-500:.0f}"'
                        f' x2="{prx-56+i*28:.0f}" y2="{pry-556:.0f}" stroke="#5b4428"'
                        f' stroke-width="8"/>')
    s += SL(Z_SRED, f'<ellipse cx="{prx+20:.0f}" cy="{pry-540:.0f}" rx="74" ry="56"'
                    f' fill="url(#solom)" opacity=".92" {o(5)}/></g>')
    # сундук под окном
    s += SL(Z_SRED, f'<rect x="940" y="930" width="300" height="130" rx="10"'
                    f' fill="url(#derev)" {o(6)}/>'
                    f'<path d="M940,930 Q1090,876 1240,930 Z" fill="#5b4428" {o(5)}/>'
                    f'<rect x="930" y="962" width="320" height="18" rx="7"'
                    f' fill="{ZHELEZ}" {o(3)}/>'
                    f'<rect x="1070" y="954" width="40" height="46" rx="8"'
                    f' fill="{ZHELEZ}" {o(3)}/>')
    s += SL(Z_SRED, _dvorovaya_utvar(560, 1072, 820, t, 321,
                                     ["korzina", "korob", "kadka", "meshok"]))
    s += SL(Z_SRED, _listya(377, 22, 950, 1050))
    s += SL(Z_PERED, _stolb_pered(1846, 110, "#140f0b", 0, H))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def vdova_natalya_i_malchik(t):
    """Тёплая изба: Наталья ставит мальчику миску с кашей и набрасывает на
    плечи тулупчик, мальчик сидит на лавке с ложкой. Потом на столе доска с
    писалом, и он берёт писало. На полке горшки, у печи кот."""
    rnd = random.Random(111)
    pol = 770
    s = _stena_gornicy(t, 9, True, pol)
    s += SL(Z_DAL, f'<rect x="1180" y="0" width="30" height="{pol:.0f}" fill="#4e3220"'
                   f' opacity=".7"/>')
    s += SL(Z_DAL, _polka_s_utvaryu(1240, 300, 560, t, 87, 4))
    s += SL(Z_DAL, utvar_izby(1300, 520, 420, t, 13))
    s += SL(Z_DAL, okno_izby(980, 160, 260, 230, t, svet=False, moroz=.4))

    # печь крупно слева — главный предмет и единственное тёплое пятно
    s += SL(Z_SRED, pech(20, 90, 620, 740, t, True, True, False))
    s += SL(Z_SRED, teplo(330, 560, 420, 350, .46))
    s += SL(Z_SRED, iskra_let(t, 300, 600, 8, 4, 280, .5))
    s += SL(Z_SRED, dym(330, 150, t, 4, .3, 240, .3, "#d3dae2", .8))
    s += SL(Z_SRED, _kot_zhivoy(640, 1046, t, 1.4, "#554c44", .7, True, False))
    s += SL(Z_SRED, mebel_hlam(1660, 1050, 420, t, 19))

    s += SL(Z_SRED, stol(1180, 850, 1180, 40))
    s += SL(Z_SRED, _polka_s_utvaryu(760, 250, 520, t, 339, 4))
    s += SL(Z_SRED, _dvorovaya_utvar(700, 1070, 460, t, 341,
                                     ["kadka", "korzina", "korob"]))
    s += SL(Z_SRED, utvar_izby(820, 520, 360, t, 35))
    s += SL(Z_SRED, _polka_s_utvaryu(620, 440, 520, t, 353, 4))
    s += SL(Z_SRED, _stennoe_hozyaystvo(560, 320, t, 355))
    s += SL(Z_SRED, f'<rect x="1180" y="400" width="300" height="210" rx="10"'
                    f' fill="{RUSH}" {o(5)}/>'
                    f'<path d="M1196,452 L1464,452 M1196,502 L1464,502"'
                    f' stroke="{KRAS}" stroke-width="9" opacity=".65"/>')
    s += SL(Z_SRED, _lavka_krupno(1290, 1010, 480, t, 160))

    # миска с кашей ставится на стол
    st1 = A.ease(A.seg(t, .4, .9))
    bx_, by_ = 960, 836 - 140 * (1 - st1)
    s += SL(Z_SRED, f'<path d="M{bx_-88:.0f},{by_:.0f} Q{bx_:.0f},{by_+76:.0f}'
                    f' {bx_+88:.0f},{by_:.0f} L{bx_+72:.0f},{by_-26:.0f}'
                    f' Q{bx_:.0f},{by_+30:.0f} {bx_-72:.0f},{by_-26:.0f} Z"'
                    f' fill="url(#glina)" {o(5)}/>'
                    f'<ellipse cx="{bx_:.0f}" cy="{by_-24:.0f}" rx="80" ry="24"'
                    f' fill="url(#krem)" {o(3)}/>'
                    + par(bx_, by_ - 50, t, 4, .55, 170, .45, 1.1))

    # доска с писалом появляется на третьих словах
    st3 = A.ease(A.seg(t, 3.2, 1.0))
    dx_, dy_ = 1380, 830
    dos = (f'<rect x="{dx_-130:.0f}" y="{dy_-30:.0f}" width="260" height="36" rx="8"'
           f' fill="#6b5a3c" opacity="{st3:.2f}" {o(5)}/>'
           f'<rect x="{dx_-118:.0f}" y="{dy_-24:.0f}" width="236" height="24" rx="6"'
           f' fill="#2e2620" opacity="{st3*.9:.2f}"/>')
    vol = min(1.0, max(.0, (t - 3.6) * .8))
    dos += (f'<path d="M{dx_-96:.0f},{dy_-12:.0f} Q{dx_-70:.0f},{dy_-22:.0f}'
            f' {dx_-44:.0f},{dy_-12:.0f} Q{dx_-18:.0f},{dy_-2:.0f} {dx_+8:.0f},{dy_-12:.0f}"'
            f' fill="none" stroke="#d8c79a" stroke-width="5"'
            f' stroke-dasharray="{200*vol:.0f} 400" opacity="{st3:.2f}"/>')
    s += SL(Z_SRED, dos)

    # Наталья у стола
    nx, ny, nh = 760, 1030, 540
    nat = figura(nx, ny, nh, t, col="#39303c", kant="#ffd98a", platok=True, ph=.2)
    # было: один прямой рукав в 270 px по диагонали к полке — брусок
    r1, (hx, hy), (npx, npy) = _ruka_so_sgibom(nx, ny, nh, 1, nh * .25,
                                               16 + 14 * st1, nh * .22,
                                               72 - 16 * st1, t, "#39303c",
                                               "#ffd98a", .1, 5)
    r2, (tx2, ty2), (nlx, nly) = _ruka_ekr(nx, ny, nh, -1, nh * .40, -62, t, "#39303c",
                                           "#ffd98a", .5, 4)
    nat += r1 + r2
    s += SL(Z_SRED, nat)

    # мальчик на лавке
    mx_, my_, mh_ = 1420, 1010, 330
    ber = A.ease(A.seg(t, 3.8, .8))
    mal = figura(mx_, my_ - 150, mh_, t, col="#7a6a52", kant="#ffd98a", ph=.4,
                 naklon=-5 * ber)
    r3, (lx3, ly3), (p1x, p1y) = _ruka_ekr(mx_, my_ - 150, mh_, 1, mh_ * .46, 154 - 40 * ber, t,
                                           "#7a6a52", "#ffd98a", .2, 4)
    r4, _, (p2x, p2y) = _ruka_ekr(mx_, my_ - 150, mh_, -1, mh_ * .42, 170, t, "#7a6a52",
                                  "#ffd98a", .6, 4)
    mal += r3 + r4
    mal += (f'<rect x="{lx3-10:.0f}" y="{ly3-10:.0f}" width="16" height="96" rx="7"'
            f' fill="url(#derev)" opacity="{1-ber:.2f}" {o(3)}/>'
            f'<ellipse cx="{lx3-2:.0f}" cy="{ly3+96:.0f}" rx="26" ry="16"'
            f' fill="url(#derev)" opacity="{1-ber:.2f}" {o(3)}/>'
            f'<rect x="{lx3-8:.0f}" y="{ly3-16:.0f}" width="12" height="90" rx="6"'
            f' fill="{ZHELEZ}" opacity="{ber:.2f}" {o(3)}/>')
    s += SL(Z_SRED, mal)

    # тулупчик ложится на плечи
    tul = A.ease(A.seg(t, 1.5, 1.0))
    s += SL(Z_SRED, f'<path d="M{mx_-92:.0f},{my_-150-mh_*.62-40*(1-tul):.0f}'
                    f' Q{mx_:.0f},{my_-150-mh_*.80-70*(1-tul):.0f}'
                    f' {mx_+92:.0f},{my_-150-mh_*.62-40*(1-tul):.0f}'
                    f' L{mx_+76:.0f},{my_-150-mh_*.28:.0f}'
                    f' Q{mx_:.0f},{my_-150-mh_*.40:.0f}'
                    f' {mx_-76:.0f},{my_-150-mh_*.28:.0f} Z" fill="#7a5a36"'
                    f' opacity="{tul*.95:.2f}" {o(5)}/>')
    s += SL(Z_SRED, krynka(1800, 836, 1.2) + karavay(1640, 840, 1.1, True))
    s += SL(Z_PERED, _stolb_pered(-6, 96, "#140f0b", 0, H))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def malchik_u_steny(t):
    """Городская улица: бревенчатая стена амбара на пол-кадра. Четверо ребят
    играют в горелки, Иван стоит у стены, руки за спиной, и смотрит.
    У стены бочка, тележное колесо, лопухи, курица перебегает улицу."""
    rnd = random.Random(112)
    s = nebo("den", t, False, 43)
    s += oblaka(t, 130, 5, 25, .45)
    s += SL(Z_DAL, _derevnya_ryad(470, t, 71, ((130, 300), (1810, 280))))
    # НАД ГОЛОВОЙ РЕБЁНКА ПУСТО. Осмотр 15.11: «два взрослых держат
    # скрещённые шесты прямо над головой мальчика, у самого лица». Шестов
    # никто не держал — это крестовина ворот амбара (1010-1439 × 419-616) и
    # полотно пилы со стенной снасти (1240-1520 × 620-708) приходились ровно
    # на голову Ивана, стоявшего на 1480. Стена и снасть съехали влево,
    # правую часть держит дощатый забор, Иван отошёл в чистое поле кадра.
    s += SL(Z_SRED, _stena_ambara(230, 210, 1120, 580, t, True, 3))
    s += SL(Z_SRED, _stennoe_hozyaystvo(240, 300, t, 137))
    # забор и поленница стоят НИЖЕ и ПРАВЕЕ головы Ивана: горизонтальные
    # поперечины забора на уровне лица — та же беда, что и шесты
    s += SL(Z_SRED, _zabor_dosok(1366, 700, 574, 240, 85, 56))
    s += SL(Z_SRED, _polenica(1706, 420, 214, 180, 87, 22))
    s += SL(Z_DAL, dym(1810, 180, t, 4, .24, 240, .3, "#d3dae2", .8))

    zem = f'<rect x="0" y="780" width="{W}" height="300" fill="#4e3f2c"/>'
    zem += _zemlya_faktura(830, 1060, 73, 15)
    zem += _koleya(960, 75, 2)
    zem += _listya(77, 24, 830, 1060)
    zem += _trava(rnd, 10, 850, 1050)
    s += SL(Z_SRED, zem)

    # бочка, тележное колесо, лопухи у стены
    s += SL(Z_SRED, f'<path d="M80,1000 Q40,900 80,800 L250,800 Q290,900 250,1000 Z"'
                    f' fill="url(#derev)" {o(6)}/>'
                    f'<rect x="56" y="836" width="218" height="20" rx="7" fill="{ZHELEZ}"'
                    f' {o(3)}/>'
                    f'<rect x="56" y="946" width="218" height="20" rx="7" fill="{ZHELEZ}"'
                    f' {o(3)}/>'
                    f'<ellipse cx="165" cy="800" rx="86" ry="24" fill="#5b4428" {o(4)}/>')
    # колесо ушло к бочке влево, чтобы не стоять там, где теперь Иван
    kol_a = 6 * A.w(t, 5.0, .2)
    kolo = (f'<g transform="rotate({kol_a:.1f} 340 972)">'
            f'<circle cx="340" cy="972" r="118" fill="none" stroke="url(#derev)"'
            f' stroke-width="24"/>'
            f'<circle cx="340" cy="972" r="31" fill="url(#derev)" {o(4)}/>')
    for i in range(8):
        a = math.radians(i * 45)
        kolo += (f'<line x1="{340+31*math.cos(a):.0f}" y1="{972+31*math.sin(a):.0f}"'
                 f' x2="{340+107*math.cos(a):.0f}" y2="{972+107*math.sin(a):.0f}"'
                 f' stroke="#5e442a" stroke-width="10"/>')
    kolo += "</g>"
    s += SL(Z_SRED, kolo)
    s += SL(Z_SRED, _podorozhnik(400, 1040, 2.0, t, .2, 6)
            + _podorozhnik(1480, 1056, 1.8, t, .7, 6))
    s += SL(Z_SRED, _yaschiki(1414, 962, t, 79, 2, .92))

    # четверо ребят в горелки: двое бегут, двое догоняют
    beg = (t * .5) % 1.0
    deti = ""
    # РОСТ, ГЛУБИНА, ШАГ И ПОВОРОТ У КАЖДОГО СВОИ (осмотр 15.11: четверо
    # ребят шли ровным рядом одного роста и читались орнаментом). Теперь
    # разброс роста 614-217 px, базы 1032-976, шаги 412-274-328 и у каждого
    # свой убор.
    for i, (bx0, bh, col, dg, dep) in enumerate(((330, 530, "#6b5a3c", 0, 1.16),
                                                 (742, 390, "#3f5466", 0, .78),
                                                 (1016, 470, "#6a4a52", 1, .98),
                                                 (1344, 330, "#4c5c3e", 1, .66))):
        bh = int(bh * dep)
        dx_ = bx0 + (150 if dg else 230) * beg
        yb = 1014 - (1 - dep) * 110
        pryg = (14 + 9 * i % 11) * abs(math.sin(beg * 6.283 * 2 + i * 1.7))
        d = figura(dx_, yb - pryg, bh, t, col=col, kant="#cfe4f5", ph=i * .31,
                   naklon=(14 if dg else -11) + (3 if i % 2 else -4),
                   platok=(i == 3), shapka=(i in (1, 2)), profil=(i % 2 == 0),
                   op=.78 + .22 * dep)
        # руки МАШУТ в противофазе: одна вверх-наружу, другая вниз-наружу,
        # и у чётных-нечётных по-разному — бег, а не стойка «руки по швам»
        rr1, _, (a1x, a1y) = _ruka(dx_, yb - pryg, bh, 1, bh * (.38 + .09 * (i % 2)),
                                   (-34 if dg else 52) + (14 if i % 2 else -16), t, col,
                                   "#cfe4f5", i * .2, 7)
        rr2, _, (a2x, a2y) = _ruka(dx_, yb - pryg, bh, -1, bh * (.34 + .11 * (i % 2)),
                                   (46 if dg else -30) + (11 if i % 2 else -13), t, col,
                                   "#cfe4f5", i * .2 + .4, 7)
        d += rr1 + rr2
        deti += d + ten(dx_, yb + 6, 60 * dep, 13 * dep, .4)
        # пыль из-под ног
        for k in range(3):
            pp = (beg + k / 3.0) % 1.0
            deti += (f'<ellipse cx="{dx_-40-pp*70:.0f}" cy="{yb-pp*16:.0f}"'
                     f' rx="{(18+pp*30)*dep:.0f}" ry="{(8+pp*12)*dep:.0f}"'
                     f' fill="#8a7a62" opacity="{(1-pp)*.35:.2f}"/>')
    s += SL(Z_SRED, deti)

    # Иван у стены: спиной к брёвнам, руки за спиной
    ix, iy, ih = 1600, 1026, 470
    iv = figura(ix, iy, ih, t, col="#8e8068", kant="#ffd98a", ph=.5)
    s += SL(Z_SRED, iv + ten(ix, iy + 6, 84, 16, .45))
    s += SL(Z_SRED, f'<path d="M{ix-66:.0f},{iy-ih*.52:.0f} Q{ix:.0f},{iy-ih*.40:.0f}'
                    f' {ix+66:.0f},{iy-ih*.52:.0f}" fill="none" stroke="#8e8068"'
                    f' stroke-width="26" stroke-linecap="round"/>')

    # курица перебегает улицу
    kx_ = ((t * 170) % 2300) - 200
    s += SL(Z_SRED, kura(kx_, 1056, t, 1.4, .2))
    s += SL(Z_SRED, _dvorovaya_utvar(560, 1066, 420, t, 81, ["korzina", "vedro"]))
    s += SL(Z_PERED, _vetka_pered(2000, 60, 760, 158, t, 83, "#241c16", 6))
    s += SL(Z_LETIT, sneg_letit(t, 12, 29, .3, .6))
    s += ramka_pp("oba")
    s += vinetka(.42)
    return s


def yurodivyy_na_vecherney_ulice(t):
    """Та же улица на закате, длинные тени: высокий худой странник идёт со
    спины, босой, подпоясан верёвкой, в правой руке посох. Четверо ребят
    сбились в кучку и хохочут. У забора лежит собака, над крышами звезда."""
    rnd = random.Random(113)
    s = nebo("zakat", t, False, 47) if "zakat" else nebo("sumer", t, True, 47)
    s += oblaka(t, 140, 5, 31, .5)
    s += SL(Z_DAL, _derevnya_ryad(460, t, 85, ((150, 380), (640, 320), (1780, 400))))
    s += SL(Z_SRED, _stena_ambara(620, 110, 1300, 660, t, False, 5))
    s += SL(Z_DAL, _zabor_dosok(-20, 380, 560, 190, 87, 54))
    s += SL(Z_DAL, teplo(640, 330, 230, 180, .40))
    s += SL(Z_DAL, dym(640, 210, t, 5, .26, 280, .34, "#d3dae2", .9))

    # первая звезда
    mig = .4 + .6 * abs(A.w(t, 1.6, .2))
    s += SL(Z_DAL, f'<circle cx="1480" cy="110" r="9" fill="#fff6dd"'
                   f' opacity="{mig:.2f}"/>'
                   f'<path d="M1480,86 L1484,106 L1504,110 L1484,114 L1480,134'
                   f' L1476,114 L1456,110 L1476,106 Z" fill="#fff6dd"'
                   f' opacity="{mig*.8:.2f}"/>')

    zem = f'<rect x="0" y="770" width="{W}" height="310" fill="#4a3c2a"/>'
    zem += _zemlya_faktura(820, 1060, 89, 15)
    zem += _koleya(950, 91, 2)
    zem += _listya(93, 26, 820, 1060)
    s += SL(Z_SRED, zem)

    # длинные тени поперёк улицы
    ten_ = ""
    for i, tx_ in enumerate((336, 742, 1046, 1532)):
        ten_ += (f'<path d="M{tx_:.0f},1010 L{tx_+330:.0f},1066 L{tx_+270:.0f},1076'
                 f' L{tx_-40:.0f},1016 Z" fill="#2c2318" opacity=".35"/>')
    s += SL(Z_SRED, ten_)
    s += SL(Z_SRED, _polenica(80, 700, 320, 260, 95, 26))
    # Якорь был 1060, и пила (x+880) уходила за холст на 1940 — половина
    # снасти просто не попадала в кадр, отчего правая стена и пустовала.
    s += SL(Z_SRED, _stennoe_hozyaystvo(700, 290, t, 139))
    s += SL(Z_SRED, _kadushki_i_grabli(1500, 1050, t, 141))
    s += SL(Z_SRED, _dvorovaya_utvar(1600, 1060, 320, t, 97, ["kadka", "korob"]))

    # странник идёт ровным шагом
    hod = (t * .3) % 1.0
    sx, sy, sh = 760 + 160 * hod, 1030, 620
    shag = 14 * math.sin(hod * 6.283 * 2)
    str_ = figura(sx, sy - abs(shag) * .3, sh, t, col="#4e4438", kant="#ffd98a",
                  ph=.2, boroda=True, naklon=2 * math.sin(hod * 12.6))
    r1, (px2, py2), (spx, spy) = _ruka_ekr(sx, sy, sh, 1, sh * .42, 72, t, "#4e4438", "#ffd98a",
                                           .1, 4)
    r2, _, (slx, sly) = _ruka_ekr(sx, sy, sh, -1, sh * .44, 96, t, "#4e4438", "#ffd98a", .5, 6)
    str_ += r1 + r2
    # посох стучит о землю
    stuk = 10 * abs(math.sin(hod * 6.283))
    str_ += (f'<line x1="{px2:.0f}" y1="{py2-180:.0f}" x2="{px2+16:.0f}"'
             f' y2="{sy+6-stuk:.0f}" stroke="url(#derev)" stroke-width="18"'
             f' stroke-linecap="round"/>'
             f'<circle cx="{px2:.0f}" cy="{py2-186:.0f}" r="18" fill="#5e442a" {o(3)}/>')
    # заплаты на длинной одежде и верёвка-пояс
    for i, (zx_, zy_) in enumerate(((-44, -.42), (36, -.30), (-20, -.16))):
        str_ += (f'<rect x="{sx+zx_:.0f}" y="{sy+sh*zy_:.0f}" width="54" height="46"'
                 f' rx="8" fill="#6a5a46" opacity=".8" {o(3)}/>')
    str_ += (f'<path d="M{sx-70:.0f},{sy-sh*.46:.0f} Q{sx:.0f},{sy-sh*.40:.0f}'
             f' {sx+70:.0f},{sy-sh*.46:.0f}" fill="none" stroke="#9a8a68"'
             f' stroke-width="12"/>'
             f'<path d="M{sx+58:.0f},{sy-sh*.45:.0f} L{sx+66:.0f},{sy-sh*.26:.0f}"'
             f' stroke="#9a8a68" stroke-width="8"/>')
    s += SL(Z_SRED, str_ + ten(sx, sy + 6, 110, 20, .5))

    # четверо ребят кучкой хохочут
    deti = ""
    # ростом и шагом разные: было 290-275-300-270 через ровные 90 px
    for i, (bx0, bh, col, gl) in enumerate(((268, 380, "#6b5a3c", 1.0),
                                            (404, 246, "#4a5a6a", .80),
                                            (512, 322, "#6a4a52", .94),
                                            (650, 196, "#52604a", .70))):
        tr = 10 * abs(A.w(t, 1.1, i * .3))
        yb3 = 1020 - tr * .3 - (1 - gl) * 86
        d = figura(bx0, yb3, bh, t, col=col,
                   kant="#cfe4f5", ph=i * .25, naklon=-9 + 6 * i,
                   profil=(i % 2 == 1), shapka=(i == 2), platok=(i == 3),
                   op=.80 + .20 * gl)
        ug = -64 if i == 0 else -100
        rr1, _, (a1x, a1y) = _ruka_ekr(bx0, yb3, bh, 1, bh * (.54 if i == 0 else .34),
                                       ug, t, col, "#cfe4f5", i * .2, 5)
        rr2, _, (a2x, a2y) = _ruka_ekr(bx0, yb3, bh, -1, bh * .32, -104, t, col,
                                       "#cfe4f5", i * .2 + .4, 5)
        d += rr1 + rr2
        deti += d + ten(bx0, yb3 + 6, 58 * gl, 12 * gl, .4)
    s += SL(Z_SRED, deti)

    # собака у забора поднимает голову
    sg = A.ease(A.seg(t, 1.6, .8))
    dx_, dy_ = 180, 1046
    s += SL(Z_SRED, f'<ellipse cx="{dx_:.0f}" cy="{dy_:.0f}" rx="106" ry="46"'
                    f' fill="#6b5236" {o(4)}/>'
                    f'<ellipse cx="{dx_-96:.0f}" cy="{dy_-30-44*sg:.0f}" rx="46" ry="38"'
                    f' fill="#6b5236" {o(4)}/>'
                    f'<path d="M{dx_-128:.0f},{dy_-50-44*sg:.0f}'
                    f' L{dx_-140:.0f},{dy_-92-44*sg:.0f}'
                    f' L{dx_-100:.0f},{dy_-66-44*sg:.0f} Z" fill="#54402a" {o(3)}/>'
                    f'<circle cx="{dx_-112:.0f}" cy="{dy_-36-44*sg:.0f}" r="5"'
                    f' fill="#120c08"/>'
                    f'<path d="M{dx_+96:.0f},{dy_-16:.0f} Q{dx_+150:.0f},'
                    f'{dy_-60-20*A.w(t,1.3,.2):.0f} {dx_+168:.0f},{dy_-10:.0f}"'
                    f' fill="none" stroke="#6b5236" stroke-width="16"'
                    f' stroke-linecap="round"/>')
    s += SL(Z_SRED, _lavka_krupno(1180, 1056, 480, t, 170))
    s += SL(Z_SRED, _polka_s_utvaryu(1100, 540, 420, t, 151, 3))
    # ПРАВАЯ СТЕНА ОБЖИТА (осмотр 15.11: от 1520 до края шло голое бревно на
    # две трети высоты кадра). Настоящие вещи: приставная лестница, второе
    # стенное хозяйство, поленница под стеной, штабель ящиков, связки трав.
    lest = (f'<g transform="rotate(-6 1720 1040)">'
            f'<rect x="1636" y="300" width="20" height="740" rx="8"'
            f' fill="url(#derev)" {o(4)}/>'
            f'<rect x="1792" y="300" width="20" height="740" rx="8"'
            f' fill="url(#derev)" {o(4)}/>')
    for i in range(8):
        lest += (f'<rect x="1640" y="{352+i*92:.0f}" width="168" height="16" rx="6"'
                 f' fill="#5b4428" {o(3)}/>')
    lest += "</g>"
    s += SL(Z_SRED, lest)
    s += SL(Z_SRED, _polenica(1178, 884, 268, 186, 153, 23))
    s += SL(Z_SRED, _yaschiki(1430, 1056, t, 155, 2, .84))
    trav = ""
    for i, (hx_, hl) in enumerate(((1538, 150), (1596, 120), (1876, 168))):
        kol = 3 * A.w(t, 2.2, i * .3)
        trav += (f'<g transform="rotate({kol:.1f} {hx_:.0f} 240)">'
                 f'<rect x="{hx_-7:.0f}" y="236" width="14" height="{hl*.3:.0f}"'
                 f' rx="5" fill="#6a5a3c" {o(3)}/>')
        for k in range(7):
            trav += (f'<path d="M{hx_:.0f},{236+hl*.3:.0f} q{-22+k*7:.0f},{hl*.4:.0f}'
                     f' {-30+k*10:.0f},{hl:.0f}" fill="none" stroke="#7e8a4e"'
                     f' stroke-width="7" opacity=".85"/>')
        trav += (f'<rect x="{hx_-20:.0f}" y="{236+hl*.3:.0f}" width="40" height="16"'
                 f' rx="6" fill="#a8683c" {o(2)}/>'
                 f'<circle cx="{hx_:.0f}" cy="230" r="9" fill="{ZHELEZ}" {o(2)}/></g>')
    s += SL(Z_SRED, trav)
    s += SL(Z_PERED, _stolb_pered(-6, 104, "#1d1611", 0, H))
    s += SL(Z_LETIT, sneg_letit(t, 12, 33, .28, .55))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def yurodivyy_podnimaet_malchika(t):
    """У стены амбара: странник стоит, расставив ноги, посох прислонён к
    стене, обеими руками он поднимает мальчика прямо над своей головой.
    Закатный луч падает на обоих, сорочка отлетает вверх."""
    rnd = random.Random(114)
    s = nebo("zakat", t, False, 51)
    s += oblaka(t, 120, 4, 35, .45)
    s += SL(Z_DAL, _derevnya_ryad(430, t, 99, ((120, 320), (1830, 300))))
    s += SL(Z_SRED, _stena_ambara(220, 40, 1480, 760, t, True, 7))
    s += SL(Z_DAL, dym(1830, 190, t, 4, .24, 240, .3, "#d3dae2", .8))

    zem = f'<rect x="0" y="800" width="{W}" height="280" fill="#4a3c2a"/>'
    zem += _zemlya_faktura(840, 1060, 101, 14)
    zem += _listya(103, 24, 840, 1060)
    zem += _trava(rnd, 9, 860, 1050)
    s += SL(Z_SRED, zem)
    s += SL(Z_SRED, _polenica(40, 740, 280, 220, 105, 25))
    s += SL(Z_SRED, _dvorovaya_utvar(1560, 1062, 380, t, 107, ["korzina", "vedro"]))

    # закатный луч падает на обоих
    s += SL(Z_SRED, luch(700, 60, 620, 900, t, .22))
    s += SL(Z_SRED, teplo(980, 560, 480, 420, .36))

    # посох прислонён к стене
    s += SL(Z_SRED, f'<line x1="520" y1="300" x2="466" y2="1010" stroke="url(#derev)"'
                    f' stroke-width="20" stroke-linecap="round"/>'
                    f'<circle cx="522" cy="294" r="20" fill="#5e442a" {o(3)}/>')

    pod = A.ease(A.seg(t, .4, 1.6))
    # бочка, на которую мальчик встаёт
    bo_x, bo_y, bo_h, bo_w = 1280, 1046, 330, 260
    boch = (f'<path d="M{bo_x-bo_w/2:.0f},{bo_y-bo_h:.0f}'
            f' Q{bo_x-bo_w*.66:.0f},{bo_y-bo_h*.5:.0f} {bo_x-bo_w/2:.0f},{bo_y:.0f}'
            f' L{bo_x+bo_w/2:.0f},{bo_y:.0f}'
            f' Q{bo_x+bo_w*.66:.0f},{bo_y-bo_h*.5:.0f} {bo_x+bo_w/2:.0f},{bo_y-bo_h:.0f} Z"'
            f' fill="url(#derev)" {o(6)}/>'
            f'<rect x="{bo_x-bo_w*.62:.0f}" y="{bo_y-bo_h*.80:.0f}"'
            f' width="{bo_w*1.24:.0f}" height="20" rx="7" fill="{ZHELEZ}" {o(4)}/>'
            f'<rect x="{bo_x-bo_w*.62:.0f}" y="{bo_y-bo_h*.30:.0f}"'
            f' width="{bo_w*1.24:.0f}" height="20" rx="7" fill="{ZHELEZ}" {o(4)}/>'
            f'<ellipse cx="{bo_x:.0f}" cy="{bo_y-bo_h:.0f}" rx="{bo_w/2:.0f}"'
            f' ry="{bo_w*.18:.0f}" fill="#5b4428" {o(5)}/>'
            + ten(bo_x, bo_y + 8, 150, 26, .5))
    s += SL(Z_SRED, boch)
    # странник
    sx, sy, sh = 860, 1046, 560
    str_ = figura(sx, sy, sh, t, col="#4e4438", kant="#ffd98a", ph=.2, boroda=True)
    spx, spy = _plecho(sx, sy, sh, 1)
    # правый рукав тянется к плечу мальчика на бочке и поддерживает его
    mal_pl_x, mal_pl_y = bo_x - 46, bo_y - bo_h - 290 * .62
    ang_p = math.degrees(math.atan2(mal_pl_y - spy, mal_pl_x - spx))
    dl_p = math.hypot(mal_pl_x - spx, mal_pl_y - spy)
    r1, (hx1, hy1), _ = _ruka_ekr(sx, sy, sh, 1, dl_p, ang_p, t,
                                  "#4e4438", "#ffd98a", .1, 2)
    r2, (hx2, hy2), (slx, sly) = _ruka_ekr(sx, sy, sh, -1, sh * .42, 104 - 10 * pod, t,
                                           "#4e4438", "#ffd98a", .5, 4)
    str_ += r1 + r2
    # расставленные ноги
    str_ += (f'<line x1="{sx-30:.0f}" y1="{sy-sh*.30:.0f}" x2="{sx-104:.0f}"'
             f' y2="{sy-4:.0f}" stroke="#4e4438" stroke-width="40" stroke-linecap="round"/>'
             f'<line x1="{sx+30:.0f}" y1="{sy-sh*.30:.0f}" x2="{sx+104:.0f}"'
             f' y2="{sy-4:.0f}" stroke="#4e4438" stroke-width="40" stroke-linecap="round"/>')
    for i, (zx_, zy_) in enumerate(((-56, -.44), (30, -.32), (-16, -.20))):
        str_ += (f'<rect x="{sx+zx_:.0f}" y="{sy+sh*zy_:.0f}" width="58" height="48"'
                 f' rx="8" fill="#6a5a46" opacity=".8" {o(3)}/>')
    str_ += (f'<path d="M{sx-76:.0f},{sy-sh*.46:.0f} Q{sx:.0f},{sy-sh*.40:.0f}'
             f' {sx+76:.0f},{sy-sh*.46:.0f}" fill="none" stroke="#9a8a68"'
             f' stroke-width="13"/>')
    s += SL(Z_SRED, str_ + ten(sx, sy + 8, 150, 26, .5))

    # мальчик поднимается над головой странника
    mh2 = 290
    sx_m = bo_x
    my_ = bo_y - bo_h - 6
    mal = figura(sx_m, my_, mh2, t, col="#d8cbab", kant="#ffd98a", ph=.4,
                 naklon=-3 + 2 * pod)
    r3, _, (m1x, m1y) = _ruka_ekr(sx_m, my_, mh2, 1, mh2 * .44, -28 - 10 * pod, t, "#d8cbab",
                                  "#ffd98a", .2, 5)
    r4, _, (m2x, m2y) = _ruka_ekr(sx_m, my_, mh2, -1, mh2 * .44, -152 + 10 * pod, t, "#d8cbab",
                                  "#ffd98a", .6, 5)
    mal += r3 + r4
    # сорочка отклоняется вверх по ходу подъёма
    mal += (f'<path d="M{sx_m-72:.0f},{my_-40:.0f} Q{sx_m:.0f},{my_-72-40*pod:.0f}'
            f' {sx_m+72:.0f},{my_-40:.0f} L{sx_m+58:.0f},{my_-96:.0f}'
            f' Q{sx_m:.0f},{my_-120:.0f} {sx_m-58:.0f},{my_-96:.0f} Z" fill="#e4d9bc"'
            f' opacity=".9" {o(4)}/>')
    s += SL(Z_SRED, mal)
    s += SL(Z_SRED, f'<circle cx="{sx_m:.0f}" cy="{my_-150:.0f}" r="{150+24*pod:.0f}"'
                    f' fill="#ffe9ac" opacity="{.08+.05*pod:.2f}"/>')
    s += SL(Z_SRED, iskra_let(t, sx_m, my_ - 120, 7, 6, 300, .40))
    s += SL(Z_SRED, _polka_s_utvaryu(420, 420, 420, t, 131, 3))
    s += SL(Z_SRED, _lavka_krupno(260, 1050, 440, t, 150))
    s += SL(Z_SRED, _kadushki_i_grabli(1180, 1046, t, 133))
    s += SL(Z_PERED, _vetka_pered(-40, 60, 700, 24, t, 109, "#241c16", 6))
    s += SL(Z_LETIT, sneg_letit(t, 12, 37, .28, .55))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def vorota_lesnoy_obiteli(t):
    """Бревенчатая ограда и тесовые ворота обители среди елей, ворота
    распахнуты, в проёме настоящий осенний лес. Юноша с котомкой идёт к
    воротам со спины. У ворот колода с топором, поленница, улей-борть."""
    rnd = random.Random(115)
    s = nebo("den", t, False, 53)
    s += oblaka(t, 130, 5, 39, .45)

    px_, py_, pw_, ph_ = 700, 230, 790, 500
    put = kontur_proema(px_, py_, pw_, ph_, "arka")
    s += SL(Z_DAL, _vid_za_proemom(put, t, "les", 13)
            + mesto_stoka(px_, py_, pw_, ph_, "arka")
            + f'<path d="{put}" fill="none" stroke="#2a1d12" stroke-width="18"/>')

    # ограда из брёвен по сторонам ворот
    ogr = ""
    for bx, bw in ((-20, 640), (1540, 420)):
        ogr += (f'<rect x="{bx:.0f}" y="300" width="{bw:.0f}" height="520" rx="6"'
                f' fill="url(#brev)" {o(6)}/>')
        for i in range(9):
            ogr += (f'<rect x="{bx:.0f}" y="{306+i*58:.0f}" width="{bw:.0f}" height="50"'
                    f' rx="8" fill="url(#brev)" {o(3)}/>')
        ogr += (f'<path d="M{bx-20:.0f},300 L{bx+bw/2:.0f},230 L{bx+bw+20:.0f},300 Z"'
                f' fill="#4a3a28" {o(5)}/>')
    for sgn, vx in ((-1, px_ - 210), (1, px_ + pw_ + 10)):
        ug = sgn * (-16 + 2 * A.w(t, 4.4, .2))
        ogr += (f'<g transform="rotate({ug:.1f} {vx+(200 if sgn<0 else 0):.0f} {py_+ph_:.0f})">'
                f'<rect x="{vx:.0f}" y="{py_+40:.0f}" width="200" height="{ph_-10:.0f}"'
                f' rx="8" fill="url(#derev)" {o(6)}/>')
        for i in range(4):
            ogr += (f'<rect x="{vx+12+i*48:.0f}" y="{py_+56:.0f}" width="34"'
                    f' height="{ph_-42:.0f}" rx="6" fill="#6a5030" {o(3)}/>')
        ogr += (f'<rect x="{vx+4:.0f}" y="{py_+120:.0f}" width="192" height="24"'
                f' fill="{ZHELEZ}" {o(3)}/>'
                f'<rect x="{vx+4:.0f}" y="{py_+380:.0f}" width="192" height="24"'
                f' fill="{ZHELEZ}" {o(3)}/></g>')
    ogr += (f'<path d="M{px_-80:.0f},{py_+20:.0f} L{px_+pw_*.5:.0f},{py_-80:.0f}'
            f' L{px_+pw_+80:.0f},{py_+20:.0f} Z" fill="#4e3a24" {o(6)}/>'
            f'<rect x="{px_-100:.0f}" y="{py_+14:.0f}" width="{pw_+200:.0f}" height="26"'
            f' rx="9" fill="#5c4830" {o(5)}/>')
    s += SL(Z_SRED, ogr)

    # ели по сторонам ограды
    el = ""
    for i, (ex, eb, eh) in enumerate(((100, 560, 700), (360, 480, 520), (1800, 580, 720),
                                      (1580, 470, 480))):
        kach = 1.4 * A.w(t, 5.0 + i, i * .3)
        el += f'<g transform="rotate({kach:.2f} {ex:.0f} {eb:.0f})">'
        for k in range(4):
            yy = eb - eh * (k / 4.0)
            ww = eh * .38 * (1 - k / 5.2)
            el += (f'<path d="M{ex-ww:.0f},{yy:.0f} L{ex:.0f},{yy-eh*.36:.0f}'
                   f' L{ex+ww:.0f},{yy:.0f} Z" fill="{["#3e4f3e","#35463a"][k%2]}"'
                   f' {o(4)}/>')
        el += (f'<rect x="{ex-14:.0f}" y="{eb-20:.0f}" width="28" height="90"'
               f' fill="#3b2a1a" {o(3)}/></g>')
    s += SL(Z_DAL, el)
    s += SL(Z_SRED, dym(430, 250, t, 5, .26, 300, .36, "#d3dae2", .9))

    zem = f'<rect x="0" y="810" width="{W}" height="270" fill="#4e3f2c"/>'
    zem += _zemlya_faktura(850, 1060, 111, 14)
    zem += _listya(113, 30, 840, 1060)
    zem += _trava(rnd, 10, 870, 1050)
    s += SL(Z_SRED, zem)

    # колода с топором
    s += SL(Z_SRED, f'<ellipse cx="340" cy="880" rx="120" ry="34" fill="#7b5c38" {o(5)}/>'
                    f'<rect x="220" y="880" width="240" height="170" rx="10"'
                    f' fill="url(#derev)" {o(6)}/>'
                    f'<path d="M352,880 L330,790 L300,804 L306,874 Z" fill="url(#zhel)"'
                    f' {o(5)}/>'
                    f'<rect x="318" y="760" width="22" height="60" rx="8"'
                    f' fill="url(#derev)" {o(4)}/>'
                    f'<path d="M306,812 L328,804" stroke="#e6eef6" stroke-width="7"'
                    f' opacity=".7"/>')
    s += SL(Z_SRED, _polenica(20, 700, 190, 300, 115, 24))
    s += SL(Z_SRED, f'<path d="M620,1080 Q820,944 {px_+pw_*.34:.0f},{py_+ph_-8:.0f}'
                    f' L{px_+pw_*.70:.0f},{py_+ph_-8:.0f} Q1240,944 1440,1080 Z"'
                    f' fill="#6a5236" opacity=".85"/>'
                    f'<path d="M680,1078 Q860,952 {px_+pw_*.40:.0f},{py_+ph_-6:.0f}"'
                    f' fill="none" stroke="#7d6243" stroke-width="7" opacity=".6"/>')

    # улей-борть
    s += SL(Z_SRED, f'<path d="M1660,1050 L1640,820 Q1740,786 1840,820 L1820,1050 Z"'
                    f' fill="url(#derev)" {o(6)}/>'
                    f'<ellipse cx="1740" cy="820" rx="100" ry="30" fill="#5b4428" {o(4)}/>'
                    f'<ellipse cx="1740" cy="930" rx="24" ry="16" fill="#2a1d12" {o(3)}/>'
                    f'<rect x="1636" y="880" width="208" height="18" rx="7" fill="#8a6a3c"'
                    f' {o(3)}/>')
    for i in range(5):
        pz = ((t * .7 + i * .2) % 1.0)
        s += SL(Z_SRED, f'<ellipse cx="{1740+120*math.cos(pz*6.283+i):.0f}"'
                        f' cy="{900+60*math.sin(pz*6.283+i*1.7):.0f}" rx="9" ry="6"'
                        f' fill="#d8a14a" opacity=".85"/>')

    # юноша с котомкой идёт к воротам со спины
    vh = A.ease(A.seg(t, .4, 2.0))
    fx, fy, fh = 560 - 90 * vh, 1052 - 40 * vh, 660 - 60 * vh
    yun = figura(fx, fy, fh, t, col="#4a4254", kant="#ffd98a", ph=.2)
    r1, (px2, py2), (ypx, ypy) = _ruka_ekr(fx, fy, fh, 1, fh * .44, 78, t, "#4a4254", "#ffd98a",
                                           .1, 5)
    r2, _, (ylx, yly) = _ruka_ekr(fx, fy, fh, -1, fh * .30, 206, t, "#4a4254", "#ffd98a", .5, 4)
    yun += r1 + r2
    yun += (f'<line x1="{px2:.0f}" y1="{py2-150:.0f}" x2="{px2+10:.0f}" y2="{fy+4:.0f}"'
            f' stroke="url(#derev)" stroke-width="16" stroke-linecap="round"/>')
    # котомка за плечами
    yun += (f'<path d="M{fx-fh*.34:.0f},{fy-fh*.44:.0f}'
            f' Q{fx-fh*.44:.0f},{fy-fh*.30:.0f} {fx-fh*.34:.0f},{fy-fh*.16:.0f}'
            f' Q{fx-fh*.22:.0f},{fy-fh*.10:.0f} {fx-fh*.16:.0f},{fy-fh*.24:.0f}'
            f' Q{fx-fh*.16:.0f},{fy-fh*.38:.0f} {fx-fh*.34:.0f},{fy-fh*.44:.0f} Z"'
            f' fill="#7a6342" {o(5)}/>'
            f'<path d="M{fx-fh*.30:.0f},{fy-fh*.44:.0f} Q{fx-fh*.22:.0f},'
            f'{fy-fh*.56:.0f} {fx-fh*.12:.0f},{fy-fh*.52:.0f}" fill="none"'
            f' stroke="#8a7a58" stroke-width="9"/>'
            f'<path d="M{fx-fh*.30:.0f},{fy-fh*.32:.0f} L{fx-fh*.18:.0f},'
            f'{fy-fh*.28:.0f}" stroke="#5e4a2e" stroke-width="6"/>')
    s += SL(Z_SRED, yun + ten(fx, fy + 6, 110 - 20 * vh, 20, .45))
    s += SL(Z_SRED, _kadushki_i_grabli(560, 1064, t, 143))
    s += SL(Z_SRED, _polka_s_utvaryu(240, 700, 400, t, 153, 3))
    s += SL(Z_SRED, _polenica(1600, 740, 280, 230, 401, 24))
    s += SL(Z_SRED, _dvorovaya_utvar(880, 1072, 420, t, 403, ["korob", "meshok"]))
    s += SL(Z_SRED, _listya(155, 22, 880, 1060))
    s += SL(Z_SRED, _dvorovaya_utvar(1240, 1070, 360, t, 145, ["meshok", "korzina"]))
    s += SL(Z_PERED, _stolb_pered(1874, 106, "#1d1611", 0, H))
    s += SL(Z_LETIT, sneg_letit(t, 12, 41, .3, .6))
    s += ramka_pp("oba")
    s += vinetka(.42)
    return s


def gorozhane_zovut_ionu(t):
    """Городская площадь: толпа со спины — шапки, платки, посохи. Седобородый
    старец на крыльце, руки сложены на посохе; старшина подаёт ему на рушнике
    хлеб-соль. Над площадью летят вверх шапки. У крыльца бочки, сани, собака."""
    rnd = random.Random(116)
    s = nebo("den", t, False, 57)
    s += oblaka(t, 120, 6, 43, .5)
    s += SL(Z_DAL, _derevnya_ryad(400, t, 117, ((130, 400), (1800, 420))))
    # палаты за крыльцом
    s += SL(Z_DAL, brevna(420, 60, 1100, 560, 92)
            + f'<rect x="420" y="60" width="1100" height="560" fill="none" {o(9)}/>')
    s += SL(Z_DAL, okno_izby(520, 180, 260, 230, t, svet=True)
            + okno_izby(1180, 180, 260, 230, t, svet=True)
            + teplo(650, 300, 230, 190, .40) + teplo(1310, 300, 230, 190, .40))
    s += SL(Z_DAL, dver(860, 150, 300, 480, .0, "url(#derev)", True, False))
    s += SL(Z_DAL, dym(1800, 200, t, 5, .26, 280, .34, "#d3dae2", .9))

    zem = f'<rect x="0" y="700" width="{W}" height="380" fill="#4e3f2c"/>'
    zem += _zemlya_faktura(760, 1060, 119, 16)
    zem += _listya(121, 24, 760, 1060)
    s += SL(Z_SRED, zem)
    s += SL(Z_SRED, _kryl_co(620, 620, 700, 200, t, 4, True, True))

    # бочки, сани, собака у крыльца
    s += SL(Z_SRED, _dvorovaya_utvar(40, 880, 520, t, 123, ["kadka", "kadka", "korob"]))
    sani = (f'<path d="M1480,980 Q1560,936 1800,936 L1812,980 Z" fill="url(#derev)"'
            f' {o(5)}/>'
            f'<rect x="1500" y="880" width="300" height="60" rx="10" fill="#5b4428"'
            f' {o(5)}/>'
            f'<line x1="1530" y1="940" x2="1530" y2="980" stroke="#4a3522"'
            f' stroke-width="14"/>'
            f'<line x1="1740" y1="940" x2="1740" y2="980" stroke="#4a3522"'
            f' stroke-width="14"/>'
            f'<path d="M1470,984 Q1580,962 1824,962" fill="none" stroke="{ZHELEZ}"'
            f' stroke-width="10"/>')
    s += SL(Z_SRED, sani)
    s += SL(Z_SRED, f'<ellipse cx="1360" cy="1040" rx="94" ry="40" fill="#54402a"'
                    f' {o(4)}/>'
                    f'<ellipse cx="1278" cy="1012" rx="42" ry="35" fill="#54402a" {o(4)}/>'
                    f'<path d="M1248,994 L1238,956 L1274,974 Z" fill="#43321f" {o(3)}/>'
                    f'<circle cx="1262" cy="1008" r="5" fill="#120c08"/>'
                    f'<path d="M1448,1026 Q1498,{988-16*A.w(t,1.4,.2):.0f} 1512,1038"'
                    f' fill="none" stroke="#54402a" stroke-width="15"'
                    f' stroke-linecap="round"/>')

    # толпа со спины: шапки, платки, посохи
    # толпа: три глубины, рост и цвет у каждого свой, шаг неровный
    CVET = ["#39323f", "#4a3b2a", "#2f3a44", "#523340", "#3d4a3a", "#5a4a32",
            "#2e3a34", "#4a3346", "#3a4452", "#54412c"]
    # глубины разведены сильнее (0.54 / 0.80 / 1.10): иначе крупный из
    # дальнего ряда оказывался по соседству с крупным из ближнего и
    # кратность роста падала до 1.05
    ryady = ((1, 0.54, 936, 150), (0, 0.80, 1012, 196), (2, 1.10, 1074, 238))
    for sloy, msh, ty0, step in ryady:
        tol = ""
        x0 = 40 + sloy * 70
        i = 0
        while x0 < W + 80:
            # РОСТ СОСЕДЕЙ ОТЛИЧАЕТСЯ НЕ МЕНЬШЕ ЧЕМ В ПОЛТОРА РАЗА, ШАГ
            # РВАНЫЙ, ЧАСТЬ ФИГУР СО СПИНЫ И В ПРОФИЛЬ, ДВОЕ-ТРОЕ СТОЯТ
            # ВПЛОТНУЮ И ПЕРЕКРЫВАЮТ ДРУГ ДРУГА. Осмотр 15.11, второй заход:
            # «внизу снова читается ровный ряд одинаковых мелких фигур с
            # равным шагом» — прежнего разброса ±52 по росту и ±62 по базе
            # глазу не хватило, ряд всё равно складывался в орнамент.
            krup = (i % 2 == 0)              # строго через одного
            th = (362 if krup else 150) * msh * rnd.uniform(.92, 1.08)
            ty = ty0 - rnd.uniform(0, 70) - (0 if krup else 38)
            col = CVET[rnd.randrange(len(CVET))]
            pl = rnd.random() < .42
            d = figura(x0, ty, th, t, col=col, kant="#cfe4f5", platok=pl,
                       ph=rnd.uniform(0, 1), shapka=not pl,
                       profil=rnd.random() < .50,
                       lico=rnd.random() > .32,
                       naklon=rnd.uniform(-15, 15),
                       op=.72 + .28 * msh)
            if rnd.random() < .32:
                rr, (qx, qy), (a1x, a1y) = _ruka_ekr(x0, ty, th, 1, th * .36,
                                                     62 + rnd.uniform(-18, 18), t, col,
                                                     "#cfe4f5", rnd.uniform(0, 1), 4)
                d += rr + (f'<line x1="{qx:.0f}" y1="{qy-th*.58:.0f}"'
                           f' x2="{qx+8:.0f}" y2="{ty+4:.0f}" stroke="url(#derev)"'
                           f' stroke-width="{11*msh:.0f}" stroke-linecap="round"/>')
            tol += d
            # треть шагов — почти вплотную: фигуры заходят одна за другую
            x0 += step * (rnd.uniform(.24, .44) if rnd.random() < .34
                          else rnd.uniform(.78, 1.62))
            i += 1
        s += SL(Z_DAL if sloy == 1 else Z_SRED, tol)

    # шапки летят вверх
    # ШАПКИ ЛЕТЯТ ВРАЗНОБОЙ: было ровно девять штук через 200 px — ряд
    # одинаковых предметов равным шагом читается узором, а не радостью
    shap = ""
    for i, (hx_, hs_, hf_) in enumerate(((150, 1.14, .00), (372, .82, .37),
                                         (470, 1.04, .62), (690, .72, .18),
                                         (902, 1.22, .81), (1024, .88, .44),
                                         (1290, .96, .07), (1416, 1.10, .70),
                                         (1664, .78, .29), (1842, 1.02, .52))):
        p = ((t * .55 + hf_) % 1.0)
        hy_ = 1000 - (620 + 180 * hs_) * math.sin(math.pi * p * .9)
        rot = 240 * p + i * 47
        shap += (f'<g transform="rotate({rot:.0f} {hx_:.0f} {hy_:.0f})">'
                 f'<path d="M{hx_-44:.0f},{hy_:.0f} Q{hx_-30:.0f},{hy_-56:.0f}'
                 f' {hx_:.0f},{hy_-58:.0f} Q{hx_+30:.0f},{hy_-56:.0f}'
                 f' {hx_+44:.0f},{hy_:.0f} Z"'
                 f' fill="{["#3a3040","#5e4a3a","#4a3b2a","#4a3346"][i%4]}" {o(4)}/>'
                 f'<rect x="{hx_-54:.0f}" y="{hy_-10:.0f}" width="108" height="26" rx="12"'
                 f' fill="#6b5236" {o(3)}/></g>')
    s += SL(Z_SRED, shap)

    # старец на крыльце, руки сложены на посохе
    sk = A.ease(A.seg(t, 1.0, 1.2))
    sx, sy, sh = 1120, 636, 620
    star = figura(sx, sy, sh, t, col="#2e2a34", kant="#ffd98a", ph=.2, boroda=True,
                  naklon=7 * sk)
    r1, (hx1, hy1), (spx, spy) = _ruka_ekr(sx, sy, sh, 1, sh * .40, 62, t, "#2e2a34", "#ffd98a",
                                           .1, 3)
    r2, _, (slx, sly) = _ruka_ekr(sx, sy, sh, -1, sh * .40, 118, t, "#2e2a34", "#ffd98a", .5, 3)
    star += r1 + r2
    star += (f'<line x1="{sx+10:.0f}" y1="{sy-sh*.60:.0f}" x2="{sx+18:.0f}" y2="{sy+6:.0f}"'
             f' stroke="url(#derev)" stroke-width="18" stroke-linecap="round"/>'
             f'<circle cx="{sx+8:.0f}" cy="{sy-sh*.62:.0f}" r="20" fill="#5e442a" {o(3)}/>')
    # борода от подбородка, лежит на груди
    star += (f'<path d="M{sx-50:.0f},{sy-sh*.74:.0f} Q{sx:.0f},{sy-sh*.40+8*sk:.0f}'
             f' {sx+50:.0f},{sy-sh*.74:.0f} Q{sx:.0f},{sy-sh*.66:.0f}'
             f' {sx-50:.0f},{sy-sh*.74:.0f} Z" fill="#d8d2c4" opacity=".95" {o(4)}/>')
    s += SL(Z_SRED, star)

    # старшина подаёт хлеб-соль на рушнике
    ox, oy, oh = 700, 860, 520
    ost = figura(ox, oy, oh, t, col="#4b3550", kant="#ffd98a", ph=.5, boroda=True)
    r3, (q1x, q1y), (o1x, o1y) = _ruka_ekr(ox, oy, oh, 1, oh * .44, -48, t, "#4b3550", "#ffd98a",
                                           .2, 4)
    r4, (q2x, q2y), (o2x, o2y) = _ruka_ekr(ox, oy, oh, -1, oh * .44, -22, t, "#4b3550",
                                           "#ffd98a", .6, 4)
    ost += r3 + r4
    rx_, ry_ = (q1x + q2x) / 2, (q1y + q2y) / 2
    ost += (f'<path d="M{rx_-150:.0f},{ry_:.0f} Q{rx_:.0f},{ry_-50:.0f}'
            f' {rx_+150:.0f},{ry_:.0f} L{rx_+150:.0f},{ry_+40:.0f}'
            f' Q{rx_:.0f},{ry_-10:.0f} {rx_-150:.0f},{ry_+40:.0f} Z" fill="{RUSH}" {o(4)}/>')
    for i in range(5):
        ux = rx_ - 124 + i * 62
        ost += (f'<path d="M{ux:.0f},{ry_+8:.0f} L{ux+16:.0f},{ry_-12:.0f}'
                f' L{ux+32:.0f},{ry_+8:.0f} Z" fill="{KRAS}" opacity=".75"/>')
    ost += karavay(rx_, ry_ - 26, 1.5, False)
    s += SL(Z_SRED, ost)
    s += SL(Z_PERED, _stolb_pered(-6, 96, "#1d1611", 0, H))
    s += SL(Z_LETIT, sneg_letit(t, 12, 45, .28, .55))
    s += ramka_pp("oba")
    s += vinetka(.42)
    return s


def tri_dela_vladyki(t):
    """Три сцены по словам, старец везде со спины: держит весы над двумя
    спорщиками; заслоняет вдову с ребёнком от купца с долговой книгой;
    подаёт нищему каравай. Борода белеет от сцены к сцене."""
    rnd = random.Random(117)
    pol = 790
    s = _stena_gornicy(t, 11, True, pol)
    s += SL(Z_DAL, svody(t, "#4b443b", 3))
    for dx in (640, 1280):
        s += SL(Z_DAL, f'<rect x="{dx:.0f}" y="0" width="34" height="{pol:.0f}"'
                       f' fill="#4e3220" opacity=".7"/>')
    for i, ox in enumerate((250, 940, 1620)):
        s += SL(Z_DAL, okno_izby(ox - 110, 150, 230, 210, t, svet=False, moroz=.35))
        s += SL(Z_DAL, zanaveska(ox - 110, 140, 130, 100, TKAN, t, 1))
    s += SL(Z_DAL, _polka_s_utvaryu(420, 430, 420, t, 125, 3)
            + _polka_s_utvaryu(1380, 430, 420, t, 127, 3))

    # свечи в подсвечниках — по свече на каждую сцену
    for i, sx_ in enumerate((430, 1080, 1760)):
        s += SL(Z_SRED, f'<rect x="{sx_-34:.0f}" y="{pol-26:.0f}" width="68" height="26"'
                        f' rx="9" fill="{ZHELEZ}" {o(4)}/>'
                        f'<rect x="{sx_-12:.0f}" y="{pol-96:.0f}" width="24" height="76"'
                        f' rx="8" fill="{ZHELEZ}" {o(3)}/>'
                        + svecha(sx_, pol - 96, t, i * .3, 1.5))
    s += SL(Z_SRED, teplo(1080, 640, 520, 420, .36))

    for i, (lx, ly, lw) in enumerate(((96, 1046, 440), (806, 1056, 350),
                                      (1486, 1038, 480))):
        s += SL(Z_SRED, _lavka_krupno(lx, ly, lw, t, 120 + i * 14, i == 1))
    s += SL(Z_SRED, mebel_hlam(60, 900, 320, t, 23))

    prost = ""
    for dx2 in (650, 1300):
        prost += (f'<rect x="{dx2:.0f}" y="0" width="54" height="{pol+120:.0f}"'
                  f' fill="#2a1d12" {o(6)}/>'
                  f'<rect x="{dx2+10:.0f}" y="0" width="16" height="{pol+120:.0f}"'
                  f' fill="#3e2c1c" opacity=".8"/>'
                  f'<path d="M{dx2-34:.0f},84 L{dx2+88:.0f},84 L{dx2+74:.0f},130'
                  f' L{dx2-20:.0f},130 Z" fill="#4e3a24" {o(4)}/>')
    s += SL(Z_SRED, prost)
    pr = (t * .34) % 1.0
    # ── первая: старец на скамье держит весы, чаши ровные
    ax, ay, ah = 330, 920, 480
    rov = A.ease(A.seg(t, .4, 1.1))
    st1 = figura(ax, ay, ah, t, col="#2e2a34", kant="#ffd98a", ph=.2, boroda=True)
    r1, (v1x, v1y), (p1x, p1y) = _ruka_ekr(ax, ay, ah, 1, ah * .44, -28, t, "#2e2a34", "#ffd98a",
                                           .1, 4)
    r2, _, (p2x, p2y) = _ruka_ekr(ax, ay, ah, -1, ah * .40, 48, t, "#2e2a34", "#ffd98a", .5, 4)
    st1 += r1 + r2
    st1 += (f'<path d="M{ax-44:.0f},{ay-ah*.72:.0f} Q{ax:.0f},{ay-ah*.46:.0f}'
            f' {ax+44:.0f},{ay-ah*.72:.0f} Z" fill="#cfc8ba" opacity=".9" {o(3)}/>')
    nak = 14 * (1 - rov)
    ves = (f'<g transform="rotate({nak:.1f} {v1x:.0f} {v1y:.0f})">'
           f'<rect x="{v1x-130:.0f}" y="{v1y-9:.0f}" width="260" height="16" rx="7"'
           f' fill="{ZHELEZ}" {o(3)}/>'
           f'<line x1="{v1x-118:.0f}" y1="{v1y:.0f}" x2="{v1x-118:.0f}" y2="{v1y+62:.0f}"'
           f' stroke="{ZHELEZ}" stroke-width="4"/>'
           f'<line x1="{v1x+118:.0f}" y1="{v1y:.0f}" x2="{v1x+118:.0f}" y2="{v1y+62:.0f}"'
           f' stroke="{ZHELEZ}" stroke-width="4"/>'
           f'<path d="M{v1x-168:.0f},{v1y+62:.0f} Q{v1x-118:.0f},{v1y+112:.0f}'
           f' {v1x-68:.0f},{v1y+62:.0f} Z" fill="url(#zhel)" {o(4)}/>'
           f'<path d="M{v1x+68:.0f},{v1y+62:.0f} Q{v1x+118:.0f},{v1y+112:.0f}'
           f' {v1x+168:.0f},{v1y+62:.0f} Z" fill="url(#zhel)" {o(4)}/></g>')
    s += SL(Z_SRED, st1 + ves)
    # НИЖНИЙ РЯД ВРАЗНОБОЙ (осмотр 15.11, второй заход: «то же самое в нижнем
    # ряду»). Рост соседей 452 · 268 · 236 — каждый следующий в полтора-два
    # раза иной, базы 1046-1062-1030 разные, шаги 214 и 112 рваные, третий
    # зритель заходит на спорщика, двое из трёх даны со спины и в профиль.
    SPOR = (("#5a3340", 104, 1046, 452, -11, 0, 1, 1),
            ("#3d4a3a", 318, 1062, 268, 13, 1, 0, 0),
            ("#54412c", 430, 1030, 236, -6, 0, 0, 1))
    for i, (col2, sx_, sy2, sh2, nak2, shap2, bor2, prof2) in enumerate(SPOR):
        d = figura(sx_, sy2, sh2, t, col=col2, kant="#cfe4f5", ph=.3 + i * .2,
                   shapka=bool(shap2), boroda=bool(bor2), profil=bool(prof2),
                   lico=(i != 2), naklon=nak2)
        rr, _, (q1x, q1y) = _ruka(sx_, sy2, sh2, 1 if i == 1 else -1,
                                  sh2 * (.46 if i == 1 else .38), -34 + 66 * (i == 1),
                                  t, col2, "#cfe4f5", i * .3, 6)
        s += SL(Z_SRED, d + rr)

    # ── вторая: заслоняет вдову с ребёнком от купца с книгой
    bx_, by_, bh_ = 1000, 1016, 596
    zasl = A.ease(A.seg(t, 2.0, 1.1))
    st2 = figura(bx_, by_, bh_, t, col="#2e2a34", kant="#ffd98a", ph=.4, boroda=True,
                 naklon=-8 * zasl)
    r3, _, (p3x, p3y) = _ruka_ekr(bx_, by_, bh_, -1, bh_ * .52, -178 + 16 * zasl, t, "#2e2a34",
                                  "#ffd98a", .2, 4)
    r4, _, (p4x, p4y) = _ruka_ekr(bx_, by_, bh_, 1, bh_ * .38, 36, t, "#2e2a34", "#ffd98a", .6, 4)
    st2 += r3 + r4
    st2 += (f'<path d="M{bx_-48:.0f},{by_-bh_*.72:.0f} Q{bx_:.0f},{by_-bh_*.40:.0f}'
            f' {bx_+48:.0f},{by_-bh_*.72:.0f} Z" fill="#e2ded2" opacity=".95" {o(3)}/>')
    s += SL(Z_SRED, st2)
    vd = figura(798, 1044, 486, t, col="#4e3a50", kant="#cfe4f5", platok=True, ph=.7,
                naklon=6)
    s += SL(Z_SRED, vd + figura(700, 1058, 214, t, col="#8e8068", kant="#cfe4f5",
                                ph=.3, profil=True))
    kx_, ky_, kh_ = 1230, 1038, 470
    kup = figura(kx_, ky_, kh_, t, col="#4b3550", kant="#ffd98a", ph=.5, boroda=True,
                 profil=True, naklon=-7)
    r5, (bkx, bky), (p5x, p5y) = _ruka_ekr(kx_, ky_, kh_, -1, kh_ * .40, -156, t, "#4b3550",
                                           "#ffd98a", .3, 4)
    kup += r5
    kup += (f'<path d="M{bkx-70:.0f},{bky-56:.0f} L{bkx+70:.0f},{bky-56:.0f}'
            f' L{bkx+70:.0f},{bky+56:.0f} L{bkx-70:.0f},{bky+56:.0f} Z" fill="#6b4a2c"'
            f' {o(5)}/>'
            f'<rect x="{bkx-62:.0f}" y="{bky-48:.0f}" width="124" height="96" rx="5"'
            f' fill="#e4dcc4" {o(3)}/>')
    for i in range(4):
        kup += (f'<path d="M{bkx-46:.0f},{bky-28+i*24:.0f} Q{bkx-10:.0f},'
                f'{bky-38+i*24:.0f} {bkx+28:.0f},{bky-28+i*24:.0f}" fill="none"'
                f' stroke="#8a7a58" stroke-width="4"/>')
    s += SL(Z_SRED, kup)

    # ── третья: подаёт нищему каравай
    cx_, cy_, ch_ = 1626, 994, 524
    dat = A.ease(A.seg(t, 3.6, 1.1))
    st3 = figura(cx_, cy_, ch_, t, col="#2e2a34", kant="#ffd98a", ph=.6, boroda=True,
                 profil=True, naklon=9 * dat)
    r6, (k1x, k1y), (p6x, p6y) = _ruka_ekr(cx_, cy_, ch_, 1, ch_ * .44, 4 - 24 * dat, t,
                                           "#2e2a34", "#ffd98a", .1, 3)
    r7, (k2x, k2y), (p7x, p7y) = _ruka_ekr(cx_, cy_, ch_, -1, ch_ * .44, 30 - 24 * dat, t,
                                           "#2e2a34", "#ffd98a", .5, 3)
    st3 += r6 + r7
    st3 += (f'<path d="M{cx_-52:.0f},{cy_-ch_*.72:.0f} Q{cx_:.0f},{cy_-ch_*.36:.0f}'
            f' {cx_+52:.0f},{cy_-ch_*.72:.0f} Z" fill="#f2efe6" opacity=".95" {o(3)}/>')
    s += SL(Z_SRED, st3)
    # каравай идёт в ПРАВОЙ руке, наружу к нищему: от середины между кистями
    # он ложился старцу на грудь, когда левый рукав прижимался к телу
    kar_x = k1x + _predmet_naruzhu(cx_, ch_, k1x, 230) + 60 * dat
    s += SL(Z_SRED, karavay(kar_x, k1y + 24, 1.5, True))
    nx_, ny_, nh_ = 1786, 1066, 306
    nish = figura(nx_, ny_, nh_, t, col="#6a5a46", kant="#cfe4f5", ph=.8, boroda=True,
                  naklon=15, profil=True)
    r8, _, (p8x, p8y) = _ruka_ekr(nx_, ny_, nh_, -1, nh_ * .46, -164, t, "#6a5a46", "#cfe4f5",
                                  .4, 5)
    s += SL(Z_SRED, nish + r8)
    # третий зритель третьего пролёта: заходит на владыку и ломает линию
    zr = figura(1450, 1038, 240, t, col="#2e3a34", kant="#cfe4f5", ph=.8,
                shapka=True, lico=False, naklon=9)
    rz, _, _ = _ruka(1450, 1038, 240, -1, 240 * .42, 64, t, "#2e3a34",
                     "#cfe4f5", .8, 4)
    s += SL(Z_SRED, zr + rz + ten(1450, 1044, 56, 12, .4))
    s += SL(Z_PERED, _stolb_pered(-4, 84, "#140f0b", 0, H))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def tihiy_uchenik_v_shkolnom_klasse(t):
    """Школьный класс: парты с откидными крышками, чёрная доска, глобус,
    чернильницы, портфели на крючках. Трое на перемене дерутся портфелями,
    у стены за последней партой сидит тихий мальчик в очках; следующий миг —
    он у доски, в правой руке мел, в левой тряпка."""
    rnd = random.Random(118)
    pol = 820
    s = f'<rect width="{W}" height="{H}" fill="#3b3a36"/>'
    s += SL(Z_DAL, doski(0, 0, W, pol, 70, False, "dosk"))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-130:.0f}" width="{W}" height="26"'
                   f' fill="#5b4428" opacity=".85"/>'
                   f'<rect x="0" y="{pol-20:.0f}" width="{W}" height="36"'
                   f' fill="#2f2a22" opacity=".85"/>')
    s += SL(Z_DAL, polovicy(pol + 20))

    # чёрная доска
    dx_, dy_, dw, dh = 250, 150, 1060, 430
    dos = (f'<rect x="{dx_-24:.0f}" y="{dy_-24:.0f}" width="{dw+48:.0f}"'
           f' height="{dh+48:.0f}" rx="10" fill="#6b5a3c" {o(6)}/>'
           f'<rect x="{dx_:.0f}" y="{dy_:.0f}" width="{dw:.0f}" height="{dh:.0f}"'
           f' rx="6" fill="#23302a" {o(4)}/>'
           f'<rect x="{dx_-30:.0f}" y="{dy_+dh+24:.0f}" width="{dw+60:.0f}" height="26"'
           f' rx="8" fill="#7a6342" {o(4)}/>')
    # решённая задача — волнистыми строками, букв не рисуем
    pis = min(1.0, max(.0, (t - 2.6) * .55))
    for i in range(5):
        ly = dy_ + 90 + i * 66
        dl = (dw - 160) * min(1.0, max(.0, pis * 5 - i))
        if dl > 4:
            dos += (f'<path d="M{dx_+70:.0f},{ly:.0f} Q{dx_+70+dl*.25:.0f},{ly-18:.0f}'
                    f' {dx_+70+dl*.5:.0f},{ly:.0f} Q{dx_+70+dl*.75:.0f},{ly+18:.0f}'
                    f' {dx_+70+dl:.0f},{ly:.0f}" fill="none" stroke="#e8ecd8"'
                    f' stroke-width="7" opacity=".9"/>')
    # ДОСКА НЕ ПУСТАЯ (осмотр 15.11: до 2,6 с это было ровное зелёное поле на
    # четверть кадра). На ней всегда есть прошлый урок: чертёж с прямым углом
    # и штриховкой, окружность с радиусом, два столбика палочек, уголок
    # деления, затёртые разводы от тряпки, лоток с мелом и указка.
    tri = (dx_ + 118, dy_ + 338)
    dos += (f'<path d="M{tri[0]:.0f},{tri[1]:.0f} L{tri[0]+250:.0f},{tri[1]:.0f}'
            f' L{tri[0]:.0f},{tri[1]-172:.0f} Z" fill="none" stroke="#dfe6cf"'
            f' stroke-width="6" opacity=".88"/>'
            f'<rect x="{tri[0]+4:.0f}" y="{tri[1]-34:.0f}" width="30" height="30"'
            f' fill="none" stroke="#dfe6cf" stroke-width="4" opacity=".8"/>')
    for i in range(7):
        dos += (f'<line x1="{tri[0]+26+i*30:.0f}" y1="{tri[1]:.0f}"'
                f' x2="{tri[0]+6+i*30:.0f}" y2="{tri[1]-24-i*6:.0f}"'
                f' stroke="#c8d2bc" stroke-width="3" opacity=".7"/>')
    okr = (dx_ + 560, dy_ + 262)
    dos += (f'<circle cx="{okr[0]:.0f}" cy="{okr[1]:.0f}" r="96" fill="none"'
            f' stroke="#dfe6cf" stroke-width="6" opacity=".88"/>'
            f'<line x1="{okr[0]:.0f}" y1="{okr[1]:.0f}" x2="{okr[0]+68:.0f}"'
            f' y2="{okr[1]-68:.0f}" stroke="#dfe6cf" stroke-width="5" opacity=".8"/>'
            f'<circle cx="{okr[0]:.0f}" cy="{okr[1]:.0f}" r="7" fill="#e8ecd8"'
            f' opacity=".9"/>')
    for st_ in (0, 1):
        for i in range(6):
            dos += (f'<line x1="{dx_+770+st_*86+i*13:.0f}" y1="{dy_+200:.0f}"'
                    f' x2="{dx_+766+st_*86+i*13:.0f}" y2="{dy_+268:.0f}"'
                    f' stroke="#dfe6cf" stroke-width="5" opacity=".82"/>')
    dos += (f'<path d="M{dx_+760:.0f},{dy_+300:.0f} h190 M{dx_+950:.0f},{dy_+300:.0f}'
            f' v76" fill="none" stroke="#dfe6cf" stroke-width="5" opacity=".85"/>'
            f'<path d="M{dx_+770:.0f},{dy_+348:.0f} q40,-20 86,2 q44,22 92,-6"'
            f' fill="none" stroke="#c8d2bc" stroke-width="6" opacity=".7"/>')
    for i, (ex_, ew) in enumerate(((dx_ + 300, 240), (dx_ + 690, 190),
                                   (dx_ + 120, 150))):
        dos += (f'<ellipse cx="{ex_:.0f}" cy="{dy_+56+i*34:.0f}" rx="{ew:.0f}"'
                f' ry="26" fill="#cfe0c8" opacity=".10"/>')
    dos += (f'<path d="M{dx_+60:.0f},{dy_+46:.0f} h420" stroke="#dfe6cf"'
            f' stroke-width="5" opacity=".55"/>')
    for i, mx_ in enumerate((dx_ + 70, dx_ + 118, dx_ + 158)):
        dos += (f'<rect x="{mx_:.0f}" y="{dy_+dh+26:.0f}" width="{34-i*5:.0f}"'
                f' height="18" rx="7" fill="#f2efe2" {o(2)}/>')
    dos += (f'<rect x="{dx_+230:.0f}" y="{dy_+dh+22:.0f}" width="86" height="26"'
            f' rx="9" fill="#5c87a8" {o(3)}/>'
            f'<rect x="{dx_+250:.0f}" y="{dy_+dh+16:.0f}" width="48" height="12"'
            f' rx="5" fill="#e4dcc4" opacity=".8"/>'
            f'<g transform="rotate(-72 {dx_+dw-40:.0f} {dy_+dh+40:.0f})">'
            f'<rect x="{dx_+dw-48:.0f}" y="{dy_+dh+40:.0f}" width="16" height="520"'
            f' rx="7" fill="url(#derev)" {o(3)}/>'
            f'<circle cx="{dx_+dw-40:.0f}" cy="{dy_+dh+44:.0f}" r="15"'
            f' fill="#5e442a" {o(2)}/></g>')
    s += SL(Z_SRED, dos)

    # глобус, чернильницы, портфели на крючках, карта-рейка
    gl = 8 * A.w(t, 4.0, .2)
    s += SL(Z_SRED, f'<rect x="1545" y="470" width="30" height="110" rx="9"'
                    f' fill="#5b4428" {o(4)}/>'
                    f'<ellipse cx="1560" cy="590" rx="66" ry="18" fill="#4a3522" {o(4)}/>'
                    f'<g transform="translate(335 0)">'
                    f'<g transform="rotate({gl:.1f} 1225 370)">'
                    f'<circle cx="1225" cy="370" r="104" fill="#5c87a8" {o(5)}/>'
                    f'<path d="M1150,330 Q1200,300 1256,336 Q1300,364 1270,404'
                    f' Q1220,430 1176,398 Z" fill="#6f9a5e" {o(3)}/>'
                    f'<path d="M1130,392 Q1180,420 1240,430" fill="none" stroke="#6f9a5e"'
                    f' stroke-width="18" opacity=".85"/>'
                    f'<path d="M1121,370 L1329,370" stroke="#2a3a46" stroke-width="4"'
                    f' opacity=".6"/>'
                    f'<path d="M1225,266 Q1310,370 1225,474" fill="none" stroke="{ZHELEZ}"'
                    f' stroke-width="11"/></g></g>')
    kr = ""
    for i in range(5):
        hx = 1230 + i * 92
        kch = 3.0 * A.w(t, 2.6, i * .3)
        kr += (f'<rect x="{hx-6:.0f}" y="188" width="12" height="36" fill="{ZHELEZ}"'
               f' {o(2)}/>'
               f'<g transform="rotate({kch:.1f} {hx:.0f} 220)">'
               f'<rect x="{hx-42:.0f}" y="220" width="84" height="104" rx="9"'
               f' fill="{["#4a3522","#5e3a2a","#3a4452","#5a4a2e","#4e3a50"][i]}" {o(4)}/>'
               f'<rect x="{hx-42:.0f}" y="254" width="84" height="16" fill="#2f2419"'
               f' opacity=".7"/>'
               f'<rect x="{hx-12:.0f}" y="212" width="24" height="18" rx="6"'
               f' fill="{ZHELEZ}" {o(2)}/></g>')
    s += SL(Z_SRED, kr)
    s += SL(Z_SRED, tusklaya_lampochka(980, 80, t, 1.8, True))
    s += SL(Z_SRED, _polka_s_utvaryu(1380, 700, 460, t, 343, 4))
    s += SL(Z_SRED, f'<rect x="300" y="624" width="900" height="30" rx="10"'
                    f' fill="url(#dosk)" {o(6)}/>'
                    f'<rect x="330" y="654" width="840" height="120" rx="8"'
                    f' fill="#5e4a3a" {o(5)}/>')
    PORTF = ["#3a4452", "#5a3340", "#4a3b2a", "#3d4a3a", "#4e3a50", "#5e3a2a"]
    for i in range(6):
        s += SL(Z_SRED, f'<rect x="{356+i*140:.0f}" y="668" width="110" height="92"'
                        f' rx="6" fill="{PORTF[i]}" {o(3)}/>')
    s += SL(Z_SRED, teplo(980, 300, 420, 320, .34))

    # парты рядами
    def parta(px, py, pw, ph2, col="url(#derev)"):
        g = (f'<path d="M{px:.0f},{py-ph2:.0f} L{px+pw:.0f},{py-ph2:.0f}'
             f' L{px+pw:.0f},{py-ph2+34:.0f} L{px:.0f},{py-ph2+46:.0f} Z"'
             f' fill="{col}" {o(5)}/>'
             f'<rect x="{px:.0f}" y="{py-ph2+46:.0f}" width="{pw:.0f}" height="20"'
             f' fill="#3a2a1a" opacity=".8"/>'
             f'<rect x="{px+16:.0f}" y="{py-ph2+66:.0f}" width="30"'
             f' height="{ph2-66:.0f}" rx="8" fill="#4a3522" {o(3)}/>'
             f'<rect x="{px+pw-46:.0f}" y="{py-ph2+66:.0f}" width="30"'
             f' height="{ph2-66:.0f}" rx="8" fill="#4a3522" {o(3)}/>'
             f'<rect x="{px:.0f}" y="{py-ph2*.46:.0f}" width="{pw:.0f}" height="24"'
             f' rx="8" fill="url(#dosk)" {o(4)}/>'
             f'<circle cx="{px+pw-70:.0f}" cy="{py-ph2+22:.0f}" r="18" fill="#2a3a46"'
             f' {o(3)}/>')
        return g
    s += SL(Z_SRED, parta(30, 1012, 490, 236) + parta(600, 1012, 490, 236)
            + parta(1170, 1012, 490, 236))
    s += SL(Z_SRED, parta(1390, 888, 470, 206))
    s += SL(Z_SRED, f'<rect x="1380" y="60" width="440" height="30" rx="10"'
                    f' fill="#5b4428" {o(5)}/>'
                    f'<rect x="1400" y="90" width="400" height="300" rx="8"'
                    f' fill="#cfd8d2" {o(5)}/>'
                    f'<path d="M1430,210 Q1520,160 1620,210 Q1710,260 1780,210"'
                    f' fill="none" stroke="#6f9a5e" stroke-width="14" opacity=".8"/>'
                    f'<path d="M1420,290 Q1540,250 1660,296 Q1740,324 1790,292"'
                    f' fill="none" stroke="#5c87a8" stroke-width="12" opacity=".75"/>')
    s += SL(Z_SRED, _dvorovaya_utvar(560, 840, 460, t, 393, ["korob", "korzina"]))
    s += SL(Z_SRED, f'<rect x="60" y="640" width="300" height="170" rx="10"'
                    f' fill="url(#derev)" {o(5)}/>'
                    f'<rect x="60" y="640" width="300" height="22" rx="7"'
                    f' fill="#5b4428" {o(4)}/>')
    for i in range(4):
        s += SL(Z_SRED, f'<rect x="{84+i*70:.0f}" y="672" width="52" height="118"'
                        f' rx="6" fill="{["#5a3340","#3d4a3a","#4a3b2a","#3a4452"][i]}"'
                        f' {o(3)}/>')
    chrn = ""
    for i, cx_ in enumerate((700, 1270, 1600)):
        chrn += (f'<rect x="{cx_-24:.0f}" y="{(820 if i<2 else 696):.0f}" width="48"'
                 f' height="44" rx="9" fill="#2a3a46" {o(4)}/>'
                 f'<ellipse cx="{cx_:.0f}" cy="{(820 if i<2 else 696):.0f}" rx="24"'
                 f' ry="9" fill="#6a7a88" {o(3)}/>')
    s += SL(Z_SRED, chrn)

    # трое на перемене дерутся портфелями
    dr = ""
    # рост 412-286, базы 918-868, шаги 208-248 и у каждого свой убор: было
    # трое одного роста через ровные 200 px (осмотр 15.11)
    for i, (bx0, bh, col, gl2) in enumerate(((396, 412, "#3a4452", 1.0),
                                             (604, 286, "#2f3a44", .78),
                                             (852, 352, "#4a3346", .92))):
        pr_ = 22 * A.w(t, 1.2, i * .35)
        d = figura(bx0, 918 - (1 - gl2) * 50 - abs(pr_) * .4, bh, t, col=col,
                   kant="#cfe4f5", ph=i * .3, naklon=-14 + 13 * i,
                   shapka=(i == 1), profil=(i != 1), op=.80 + .20 * gl2)
        yb2 = 918 - (1 - gl2) * 50
        rr1, (q1x, q1y), (a1x, a1y) = _ruka(bx0, yb2, bh, 1, bh * .46,
                                            -52 + 34 * A.w(t, 1.2, i * .35), t,
                                            col, "#cfe4f5", i * .2, 9)
        rr2, _, (a2x, a2y) = _ruka(bx0, yb2, bh, -1, bh * .36, 48 - 22 * (i % 2), t,
                                   col, "#cfe4f5", i * .2 + .4, 7)
        d += rr1 + rr2
        d += (f'<g transform="rotate({26*A.w(t,1.2,i*.35):.0f} {q1x:.0f} {q1y:.0f})">'
              f'<rect x="{q1x-52:.0f}" y="{q1y-14:.0f}" width="104" height="80" rx="10"'
              f' fill="{["#4a3522","#5e3a2a","#3a4452"][i]}" {o(5)}/>'
              f'<rect x="{q1x-52:.0f}" y="{q1y+18:.0f}" width="104" height="16"'
              f' fill="#2f2419" opacity=".7"/>'
              f'<rect x="{q1x-16:.0f}" y="{q1y-30:.0f}" width="32" height="20" rx="8"'
              f' fill="{ZHELEZ}" {o(3)}/>'
              f'<rect x="{q1x+16:.0f}" y="{q1y+10:.0f}" width="22" height="18" rx="5"'
              f' fill="{ZHELEZ}" {o(2)}/></g>')
        dr += d + ten(bx0, yb2 + 6, 62 * gl2, 13 * gl2, .4)
    s += SL(Z_SRED, dr)

    # ТИХИЙ ВЫДЕЛЕН МЕСТОМ, ПОЗОЙ И СВЕТОМ (осмотр 15.11: «ученики
    # одинаковые, тихий не выделен»). Он один сидит, пригнувшись к тетради,
    # в профиль, в тёплом пятне своей свечи — а трое дерутся в холодной
    # половине класса.
    ux, uy, uh = 1620, 896, 346
    s += SL(Z_SRED, teplo(ux - 10, uy - 150, 330, 260, .46))
    s += SL(Z_SRED, f'<rect x="{ux+120:.0f}" y="{uy-24:.0f}" width="54" height="24"'
                    f' rx="8" fill="{ZHELEZ}" {o(3)}/>'
            + svecha(ux + 147, uy - 24, t, .4, 1.25))
    u = figura(ux, uy, uh, t, col="#6a4a32", kant="#ffd98a", ph=.6, naklon=14,
               profil=True)
    r1, (sh1x, sh1y), (u1x, u1y) = _ruka_ekr(ux, uy, uh, -1, uh * .40, -72, t, "#3d4a3a",
                                             "#ffd98a", .3, 3)
    r2, (pe_x, pe_y), (u2x, u2y) = _ruka_ekr(ux, uy, uh, 1, uh * .40, 10, t, "#3d4a3a",
                                             "#ffd98a", .7, 4)
    u += r1 + r2
    skr = 7 * A.w(t, 1.6, .2)
    u += (f'<line x1="{pe_x:.0f}" y1="{pe_y:.0f}" x2="{pe_x+34+skr:.0f}"'
          f' y2="{pe_y+56:.0f}" stroke="#e4dcc4" stroke-width="8"'
          f' stroke-linecap="round"/>'
          f'<rect x="{ux-66:.0f}" y="{uy-14:.0f}" width="150" height="20" rx="5"'
          f' fill="#f0ead6" {o(3)}/>'
          f'<path d="M{ux-56:.0f},{uy-6:.0f} Q{ux-20:.0f},{uy-16:.0f}'
          f' {ux+16:.0f},{uy-6:.0f}" fill="none" stroke="#7a8a9a" stroke-width="4"/>'
          f'<circle cx="{ux-18:.0f}" cy="{uy-uh*.80:.0f}" r="20" fill="none"'
          f' stroke="#cfe4f5" stroke-width="5" opacity=".9"/>'
          f'<circle cx="{ux+22:.0f}" cy="{uy-uh*.80:.0f}" r="20" fill="none"'
          f' stroke="#cfe4f5" stroke-width="5" opacity=".9"/>'
          f'<line x1="{ux-2:.0f}" y1="{uy-uh*.80:.0f}" x2="{ux+2:.0f}"'
          f' y2="{uy-uh*.80:.0f}" stroke="#cfe4f5" stroke-width="5"/>')
    s += SL(Z_SRED, u)
    s += SL(Z_SRED, _dvorovaya_utvar(60, 1076, 300, t, 129, ["korob", "korzina"]))
    s += SL(Z_PERED, _stolb_pered(1870, 92, "#140f0b", 0, H))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def pyat_monet_na_podzerkalnike(t):
    """Старое трюмо с тремя зеркалами, перед ним подзеркальник на пол-кадра:
    гребень, флакон, катушка ниток, фарфоровое блюдце. Бабушка на пуфе левой
    придерживает блюдце, правой выкладывает в ряд пять медных монет."""
    rnd = random.Random(119)
    pol = 840
    s = f'<rect width="{W}" height="{H}" fill="#2a2630"/>'
    s += SL(Z_DAL, doski(0, 0, W, pol, 180, True, "dosk"))
    s += SL(Z_DAL, f'<rect x="0" y="0" width="{W}" height="{pol:.0f}" fill="#3b3a46"'
                   f' opacity=".55"/>'
                   f'<rect x="0" y="{pol-150:.0f}" width="{W}" height="26"'
                   f' fill="#2f2c38" opacity=".8"/>')
    s += SL(Z_DAL, polovicy(pol + 30))
    s += SL(Z_DAL, kvartira_veschi(1600, 760, 620, t, 11))

    # синий вечер за окном
    s += SL(Z_DAL, okno_izby(60, 150, 320, 380, t, svet=False, moroz=.0))
    s += SL(Z_DAL, f'<rect x="76" y="166" width="288" height="348" fill="#2b3a52"/>')
    for i in range(10):
        s += SL(Z_DAL, f'<rect x="{96+(i%3)*96:.0f}" y="{220+(i//3)*78:.0f}" width="44"'
                       f' height="40" rx="5" fill="#ffd98a"'
                       f' opacity="{.35+.25*abs(A.w(t,4.0,i*.2)):.2f}"/>')
    s += SL(Z_DAL, zanaveska(60, 140, 220, 150, TKAN, t, 1)
            + zanaveska(380, 140, 220, 150, TKAN, t, -1))

    # трюмо — главный предмет
    s += SL(Z_SRED, _tryumo(620, 700, 900, 600, t, 3))
    s += SL(Z_SRED, lampa(1420, 560, t, 1.5, True))
    s += SL(Z_SRED, teplo(1420, 700, 440, 340, .44))

    # вещи НА подзеркальнике
    pd = 700
    veshi = (f'<path d="M700,{pd-10:.0f} L860,{pd-10:.0f} L860,{pd-34:.0f}'
             f' L700,{pd-34:.0f} Z" fill="#c9b78e" {o(4)}/>')
    for i in range(14):
        veshi += (f'<line x1="{706+i*11:.0f}" y1="{pd-10:.0f}" x2="{706+i*11:.0f}"'
                  f' y2="{pd+22:.0f}" stroke="#c9b78e" stroke-width="5"/>')
    veshi += (f'<path d="M920,{pd-10:.0f} L920,{pd-96:.0f} Q952,{pd-120:.0f}'
              f' {984:.0f},{pd-96:.0f} L984,{pd-10:.0f} Z" fill="#8fb6c4"'
              f' opacity=".85" {o(4)}/>'
              f'<rect x="936" y="{pd-124:.0f}" width="32" height="28" rx="8"'
              f' fill="#d8c69a" {o(3)}/>'
              f'<rect x="1040" y="{pd-76:.0f}" width="86" height="66" rx="10"'
              f' fill="#b4762f" {o(4)}/>'
              f'<ellipse cx="1083" cy="{pd-76:.0f}" rx="43" ry="13" fill="#d09850"'
              f' {o(3)}/>'
              f'<line x1="1083" y1="{pd-76:.0f}" x2="1083" y2="{pd-16:.0f}"'
              f' stroke="#f0e6cc" stroke-width="4" opacity=".8"/>')
    s += SL(Z_SRED, veshi)

    # блюдце и пять монет в ряд
    bx_, by_ = 1300, pd - 14
    s += SL(Z_SRED, f'<path d="M{bx_-104:.0f},{by_-36:.0f} Q{bx_:.0f},{by_+30:.0f}'
                    f' {bx_+104:.0f},{by_-36:.0f} Z" fill="#eae4d6" {o(5)}/>'
                    f'<ellipse cx="{bx_:.0f}" cy="{by_-38:.0f}" rx="104" ry="26"'
                    f' fill="#f6f1e6" {o(3)}/>')
    mon = ""
    for i in range(5):
        vy = A.ease(A.seg(t, .5 + i * .35, .5))
        mx = 700 + i * 150
        my = by_ - 54 - 180 * (1 - vy)
        if vy > .02:
            mon += _moneta_krupno(mx, my, 66, t, i * .2, True, True, .80 * vy)
            nm = A.ease(A.seg(t, .9 + i * .35, .4))
            mon += (f'<circle cx="{mx:.0f}" cy="{my:.0f}" r="{78*nm:.0f}" fill="none"'
                    f' stroke="#ffe9ac" stroke-width="5" opacity="{(1-nm)*.8:.2f}"/>'
                    f'<circle cx="{mx:.0f}" cy="{my:.0f}" r="34" fill="#fff3cf"'
                    f' opacity="{nm*.30:.2f}"/>')
    s += SL(Z_SRED, mon)

    # бабушка на пуфе
    fx, fy, fh = 1620, 1040, 470
    s += SL(Z_SRED, f'<ellipse cx="{fx:.0f}" cy="{fy-60:.0f}" rx="120" ry="44"'
                    f' fill="#5a4a58" {o(5)}/>'
                    f'<rect x="{fx-110:.0f}" y="{fy-62:.0f}" width="220" height="56"'
                    f' rx="16" fill="#4a3c48" {o(4)}/>')
    bab = figura(fx, fy - 56, fh, t, col="#46404e", kant="#ffd98a", platok=True, ph=.3,
                 naklon=-6)
    # Руки лежат на колене и на пуфе. Было: правый рукав под 178° уходил
    # прямой палкой через полкадра влево и кончался в пустоте (осмотр 15.11).
    r1, _, (b1x, b1y) = _ruka(fx, fy - 56, fh, 1, fh * .34, 74, t,
                              "#46404e", "#ffd98a", .2, 5)
    r2, _, (b2x, b2y) = _ruka(fx, fy - 56, fh, -1, fh * .30, 82, t,
                              "#46404e", "#ffd98a", .6, 4)
    s += SL(Z_SRED, bab + r1 + r2)
    s += SL(Z_SRED, _kot_zhivoy(300, 1060, t, 1.6, "#4a423c", .3, True, True))
    s += SL(Z_SRED, mebel_hlam(120, 940, 380, t, 29))
    s += SL(Z_SRED, _lavka_krupno(520, 1070, 520, t, 190, True))
    s += SL(Z_SRED, kvartira_veschi(520, 380, 420, t, 31))
    s += SL(Z_SRED, f'<path d="M560,1010 L1500,1010 L1620,1076 L440,1076 Z"'
                    f' fill="#5a3f46" {o(5)}/>'
                    f'<path d="M580,1032 L1512,1032 M566,1056 L1560,1056"'
                    f' stroke="#8a6a3c" stroke-width="8" opacity=".55"/>')
    s += SL(Z_PERED, _stolb_pered(1884, 90, "#140f0b", 0, H))
    s += ramka_pp("oba")
    s += vinetka(.46)
    return s


def ruka_nad_monetoy(t):
    """Булыжная мостовая крупно: в щели между камнями ЛЕЖИТ ПЛАШМЯ крупная
    серебряная монета — профиль-чеканка, гурт насечкой, блик дугой, тень под
    ребром. Рядом жёлтый лист, оброненная пуговица, травинка. Сверху входит
    рука до локтя в рукаве пальто, зависает, сжимается в кулак и уходит."""
    rnd = random.Random(120)
    s = f'<rect width="{W}" height="{H}" fill="#2e2f33"/>'
    s += SL(Z_DAL, _bulyzhnik(60, 440, 13, 90, "#4a4740"))
    s += SL(Z_SRED, _bulyzhnik(400, 1080, 17, 150, "#5a5248"))
    s += SL(Z_SRED, _bulyzhnik(620, 1080, 19, 90, "#625a4e"))
    s += SL(Z_SRED, f'<rect x="0" y="40" width="{W}" height="80" fill="#3a3b40"'
                    f' opacity=".7"/>')
    s += SL(Z_DAL, tuman(t, 160, .30, "#aab4bc"))
    # ВЕРХ КАДРА — НЕ ПУСТОЙ СЕРЫЙ (осмотр 15.11). Та же мостовая дальше:
    # чугунная крышка люка, водосточный жёлоб, лужа с отражением, сгребённые
    # листья, ящик у бордюра, голубь. Вещи, а не полупрозрачные пятна.
    lyuk = (f'<ellipse cx="286" cy="176" rx="196" ry="112" fill="#2a2d31" {o(6)}/>'
            f'<ellipse cx="286" cy="166" rx="176" ry="98" fill="#4a4d52" {o(5)}/>'
            f'<ellipse cx="286" cy="166" rx="146" ry="80" fill="none" stroke="#2f3237"'
            f' stroke-width="9"/>')
    for i in range(8):
        a_ = math.radians(i * 45)
        lyuk += (f'<line x1="{286+36*math.cos(a_):.0f}" y1="{166+20*math.sin(a_):.0f}"'
                 f' x2="{286+142*math.cos(a_):.0f}" y2="{166+78*math.sin(a_):.0f}"'
                 f' stroke="#2f3237" stroke-width="11"/>')
    for i in range(6):
        lyuk += (f'<ellipse cx="{196+i*36:.0f}" cy="{150+(i%2)*26:.0f}" rx="13"'
                 f' ry="8" fill="#6a6f75" opacity=".7"/>')
    lyuk += (f'<ellipse cx="286" cy="166" rx="34" ry="19" fill="#23262a" {o(3)}/>'
             f'<path d="M240,120 Q286,96 332,120" fill="none" stroke="#7d848b"'
             f' stroke-width="7" opacity=".55"/>')
    s += SL(Z_SRED, lyuk)
    zhel = (f'<path d="M0,268 L{W},242 L{W},288 L0,314 Z" fill="#3a3d42" {o(4)}/>'
            f'<path d="M0,282 L{W},256" stroke="#22262a" stroke-width="12"'
            f' opacity=".85"/>')
    for i in range(14):
        zhel += (f'<rect x="{40+i*136:.0f}" y="{262-i*2:.0f}" width="54" height="16"'
                 f' rx="6" fill="#20242a" {o(2)}/>')
    s += SL(Z_SRED, zhel)
    s += SL(Z_SRED, _luzha(1420, 150, 240, t, .4, 92, "#8ea6bb"))
    s += SL(Z_SRED, _kucha_listev(830, 230, 330, 163, 118))
    s += SL(Z_SRED, _yaschiki(1700, 230, t, 167, 1, .92))
    s += SL(Z_SRED, f'<g transform="rotate(-18 620 206)">'
                    f'<path d="M556,206 Q556,142 596,136 Q604,100 640,118'
                    f' Q676,102 680,142 Q716,152 702,198 Q660,230 606,228 Z"'
                    f' fill="#4e3a44" {o(5)}/>'
                    f'<path d="M578,212 Q624,196 690,206" fill="none" stroke="#2f2029"'
                    f' stroke-width="7" opacity=".8"/></g>')
    s += SL(Z_SRED, ptica(1180, 330, t, 1.7, "#6a717a", .3, "#4a5058"))
    # бордюрный камень и решётка стока
    s += SL(Z_SRED, f'<rect x="0" y="300" width="{W}" height="56" rx="8"'
                    f' fill="#7a7c80" {o(5)}/>'
                    f'<rect x="0" y="356" width="{W}" height="30" fill="#5a5c60"'
                    f' opacity=".9"/>')
    resh = f'<rect x="1500" y="420" width="330" height="150" rx="10" fill="#3a3d42" {o(5)}/>'
    for i in range(7):
        resh += (f'<rect x="{1516+i*44:.0f}" y="432" width="26" height="126" rx="5"'
                 f' fill="#22262a" {o(2)}/>')
    s += SL(Z_SRED, resh)
    # крупные камни переднего плана
    for i, (gx_, gy_, gr) in enumerate(((180, 700, 130), (1600, 840, 150),
                                        (1180, 1040, 170), (300, 1020, 120))):
        s += SL(Z_SRED, f'<ellipse cx="{gx_:.0f}" cy="{gy_:.0f}" rx="{gr:.0f}"'
                        f' ry="{gr*.66:.0f}" fill="#5e5a52" {o(5)}/>'
                        f'<ellipse cx="{gx_-gr*.24:.0f}" cy="{gy_-gr*.20:.0f}"'
                        f' rx="{gr*.52:.0f}" ry="{gr*.30:.0f}" fill="#726d62"'
                        f' opacity=".6"/>')
    s += SL(Z_SRED, f'<ellipse cx="460" cy="1046" rx="330" ry="54" fill="#6d7f8c"'
                    f' opacity=".45"/>'
                    f'<path d="M250,1036 L680,1030" stroke="#c6dcea" stroke-width="6"'
                    f' opacity=".55"/>')

    # щель между камнями, в которой лежит монета
    mx, my = 860, 720
    s += SL(Z_SRED, f'<path d="M{mx-620:.0f},{my+56:.0f} Q{mx:.0f},{my-54:.0f}'
                    f' {mx+620:.0f},{my+86:.0f} L{mx+620:.0f},{my+150:.0f}'
                    f' Q{mx:.0f},{my+20:.0f} {mx-620:.0f},{my+120:.0f} Z"'
                    f' fill="#26262a" opacity=".85"/>')
    # МОНЕТА ЛЕЖИТ ПЛАШМЯ И КРУПНО
    s += SL(Z_SRED, _moneta_krupno(mx, my, 268, t, .1, False, True, .56))
    s += SL(Z_SRED, teplo(mx, my, 360, 260, .32))

    # жёлтый лист, пуговица, травинка
    lk = 5 * A.w(t, 1.9, .2)
    s += SL(Z_SRED, f'<g transform="rotate({lk:.1f} 340 1004)">'
                    f'<path d="M190,1004 Q340,890 490,1004 Q340,1090 190,1004 Z"'
                    f' fill="#c08a3a" {o(4)}/>'
                    f'<line x1="190" y1="1004" x2="490" y2="1004" stroke="#7a5420"'
                    f' stroke-width="6"/>'
                    f'<path d="M264,978 L304,1004 M340,966 L350,1004'
                    f' M416,978 L386,1004" stroke="#7a5420" stroke-width="4"'
                    f' opacity=".8"/></g>')
    s += SL(Z_SRED, f'<ellipse cx="1430" cy="980" rx="74" ry="30" fill="#e8e2d2" {o(5)}/>'
                    f'<ellipse cx="1430" cy="980" rx="30" ry="12" fill="none"'
                    f' stroke="#b9ae95" stroke-width="6"/>'
                    f'<circle cx="1412" cy="976" r="7" fill="#fff8e8" opacity=".9"/>'
                    f'<circle cx="1448" cy="976" r="7" fill="#fff8e8" opacity=".9"/>')
    s += SL(Z_SRED, _podorozhnik(1620, 1040, 1.8, t, .3, 5)
            + _trava(rnd, 10, 840, 1060, "#6f7a44"))
    s += SL(Z_SRED, _listya(161, 30, 480, 1060))
    s += SL(Z_SRED, svecha(1800, 760, t, .2, 1.6))
    s += SL(Z_SRED, _gorodskoy_hlam(1060, 1076, 460, t, 205, ["korobka", "yaschik"]))

    # рука до локтя в рукаве пальто: опускается, зависает, сжимается, уходит
    op_ = A.ease(A.seg(t, .2, 1.2))
    zh = A.ease(A.seg(t, 1.9, .6))
    uh = A.ease(A.seg(t, 2.8, .8))
    ky_ = -400 + 640 * op_ - 700 * uh
    ruk, (kx2, ky2) = rukav(mx + 310, ky_, 380, 112, t, "#2f3542", "#cfe4f5", .1, 3, True)
    kul = (f'<ellipse cx="{kx2:.0f}" cy="{ky2:.0f}" rx="{84-18*zh:.0f}"'
           f' ry="{74-12*zh:.0f}" fill="#2f3542" {o(6)}/>'
           f'<rect x="{mx+248:.0f}" y="{ky_-32:.0f}" width="132" height="58" rx="17"'
           f' fill="#232835" {o(5)}/>'
           f'<path d="M{kx2-52:.0f},{ky2-26+14*zh:.0f} Q{kx2:.0f},{ky2-48+20*zh:.0f}'
           f' {kx2+52:.0f},{ky2-26+14*zh:.0f}" fill="none" stroke="#1a1e28"'
           f' stroke-width="7" opacity=".8"/>'
           f'<ellipse cx="{kx2:.0f}" cy="{my+120:.0f}" rx="{110-20*zh:.0f}" ry="26"'
           f' fill="#1a1a1e" opacity="{.30*op_*(1-uh):.2f}"/>')
    s += SL(Z_PERED, ruk + kul)
    s += SL(Z_LETIT, mokryy_sneg(t, 14, 19, .4, .7))
    s += ramka_pp("oba")
    s += vinetka(.48)
    return s


def nadezhda_v_monete(t):
    """Монета во весь кадр: в её блестящем кружке, как в окошке, виден тёплый
    вид — изба с огоньком в окне, крыльцо, дымок над трубой, рябина. Девушка
    стоит СНАРУЖИ монеты и смотрит в неё. Сверху тянется та же рука и
    отдёргивается, по ободку бежит блик."""
    rnd = random.Random(121)
    s = f'<rect width="{W}" height="{H}" fill="#2a2a2e"/>'
    s += SL(Z_DAL, _bulyzhnik(500, 1080, 23, 90, "#4a4740"))
    s += SL(Z_DAL, tuman(t, 240, .26, "#aab4bc"))

    cx, cy, r = 760, 520, 496
    s += SL(Z_SRED, ten(cx, cy + r * .98, r * 1.04, r * .2, .5))
    s += SL(Z_SRED, f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="{r:.0f}" fill="url(#med)"'
                    f' {o(9)}/>'
                    f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="{r*.90:.0f}" fill="none"'
                    f' stroke="#8a5a22" stroke-width="12" opacity=".85"/>')
    gurt = ""
    for i in range(44):
        a = math.radians(i * 360 / 44.0)
        gurt += (f'<line x1="{cx+r*.91*math.cos(a):.0f}" y1="{cy+r*.91*math.sin(a):.0f}"'
                 f' x2="{cx+r*1.0*math.cos(a):.0f}" y2="{cy+r*1.0*math.sin(a):.0f}"'
                 f' stroke="#7a4d1c" stroke-width="7" opacity=".8"/>')
    for i in range(22):
        a = math.radians(i * 360 / 22.0 + 8)
        gurt += (f'<circle cx="{cx+r*.82*math.cos(a):.0f}" cy="{cy+r*.82*math.sin(a):.0f}"'
                 f' r="11" fill="#8a5a22" opacity=".85"/>')
    s += SL(Z_SRED, gurt)

    # ── в кружке монеты ТЁПЛЫЙ ВИД: изба с огоньком, крыльцо, дымок
    rr = r * .74
    vid = (f'<clipPath id="monok"><circle cx="{cx:.0f}" cy="{cy:.0f}"'
           f' r="{rr:.0f}"/></clipPath><g clip-path="url(#monok)">'
           f'<rect x="{cx-rr:.0f}" y="{cy-rr:.0f}" width="{rr*2:.0f}"'
           f' height="{rr*2:.0f}" fill="#d8a85c"/>'
           f'<rect x="{cx-rr:.0f}" y="{cy-rr:.0f}" width="{rr*2:.0f}"'
           f' height="{rr:.0f}" fill="#e6c488"/>'
           f'<rect x="{cx-rr:.0f}" y="{cy+rr*.42:.0f}" width="{rr*2:.0f}"'
           f' height="{rr:.0f}" fill="#a87a38"/>')
    # сруб избы
    ix, ib, iw = cx + rr * .14, cy + rr * .46, rr * 1.22
    for i in range(6):
        vid += (f'<rect x="{ix-iw/2:.0f}" y="{ib-28-i*30:.0f}" width="{iw:.0f}"'
                f' height="27" rx="9" fill="{["#b5813c","#a3722f"][i%2]}" {o(4)}/>')
    vid += (f'<path d="M{ix-iw*.62:.0f},{ib-180:.0f} L{ix:.0f},{ib-268:.0f}'
            f' L{ix+iw*.62:.0f},{ib-180:.0f} Z" fill="#8a5a22" {o(5)}/>'
            f'<rect x="{ix-iw*.66:.0f}" y="{ib-188:.0f}" width="{iw*1.32:.0f}"'
            f' height="18" rx="7" fill="#94651f" {o(4)}/>')
    # огонёк в окне
    og = .65 + .35 * abs(A.w(t, 2.0, .1))
    vid += (f'<rect x="{ix-44:.0f}" y="{ib-140:.0f}" width="88" height="80" rx="8"'
            f' fill="#6b4420" {o(4)}/>'
            f'<rect x="{ix-34:.0f}" y="{ib-130:.0f}" width="68" height="60" rx="5"'
            f' fill="#fff0bd" opacity="{og:.2f}"/>'
            f'<line x1="{ix:.0f}" y1="{ib-130:.0f}" x2="{ix:.0f}" y2="{ib-70:.0f}"'
            f' stroke="#6b4420" stroke-width="7"/>'
            f'<line x1="{ix-34:.0f}" y1="{ib-100:.0f}" x2="{ix+34:.0f}"'
            f' y2="{ib-100:.0f}" stroke="#6b4420" stroke-width="7"/>'
            f'<circle cx="{ix:.0f}" cy="{ib-100:.0f}" r="{74*og:.0f}" fill="#fff0bd"'
            f' opacity=".30"/>')
    # крыльцо
    vid += (f'<rect x="{ix-iw*.72:.0f}" y="{ib-54:.0f}" width="{iw*.46:.0f}"'
            f' height="20" rx="7" fill="#8a5a22" {o(4)}/>'
            f'<rect x="{ix-iw*.68:.0f}" y="{ib-34:.0f}" width="{iw*.38:.0f}"'
            f' height="18" rx="6" fill="#94651f" {o(3)}/>'
            f'<rect x="{ix-iw*.72:.0f}" y="{ib-120:.0f}" width="16" height="70"'
            f' rx="6" fill="#7a4d1c" {o(3)}/>'
            f'<rect x="{ix-iw*.32:.0f}" y="{ib-120:.0f}" width="16" height="70"'
            f' rx="6" fill="#7a4d1c" {o(3)}/>')
    # труба и дымок
    vid += (f'<rect x="{ix+iw*.26:.0f}" y="{ib-286:.0f}" width="36" height="60" rx="6"'
            f' fill="#94651f" {o(4)}/>')
    for i in range(4):
        p = ((t * .22 + i * .25) % 1.0)
        vid += (f'<ellipse cx="{ix+iw*.30+26*math.sin(p*5+i):.0f}"'
                f' cy="{ib-300-p*170:.0f}" rx="{20+p*34:.0f}" ry="{15+p*26:.0f}"'
                f' fill="#f0e0bc" opacity="{(1-p)*.5:.2f}"/>')
    # рябина у крыльца
    vid += (f'<line x1="{cx-rr*.64:.0f}" y1="{ib:.0f}" x2="{cx-rr*.60:.0f}"'
            f' y2="{ib-140:.0f}" stroke="#7a4d1c" stroke-width="12"/>')
    for i in range(9):
        a = math.radians(i * 40 + 10 * A.w(t, 3.0, i * .2))
        vid += (f'<circle cx="{cx-rr*.60+40*math.cos(a):.0f}"'
                f' cy="{ib-150+30*math.sin(a):.0f}" r="10" fill="#c8402c"'
                f' opacity=".95"/>')
    # тёплое пятно от окна на земле
    vid += (f'<ellipse cx="{ix:.0f}" cy="{ib+30:.0f}" rx="{rr*.72:.0f}"'
            f' ry="{rr*.18:.0f}" fill="#ffe9ac" opacity=".38"/>')
    vid += "</g>"
    s += SL(Z_SRED, vid)
    s += SL(Z_SRED, f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="{rr:.0f}" fill="none"'
                    f' stroke="#8a5a22" stroke-width="12" opacity=".9"/>')

    # блик бежит по ободку
    bp = (t * .35) % 1.0
    ba = bp * 6.283
    s += SL(Z_SRED, f'<path d="M{cx+r*.95*math.cos(ba-.5):.0f},'
                    f'{cy+r*.95*math.sin(ba-.5):.0f} A{r*.95:.0f},{r*.95:.0f} 0 0 1'
                    f' {cx+r*.95*math.cos(ba+.5):.0f},{cy+r*.95*math.sin(ba+.5):.0f}"'
                    f' fill="none" stroke="#fff3cf" stroke-width="26" opacity=".55"/>')
    s += SL(Z_SRED, teplo(cx, cy, 540, 480, .32))

    # девушка СНАРУЖИ монеты: стоит на мостовой и смотрит в кружок
    isp = A.ease(A.seg(t, 1.1, .5)) * (1 - A.ease(A.seg(t, 2.4, .6)))
    fx, fy, fh = 1560, 1030, 600
    dev = figura(fx, fy, fh, t, col="#4a3f52", kant="#ffd98a", platok=True, ph=.3,
                 naklon=-7 + 5 * isp)
    rr1, (c1x, c1y), (d1x, d1y) = _ruka_ekr(fx, fy, fh, 1, fh * .34, -150 + 24 * isp, t,
                                            "#4a3f52", "#ffd98a", .2, 4)
    rr2, (c2x, c2y), (d2x, d2y) = _ruka_ekr(fx, fy, fh, -1, fh * .34, -116 - 24 * isp, t,
                                            "#4a3f52", "#ffd98a", .6, 4)
    dev += rr1 + rr2
    # ладони сложены у груди, при испуге поднимаются к лицу
    for (hx_, hy_) in ((c1x, c1y), (c2x, c2y)):
        dev += (f'<ellipse cx="{hx_:.0f}" cy="{hy_-40*isp:.0f}" rx="34" ry="46"'
                f' fill="#4a3f52" {o(5)}/>')
    dev += para_izo_rta(fx - 48, fy - fh * .80, t, .2, 1.1, .5)
    s += SL(Z_SRED, dev + ten(fx, fy + 8, 120, 22, .5))

    # рука тянется к монете и отдёргивается
    tyn = A.ease(A.seg(t, .6, .9)) * (1 - A.ease(A.seg(t, 2.2, .7)))
    ruk, (kx2, ky2) = rukav(cx - 300, -340 + 500 * tyn, 420, 72, t, "#2f3542",
                            "#cfe4f5", .1, 3, True)
    s += SL(Z_PERED, ruk + f'<ellipse cx="{kx2:.0f}" cy="{ky2:.0f}" rx="82" ry="72"'
                           f' fill="#2f3542" {o(6)}/>'
                           f'<rect x="{cx-366:.0f}" y="{-370+500*tyn:.0f}" width="132"'
                           f' height="58" rx="17" fill="#232835" {o(5)}/>')
    s += SL(Z_SRED, _listya(167, 30, 620, 1060))
    s += SL(Z_SRED, _gorodskoy_hlam(40, 1056, 420, t, 187, ["stolbik", "yaschik"]))
    s += SL(Z_SRED, _gorodskoy_hlam(1760, 1070, 200, t, 189, ["korobka"]))
    for i, (gx_, gy_, gr) in enumerate(((240, 900, 120), (1320, 980, 140))):
        s += SL(Z_SRED, f'<ellipse cx="{gx_:.0f}" cy="{gy_:.0f}" rx="{gr:.0f}"'
                        f' ry="{gr*.66:.0f}" fill="#5e5a52" {o(5)}/>')
    s += SL(Z_SRED, _podorozhnik(300, 1040, 1.8, t, .4, 5)
            + _podorozhnik(1180, 1060, 1.6, t, .9, 5))
    s += SL(Z_SRED, svecha(120, 760, t, .3, 1.5))
    s += SL(Z_SRED, lampa(180, 300, t, 1.3, True) + teplo(180, 420, 240, 200, .36))
    s += SL(Z_LETIT, mokryy_sneg(t, 12, 21, .35, .65))
    s += ramka_pp("oba")
    s += vinetka(.48)
    return s


def nogi_pereshagivayut_nahodku(t):
    """Деревянные мостки, на доске лежит монета. КРУПНО — одна пара ног в
    валенках с подошвой, опора на доски настила: нога поднимается выше и
    перешагивает находку. Двое других идут следом в глубине кадра, видны
    целиком и мелко. Под мостками лужа со льдом, лопух, воробей."""
    rnd = random.Random(122)
    POL = 880
    s = f'<rect width="{W}" height="{H}" fill="#39342c"/>'
    s += SL(Z_DAL, f'<rect x="0" y="{POL+60:.0f}" width="{W}" height="{H-POL-60}"'
                   f' fill="#3b352c"/>'
                   f'<ellipse cx="620" cy="1020" rx="420" ry="60" fill="#6d7f8c"'
                   f' opacity=".55"/>'
                   f'<ellipse cx="620" cy="1008" rx="310" ry="38" fill="#c6dcea"'
                   f' opacity=".45"/>'
                   f'<path d="M380,1010 L860,998 M450,1034 L800,1024" stroke="#e4f1fa"'
                   f' stroke-width="5" opacity=".6"/>')
    s += SL(Z_DAL, _podorozhnik(1360, 1060, 2.6, t, .2, 6)
            + _podorozhnik(180, 1056, 2.0, t, .7, 5))
    vp = (t * .5) % 1.0
    s += SL(Z_DAL, ptica(1180 - 320 * vp, POL - 40 - 200 * max(.0, vp - .62) * 2.6, t,
                         1.5, "#7d6a52", .2))

    # дальний план: улица, заборы, дым, перила мостков
    s += SL(Z_DAL, _zabor_dosok(-20, POL - 560, 820, 300, 177, 56)
            + _zabor_dosok(1180, POL - 556, 780, 296, 179, 58))
    s += SL(Z_DAL, teplo(300, POL - 420, 260, 210, .34))
    s += SL(Z_DAL, dym(300, POL - 560, t, 5, .26, 280, .34, "#d3dae2", .9))
    s += SL(Z_DAL, goloe_derevo(1180, POL - 540, 620, t, 325, 10, "#2a2b33", True)
            + goloe_derevo(560, POL - 548, 520, t, 357, 9, "#2a2b33", True))
    s += SL(Z_DAL, _derevnya_ryad(POL - 560, t, 359, ((640, 380), (1240, 340))))
    sta2 = ""
    for i in range(7):
        bx_ = 460 + i * 160 + 26 * math.sin(t * .5 + i)
        sta2 += ptica(bx_, 214 + (i % 3) * 44, t, .9, "#4a4a52", i * .2)
    s += SL(Z_DAL, sta2)
    per = (f'<rect x="150" y="{POL-470:.0f}" width="1480" height="28" rx="10"'
           f' fill="url(#derev)" {o(6)}/>'
           f'<rect x="150" y="{POL-392:.0f}" width="1480" height="22" rx="9"'
           f' fill="#5b4428" {o(5)}/>')
    for i in range(8):
        px = 40 + i * 260
        per += (f'<rect x="{px:.0f}" y="{POL-478:.0f}" width="32" height="300" rx="9"'
                f' fill="#4a3522" {o(4)}/>')
    s += SL(Z_DAL, per)
    s += SL(Z_DAL, tuman(t, POL - 330, .26, "#aab4bc"))

    # двое других — целиком, мелко, в глубине
    sh = (t * .55) % 1.0
    glub = ""
    for i, (gx_, gh, col, pl, ph_) in enumerate(((1310, 290, "#3a3a44", False, .2),
                                                 (1470, 250, "#4a4a56", True, .6))):
        pryg = 10 * abs(math.sin((sh + i * .4) * 6.283))
        g = figura(gx_, POL - 12 - pryg * .3, gh, t, col=col, kant="#cfe4f5",
                   platok=pl, ph=ph_, shapka=not pl)
        rr1, (q1x, q1y), (a1x, a1y) = _ruka_ekr(gx_, POL - 12, gh, 1, gh * .40, 72, t, col,
                                                "#cfe4f5", ph_, 5)
        rr2, _, (a2x, a2y) = _ruka_ekr(gx_, POL - 12, gh, -1, gh * .38, 104, t, col, "#cfe4f5",
                                       ph_ + .3, 5)
        g += rr1 + rr2
        if i == 0:
            g += (f'<path d="M{q1x-46:.0f},{q1y:.0f} L{q1x+46:.0f},{q1y:.0f}'
                  f' L{q1x+34:.0f},{q1y+76:.0f} L{q1x-34:.0f},{q1y+76:.0f} Z"'
                  f' fill="url(#solom)" {o(4)}/>'
                  f'<path d="M{q1x-38:.0f},{q1y:.0f} Q{q1x:.0f},{q1y-50:.0f}'
                  f' {q1x+38:.0f},{q1y:.0f}" fill="none" stroke="#8a6a3c"'
                  f' stroke-width="7"/>')
        else:
            g += (f'<path d="M{q1x-30:.0f},{q1y:.0f} Q{q1x-44:.0f},{q1y+44:.0f}'
                  f' {q1x-30:.0f},{q1y+86:.0f} L{q1x+30:.0f},{q1y+86:.0f}'
                  f' Q{q1x+44:.0f},{q1y+44:.0f} {q1x+30:.0f},{q1y:.0f} Z"'
                  f' fill="url(#glina)" {o(4)}/>')
        glub += g + ten(gx_, POL + 4, 54, 12, .4)
    s += SL(Z_DAL, glub)

    # настил мостков
    nast = ""
    for i in range(6):
        dy = POL - 10 + i * 36
        nast += (f'<rect x="-30" y="{dy:.0f}" width="{W+60}" height="32" rx="6"'
                 f' fill="url(#dosk)" {o(4)}/>'
                 f'<line x1="-30" y1="{dy+32:.0f}" x2="{W+30}" y2="{dy+32:.0f}"'
                 f' stroke="#2f2419" stroke-width="5" opacity=".7"/>')
    for i in range(9):
        gx = 90 + i * 220
        nast += (f'<circle cx="{gx:.0f}" cy="{POL+6:.0f}" r="9" fill="#5e5146" {o(2)}/>'
                 f'<circle cx="{gx+110:.0f}" cy="{POL+78:.0f}" r="9" fill="#5e5146"'
                 f' {o(2)}/>')
    s += SL(Z_SRED, nast)
    s += SL(Z_SRED, _listya(169, 26, POL - 20, POL + 160))
    s += SL(Z_SRED, _inej(171, 30, POL - 10, POL + 160))

    # монета лежит на доске
    s += SL(Z_SRED, _moneta_krupno(1000, POL + 70, 96, t, .2, True, True, .86))
    s += SL(Z_SRED, teplo(1000, POL + 70, 300, 210, .30))

    # ── КРУПНО одна пара ног в валенках, опора на доски настила
    shag = sh
    bedr = 330
    col = "#5a3f46"
    nx = 620
    kr = ""
    for k, sgn in ((0, -1), (1, 1)):
        lift = max(.0, math.sin((shag + k * .5) * math.pi)) * 230
        bx2 = nx + sgn * 96
        fy2 = POL + 96 - lift
        # штанина/чулок
        kr += (f'<path d="M{bx2-38:.0f},{bedr:.0f} L{bx2+38:.0f},{bedr:.0f}'
               f' L{bx2+34:.0f},{fy2-150:.0f} L{bx2-34:.0f},{fy2-150:.0f} Z"'
               f' fill="#6e6252" {o(6)}/>')
        # валенок: голенище, след, подошва, строчка
        kr += (f'<path d="M{bx2-42:.0f},{fy2-262:.0f} L{bx2+42:.0f},{fy2-262:.0f}'
               f' L{bx2+52:.0f},{fy2-30:.0f} L{bx2-52:.0f},{fy2-30:.0f} Z"'
               f' fill="#9a8c70" {o(7)}/>'
               f'<path d="M{bx2-74:.0f},{fy2-30:.0f} Q{bx2+30:.0f},{fy2-10:.0f}'
               f' {bx2+128:.0f},{fy2-40:.0f} L{bx2+134:.0f},{fy2+16:.0f}'
               f' Q{bx2+20:.0f},{fy2+46:.0f} {bx2-78:.0f},{fy2+22:.0f} Z"'
               f' fill="#8b7d62" {o(7)}/>'
               f'<path d="M{bx2-78:.0f},{fy2+22:.0f} Q{bx2+20:.0f},{fy2+46:.0f}'
               f' {bx2+134:.0f},{fy2+16:.0f} L{bx2+136:.0f},{fy2+44:.0f}'
               f' Q{bx2+20:.0f},{fy2+76:.0f} {bx2-80:.0f},{fy2+50:.0f} Z"'
               f' fill="#4a4036" {o(6)}/>')
        for q in range(5):                                   # подошва-рифление
            kr += (f'<line x1="{bx2-56+q*44:.0f}" y1="{fy2+34+q*2:.0f}"'
                   f' x2="{bx2-50+q*44:.0f}" y2="{fy2+60+q*2:.0f}" stroke="#2e2820"'
                   f' stroke-width="6" opacity=".8"/>')
        kr += (f'<path d="M{bx2-60:.0f},{fy2-206:.0f} L{bx2+60:.0f},{fy2-206:.0f}"'
               f' stroke="#857757" stroke-width="7"/>'
               f'<path d="M{bx2-66:.0f},{fy2-96:.0f} Q{bx2:.0f},{fy2-76:.0f}'
               f' {bx2+70:.0f},{fy2-100:.0f}" fill="none" stroke="#857757"'
               f' stroke-width="6"/>')
        kr += ten(bx2 + 24, POL + 122, 86, 18, .40 * (1 - lift / 300.0))
    # подол и пояс крупно
    kr += (f'<path d="M{nx-104:.0f},-80 L{nx+104:.0f},-80'
           f' L{nx+174:.0f},{bedr+62:.0f} L{nx-174:.0f},{bedr+62:.0f} Z"'
           f' fill="{col}" {o(8)}/>'
           f'<path d="M{nx-174:.0f},{bedr+62:.0f} Q{nx-60:.0f},{bedr+118:.0f}'
           f' {nx+6:.0f},{bedr+74:.0f} Q{nx+80:.0f},{bedr+120:.0f}'
           f' {nx+174:.0f},{bedr+62:.0f}" fill="none" stroke="#2a1820"'
           f' stroke-width="10" opacity=".6"/>'
           f'<path d="M{nx+4:.0f},-80 L{nx+10:.0f},{bedr+72:.0f}" stroke="#2a1820"'
           f' stroke-width="9" opacity=".45"/>')
    for k in range(6):
        kr += (f'<line x1="{nx-86+k*36:.0f}" y1="-60"'
               f' x2="{nx-140+k*58:.0f}" y2="{bedr+54:.0f}" stroke="#2a1820"'
               f' stroke-width="6" opacity=".28"/>')
    s += SL(Z_SRED, kr)

    s += SL(Z_SRED, _dvorovaya_utvar(1180, POL + 180, 560, t, 181,
                                     ["korzina", "vedro", "korob"]))
    s += SL(Z_SRED, _polka_s_utvaryu(600, POL - 420, 420, t, 183, 3))
    s += SL(Z_SRED, _dvorovaya_utvar(760, POL - 380, 420, t, 323, ["kadka", "meshok"]))
    s += SL(Z_SRED, svecha(1840, POL - 420, t, .2, 1.4))
    s += SL(Z_PERED, _stolb_pered(-8, 86, "#1d1611", 0, H))
    s += SL(Z_LETIT, mokryy_sneg(t, 16, 23, .4, .7))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def moneta_kupyura_i_perchatka_na_asfa(t):
    """Городской тротуар у бордюра, осенние листья. В ряд лежат монета,
    сложенная купюра и вязаная перчатка. Рядом урна, скамейка, колесо
    коляски. Женщина в пальто и берете проходит мимо, не сбавляя шага."""
    rnd = random.Random(123)
    s = f'<rect width="{W}" height="{H}" fill="#2d3038"/>'
    s += SL(Z_DAL, panelka(300, 470, 620, t, 5, True, 7)
            + panelka(1500, 450, 560, t, 5, True, 9))
    s += SL(Z_DAL, goloe_derevo(470, 482, 700, t, 13, 11, "#2a2b33", False)
            + goloe_derevo(1520, 476, 560, t, 361, 9, "#2a2b33", False))
    s += SL(Z_DAL, panelka(960, 470, 540, t, 6, True, 363))
    s += SL(Z_DAL, tusklaya_lampochka(300, 160, t, 2.0, False))
    s += SL(Z_DAL, teplo(300, 280, 260, 210, .36))
    s += SL(Z_SRED, _asfalt(470, 1080, 29, 34))
    s += SL(Z_SRED, f'<rect x="170" y="462" width="1440" height="46" rx="8"'
                    f' fill="#7a7c80" {o(5)}/>'
                    f'<rect x="0" y="508" width="{W}" height="26" fill="#5a5c60"'
                    f' opacity=".9"/>')

    # урна, скамейка, колесо коляски
    # урна ушла в правый край, скамейка стала МЕНЬШЕ и дальше, коляскино
    # колесо поднялось: находки были мельче скамейки и в кадре читались
    # мусором под ногами (осмотр 15.11)
    s += SL(Z_SRED, f'<path d="M1636,906 L1796,906 L1774,1060 L1658,1060 Z"'
                    f' fill="#4a5055" {o(6)}/>'
                    f'<rect x="1622" y="888" width="188" height="26" rx="10"'
                    f' fill="#5e656a" {o(4)}/>'
                    f'<rect x="1700" y="1060" width="22" height="20" fill="#3a4045"/>')
    for i in range(4):
        s += SL(Z_SRED, f'<line x1="{1656+i*38:.0f}" y1="916" x2="{1666+i*36:.0f}"'
                        f' y2="1054" stroke="#333a3e" stroke-width="5" opacity=".7"/>')
    skam = (f'<rect x="1150" y="712" width="700" height="28" rx="11" fill="url(#dosk)"'
            f' {o(6)}/>'
            f'<rect x="1150" y="636" width="700" height="24" rx="10" fill="url(#dosk)"'
            f' {o(6)}/>'
            f'<rect x="1150" y="674" width="700" height="24" rx="10" fill="url(#dosk)"'
            f' {o(6)}/>')
    for px in (1196, 1784):
        skam += (f'<rect x="{px:.0f}" y="736" width="22" height="124" rx="8"'
                 f' fill="#4a5055" {o(4)}/>'
                 f'<rect x="{px-22:.0f}" y="616" width="22" height="132" rx="8"'
                 f' fill="#4a5055" {o(4)}/>')
    s += SL(Z_SRED, skam)
    ka = 10 * A.w(t, 4.6, .2)
    kolo = f'<g transform="rotate({ka:.1f} 1016 718)"><circle cx="1016" cy="718" r="72"' \
           f' fill="none" stroke="#3a4045" stroke-width="17"/>' \
           f'<circle cx="1016" cy="718" r="19" fill="#5e656a" {o(3)}/>'
    for i in range(10):
        a = math.radians(i * 36)
        kolo += (f'<line x1="{1016+19*math.cos(a):.0f}" y1="{718+19*math.sin(a):.0f}"'
                 f' x2="{1016+64*math.cos(a):.0f}" y2="{718+64*math.sin(a):.0f}"'
                 f' stroke="#767c82" stroke-width="6"/>')
    s += SL(Z_SRED, kolo + "</g>")

    # ТРИ НАХОДКИ — ГЛАВНЫЕ ПРЕДМЕТЫ КАДРА: монета 416 px (две головы
    # прохожей), купюра 540, перчатка 420 по длинной стороне
    s += SL(Z_SRED, _moneta_krupno(336, 936, 208, t, .2, True, True, .80))
    kp = A.ease(A.seg(t, 2.4, .8))
    s += SL(Z_SRED, f'<path d="M600,904 L1134,866 L1148,1000 L614,1038 Z"'
                    f' fill="#9aa07e" {o(6)}/>'
                    f'<path d="M600,904 L1148,1000" fill="none" stroke="#7c8463"'
                    f' stroke-width="7"/>'
                    f'<path d="M700,892 L716,1020 M1012,870 L1028,998"'
                    f' stroke="#7c8463" stroke-width="6" opacity=".8"/>'
                    f'<ellipse cx="872" cy="950" rx="86" ry="52" fill="none"'
                    f' stroke="#7c8463" stroke-width="7" opacity=".7"/>'
                    f'<path d="M622,{896+30*kp:.0f} Q880,{836+30*kp:.0f}'
                    f' {1160:.0f},{884+30*kp:.0f}" fill="none" stroke="#b4762f"'
                    f' stroke-width="26" opacity="{kp*.9:.2f}"/>')
    per = (f'<path d="M1280,980 L1270,880 Q1300,856 1330,878 L1340,960'
           f' L1410,944 Q1440,956 1430,984 L1360,1016 Q1310,1030 1280,1010 Z"'
           f' fill="#7a5a86" {o(6)}/>')
    for i in range(4):
        per += (f'<path d="M{1272+i*20:.0f},{884-i*4:.0f} L{1282+i*20:.0f},'
                f'{836-i*6:.0f} Q{1300+i*20:.0f},{824-i*6:.0f}'
                f' {1312+i*20:.0f},{842-i*6:.0f} L{1304+i*20:.0f},{890-i*4:.0f} Z"'
                f' fill="#8a6a96" {o(4)}/>')
    per += (f'<path d="M1286,948 Q1340,934 1400,946 M1290,976 Q1344,962 1406,974"'
            f' fill="none" stroke="#5e4068" stroke-width="6" opacity=".8"/>')
    s += SL(Z_SRED, f'<g transform="translate(-668 -542) scale(1.58)">{per}</g>')
    for i, (chx, chy) in enumerate(((336, 770), (872, 806), (1416, 758))):
        ch = A.ease(A.seg(t, .6 + i * .6, .5))
        s += SL(Z_SRED, f'<rect x="{chx-150*ch:.0f}" y="{chy:.0f}"'
                        f' width="{300*ch:.0f}" height="20" rx="10" fill="{KRAS}"'
                        f' opacity="{ch*.9:.2f}" {o(3)}/>')
    # лист накрывает купюру
    nl = A.ease(A.seg(t, 3.2, 1.0))
    s += SL(Z_SRED, f'<g transform="rotate({40*nl:.0f} 876 {690+240*nl:.0f})">'
                    f'<path d="M720,{690+240*nl:.0f} Q876,{586+240*nl:.0f}'
                    f' {1032:.0f},{690+240*nl:.0f} Q876,{776+240*nl:.0f}'
                    f' {720:.0f},{690+240*nl:.0f} Z" fill="#b4762f" {o(5)}/></g>')

    # женщина идёт мимо, не сбавляя шага
    hod = (t * .32) % 1.0
    fx, fy, fh = 460 + 900 * hod, 1062, 680
    zh = figura(fx, fy, fh, t, col="#3f3a46", kant="#cfe4f5", ph=.2)
    r1, (sx2, sy2), (z1x, z1y) = _ruka_ekr(fx, fy, fh, 1, fh * .44, 86, t, "#3f3a46", "#cfe4f5",
                                           .1, 8)
    r2, _, (z2x, z2y) = _ruka_ekr(fx, fy, fh, -1, fh * .34, 102, t, "#3f3a46", "#cfe4f5", .5, 4)
    zh += r1 + r2
    sk = 10 * A.w(t, 1.2, .2)
    zh += (f'<g transform="rotate({sk:.1f} {sx2:.0f} {sy2:.0f})">'
           f'<rect x="{sx2-58:.0f}" y="{sy2:.0f}" width="116" height="92" rx="12"'
           f' fill="#5a3f46" {o(5)}/>'
           f'<path d="M{sx2-30:.0f},{sy2:.0f} Q{sx2:.0f},{sy2-50:.0f}'
           f' {sx2+30:.0f},{sy2:.0f}" fill="none" stroke="#5a3f46" stroke-width="8"/></g>')
    # берет
    zh += (f'<path d="M{fx-54:.0f},{fy-fh*.88:.0f} Q{fx:.0f},{fy-fh*.99:.0f}'
           f' {fx+54:.0f},{fy-fh*.88:.0f} Q{fx:.0f},{fy-fh*.82:.0f}'
           f' {fx-54:.0f},{fy-fh*.88:.0f} Z" fill="#5a3f46" {o(4)}/>'
           f'<circle cx="{fx+6:.0f}" cy="{fy-fh*.99:.0f}" r="9" fill="#5a3f46"/>')
    zh += para_izo_rta(fx + 44, fy - fh * .80, t, .2, 1.0, .5)
    s += SL(Z_SRED, zh + ten(fx, fy + 8, 110, 20, .45))
    s += SL(Z_SRED, _gorodskoy_hlam(60, 700, 420, t, 191, ["stolbik", "kust"]))
    s += SL(Z_SRED, _gorodskoy_hlam(1180, 706, 460, t, 395, ["yaschik", "velik"]))
    s += SL(Z_SRED, _gorodskoy_hlam(1380, 1062, 520, t, 193,
                                   ["yaschik", "korobka", "stolbik"]))
    s += SL(Z_SRED, _zabor_dosok(540, 600, 560, 190, 195, 56, "#3f5a46"))
    s += SL(Z_SRED, _gorodskoy_hlam(700, 1070, 440, t, 317, ["kust", "stolbik"]))
    s += SL(Z_SRED, goloe_derevo(1500, 700, 360, t, 319, 7, "#2a2b33", False))
    s += SL(Z_LETIT, mokryy_sneg(t, 20, 25, .45, .8))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def perchatka_na_zabore(t):
    """Низкий заборчик палисадника у подъезда: на столбике НА ПОЛ-КАДРА
    надета вязаная перчатка пальцами вверх. На ветке сирени чьи-то ключи с
    брелоком, на скамейке забытый плюшевый заяц. Мужчина подбегает,
    снимает перчатку ЛЕВОЙ рукой и держит обе перед собой."""
    rnd = random.Random(124)
    s = f'<rect width="{W}" height="{H}" fill="#2d3038"/>'
    s += SL(Z_DAL, panelka(620, 520, 900, t, 5, True, 11))
    s += SL(Z_DAL, panelka(1740, 500, 520, t, 5, True, 13))
    s += SL(Z_DAL, tusklaya_lampochka(1140, 300, t, 1.8, False))
    s += SL(Z_DAL, teplo(1140, 410, 280, 230, .38))
    s += SL(Z_DAL, goloe_derevo(240, 540, 480, t, 15, 9, "#2a2b33", False))
    s += SL(Z_SRED, _asfalt(540, 1080, 31, 30))

    # козырёк подъезда и дверь
    s += SL(Z_SRED, f'<rect x="900" y="300" width="420" height="300" rx="8"'
                    f' fill="#3f4650" {o(6)}/>'
                    f'<rect x="950" y="340" width="150" height="260" rx="6"'
                    f' fill="#2a3038" {o(5)}/>'
                    f'<rect x="1120" y="340" width="150" height="260" rx="6"'
                    f' fill="#2a3038" {o(5)}/>'
                    f'<rect x="860" y="268" width="500" height="36" rx="10"'
                    f' fill="#5e656a" {o(5)}/>'
                    f'<rect x="1095" y="440" width="20" height="60" rx="8"'
                    f' fill="#9aa2a8" {o(3)}/>')

    # заборчик палисадника
    s += SL(Z_SRED, _zabor_dosok(60, 686, 1100, 290, 33, 58, "#3f5a46"))
    # столбик со вязаной перчаткой — главный предмет
    px, py = 500, 700
    kch = 3.0 * A.w(t, 2.4, .1)
    s += SL(Z_SRED, f'<rect x="{px-46:.0f}" y="{py:.0f}" width="92" height="330" rx="10"'
                    f' fill="#3f5a46" {o(6)}/>'
                    f'<rect x="{px-58:.0f}" y="{py-20:.0f}" width="116" height="26"'
                    f' rx="9" fill="#4e6b54" {o(4)}/>')
    snyal = A.ease(A.seg(t, 2.8, .9))
    perch = (f'<g transform="rotate({kch:.1f} {px:.0f} {py:.0f})" '
             f'opacity="{1-snyal:.2f}">'
             f'<path d="M{px-88:.0f},{py-20:.0f} L{px-78:.0f},{py-250:.0f}'
             f' Q{px-46:.0f},{py-300:.0f} {px-14:.0f},{py-252:.0f}'
             f' L{px-6:.0f},{py-130:.0f} L{px+10:.0f},{py-290:.0f}'
             f' Q{px+42:.0f},{py-330:.0f} {px+66:.0f},{py-284:.0f}'
             f' L{px+58:.0f},{py-120:.0f} L{px+88:.0f},{py-20:.0f} Z"'
             f' fill="#7a5a86" {o(7)}/>')
    for i in range(5):
        perch += (f'<path d="M{px-84+i*6:.0f},{py-60-i*34:.0f}'
                  f' Q{px:.0f},{py-96-i*34:.0f} {px+84-i*6:.0f},{py-60-i*34:.0f}"'
                  f' fill="none" stroke="#5e4068" stroke-width="7" opacity=".8"/>')
    perch += (f'<path d="M{px-52:.0f},{py-212:.0f} Q{px:.0f},{py-250:.0f}'
              f' {px+44:.0f},{py-216:.0f}" fill="none" stroke="#9a7aa6"'
              f' stroke-width="6" opacity=".8"/></g>')
    s += SL(Z_SRED, perch)

    # ветка сирени с ключами
    s += SL(Z_SRED, _vetka_pered(1500, 420, 420, 128, t, 35, "#3a2f28", 6))
    zv = 8 * A.w(t, 2.0, .3)
    s += SL(Z_SRED, f'<g transform="rotate({zv:.1f} 1680 620)">'
                    f'<line x1="1680" y1="620" x2="1680" y2="690" stroke="{ZHELEZ}"'
                    f' stroke-width="5"/>'
                    f'<circle cx="1680" cy="702" r="22" fill="none" stroke="{ZHELEZ}"'
                    f' stroke-width="7"/>'
                    f'<path d="M1668,716 L1660,790 L1676,790 L1670,760 L1684,760"'
                    f' fill="none" stroke="url(#zhel)" stroke-width="8"/>'
                    f'<path d="M1696,716 L1704,780 L1690,780" fill="none"'
                    f' stroke="url(#zhel)" stroke-width="8"/>'
                    f'<circle cx="1712" cy="712" r="26" fill="#8a6a46" {o(3)}/>'
                    f'<circle cx="1698" cy="692" r="12" fill="#8a6a46" {o(2)}/>'
                    f'<circle cx="1726" cy="692" r="12" fill="#8a6a46" {o(2)}/></g>')

    # скамейка с плюшевым зайцем
    s += SL(Z_SRED, f'<rect x="60" y="930" width="420" height="28" rx="10"'
                    f' fill="url(#dosk)" {o(5)}/>'
                    f'<rect x="60" y="848" width="420" height="24" rx="10"'
                    f' fill="url(#dosk)" {o(5)}/>'
                    f'<rect x="96" y="958" width="24" height="120" rx="8"'
                    f' fill="#4a5055" {o(4)}/>'
                    f'<rect x="416" y="958" width="24" height="120" rx="8"'
                    f' fill="#4a5055" {o(4)}/>')
    # ПЛЮШЕВЫЙ ЗАЯЦ УБРАН (осмотр 15.11: «сцена городская»). На скамейке —
    # городские забытые вещи: сложенный зонт и авоська с покупками.
    zk = 3 * A.w(t, 2.8, .4)
    s += SL(Z_SRED, f'<g transform="rotate({zk:.1f} 150 928)">'
                    f'<rect x="92" y="800" width="26" height="128" rx="10"'
                    f' fill="#3a4452" {o(4)}/>'
                    f'<path d="M86,800 Q105,748 124,800 Q134,836 105,844'
                    f' Q78,838 86,800 Z" fill="#46506a" {o(5)}/>'
                    f'<rect x="98" y="760" width="14" height="48" rx="6"'
                    f' fill="#6a7488" opacity=".8"/>'
                    f'<path d="M118,924 q26,22 44,-4" fill="none" stroke="#2a3038"'
                    f' stroke-width="9"/></g>')
    avos = (f'<path d="M250,932 Q238,1010 310,1022 Q384,1012 372,932 Z"'
            f' fill="#6a7a5e" opacity=".55" {o(5)}/>')
    for i in range(5):
        avos += (f'<line x1="{258+i*29:.0f}" y1="938" x2="{266+i*26:.0f}" y2="1018"'
                 f' stroke="#8a9a76" stroke-width="4" opacity=".8"/>'
                 f'<path d="M248,{950+i*16:.0f} Q310,{964+i*16:.0f}'
                 f' {374:.0f},{948+i*16:.0f}" fill="none" stroke="#8a9a76"'
                 f' stroke-width="4" opacity=".7"/>')
    avos += (f'<circle cx="286" cy="976" r="32" fill="#a8482f" {o(4)}/>'
             f'<circle cx="340" cy="986" r="27" fill="#8a9a3a" {o(4)}/>'
             f'<ellipse cx="312" cy="944" rx="38" ry="20" fill="#c8a24a" {o(3)}/>'
             f'<path d="M254,934 Q268,886 296,906 M366,934 Q352,886 324,906"'
             f' fill="none" stroke="#6a7a5e" stroke-width="9"/>')
    s += SL(Z_SRED, avos)

    # мужчина подбегает и прижимает перчатки к груди
    beg = A.ease(A.seg(t, .3, 1.6))
    fx, fy, fh = 1500 - 620 * beg, 1046, 560
    m = figura(fx, fy, fh, t, col="#3a4452", kant="#cfe4f5", ph=.2, naklon=-12 * (1 - beg))
    # СНИМАЕТ ЛЕВОЙ: столбик с перчаткой стоит СЛЕВА от него, и тянуться
    # туда правой рукой значило вести рукав бруском через голову на 206 px
    # за ось тела (осмотр 15.11). Обе перчатки он потом держит перед собой,
    # но не на груди: рукав без кисти, прижатый к груди, читается палкой.
    r2, (hx2, hy2), (m2x, m2y) = _ruka(fx, fy, fh, -1, fh * (.58 - .18 * snyal),
                                       -12 + 46 * snyal, t, "#3a4452", "#cfe4f5", .5, 5)
    r1, (hx1, hy1), (m1x, m1y) = _ruka(fx, fy, fh, 1, fh * (.34 + .08 * snyal),
                                       26 + 18 * snyal, t, "#3a4452", "#cfe4f5", .1, 7)
    m += r1 + r2
    # вторая перчатка в правой руке с самого начала
    m += (f'<path d="M{hx1-32:.0f},{hy1-46:.0f} L{hx1-24:.0f},{hy1-104:.0f}'
          f' Q{hx1-4:.0f},{hy1-130:.0f} {hx1+14:.0f},{hy1-102:.0f}'
          f' L{hx1+20:.0f},{hy1-44:.0f} L{hx1+32:.0f},{hy1+6:.0f}'
          f' Q{hx1:.0f},{hy1+22:.0f} {hx1-32:.0f},{hy1+6:.0f} Z" fill="#7a5a86"'
          f' {o(5)}/>')
    # снятая перчатка приходит в левую руку
    if snyal > .02:
        m += (f'<g opacity="{snyal:.2f}">'
              f'<path d="M{hx2-32:.0f},{hy2-46:.0f} L{hx2-24:.0f},{hy2-104:.0f}'
              f' Q{hx2-4:.0f},{hy2-130:.0f} {hx2+14:.0f},{hy2-102:.0f}'
              f' L{hx2+20:.0f},{hy2-44:.0f} L{hx2+32:.0f},{hy2+6:.0f}'
              f' Q{hx2:.0f},{hy2+22:.0f} {hx2-32:.0f},{hy2+6:.0f} Z"'
              f' fill="#8a6a96" {o(5)}/></g>')
    m += para_izo_rta(fx + 44, fy - fh * .80, t, .2, 1.0, .5)
    s += SL(Z_SRED, m + ten(fx, fy + 8, 110, 20, .45))
    s += SL(Z_SRED, _gorodskoy_hlam(1380, 1070, 520, t, 197,
                                   ["velik", "yaschik", "stolbik"]))
    s += SL(Z_SRED, _gorodskoy_hlam(640, 1074, 420, t, 199, ["korobka", "kust"]))
    s += SL(Z_SRED, _gorodskoy_hlam(300, 700, 380, t, 313, ["stolbik", "kust"]))
    s += SL(Z_SRED, _zabor_dosok(900, 780, 520, 200, 315, 56, "#3f5a46"))
    s += SL(Z_LETIT, mokryy_sneg(t, 18, 27, .45, .8))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def babushkin_shag_u_podezda(t):
    """Дорожка к подъезду, посреди неё блестит монета. Женщина в пальто идёт
    к подъезду и перешагивает монету; рядом полупрозрачным контуром тем же
    движением шагает бабушка в платке с бидоном. Клумба, скамейка, кот."""
    rnd = random.Random(125)
    s = f'<rect width="{W}" height="{H}" fill="#2d3038"/>'
    s += SL(Z_DAL, panelka(500, 500, 820, t, 5, True, 15)
            + panelka(1620, 480, 600, t, 5, True, 17))
    s += SL(Z_DAL, goloe_derevo(180, 510, 440, t, 19, 8, "#2a2b33", False))
    s += SL(Z_DAL, tusklaya_lampochka(960, 250, t, 1.8, False))
    s += SL(Z_DAL, teplo(960, 370, 300, 240, .38))
    s += SL(Z_SRED, _asfalt(520, 1080, 37, 32))
    s += SL(Z_SRED, f'<path d="M620,1080 Q780,820 900,600 L1120,600 Q1200,820'
                    f' 1360,1080 Z" fill="#62646a" opacity=".9"/>')

    # подъезд
    s += SL(Z_SRED, f'<rect x="840" y="320" width="340" height="300" rx="8"'
                    f' fill="#3f4650" {o(6)}/>'
                    f'<rect x="880" y="356" width="124" height="262" rx="6"'
                    f' fill="#2a3038" {o(5)}/>'
                    f'<rect x="1018" y="356" width="124" height="262" rx="6"'
                    f' fill="#2a3038" {o(5)}/>'
                    f'<rect x="806" y="292" width="408" height="34" rx="10"'
                    f' fill="#5e656a" {o(5)}/>')

    # клумба и скамейка
    klm = (f'<path d="M80,900 Q300,840 520,900 Q300,970 80,900 Z" fill="#4a3f33" {o(5)}/>')
    for i in range(9):
        cx_ = 120 + i * 48
        kk = 4 * A.w(t, 3.0, i * .2)
        klm += (f'<g transform="rotate({kk:.1f} {cx_:.0f} 900)">'
                f'<line x1="{cx_:.0f}" y1="900" x2="{cx_+6:.0f}" y2="{824:.0f}"'
                f' stroke="#5e6b42" stroke-width="6"/>'
                f'<circle cx="{cx_+6:.0f}" cy="816" r="18"'
                f' fill="{["#b4762f","#8a5a86","#9a5a28"][i%3]}" {o(2)}/></g>')
    s += SL(Z_SRED, klm)
    skam = (f'<rect x="1080" y="840" width="800" height="32" rx="12" fill="url(#dosk)"'
            f' {o(6)}/>'
            f'<rect x="1080" y="752" width="800" height="28" rx="11" fill="url(#dosk)"'
            f' {o(6)}/>'
            f'<rect x="1080" y="796" width="800" height="28" rx="11" fill="url(#dosk)"'
            f' {o(6)}/>'
            f'<rect x="1124" y="872" width="26" height="130" rx="9" fill="#4a5055" {o(4)}/>'
            f'<rect x="1810" y="872" width="26" height="130" rx="9" fill="#4a5055" {o(4)}/>'
            f'<rect x="160" y="620" width="1180" height="34" rx="12" fill="#7a7c80"'
            f' {o(5)}/>')
    s += SL(Z_SRED, skam)
    # КОТ ЧИТАЕТСЯ КОТОМ (осмотр 15.11: было чёрное пятно с двумя точками)
    s += SL(Z_SRED, _kot_zhivoy(1596, 840, t, 1.35, "#4a423c", .3))

    # монета на дорожке
    s += SL(Z_SRED, _moneta_krupno(960, 900, 88, t, .2, True, True, .84))

    hod = (t * .30) % 1.0
    pere = max(.0, math.sin(hod * math.pi)) * 120

    # сегодняшняя женщина
    fx, fy, fh = 500 + 820 * hod, 1046, 580
    zh = figura(fx, fy - pere * .12, fh, t, col="#3f3a46", kant="#cfe4f5", ph=.2)
    r1, (sx2, sy2), (z1x, z1y) = _ruka_ekr(fx, fy, fh, 1, fh * .44, 90, t, "#3f3a46", "#cfe4f5",
                                           .1, 7)
    r2, _, (z2x, z2y) = _ruka_ekr(fx, fy, fh, -1, fh * .30, 54, t, "#3f3a46", "#cfe4f5", .5, 4)
    zh += r1 + r2
    zh += (f'<rect x="{sx2-54:.0f}" y="{sy2:.0f}" width="108" height="104" rx="10"'
           f' fill="#8a7a58" {o(5)}/>'
           f'<path d="M{sx2-30:.0f},{sy2:.0f} Q{sx2:.0f},{sy2-44:.0f}'
           f' {sx2+30:.0f},{sy2:.0f}" fill="none" stroke="#8a7a58" stroke-width="8"/>'
           f'<ellipse cx="{sx2:.0f}" cy="{sy2+30:.0f}" rx="40" ry="24" fill="#c9a86a"'
           f' {o(3)}/>')
    # поднятая нога
    zh += (f'<line x1="{fx+20:.0f}" y1="{fy-fh*.30:.0f}" x2="{fx+78:.0f}"'
           f' y2="{fy-10-pere:.0f}" stroke="#3f3a46" stroke-width="40"'
           f' stroke-linecap="round"/>')
    zh += para_izo_rta(fx + 44, fy - fh * .80, t, .2, 1.0, .5)
    s += SL(Z_SRED, zh + ten(fx, fy + 8, 110, 20, .45))

    # бабушка полупрозрачным контуром, то же движение
    gx = fx - 230
    bab = figura(gx, fy - pere * .12, 560, t, col="#6a7a8a", kant="#cfe4f5",
                 platok=True, ph=.5, op=.42, tulup=True)
    r3, (bx2, by2), (g1x, g1y) = _ruka_ekr(gx, fy, 560, 1, 560 * .44, 78, t, "#6a7a8a",
                                           "#cfe4f5", .3, 7)
    r4, _, (g2x, g2y) = _ruka_ekr(gx, fy, 560, -1, 560 * .24, -100, t, "#6a7a8a", "#cfe4f5", .7, 4)
    bab += r3 + r4
    bid = 10 * A.w(t, 1.3, .2)
    bab += (f'<g transform="rotate({bid:.1f} {bx2:.0f} {by2:.0f})" opacity=".45">'
            f'<rect x="{bx2-42:.0f}" y="{by2:.0f}" width="84" height="110" rx="10"'
            f' fill="#8fa2b4" {o(4)}/>'
            f'<rect x="{bx2-50:.0f}" y="{by2-14:.0f}" width="100" height="22" rx="8"'
            f' fill="#8fa2b4" {o(3)}/>'
            f'<path d="M{bx2-30:.0f},{by2-14:.0f} Q{bx2:.0f},{by2-60:.0f}'
            f' {bx2+30:.0f},{by2-14:.0f}" fill="none" stroke="#8fa2b4"'
            f' stroke-width="8"/></g>')
    bab += (f'<line x1="{gx+20:.0f}" y1="{fy-560*.30:.0f}" x2="{gx+78:.0f}"'
            f' y2="{fy-10-pere:.0f}" stroke="#6a7a8a" stroke-width="40"'
            f' stroke-linecap="round" opacity=".42"/>')
    s += SL(Z_SRED, bab)
    s += SL(Z_SRED, _gorodskoy_hlam(60, 1072, 460, t, 201,
                                   ["yaschik", "stolbik", "korobka"]))
    s += SL(Z_SRED, _gorodskoy_hlam(1400, 1076, 480, t, 203, ["velik", "kust"]))
    s += SL(Z_SRED, _gorodskoy_hlam(300, 1078, 440, t, 399, ["yaschik", "korobka"]))
    # НИЖНЯЯ ТРЕТЬ ОБЖИТА: мокрая дорожка со следами, лужа с отражением
    # подъезда, сгребённые к бордюру листья (осмотр 15.11 — голый асфальт)
    s += SL(Z_SRED, _sledy(640, 1074, 912, 736, 7, 205, "#4a4b50", 1.35)
            + _luzha(1246, 992, 214, t, .4, 72, "#8ea6bb")
            + _kucha_listev(690, 1062, 290, 207, 88)
            + _kucha_listev(1664, 1074, 320, 211, 102))
    s += SL(Z_LETIT, mokryy_sneg(t, 18, 29, .45, .8))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def larek_s_iriskami(t):
    """Фанерный ларёк с навесом и окошком на пол-кадра: на полке за стеклом
    банки с леденцами, пряники, коробка ирисок, весы. В окошке — настоящие
    ириски. Мальчик на цыпочках протягивает монетку, продавщица в белом
    колпаке подаёт ему ириску."""
    rnd = random.Random(126)
    s = nebo("den", t, False, 59)
    s += oblaka(t, 120, 5, 47, .45)
    s += SL(Z_DAL, panelka(260, 520, 560, t, 4, True, 19)
            + panelka(1700, 500, 520, t, 4, True, 21))
    s += SL(Z_DAL, goloe_derevo(120, 560, 430, t, 23, 8, "#2a2b33", False))
    s += SL(Z_SRED, _asfalt(560, 1080, 41, 30))

    # корпус ларька
    lx, ly, lw, lh = 420, 230, 1120, 720
    lar = (f'<rect x="{lx:.0f}" y="{ly:.0f}" width="{lw:.0f}" height="{lh:.0f}" rx="10"'
           f' fill="url(#dosk)" {o(7)}/>')
    for i in range(9):
        lar += (f'<rect x="{lx+10+i*(lw-20)/9:.0f}" y="{ly+10:.0f}"'
                f' width="{(lw-20)/9-10:.0f}" height="{lh-20:.0f}" rx="6"'
                f' fill="#7d6a48" {o(3)}/>')
    # навес
    lar += (f'<path d="M{lx-70:.0f},{ly:.0f} L{lx+lw/2:.0f},{ly-130:.0f}'
            f' L{lx+lw+70:.0f},{ly:.0f} Z" fill="#8a4a4a" {o(6)}/>'
            f'<rect x="{lx-86:.0f}" y="{ly-10:.0f}" width="{lw+172:.0f}" height="30"'
            f' rx="10" fill="#6a3a3a" {o(5)}/>')
    for i in range(10):
        lar += (f'<rect x="{lx-60+i*(lw+120)/10:.0f}" y="{ly-6:.0f}"'
                f' width="{(lw+120)/20:.0f}" height="26" fill="#a85a5a"'
                f' opacity=".75"/>')
    s += SL(Z_SRED, lar)

    # полка за стеклом: банки, пряники, коробка ирисок, весы
    s += SL(Z_SRED, f'<rect x="{lx+60:.0f}" y="{ly+70:.0f}" width="{lw-120:.0f}"'
                    f' height="230" rx="8" fill="#2e3a40" {o(5)}/>'
                    f'<rect x="{lx+60:.0f}" y="{ly+290:.0f}" width="{lw-120:.0f}"'
                    f' height="22" rx="8" fill="#5b4428" {o(4)}/>')
    bank = ""
    for i in range(4):
        bx_ = lx + 150 + i * 150
        bank += (f'<rect x="{bx_-52:.0f}" y="{ly+140:.0f}" width="104" height="150"'
                 f' rx="12" fill="#9fc4da" opacity=".8" {o(4)}/>'
                 f'<rect x="{bx_-58:.0f}" y="{ly+122:.0f}" width="116" height="26"'
                 f' rx="9" fill="#c9c2ae" {o(3)}/>')
        for k in range(7):
            bank += (f'<circle cx="{bx_-34+(k%3)*34:.0f}" cy="{ly+200+(k//3)*32:.0f}"'
                     f' r="16" fill="{["#c84a3a","#d8a14a","#6f9a5e"][k%3]}"'
                     f' opacity=".95"/>')
    bank += (f'<rect x="{lx+760:.0f}" y="{ly+170:.0f}" width="190" height="120" rx="8"'
             f' fill="#b4762f" {o(5)}/>'
             f'<rect x="{lx+760:.0f}" y="{ly+170:.0f}" width="190" height="26" rx="7"'
             f' fill="#8a5a22" {o(3)}/>')
    for k in range(6):
        bank += _iriska(lx + 794 + (k % 3) * 60, ly + 224 + (k // 3) * 44,
                        .78, -18 + (k % 3) * 22, "#7d4f1c", "#e8dcc0")
    s += SL(Z_SRED, bank)

    # весы с качающейся чашей
    vx_, vy_ = lx + 1000, ly + 300
    nak = 8 * A.w(t, 1.6, .2)
    s += SL(Z_SRED, f'<rect x="{vx_-14:.0f}" y="{vy_-150:.0f}" width="28" height="150"'
                    f' rx="9" fill="{ZHELEZ}" {o(4)}/>'
                    f'<g transform="rotate({nak:.1f} {vx_:.0f} {vy_-150:.0f})">'
                    f'<rect x="{vx_-90:.0f}" y="{vy_-160:.0f}" width="180" height="16"'
                    f' rx="7" fill="{ZHELEZ}" {o(3)}/>'
                    f'<path d="M{vx_-120:.0f},{vy_-110:.0f} Q{vx_-80:.0f},{vy_-64:.0f}'
                    f' {vx_-40:.0f},{vy_-110:.0f} Z" fill="url(#zhel)" {o(4)}/>'
                    f'<path d="M{vx_+40:.0f},{vy_-110:.0f} Q{vx_+80:.0f},{vy_-64:.0f}'
                    f' {vx_+120:.0f},{vy_-110:.0f} Z" fill="url(#zhel)" {o(4)}/>'
                    f'<line x1="{vx_-80:.0f}" y1="{vy_-144:.0f}" x2="{vx_-80:.0f}"'
                    f' y2="{vy_-110:.0f}" stroke="{ZHELEZ}" stroke-width="4"/>'
                    f'<line x1="{vx_+80:.0f}" y1="{vy_-144:.0f}" x2="{vx_+80:.0f}"'
                    f' y2="{vy_-110:.0f}" stroke="{ZHELEZ}" stroke-width="4"/></g>')

    # окошко-витрина: нарисованный вид, метка, потом переплёт поверх
    px_, py_, pw_, ph_ = 560, 560, 800, 300
    put = kontur_proema(px_, py_, pw_, ph_, "pryam")
    vit = (f'<path d="{put}" fill="#6a4a28"/>')
    # В ОКОШКЕ — ИРИСКИ В ФАНТИКАХ (были жёлтые кружки = мелочь)
    for i in range(11):
        vit += _iriska(px_ + 70 + i * 66, py_ + ph_ * .5 + ((i % 3) - 1) * 60,
                       1.12, -26 + (i % 4) * 17, "#8a5a22", "#efe2c2")
    s += SL(Z_SRED, vit + mesto_stoka(px_, py_, pw_, ph_, "pryam")
            + f'<path d="{put}" fill="none" stroke="#5b4428" stroke-width="18"/>'
            + f'<rect x="{px_-20:.0f}" y="{py_+ph_-6:.0f}" width="{pw_+40:.0f}"'
              f' height="40" rx="10" fill="#8a7248" {o(5)}/>')
    s += SL(Z_SRED, lampa(960, 150, t, 1.3, True))
    s += SL(Z_SRED, teplo(960, 700, 460, 300, .36))

    # мальчик на цыпочках
    cyp = 24 * A.ease(abs(A.w(t, 2.0, .0)))
    mx_, my_, mh_ = 620, 1050 - cyp, 420
    mal = figura(mx_, my_, mh_, t, col="#3a4452", kant="#ffd98a", ph=.3)
    # ТЯНЕТСЯ ОДНОЙ РУКОЙ — к окошку, оно справа от него. Было: оба рукава
    # задраны вверх под -46° и -24°, в кадре это поза распятия (осмотр 15.11)
    r1, (hx1, hy1), (m1x, m1y) = _ruka(mx_, my_, mh_, 1, mh_ * .54, -44, t, "#3a4452",
                                       "#ffd98a", .2, 5)
    r2, _, (m2x, m2y) = _ruka(mx_, my_, mh_, -1, mh_ * .40, 64, t, "#3a4452",
                              "#ffd98a", .6, 4)
    mal += r1 + r2
    mal += _moneta_krupno(hx1, hy1 - 14, 26, t, .2, True, False, .9)
    # кепка
    mal += (f'<path d="M{mx_-50:.0f},{my_-mh_*.88:.0f} Q{mx_:.0f},{my_-mh_*1.0:.0f}'
            f' {mx_+50:.0f},{my_-mh_*.88:.0f} Z" fill="#2f3a44" {o(4)}/>'
            f'<rect x="{mx_+28:.0f}" y="{my_-mh_*.90:.0f}" width="54" height="16"'
            f' rx="7" fill="#2f3a44" {o(3)}/>')
    s += SL(Z_SRED, mal + ten(mx_, 1056, 78, 15, .45))

    # продавщица в белом колпаке
    px2, py2, ph2 = 1360, 1046, 470
    pro = figura(px2, py2, ph2, t, col="#e4e0d4", kant="#ffd98a", ph=.6)
    r3, _, (p1x, p1y) = _ruka_ekr(px2, py2, ph2, 1, ph2 * .40, -12, t, "#e4e0d4", "#ffd98a", .3, 4)
    r4, (hx2, hy2), (p2x, p2y) = _ruka_ekr(px2, py2, ph2, -1, ph2 * .54, -168, t, "#e4e0d4",
                                           "#ffd98a", .7, 5)
    pro += r3 + r4
    pro += (f'<rect x="{px2-46:.0f}" y="{py2-ph2*1.04:.0f}" width="92" height="76"'
            f' rx="12" fill="#f4f1e8" {o(4)}/>'
            f'<rect x="{px2-52:.0f}" y="{py2-ph2*.92:.0f}" width="104" height="22"'
            f' rx="9" fill="#e0dccc" {o(3)}/>')
    # ириска переходит из руки в руку
    ir = A.ease(A.seg(t, 1.4, 1.2))
    irx = hx2 + (hx1 - hx2) * ir
    iry = hy2 + (hy1 - 30 - hy2) * ir - 60 * math.sin(math.pi * ir)
    pro += _iriska(irx, iry, 1.45, 24 * ir, "#8a5a22", "#efe2c2")
    s += SL(Z_SRED, pro + ten(px2, 1052, 90, 17, .45))
    s += SL(Z_SRED, _gorodskoy_hlam(80, 1070, 320, t, 207, ["yaschik", "korobka"]))
    s += SL(Z_SRED, _gorodskoy_hlam(1620, 1074, 320, t, 209, ["stolbik", "kust"]))
    s += SL(Z_PERED, _stolb_pered(1880, 90, "#1d1611", 0, H))
    s += SL(Z_LETIT, sneg_letit(t, 12, 49, .28, .55))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def pyatak_v_tufle(t):
    """Школьный коридор, скамья у двери с табличкой без надписи. Школьница в
    форме с белым фартуком сидит на скамье: левая нога на полу, правая на
    левом колене. Левой держит снятую туфлю, правой кладёт под пятку пятак.
    Рядом портфель, зачётная книжка, букет астр."""
    rnd = random.Random(127)
    pol = 800
    s = f'<rect width="{W}" height="{H}" fill="#3a4442"/>'
    s += SL(Z_DAL, f'<rect x="0" y="0" width="{W}" height="{pol:.0f}" fill="#54645e"/>'
                   f'<rect x="0" y="{pol-260:.0f}" width="{W}" height="260"'
                   f' fill="#6e7d74" opacity=".9"/>'
                   f'<rect x="0" y="{pol-274:.0f}" width="{W}" height="22"'
                   f' fill="#3e4a46" opacity=".9"/>'
                   f'<rect x="0" y="{pol-20:.0f}" width="{W}" height="34"'
                   f' fill="#2f3a36" opacity=".9"/>')
    # пол шашками
    sh = ""
    yy, ry = pol + 14, 0
    while yy < H:
        step = 120 + (yy - pol) * .5
        xx = -((ry % 2) * step / 2)
        while xx < W:
            sh += (f'<rect x="{xx:.0f}" y="{yy:.0f}" width="{step:.0f}"'
                   f' height="{step*.5:.0f}" fill="{["#6a5a4a","#4e4238"][ry%2]}"'
                   f' opacity=".85"/>')
            xx += step * 2
        yy += step * .5
        ry += 1
    s += SL(Z_DAL, sh)

    # две двери с табличками без надписи
    for i, dx in enumerate((160, 1500)):
        s += SL(Z_DAL, f'<rect x="{dx:.0f}" y="190" width="300" height="610" rx="8"'
                       f' fill="#6a5a3c" {o(6)}/>'
                       f'<rect x="{dx+24:.0f}" y="220" width="252" height="250" rx="6"'
                       f' fill="#7d6a48" {o(4)}/>'
                       f'<rect x="{dx+24:.0f}" y="500" width="252" height="270" rx="6"'
                       f' fill="#7d6a48" {o(4)}/>'
                       f'<rect x="{dx+250:.0f}" y="480" width="22" height="70" rx="9"'
                       f' fill="{ZHELEZ}" {o(3)}/>'
                       f'<rect x="{dx+90:.0f}" y="128" width="130" height="52" rx="7"'
                       f' fill="#e4dcc4" {o(4)}/>'
                       f'<path d="M{dx+104:.0f},154 Q{dx+140:.0f},142 {dx+178:.0f},156"'
                       f' fill="none" stroke="#9aa0a4" stroke-width="5"/>')
    # окно коридора и свет
    s += SL(Z_DAL, okno_izby(760, 150, 420, 330, t, svet=False, moroz=.0)
            + f'<rect x="780" y="168" width="382" height="296" fill="#aebfcc"'
              f' opacity=".9"/>')
    s += SL(Z_SRED, luch(700, 480, 520, 420, t, .20))
    s += SL(Z_SRED, tusklaya_lampochka(960, 70, t, 1.6, True))
    s += SL(Z_SRED, teplo(960, 300, 380, 280, .32))

    s += SL(Z_SRED, _gorodskoy_hlam(1500, 1076, 420, t, 211, ["yaschik", "kust"]))
    s += SL(Z_SRED, _gorodskoy_hlam(80, 1070, 360, t, 293, ["stolbik", "korobka"]))
    s += SL(Z_SRED, _kot_zhivoy(1760, 1062, t, 1.2, "#4a423c", .5))
    # батарея под окном
    bat = f'<rect x="700" y="560" width="540" height="140" rx="10" fill="#b9bcc0" {o(5)}/>'
    for i in range(11):
        bat += (f'<rect x="{716+i*48:.0f}" y="570" width="30" height="120" rx="9"'
                f' fill="#cdd1d4" {o(3)}/>')
    s += SL(Z_SRED, bat)
    # вешалка с пальто
    s += SL(Z_SRED, f'<rect x="1320" y="300" width="420" height="22" rx="9"'
                    f' fill="#5e4a3a" {o(5)}/>'
                    f'<rect x="1500" y="322" width="24" height="420" rx="9"'
                    f' fill="#5e4a3a" {o(4)}/>')
    for i in range(4):
        hx2 = 1360 + i * 108
        s += SL(Z_SRED, f'<rect x="{hx2-8:.0f}" y="308" width="16" height="40"'
                        f' fill="{ZHELEZ}" {o(2)}/>'
                        f'<path d="M{hx2-60:.0f},{360:.0f} Q{hx2:.0f},{330:.0f}'
                        f' {hx2+60:.0f},{360:.0f} L{hx2+74:.0f},{640:.0f}'
                        f' L{hx2-74:.0f},{640:.0f} Z"'
                        f' fill="{["#3a4452","#5a3340","#3d4a3a","#4a3b2a"][i]}"'
                        f' {o(5)}/>')
    # доска объявлений без текста
    s += SL(Z_SRED, f'<rect x="240" y="300" width="380" height="280" rx="10"'
                    f' fill="#6b5a3c" {o(5)}/>'
                    f'<rect x="262" y="322" width="336" height="236" rx="6"'
                    f' fill="#3a4a44" {o(3)}/>')
    for i in range(3):
        s += SL(Z_SRED, f'<rect x="{286+i*110:.0f}" y="{348+(i%2)*90:.0f}" width="90"'
                        f' height="120" rx="5" fill="#e8e2d2" {o(2)}/>')
    # скамья
    s += SL(Z_SRED, _lavka_krupno(380, 1010, 1180, t, 216, True))
    # портфель, зачётка, астры НА скамье
    s += SL(Z_SRED, f'<rect x="1160" y="640" width="190" height="130" rx="10"'
                    f' fill="#5e3a2a" {o(5)}/>'
                    f'<rect x="1160" y="690" width="190" height="20" fill="#3a2419"'
                    f' opacity=".8"/>'
                    f'<rect x="1230" y="614" width="50" height="34" rx="12"'
                    f' fill="{ZHELEZ}" {o(3)}/>'
                    f'<rect x="1000" y="730" width="124" height="40" rx="5"'
                    f' fill="#8a3a3a" {o(4)}/>'
                    f'<rect x="1004" y="736" width="116" height="28" rx="4"'
                    f' fill="#e8e2d2" {o(2)}/>')
    ast = ""
    for i in range(7):
        ax = 250 + i * 32
        kk = 4 * A.w(t, 2.6, i * .25)
        ast += (f'<g transform="rotate({kk:.1f} {ax:.0f} 752)">'
                f'<line x1="{ax:.0f}" y1="752" x2="{ax+8:.0f}" y2="620"'
                f' stroke="#5e6b42" stroke-width="7"/>')
        for k in range(8):
            a = math.radians(k * 45)
            ast += (f'<ellipse cx="{ax+8+26*math.cos(a):.0f}"'
                    f' cy="{612+26*math.sin(a):.0f}" rx="16" ry="7"'
                    f' transform="rotate({k*45} {ax+8+26*math.cos(a):.0f}'
                    f' {612+26*math.sin(a):.0f})"'
                    f' fill="{["#b07ab0","#d4a0cc","#8a6aa6"][i%3]}" opacity=".95"/>')
        ast += (f'<circle cx="{ax+8:.0f}" cy="612" r="13" fill="#e8c86a"/></g>')
    s += SL(Z_SRED, ast)

    # школьница
    fx, fy, fh = 820, 790, 500
    put_ = A.ease(A.seg(t, .5, 1.0))
    vst = A.ease(A.seg(t, 2.6, .9))
    # пока сидит — короткий торс над скамьёй, встала — полный рост
    sit = 1 - vst
    fh_ = fh + 200 * vst
    fy_ = fy - 10 - 230 * vst
    shk = figura(fx, fy_, fh_, t, col="#3a3a46", kant="#ffd98a",
                 ph=.3, naklon=-8 * sit)
    r1, (hx1, hy1), (s1x, s1y) = _ruka_ekr(fx, fy_, fh_, 1, fh_ * .56, 64 - 40 * vst, t,
                                           "#3a3a46", "#ffd98a", .2, 5)
    r2, (hx2, hy2), (s2x, s2y) = _ruka_ekr(fx, fy_, fh_, -1, fh_ * .52, 108 - 30 * vst, t,
                                           "#3a3a46", "#ffd98a", .6, 4)
    shk += r1 + r2
    # белый фартук поверх формы
    byy = fy_
    shk += (f'<path d="M{fx-34:.0f},{byy-fh_*.56:.0f} L{fx+34:.0f},{byy-fh_*.56:.0f}'
            f' L{fx+48:.0f},{byy-fh_*.12:.0f} L{fx-48:.0f},{byy-fh_*.12:.0f} Z"'
            f' fill="#f2efe6" opacity=".95" {o(4)}/>'
            f'<path d="M{fx-26:.0f},{byy-fh_*.56:.0f} L{fx-16:.0f},{byy-fh_*.70:.0f}'
            f' M{fx+26:.0f},{byy-fh_*.56:.0f} L{fx+16:.0f},{byy-fh_*.70:.0f}"'
            f' stroke="#f2efe6" stroke-width="9"/>')
    # ТУФЛЯ И ПЯТАК — ГЛАВНЫЙ ПРЕДМЕТ КАДРА. Осмотр 15.11: «пятак и туфля не
    # опознаются» — туфля была 144 px безымянным пятном, пятак 60 px. Теперь
    # туфля 420 px с каблуком, подошвой, ремешком и стоптанным носком, пятак
    # 132 px ложится под пятку, и его видно поштучно.
    tx_, ty_ = hx2 - 36, hy2 + 24
    shk += (f'<ellipse cx="{tx_+10:.0f}" cy="{ty_+58:.0f}" rx="200" ry="30"'
            f' fill="#1f1714" opacity=".45"/>'
            f'<path d="M{tx_-206:.0f},{ty_+34:.0f} Q{tx_-196:.0f},{ty_-76:.0f}'
            f' {tx_-96:.0f},{ty_-104:.0f} Q{tx_+8:.0f},{ty_-122:.0f}'
            f' {tx_+104:.0f},{ty_-66:.0f} L{tx_+196:.0f},{ty_+8:.0f}'
            f' Q{tx_+210:.0f},{ty_+42:.0f} {tx_+150:.0f},{ty_+48:.0f}'
            f' L{tx_-196:.0f},{ty_+48:.0f} Z" fill="#4a2f2a" {o(7)}/>'
            f'<path d="M{tx_-196:.0f},{ty_+48:.0f} L{tx_+176:.0f},{ty_+24:.0f}'
            f' L{tx_+186:.0f},{ty_+54:.0f} L{tx_-194:.0f},{ty_+78:.0f} Z"'
            f' fill="#2a1a16" {o(5)}/>'
            f'<path d="M{tx_-196:.0f},{ty_+76:.0f} L{tx_-120:.0f},{ty_+72:.0f}'
            f' L{tx_-114:.0f},{ty_+146:.0f} L{tx_-186:.0f},{ty_+150:.0f} Z"'
            f' fill="#33211c" {o(5)}/>'
            f'<path d="M{tx_-176:.0f},{ty_-24:.0f} Q{tx_-86:.0f},{ty_-56:.0f}'
            f' {tx_+16:.0f},{ty_-62:.0f} Q{tx_+96:.0f},{ty_-54:.0f}'
            f' {tx_+150:.0f},{ty_-6:.0f}" fill="none" stroke="#6a443c"'
            f' stroke-width="10" opacity=".8"/>'
            f'<path d="M{tx_-118:.0f},{ty_-98:.0f} Q{tx_-20:.0f},{ty_-54:.0f}'
            f' {tx_+90:.0f},{ty_-70:.0f}" fill="none" stroke="#33211c"'
            f' stroke-width="16" opacity=".85"/>'
            f'<ellipse cx="{tx_+34:.0f}" cy="{ty_-74:.0f}" rx="20" ry="13"'
            f' fill="#c9a86a" {o(3)}/>'
            f'<path d="M{tx_+120:.0f},{ty_-44:.0f} Q{tx_+168:.0f},{ty_-26:.0f}'
            f' {tx_+188:.0f},{ty_+6:.0f}" fill="none" stroke="#8a6258"'
            f' stroke-width="9" opacity=".7"/>'
            f'<path d="M{tx_-178:.0f},{ty_-6:.0f} Q{tx_-90:.0f},{ty_+20:.0f}'
            f' {tx_+120:.0f},{ty_-2:.0f}" fill="none" stroke="#2a1a16"'
            f' stroke-width="7" opacity=".55"/>')
    px3 = hx1 + (tx_ - 150 - hx1) * put_
    py3 = hy1 + (ty_ + 6 - hy1) * put_
    shk += _moneta_krupno(px3, py3, 66, t, .2, True, True, .72)
    # нога на колене / обе на полу
    # сидит: левая нога на полу, правая закинута на левое колено
    bedr_x, bedr_y = fx - 40, byy - 6
    kol_x, kol_y = fx - 180 * sit, byy + 100 * sit
    shk += (f'<line x1="{bedr_x:.0f}" y1="{bedr_y:.0f}" x2="{kol_x:.0f}"'
            f' y2="{kol_y:.0f}" stroke="#3a3a46" stroke-width="46"'
            f' stroke-linecap="round" opacity="{sit:.2f}"/>'
            f'<line x1="{kol_x:.0f}" y1="{kol_y:.0f}" x2="{kol_x+8:.0f}"'
            f' y2="{1010:.0f}" stroke="#3a3a46" stroke-width="44"'
            f' stroke-linecap="round" opacity="{sit:.2f}"/>'
            f'<ellipse cx="{kol_x+2:.0f}" cy="{1024:.0f}" rx="56" ry="22"'
            f' fill="#4a2f2a" opacity="{sit:.2f}" {o(4)}/>'
            f'<line x1="{bedr_x+80:.0f}" y1="{bedr_y:.0f}" x2="{kol_x-30:.0f}"'
            f' y2="{kol_y-30:.0f}" stroke="#3a3a46" stroke-width="46"'
            f' stroke-linecap="round" opacity="{sit:.2f}"/>'
            f'<line x1="{kol_x-30:.0f}" y1="{kol_y-30:.0f}" x2="{kol_x+130:.0f}"'
            f' y2="{kol_y-110:.0f}" stroke="#3a3a46" stroke-width="44"'
            f' stroke-linecap="round" opacity="{sit:.2f}"/>')
    if vst > .02:
        shk += (f'<g opacity="{vst:.2f}">'
                f'<line x1="{fx-24:.0f}" y1="{byy-fh_*.24:.0f}" x2="{fx-50:.0f}"'
                f' y2="{1010:.0f}" stroke="#3a3a46" stroke-width="44"'
                f' stroke-linecap="round"/>'
                f'<line x1="{fx+24:.0f}" y1="{byy-fh_*.24:.0f}" x2="{fx+50:.0f}"'
                f' y2="{1010:.0f}" stroke="#3a3a46" stroke-width="44"'
                f' stroke-linecap="round"/>'
                f'<ellipse cx="{fx-54:.0f}" cy="{1026:.0f}" rx="54" ry="21"'
                f' fill="#4a2f2a" {o(4)}/>'
                f'<ellipse cx="{fx+54:.0f}" cy="{1026:.0f}" rx="54" ry="21"'
                f' fill="#4a2f2a" {o(4)}/></g>')
    s += SL(Z_SRED, shk)
    s += SL(Z_PERED, _stolb_pered(-6, 92, "#20262a", 0, H))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def babushka_i_moneta_v_ladoshke(t):
    """Двор у скамейки: внук лет пяти стоит на земле и гордо показывает на
    раскрытой ладошке найденную монету. Бабушка сидит на скамейке, правой
    берёт монету двумя пальцами и кладёт обратно на землю под скамейку.
    Рядом песочница, голуби, качели."""
    rnd = random.Random(128)
    s = f'<rect width="{W}" height="{H}" fill="#2d3038"/>'
    s += SL(Z_DAL, panelka(420, 500, 760, t, 5, True, 23)
            + panelka(1660, 480, 560, t, 5, True, 25))
    s += SL(Z_DAL, goloe_derevo(200, 540, 470, t, 27, 9, "#2a2b33", False))
    s += SL(Z_DAL, goloe_derevo(1260, 520, 380, t, 29, 8, "#2a2b33", False))
    s += SL(Z_DAL, tusklaya_lampochka(840, 220, t, 1.8, False))
    s += SL(Z_DAL, teplo(840, 340, 300, 240, .36))
    s += SL(Z_SRED, _asfalt(540, 1080, 43, 30))

    # качели
    kx, ky = 1540, 520
    kach = 9 * A.w(t, 2.6, .2)
    s += SL(Z_SRED, f'<path d="M{kx-200:.0f},1010 L{kx-110:.0f},{ky:.0f}'
                    f' L{kx+110:.0f},{ky:.0f} L{kx+200:.0f},1010" fill="none"'
                    f' stroke="#4a5055" stroke-width="22"/>'
                    f'<rect x="{kx-230:.0f}" y="{ky-16:.0f}" width="460" height="26"'
                    f' rx="10" fill="#5e656a" {o(4)}/>'
                    f'<g transform="rotate({kach:.1f} {kx:.0f} {ky:.0f})">'
                    f'<line x1="{kx-60:.0f}" y1="{ky:.0f}" x2="{kx-60:.0f}" y2="{ky+290:.0f}"'
                    f' stroke="{ZHELEZ}" stroke-width="7"/>'
                    f'<line x1="{kx+60:.0f}" y1="{ky:.0f}" x2="{kx+60:.0f}" y2="{ky+290:.0f}"'
                    f' stroke="{ZHELEZ}" stroke-width="7"/>'
                    f'<rect x="{kx-86:.0f}" y="{ky+290:.0f}" width="172" height="26"'
                    f' rx="9" fill="#8a4a4a" {o(4)}/></g>')

    # песочница
    s += SL(Z_SRED, f'<path d="M60,1010 L560,1010 L600,1076 L20,1076 Z"'
                    f' fill="#b09868" {o(5)}/>')
    for i in range(4):
        s += SL(Z_SRED, f'<rect x="{30+i*140:.0f}" y="984" width="150" height="34"'
                        f' rx="8" fill="#6b5a3c" {o(4)}/>')
    s += SL(Z_SRED, f'<rect x="150" y="930" width="70" height="58" rx="8"'
                    f' fill="#c84a3a" {o(4)}/>'
                    f'<path d="M150,930 Q185,900 220,930" fill="none" stroke="#c84a3a"'
                    f' stroke-width="7"/>'
                    f'<rect x="330" y="952" width="24" height="90" rx="8"'
                    f' fill="#4a5055" {o(3)}/>'
                    f'<path d="M318,952 L376,952 L364,992 L330,992 Z" fill="#d8a14a"'
                    f' {o(3)}/>')

    # скамейка
    s += SL(Z_SRED, f'<rect x="880" y="840" width="1020" height="34" rx="12"'
                    f' fill="url(#dosk)" {o(6)}/>'
                    f'<rect x="880" y="736" width="1020" height="28" rx="11"'
                    f' fill="url(#dosk)" {o(6)}/>'
                    f'<rect x="880" y="788" width="1020" height="28" rx="11"'
                    f' fill="url(#dosk)" {o(6)}/>'
                    f'<rect x="922" y="874" width="28" height="150" rx="9"'
                    f' fill="#4a5055" {o(4)}/>'
                    f'<rect x="1840" y="874" width="28" height="150" rx="9"'
                    f' fill="#4a5055" {o(4)}/>'
                    f'<rect x="896" y="676" width="28" height="172" rx="9"'
                    f' fill="#4a5055" {o(4)}/>'
                    f'<rect x="1856" y="676" width="28" height="172" rx="9"'
                    f' fill="#4a5055" {o(4)}/>')

    # бабушка на скамейке
    bx_, by_, bh_ = 1200, 840, 480
    vz = A.ease(A.seg(t, 1.2, 1.0))
    pol_ = A.ease(A.seg(t, 2.6, 1.0))
    bab = figura(bx_, by_, bh_, t, col="#46404e", kant="#ffd98a", platok=True, ph=.4,
                 naklon=10 * pol_)
    ug = 10 + 44 * vz + 36 * pol_
    r1, (hx1, hy1), (b1x, b1y) = _ruka_ekr(bx_, by_, bh_, 1, bh_ * (.50 + .14 * pol_),
                                           ug, t, "#46404e", "#ffd98a", .2, 5)
    r2, (hx2, hy2), (b2x, b2y) = _ruka_ekr(bx_, by_, bh_, -1, bh_ * .40, 56, t, "#46404e",
                                           "#ffd98a", .6, 4)
    bab += r1 + r2
    # сумка отодвинута НАРУЖУ: при опущенной вдоль тела руке её габарит
    # налезал бабушке на подол
    sum_x = hx2 + _predmet_naruzhu(bx_, bh_, hx2, 124)
    bab += (f'<rect x="{sum_x-62:.0f}" y="{hy2-40:.0f}" width="124" height="92" rx="12"'
            f' fill="#5a3f46" {o(5)}/>'
            f'<path d="M{sum_x-34:.0f},{hy2-40:.0f} Q{sum_x:.0f},{hy2-90:.0f}'
            f' {sum_x+34:.0f},{hy2-40:.0f}" fill="none" stroke="#5a3f46"'
            f' stroke-width="9"/>')
    # ноги на земле
    bab += (f'<line x1="{bx_-26:.0f}" y1="{by_-bh_*.24:.0f}" x2="{bx_-66:.0f}"'
            f' y2="{by_+176:.0f}" stroke="#46404e" stroke-width="40"'
            f' stroke-linecap="round"/>'
            f'<line x1="{bx_+26:.0f}" y1="{by_-bh_*.24:.0f}" x2="{bx_+8:.0f}"'
            f' y2="{by_+176:.0f}" stroke="#46404e" stroke-width="40"'
            f' stroke-linecap="round"/>')
    s += SL(Z_SRED, bab)

    # внук с монетой на ладошке
    vx_, vy_, vh_ = 740, 1030, 360
    vn = figura(vx_, vy_, vh_, t, col="#5a4a3a", kant="#ffd98a", ph=.7,
                naklon=8 * pol_)
    r3, (lx1, ly1), (v1x, v1y) = _ruka_ekr(vx_, vy_, vh_, 1, vh_ * .56, -28, t, "#5a4a3a",
                                           "#ffd98a", .3, 4)
    r4, _, (v2x, v2y) = _ruka_ekr(vx_, vy_, vh_, -1, vh_ * .44, 104, t, "#5a4a3a", "#ffd98a", .7,
                                  4)
    vn += r3 + r4
    s += SL(Z_SRED, vn + ten(vx_, vy_ + 6, 82, 16, .45))

    # МОНЕТУ В ЛАДОШКЕ ВИДНО (осмотр 15.11: было 88 px — пятнышко на рукаве).
    # Диаметр 196 px — почти две головы внука; под ней светлая оторочка
    # рукава вместо кисти (рук в кадре не рисуем) и тёплое пятно-подсветка.
    if pol_ < .02:
        mx_, my_ = lx1, ly1 - 26
        pl = .50
    else:
        mx_ = lx1 + (1240 - lx1) * pol_
        my_ = (ly1 - 26) + (1042 - (ly1 - 26)) * pol_
        pl = .50 + .40 * pol_
    s += SL(Z_SRED, f'<ellipse cx="{lx1:.0f}" cy="{ly1+10:.0f}" rx="104" ry="40"'
                    f' fill="#c9bfae" opacity="{(1-pol_)*.9:.2f}" {o(4)}/>'
                    f'<ellipse cx="{lx1:.0f}" cy="{ly1+2:.0f}" rx="84" ry="28"'
                    f' fill="#8a7a62" opacity="{(1-pol_)*.7:.2f}"/>'
            + teplo(mx_, my_, 210, 150, .34 * (1 - pol_ * .6))
            + _moneta_krupno(mx_, my_, 98, t, .2, True, True, pl))

    # голуби расходятся
    gol = ""
    for i in range(5):
        gp = ((t * .4 + i * .18) % 1.0)
        gx_ = 420 + i * 120 - 160 * gp
        gy_ = 1030 - 60 * max(.0, gp - .6) * 2.5
        gol += (f'<ellipse cx="{gx_:.0f}" cy="{gy_:.0f}" rx="42" ry="26"'
                f' fill="#6a7682" {o(3)}/>'
                f'<circle cx="{gx_-34:.0f}" cy="{gy_-20:.0f}" r="18" fill="#6a7682"'
                f' {o(3)}/>'
                f'<path d="M{gx_-50:.0f},{gy_-22:.0f} L{gx_-74:.0f},{gy_-16:.0f}'
                f' L{gx_-50:.0f},{gy_-10:.0f} Z" fill="#d8a14a" {o(2)}/>'
                f'<circle cx="{gx_-40:.0f}" cy="{gy_-24:.0f}" r="4" fill="#120c08"/>'
                f'<path d="M{gx_+6:.0f},{gy_-10:.0f} Q{gx_+26:.0f},'
                f'{gy_-44-20*max(.0,gp-.6)*2.5:.0f} {gx_+62:.0f},{gy_-16:.0f}'
                f' Q{gx_+34:.0f},{gy_+4:.0f} {gx_+6:.0f},{gy_+6:.0f} Z"'
                f' fill="#8a96a2" {o(2)}/>')
    s += SL(Z_SRED, gol)
    s += SL(Z_SRED, _gorodskoy_hlam(1660, 1076, 300, t, 213, ["stolbik", "kust"]))
    s += SL(Z_SRED, _gorodskoy_hlam(560, 700, 520, t, 365, ["kust", "stolbik", "kust"]))
    # НИЖНЯЯ ТРЕТЬ: лужа с отражением скамейки, сгребённые листья, авоська на
    # земле, следы к скамейке — вместо голого асфальта (осмотр 15.11)
    s += SL(Z_SRED, _luzha(1540, 1024, 230, t, .2, 76, "#8ea6bb")
            + _kucha_listev(380, 1060, 300, 215, 92)
            + _sledy(140, 1072, 640, 946, 6, 217, "#4a4b50", 1.2)
            + _yaschiki(930, 1056, t, 219, 1, .8))
    s += SL(Z_SRED, _zabor_dosok(420, 560, 1080, 180, 367, 58, "#3f5a46"))
    s += SL(Z_LETIT, mokryy_sneg(t, 16, 31, .4, .7))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def ostanovka_s_monetoy(t):
    """Стеклянный павильон остановки на пол-кадра, скамья, урна, расписание
    без текста. За стеклом — настоящая вечерняя улица в огнях. На плитке
    переднего плана крупно блестит монета. Мужчина в шляпе читает газету; женщина с
    зонтом-тростью проходит мимо, не наклоняясь."""
    rnd = random.Random(129)
    s = f'<rect width="{W}" height="{H}" fill="#20242e"/>'
    s += SL(Z_DAL, panelka(220, 480, 440, t, 6, True, 27)
            + panelka(1760, 460, 420, t, 6, True, 29))
    s += SL(Z_SRED, _asfalt(560, 1080, 45, 28))

    # нарисованный вид, метка, переплёт поверх
    px_, py_, pw_, ph_ = 300, 200, 790, 420
    put = kontur_proema(px_, py_, pw_, ph_, "pryam")
    s += SL(Z_SRED, _vid_za_proemom(put, t, "ulica", 17)
            + mesto_stoka(px_, py_, pw_, ph_, "pryam"))
    # переплёт павильона поверх кадра
    ram = (f'<path d="{put}" fill="none" stroke="#3f4650" stroke-width="26"/>'
           f'<rect x="{px_+pw_*.5-9:.0f}" y="{py_:.0f}" width="18" height="{ph_:.0f}"'
           f' fill="#3f4650" {o(3)}/>'
           f'<rect x="{px_:.0f}" y="{py_+ph_*.5-8:.0f}" width="{pw_:.0f}" height="16"'
           f' fill="#3f4650" {o(3)}/>'
           f'<path d="M{px_+40:.0f},{py_+ph_-40:.0f} L{px_+260:.0f},{py_+40:.0f}"'
           f' stroke="#cfe4f5" stroke-width="22" opacity=".16"/>'
           f'<path d="M{px_+150:.0f},{py_+ph_-40:.0f} L{px_+370:.0f},{py_+40:.0f}"'
           f' stroke="#cfe4f5" stroke-width="12" opacity=".12"/>')
    s += SL(Z_SRED, ram)
    # стойки и крыша павильона
    s += SL(Z_SRED, f'<rect x="{px_-150:.0f}" y="{py_-70:.0f}" width="{pw_+300:.0f}"'
                    f' height="48" rx="12" fill="#4a5560" {o(6)}/>'
                    f'<path d="M{px_-170:.0f},{py_-70:.0f} L{px_+pw_+170:.0f},{py_-70:.0f}'
                    f' L{px_+pw_+130:.0f},{py_-116:.0f} L{px_-130:.0f},{py_-116:.0f} Z"'
                    f' fill="#5e6a74" {o(5)}/>'
                    f'<rect x="{px_-70:.0f}" y="{py_-26:.0f}" width="40"'
                    f' height="{ph_+330:.0f}" rx="10" fill="#3f4650" {o(5)}/>'
                    f'<rect x="{px_+pw_+30:.0f}" y="{py_-26:.0f}" width="40"'
                    f' height="{ph_+330:.0f}" rx="10" fill="#3f4650" {o(5)}/>')
    # расписание без текста
    s += SL(Z_SRED, f'<rect x="1180" y="300" width="230" height="330" rx="10"'
                    f' fill="#2e3640" {o(5)}/>'
                    f'<rect x="1196" y="318" width="198" height="294" rx="6"'
                    f' fill="#e8e2d2" {o(3)}/>')
    for i in range(8):
        s += SL(Z_SRED, f'<path d="M1214,{350+i*34:.0f} Q1280,{338+i*34:.0f}'
                        f' 1376,{352+i*34:.0f}" fill="none" stroke="#8a929a"'
                        f' stroke-width="6"/>')
    s += SL(Z_SRED, tusklaya_lampochka(960, 120, t, 1.6, True))
    s += SL(Z_SRED, teplo(960, 320, 420, 300, .32))

    # скамья и урна
    s += SL(Z_SRED, f'<rect x="1060" y="800" width="840" height="34" rx="12"'
                    f' fill="url(#dosk)" {o(6)}/>'
                    f'<rect x="1060" y="698" width="840" height="28" rx="11"'
                    f' fill="url(#dosk)" {o(6)}/>'
                    f'<rect x="1060" y="748" width="840" height="28" rx="11"'
                    f' fill="url(#dosk)" {o(6)}/>'
                    f'<rect x="1104" y="834" width="28" height="170" rx="9"'
                    f' fill="#4a5055" {o(4)}/>'
                    f'<rect x="1832" y="834" width="28" height="170" rx="9"'
                    f' fill="#4a5055" {o(4)}/>')
    s += SL(Z_SRED, f'<path d="M250,860 L400,860 L376,1010 L274,1010 Z"'
                    f' fill="#4a5055" {o(6)}/>'
                    f'<rect x="236" y="842" width="178" height="26" rx="10"'
                    f' fill="#5e656a" {o(4)}/>')
    for i in range(4):
        s += SL(Z_SRED, f'<line x1="{272+i*36:.0f}" y1="872" x2="{280+i*34:.0f}"'
                        f' y2="1002" stroke="#333a3e" stroke-width="5" opacity=".7"/>')

    # МОНЕТА ЕСТЬ И ЕЁ ВИДНО (осмотр 15.11: «монеты в кадре НЕТ ВООБЩЕ» —
    # 144 px под скамьёй, да ещё за ногами мужчины и за проходящей женщиной).
    # Теперь 352 px на свободной плитке переднего плана, с бликом и
    # подсветкой, и ничем не перекрыта.
    s += SL(Z_SRED, f'<ellipse cx="700" cy="1024" rx="250" ry="56" fill="#1b1f26"'
                    f' opacity=".5"/>'
            + teplo(700, 992, 330, 180, .30)
            + _moneta_krupno(700, 992, 176, t, .2, True, True, .74)
            + f'<path d="M520,1056 Q700,1030 886,1058" fill="none"'
              f' stroke="#cfe4f5" stroke-width="7" opacity=".3"/>')

    # мужчина в шляпе с газетой
    mx_, my_, mh_ = 1480, 800, 500
    gz = 6 * A.w(t, 1.1, .2)
    muz = figura(mx_, my_, mh_, t, col="#3a3a46", kant="#ffd98a", ph=.3)
    r1, (g1x, g1y), (m1x, m1y) = _ruka_ekr(mx_, my_, mh_, 1, mh_ * .40, 46, t, "#3a3a46",
                                           "#ffd98a", .2, 4)
    r2, (g2x, g2y), (m2x, m2y) = _ruka_ekr(mx_, my_, mh_, -1, mh_ * .40, 134, t, "#3a3a46",
                                           "#ffd98a", .6, 4)
    muz += r1 + r2
    gcx = (g1x + g2x) / 2
    gcy = (g1y + g2y) / 2
    gcy += 46
    muz += (f'<g transform="rotate({gz:.1f} {gcx:.0f} {gcy:.0f})">'
            f'<path d="M{gcx-92:.0f},{gcy-70:.0f} L{gcx:.0f},{gcy-60:.0f}'
            f' L{gcx+92:.0f},{gcy-70:.0f} L{gcx+92:.0f},{gcy+62:.0f}'
            f' L{gcx:.0f},{gcy+72:.0f} L{gcx-92:.0f},{gcy+62:.0f} Z"'
            f' fill="#ddd8c8" {o(5)}/>'
            f'<line x1="{gcx:.0f}" y1="{gcy-60:.0f}" x2="{gcx:.0f}" y2="{gcy+72:.0f}"'
            f' stroke="#a8a294" stroke-width="5"/>')
    for i in range(5):
        muz += (f'<path d="M{gcx-78:.0f},{gcy-42+i*24:.0f}'
                f' Q{gcx-42:.0f},{gcy-50+i*24:.0f} {gcx-12:.0f},{gcy-40+i*24:.0f}'
                f' M{gcx+12:.0f},{gcy-40+i*24:.0f} Q{gcx+46:.0f},{gcy-50+i*24:.0f}'
                f' {gcx+78:.0f},{gcy-42+i*24:.0f}" fill="none" stroke="#9aa0a4"'
                f' stroke-width="4"/>')
    muz += "</g>"
    muz += (f'<path d="M{mx_-66:.0f},{my_-mh_*.88:.0f} Q{mx_:.0f},{my_-mh_*1.04:.0f}'
            f' {mx_+66:.0f},{my_-mh_*.88:.0f} Z" fill="#2a2a34" {o(5)}/>'
            f'<rect x="{mx_-96:.0f}" y="{my_-mh_*.90:.0f}" width="192" height="20"'
            f' rx="9" fill="#2a2a34" {o(4)}/>')
    muz += (f'<line x1="{mx_-26:.0f}" y1="{my_-mh_*.24:.0f}" x2="{mx_-70:.0f}"'
            f' y2="{my_+200:.0f}" stroke="#3a3a46" stroke-width="40"'
            f' stroke-linecap="round"/>'
            f'<line x1="{mx_+26:.0f}" y1="{my_-mh_*.24:.0f}" x2="{mx_+30:.0f}"'
            f' y2="{my_+200:.0f}" stroke="#3a3a46" stroke-width="40"'
            f' stroke-linecap="round"/>')
    s += SL(Z_SRED, muz)

    # женщина с зонтом-тростью проходит мимо
    hod = (t * .30) % 1.0
    fx, fy, fh = 1560 - 560 * hod, 1056, 580
    zh = figura(fx, fy, fh, t, col="#4a3f52", kant="#cfe4f5", platok=False, ph=.5)
    r3, (zx2, zy2), (z1x, z1y) = _ruka_ekr(fx, fy, fh, 1, fh * .42, 84, t, "#4a3f52", "#cfe4f5",
                                           .1, 6)
    r4, (sx3, sy3), (z2x, z2y) = _ruka_ekr(fx, fy, fh, -1, fh * .36, -46, t, "#4a3f52",
                                           "#cfe4f5", .5, 4)
    zh += r3 + r4
    stuk = 8 * abs(math.sin(hod * 6.283 * 2))
    zh += (f'<line x1="{zx2:.0f}" y1="{zy2:.0f}" x2="{zx2+14:.0f}"'
           f' y2="{fy+6-stuk:.0f}" stroke="#2e2a36" stroke-width="15"'
           f' stroke-linecap="round"/>'
           f'<path d="M{zx2-10:.0f},{zy2-6:.0f} Q{zx2-44:.0f},{zy2-30:.0f}'
           f' {zx2-40:.0f},{zy2+6:.0f}" fill="none" stroke="#2e2a36"'
           f' stroke-width="13"/>')
    # шарф
    zh += (f'<path d="M{fx-54:.0f},{fy-fh*.72:.0f} Q{fx:.0f},{fy-fh*.64:.0f}'
           f' {fx+54:.0f},{fy-fh*.72:.0f} L{fx+46:.0f},{fy-fh*.56:.0f}'
           f' Q{fx:.0f},{fy-fh*.48:.0f} {fx-46:.0f},{fy-fh*.56:.0f} Z"'
           f' fill="#8a4a4a" {o(4)}/>'
           f'<path d="M{fx+30:.0f},{fy-fh*.58:.0f} L{fx+54:.0f},{fy-fh*.30:.0f}'
           f' L{fx+16:.0f},{fy-fh*.32:.0f} Z" fill="#8a4a4a" {o(3)}/>')
    zh += para_izo_rta(fx + 44, fy - fh * .80, t, .2, 1.0, .5)
    s += SL(Z_SRED, zh + ten(fx, fy + 8, 110, 20, .45))
    s += SL(Z_SRED, _gorodskoy_hlam(60, 1076, 380, t, 215, ["stolbik", "yaschik"]))
    s += SL(Z_SRED, _gorodskoy_hlam(1560, 1076, 360, t, 217, ["kust", "stolbik"]))
    s += SL(Z_LETIT, mokryy_sneg(t, 18, 33, .45, .8))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def chuzhoy_venik_u_vhoda(t):
    """Порог избы снаружи: поперёк него лежит чужой веник НА ПОЛ-КАДРА —
    растрёпанный, с красной тряпицей на ручке. Рядом скребок для обуви,
    половик, кадка. Хозяйка стоит в дверях, держится за косяк, отдёргивает
    протянутую руку и отступает на шаг внутрь."""
    rnd = random.Random(130)
    s = nebo("sumer", t, True, 61)
    s += oblaka(t, 120, 4, 51, .36)
    s += SL(Z_DAL, _derevnya_ryad(470, t, 219, ((130, 300), (1830, 280))))
    s += SL(Z_DAL, brevna(230, 0, 1480, 760, 94)
            + f'<rect x="230" y="0" width="1480" height="760" fill="none" {o(10)}/>')
    s += SL(Z_DAL, okno_izby(1420, 120, 320, 270, t, svet=True)
            + teplo(1580, 256, 280, 230, .44))
    s += SL(Z_DAL, _polka_s_utvaryu(240, 180, 440, t, 221, 3))
    s += SL(Z_DAL, _stennoe_hozyaystvo(240, 330, t, 223))
    s += SL(Z_DAL, dym(1620, 140, t, 5, .26, 280, .34, "#d3dae2", .9))

    # дверной проём с косяком, внутри тепло
    dx_, dy_, dw, dh = 760, 200, 420, 560
    s += SL(Z_SRED, f'<rect x="{dx_-40:.0f}" y="{dy_-40:.0f}" width="{dw+80:.0f}"'
                    f' height="{dh+60:.0f}" rx="10" fill="#3b2a1a" {o(7)}/>'
                    f'<rect x="{dx_:.0f}" y="{dy_:.0f}" width="{dw:.0f}"'
                    f' height="{dh:.0f}" fill="#1c1510" {o(5)}/>'
                    f'<ellipse cx="{dx_+dw*.5:.0f}" cy="{dy_+dh*.62:.0f}" rx="200"'
                    f' ry="200" fill="#ffd98a" opacity=".16"/>')
    # ДВЕРЬ НА ПЕТЛЯХ, А КРЮК И ЦЕПОЧКА — НА ОПОРЕ. Осмотр 15.11: «синяя
    # дуга висит без опоры» — крюк и цепочка из `dver()` рисовались правее
    # полотна, по голым брёвнам, и читались дугой, подвешенной в воздухе.
    s += SL(Z_SRED, dver(dx_ + dw - 60, dy_, 380, dh, .0, "url(#derev)", False, False))
    petli = ""
    for py2 in (dy_ + 70, dy_ + dh * .5, dy_ + dh - 90):
        petli += (f'<rect x="{dx_+dw-96:.0f}" y="{py2:.0f}" width="104" height="30"'
                  f' rx="10" fill="{ZHELEZ}" {o(4)}/>'
                  f'<circle cx="{dx_+dw-88:.0f}" cy="{py2+15:.0f}" r="13"'
                  f' fill="#3a4045" {o(3)}/>'
                  f'<circle cx="{dx_+dw-14:.0f}" cy="{py2+15:.0f}" r="8"'
                  f' fill="#3a4045" {o(2)}/>')
    kolx, koly = dx_ + dw + 374, dy_ + dh * .40
    petli += (f'<rect x="{kolx-24:.0f}" y="{koly-30:.0f}" width="48" height="60"'
              f' rx="9" fill="#4a3522" {o(4)}/>'
              f'<circle cx="{kolx:.0f}" cy="{koly:.0f}" r="13" fill="{ZHELEZ}"'
              f' {o(3)}/>'
              f'<path d="M{dx_+dw+316:.0f},{koly-18:.0f} q30,30 {kolx-dx_-dw-316:.0f},18"'
              f' fill="none" stroke="{ZHELEZ}" stroke-width="9"'
              f' stroke-dasharray="5 9" stroke-linecap="round"/>'
              f'<rect x="{dx_+dw+300:.0f}" y="{koly-34:.0f}" width="30" height="34"'
              f' rx="8" fill="{ZHELEZ}" {o(3)}/>')
    s += SL(Z_SRED, petli)
    # подкова прибита к НАЩЕЛЬНИКУ над дверью, а не парит над проёмом
    s += SL(Z_SRED, f'<rect x="{dx_+dw*.5-120:.0f}" y="{dy_-104:.0f}" width="240"'
                    f' height="38" rx="9" fill="#5b4428" {o(5)}/>'
            + podkova(dx_ + dw * .5, dy_ - 74, 1.6, t))

    zem = f'<rect x="0" y="760" width="{W}" height="320" fill="#473626"/>'
    zem += _zemlya_faktura(820, 1060, 225, 14)
    zem += _listya(227, 26, 800, 1060)
    zem += _inej(229, 30, 800, 1060)
    s += SL(Z_SRED, zem)
    # порог и крыльцо
    s += SL(Z_SRED, f'<rect x="{dx_-80:.0f}" y="760" width="{dw+160:.0f}" height="46"'
                    f' rx="10" fill="#5b4428" {o(6)}/>'
                    f'<rect x="{dx_-120:.0f}" y="806" width="{dw+240:.0f}" height="36"'
                    f' rx="9" fill="url(#derev)" {o(5)}/>'
                    f'<rect x="{dx_-160:.0f}" y="842" width="{dw+320:.0f}" height="36"'
                    f' rx="9" fill="url(#derev)" {o(5)}/>')

    # ЧУЖОЙ ВЕНИК ЛЕЖИТ ПОПЕРЁК ПОРОГА — ПРУТЬЯМИ ВЕЕРОМ И С ПЕРЕВЯЗЬЮ.
    # Осмотр 15.11: «бесформенный жёлтый пучок» — разброс прутьев стоял на
    # 1.0 и веер рассыпался в пятно, а тон #8a7246 сливался с землёй.
    # Теперь разброс 0.24, прутья светлые по тёмному комлю, две перевязи.
    ven = (f'<g transform="rotate(-84 700 940)">'
           + _venik(700, 1104, 620, t, "#c2a45e", "#b8352c", False, .24, .0, 1.5, 231))
    for i, (ky2, kw2, kc) in enumerate(((.50, 104, "#b8352c"), (.40, 92, "#6a4a26"),
                                        (.30, 84, "#8a6a3c"))):
        ven += (f'<rect x="{700-kw2*.5:.0f}" y="{1104-620*ky2:.0f}" width="{kw2:.0f}"'
                f' height="26" rx="10" fill="{kc}" {o(4)}/>')
    ven += (f'<path d="M{700-150:.0f},{1104-620+28:.0f} Q700,{1104-620-34:.0f}'
            f' {700+150:.0f},{1104-620+28:.0f}" fill="none" stroke="#8a6a3c"'
            f' stroke-width="8" opacity=".55"/></g>')
    s += SL(Z_SRED, ven)
    # скребок, половик, кадка
    s += SL(Z_SRED, f'<path d="M520,900 L700,900 L700,870 L520,870 Z" fill="{ZHELEZ}"'
                    f' {o(5)}/>'
                    f'<rect x="508" y="896" width="30" height="80" rx="8"'
                    f' fill="#3a4045" {o(4)}/>'
                    f'<rect x="682" y="896" width="30" height="80" rx="8"'
                    f' fill="#3a4045" {o(4)}/>')
    s += SL(Z_SRED, f'<path d="M1240,906 L1660,906 L1720,992 L1180,992 Z" fill="{RUSH}"'
                    f' {o(5)}/>'
                    f'<path d="M1222,936 L1686,936 M1204,966 L1704,966" stroke="{KRAS}"'
                    f' stroke-width="9" opacity=".65"/>')
    s += SL(Z_SRED, _dvorovaya_utvar(220, 1056, 420, t, 233, ["kadka", "vedro"]))
    s += SL(Z_SRED, _kadushki_i_grabli(1480, 1070, t, 235))

    # хозяйка в дверях: левой за косяк, правую прижимает к груди, отступает
    otst = A.ease(A.seg(t, 1.4, 1.0))
    fx, fy, fh = 1040 + 70 * otst, 790, 560
    hoz = figura(fx, fy, fh, t, col="#4a3b2a", kant="#ffd98a", platok=True, ph=.2,
                 naklon=5 * otst)
    r1, _, (h1x, h1y) = _ruka_ekr(fx, fy, fh, 1, fh * (.46 - .22 * otst), 118 - 76 * otst, t,
                                  "#4a3b2a", "#ffd98a", .1, 6)
    r2, _, (h2x, h2y) = _ruka_ekr(fx, fy, fh, -1, fh * .40, -158, t, "#4a3b2a", "#ffd98a", .5, 4)
    hoz += r1 + r2
    hoz += (f'<path d="M{fx-56:.0f},{fy-fh*.62:.0f} L{fx+56:.0f},{fy-fh*.62:.0f}'
            f' L{fx+74:.0f},{fy-fh*.16:.0f} L{fx-74:.0f},{fy-fh*.16:.0f} Z"'
            f' fill="#9a8c70" opacity=".92" {o(4)}/>')
    hoz += para_izo_rta(fx + 46, fy - fh * .80, t, .3, 1.0, .5)
    s += SL(Z_SRED, hoz + ten(fx, fy + 8, 110, 20, .45))
    s += SL(Z_PERED, _stolb_pered(-6, 96, "#1d1611", 0, H))
    s += SL(Z_LETIT, mokryy_sneg(t, 16, 35, .4, .7))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def svoy_venik_i_svoi_ugly(t):
    """Горница сверху, как план: четыре угла, печь, стол, лавки, прялка.
    Хозяйка держит свой тёмный веник обеими руками и метёт от угла к порогу,
    из каждого угла тянется дорожка сора. В дверь просовывается чужой веник,
    и с него сыплется чужой сор."""
    rnd = random.Random(131)
    s = f'<rect width="{W}" height="{H}" fill="#2a2018"/>'
    # план горницы: пол досками в перспективе «сверху»
    s += SL(Z_DAL, f'<path d="M260,120 L1660,120 L1880,1020 L40,1020 Z"'
                   f' fill="url(#pol)" {o(8)}/>')
    for i in range(13):
        p = i / 12.0
        s += SL(Z_DAL, f'<line x1="{260+1400*p:.0f}" y1="120"'
                       f' x2="{40+1840*p:.0f}" y2="1020" stroke="#4a3522"'
                       f' stroke-width="6" opacity=".55"/>')
    # стены по периметру
    s += SL(Z_DAL, f'<path d="M260,120 L1660,120 L1700,40 L220,40 Z" fill="url(#brev)"'
                   f' {o(6)}/>'
                   f'<path d="M260,120 L40,1020 L-40,1020 L160,60 Z" fill="url(#brev)"'
                   f' {o(6)}/>'
                   f'<path d="M1660,120 L1880,1020 L1960,1020 L1760,60 Z"'
                   f' fill="url(#brev)" {o(6)}/>')
    # печь в дальнем левом углу
    s += SL(Z_SRED, pech(250, 120, 330, 400, t, True, True, False))
    s += SL(Z_SRED, teplo(400, 380, 360, 300, .42))
    s += SL(Z_SRED, dym(400, 130, t, 4, .26, 230, .3, "#d3dae2", .8))
    # стол, лавки, прялка по углам
    s += SL(Z_SRED, stol(1180, 540, 460, 30))
    s += SL(Z_SRED, _lavka_krupno(760, 620, 420, t, 130))
    s += SL(Z_SRED, _lavka_krupno(1420, 760, 420, t, 140))
    s += SL(Z_SRED, krynka(1180, 520, 1.2) + karavay(1300, 522, 1.0, True))
    prx, pry = 1660, 420
    s += SL(Z_SRED, f'<rect x="{prx-90:.0f}" y="{pry-26:.0f}" width="190" height="30"'
                    f' rx="10" fill="url(#dosk)" {o(5)}/>'
                    f'<rect x="{prx-14:.0f}" y="{pry-320:.0f}" width="30" height="300"'
                    f' rx="11" fill="url(#derev)" {o(5)}/>'
                    f'<ellipse cx="{prx+10:.0f}" cy="{pry-360:.0f}" rx="66" ry="50"'
                    f' fill="url(#solom)" opacity=".92" {o(5)}/>')
    s += SL(Z_SRED, mebel_hlam(180, 980, 380, t, 31))
    s += SL(Z_SRED, _kot_zhivoy(1740, 960, t, 1.35, "#4a423c", .6, True, True))
    s += SL(Z_SRED, _polenica(300, 540, 260, 220, 295, 24))
    s += SL(Z_SRED, _dvorovaya_utvar(560, 900, 420, t, 297,
                                     ["kadka", "korzina", "vedro"]))
    s += SL(Z_SRED, _polka_s_utvaryu(760, 300, 420, t, 299, 4))
    s += SL(Z_SRED, _polka_s_utvaryu(1060, 380, 420, t, 369, 4))
    s += SL(Z_SRED, _lavka_krupno(560, 470, 420, t, 130))
    s += SL(Z_SRED, _dvorovaya_utvar(620, 960, 560, t, 371,
                                     ["korzina", "vedro", "korob"]))
    s += SL(Z_SRED, _listya(373, 24, 880, 1000))
    s += SL(Z_SRED, utvar_izby(1240, 260, 400, t, 33))
    s += SL(Z_SRED, f'<path d="M620,700 L1320,700 L1420,900 L520,900 Z" fill="{RUSH}"'
                    f' {o(5)}/>'
                    f'<path d="M600,760 L1350,760 M576,820 L1382,820" stroke="{KRAS}"'
                    f' stroke-width="9" opacity=".6"/>')
    s += SL(Z_SRED, f'<rect x="1440" y="200" width="300" height="140" rx="10"'
                    f' fill="url(#derev)" {o(6)}/>'
                    f'<path d="M1440,200 Q1590,146 1740,200 Z" fill="#5b4428" {o(5)}/>'
                    f'<rect x="1430" y="236" width="320" height="18" rx="7"'
                    f' fill="{ZHELEZ}" {o(3)}/>')

    # дорожки сора из каждого угла к порогу
    sor = ""
    uglov = ((300, 200), (1620, 200), (120, 960), (1820, 960))
    for i, (ux, uy) in enumerate(uglov):
        for k in range(11):
            p = k / 10.0
            sx_ = ux + (960 - ux) * p + 30 * math.sin(p * 6 + i)
            sy_ = uy + (1000 - uy) * p
            r = 7 + (1 - p) * 9
            sor += (f'<ellipse cx="{sx_:.0f}" cy="{sy_:.0f}" rx="{r:.0f}"'
                    f' ry="{r*.6:.0f}" fill="{["#8a7a58","#6b5a3c","#9a8c70"][k%3]}"'
                    f' opacity=".9"/>')
            if k % 3 == 0:
                sor += (f'<line x1="{sx_-16:.0f}" y1="{sy_-6:.0f}" x2="{sx_+14:.0f}"'
                        f' y2="{sy_+8:.0f}" stroke="#7a6a48" stroke-width="4"/>')
    s += SL(Z_SRED, sor)

    # хозяйка метёт от угла к порогу
    mah = A.ease(abs(A.w(t, 1.6, .0)))
    fx, fy, fh = 700, 900, 460
    hoz = figura(fx, fy, fh, t, col="#4a3b2a", kant="#ffd98a", platok=True, ph=.2,
                 naklon=14 * mah)
    r1, (v1x, v1y), (h1x, h1y) = _ruka_ekr(fx, fy, fh, 1, fh * .50, 36 + 30 * mah, t, "#4a3b2a",
                                           "#ffd98a", .1, 5)
    r2, _, (h2x, h2y) = _ruka_ekr(fx, fy, fh, -1, fh * .46, 56 + 26 * mah, t, "#4a3b2a",
                                  "#ffd98a", .5, 5)
    hoz += r1 + r2
    hoz += _venik_v_ruke(v1x, v1y, 280, t, "#4b3f28", "#5a4a2e",
                         104 - 30 * mah, .9, 237, .25, .7)
    # подол и платок отклоняются по ходу взмаха
    hoz += (f'<path d="M{fx-80:.0f},{fy-fh*.30:.0f} Q{fx+30*mah:.0f},{fy-fh*.10:.0f}'
            f' {fx+90:.0f},{fy-fh*.28:.0f} L{fx+74:.0f},{fy-4:.0f}'
            f' L{fx-74:.0f},{fy-4:.0f} Z" fill="#4a3b2a" {o(5)}/>')
    s += SL(Z_SRED, hoz)

    # чужой веник просовывается в дверь, сыплется чужой сор
    dv = A.ease(A.seg(t, 3.0, 1.2))
    s += SL(Z_SRED, f'<rect x="820" y="1004" width="300" height="76" rx="10"'
                    f' fill="#2a1d12" {o(6)}/>'
                    f'<rect x="800" y="986" width="340" height="26" rx="9"'
                    f' fill="#5b4428" {o(5)}/>')
    s += SL(Z_SRED, f'<g transform="rotate(176 970 1040)">'
                    + _venik(970, 1040 + 300 * (1 - dv), 360, t, "#8a7246", "#b8352c",
                             False, 1.0, .3, 1.0, 239) + "</g>")
    chuz = ""
    for i in range(10):
        p = ((t * .7 + i * .1) % 1.0)
        cx_ = 880 + i * 22
        cy_ = 960 + 110 * p
        if i % 4 == 0:                           # рассерженная рожица
            chuz += (f'<circle cx="{cx_:.0f}" cy="{cy_:.0f}" r="22" fill="#c86a4a"'
                     f' opacity="{(1-p)*dv:.2f}" {o(3)}/>'
                     f'<path d="M{cx_-10:.0f},{cy_+8:.0f} Q{cx_:.0f},{cy_-2:.0f}'
                     f' {cx_+10:.0f},{cy_+8:.0f}" fill="none" stroke="#3a1c14"'
                     f' stroke-width="4" opacity="{(1-p)*dv:.2f}"/>'
                     f'<path d="M{cx_-12:.0f},{cy_-10:.0f} L{cx_-2:.0f},{cy_-4:.0f}'
                     f' M{cx_+12:.0f},{cy_-10:.0f} L{cx_+2:.0f},{cy_-4:.0f}"'
                     f' stroke="#3a1c14" stroke-width="4"'
                     f' opacity="{(1-p)*dv:.2f}"/>')
        elif i % 4 == 1:                         # чужая пуговица
            chuz += (f'<circle cx="{cx_:.0f}" cy="{cy_:.0f}" r="14" fill="#e8e2d2"'
                     f' opacity="{(1-p)*dv:.2f}" {o(2)}/>')
        else:                                    # чужое письмо
            chuz += (f'<rect x="{cx_-16:.0f}" y="{cy_-12:.0f}" width="32" height="24"'
                     f' rx="4" fill="#f0e8d4" opacity="{(1-p)*dv:.2f}" {o(2)}/>')
    s += SL(Z_SRED, chuz)
    s += SL(Z_PERED, ramka_pp("oba"))
    s += vinetka(.46)
    return s


def prischurennaya_sosedka(t):
    """Двор и забор: у калитки на земле лежит чужой веник. Хозяйка метёт
    крыльцо своим старым веником, замечает чужой и замирает. Из-за забора
    выглядывает соседка, обе руки на жерди, от прищуренных глаз к венику
    тянется пунктир. Во дворе куры, корыто, поленница."""
    rnd = random.Random(132)
    s = nebo("sumer", t, True, 63)
    s += oblaka(t, 120, 4, 53, .36)
    s += SL(Z_DAL, _derevnya_ryad(430, t, 241, ((140, 330), (1820, 300))))
    s += SL(Z_DAL, brevna(-20, 40, 1040, 700, 92)
            + f'<rect x="-20" y="40" width="1040" height="700" fill="none" {o(9)}/>')
    s += SL(Z_DAL, okno_izby(120, 170, 300, 250, t, svet=True)
            + teplo(270, 296, 260, 210, .44))
    s += SL(Z_DAL, dver(520, 150, 280, 500, .0, "url(#derev)", True, False))
    s += SL(Z_DAL, dym(360, 100, t, 5, .26, 280, .34, "#d3dae2", .9))
    # СТЕННОЕ ХОЗЯЙСТВО ПОДНЯТО НА СТЕНУ. Осмотр 15.11: «белый вытянутый
    # предмет внизу не опознаётся» — это ПИЛА: `_stennoe_hozyaystvo` вешает её
    # на y+320, и при якоре 540 полотно (940-1220 × 860-948, сталь #7e848c)
    # оказывалось на 200 px НИЖЕ бревенчатой стены, прямо на земле, и читалось
    # светлым пятном ни на чём. Якорь 290 — вся снасть внутри стены (40-740).
    s += SL(Z_DAL, _stennoe_hozyaystvo(60, 290, t, 243))

    zem = f'<rect x="0" y="760" width="{W}" height="320" fill="#473626"/>'
    zem += _zemlya_faktura(820, 1060, 245, 14)
    zem += _listya(247, 26, 800, 1060)
    zem += _inej(249, 28, 800, 1060)
    s += SL(Z_SRED, zem)
    s += SL(Z_SRED, _kryl_co(60, 700, 620, 180, t, 3, True, False))

    # забор с соседкой
    s += SL(Z_SRED, _zabor_dosok(880, 470, 1080, 350, 251, 58))
    sx_, sy_ = 1480, 480
    pr = 4 * A.w(t, 2.2, .2)
    sos = (f'<path d="M{sx_-130:.0f},{sy_+40:.0f} Q{sx_-116:.0f},{sy_-70:.0f}'
           f' {sx_-48:.0f},{sy_-110:.0f} L{sx_+48:.0f},{sy_-110:.0f}'
           f' Q{sx_+116:.0f},{sy_-70:.0f} {sx_+130:.0f},{sy_+40:.0f} Z"'
           f' fill="#3d4a3a" {o(5)}/>'
           f'<ellipse cx="{sx_:.0f}" cy="{sy_-80+pr:.0f}" rx="86" ry="96"'
           f' fill="#e8c9a8" {o(5)}/>'
           f'<path d="M{sx_-92:.0f},{sy_-110+pr:.0f} Q{sx_:.0f},{sy_-230+pr:.0f}'
           f' {sx_+92:.0f},{sy_-110+pr:.0f} Q{sx_+70:.0f},{sy_-50+pr:.0f}'
           f' {sx_+86:.0f},{sy_+10+pr:.0f} L{sx_-86:.0f},{sy_+10+pr:.0f}'
           f' Q{sx_-70:.0f},{sy_-50+pr:.0f} {sx_-92:.0f},{sy_-110+pr:.0f} Z"'
           f' fill="#5a2f33" {o(5)}/>'
           f'<ellipse cx="{sx_:.0f}" cy="{sy_-80+pr:.0f}" rx="86" ry="96"'
           f' fill="#e8c9a8" {o(0)}/>'
           f'<path d="M{sx_-96:.0f},{sy_-96+pr:.0f} Q{sx_:.0f},{sy_-236+pr:.0f}'
           f' {sx_+96:.0f},{sy_-96+pr:.0f} Q{sx_+70:.0f},{sy_-132+pr:.0f}'
           f' {sx_:.0f},{sy_-142+pr:.0f} Q{sx_-70:.0f},{sy_-132+pr:.0f}'
           f' {sx_-96:.0f},{sy_-96+pr:.0f} Z" fill="#8a4a6a" {o(5)}/>'
           f'<path d="M{sx_-96:.0f},{sy_-96+pr:.0f} Q{sx_-120:.0f},{sy_-30+pr:.0f}'
           f' {sx_-60:.0f},{sy_+10+pr:.0f} L{sx_-74:.0f},{sy_-52+pr:.0f} Z"'
           f' fill="#8a4a6a" {o(4)}/>'
           f'<path d="M{sx_+96:.0f},{sy_-96+pr:.0f} Q{sx_+120:.0f},{sy_-30+pr:.0f}'
           f' {sx_+60:.0f},{sy_+10+pr:.0f} L{sx_+74:.0f},{sy_-52+pr:.0f} Z"'
           f' fill="#8a4a6a" {o(4)}/>'
           f'<path d="M{sx_-48:.0f},{sy_-96+pr:.0f} Q{sx_-28:.0f},{sy_-108+pr:.0f}'
           f' {sx_-8:.0f},{sy_-96+pr:.0f}" fill="none" stroke="#3a2a22"'
           f' stroke-width="9" stroke-linecap="round"/>'
           f'<path d="M{sx_+8:.0f},{sy_-96+pr:.0f} Q{sx_+28:.0f},{sy_-108+pr:.0f}'
           f' {sx_+48:.0f},{sy_-96+pr:.0f}" fill="none" stroke="#3a2a22"'
           f' stroke-width="9" stroke-linecap="round"/>'
           f'<path d="M{sx_-54:.0f},{sy_-124+pr:.0f} Q{sx_-28:.0f},{sy_-142+pr:.0f}'
           f' {sx_-4:.0f},{sy_-128+pr:.0f} M{sx_+4:.0f},{sy_-128+pr:.0f}'
           f' Q{sx_+28:.0f},{sy_-142+pr:.0f} {sx_+54:.0f},{sy_-124+pr:.0f}"'
           f' fill="none" stroke="#5a4030" stroke-width="7"/>'
           f'<path d="M{sx_-26:.0f},{sy_-44+pr:.0f} Q{sx_:.0f},{sy_-34+pr:.0f}'
           f' {sx_+26:.0f},{sy_-44+pr:.0f}" fill="none" stroke="#9c4a3c"'
           f' stroke-width="7" stroke-linecap="round"/>')
    # обе руки на верхней жерди
    sos += (f'<rect x="{sx_-140:.0f}" y="{sy_+6:.0f}" width="110" height="38" rx="16"'
            f' fill="#5a2f33" {o(4)}/>'
            f'<rect x="{sx_+30:.0f}" y="{sy_+6:.0f}" width="110" height="38" rx="16"'
            f' fill="#5a2f33" {o(4)}/>')
    s += SL(Z_SRED, sos)

    # чужой веник у калитки
    s += SL(Z_SRED, f'<g transform="rotate(96 1240 980)">'
                    + _venik(1240, 1250, 520, t, "#8a7246", "#b8352c", False, 1.0, .2,
                             1.1, 253) + "</g>")
    # пунктир взгляда от глаз к венику
    pun = ""
    for i in range(14):
        p = i / 13.0
        px_ = sx_ - 20 + (1240 - sx_ + 20) * p
        py_ = sy_ - 96 + (980 - sy_ + 96) * p
        mig = max(.0, 1 - abs(((t * .6) % 1.0) - p) * 4.0)
        pun += (f'<circle cx="{px_:.0f}" cy="{py_:.0f}" r="{8+6*mig:.0f}"'
                f' fill="#d8c0a0" opacity="{.30+mig*.5:.2f}"/>')
    s += SL(Z_SRED, pun)

    # хозяйка метёт крыльцо, потом обходит веник по дуге
    mah = A.ease(abs(A.w(t, 1.8, .0)))
    obh = A.ease(A.seg(t, 4.2, 2.0))
    fx, fy, fh = 420 + 420 * obh, 880 + 150 * obh, 540
    hoz = figura(fx, fy, fh, t, col="#4a3b2a", kant="#ffd98a", platok=True, ph=.2,
                 naklon=12 * mah * (1 - obh))
    r1, (v1x, v1y), (h1x, h1y) = _ruka_ekr(fx, fy, fh, 1, fh * .48,
                                           44 + 26 * mah * (1 - obh) - 60 * obh, t, "#4a3b2a",
                                           "#ffd98a", .1, 5)
    r2, _, (h2x, h2y) = _ruka_ekr(fx, fy, fh, -1, fh * .44, 62 - 40 * obh, t, "#4a3b2a",
                                  "#ffd98a", .5, 5)
    hoz += r1 + r2
    hoz += _venik_v_ruke(v1x, v1y, 300, t, "#4b3f28", "#5a4a2e",
                         102 - 26 * mah * (1 - obh) + 22 * obh, .95, 255, .25, .7)
    hoz += para_izo_rta(fx + 46, fy - fh * .80, t, .3, 1.0, .5)
    s += SL(Z_SRED, hoz + ten(fx, fy + 8, 110, 20, .45))

    # куры разбегаются, корыто, поленница
    # КУРЫ РЯБЫЕ, А НЕ БЕЛЫЕ: сливочный #e2d6c2 на буром дворе читался
    # батоном или костью (осмотр 15.11). Теперь у каждой свой тон и размер.
    for i, kcol in enumerate(("#b9a88c", "#8a7a62", "#c2a882", "#9a8468")):
        kp = ((t * .55 + i * .22) % 1.0)
        s += SL(Z_SRED, kura(300 + i * 150 + 220 * kp,
                             1050 - 30 * abs(A.w(t, 1.2, i * .3)),
                             t, 1.18 + .14 * (i % 2), i * .25, kcol))
    s += SL(Z_SRED, f'<path d="M700,1070 Q760,990 900,990 L1100,990 Q1180,1056'
                    f' 1140,1076 Z" fill="url(#derev)" {o(6)}/>'
                    f'<ellipse cx="920" cy="996" rx="200" ry="30" fill="#5b4428"'
                    f' {o(4)}/>')
    s += SL(Z_SRED, _polenica(1620, 780, 320, 270, 257, 26))
    s += SL(Z_SRED, _dvorovaya_utvar(700, 880, 420, t, 301, ["kadka", "korzina"]))
    s += SL(Z_SRED, goloe_derevo(1180, 800, 420, t, 303, 8, "#2a2b33", True))
    s += SL(Z_SRED, _kadushki_i_grabli(260, 1070, t, 305))
    s += SL(Z_PERED, _stolb_pered(1880, 90, "#1d1611", 0, H))
    s += SL(Z_LETIT, mokryy_sneg(t, 16, 37, .4, .7))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def venik_i_dlinnaya_palka(t):
    """Крыльцо современного дома с ковриком и фонарём, у нижней доски лежит
    чужой веник. Хозяин в куртке и резиновых сапогах стоит на земле и обеими
    руками держит длинную лыжную палку, как клюшку, и её концом отодвигает
    веник к калитке. Рядом лопата, лейка, собачья миска."""
    rnd = random.Random(133)
    s = nebo("sumer", t, True, 67)
    s += oblaka(t, 120, 4, 55, .36)
    s += SL(Z_DAL, goloe_derevo(1700, 560, 480, t, 33, 9, "#2a2b33", False)
            + goloe_derevo(240, 540, 380, t, 35, 7, "#2a2b33", False))
    # дом: сайдинг, окно со светом
    s += SL(Z_SRED, doski(300, 60, 1120, 660, 72, False, "dosk"))
    s += SL(Z_SRED, f'<rect x="300" y="60" width="1120" height="660" fill="none"'
                    f' {o(9)}/>')
    s += SL(Z_SRED, okno_izby(1060, 160, 300, 250, t, svet=True)
            + teplo(1210, 286, 270, 220, .44))
    s += SL(Z_SRED, f'<rect x="560" y="180" width="300" height="540" rx="8"'
                    f' fill="#5e4a3a" {o(6)}/>'
                    f'<rect x="586" y="210" width="248" height="230" rx="6"'
                    f' fill="#7d6a48" {o(4)}/>'
                    f'<rect x="586" y="470" width="248" height="230" rx="6"'
                    f' fill="#7d6a48" {o(4)}/>'
                    f'<rect x="812" y="430" width="22" height="70" rx="9"'
                    f' fill="{ZHELEZ}" {o(3)}/>')
    # фонарь у двери
    fg = .6 + .4 * abs(A.w(t, 2.4, .2))
    s += SL(Z_SRED, f'<rect x="900" y="200" width="22" height="80" fill="#3a4045"'
                    f' {o(3)}/>'
                    f'<path d="M880,280 L944,280 L930,370 L894,370 Z" fill="#3a4045"'
                    f' {o(5)}/>'
                    f'<path d="M888,288 L936,288 L924,362 L900,362 Z" fill="#ffd98a"'
                    f' opacity="{fg:.2f}"/>'
                    f'<circle cx="912" cy="326" r="90" fill="#ffd98a"'
                    f' opacity="{fg*.22:.2f}"/>')

    zem = f'<rect x="0" y="790" width="{W}" height="290" fill="#473626"/>'
    zem += _zemlya_faktura(840, 1060, 259, 14)
    zem += _listya(261, 26, 830, 1060)
    s += SL(Z_SRED, zem)
    s += SL(Z_SRED, _kryl_co(540, 720, 420, 150, t, 3, True, False))
    s += SL(Z_SRED, f'<rect x="590" y="690" width="320" height="42" rx="8"'
                    f' fill="#4a5055" {o(5)}/>')
    for i in range(9):
        s += SL(Z_SRED, f'<line x1="{600+i*35:.0f}" y1="694" x2="{600+i*35:.0f}"'
                        f' y2="728" stroke="#2f3338" stroke-width="7"/>')
    # калитка справа
    s += SL(Z_SRED, _zabor_dosok(1560, 640, 400, 300, 263, 58, "#3f5a46"))

    # чужой веник едет к калитке
    ed = A.ease(A.seg(t, .4, 2.2))
    vx_ = 980 + 520 * ed
    s += SL(Z_SRED, f'<g transform="rotate(92 {vx_:.0f} 940)">'
                    + _venik(vx_, 1200, 480, t, "#8a7246", "#b8352c", False, 1.0, .2,
                             1.0, 265) + "</g>")

    # хозяин с длинной палкой
    fx, fy, fh = 560, 1030, 580
    # ГАММА ТЁПЛАЯ, КАК ВЕСЬ ВЕЧЕР: фигура была бирюзовой (#2f4a52) и выпадала
    # из кадра, палка — холодной сталью (осмотр 15.11)
    hoz = figura(fx, fy, fh, t, col="#5a3f2e", kant="#ffd98a", ph=.2, shapka=True,
                 naklon=-8)
    # палка ОДНОЙ рукой, от правого плеча наружу; левая просто висит вниз —
    # прежде на её конце болтался кулак, которому палку взять было неоткуда
    r1, (p1x, p1y), (h1x, h1y) = _ruka(fx, fy, fh, 1, fh * .36, 26, t, "#5a3f2e",
                                       "#ffd98a", .1, 3)
    r2, (p2x, p2y), (h2x, h2y) = _ruka(fx, fy, fh, -1, fh * .30, 80, t, "#5a3f2e",
                                       "#ffd98a", .5, 3)
    hoz += r1 + r2
    # хват: ближний кулак на конце палки, дальний чуть выше по ней
    # палка начинается ОТСТУПИВ от кисти и светлее пальто: при тоне, близком
    # к одежде, рукав и палка сливались в один брусок «из груди» (осмотр 15.11)
    pal_x0, pal_y0 = p1x + 44, p1y + 16
    # длина палки ограничена 340 px: прежде она тянулась на 520 и доходила
    # почти до края кадра (осмотр 15.11)
    _pdx, _pdy = (vx_ - 90) - pal_x0, 968 - pal_y0
    _pk = min(1.0, 340.0 / max(1.0, math.hypot(_pdx, _pdy)))
    pal_x1, pal_y1 = pal_x0 + _pdx * _pk, pal_y0 + _pdy * _pk
    hoz += (f'<line x1="{pal_x0:.0f}" y1="{pal_y0:.0f}" x2="{pal_x1:.0f}"'
            f' y2="{pal_y1:.0f}" stroke="#b08a52" stroke-width="17"'
            f' stroke-linecap="round"/>'
            f'<line x1="{pal_x0:.0f}" y1="{pal_y0:.0f}" x2="{pal_x1:.0f}"'
            f' y2="{pal_y1:.0f}" stroke="#e8cf96" stroke-width="5" opacity=".55"/>'
            f'<circle cx="{pal_x1:.0f}" cy="{pal_y1:.0f}" r="25" fill="none"'
            f' stroke="#b08a52" stroke-width="9"/>'
            f'<rect x="{pal_x0-22:.0f}" y="{pal_y0-28:.0f}" width="44" height="56"'
            f' rx="15" fill="#3a2b20" {o(5)}/>'
            f'<path d="M{pal_x0-16:.0f},{pal_y0-14:.0f} l32,6'
            f' M{pal_x0-16:.0f},{pal_y0+2:.0f} l32,6'
            f' M{pal_x0-16:.0f},{pal_y0+18:.0f} l32,6" stroke="#6a5438"'
            f' stroke-width="5" opacity=".9"/>')
    # резиновые сапоги
    hoz += (f'<path d="M{fx-56:.0f},{fy-fh*.26:.0f} L{fx-10:.0f},{fy-fh*.26:.0f}'
            f' L{fx-10:.0f},{fy-6:.0f} L{fx-70:.0f},{fy-6:.0f} Z" fill="#3a2f26"'
            f' {o(5)}/>'
            f'<path d="M{fx+12:.0f},{fy-fh*.26:.0f} L{fx+58:.0f},{fy-fh*.26:.0f}'
            f' L{fx+72:.0f},{fy-6:.0f} L{fx+12:.0f},{fy-6:.0f} Z" fill="#3a2f26"'
            f' {o(5)}/>')
    hoz += para_izo_rta(fx + 46, fy - fh * .80, t, .2, 1.0, .5)
    s += SL(Z_SRED, hoz + ten(fx, fy + 8, 120, 22, .45))

    # лопата, лейка, собачья миска, пёс нюхает веник и отходит
    s += SL(Z_SRED, f'<line x1="200" y1="700" x2="236" y2="1020" stroke="url(#derev)"'
                    f' stroke-width="20" stroke-linecap="round"/>'
                    f'<path d="M206,1016 L280,1030 L264,1076 L190,1062 Z"'
                    f' fill="url(#zhel)" {o(5)}/>'
                    f'<path d="M340,1070 L340,956 L470,956 L470,1070 Z" fill="#4a7a6a"'
                    f' {o(5)}/>'
                    f'<path d="M470,990 L560,940 L566,966 L478,1014 Z" fill="#4a7a6a"'
                    f' {o(4)}/>'
                    f'<path d="M352,956 Q404,900 456,956" fill="none" stroke="#4a7a6a"'
                    f' stroke-width="11"/>'
                    f'<ellipse cx="1180" cy="1060" rx="78" ry="26" fill="#5e656a"'
                    f' {o(4)}/>')
    nn = (t * .34) % 1.0
    px3 = 1340 - 180 * max(.0, nn - .5) * 2
    s += SL(Z_SRED, f'<ellipse cx="{px3:.0f}" cy="1010" rx="98" ry="44"'
                    f' fill="#6b5236" {o(4)}/>'
                    f'<ellipse cx="{px3+86:.0f}" cy="986" rx="44" ry="38"'
                    f' fill="#6b5236" {o(4)}/>'
                    f'<path d="M{px3+112:.0f},966 L{px3+126:.0f},922'
                    f' L{px3+86:.0f},946 Z" fill="#54402a" {o(3)}/>'
                    f'<circle cx="{px3+100:.0f}" cy="982" r="5" fill="#120c08"/>'
                    f'<path d="M{px3-90:.0f},994 Q{px3-140:.0f},'
                    f'{950-16*A.w(t,1.3,.2):.0f} {px3-154:.0f},1004" fill="none"'
                    f' stroke="#6b5236" stroke-width="15" stroke-linecap="round"/>')
    s += SL(Z_SRED, _gorodskoy_hlam(1180, 1072, 420, t, 307, ["yaschik", "kust"]))
    s += SL(Z_SRED, _polenica(60, 700, 220, 260, 309, 24))
    s += SL(Z_SRED, _dvorovaya_utvar(700, 1072, 420, t, 311, ["kadka", "korob"]))
    s += SL(Z_PERED, _vetka_pered(2020, 60, 720, 160, t, 267, "#241c16", 6))
    s += SL(Z_LETIT, mokryy_sneg(t, 16, 39, .4, .7))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def lestnichnaya_ploschadka_s_dvumya_d(t):
    """Лестничная площадка, две двери, между ними велосипед, коврики, детская
    коляска. В проёме открытой двери соседки виден настоящий кадр: веник
    метёт пол. Соседка протягивает швабру и веник, хозяйка обеими ладонями
    показывает «нет». У неё за спиной новые веник и швабра в упаковке."""
    rnd = random.Random(134)
    pol = 860
    s = f'<rect width="{W}" height="{H}" fill="#3a4046"/>'
    s += SL(Z_DAL, f'<rect x="0" y="0" width="{W}" height="{pol:.0f}" fill="#58646a"/>'
                   f'<rect x="0" y="{pol-300:.0f}" width="{W}" height="300"'
                   f' fill="#6e7a80" opacity=".9"/>'
                   f'<rect x="0" y="{pol-314:.0f}" width="{W}" height="22"'
                   f' fill="#3e484e" opacity=".9"/>'
                   f'<rect x="0" y="{pol-20:.0f}" width="{W}" height="34"'
                   f' fill="#2f383c" opacity=".9"/>')
    # плитка пола
    sh = ""
    yy, ry = pol + 14, 0
    while yy < H:
        step = 130 + (yy - pol) * .5
        xx = -((ry % 2) * step / 2)
        while xx < W:
            sh += (f'<rect x="{xx:.0f}" y="{yy:.0f}" width="{step:.0f}"'
                   f' height="{step*.5:.0f}" fill="{["#6a6258","#4e4a42"][ry%2]}"'
                   f' opacity=".85"/>')
            xx += step * 2
        yy += step * .5
        ry += 1
    s += SL(Z_DAL, sh)
    s += SL(Z_SRED, tusklaya_lampochka(960, 60, t, 1.6, True))
    s += SL(Z_SRED, teplo(960, 280, 400, 300, .32))
    # перила лестницы справа
    s += SL(Z_SRED, f'<path d="M1700,520 L1960,400 L1960,440 L1700,560 Z"'
                    f' fill="#5e4a3a" {o(5)}/>')
    for i in range(5):
        s += SL(Z_SRED, f'<line x1="{1716+i*58:.0f}" y1="{548-i*26:.0f}"'
                        f' x2="{1716+i*58:.0f}" y2="{880-i*26:.0f}" stroke="{ZHELEZ}"'
                        f' stroke-width="9"/>')

    # закрытая дверь хозяйки слева
    s += SL(Z_SRED, f'<rect x="120" y="190" width="380" height="670" rx="8"'
                    f' fill="#5e4a3a" {o(7)}/>'
                    f'<rect x="150" y="224" width="320" height="270" rx="6"'
                    f' fill="#7d6a48" {o(4)}/>'
                    f'<rect x="150" y="524" width="320" height="300" rx="6"'
                    f' fill="#7d6a48" {o(4)}/>'
                    f'<rect x="440" y="500" width="24" height="76" rx="10"'
                    f' fill="{ZHELEZ}" {o(3)}/>'
                    f'<circle cx="300" cy="200" r="20" fill="#c9b78e" {o(3)}/>')

    # открытая дверь соседки: нарисованный вид, метка, косяк поверх
    px_, py_, pw_, ph_ = 980, 290, 900, 570
    put = kontur_proema(px_, py_, pw_, ph_, "pryam")
    vid = (f'<path d="{put}" fill="#4e4236"/>')
    for i in range(9):
        vid += (f'<rect x="{px_:.0f}" y="{py_+40+i*58:.0f}" width="{pw_:.0f}"'
                f' height="48" fill="url(#dosk)" opacity=".9"/>')
    s += SL(Z_SRED, vid + mesto_stoka(px_, py_, pw_, ph_, "pryam")
            + f'<rect x="{px_-46:.0f}" y="{py_-46:.0f}" width="{pw_+92:.0f}"'
              f' height="{ph_+66:.0f}" rx="8" fill="none" stroke="#5e4a3a"'
              f' stroke-width="46"/>')
    # распахнутая створка перед проёмом
    s += SL(Z_SRED, f'<g transform="rotate(-5 {px_-40:.0f} {py_+ph_:.0f})">'
                    f'<rect x="{px_-250:.0f}" y="{py_-20:.0f}" width="230"'
                    f' height="{ph_+20:.0f}" rx="8" fill="#5e4a3a" {o(6)}/>'
                    f'<rect x="{px_-224:.0f}" y="{py_+10:.0f}" width="178"'
                    f' height="230" rx="6" fill="#7d6a48" {o(4)}/>'
                    f'<rect x="{px_-224:.0f}" y="{py_+270:.0f}" width="178"'
                    f' height="250" rx="6" fill="#7d6a48" {o(4)}/></g>')

    # велосипед, коврики, коляска
    s += SL(Z_SRED, _gorodskoy_hlam(520, 1010, 420, t, 269, ["velik", "yaschik"]))
    s += SL(Z_SRED, _gorodskoy_hlam(80, 1074, 400, t, 405, ["korobka", "yaschik"]))
    for i, (kx_, ky_) in enumerate(((240, 950), (1260, 1000))):
        s += SL(Z_SRED, f'<path d="M{kx_-150:.0f},{ky_:.0f} L{kx_+150:.0f},{ky_:.0f}'
                        f' L{kx_+186:.0f},{ky_+76:.0f} L{kx_-186:.0f},{ky_+76:.0f} Z"'
                        f' fill="{["#8a4a4a","#4a6a5a"][i]}" {o(5)}/>'
                        f'<path d="M{kx_-160:.0f},{ky_+28:.0f}'
                        f' L{kx_+160:.0f},{ky_+28:.0f} M{kx_-174:.0f},{ky_+54:.0f}'
                        f' L{kx_+174:.0f},{ky_+54:.0f}" stroke="#e8dcc8"'
                        f' stroke-width="7" opacity=".55"/>')
    kol = (f'<path d="M1600,900 Q1620,790 1740,790 L1860,790 Q1900,880 1860,940'
           f' L1640,940 Z" fill="#3a4a5a" {o(6)}/>'
           f'<path d="M1620,860 Q1700,816 1820,824" fill="none" stroke="#5a6a7a"'
           f' stroke-width="9"/>'
           f'<circle cx="1660" cy="990" r="52" fill="none" stroke="#2f3338"'
           f' stroke-width="14"/>'
           f'<circle cx="1830" cy="990" r="52" fill="none" stroke="#2f3338"'
           f' stroke-width="14"/>'
           f'<path d="M1860,790 L1930,700" stroke="#5a6a7a" stroke-width="13"'
           f' fill="none"/>')
    s += SL(Z_SRED, kol)

    # новые веник и швабра в упаковке за спиной хозяйки, листок с числом
    # НОВЫЕ ВЕНИК И ШВАБРА ПРИСЛОНЕНЫ К СТЕНЕ И СТОЯТ НА ПОЛУ: раньше они
    # просто висели в воздухе, а насадка швабры была ярко-розовой (#8a5a86) и
    # выбивалась из всего кадра (осмотр 15.11)
    s += SL(Z_SRED, ten(300, 1016, 76, 17, .5) + ten(420, 1062, 84, 18, .5)
            + f'<g transform="rotate(7 300 1010)">'
            + _venik(300, 1010, 420, t, "url(#solom)", "#c8a24a", True, .0, .3,
                     .85, 271) + "</g>")
    s += SL(Z_SRED, f'<line x1="372" y1="606" x2="420" y2="1010" stroke="#6a5a4a"'
                    f' stroke-width="17"/>'
                    f'<path d="M352,1010 L488,1010 L482,1056 L358,1056 Z"'
                    f' fill="#5a6670" {o(5)}/>'
                    f'<path d="M360,1018 L480,1018 M362,1038 L478,1038"'
                    f' stroke="#8a949c" stroke-width="6" opacity=".6"/>'
                    f'<rect x="244" y="560" width="230" height="300" rx="10"'
                    f' fill="#cfe4f5" opacity=".30" {o(3)}/>')
    lst = 5 * A.w(t, 2.0, .3)
    s += SL(Z_SRED, f'<g transform="rotate({lst:.1f} 360 580)">'
                    f'<rect x="300" y="560" width="120" height="86" rx="7"'
                    f' fill="#f0ead6" {o(4)}/>'
                    f'<path d="M318,598 Q356,586 404,600" fill="none" stroke="#8a929a"'
                    f' stroke-width="6"/>'
                    f'<path d="M318,622 Q350,612 388,624" fill="none" stroke="#8a929a"'
                    f' stroke-width="5"/></g>')

    # соседка в дверях протягивает швабру и веник
    # СОСЕДКА ЦЕЛИКОМ В КАДРЕ: стояла на 1880 и обрезалась правым краем
    # (туловище 1771-1989 при холсте 1920). И протягивает она ЛЕВОЙ — хозяйка
    # стоит слева, а правый рукав под 176° уходил поперёк тела за холст.
    sx_, sy_, sh_ = 1676, 944, 540
    sos = figura(sx_, sy_, sh_, t, col="#8a4a6a", kant="#ffd98a", ph=.5, naklon=-5)
    r2, (q2x, q2y), (s2x, s2y) = _ruka(sx_, sy_, sh_, -1, sh_ * .56, 6, t, "#8a4a6a",
                                       "#ffd98a", .6, 5)
    r1, (q1x, q1y), (s1x, s1y) = _ruka(sx_, sy_, sh_, 1, sh_ * .34, 72, t, "#8a4a6a",
                                       "#ffd98a", .2, 5)
    sos += r1 + r2
    # швабра в протянутой левой: черенок от кисти, насадка на дальнем конце
    sos += (f'<line x1="{q2x:.0f}" y1="{q2y:.0f}" x2="{q2x-250:.0f}"'
            f' y2="{q2y+96:.0f}" stroke="#6a5a4a" stroke-width="15"/>'
            f'<path d="M{q2x-250:.0f},{q2y+74:.0f} L{q2x-164:.0f},{q2y+112:.0f}'
            f' L{q2x-178:.0f},{q2y+146:.0f} L{q2x-266:.0f},{q2y+108:.0f} Z"'
            f' fill="#5a6670" {o(4)}/>')
    # веник в правой, прутьями вниз-вперёд и ЗА черенок
    sos += _venik_v_ruke(q1x, q1y, 300, t, "#8a7246", "#b8352c", 92, .78, 273, .3, .4)
    s += SL(Z_SRED, sos + ten(sx_, sy_ + 6, 104, 19, .45))

    # хозяйка напротив: обе ладони вежливо показывают «нет»
    hx_, hy_, hh_ = 700, 1000, 560
    hoz = figura(hx_, hy_, hh_, t, col="#3d4a3a", kant="#ffd98a", ph=.2)
    r3, (n1x, n1y), (g1x, g1y) = _ruka_ekr(hx_, hy_, hh_, 1, hh_ * .40, -48, t, "#3d4a3a",
                                           "#ffd98a", .1, 4)
    r4, (n2x, n2y), (g2x, g2y) = _ruka_ekr(hx_, hy_, hh_, -1, hh_ * .40, -22, t, "#3d4a3a",
                                           "#ffd98a", .5, 4)
    hoz += r3 + r4
    for (nx_, ny_) in ((n1x, n1y), (n2x, n2y)):
        hoz += (f'<ellipse cx="{nx_:.0f}" cy="{ny_:.0f}" rx="40" ry="54"'
                f' fill="#3d4a3a" {o(5)}/>'
                f'<ellipse cx="{nx_:.0f}" cy="{ny_:.0f}" rx="26" ry="38"'
                f' fill="#4c5b48" opacity=".8"/>')
    # фартук
    hoz += (f'<path d="M{hx_-56:.0f},{hy_-hh_*.60:.0f} L{hx_+56:.0f},{hy_-hh_*.60:.0f}'
            f' L{hx_+76:.0f},{hy_-hh_*.16:.0f} L{hx_-76:.0f},{hy_-hh_*.16:.0f} Z"'
            f' fill="#e4dcc4" opacity=".92" {o(4)}/>')
    s += SL(Z_SRED, hoz + ten(hx_, hy_ + 8, 110, 20, .45))
    s += SL(Z_PERED, _stolb_pered(-6, 86, "#20262a", 0, H))
    s += ramka_pp("oba")
    s += vinetka(.44)
    return s


def tri_raboty_odnogo_venika(t):
    """Три сцены по словам, в каждой по одному человеку: женщина в косынке
    метёт крашеный пол обеими руками; во дворе она же бьёт веником половик
    на верёвке; на крыльце мальчик на одной ноге обметает веником снег с
    валенка."""
    rnd = random.Random(135)
    pol = 800
    s = f'<rect width="{W}" height="{H}" fill="#2a2118"/>'
    s += SL(Z_DAL, brevna(0, 0, 640, pol + 40, 92))
    s += SL(Z_DAL, f'<rect x="640" y="0" width="640" height="{pol+40:.0f}"'
                   f' fill="#51606a"/>')
    s += SL(Z_DAL, nebo("sumer", t, True, 69))
    s += SL(Z_DAL, f'<rect x="640" y="0" width="640" height="{pol+40:.0f}"'
                   f' fill="#2f3a46" opacity=".55"/>')
    s += SL(Z_DAL, brevna(1280, 0, 680, pol + 40, 92))
    s += SL(Z_DAL, f'<rect x="200" y="56" width="1520" height="62" rx="12"'
                   f' fill="#3b2a1a" {o(7)}/>'
                   f'<rect x="200" y="112" width="1520" height="18" fill="#2a1d12"'
                   f' opacity=".8"/>')
    # простенки между тремя сценами
    for dx2 in (620, 1260):
        s += SL(Z_SRED, f'<rect x="{dx2:.0f}" y="0" width="52" height="{H}"'
                        f' fill="#2a1d12" {o(6)}/>'
                        f'<rect x="{dx2+10:.0f}" y="0" width="16" height="{H}"'
                        f' fill="#3e2c1c" opacity=".8"/>')

    # ── 1: крашеный пол, женщина метёт обеими руками
    s += SL(Z_DAL, okno_izby(60, 150, 260, 230, t, svet=False, moroz=.4))
    s += SL(Z_DAL, _polka_s_utvaryu(300, 330, 300, t, 275, 3))
    s += SL(Z_SRED, f'<rect x="0" y="{pol:.0f}" width="620" height="{H-pol}"'
                    f' fill="#8a5a4a" {o(0)}/>')
    for i in range(5):
        s += SL(Z_SRED, f'<line x1="0" y1="{pol+40+i*60:.0f}" x2="620"'
                        f' y2="{pol+40+i*60:.0f}" stroke="#6e4438" stroke-width="6"'
                        f' opacity=".7"/>')
    s += SL(Z_SRED, lampa(320, 160, t, 1.2, True) + teplo(320, 300, 260, 220, .40))
    s += SL(Z_SRED, _lavka_krupno(40, 1046, 320, t, 140))
    m1 = A.ease(abs(A.w(t, 1.5, .0)))
    ax, ay, ah = 340, 1010, 500
    zh1 = figura(ax, ay, ah, t, col="#4a3b2a", kant="#ffd98a", platok=True, ph=.2,
                 naklon=14 * m1)
    r1, (w1x, w1y), (a1x, a1y) = _ruka_ekr(ax, ay, ah, 1, ah * .48, 40 + 30 * m1, t, "#4a3b2a",
                                           "#ffd98a", .1, 5)
    r2, _, (a2x, a2y) = _ruka_ekr(ax, ay, ah, -1, ah * .44, 62 + 24 * m1, t, "#4a3b2a",
                                  "#ffd98a", .5, 5)
    zh1 += r1 + r2
    zh1 += _venik_v_ruke(w1x, w1y, 290, t, "#4b3f28", "#5a4a2e",
                         100 - 24 * m1, .9, 277, .25, .7)
    s += SL(Z_SRED, zh1)
    pyl = ""
    for i in range(7):
        p = ((t * .8 + i * .14) % 1.0)
        pyl += (f'<ellipse cx="{200-p*120:.0f}" cy="{1010-p*60:.0f}"'
                f' rx="{14+p*26:.0f}" ry="{7+p*12:.0f}" fill="#8a7a62"'
                f' opacity="{(1-p)*.4:.2f}"/>')
    s += SL(Z_SRED, pyl)

    # ── 2: двор, половик на верёвке, удары веником
    s += SL(Z_DAL, _derevnya_ryad(430, t, 279, ((760, 260), (1180, 240))))
    s += SL(Z_SRED, f'<rect x="640" y="{pol+10:.0f}" width="620" height="{H-pol-10}"'
                    f' fill="#473626" {o(0)}/>')
    s += SL(Z_SRED, _zemlya_faktura(pol + 60, 1060, 281, 8))
    s += SL(Z_SRED, f'<line x1="660" y1="430" x2="1250" y2="400" stroke="#9a8a68"'
                    f' stroke-width="8"/>')
    ud = A.ease(abs(A.w(t, 1.3, .2)))
    s += SL(Z_SRED, f'<path d="M820,410 L1120,398 L{1126+16*ud:.0f},680'
                    f' L{814-16*ud:.0f},692 Z" fill="{RUSH}" {o(6)}/>'
                    f'<path d="M824,470 L1122,458 M820,540 L1124,528'
                    f' M818,610 L1126,598" stroke="{KRAS}" stroke-width="11"'
                    f' opacity=".65"/>')
    for i in range(6):
        for k in range(3):
            sp = ((t * .9 + i * .16 + k * .3) % 1.0)
            s += SL(Z_SRED, f'<ellipse cx="{1130+sp*170:.0f}"'
                            f' cy="{460+k*80-sp*70:.0f}" rx="{10+sp*24:.0f}"'
                            f' ry="{6+sp*14:.0f}" fill="#9a8c70"'
                            f' opacity="{(1-sp)*.45*ud:.2f}"/>')
    bx_, by_, bh_ = 686, 1046, 500
    zh2 = figura(bx_, by_, bh_, t, col="#5a3f46", kant="#ffd98a", platok=True, ph=.5,
                 naklon=-8 * ud)
    # Женщина встала ЛЕВЕЕ половика и бьёт по нему ПРАВОЙ, наружу: прежде она
    # стояла прямо перед половиком, рукав под -44° шёл поперёк её лица, а
    # прутья веника ложились ей на голову (осмотр 15.11)
    r3, (w2x, w2y), (b1x, b1y) = _ruka(bx_, by_, bh_, 1, bh_ * .50, -50 + 30 * ud, t,
                                       "#5a3f46", "#ffd98a", .3, 6)
    r4, _, (b2x, b2y) = _ruka(bx_, by_, bh_, -1, bh_ * .44, 74, t, "#5a3f46",
                              "#ffd98a", .7, 4)
    zh2 += r3 + r4
    zh2 += _venik_v_ruke(w2x, w2y, 320, t, "#4b3f28", "#5a4a2e",
                         -42 + 26 * ud, .85, 283, .25, .2)
    zh2 += para_izo_rta(bx_ + 44, by_ - bh_ * .80, t, .4, 1.0, .5)
    s += SL(Z_SRED, zh2 + ten(bx_, by_ + 6, 100, 18, .45))
    s += SL(Z_SRED, _dvorovaya_utvar(940, 1070, 310, t, 285, ["kadka", "vedro"]))

    # ── 3: крыльцо, мальчик на одной ноге обметает валенок
    s += SL(Z_DAL, okno_izby(1640, 150, 260, 230, t, svet=True)
            + teplo(1770, 270, 240, 200, .42))
    s += SL(Z_DAL, _polka_s_utvaryu(1320, 340, 300, t, 287, 3))
    s += SL(Z_SRED, f'<rect x="1312" y="{pol+10:.0f}" width="648" height="{H-pol-10}"'
                    f' fill="#473626" {o(0)}/>')
    s += SL(Z_SRED, _kryl_co(1340, 820, 540, 170, t, 3, True, False))
    sug = (f'<path d="M1320,900 Q1420,844 1540,862 Q1660,820 1780,856'
           f' Q1880,834 1956,868 L1956,1080 L1320,1080 Z" fill="url(#sneg)" {o(5)}/>'
           f'<path d="M1330,906 Q1440,866 1546,882 Q1664,846 1790,876"'
           f' fill="none" stroke="#f2f7fb" stroke-width="7" opacity=".7"/>')
    s += SL(Z_SRED, sug)
    kach2 = A.ease(abs(A.w(t, 1.4, .1)))
    cx_, cy_, ch_ = 1600, 820, 400
    mal = figura(cx_, cy_, ch_, t, col="#3a4452", kant="#ffd98a", ph=.3,
                 naklon=8 * kach2 - 4)
    r5, (w3x, w3y), (c1x, c1y) = _ruka_ekr(cx_, cy_, ch_, 1, ch_ * .52, 66, t, "#3a4452",
                                           "#ffd98a", .2, 7)
    r6, _, (c2x, c2y) = _ruka_ekr(cx_, cy_, ch_, -1, ch_ * .48, 152, t, "#3a4452", "#ffd98a", .6,
                                  4)
    mal += r5 + r6
    # опорная нога на крыльце, вторая поднята
    mal += (f'<line x1="{cx_-14:.0f}" y1="{cy_-ch_*.28:.0f}" x2="{cx_-30:.0f}"'
            f' y2="{cy_-6:.0f}" stroke="#3a4452" stroke-width="36"'
            f' stroke-linecap="round"/>'
            f'<line x1="{cx_+14:.0f}" y1="{cy_-ch_*.28:.0f}" x2="{cx_+160:.0f}"'
            f' y2="{cy_-142:.0f}" stroke="#3a4452" stroke-width="36"'
            f' stroke-linecap="round"/>'
            f'<path d="M{cx_+136:.0f},{cy_-190:.0f} L{cx_+212:.0f},{cy_-180:.0f}'
            f' L{cx_+218:.0f},{cy_-92:.0f} L{cx_+130:.0f},{cy_-102:.0f} Z"'
            f' fill="#9a8c70" {o(5)}/>'
            f'<ellipse cx="{cx_+174:.0f}" cy="{cy_-94:.0f}" rx="50" ry="19"'
            f' fill="#7a6c52" {o(4)}/>')
    mal += _venik_v_ruke(w3x, w3y, 230, t, "#4b3f28", "#5a4a2e",
                         -86 + 16 * kach2, .7, 289, .25, .5)
    for i in range(8):
        sp = ((t * 1.1 + i * .12) % 1.0)
        mal += (f'<circle cx="{cx_+130+sp*120:.0f}" cy="{cy_-110+sp*180:.0f}"'
                f' r="{7-sp*3:.0f}" fill="#e4f1fa" opacity="{(1-sp)*.8:.2f}"/>')
    mal += para_izo_rta(cx_ + 40, cy_ - ch_ * .80, t, .2, .9, .5)
    s += SL(Z_SRED, mal)
    s += SL(Z_SRED, _dvorovaya_utvar(1340, 1070, 320, t, 291, ["korzina", "vedro"]))
    s += SL(Z_PERED, ramka_pp("oba"))
    s += vinetka(.44)
    return s


# ═══ из chast2.py ═══
def _varezhka(x, y, h_=800.0, t=0.0, ph=.0, col="#e8d8c0", kant="#b89a74"):
    """ВАРЕЖКА НА КОНЦЕ РУКАВА — ХВАТ ЧИТАЕТСЯ ПЕРЕКРЫТИЕМ.

    Разбор принятого ролика 17-11 глазами: там рука — ОДИН сегмент рукава,
    на конце светлый овал-варежка, и предмет лежит ПОД варежкой внахлёст.
    Поэтому видно, что предмет держат. В первой порции «Дня Ионы» рукав
    обрывался в пустоту во всех 17 осмотренных кадрах, и предмет примыкал
    встык или висел с зазором («веник висит в воздухе без руки»).
    Пальцев не рисуем — их нет и в образце: овал, большой палец отдельной
    долькой, тёмный кант по нижней кромке, светлый блик сверху.

    Ставится ПОСЛЕ предмета: овал ложится поверх черенка.

    ПРАВИЛО (решение по осмотру порции 2): варежка ставится ТОЛЬКО там, где
    она перекрывает предмет не меньше чем на ЧЕТВЕРТЬ своей площади. Где
    перекрытия нет — варежку не ставим вовсе, рукав остаётся без кисти, как
    в первой порции: иначе она читается отдельным светлым пятном и обещает
    хват, которого нет. Проверяется числом: `varezhki_proverka.py`.
    """
    s_ = max(.42, h_ / 800.0)
    rx_, ry_ = 34 * s_, 27 * s_
    kol = 3 * s_ * A.w(t, 1.7, ph)
    return (f'<g transform="translate({kol:.1f},0)">'
            f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{rx_:.0f}" ry="{ry_:.0f}"'
            f' fill="{col}" stroke="{K}" stroke-width="{max(2, 4 * s_):.1f}"/>'
            f'<ellipse cx="{x-rx_*.62:.0f}" cy="{y+ry_*.30:.0f}" rx="{rx_*.34:.0f}"'
            f' ry="{ry_*.46:.0f}" fill="{col}" stroke="{K}"'
            f' stroke-width="{max(2, 3 * s_):.1f}"/>'
            f'<path d="M{x-rx_*.84:.0f},{y+ry_*.42:.0f}'
            f' q{rx_*.84:.0f},{ry_*.68:.0f} {rx_*1.68:.0f},{-ry_*.16:.0f}"'
            f' fill="none" stroke="{kant}" stroke-width="{max(2, 5 * s_):.1f}"'
            f' opacity=".8"/>'
            f'<path d="M{x-rx_*.56:.0f},{y-ry_*.44:.0f}'
            f' q{rx_*.46:.0f},{-ry_*.34:.0f} {rx_*1.02:.0f},{-ry_*.06:.0f}"'
            f' fill="none" stroke="#fff4e2" stroke-width="{max(2, 4 * s_):.1f}"'
            f' opacity=".55"/></g>')


def _konus_sveta(x, y, w_, h_, ug=0.0, op=.40, col="#ffd98a"):
    """Световой конус от источника на стену или пол: у принятого 17-11 он
    есть в каждом кадре, и именно от него кадр читается ОСВЕЩЁННЫМ, а не
    просто светлым. Прозрачность держим выше .35 — мутных пятен не плодим."""
    return (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
            f'<path d="M{x-w_*.14:.0f},{y:.0f} L{x+w_*.14:.0f},{y:.0f}'
            f' L{x+w_*.5:.0f},{y+h_:.0f} L{x-w_*.5:.0f},{y+h_:.0f} Z"'
            f' fill="{col}" opacity="{op:.2f}"/>'
            f'<path d="M{x-w_*.07:.0f},{y:.0f} L{x+w_*.07:.0f},{y:.0f}'
            f' L{x+w_*.26:.0f},{y+h_:.0f} L{x-w_*.26:.0f},{y+h_:.0f} Z"'
            f' fill="#fff2d2" opacity="{op*.7:.2f}"/></g>')


def _pol_shvy(y0, y1, seed=3, n=5, col="#3f3326"):
    """Фактура пола и земли вблизи: швы половиц сходятся к точке схода,
    поперечные трещины, пара сучков. Разбор 17-11: у них деталь у земли
    втрое густее, чем в небе, у нас была ровная заливка."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n + 1):
        p = i / float(n)
        x0 = 960 + (p - .5) * 1120
        x1 = 960 + (p - .5) * 2600
        s += (f'<line x1="{x0:.0f}" y1="{y0:.0f}" x2="{x1:.0f}" y2="{y1:.0f}"'
              f' stroke="{col}" stroke-width="7" opacity=".55"/>')
    for i in range(4):
        yy = y0 + (y1 - y0) * (.22 + i * .22)
        s += (f'<path d="M-20,{yy:.0f} Q480,{yy-14:.0f} 980,{yy+8:.0f}'
              f' Q1480,{yy+20:.0f} 1940,{yy-6:.0f}" fill="none" stroke="{col}"'
              f' stroke-width="5" opacity=".42"/>')
    for i in range(5):
        sx = rnd.uniform(80, W - 80)
        sy = rnd.uniform(y0 + 20, y1 - 20)
        s += (f'<ellipse cx="{sx:.0f}" cy="{sy:.0f}" rx="{rnd.uniform(16, 30):.0f}"'
              f' ry="{rnd.uniform(7, 13):.0f}" fill="{col}" opacity=".5"/>')
    return s


def _kafel(x, y, w_, h_, t, seed=3, col="#d4dcdc", shov="#a8b4b4"):
    """Кафельная стена кухни: плитка в перевязку, затирка, пара плиток с
    рисунком и мокрый блик по нижнему ряду у мойки."""
    rnd = random.Random(seed)
    s = ""
    kh = 74
    for r in range(int(h_ / kh) + 1):
        yy = y + r * kh
        off = 0 if r % 2 == 0 else 86
        for c in range(int(w_ / 172) + 2):
            xx = x - 86 + off + c * 172
            if xx + 166 < x or xx > x + w_:
                continue
            tn = col if rnd.random() < .82 else "#c2cdcd"
            s += (f'<rect x="{xx:.0f}" y="{yy:.0f}" width="166" height="{kh-7}"'
                  f' rx="6" fill="{tn}" stroke="{shov}" stroke-width="4"/>')
            if rnd.random() < .16:
                s += (f'<path d="M{xx+40:.0f},{yy+44:.0f} q{42:.0f},{-30:.0f}'
                      f' {84:.0f},0" fill="none" stroke="#8fa3a8"'
                      f' stroke-width="6" opacity=".7"/>')
    s += (f'<rect x="{x:.0f}" y="{y+h_-14:.0f}" width="{w_:.0f}" height="14"'
          f' fill="#8f9c9c" opacity=".7"/>')
    return s


def _tarelka(cx, cy, r, t, ph=.0, pena=True, ug=0.0, col="#eef2f4"):
    """Тарелка, которую видно со стоп-кадра: борт, кольцо дна, глазурный
    блик дугой, скол на борту и пена по краю."""
    bl = .4 + .6 * abs(A.w(t, 2.2, ph))
    s = (f'<g transform="rotate({ug:.1f} {cx:.0f} {cy:.0f})">'
         f'<ellipse cx="{cx:.0f}" cy="{cy:.0f}" rx="{r:.0f}" ry="{r*.86:.0f}"'
         f' fill="{col}" {o(6)}/>'
         f'<ellipse cx="{cx:.0f}" cy="{cy:.0f}" rx="{r*.80:.0f}" ry="{r*.68:.0f}"'
         f' fill="none" stroke="#b9c6cc" stroke-width="7"/>'
         f'<ellipse cx="{cx:.0f}" cy="{cy:.0f}" rx="{r*.46:.0f}" ry="{r*.39:.0f}"'
         f' fill="#e2e9ec" {o(4)}/>'
         f'<path d="M{cx-r*.72:.0f},{cy-r*.30:.0f} Q{cx-r*.10:.0f},{cy-r*.78:.0f}'
         f' {cx+r*.56:.0f},{cy-r*.44:.0f}" fill="none" stroke="#ffffff"'
         f' stroke-width="{max(5, r*.11):.0f}" opacity="{.32+bl*.40:.2f}"/>'
         f'<path d="M{cx+r*.86:.0f},{cy-r*.14:.0f} l{r*.12:.0f},{r*.08:.0f}'
         f' l{-r*.12:.0f},{r*.10:.0f} Z" fill="#c6d0d4" {o(3)}/>')
    if pena:
        rnd = random.Random(int(cx) + int(r))
        for i in range(9):
            a = math.radians(i * 40 + 12 * A.w(t, 2.8, ph + i * .1))
            px = cx + r * .93 * math.cos(a)
            py = cy + r * .80 * math.sin(a)
            rr = rnd.uniform(13, 27)
            s += (f'<circle cx="{px:.0f}" cy="{py:.0f}" r="{rr:.0f}" fill="#f6fbff"'
                  f' stroke="#c8d8e2" stroke-width="3"/>')
    return s + "</g>"


def _stopka_tarelok(x, y, n, t, seed=5, shir=190):
    """Гора тарелок: каждая своя, с бортом и щербинкой, стопка чуть ведёт
    в сторону — ровный столбик читается трубой."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        dx = rnd.uniform(-13, 13) + 3 * A.w(t, 3.4, i * .2)
        yy = y - i * 23
        w2 = shir * rnd.uniform(.88, 1.06)
        s += (f'<ellipse cx="{x+dx:.0f}" cy="{yy:.0f}" rx="{w2*.5:.0f}" ry="{w2*.15:.0f}"'
              f' fill="#e7edf0" {o(4)}/>'
              f'<ellipse cx="{x+dx:.0f}" cy="{yy-5:.0f}" rx="{w2*.44:.0f}"'
              f' ry="{w2*.11:.0f}" fill="#fbfdfe" opacity=".8"/>')
    return s


def _pena_gorka(cx, cy, rx, t, seed=7, n=16, osadka=.0):
    """Мыльная пена кучей: пузыри разного калибра, часть с радужным бликом.
    osadka 0..1 — пена оседает, горка становится ниже."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        a = rnd.uniform(0, 6.28)
        rr = rnd.uniform(.2, 1.0)
        px = cx + math.cos(a) * rx * rr
        py = cy - abs(math.sin(a)) * rx * .34 * rr * (1 - .55 * osadka)
        b = rnd.uniform(16, 44) * (1 - .25 * osadka)
        s += (f'<circle cx="{px:.0f}" cy="{py:.0f}" r="{b:.0f}" fill="#f4fafe"'
              f' stroke="#cadbe6" stroke-width="3" opacity=".92"/>')
        if i % 3 == 0:
            s += (f'<circle cx="{px-b*.3:.0f}" cy="{py-b*.3:.0f}" r="{b*.26:.0f}"'
                  f' fill="#ffffff" opacity="{.5+.4*abs(A.w(t,2.0,i*.2)):.2f}"/>')
    return s


def _moyka(x, y, w_, t, seed=5, kran=True, osadka=.0):
    """Мойка с тумбой: столешница, врезанная чаша, смеситель с каплей,
    дверцы тумбы, пена в чаше, бутылка и губка на борту."""
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="40" rx="10"'
         f' fill="#b9b2a4" {o(6)}/>'
         f'<rect x="{x+6:.0f}" y="{y+40:.0f}" width="{w_-12:.0f}" height="{H-y-40:.0f}"'
         f' fill="#7e6c56" {o(5)}/>')
    for i in range(3):
        dx = x + 26 + i * (w_ - 70) / 3.0
        s += (f'<rect x="{dx:.0f}" y="{y+66:.0f}" width="{(w_-120)/3.2:.0f}"'
              f' height="260" rx="8" fill="#8f7b61" {o(4)}/>'
              f'<rect x="{dx+20:.0f}" y="{y+96:.0f}" width="{(w_-120)/4.4:.0f}"'
              f' height="200" rx="6" fill="#9c886c" opacity=".75"/>'
              f'<circle cx="{dx+(w_-120)/6.6:.0f}" cy="{y+300:.0f}" r="12"'
              f' fill="{ZHELEZ}" {o(3)}/>')
    cx = x + w_ * .42
    s += (f'<rect x="{cx-230:.0f}" y="{y+6:.0f}" width="460" height="30" rx="12"'
          f' fill="#6f767c" {o(5)}/>'
          f'<path d="M{cx-212:.0f},{y+28:.0f} L{cx-182:.0f},{y+176:.0f}'
          f' L{cx+182:.0f},{y+176:.0f} L{cx+212:.0f},{y+28:.0f} Z"'
          f' fill="#5a6168" {o(5)}/>'
          f'<ellipse cx="{cx:.0f}" cy="{y+172:.0f}" rx="56" ry="16" fill="#3e4348" {o(3)}/>')
    if kran:
        kx = x + w_ * .14
        s += (f'<rect x="{kx-14:.0f}" y="{y-150:.0f}" width="28" height="160" rx="12"'
              f' fill="#9aa3aa" {o(4)}/>'
              f'<path d="M{kx:.0f},{y-150:.0f} q0,{-64:.0f} {92:.0f},{-60:.0f}'
              f' q{36:.0f},{4:.0f} {32:.0f},{48:.0f}" fill="none" stroke="#9aa3aa"'
              f' stroke-width="26" stroke-linecap="round"/>'
              f'<rect x="{kx-54:.0f}" y="{y-176:.0f}" width="44" height="18" rx="8"'
              f' fill="#7d868d" {o(3)}/>')
        kap = ((t * .8) % 1.0)
        s += (f'<ellipse cx="{kx+124:.0f}" cy="{y-96+kap*86:.0f}" rx="7"'
              f' ry="{10+6*kap:.0f}" fill="#d6e8f4" opacity="{1-kap:.2f}"/>')
    s += _pena_gorka(cx, y + 150, 190, t, seed + 3, 18, osadka)
    s += (f'<rect x="{x+w_-150:.0f}" y="{y-96:.0f}" width="62" height="100" rx="14"'
          f' fill="#4e7a52" {o(4)}/>'
          f'<rect x="{x+w_-144:.0f}" y="{y-78:.0f}" width="48" height="44" rx="6"'
          f' fill="#e9f0d8" opacity=".85"/>'
          f'<rect x="{x+w_-74:.0f}" y="{y-40:.0f}" width="66" height="44" rx="12"'
          f' fill="#e4c85a" {o(4)}/>')
    return s


def _chaynik(x, y, s_=1.0, t=0.0, parok=False):
    """Чайник: тулово, носик, дуга-ручка, свисток и блик на боку."""
    s = (ten(x, y + 8 * s_, 74 * s_, 14 * s_, .45)
         + f'<path d="M{x-72*s_:.0f},{y:.0f} q{-16*s_:.0f},{-82*s_:.0f} {18*s_:.0f},{-104*s_:.0f}'
           f' q{54*s_:.0f},{-18*s_:.0f} {108*s_:.0f},0 q{34*s_:.0f},{22*s_:.0f}'
           f' {18*s_:.0f},{104*s_:.0f} Z" fill="url(#zhel)" {o(6)}/>'
         + f'<path d="M{x+58*s_:.0f},{y-82*s_:.0f} l{46*s_:.0f},{-38*s_:.0f}'
           f' l{14*s_:.0f},{20*s_:.0f} l{-44*s_:.0f},{36*s_:.0f} Z"'
           f' fill="url(#zhel)" {o(5)}/>'
         + f'<path d="M{x-40*s_:.0f},{y-104*s_:.0f} q{40*s_:.0f},{-58*s_:.0f}'
           f' {80*s_:.0f},0" fill="none" stroke="{ZHELEZ}" stroke-width="{13*s_:.0f}"/>'
         + f'<ellipse cx="{x:.0f}" cy="{y-104*s_:.0f}" rx="{44*s_:.0f}" ry="{13*s_:.0f}"'
           f' fill="#6f767c" {o(4)}/>'
         + f'<path d="M{x-44*s_:.0f},{y-56*s_:.0f} q{10*s_:.0f},{-28*s_:.0f}'
           f' {4*s_:.0f},{-44*s_:.0f}" fill="none" stroke="#fff0c8"'
           f' stroke-width="{9*s_:.0f}" opacity=".5"/>')
    return s


def _kastryulya(x, y, s_=1.0, t=0.0, kryshka=True):
    """Кастрюля: бок с обручем, две ушные ручки, крышка с пуговкой."""
    s = (ten(x, y + 6 * s_, 68 * s_, 12 * s_, .4)
         + f'<path d="M{x-62*s_:.0f},{y-104*s_:.0f} L{x+62*s_:.0f},{y-104*s_:.0f}'
           f' L{x+54*s_:.0f},{y:.0f} L{x-54*s_:.0f},{y:.0f} Z" fill="#b6bcc2" {o(6)}/>'
         + f'<rect x="{x-62*s_:.0f}" y="{y-66*s_:.0f}" width="{124*s_:.0f}"'
           f' height="{12*s_:.0f}" fill="#8b9299" opacity=".8"/>')
    for i in (-1, 1):
        s += (f'<path d="M{x+i*62*s_:.0f},{y-96*s_:.0f} q{i*30*s_:.0f},{4*s_:.0f}'
              f' {i*26*s_:.0f},{26*s_:.0f}" fill="none" stroke="{CHUGUN}"'
              f' stroke-width="{11*s_:.0f}"/>')
    if kryshka:
        s += (f'<ellipse cx="{x:.0f}" cy="{y-104*s_:.0f}" rx="{66*s_:.0f}"'
              f' ry="{15*s_:.0f}" fill="#cfd5da" {o(5)}/>'
              f'<circle cx="{x:.0f}" cy="{y-118*s_:.0f}" r="{11*s_:.0f}"'
              f' fill="{CHUGUN}" {o(3)}/>')
    return s


def _kruzhka(x, y, s_=1.0, ug=0.0, col="#e8eef0", uho=1):
    """Кружка: тулово, ручка кольцом, пояс рисунка, блик."""
    return (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
            f'{ten(x, y + 6 * s_, 34 * s_, 9 * s_, .4)}'
            f'<path d="M{x-34*s_:.0f},{y-78*s_:.0f} L{x+34*s_:.0f},{y-78*s_:.0f}'
            f' L{x+28*s_:.0f},{y:.0f} L{x-28*s_:.0f},{y:.0f} Z" fill="{col}" {o(5)}/>'
            f'<path d="M{x+uho*34*s_:.0f},{y-62*s_:.0f} q{uho*42*s_:.0f},{10*s_:.0f}'
            f' {uho*2*s_:.0f},{44*s_:.0f}" fill="none" stroke="{col}"'
            f' stroke-width="{11*s_:.0f}"/>'
            f'<rect x="{x-32*s_:.0f}" y="{y-54*s_:.0f}" width="{64*s_:.0f}"'
            f' height="{12*s_:.0f}" fill="{TKAN2}" opacity=".7"/>'
            f'<ellipse cx="{x:.0f}" cy="{y-78*s_:.0f}" rx="{34*s_:.0f}" ry="{9*s_:.0f}"'
            f' fill="#cfd8dc" {o(4)}/></g>')


def _banka_krupy(x, y, s_=1.0, col="#d8c08a"):
    """Банка крупы: стекло, крупа до плеча, жестяная крышка, бумажный ярлык
    с волнистой строкой (своих букв в декорации не рисуем)."""
    h2, w2 = 128 * s_, 84 * s_
    return (f'{ten(x, y + 6 * s_, w2 * .5, 10 * s_, .4)}'
            f'<rect x="{x-w2/2:.0f}" y="{y-h2:.0f}" width="{w2:.0f}" height="{h2:.0f}"'
            f' rx="10" fill="url(#stekl)" opacity=".9" {o(5)}/>'
            f'<rect x="{x-w2/2+7:.0f}" y="{y-h2*.62:.0f}" width="{w2-14:.0f}"'
            f' height="{h2*.58:.0f}" rx="7" fill="{col}"/>'
            f'<rect x="{x-w2/2-5:.0f}" y="{y-h2-16:.0f}" width="{w2+10:.0f}"'
            f' height="22" rx="8" fill="{ZHELEZ}" {o(4)}/>'
            f'<rect x="{x-w2*.32:.0f}" y="{y-h2*.46:.0f}" width="{w2*.64:.0f}"'
            f' height="{h2*.26:.0f}" rx="5" fill="#f2ead6" {o(3)}/>'
            f'<path d="M{x-w2*.24:.0f},{y-h2*.34:.0f} q{w2*.12:.0f},{-9:.0f}'
            f' {w2*.24:.0f},0 q{w2*.12:.0f},{9:.0f} {w2*.24:.0f},0" fill="none"'
            f' stroke="#9a8a68" stroke-width="4"/>')


def _polotence(x, y, h_, t, ph=.0, col="#e3ddc6", kryuk=True):
    """Полотенце на крючке: складки, кант по низу, слабое качание."""
    kach = 2.2 * A.w(t, 3.0, ph)
    s = ""
    if kryuk:
        s += (f'<path d="M{x:.0f},{y-26:.0f} q{14:.0f},{-20:.0f} {28:.0f},{-4:.0f}"'
              f' fill="none" stroke="{ZHELEZ}" stroke-width="9"/>')
    s += (f'<g transform="rotate({kach:.1f} {x+14:.0f} {y:.0f})">'
          f'<path d="M{x-6:.0f},{y:.0f} L{x+56:.0f},{y:.0f} L{x+66:.0f},{y+h_:.0f}'
          f' L{x-18:.0f},{y+h_:.0f} Z" fill="{col}" {o(5)}/>')
    for i in range(3):
        s += (f'<line x1="{x+6+i*18:.0f}" y1="{y+10:.0f}" x2="{x+2+i*20:.0f}"'
              f' y2="{y+h_-12:.0f}" stroke="#c9c1a6" stroke-width="5" opacity=".8"/>')
    s += (f'<rect x="{x-16:.0f}" y="{y+h_-28:.0f}" width="82" height="16"'
          f' fill="{TKAN}" opacity=".75"/></g>')
    return s


def _tabyret(x, y, t, h_=150, w_=160):
    """Табурет: толстое сиденье, четыре ножки с проножкой."""
    s = (f'{ten(x, y + 6, w_ * .54, 14, .45)}'
         f'<rect x="{x-w_/2:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="26" rx="9"'
         f' fill="url(#dosk)" {o(6)}/>')
    for i in (-1, 1):
        s += (f'<rect x="{x+i*(w_*.36)-13:.0f}" y="{y-h_+26:.0f}" width="26"'
              f' height="{h_-26:.0f}" rx="8" fill="#4a3522" {o(4)}/>'
              f'<rect x="{x+i*(w_*.22)-11:.0f}" y="{y-h_+30:.0f}" width="22"'
              f' height="{h_-32:.0f}" rx="7" fill="#3f2d1d" {o(3)}/>')
    s += (f'<rect x="{x-w_*.34:.0f}" y="{y-h_*.42:.0f}" width="{w_*.68:.0f}"'
          f' height="16" rx="7" fill="#4a3522" {o(3)}/>')
    return s


def _ugol_pechnoy_utvari(x, y, t, seed=3):
    """Угол у печи: кочерга, ухват и совок стоят в железном ведре-держалке,
    черенки короткие (≤340 px), на стене скоба с рукавицей."""
    s = (f'<path d="M{x-62:.0f},{y:.0f} L{x+62:.0f},{y:.0f} L{x+50:.0f},{y-108:.0f}'
         f' L{x-50:.0f},{y-108:.0f} Z" fill="#59606a" {o(5)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-108:.0f}" rx="50" ry="14" fill="#3d434b" {o(4)}/>')
    # кочерга
    k1 = 1.6 * A.w(t, 2.6, .1)
    s += (f'<g transform="rotate({k1:.1f} {x-20:.0f} {y-60:.0f})">'
          f'<line x1="{x-20:.0f}" y1="{y-60:.0f}" x2="{x-56:.0f}" y2="{y-392:.0f}"'
          f' stroke="{CHUGUN}" stroke-width="15" stroke-linecap="round"/>'
          f'<path d="M{x-20:.0f},{y-60:.0f} q{-30:.0f},{18:.0f} {-58:.0f},{10:.0f}"'
          f' fill="none" stroke="{CHUGUN}" stroke-width="15"/>'
          f'<circle cx="{x-58:.0f}" cy="{y-396:.0f}" r="13" fill="none"'
          f' stroke="{CHUGUN}" stroke-width="8"/></g>')
    # ухват
    k2 = 1.9 * A.w(t, 3.1, .5)
    s += (f'<g transform="rotate({k2:.1f} {x+6:.0f} {y-60:.0f})">'
          f'<line x1="{x+6:.0f}" y1="{y-60:.0f}" x2="{x+30:.0f}" y2="{y-378:.0f}"'
          f' stroke="url(#derev)" stroke-width="17" stroke-linecap="round"/>'
          f'<path d="M{x+14:.0f},{y-330:.0f} q{-36:.0f},{-54:.0f} {4:.0f},{-74:.0f}'
          f' q{44:.0f},{18:.0f} {40:.0f},{74:.0f}" fill="none" stroke="{ZHELEZ}"'
          f' stroke-width="14"/></g>')
    # совок
    s += (f'<g transform="rotate({-4 + 1.4 * A.w(t, 2.2, .8):.1f} {x+44:.0f} {y-70:.0f})">'
          f'<line x1="{x+44:.0f}" y1="{y-70:.0f}" x2="{x+78:.0f}" y2="{y-300:.0f}"'
          f' stroke="url(#derev)" stroke-width="14" stroke-linecap="round"/>'
          f'<path d="M{x+30:.0f},{y-66:.0f} L{x+96:.0f},{y-54:.0f} L{x+88:.0f},{y+4:.0f}'
          f' L{x+22:.0f},{y-8:.0f} Z" fill="#6e757c" {o(5)}/></g>')
    # скоба с рукавицей на стене
    s += (f'<rect x="{x+128:.0f}" y="{y-382:.0f}" width="34" height="18" rx="7"'
          f' fill="{ZHELEZ}" {o(3)}/>'
          f'<path d="M{x+136:.0f},{y-364:.0f} q{-22:.0f},{56:.0f} {4:.0f},{96:.0f}'
          f' q{34:.0f},{14:.0f} {44:.0f},{-18:.0f} q{10:.0f},{-54:.0f} {-10:.0f},{-78:.0f} Z"'
          f' fill="#8c6a4a" {o(4)}/>'
          f'<path d="M{x+178:.0f},{y-320:.0f} q{26:.0f},{12:.0f} {16:.0f},{40:.0f}"'
          f' fill="none" stroke="#8c6a4a" stroke-width="16"/>')
    return s


def _kreslo(x, y, w_, t, h_=430, col="#6c5a4a"):
    """Мягкое кресло: спинка валиком, два подлокотника, подушка на сиденье,
    короткие ножки и тень под ними."""
    s = (f'{ten(x, y + 8, w_ * .52, 20, .5)}'
         f'<path d="M{x-w_/2:.0f},{y-h_*.42:.0f} q0,{-h_*.62:.0f} {w_*.5:.0f},{-h_*.58:.0f}'
         f' q{w_*.5:.0f},{-h_*.04:.0f} {w_*.5:.0f},{h_*.58:.0f} Z"'
         f' fill="{col}" {o(7)}/>'
         f'<rect x="{x-w_/2:.0f}" y="{y-h_*.46:.0f}" width="{w_:.0f}"'
         f' height="{h_*.30:.0f}" rx="22" fill="#7d6a58" {o(6)}/>')
    for i in (-1, 1):
        s += (f'<path d="M{x+i*w_*.5:.0f},{y-h_*.46:.0f} q{i*w_*.10:.0f},{-h_*.22:.0f}'
              f' {-i*w_*.02:.0f},{-h_*.30:.0f} q{-i*w_*.14:.0f},{-h_*.04:.0f}'
              f' {-i*w_*.16:.0f},{h_*.14:.0f} Z" fill="#7d6a58" {o(5)}/>'
              f'<rect x="{x+i*w_*.42-26:.0f}" y="{y-h_*.14:.0f}" width="34"'
              f' height="{h_*.16:.0f}" rx="10" fill="#4a3c30" {o(4)}/>')
    s += (f'<path d="M{x-w_*.40:.0f},{y-h_*.30:.0f} q{w_*.40:.0f},{-h_*.14:.0f}'
          f' {w_*.80:.0f},0 q{-w_*.06:.0f},{h_*.12:.0f} {-w_*.80:.0f},0 Z"'
          f' fill="#8c7260" {o(5)}/>')
    for i in range(4):
        s += (f'<line x1="{x-w_*.30+i*w_*.20:.0f}" y1="{y-h_*.86:.0f}"'
              f' x2="{x-w_*.30+i*w_*.20:.0f}" y2="{y-h_*.48:.0f}" stroke="#5a4a3c"'
              f' stroke-width="7" opacity=".7"/>')
    return s


def _stolik(x, y, w_, t, h_=190, kruzhev=False):
    """Журнальный столик: столешница, точёные ножки, кружевная салфетка."""
    s = (f'{ten(x, y + 6, w_ * .5, 16, .45)}'
         f'<rect x="{x-w_/2:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="24" rx="10"'
         f' fill="url(#derev)" {o(6)}/>')
    for i in (-1, 1):
        s += (f'<rect x="{x+i*w_*.38-12:.0f}" y="{y-h_+24:.0f}" width="24"'
              f' height="{h_-24:.0f}" rx="9" fill="#5b4428" {o(4)}/>'
              f'<ellipse cx="{x+i*w_*.38:.0f}" cy="{y-h_*.52:.0f}" rx="22" ry="14"'
              f' fill="#6a5030" {o(3)}/>')
    if kruzhev:
        s += (f'<path d="M{x-w_*.42:.0f},{y-h_:.0f} h{w_*.84:.0f} l-10,26 h{-w_*.84+20:.0f} Z"'
              f' fill="#f4efe0" {o(4)}/>')
        for i in range(9):
            s += (f'<circle cx="{x-w_*.40+i*w_*.10:.0f}" cy="{y-h_+30:.0f}" r="11"'
                  f' fill="none" stroke="#e2d8bf" stroke-width="4"/>')
    return s


def _pirog(x, y, s_=1.0, t=0.0, nadrez=True):
    """Пирог на блюде: корж, защип по краю, косые надрезы, блюдо с каймой."""
    s = (f'{ten(x, y + 10 * s_, 118 * s_, 16 * s_, .45)}'
         f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{124*s_:.0f}" ry="{30*s_:.0f}"'
         f' fill="#eae2cf" {o(5)}/>'
         f'<path d="M{x-104*s_:.0f},{y-6*s_:.0f} q{14*s_:.0f},{-66*s_:.0f}'
         f' {104*s_:.0f},{-64*s_:.0f} q{90*s_:.0f},{-2*s_:.0f} {104*s_:.0f},{64*s_:.0f} Z"'
         f' fill="url(#med)" {o(6)}/>')
    if nadrez:
        for i in range(4):
            s += (f'<path d="M{x-66*s_+i*44*s_:.0f},{y-18*s_:.0f}'
                  f' l{26*s_:.0f},{-34*s_:.0f}" fill="none" stroke="#8a5a22"'
                  f' stroke-width="{7*s_:.0f}" opacity=".8"/>')
    for i in range(7):
        s += (f'<circle cx="{x-96*s_+i*32*s_:.0f}" cy="{y-10*s_:.0f}" r="{11*s_:.0f}"'
              f' fill="#c99a52" {o(2)}/>')
    s += (f'<path d="M{x-70*s_:.0f},{y-54*s_:.0f} q{30*s_:.0f},{-14*s_:.0f}'
          f' {62*s_:.0f},{-6*s_:.0f}" fill="none" stroke="#fff0c8"'
          f' stroke-width="{8*s_:.0f}" opacity="{.3+.3*abs(A.w(t,2.6)):.2f}"/>')
    return s


def _vaza_s_yablokami(x, y, s_=1.0, t=0.0, seed=9, n=6):
    """Ваза-фруктовница на ножке и яблоки горкой: у каждого черешок и блик."""
    rnd = random.Random(seed)
    s = (f'{ten(x, y + 8 * s_, 80 * s_, 13 * s_, .4)}'
         f'<path d="M{x-28*s_:.0f},{y:.0f} L{x+28*s_:.0f},{y:.0f}'
         f' L{x+16*s_:.0f},{y-44*s_:.0f} L{x-16*s_:.0f},{y-44*s_:.0f} Z"'
         f' fill="url(#stekl)" opacity=".9" {o(4)}/>'
         f'<path d="M{x-92*s_:.0f},{y-48*s_:.0f} q{92*s_:.0f},{58*s_:.0f}'
         f' {184*s_:.0f},0 Z" fill="url(#stekl)" opacity=".85" {o(5)}/>')
    for i in range(n):
        ax = x + rnd.uniform(-72, 72) * s_
        ay = y - 58 * s_ - abs(rnd.uniform(0, 42)) * s_
        rr = rnd.uniform(26, 34) * s_
        col = "#b8352c" if i % 2 else "#c9772c"
        s += (f'<circle cx="{ax:.0f}" cy="{ay:.0f}" r="{rr:.0f}" fill="{col}" {o(4)}/>'
              f'<path d="M{ax+2*s_:.0f},{ay-rr:.0f} q{6*s_:.0f},{-16*s_:.0f}'
              f' {18*s_:.0f},{-18*s_:.0f}" fill="none" stroke="#4e3418"'
              f' stroke-width="{5*s_:.0f}"/>'
              f'<circle cx="{ax-rr*.32:.0f}" cy="{ay-rr*.34:.0f}" r="{rr*.22:.0f}"'
              f' fill="#ffe6c8" opacity=".55"/>')
    return s


def _servant_hrustal(x, y, w_, h_, t, seed=3):
    """Сервант шестидесятых: цоколь, застеклённая верхняя часть, рюмки и
    вазы за стеклом, нижние глухие дверцы с латунными ручками."""
    rnd = random.Random(seed)
    s = (f'{ten(x + w_ / 2, y + 10, w_ * .46, 18, .45)}'
         f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}" rx="10"'
         f' fill="url(#derev)" {o(7)}/>'
         f'<rect x="{x-14:.0f}" y="{y-h_-22:.0f}" width="{w_+28:.0f}" height="26" rx="9"'
         f' fill="#6a5030" {o(5)}/>')
    st_y = y - h_ + 40
    st_h = h_ * .46
    s += (f'<rect x="{x+20:.0f}" y="{st_y:.0f}" width="{w_-40:.0f}" height="{st_h:.0f}"'
          f' rx="8" fill="url(#stekl)" opacity=".7" {o(5)}/>')
    for p in range(2):
        py = st_y + st_h * (.52 + .44 * p)
        s += (f'<rect x="{x+22:.0f}" y="{py:.0f}" width="{w_-44:.0f}" height="12"'
              f' fill="#5b4428" opacity=".85"/>')
        for i in range(6):
            gx = x + 54 + i * (w_ - 110) / 5.0
            hh = rnd.uniform(44, 76)
            bl = .35 + .4 * abs(A.w(t, 2.4 + i * .3, i * .2))
            s += (f'<path d="M{gx-18:.0f},{py:.0f} L{gx+18:.0f},{py:.0f}'
                  f' L{gx+12:.0f},{py-hh*.52:.0f} L{gx+16:.0f},{py-hh:.0f}'
                  f' L{gx-16:.0f},{py-hh:.0f} L{gx-12:.0f},{py-hh*.52:.0f} Z"'
                  f' fill="#dbeaf4" opacity=".9" {o(3)}/>'
                  f'<circle cx="{gx-6:.0f}" cy="{py-hh*.8:.0f}" r="5"'
                  f' fill="#ffffff" opacity="{bl:.2f}"/>')
    s += (f'<line x1="{x+w_/2:.0f}" y1="{st_y:.0f}" x2="{x+w_/2:.0f}"'
          f' y2="{st_y+st_h:.0f}" stroke="#4a3522" stroke-width="10"/>')
    for i in (0, 1):
        dx = x + 24 + i * (w_ - 48) / 2.0
        s += (f'<rect x="{dx:.0f}" y="{y-h_*.44:.0f}" width="{(w_-66)/2:.0f}"'
              f' height="{h_*.36:.0f}" rx="8" fill="#8a6a44" {o(5)}/>'
              f'<rect x="{dx+18:.0f}" y="{y-h_*.40:.0f}" width="{(w_-66)/2-36:.0f}"'
              f' height="{h_*.28:.0f}" rx="6" fill="#7b5c38" opacity=".8"/>'
              f'<rect x="{dx+(w_-66)/4-22:.0f}" y="{y-h_*.26:.0f}" width="44"'
              f' height="14" rx="7" fill="url(#zol)" {o(3)}/>')
    return s


def _venskiy_stul(x, y, h_, t, ug=0.0, sidit=False):
    """Венский стул: круглое сиденье, гнутая спинка с кольцом, четыре
    расходящиеся ножки и проножка."""
    sy = y - h_ * .52
    s = (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
         f'{ten(x, y + 6, h_ * .22, 13, .45)}'
         f'<ellipse cx="{x:.0f}" cy="{sy:.0f}" rx="{h_*.24:.0f}" ry="{h_*.072:.0f}"'
         f' fill="url(#derev)" {o(6)}/>'
         f'<ellipse cx="{x:.0f}" cy="{sy-h_*.016:.0f}" rx="{h_*.20:.0f}"'
         f' ry="{h_*.052:.0f}" fill="#8a6a44" opacity=".8"/>')
    for i, dx in enumerate((-.20, -.08, .08, .20)):
        s += (f'<line x1="{x+h_*dx:.0f}" y1="{sy+h_*.03:.0f}"'
              f' x2="{x+h_*dx*1.5:.0f}" y2="{y:.0f}" stroke="#5b4428"'
              f' stroke-width="{13 if abs(dx) > .1 else 10}" stroke-linecap="round"/>')
    s += (f'<path d="M{x-h_*.26:.0f},{sy-h_*.02:.0f} q{h_*.02:.0f},{-h_*.46:.0f}'
          f' {h_*.26:.0f},{-h_*.48:.0f} q{h_*.24:.0f},{h_*.02:.0f}'
          f' {h_*.26:.0f},{h_*.48:.0f}" fill="none" stroke="#6a5030"'
          f' stroke-width="16"/>'
          f'<ellipse cx="{x:.0f}" cy="{sy-h_*.26:.0f}" rx="{h_*.13:.0f}"'
          f' ry="{h_*.14:.0f}" fill="none" stroke="#6a5030" stroke-width="12"/>'
          f'<path d="M{x-h_*.22:.0f},{y-h_*.18:.0f} q{h_*.22:.0f},{h_*.05:.0f}'
          f' {h_*.44:.0f},0" fill="none" stroke="#5b4428" stroke-width="9"/></g>')
    return s


def _supnica(x, y, s_=1.0, t=0.0):
    """Супница: пузатое тулово, две ручки, крышка с хватком, золотая кайма."""
    return (f'{ten(x, y + 8 * s_, 96 * s_, 14 * s_, .45)}'
            f'<path d="M{x-96*s_:.0f},{y-54*s_:.0f} q{18*s_:.0f},{58*s_:.0f}'
            f' {96*s_:.0f},{56*s_:.0f} q{78*s_:.0f},{2*s_:.0f} {96*s_:.0f},{-56*s_:.0f} Z"'
            f' fill="#f0ece0" {o(6)}/>'
            f'<ellipse cx="{x:.0f}" cy="{y-56*s_:.0f}" rx="{98*s_:.0f}"'
            f' ry="{20*s_:.0f}" fill="#e4dfd0" {o(5)}/>'
            f'<path d="M{x-98*s_:.0f},{y-60*s_:.0f} q{98*s_:.0f},{-56*s_:.0f}'
            f' {196*s_:.0f},0 q{-98*s_:.0f},{26*s_:.0f} {-196*s_:.0f},0 Z"'
            f' fill="#f6f2e8" {o(5)}/>'
            f'<circle cx="{x:.0f}" cy="{y-96*s_:.0f}" r="{15*s_:.0f}" fill="url(#zol)"'
            f' {o(4)}/>'
            f'<path d="M{x-96*s_:.0f},{y-44*s_:.0f} q{-36*s_:.0f},{10*s_:.0f}'
            f' {-28*s_:.0f},{34*s_:.0f}" fill="none" stroke="#f0ece0"'
            f' stroke-width="{15*s_:.0f}"/>'
            f'<path d="M{x+96*s_:.0f},{y-44*s_:.0f} q{36*s_:.0f},{10*s_:.0f}'
            f' {28*s_:.0f},{34*s_:.0f}" fill="none" stroke="#f0ece0"'
            f' stroke-width="{15*s_:.0f}"/>'
            f'<path d="M{x-88*s_:.0f},{y-28*s_:.0f} q{88*s_:.0f},{22*s_:.0f}'
            f' {176*s_:.0f},0" fill="none" stroke="url(#zol)" stroke-width="{6*s_:.0f}"/>')


def _kover_na_stene(x, y, w_, h_, t, seed=5):
    """Ковёр на стене: кайма, медальон в середине, бахрома по низу."""
    rnd = random.Random(seed)
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}" rx="8"'
         f' fill="#7a2f33" {o(6)}/>'
         f'<rect x="{x+26:.0f}" y="{y+26:.0f}" width="{w_-52:.0f}" height="{h_-52:.0f}"'
         f' rx="6" fill="none" stroke="#c9a05a" stroke-width="10"/>'
         f'<path d="M{x+w_*.5:.0f},{y+h_*.22:.0f} L{x+w_*.76:.0f},{y+h_*.5:.0f}'
         f' L{x+w_*.5:.0f},{y+h_*.78:.0f} L{x+w_*.24:.0f},{y+h_*.5:.0f} Z"'
         f' fill="#9c4b40" stroke="#e0c084" stroke-width="7"/>')
    for i in range(6):
        px = x + w_ * (.18 + .13 * i)
        s += (f'<circle cx="{px:.0f}" cy="{y+h_*(.36 if i % 2 else .64):.0f}" r="18"'
              f' fill="#d8b070" opacity=".8"/>')
    for i in range(int(w_ / 26)):
        fx = x + 10 + i * 26
        s += (f'<line x1="{fx:.0f}" y1="{y+h_:.0f}" x2="{fx+2*A.w(t,4.0,i*.1):.0f}"'
              f' y2="{y+h_+24:.0f}" stroke="#d8c08a" stroke-width="5" opacity=".85"/>')
    return s


def _pismennyy_stol(x, y, w_, t, h_=250):
    """Письменный стол конторы: толстая столешница с сукном, два тумбовых
    ящика с ручками, царга и чернильный развод на сукне."""
    s = (f'{ten(x + w_ / 2, y + 10, w_ * .46, 20, .5)}'
         f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="38" rx="9"'
         f' fill="url(#derev)" {o(7)}/>'
         f'<rect x="{x+16:.0f}" y="{y-h_+8:.0f}" width="{w_-32:.0f}" height="22" rx="6"'
         f' fill="#2f4a3c" opacity=".9"/>'
         f'<ellipse cx="{x+w_*.72:.0f}" cy="{y-h_+20:.0f}" rx="56" ry="9"'
         f' fill="#1d3028" opacity=".7"/>')
    for i in (0, 1):
        bx = x + (26 if i == 0 else w_ - 250)
        s += (f'<rect x="{bx:.0f}" y="{y-h_+38:.0f}" width="224"'
              f' height="{h_-38:.0f}" rx="8" fill="#7b5c38" {o(5)}/>')
        for k in range(2):
            s += (f'<rect x="{bx+16:.0f}" y="{y-h_+58+k*86:.0f}" width="192"'
                  f' height="72" rx="6" fill="#8a6a44" {o(4)}/>'
                  f'<rect x="{bx+86:.0f}" y="{y-h_+88+k*86:.0f}" width="52"'
                  f' height="14" rx="7" fill="url(#zhel)" {o(3)}/>')
    s += (f'<rect x="{x+250:.0f}" y="{y-h_+44:.0f}" width="{w_-500:.0f}" height="18"'
          f' rx="7" fill="#6a5030" {o(4)}/>')
    return s


def _chernilnica(x, y, s_=1.0, t=0.0):
    """Чернильница: стеклянный куб с чернилами, бронзовая крышка на шарнире,
    блик на граненом боку."""
    w2, h2 = 76 * s_, 70 * s_
    return (f'{ten(x, y + 6 * s_, w2 * .56, 10 * s_, .45)}'
            f'<rect x="{x-w2/2:.0f}" y="{y-h2:.0f}" width="{w2:.0f}" height="{h2:.0f}"'
            f' rx="8" fill="url(#stekl)" opacity=".92" {o(5)}/>'
            f'<rect x="{x-w2/2+6:.0f}" y="{y-h2*.52:.0f}" width="{w2-12:.0f}"'
            f' height="{h2*.46:.0f}" rx="5" fill="#1b2434"/>'
            f'<ellipse cx="{x:.0f}" cy="{y-h2:.0f}" rx="{w2*.42:.0f}" ry="{9*s_:.0f}"'
            f' fill="#8a6a3c" {o(4)}/>'
            f'<path d="M{x-w2*.42:.0f},{y-h2-4*s_:.0f} q{w2*.42:.0f},{-26*s_:.0f}'
            f' {w2*.84:.0f},{-2*s_:.0f} l0,{10*s_:.0f} q{-w2*.42:.0f},{-14*s_:.0f}'
            f' {-w2*.84:.0f},{2*s_:.0f} Z" fill="url(#zhel)" {o(4)}/>'
            f'<line x1="{x-w2*.28:.0f}" y1="{y-h2*.86:.0f}" x2="{x-w2*.28:.0f}"'
            f' y2="{y-h2*.12:.0f}" stroke="#eaf4ff" stroke-width="{5*s_:.0f}"'
            f' opacity="{.3+.25*abs(A.w(t,2.8)):.2f}"/>')


def _pero_pisma(ex, ey, t, s_=1.0, ug=-28.0, kaplya=.0):
    """Гусиное перо: стержень, бородка с прорезями, металлический кончик и
    набухающая капля чернил на острие."""
    s = (f'<g transform="rotate({ug:.1f} {ex:.0f} {ey:.0f})">'
         f'<path d="M{ex:.0f},{ey:.0f} L{ex-16*s_:.0f},{ey-176*s_:.0f}'
         f' L{ex+6*s_:.0f},{ey-184*s_:.0f} L{ex+14*s_:.0f},{ey-8*s_:.0f} Z"'
         f' fill="#efe8da" {o(4)}/>')
    for i in range(7):
        yy = ey - 44 * s_ - i * 20 * s_
        s += (f'<line x1="{ex-12*s_+i*s_:.0f}" y1="{yy:.0f}"'
              f' x2="{ex-54*s_+i*3*s_:.0f}" y2="{yy-16*s_:.0f}" stroke="#d8cfbd"'
              f' stroke-width="{6*s_:.0f}" opacity=".9"/>'
              f'<line x1="{ex+12*s_:.0f}" y1="{yy:.0f}" x2="{ex+48*s_:.0f}"'
              f' y2="{yy-14*s_:.0f}" stroke="#e6ded0" stroke-width="{6*s_:.0f}"'
              f' opacity=".85"/>')
    s += (f'<path d="M{ex-8*s_:.0f},{ey-16*s_:.0f} L{ex+10*s_:.0f},{ey-18*s_:.0f}'
          f' L{ex+2*s_:.0f},{ey+16*s_:.0f} Z" fill="{ZHELEZ}" {o(3)}/></g>')
    if kaplya > 0:
        s += (f'<ellipse cx="{ex+4*s_:.0f}" cy="{ey+22*s_+10*kaplya:.0f}"'
              f' rx="{(5+7*kaplya)*s_:.0f}" ry="{(7+11*kaplya)*s_:.0f}"'
              f' fill="#1b2434" {o(2)}/>')
    return s


def _list_bumagi(x, y, w_, h_, t, ug=0.0, stroki=5, pustaya_stroka=True):
    """Лист бумаги: загнутый угол, волнистые строки (букв не рисуем!),
    пустая строка под подпись внизу и тень под листом."""
    s = (f'<g transform="rotate({ug:.1f} {x+w_/2:.0f} {y+h_/2:.0f})">'
         f'{ten(x + w_ / 2, y + h_ + 8, w_ * .46, 12, .4)}'
         f'<path d="M{x:.0f},{y:.0f} L{x+w_-34:.0f},{y:.0f} L{x+w_:.0f},{y+34:.0f}'
         f' L{x+w_:.0f},{y+h_:.0f} L{x:.0f},{y+h_:.0f} Z" fill="#f4efe0" {o(5)}/>'
         f'<path d="M{x+w_-34:.0f},{y:.0f} L{x+w_:.0f},{y+34:.0f} L{x+w_-34:.0f},{y+34:.0f} Z"'
         f' fill="#ddd5c2" {o(3)}/>')
    for i in range(stroki):
        yy = y + h_ * .22 + i * (h_ * .50 / max(1, stroki))
        dl = w_ * (.66 if i % 2 else .78)
        s += (f'<path d="M{x+w_*.10:.0f},{yy:.0f} q{dl*.25:.0f},{-7:.0f} {dl*.5:.0f},0'
              f' q{dl*.25:.0f},{7:.0f} {dl*.5:.0f},0" fill="none" stroke="#6b6354"'
              f' stroke-width="6" opacity=".75"/>')
    if pustaya_stroka:
        mig = .5 + .5 * abs(A.w(t, 1.6))
        s += (f'<line x1="{x+w_*.12:.0f}" y1="{y+h_*.84:.0f}" x2="{x+w_*.66:.0f}"'
              f' y2="{y+h_*.84:.0f}" stroke="#3f4a58" stroke-width="7"'
              f' opacity="{.4+.5*mig:.2f}"/>')
    return s + "</g>"


def _ochki(x, y, s_=1.0, t=0.0):
    """Очки: два стекла в тонкой оправе, переносица, заушники и блик."""
    bl = .3 + .4 * abs(A.w(t, 2.2))
    s = ""
    for i in (-1, 1):
        s += (f'<ellipse cx="{x+i*44*s_:.0f}" cy="{y:.0f}" rx="{38*s_:.0f}"'
              f' ry="{30*s_:.0f}" fill="#cfe0ea" opacity=".5" stroke="#8a6a3c"'
              f' stroke-width="{7*s_:.0f}"/>'
              f'<path d="M{x+i*76*s_:.0f},{y-12*s_:.0f} q{i*40*s_:.0f},{-10*s_:.0f}'
              f' {i*52*s_:.0f},{10*s_:.0f}" fill="none" stroke="#8a6a3c"'
              f' stroke-width="{6*s_:.0f}"/>')
    s += (f'<path d="M{x-8*s_:.0f},{y-6*s_:.0f} q{8*s_:.0f},{-12*s_:.0f}'
          f' {16*s_:.0f},0" fill="none" stroke="#8a6a3c" stroke-width="{6*s_:.0f}"/>'
          f'<line x1="{x-56*s_:.0f}" y1="{y-14*s_:.0f}" x2="{x-34*s_:.0f}"'
          f' y2="{y+10*s_:.0f}" stroke="#ffffff" stroke-width="{5*s_:.0f}"'
          f' opacity="{bl:.2f}"/>')
    return s


def _klyaksa_grust(x, y, s_=1.0, t=0.0, ph=.0):
    """Клякса-несчастье: серая капля с подтёками, грустные глаза и рот
    дугой вниз. Шевелится, как живая."""
    dr = 1.0 + .07 * A.w(t, 1.3, ph)
    s = (f'<g transform="translate({x:.0f} {y:.0f}) scale({dr:.3f})'
         f' translate({-x:.0f} {-y:.0f})">'
         f'<path d="M{x-44*s_:.0f},{y:.0f} q{-10*s_:.0f},{-48*s_:.0f} {30*s_:.0f},{-58*s_:.0f}'
         f' q{44*s_:.0f},{-10*s_:.0f} {56*s_:.0f},{26*s_:.0f}'
         f' q{14*s_:.0f},{40*s_:.0f} {-16*s_:.0f},{50*s_:.0f}'
         f' q{-36*s_:.0f},{10*s_:.0f} {-70*s_:.0f},{-18*s_:.0f} Z"'
         f' fill="#6f7680" {o(4)}/>')
    for i in range(3):
        s += (f'<path d="M{x-28*s_+i*28*s_:.0f},{y+6*s_:.0f} q{4*s_:.0f},{22*s_:.0f}'
              f' {-2*s_:.0f},{34*s_:.0f}" fill="none" stroke="#6f7680"'
              f' stroke-width="{11*s_:.0f}" stroke-linecap="round"/>')
    for i in (-1, 1):
        s += (f'<ellipse cx="{x+i*17*s_:.0f}" cy="{y-26*s_:.0f}" rx="{9*s_:.0f}"'
              f' ry="{11*s_:.0f}" fill="#f2f6fa"/>'
              f'<circle cx="{x+i*17*s_:.0f}" cy="{y-22*s_:.0f}" r="{5*s_:.0f}"'
              f' fill="#23282f"/>'
              f'<path d="M{x+i*28*s_:.0f},{y-42*s_:.0f} q{-i*11*s_:.0f},{-7*s_:.0f}'
              f' {-i*22*s_:.0f},{2*s_:.0f}" fill="none" stroke="#3a4049"'
              f' stroke-width="{5*s_:.0f}"/>')
    s += (f'<path d="M{x-14*s_:.0f},{y+2*s_:.0f} q{14*s_:.0f},{-14*s_:.0f}'
          f' {28*s_:.0f},0" fill="none" stroke="#3a4049" stroke-width="{6*s_:.0f}"'
          f' stroke-linecap="round"/></g>')
    return s


def _polki_otkrytye(x, y, w_, t, seed=11, n=3, ruchki_vlevo=True, sdvig=.0):
    """Открытые кухонные полки: три доски на кронштейнах, чашки на крючках
    ручками в одну сторону, тарелки по росту ребром, банки крупы."""
    rnd = random.Random(seed)
    s = ""
    for p in range(n):
        py = y + p * 170
        s += (f'<rect x="{x:.0f}" y="{py:.0f}" width="{w_:.0f}" height="22" rx="7"'
              f' fill="url(#dosk)" {o(5)}/>')
        for k in (x + 60, x + w_ - 90):
            s += (f'<path d="M{k:.0f},{py+22:.0f} l26,38 l-26,0 Z" fill="{ZHELEZ}" {o(3)}/>')
        if p == 0:
            for i in range(5):
                cx = x + 90 + i * (w_ - 180) / 4.0
                sg = -1 if ruchki_vlevo else 1
                sg = sg if i % 2 or sdvig < .5 else -sg
                s += _kruzhka(cx, py - 6, .92, 0, "#eceff0", sg)
        elif p == 1:
            for i in range(6):
                r = 54 + i * 11
                s += (f'<ellipse cx="{x+80+i*(w_-170)/5.0:.0f}" cy="{py-r*.5:.0f}"'
                      f' rx="{r*.28:.0f}" ry="{r*.5:.0f}" fill="#e7edf0" {o(4)}/>'
                      f'<ellipse cx="{x+80+i*(w_-170)/5.0:.0f}" cy="{py-r*.5:.0f}"'
                      f' rx="{r*.12:.0f}" ry="{r*.34:.0f}" fill="#cfd8dc" opacity=".8"/>')
        else:
            for i in range(4):
                s += _banka_krupy(x + 110 + i * (w_ - 220) / 3.0, py - 6,
                                  rnd.uniform(.86, 1.04),
                                  ["#d8c08a", "#b8a068", "#e0d2a8", "#c0a878"][i])
    return s


def _okno_razdachi(x, y, w_, h_, t):
    """Окно-раздача между кухней и комнатой: широкий подоконник-полка,
    наличник в четверть, два крюка створок и блик по верхней кромке."""
    return (f'<rect x="{x-26:.0f}" y="{y-26:.0f}" width="{w_+52:.0f}"'
            f' height="{h_+52:.0f}" rx="10" fill="none" stroke="#8a7254"'
            f' stroke-width="26"/>'
            f'<rect x="{x-54:.0f}" y="{y+h_-6:.0f}" width="{w_+108:.0f}" height="40"'
            f' rx="10" fill="url(#dosk)" {o(6)}/>'
            f'<rect x="{x-40:.0f}" y="{y-48:.0f}" width="{w_+80:.0f}" height="30"'
            f' rx="9" fill="#9c8464" {o(5)}/>'
            f'<path d="M{x+20:.0f},{y-4:.0f} L{x+w_-20:.0f},{y-4:.0f}" fill="none"'
            f' stroke="#eaf4ff" stroke-width="7"'
            f' opacity="{.25+.2*abs(A.w(t,3.2)):.2f}"/>'
            f'<circle cx="{x-30:.0f}" cy="{y+h_*.5:.0f}" r="11" fill="{ZHELEZ}" {o(3)}/>'
            f'<circle cx="{x+w_+30:.0f}" cy="{y+h_*.5:.0f}" r="11" fill="{ZHELEZ}" {o(3)}/>')


def _polovik(x, y, w_, h_, col=RUSH, pol=KRAS):
    """Половик-дорожка: перспективная трапеция, две цветные полосы, бахрома."""
    s = (f'<path d="M{x:.0f},{y:.0f} L{x+w_:.0f},{y:.0f} L{x+w_+h_*.3:.0f},{y+h_:.0f}'
         f' L{x-h_*.3:.0f},{y+h_:.0f} Z" fill="{col}" {o(5)}/>'
         f'<path d="M{x+16:.0f},{y+h_*.34:.0f} L{x+w_-16:.0f},{y+h_*.34:.0f}"'
         f' stroke="{pol}" stroke-width="12" opacity=".7"/>'
         f'<path d="M{x+2:.0f},{y+h_*.70:.0f} L{x+w_-2:.0f},{y+h_*.70:.0f}"'
         f' stroke="{TKAN2}" stroke-width="9" opacity=".6"/>')
    for i in range(int(w_ / 44)):
        s += (f'<line x1="{x-h_*.3+i*48:.0f}" y1="{y+h_:.0f}"'
              f' x2="{x-h_*.3+i*48-6:.0f}" y2="{y+h_+20:.0f}" stroke="#d8c8a8"'
              f' stroke-width="5" opacity=".8"/>')
    return s


def _knizhnaya_polka(x, y, w_, t, seed=7, polok=2, step=180):
    """Полка с книгами: корешки разной высоты и толщины, пара книг лежит
    плашмя, одна наклонена. Держит средний план там, где стена пустая."""
    rnd = random.Random(seed)
    cols = ["#7a3a32", "#3f5c7a", "#4a6a48", "#8a6a2c", "#5a4a62", "#9c6a3c"]
    s = ""
    for p in range(polok):
        py = y + p * step
        s += (f'<rect x="{x:.0f}" y="{py:.0f}" width="{w_:.0f}" height="22" rx="7"'
              f' fill="url(#dosk)" {o(5)}/>'
              f'<rect x="{x+10:.0f}" y="{py+22:.0f}" width="20" height="30"'
              f' fill="#4a3522" {o(3)}/>'
              f'<rect x="{x+w_-30:.0f}" y="{py+22:.0f}" width="20" height="30"'
              f' fill="#4a3522" {o(3)}/>')
        bx = x + 18
        while bx < x + w_ - 90:
            tol = rnd.uniform(26, 50)
            hh = rnd.uniform(118, 168)
            nak = rnd.uniform(-9, 9) if rnd.random() < .22 else 0.0
            col = cols[rnd.randrange(len(cols))]
            s += (f'<g transform="rotate({nak:.1f} {bx:.0f} {py:.0f})">'
                  f'<rect x="{bx:.0f}" y="{py-hh:.0f}" width="{tol:.0f}"'
                  f' height="{hh:.0f}" rx="4" fill="{col}" {o(4)}/>'
                  f'<rect x="{bx+4:.0f}" y="{py-hh*.82:.0f}" width="{tol-8:.0f}"'
                  f' height="12" fill="#e8d8a8" opacity=".7"/>'
                  f'<rect x="{bx+4:.0f}" y="{py-hh*.34:.0f}" width="{tol-8:.0f}"'
                  f' height="8" fill="#e8d8a8" opacity=".5"/></g>')
            bx += tol + 6
        s += (f'<rect x="{x+w_-96:.0f}" y="{py-54:.0f}" width="86" height="26" rx="5"'
              f' fill="{cols[(seed + p) % len(cols)]}" {o(4)}/>'
              f'<rect x="{x+w_-92:.0f}" y="{py-28:.0f}" width="80" height="24" rx="5"'
              f' fill="{cols[(seed + p + 2) % len(cols)]}" {o(4)}/>')
    return s


def _ramki_na_stene(x, y, w_, t, seed=5, n=4):
    """Рамки на стене: фотографии и вышивки за стеклом, у каждой паспарту,
    блик по углу и гвоздик. Вместо лиц — предметы (афиши рисованные)."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        rw = rnd.uniform(150, 230)
        rh = rw * rnd.uniform(.62, .86)
        rx_ = x + i * (w_ / max(1, n)) + rnd.uniform(-10, 10)
        ry_ = y + (0 if i % 2 else 54)
        ug = rnd.uniform(-3, 3)
        s += (f'<g transform="rotate({ug:.1f} {rx_:.0f} {ry_:.0f})">'
              f'<rect x="{rx_:.0f}" y="{ry_:.0f}" width="{rw:.0f}" height="{rh:.0f}"'
              f' rx="6" fill="#6a5030" {o(5)}/>'
              f'<rect x="{rx_+16:.0f}" y="{ry_+16:.0f}" width="{rw-32:.0f}"'
              f' height="{rh-32:.0f}" rx="4" fill="#efe8d6" {o(3)}/>')
        if i % 2:
            s += (f'<path d="M{rx_+rw*.26:.0f},{ry_+rh*.74:.0f}'
                  f' q{rw*.24:.0f},{-rh*.46:.0f} {rw*.48:.0f},0 Z"'
                  f' fill="#8a9a58" opacity=".85"/>')
        else:
            s += (f'<circle cx="{rx_+rw*.5:.0f}" cy="{ry_+rh*.5:.0f}"'
                  f' r="{rh*.22:.0f}" fill="#b9a071" opacity=".85"/>')
        s += (f'<path d="M{rx_+18:.0f},{ry_+rh-20:.0f} L{rx_+rw*.5:.0f},{ry_+20:.0f}'
              f' L{rx_+rw*.66:.0f},{ry_+20:.0f} L{rx_+rw*.32:.0f},{ry_+rh-20:.0f} Z"'
              f' fill="#ffffff" opacity="{.10+.10*abs(A.w(t,3.0,i*.2)):.2f}"/>'
              f'<circle cx="{rx_+rw*.5:.0f}" cy="{ry_-10:.0f}" r="7"'
              f' fill="{ZHELEZ}"/></g>')
    return s


def _sushilka_posudy(x, y, w_, t, seed=3):
    """Сушилка над мойкой: решётка, тарелки ребром, кружки дном вверх,
    поддон с каплями. Сопутствующие вещи среднего плана у самой мойки."""
    rnd = random.Random(seed)
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="20" rx="7"'
         f' fill="#8f979c" {o(5)}/>'
         f'<rect x="{x:.0f}" y="{y+176:.0f}" width="{w_:.0f}" height="26" rx="8"'
         f' fill="#7d868c" {o(5)}/>')
    for i in range(int(w_ / 42)):
        s += (f'<line x1="{x+14+i*42:.0f}" y1="{y+20:.0f}" x2="{x+14+i*42:.0f}"'
              f' y2="{y+176:.0f}" stroke="#a7b0b6" stroke-width="7"/>')
    for i in range(5):
        r = 148 + (i % 3) * 22
        px = x + 54 + i * (w_ - 120) / 4.0
        s += (f'<ellipse cx="{px:.0f}" cy="{y+104:.0f}" rx="{r*.11:.0f}"'
              f' ry="{r*.5:.0f}" fill="#e7edf0" {o(4)}/>'
              f'<ellipse cx="{px:.0f}" cy="{y+104:.0f}" rx="{r*.05:.0f}"'
              f' ry="{r*.34:.0f}" fill="#cfd8dc" opacity=".8"/>')
    for i in range(3):
        cx = x + 90 + i * (w_ - 190) / 2.0
        s += (f'<path d="M{cx-40:.0f},{y+200:.0f} L{cx+40:.0f},{y+200:.0f}'
              f' L{cx+32:.0f},{y+126:.0f} L{cx-32:.0f},{y+126:.0f} Z"'
              f' fill="#eceff0" {o(4)}/>')
    for i in range(6):
        s += (f'<ellipse cx="{x+30+i*64:.0f}" cy="{y+214:.0f}" rx="9"'
              f' ry="{6+4*abs(A.w(t,1.8,i*.2)):.1f}" fill="#cfe0ea" opacity=".8"/>')
    return s


def _svitki_i_papki(x, y, t, seed=5, n=5):
    """Свитки и папки конторы: трубки с печатями и тесьмой, пара папок
    стоймя. Строки на свитках — волнистые, своих букв не рисуем."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        sx = x + i * 92
        hh = rnd.uniform(130, 190)
        ug = rnd.uniform(-7, 7)
        s += (f'<g transform="rotate({ug:.1f} {sx:.0f} {y:.0f})">'
              f'<rect x="{sx-26:.0f}" y="{y-hh:.0f}" width="52" height="{hh:.0f}"'
              f' rx="20" fill="#e8dcc0" {o(5)}/>'
              f'<ellipse cx="{sx:.0f}" cy="{y-hh:.0f}" rx="26" ry="10"'
              f' fill="#d4c6a4" {o(3)}/>'
              f'<rect x="{sx-30:.0f}" y="{y-hh*.56:.0f}" width="60" height="14" rx="6"'
              f' fill="{TKAN}" opacity=".85"/>'
              f'<circle cx="{sx+22:.0f}" cy="{y-hh*.46:.0f}" r="13" fill="#9c2f28"'
              f' {o(2)}/></g>')
    for i in range(2):
        px = x + n * 92 + 30 + i * 74
        s += (f'<rect x="{px:.0f}" y="{y-200:.0f}" width="64" height="200" rx="7"'
              f' fill="#8a6a44" {o(5)}/>'
              f'<rect x="{px+8:.0f}" y="{y-186:.0f}" width="48" height="172" rx="5"'
              f' fill="#efe8d6" opacity=".85"/>'
              f'<path d="M{px+16:.0f},{y-150:.0f} q16,-8 32,0" fill="none"'
              f' stroke="#9a8a68" stroke-width="5"/>')
    return s


def _valenki_u_dveri(x, y, s_=1.0, t=0.0):
    """Пара валенок у двери: голенища разной высоты, подшитая подошва."""
    s = ""
    for i, dx in enumerate((-46, 42)):
        hh = (150 if i == 0 else 138) * s_
        s += (f'{ten(x + dx * s_, y + 6 * s_, 44 * s_, 11 * s_, .4)}'
              f'<path d="M{x+dx*s_-36*s_:.0f},{y:.0f} L{x+dx*s_+36*s_:.0f},{y:.0f}'
              f' L{x+dx*s_+28*s_:.0f},{y-hh:.0f} L{x+dx*s_-24*s_:.0f},{y-hh:.0f} Z"'
              f' fill="#6b6256" {o(5)}/>'
              f'<rect x="{x+dx*s_-38*s_:.0f}" y="{y-12*s_:.0f}" width="{76*s_:.0f}"'
              f' height="{14*s_:.0f}" rx="6" fill="#3f3a33" {o(3)}/>'
              f'<path d="M{x+dx*s_-22*s_:.0f},{y-hh+10*s_:.0f}'
              f' q{22*s_:.0f},{10*s_:.0f} {48*s_:.0f},0" fill="none" stroke="#8a8274"'
              f' stroke-width="{6*s_:.0f}" opacity=".8"/>')
    return s


# ── РУКА МИМО ЧУЖОЙ ФИГУРЫ (блокер осмотра порции 2) ───────────────────────
# `_ruka` обещает только одно: рука не попадёт в СВОЮ голову и грудь. Соседей
# она не знает — и в кадре рукав шёл сквозь голову и платок соседней фигуры,
# а жердь проходила сквозь лицо. Числами это не ловится: гейт анатомии считает
# только свои фигуры. Лечение правилом, а не поштучно: сцена объявляет, где
# стоят ВСЕ её фигуры, а рука сама укорачивается и доворачивается, пока
# отрезок плечо→кисть не разойдётся с чужими головами и корпусами.
_CHUZHIE = []


def _figury_kadra(*tochki):
    """Объявить фигуры сцены как (x, уровень пола, рост). Зовётся ОДИН раз в
    начале сцены, до первой руки; дальше `_ruka_mimo` обходит их сама."""
    global _CHUZHIE
    _CHUZHIE = [(float(a), float(b), float(c)) for a, b, c in tochki]
    return ""


def _gabarit_figury(fx, fy, fh):
    """Прямоугольники головы и корпуса фигуры — по размерам `figura()`."""
    hh = fh * .145
    gy = fy - fh * .845
    w_ = fh * .42
    return ((fx - hh * 1.2, gy - hh * 1.3, fx + hh * 1.2, gy + hh * 1.3),
            (fx - w_ * .44, fy - fh * .68, fx + w_ * .44, fy - fh * .10))


def _otrezok_v_pryam(x1, y1, x2, y2, r):
    """Пересекает ли отрезок прямоугольник (отсечение Лианга — Барски)."""
    dx, dy = x2 - x1, y2 - y1
    t0, t1 = 0.0, 1.0
    for q_, p_ in ((x1 - r[0], -dx), (r[2] - x1, dx), (y1 - r[1], -dy), (r[3] - y1, dy)):
        if abs(p_) < 1e-9:
            if q_ < 0:
                return False
            continue
        rr = q_ / p_
        if p_ < 0:
            if rr > t1:
                return False
            t0 = max(t0, rr)
        else:
            if rr < t0:
                return False
            t1 = min(t1, rr)
    return t0 <= t1


def _chisto_ot_chuzhih(fx, fy, fh, px, py, ex, ey, zapas=1.0):
    """Отрезок плечо→кисть не задевает ни одну ЧУЖУЮ фигуру кадра."""
    for cx, cy, ch in _CHUZHIE:
        if abs(cx - fx) < 24.0 and abs(ch - fh) < 24.0:
            continue                      # это я сам (идущая фигура смещается)
        gol, kor = _gabarit_figury(cx, cy, ch)
        gol = (gol[0] - zapas * 6, gol[1] - zapas * 6,
               gol[2] + zapas * 6, gol[3] + zapas * 6)
        if _otrezok_v_pryam(px, py, ex, ey, gol):
            return False
        if _otrezok_v_pryam(px, py, ex, ey, kor):
            return False
    return True


def _ruka_mimo(fx, fy, fh, storona, dl, ug, t, col="#2a2430", kant="#cfe4f5",
               ph=.0, amp=6.0):
    """Тот же `_ruka`, но рука не доходит до чужой фигуры: сначала пробуем
    укоротить (кисть останавливается перед соседом), потом довернуть вниз —
    и только если не вышло, отдаём как есть. Возвращает то же, что `_ruka`."""
    px, py = _plecho(fx, fy, fh, storona)
    for dovorot in (0.0, 10.0, 20.0, 32.0, -12.0, -24.0):
        u = max(-58.0, min(88.0, float(ug) + dovorot))
        for k in (1.0, .92, .84, .76, .68, .60, .52, .44, .36, .30):
            a = u if storona > 0 else 180.0 - u
            rad = math.radians(a + amp * A.w(t, .9, ph))
            ex = px + dl * k * math.cos(rad)
            ey = py + dl * k * math.sin(rad)
            if _chisto_ot_chuzhih(fx, fy, fh, px, py, ex, ey):
                return _ruka(fx, fy, fh, storona, dl * k, u, t, col, kant, ph, amp)
    return _ruka(fx, fy, fh, storona, dl * .34, ug, t, col, kant, ph, amp)


def _ruka_sgib_mimo(fx, fy, fh, storona, dl1, ug1, dl2, ug2, t,
                    col="#2a2430", kant="#cfe4f5", ph=.0, amp=6.0):
    """Рука со сгибом, которая так же обходит чужие фигуры: укорачиваются
    оба звена сразу, предплечье остаётся наружу."""
    px, py = _plecho(fx, fy, fh, storona)
    for dovorot in (0.0, 12.0, 24.0, -14.0):
        u1 = max(-58.0, min(88.0, float(ug1) + dovorot))
        u2 = max(-58.0, min(88.0, float(ug2) + dovorot))
        for k in (1.0, .90, .80, .70, .60, .50, .40, .32):
            a1 = u1 if storona > 0 else 180.0 - u1
            r1 = math.radians(a1 + amp * A.w(t, .9, ph))
            lx = px + dl1 * k * math.cos(r1)
            ly = py + dl1 * k * math.sin(r1)
            a2 = u2 if storona > 0 else 180.0 - u2
            r2 = math.radians(a2 + amp * .7 * A.w(t, .9, ph + .3))
            ex = lx + dl2 * k * math.cos(r2)
            ey = ly + dl2 * k * math.sin(r2)
            if (_chisto_ot_chuzhih(fx, fy, fh, px, py, lx, ly)
                    and _chisto_ot_chuzhih(fx, fy, fh, lx, ly, ex, ey)):
                return _ruka_so_sgibom(fx, fy, fh, storona, dl1 * k, u1,
                                       dl2 * k, u2, t, col, kant, ph, amp)
    return _ruka_so_sgibom(fx, fy, fh, storona, dl1 * .4, ug1, dl2 * .4, ug2,
                           t, col, kant, ph, amp)


# ── ДЕКОРАЦИИ ──────────────────────────────────────────────────────────────

def babushkin_venik_v_uglu(t):
    """Угол деревенской кухни у печи: сточенный веник в пол-кадра среди
    кочерги, ухвата и совка. Внучка протягивает новый пышный веник, бабушка
    на табурете отводит его левой рукой и гладит ручку старого правой."""
    rnd = random.Random(201)
    pol = 902
    s = f'<rect width="{W}" height="{H}" fill="#2a2119"/>'
    # задник: бревенчатая стена двумя простенками (не фон — держит сетку)
    s += SL(Z_DAL, brevna(0, 60, 1040, pol - 60, 96)
            + brevna(1040, 60, 880, pol - 60, 96))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="30"'
                   f' fill="#3b2a1a" opacity=".9"/>' + polovicy(pol + 12))
    s += SL(Z_DAL, _polka_s_utvaryu(96, 300, 520, t, 11, 4))
    # печь справа: массив, устье с огнём, шесток
    s += SL(Z_SRED, pech(1430, 268, 490, 634, t, True, True, False))
    s += SL(Z_SRED, kirpich_ustya(1520, 646, 300, 200, t, True))
    s += SL(Z_SRED, ogon(1670, 804, t, 1.35, .2, 7))
    s += SL(Z_SRED, ugli(1540, 836, 260, t, 7, 2))
    s += SL(Z_SRED, dym(1480, 240, t, 4, .22, 260, .3, "#cfd6de", 1.2))
    # угол с печной утварью
    s += SL(Z_SRED, _ugol_pechnoy_utvari(1320, pol, t, 3))
    # где в кадре стоят ОБЕ фигуры — рука внучки обходит бабушку
    dx, dy_, dh = 330, pol + 26, 690
    bx, by_, bh = 860, pol + 10, 452
    _figury_kadra((dx, dy_, dh), (bx, by_ - 168, bh))
    otv = A.ease(A.seg(t, .5, 1.3))
    glad = A.w(t, 1.5, .1)
    # РУКИ СЧИТАЮТСЯ ДО РИСОВАНИЯ: веник ставится РОВНО В КИСТЬ, иначе
    # черенок и варежка расходятся на сотню пикселей и хват не читается
    # (осмотр порции 2).
    dev = figura(dx, dy_, dh, t, col="#4a5a72", kant="#ffd98a", ph=.2)
    r1, (h1x, h1y), _ = _ruka_mimo(dx, dy_, dh, 1, dh * .40, 16 + 10 * otv, t,
                                   "#4a5a72", "#ffd98a", .2, 5.0)
    r2, (h2x, h2y), _ = _ruka_mimo(dx, dy_, dh, -1, dh * .26, 34, t,
                                   "#4a5a72", "#ffd98a", .6, 4.0)
    dev += r1 + r2
    bab = figura(bx, by_ - 168, bh, t, col="#54505e", kant="#ffd98a",
                 platok=True, ph=.5, naklon=4.0)
    rb1, (b1x, b1y), _ = _ruka_mimo(bx, by_ - 168, bh, -1, bh * .50,
                                    10 + 16 * otv, t,
                                    "#54505e", "#ffd98a", .5, 6.0)
    rb2, (b2x, b2y), _ = _ruka_sgib_mimo(bx, by_ - 168, bh, 1, bh * .44, 26,
                                         bh * .44, 44 + 8 * glad, t,
                                         "#54505e", "#ffd98a", .1, 5.0)
    bab += rb1 + rb2
    # СТАРЫЙ ВЕНИК — главный предмет: ручкой вниз, веер КОРОЧЕ черенка
    # («сточенный»), прутья СВЕТЛЫЕ — #8a7340 на срубе #8e6337 давал разницу
    # 16/255 и веер растворялся в бревне. Черенок приходит ровно в кисть.
    vx, vy, vh = b2x - 4, pol + 4, 430
    s += SL(Z_SRED, _venik(vx, vy, vh, t, "#d8c48a", "#b8352c", True, .22, .1,
                           1.12, 211))
    s += SL(Z_SRED, f'<ellipse cx="{vx+2:.0f}" cy="{vy-vh*.20:.0f}" rx="34"'
                    f' ry="22" fill="#c9a463"'
                    f' opacity="{.30+.18*abs(glad):.2f}"/>')
    # НОВЫЙ веник — в кисти внучки, прутьями от неё
    s += SL(Z_SRED, _venik_v_ruke(h1x, h1y + 6, 320, t, "#b8a86a", "#5a4a2e",
                                  76 - 26 * otv, .88, 213, .34, .3))
    s += SL(Z_SRED, _tabyret(bx + 16, by_, t, 168, 182))
    s += SL(Z_SRED, dev)
    s += SL(Z_SRED, bab)
    # варежки ПОВЕРХ черенков: хват читается перекрытием, а не соседством
    s += SL(Z_SRED, _varezhka(h1x, h1y + 2, dh, t, .2)
            + _varezhka(b2x, b2y + 2, bh, t, .1))
    s += SL(Z_SRED, ten(bx + 10, by_ + 6, 150, 24, .5))
    # кот трётся о веник, нижняя треть занята вещами
    kot_x = vx - 230 + 30 * A.w(t, 4.0, .2)
    s += SL(Z_SRED, _kot_zhivoy(kot_x, pol + 58, t, 1.05, "#38332e", .3))
    s += SL(Z_SRED, _dvorovaya_utvar(96, pol + 96, 330, t, 29,
                                     ["korzina", "vedro"])
            + _polovik(560, pol + 70, 540, 118)
            + kartoshka(1180, pol + 92, t, 6, 6, 1.0)
            + _valenki_u_dveri(248, pol + 54, 1.0, t))
    s += SL(Z_SRED, teplo(1660, 790, 520, 420, .40))
    s += SL(Z_PERED, _stolb_pered(-10, 118, "#1a120c", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 1670, 790, 8, 4, 260, .42))
    s += vinetka(.42)
    return s


def gostya_s_chuzhoy_tryapkoy(t):
    """Чужая кухня: мойка с горой тарелок на пол-кадра. Гостья в бусах уже
    закатала рукав и берёт тряпку, хозяйка в фартуке обеими руками мягко
    забирает её. Пена оседает, бусы качаются."""
    rnd = random.Random(203)
    pol = 980
    s = f'<rect width="{W}" height="{H}" fill="#2f3338"/>'
    s += SL(Z_DAL, _kafel(0, 40, 1180, 540, t, 3, "#d4dcdc"))
    s += SL(Z_DAL, _kafel(1180, 40, 740, 540, t, 9, "#c8d2d4"))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-6:.0f}" width="{W}" height="{H-pol+6:.0f}"'
                   f' fill="#564b40"/>'
            + _polovik(430, pol + 24, 700, 86, "#cfc3a8", "#7a6a52"))
    s += SL(Z_DAL, _polki_otkrytye(1240, 150, 620, t, 17, 2, True, .0))
    # мойка — главный предмет кадра
    osd = A.ease(A.seg(t, 1.2, 1.6))
    s += SL(Z_SRED, _moyka(300, 590, 1240, t, 5, True, osd))
    # ГОРА ТАРЕЛОК на борту мойки
    s += SL(Z_SRED, _stopka_tarelok(1310, 576, 8, t, 23, 196))
    s += SL(Z_SRED, _tarelka(1176, 548, 92, t, .3, True, -16))
    s += SL(Z_SRED, _kastryulya(1448, 586, 1.0, t, True)
            + _chaynik(246, 584, 1.05, t)
            + _kruzhka(560, 580, .9, 0, "#e8eef0", 1)
            + _kruzhka(640, 578, .86, 0, "#ecdfd0", -1))
    s += SL(Z_SRED, par(620, 520, t, 4, .42, 180, .36, 1.0))
    s += SL(Z_SRED, _polotence(1600, 388, 230, t, .2, "#e3ddc6", True))
    _figury_kadra((700, pol + 36, 742), (1240, pol + 44, 860))
    # гостья: правый рукав закатан, правой берёт тряпку, левой тянется к тарелке
    gx, gy, gh = 700, pol + 36, 742
    ber = A.ease(A.seg(t, .3, .9))
    otdal = A.ease(A.seg(t, 1.5, 1.0))
    gost = figura(gx, gy, gh, t, col="#7a3a52", kant="#ffd98a", ph=.2,
                  naklon=5.0)
    g1, (t1x, t1y), _ = _ruka_mimo(gx, gy, gh, 1, gh * .40, 26 + 18 * ber - 26 * otdal, t,
                              "#7a3a52", "#ffd98a", .2, 5.0)
    g2, (t2x, t2y), _ = _ruka_mimo(gx, gy, gh, -1, gh * .34, 36 - 20 * otdal, t,
                              "#e8d8c0", "#ffd98a", .6, 4.0)
    gost += g1 + g2
    # бусы: качаются от наклона
    kach = 9 * A.w(t, 1.7, .3)
    for i in range(11):
        a = math.radians(-74 + i * 15)
        gost += (f'<circle cx="{gx+74*math.cos(a)+kach*.3:.0f}"'
                 f' cy="{gy-gh*.60+52*abs(math.sin(a))+kach*.4:.0f}" r="9"'
                 f' fill="#e2c76a" stroke="{K}" stroke-width="2"/>')
    s += SL(Z_SRED, gost)
    # тряпка переходит из рук в руки
    # ТРЯПКА крупная и своего цвета: раньше её путали с фартуком хозяйки
    tr = (f'<path d="M{t1x-96:.0f},{t1y-44:.0f} q{56:.0f},{-50:.0f} {152:.0f},{-18:.0f}'
          f' q{44:.0f},{68:.0f} {2:.0f},{130:.0f} q{-92:.0f},{28:.0f}'
          f' {-154:.0f},{-34:.0f} Z" fill="#6f93a4" {o(6)}/>')
    for q_ in range(3):
        tr += (f'<path d="M{t1x-56+q_*36:.0f},{t1y-34:.0f} q{10:.0f},{52:.0f}'
               f' {-4:.0f},{92:.0f}" fill="none" stroke="#587a8c"'
               f' stroke-width="7" opacity=".9"/>')
    tr += (f'<path d="M{t1x-70:.0f},{t1y+54:.0f} q{60:.0f},{26:.0f} {120:.0f},{4:.0f}"'
           f' fill="none" stroke="#9ab4c0" stroke-width="9"/>'
           f'<path d="M{t1x-30:.0f},{t1y+16:.0f} q{30:.0f},{-18:.0f} {62:.0f},{2:.0f}"'
           f' fill="none" stroke="#86a6b6" stroke-width="6"/>')
    # (тряпка рисуется ПОСЛЕ хозяйки, ниже: её корпус закрывал 65% —
    # осмотр порции 2)
    # хозяйка в фартуке: обе руки забирают тряпку
    hx, hy, hh = 1240, pol + 44, 860
    hoz = figura(hx, hy, hh, t, col="#3f4a58", kant="#ffd98a", platok=True,
                 ph=.7, profil=False)
    h1, (q1x, q1y), _ = _ruka_mimo(hx, hy, hh, -1, hh * .38, 22 + 14 * otdal, t,
                              "#3f4a58", "#ffd98a", .7, 5.0)
    h2, (q2x, q2y), _ = _ruka_mimo(hx, hy, hh, -1, hh * .30, 48 + 10 * otdal, t,
                              "#3f4a58", "#ffd98a", .3, 4.0)
    hoz += h1 + h2
    hoz += (f'<path d="M{hx-60:.0f},{hy-hh*.56:.0f} L{hx+60:.0f},{hy-hh*.56:.0f}'
            f' L{hx+78:.0f},{hy-hh*.10:.0f} L{hx-78:.0f},{hy-hh*.10:.0f} Z"'
            f' fill="#e4dcc8" {o(5)}/>'
            f'<path d="M{hx-78:.0f},{hy-hh*.36:.0f} q{78:.0f},{16:.0f} {156:.0f},0"'
            f' fill="none" stroke="#c4b79c" stroke-width="7"/>')
    s += SL(Z_SRED, hoz)
    s += SL(Z_SRED, tr)
    s += SL(Z_SRED, ten(gx, gy + 8, 170, 26, .45) + ten(hx, hy + 8, 180, 26, .45))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(t1x, t1y, gh, t, .2) + ""
            + _varezhka(q1x, q1y, hh, t, .7) + _varezhka(q2x, q2y, hh, t, .3))
    s += SL(Z_SRED, _pol_shvy(pol + 10, 1078, 11, 6, "#413528"))
    # низ кадра: ведро, таз, ящик с луком, кот у тумбы
    s += SL(Z_SRED, _dvorovaya_utvar(96, pol + 72, 300, t, 31, ["vedro", "korob"])
            + _yaschiki(1560, pol + 70, t, 7, 2, .82)
            + _kot_zhivoy(1402, pol + 60, t, .92, "#4a423c", .6))
    s += SL(Z_PERED, ramka_pp("levo"))
    s += SL(Z_LETIT, _pena_gorka(660, 560, 90, t, 41, 7, 1 - osd))
    s += vinetka(.40)
    return s


def tarelka_s_chuzhimi_neschastyami(t):
    """Чужая тарелка в мыльной пене во весь кадр, вокруг ложки, губка,
    кружка. Видны только руки до локтя: левая держит тарелку за край,
    правая трёт её по кругу, и по правой руке лезут три кляксы."""
    rnd = random.Random(207)
    s = f'<rect width="{W}" height="{H}" fill="#2b3338"/>'
    s += SL(Z_DAL, _kafel(0, 0, 1120, 520, t, 5, "#cdd7d8"))
    s += SL(Z_DAL, _kafel(1120, 0, 800, 520, t, 13, "#c2cccd"))
    s += SL(Z_DAL, _sushilka_posudy(100, 60, 640, t, 3))
    s += SL(Z_DAL, _polka_s_utvaryu(1180, 300, 620, t, 67, 5))
    s += SL(Z_DAL, f'<rect x="0" y="446" width="{W}" height="120" rx="8"'
                   f' fill="#a9a194" {o(6)}/>')
    # чаша мойки крупно: борт, дно, вода
    s += SL(Z_SRED, f'<path d="M160,500 L1760,500 L1660,1040 L260,1040 Z"'
                    f' fill="#5e676e" {o(7)}/>'
            + f'<path d="M226,560 L1694,560 L1612,980 L308,980 Z"'
              f' fill="#49535b" {o(5)}/>'
            + f'<ellipse cx="960" cy="986" rx="150" ry="34" fill="#333c43" {o(4)}/>')
    s += SL(Z_SRED, _pena_gorka(520, 930, 300, t, 19, 20, .3)
            + _pena_gorka(1420, 920, 250, t, 23, 16, .2))
    # ГЛАВНЫЙ ПРЕДМЕТ: тарелка, её роняют в пену
    pad = A.out(A.seg(t, 3.6, 1.0))
    tcx, tcy = 930, 606 + 230 * pad
    s += SL(Z_SRED, _tarelka(tcx, tcy, 300, t, .0, True, -6 + 14 * pad))
    # тряпка трёт по кругу
    a = t * 2.1
    rx_, ry_ = tcx + 150 * math.cos(a), tcy + 112 * math.sin(a)
    s += SL(Z_SRED, f'<path d="M{rx_-78:.0f},{ry_-40:.0f} q{52:.0f},{-34:.0f}'
                    f' {122:.0f},{-10:.0f} q{22:.0f},{54:.0f} {-16:.0f},{90:.0f}'
                    f' q{-74:.0f},{16:.0f} {-106:.0f},{-70:.0f} Z"'
                    f' fill="#9ab4c0" {o(5)}/>'
            + f'<path d="M{rx_-50:.0f},{ry_-16:.0f} q{44:.0f},{22:.0f} {80:.0f},{10:.0f}"'
              f' fill="none" stroke="#7e97a6" stroke-width="8"/>')
    # ЛЕВАЯ РУКА до локтя — ничья (крупный план кистей, человека в кадре нет)
    lruk, (lx2, ly2) = rukav(118, 1062, 440, -56, t, "#e8d8c0", "#ffd98a", .2,
                             4.0, True)
    s += SL(Z_SRED, lruk)
    s += SL(Z_SRED, f'<ellipse cx="{lx2:.0f}" cy="{ly2:.0f}" rx="56" ry="40"'
                    f' fill="#e8d8c0" {o(5)}/>'
            + f'<rect x="{lx2-92:.0f}" y="{ly2+30:.0f}" width="150" height="40" rx="16"'
              f' fill="#7a3a52" {o(5)}/>')
    # ПРАВАЯ РУКА до локтя — тоже ничья, по ней лезут кляксы
    rruk, (rx2, ry2) = rukav(1848, 1066, 470, -122, t, "#e8d8c0", "#ffd98a", .5,
                             4.0, True)
    s += SL(Z_SRED, rruk)
    s += SL(Z_SRED, f'<ellipse cx="{rx2:.0f}" cy="{ry2:.0f}" rx="58" ry="42"'
                    f' fill="#e8d8c0" {o(5)}/>'
            + f'<rect x="{rx2-30:.0f}" y="{ry2+34:.0f}" width="156" height="42" rx="16"'
              f' fill="#7a3a52" {o(5)}/>')
    # три кляксы лезут по правой руке к локтю и стряхиваются в мойку
    stry = A.ease(A.seg(t, 4.6, .9))
    for i in range(3):
        p = min(1.0, max(.0, A.seg(t, .6 + i * .35, 1.6)))
        kx = rx2 + (1848 - rx2) * p * .82 + 120 * stry
        ky = ry2 + (1066 - ry2) * p * .82 + 230 * stry * (1 + i * .2)
        s += SL(Z_SRED, _klyaksa_grust(kx, ky, .92 + .1 * i, t, i * .3))
    # ложки, губка, кружка вокруг
    for i in range(4):
        lxx = 300 + i * 118
        s += SL(Z_SRED, f'<ellipse cx="{lxx:.0f}" cy="{530+(i%2)*14:.0f}" rx="40"'
                        f' ry="26" fill="#cfd8dc" {o(4)}/>'
                f'<path d="M{lxx+30:.0f},{532+(i%2)*14:.0f} l{112:.0f},{26:.0f}'
                f' l{-8:.0f},{18:.0f} l{-112:.0f},{-26:.0f} Z" fill="#b9c4c9" {o(3)}/>')
    s += SL(Z_SRED, f'<rect x="1560" y="478" width="150" height="76" rx="22"'
                    f' fill="#e4c85a" {o(5)}/>'
            + f'<path d="M1572,510 h126 M1572,534 h126" stroke="#c9a93c"'
              f' stroke-width="8"/>')
    s += SL(Z_SRED, _kruzhka(1800, 560, 1.2, 6, "#e8eef0", -1))
    # сопутствующие вещи по борту мойки: бутыли, щётка, доска, миски
    for i in range(4):
        bx = 300 + i * 150
        s += SL(Z_SRED, f'<rect x="{bx-34:.0f}" y="{430-i*16:.0f}" width="68"'
                        f' height="{150+i*18:.0f}" rx="16"'
                        f' fill="{["#4e7a52", "#7a5a2c", "#3f5c7a", "#8a4a3c"][i]}"'
                        f' {o(5)}/>'
                f'<rect x="{bx-26:.0f}" y="{454-i*16:.0f}" width="52" height="56"'
                f' rx="6" fill="#efe8d6" opacity=".85"/>')
    s += SL(Z_SRED, f'<path d="M1180,560 L1330,560 L1312,420 L1198,420 Z"'
                    f' fill="url(#dosk)" {o(5)}/>'
            + f'<circle cx="1255" cy="436" r="14" fill="none" stroke="#5b4428"'
              f' stroke-width="7"/>'
            + f'<rect x="1372" y="450" width="58" height="160" rx="12"'
              f' fill="#8a6a44" {o(5)}/>'
            + f'<rect x="1360" y="424" width="82" height="34" rx="10"'
              f' fill="#cfc3a0" {o(4)}/>')
    for i in range(3):
        s += SL(Z_SRED, _tarelka(1500 + i * 130, 980 - i * 26, 104, t, i * .3,
                                 True, 8 - i * 7))
    s += SL(Z_SRED, par(560, 470, t, 4, .4, 190, .34, 1.1))
    s += SL(Z_SRED, _polotence(1716, 120, 250, t, .4, "#dcd4bd", True))
    s += SL(Z_PERED, _stolb_pered(1846, 84, "#19140f", 0, H))
    s += SL(Z_LETIT, _pena_gorka(tcx, tcy - 40, 220, t, 29, 9, 1 - pad))
    s += vinetka(.44)
    return s


def chuzhoy_poryadok_na_polkah(t):
    """Открытые кухонные полки на пол-кадра: чашки ручками влево, тарелки по
    росту, крупы в банках. Гостья с табурета ставит чашки как попало,
    хозяйка смотрит исподлобья. В окне-раздаче настоящее мытьё тарелок."""
    rnd = random.Random(211)
    pol = 962
    s = f'<rect width="{W}" height="{H}" fill="#2d3236"/>'
    s += SL(Z_DAL, _kafel(0, 30, 1020, 520, t, 7, "#d2dadb"))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-8:.0f}" width="{W}" height="{H-pol+8:.0f}"'
                   f' fill="#5a4e42"/>' + _polovik(360, pol + 20, 620, 92))
    # НАСТОЯЩИЙ КАДР в окне-раздаче: сначала рисованный вид, потом метка,
    # потом обвязка поверх (порядок обязателен)
    px, py, pw, ph_ = 1020, 236, 820, 440
    put = kontur_proema(px, py, pw, ph_, "pryam")
    vid = (f'<clipPath id="razd2"><path d="{put}"/></clipPath>'
           f'<g clip-path="url(#razd2)">'
           f'<rect x="{px:.0f}" y="{py:.0f}" width="{pw:.0f}" height="{ph_:.0f}"'
           f' fill="#4a5258"/>'
           f'<rect x="{px:.0f}" y="{py+ph_*.62:.0f}" width="{pw:.0f}"'
           f' height="{ph_*.38:.0f}" fill="#8a8274"/>')
    for i in range(5):
        vid += (f'<ellipse cx="{px+140+i*140:.0f}" cy="{py+ph_*.58:.0f}" rx="64"'
                f' ry="20" fill="#e7edf0" opacity=".9"/>')
    vid += (f'<circle cx="{px+pw*.5:.0f}" cy="{py+ph_*.3:.0f}" r="86"'
            f' fill="#ffd98a" opacity=".22"/></g>')
    s += SL(Z_SRED, vid + mesto_stoka(px, py, pw, ph_, "pryam")
            + _okno_razdachi(px, py, pw, ph_, t))
    # ПОЛКИ — главный предмет: три доски во всю левую половину
    sdv = A.ease(A.seg(t, .4, 1.2))
    s += SL(Z_SRED, _polki_otkrytye(70, 180, 880, t, 11, 3, True, sdv))
    # чашки, которые гостья уже поставила ручками ВПРАВО
    for i in range(3):
        s += SL(Z_SRED, _kruzhka(250 + i * 150, 174, 1.0, 3 * A.w(t, 2.4, i * .3),
                                 "#efe3d4", 1))
    s += SL(Z_SRED, _banka_krupy(900, 520, 1.1, "#cdb27c")
            + _chaynik(986, 940, 1.1, t))
    # после разведения фигур в середине кадра открылась дыра — закрываю
    # настоящими вещами: рабочий столик с посудой, ящики и связка лука
    s += SL(Z_SRED, _stolik(700, pol - 10, 420, t, 300, False))
    s += SL(Z_SRED, _stopka_tarelok(640, pol - 316, 5, t, 197, 180)
            + _kruzhka(790, pol - 308, 1.0, 0, "#efe3d4", 1)
            + _kastryulya(880, pol - 306, .92, t, True))
    s += SL(Z_SRED, _yaschiki(560, pol + 6, t, 199, 2, .9))
    for i in range(4):
        s += SL(Z_SRED, f'<circle cx="{600+i*52:.0f}" cy="{pol-60:.0f}" r="26"'
                        f' fill="#c9a05a" {o(4)}/>'
                f'<path d="M{600+i*52:.0f},{pol-86:.0f} q8,-18 20,-22"'
                f' fill="none" stroke="#8a7a46" stroke-width="6"/>')
    s += SL(Z_SRED, par(986, 836, t, 4, .4, 170, .34, 1.0))
    # гостья на табурете
    gx, gy, gh = 390, pol + 2, 686
    slez = A.ease(A.seg(t, 2.7, 1.1))
    s += SL(Z_SRED, _tabyret(gx + 8, gy, t, 196, 190))
    _figury_kadra((gx, gy - 196 + 120 * slez, gh), (960, pol + 46, 840))
    gost = figura(gx, gy - 196 + 120 * slez, gh, t, col="#6e4a62",
                  kant="#ffd98a", ph=.3, naklon=-6 + 10 * slez)
    g1, (c1x, c1y), _ = _ruka_mimo(gx, gy - 196 + 120 * slez, gh, 1, gh * .40,
                              -34 + 46 * slez, t, "#6e4a62", "#ffd98a", .3, 5.0)
    g2, (c2x, c2y), _ = _ruka_mimo(gx, gy - 196 + 120 * slez, gh, -1, gh * .36,
                              -26 + 42 * slez, t, "#6e4a62", "#ffd98a", .7, 5.0)
    gost += g1 + g2
    s += SL(Z_SRED, gost)
    s += SL(Z_SRED, _kruzhka(c1x + 20, c1y + 8, .96, 8 * A.w(t, 1.6, .2),
                             "#efe3d4", 1)
            + _kruzhka(c2x - 18, c2y + 10, .9, -6 * A.w(t, 1.9, .5),
                       "#e8eef0", -1))
    # хозяйка: руки скрещены на груди, брови сдвинуты — стоит на полу
    hx, hy, hh = 960, pol + 46, 840
    hoz = figura(hx, hy, hh, t, col="#3a4452", kant="#ffd98a", platok=True,
                 ph=.8, naklon=3.0)
    h1, (d1x, d1y), _ = _ruka_sgib_mimo(hx, hy, hh, 1, hh * .22, 48,
                                        hh * .26, -4, t, "#3a4452", "#ffd98a", .2, 3.0)
    h2, (d2x, d2y), _ = _ruka_sgib_mimo(hx, hy, hh, -1, hh * .22, 52,
                                        hh * .26, -8, t, "#3a4452", "#ffd98a", .6, 3.0)
    hoz += h1 + h2
    hoz += (f'<path d="M{hx-66:.0f},{hy-hh*.54:.0f} L{hx+66:.0f},{hy-hh*.54:.0f}'
            f' L{hx+80:.0f},{hy-hh*.08:.0f} L{hx-80:.0f},{hy-hh*.08:.0f} Z"'
            f' fill="#ded6c0" {o(5)}/>')
    s += SL(Z_SRED, hoz)
    s += SL(Z_SRED, ten(hx, hy + 8, 176, 26, .45))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(c1x, c1y, gh, t, .3) + _varezhka(c2x, c2y, gh, t, .7)
            + _varezhka(d2x, d2y, hh, t, .6))
    s += SL(Z_SRED, _pol_shvy(pol + 10, 1078, 13, 6, "#44382a"))
    # низ кадра
    s += SL(Z_SRED, _dvorovaya_utvar(1180, pol + 86, 420, t, 37,
                                     ["vedro", "korzina", "korob"])
            + _yaschiki(96, pol + 78, t, 9, 2, .76)
            + _kot_zhivoy(1686, pol + 66, t, .98, "#3f3a34", .2)
            + kartoshka(1000, pol + 96, t, 7, 6, 1.0))
    s += SL(Z_PERED, _stolb_pered(1874, 72, "#191410", 0, H))
    s += SL(Z_LETIT, mokryy_sneg(t, 0, 5, .0, .0) + _pena_gorka(1380, 700, 60, t, 43, 4, .5))
    s += vinetka(.42)
    return s


def gostya_v_kresle(t):
    """Комната хозяйки: мягкое кресло на пол-кадра, торшер, столик с пирогом
    и чашками, ковёр. Гостья упёрлась руками в подлокотники и порывается
    встать, хозяйка усаживает её и подаёт чашку на блюдце."""
    rnd = random.Random(213)
    pol = 952
    s = f'<rect width="{W}" height="{H}" fill="#2b2622"/>'
    s += SL(Z_DAL, doski(0, 0, 1180, pol, 96, True, "dosk"))
    s += SL(Z_DAL, doski(1180, 0, 740, pol, 96, True, "dosk"))
    s += SL(Z_DAL, _kover_na_stene(1040, 128, 1060, 520, t, 5))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-14:.0f}" width="{W}" height="{H-pol+14:.0f}"'
                   f' fill="#6a5440"/>' + _polovik(520, pol + 16, 860, 118))
    s += SL(Z_DAL, _polka_s_utvaryu(80, 268, 540, t, 23, 4))
    s += SL(Z_DAL, _knizhnaya_polka(96, 440, 560, t, 19, 2, 196))
    s += SL(Z_DAL, _ramki_na_stene(640, 150, 420, t, 11, 3))
    # торшер — тёплое пятно сцены
    s += SL(Z_SRED, lampa(1468, 712, t, 1.25, True))
    s += SL(Z_SRED, f'<rect x="1452" y="712" width="32" height="236" rx="12"'
                    f' fill="#4a3c30" {o(5)}/>'
            + f'<ellipse cx="1468" cy="950" rx="88" ry="22" fill="#3f342a" {o(4)}/>')
    # КРЕСЛО — главный предмет
    # КРЕСЛО, А НЕ ДИВАН: 580 px ширины читались диваном — ставим 400 при
    # более высокой спинке
    # 400 px всё ещё читались диваном (ширина 2,9 подола сидящей) — 270
    s += SL(Z_SRED, _kreslo(700, pol, 270, t, 520, "#6c5a4a"))
    # столик с пирогом и чашками
    s += SL(Z_SRED, _stolik(1210, pol, 420, t, 220, False))
    s += SL(Z_SRED, _pirog(1178, pol - 224, .92, t, True)
            + _kruzhka(1346, pol - 216, 1.0, 0, "#f0eade", 1)
            + _kruzhka(1414, pol - 214, .92, 0, "#e8dcc8", -1))
    s += SL(Z_SRED, par(1352, pol - 300, t, 4, .46, 160, .4, .9))
    # гостья в кресле: привстаёт и садится обратно
    vst = A.ease(A.seg(t, .3, .9)) * (1 - A.ease(A.seg(t, 1.6, 1.0)))
    gx, gy, gh = 712, pol - 150 - 58 * vst, 430 + 60 * vst
    _figury_kadra((gx, gy, gh), (1046, pol + 30, 800))
    gost = figura(gx, gy, gh, t, col="#6a3a4a", kant="#ffd98a", platok=True,
                  ph=.3, naklon=-5 + 7 * vst)
    g1, (a1x, a1y), _ = _ruka_mimo(gx, gy, gh, 1, gh * .50, 56 - 22 * vst, t,
                              "#6a3a4a", "#ffd98a", .3, 4.0)
    g2, (a2x, a2y), _ = _ruka_mimo(gx, gy, gh, -1, gh * .50, 58 - 20 * vst, t,
                              "#6a3a4a", "#ffd98a", .7, 4.0)
    gost += g1 + g2
    s += SL(Z_SRED, gost)
    # подушка под спину ложится по ходу плана
    pod = A.ease(A.seg(t, 1.9, .8))
    s += SL(Z_SRED, f'<path d="M{gx-120:.0f},{gy-gh*.56-30*pod:.0f}'
                    f' q{120:.0f},{-54:.0f} {240:.0f},0 q{20:.0f},{70:.0f}'
                    f' {-10:.0f},{104:.0f} q{-116:.0f},{34:.0f} {-230:.0f},0'
                    f' q{-26:.0f},{-44:.0f} {0:.0f},{-104:.0f} Z"'
                    f' fill="#c9a05a" {o(5)} opacity="{.2+.8*pod:.2f}"/>')
    # хозяйка перед гостьей: обе ладони на плечах, потом чашка на блюдце
    hx, hy, hh = 1046, pol + 30, 800
    hoz = figura(hx, hy, hh, t, col="#3f4a58", kant="#ffd98a", ph=.8, naklon=-4.0)
    h1, (p1x, p1y), _ = _ruka_mimo(hx, hy, hh, -1, hh * .40, 24 + 12 * pod, t,
                              "#3f4a58", "#ffd98a", .8, 4.0)
    h2, (p2x, p2y), _ = _ruka_sgib_mimo(hx, hy, hh, -1, hh * .24, 44,
                                        hh * .24, 8, t, "#3f4a58", "#ffd98a", .2, 4.0)
    hoz += h1 + h2
    s += SL(Z_SRED, hoz)
    # чашка на блюдце переходит в руки гостьи
    per = A.ease(A.seg(t, 2.6, 1.1))
    # чашка доходит ДО САМОЙ РУКИ гостьи и остаётся в ней
    chx = p1x + (a1x - p1x) * per
    chy = p1y + (a1y - p1y) * per
    s += SL(Z_SRED, f'<ellipse cx="{chx:.0f}" cy="{chy+56:.0f}" rx="52" ry="16"'
                    f' fill="#f2ece0" {o(4)}/>'
            + _kruzhka(chx, chy + 50, .86, 4 * A.w(t, 1.8, .2), "#f6f0e4", 1))
    s += SL(Z_SRED, par(chx, chy - 20, t, 3, .4, 120, .44, .8))
    s += SL(Z_SRED, ten(hx, hy + 8, 180, 26, .45))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(a1x, a1y, gh, t, .3) + ""
            + _varezhka(p2x, p2y, hh, t, .2))
    s += SL(Z_SRED, _konus_sveta(1468, 700, 560, 300, -12, .38))
    s += SL(Z_SRED, _pol_shvy(pol + 14, 1078, 17, 6, "#4a3a28"))
    # низ кадра: тапки, корзина с клубками, кот на половике
    s += SL(Z_SRED, _valenki_u_dveri(360, pol + 70, .9, t)
            + _dvorovaya_utvar(120, pol + 92, 420, t, 41,
                               ["korzina", "korob", "vedro"])
            + _kot_zhivoy(1690, pol + 74, t, 1.1, "#4a423c", .4, True, True)
            + kartoshka(1540, pol + 96, t, 5, 6, .9))
    # пуфик, корзина с клубками и фикус в кадке у кресла
    s += SL(Z_SRED, f'<ellipse cx="420" cy="{pol-70:.0f}" rx="118" ry="74"'
                    f' fill="#7a5a4a" {o(6)}/>'
            + f'<ellipse cx="420" cy="{pol-96:.0f}" rx="104" ry="52"'
              f' fill="#8c6a56" opacity=".9"/>'
            + f'<rect x="402" y="{pol-30:.0f}" width="36" height="34" rx="10"'
              f' fill="#4a3c30" {o(4)}/>')
    for i in range(5):
        s += SL(Z_SRED, f'<circle cx="{232+i*42:.0f}" cy="{pol-44-(i%2)*30:.0f}"'
                        f' r="{30+(i%3)*8:.0f}"'
                        f' fill="{["#7a3a42", "#3f5c7a", "#8a6a2c", "#4a6a48", "#9c5a3c"][i]}"'
                        f' {o(4)}/>'
                f'<path d="M{232+i*42:.0f},{pol-44-(i%2)*30:.0f} q22,-14 40,4"'
                f' fill="none" stroke="#efe8d6" stroke-width="5" opacity=".7"/>')
    s += SL(Z_SRED, teplo(1468, 740, 560, 460, .44))
    s += SL(Z_PERED, ramka_pp("levo"))
    s += SL(Z_LETIT, iskra_let(t, 1468, 712, 5, 7, 180, .3))
    s += vinetka(.42)
    return s


def za_stolom_u_docheri(t):
    """Современная кухня-столовая после обеда: круглый стол, пустые тарелки,
    салатник, хлебница, ваза с яблоками. Мать сидит с руками на коленях,
    дочь собирает тарелки в стопку, внук протягивает бабушке яблоко."""
    rnd = random.Random(217)
    pol = 968
    s = f'<rect width="{W}" height="{H}" fill="#2e3338"/>'
    s += SL(Z_DAL, _kafel(0, 20, 980, 420, t, 11, "#d8dedd"))
    s += SL(Z_DAL, f'<rect x="980" y="20" width="940" height="560" rx="10"'
                   f' fill="#9aa3a8" {o(6)}/>')
    s += SL(Z_DAL, _polki_otkrytye(1040, 120, 760, t, 29, 2, True, .0))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-10:.0f}" width="{W}" height="{H-pol+10:.0f}"'
                   f' fill="#7a6a56"/>' + _polovik(500, pol + 22, 900, 96,
                                                   "#cfc0a4", "#8a7a5c"))
    s += SL(Z_DAL, tusklaya_lampochka(960, 180, t, 1.25, True))
    # КРУГЛЫЙ СТОЛ — главный предмет
    sx, sy, sw = 960, pol - 258, 1180
    s += SL(Z_SRED, f'{ten(sx, pol + 4, 440, 26, .5)}'
                    f'<ellipse cx="{sx:.0f}" cy="{sy:.0f}" rx="{sw/2:.0f}" ry="162"'
                    f' fill="url(#derev)" {o(7)}/>'
            + f'<ellipse cx="{sx:.0f}" cy="{sy-18:.0f}" rx="{sw/2-26:.0f}" ry="138"'
              f' fill="#a9825a" opacity=".85"/>'
            + f'<rect x="{sx-58:.0f}" y="{sy+120:.0f}" width="116" height="150" rx="14"'
              f' fill="#6a5030" {o(5)}/>'
            + f'<ellipse cx="{sx:.0f}" cy="{pol-6:.0f}" rx="210" ry="40"'
              f' fill="#5b4428" {o(5)}/>')
    # посуда на столе: пустые тарелки, салатник, хлебница
    for i in range(4):
        s += SL(Z_SRED, _tarelka(600 + i * 208, sy - 24 + (i % 2) * 18, 86, t,
                                 i * .2, False, -8 + i * 5))
    s += SL(Z_SRED, f'<path d="M1180,{sy-40:.0f} q86,-30 172,0 q-16,70 -86,76'
                    f' q-70,-6 -86,-76 Z" fill="url(#stekl)" opacity=".9" {o(5)}/>'
            + f'<ellipse cx="1266" cy="{sy-44:.0f}" rx="86" ry="22" fill="#9cc06a"'
              f' opacity=".85"/>')
    s += SL(Z_SRED, f'<rect x="420" y="{sy-96:.0f}" width="230" height="86" rx="18"'
                    f' fill="url(#solom)" {o(5)}/>'
            + f'<path d="M430,{sy-96:.0f} q114,-44 210,0" fill="none"'
              f' stroke="#8a6a3c" stroke-width="9"/>'
            + karavay(530, sy - 92, .54, False))
    s += SL(Z_SRED, _vaza_s_yablokami(930, sy - 40, 1.0, t, 9, 7))
    # дочь слева: обеими руками собирает тарелки в стопку
    dx, dy_, dh = 408, pol + 40, 804
    sob = A.ease(A.seg(t, .4, 1.4))
    _figury_kadra((408, pol + 40, 804), (1390, pol - 118, 470),
                  (1680, pol - 92, 420))
    doch = figura(dx, dy_, dh, t, col="#46586a", kant="#ffd98a", ph=.2, naklon=6.0)
    d1, (e1x, e1y), _ = _ruka_mimo(dx, dy_, dh, 1, dh * .42, 40 - 16 * sob, t,
                              "#46586a", "#ffd98a", .2, 5.0)
    d2, (e2x, e2y), _ = _ruka_mimo(dx, dy_, dh, 1, dh * .34, 62 - 14 * sob, t,
                              "#46586a", "#ffd98a", .6, 4.0)
    doch += d1 + d2
    s += SL(Z_SRED, doch)
    s += SL(Z_SRED, _stopka_tarelok(e1x + 44, e1y - 10 - 40 * sob,
                                    2 + int(4 * sob), t, 53, 172))
    # мать в нарядной кофте: сидит, обе руки на коленях
    mx, my, mh = 1390, pol - 118, 470
    s += SL(Z_SRED, _venskiy_stul(1404, pol + 6, 520, t, 2.0, True))
    mat = figura(mx, my, mh, t, col="#7a4a5e", kant="#ffd98a", platok=True,
                 ph=.6, naklon=-3.0)
    m1, (f1x, f1y), _ = _ruka_mimo(mx, my, mh, -1, mh * .46, 64, t,
                              "#7a4a5e", "#ffd98a", .6, 3.0)
    m2, (f2x, f2y), _ = _ruka_mimo(mx, my, mh, 1, mh * .44, 68, t,
                              "#7a4a5e", "#ffd98a", .2, 3.0)
    mat += m1 + m2
    s += SL(Z_SRED, mat)
    # внук рядом: правой протягивает яблоко бабушке, левой держит своё
    vx, vy, vh = 1680, pol - 92, 420
    s += SL(Z_SRED, _tabyret(1694, pol + 8, t, 190, 170))
    vnuk = figura(vx, vy, vh, t, col="#4a6a58", kant="#ffd98a", ph=.9, naklon=5.0)
    v1, (y1x, y1y), _ = _ruka_mimo(vx, vy, vh, -1, vh * .52, 18, t,
                              "#4a6a58", "#ffd98a", .9, 5.0)
    v2, (y2x, y2y), _ = _ruka_mimo(vx, vy, vh, 1, vh * .34, 54, t,
                              "#4a6a58", "#ffd98a", .4, 4.0)
    vnuk += v1 + v2
    s += SL(Z_SRED, vnuk)
    per = A.ease(A.seg(t, 2.2, 1.3))
    ayx = y1x + (f1x - y1x) * per
    ayy = y1y + (f1y - y1y) * per
    s += SL(Z_SRED, f'<circle cx="{ayx:.0f}" cy="{ayy:.0f}" r="34"'
                    f' fill="#b8352c" {o(5)}/>'
            + f'<path d="M{ayx+4:.0f},{ayy-34:.0f} q8,-18 22,-20" fill="none"'
              f' stroke="#4e3418" stroke-width="6"/>'
            + f'<circle cx="{ayx-12:.0f}" cy="{ayy-12:.0f}" r="8" fill="#ffe6c8"'
              f' opacity=".55"/>')
    s += SL(Z_SRED, f'<circle cx="{y2x+10:.0f}" cy="{y2y+14:.0f}" r="30"'
                    f' fill="#c9772c" {o(5)}/>'
            + f'<path d="M{y2x+68:.0f},{y2y-6:.0f} a30,30 0 0 0 -56,8"'
              f' fill="none" stroke="#e8c8a0" stroke-width="7"/>')
    s += SL(Z_SRED, ten(dx, dy_ + 8, 176, 26, .45))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(e1x, e1y, dh, t, .2) + ""
            + _varezhka(f1x, f1y, mh, t, .6) + ""
            + _varezhka(y1x, y1y, vh, t, .9) + _varezhka(y2x, y2y, vh, t, .4))
    s += SL(Z_SRED, _pol_shvy(pol + 10, 1078, 19, 6, "#5a4a36"))
    # низ кадра
    s += SL(Z_SRED, _gorodskoy_hlam(120, pol + 96, 340, t, 7, ["yaschik", "korobka"])
            + _kot_zhivoy(1010, pol + 84, t, 1.05, "#453e38", .7)
            + _valenki_u_dveri(1860, pol + 72, .8, t))
    s += SL(Z_PERED, _stolb_pered(-6, 96, "#1b1612", 0, H))
    s += SL(Z_LETIT, par(1266, sy - 130, t, 3, .3, 130, .3, .9))
    s += vinetka(.40)
    return s


def babushka_na_kraeshke_stula(t):
    """Гостиная шестидесятых: сервант с хрусталём, стол под кружевной
    скатертью, венский стул на пол-кадра. Бабушка сидит на самом краешке
    с сумочкой на коленях, хозяйка выносит супницу и приглашает к столу."""
    rnd = random.Random(223)
    pol = 958
    s = f'<rect width="{W}" height="{H}" fill="#2c2722"/>'
    s += SL(Z_DAL, f'<rect x="0" y="0" width="1100" height="{pol:.0f}"'
                   f' fill="#8a7a62"/>')
    for i in range(11):
        s += SL(Z_DAL, f'<rect x="{i*100:.0f}" y="0" width="54" height="{pol:.0f}"'
                       f' fill="#9a8a70" opacity=".55"/>')
    s += SL(Z_DAL, f'<rect x="1100" y="0" width="820" height="{pol:.0f}"'
                   f' fill="#7e6f58"/>')
    s += SL(Z_DAL, _kover_na_stene(1120, 128, 660, 430, t, 13))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-16:.0f}" width="{W}" height="{H-pol+16:.0f}"'
                   f' fill="#6e5640"/>' + _polovik(430, pol + 18, 1000, 120))
    s += SL(Z_DAL, hodiki(190, 300, t, 1.3))
    s += SL(Z_DAL, _knizhnaya_polka(60, 560, 520, t, 23, 2, 200))
    s += SL(Z_DAL, _ramki_na_stene(520, 150, 540, t, 29, 4))
    s += SL(Z_DAL, tusklaya_lampochka(960, 150, t, 1.15, True))
    # СЕРВАНТ С ХРУСТАЛЁМ — главный предмет
    s += SL(Z_SRED, _servant_hrustal(1140, pol, 660, 700, t, 3))
    # стол под кружевной скатертью
    s += SL(Z_SRED, f'{ten(760, pol + 6, 330, 22, .5)}'
                    f'<rect x="430" y="{pol-268:.0f}" width="680" height="34" rx="10"'
                    f' fill="url(#derev)" {o(7)}/>'
            + f'<path d="M444,{pol-234:.0f} L1096,{pol-234:.0f} L1056,{pol-96:.0f}'
              f' L484,{pol-96:.0f} Z" fill="#f2ece0" {o(5)}/>')
    for i in range(12):
        s += SL(Z_SRED, f'<circle cx="{486+i*52:.0f}" cy="{pol-92:.0f}" r="15"'
                        f' fill="none" stroke="#e0d6bd" stroke-width="5"/>')
    for i in (0, 1):
        s += SL(Z_SRED, f'<rect x="{480+i*560:.0f}" y="{pol-234:.0f}" width="30"'
                        f' height="138" fill="url(#derev)" {o(5)}/>')
    # супница встаёт на стол
    pst = A.ease(A.seg(t, 1.1, 1.0))
    s += SL(Z_SRED, _supnica(770, pol - 244 - 120 * (1 - pst), 1.05, t))
    s += SL(Z_SRED, par(770, pol - 330 - 120 * (1 - pst), t, 4, .5, 170, .42, 1.0))
    for i in range(3):
        s += SL(Z_SRED, _kruzhka(560 + i * 150, pol - 246, .8, 0, "#f2ece0", 1))
    # венский стул и бабушка на самом краешке
    sx2 = 380
    s += SL(Z_SRED, _venskiy_stul(sx2, pol + 4, 560, t, -2.0, True))
    bst = A.ease(A.seg(t, 3.4, 1.1))
    # САЖАЕМ НА СИДЕНЬЕ: уровень сиденья венского стула = pol+4 - 560*.52
    bx, by_, bh = sx2 - 50, pol - 287 + 36 - 112 * bst, 430 + 330 * bst
    _figury_kadra((bx, by_, bh), (1004, pol + 40, 800))
    bab = figura(bx, by_, bh, t, col="#4e4a58", kant="#ffd98a", platok=True,
                 ph=.4, naklon=-2.0)
    b1, (s1x, s1y), _ = _ruka_mimo(bx, by_, bh, 1, bh * .40, 62 - 20 * bst, t,
                              "#4e4a58", "#ffd98a", .4, 3.0)
    b2, (s2x, s2y), _ = _ruka_mimo(bx, by_, bh, -1, bh * .40, 64 - 18 * bst, t,
                              "#4e4a58", "#ffd98a", .8, 3.0)
    bab += b1 + b2
    # брошь на груди
    bab += (f'<circle cx="{bx+36:.0f}" cy="{by_-bh*.56:.0f}" r="15"'
            f' fill="url(#zol)" {o(3)}/>'
            f'<circle cx="{bx+36:.0f}" cy="{by_-bh*.56:.0f}" r="6" fill="#d6452a"/>')
    s += SL(Z_SRED, bab)
    # сумочка на коленях
    # СУМОЧКА НОРМАЛЬНОГО РАЗМЕРА В ОДНОЙ РУКЕ. Задание просит «обе руки
    # держат сумочку», но `_ruka` разводит кисти наружу от оси тела, и на
    # 316 px между кистями сумочка превращалась в чемодан. Держит левая
    # (её варежка перекрывает сумочку), правая лежит на колене без кисти.
    sux, suy, sw_ = s2x + 26, s2y + 10, 178.0
    s += SL(Z_SRED, f'<rect x="{sux-sw_/2:.0f}" y="{suy-30:.0f}"'
                    f' width="{sw_:.0f}" height="104" rx="14" fill="#5a3a2c" {o(5)}/>'
            + f'<path d="M{sux-sw_*.28:.0f},{suy-30:.0f}'
              f' q{sw_*.28:.0f},-54 {sw_*.56:.0f},0" fill="none" stroke="#5a3a2c"'
              f' stroke-width="11"/>'
            + f'<rect x="{sux-18:.0f}" y="{suy-16:.0f}" width="36"'
              f' height="22" rx="6" fill="url(#zol)" {o(2)}/>'
            + f'<path d="M{sux-sw_*.42:.0f},{suy+30:.0f} q{sw_*.42:.0f},18'
              f' {sw_*.84:.0f},0" fill="none" stroke="#7d5a3c" stroke-width="7"/>')
    # хозяйка в переднике: приглашающий жест правой рукой
    hx, hy, hh = 1004, pol + 40, 800
    hoz = figura(hx, hy, hh, t, col="#3a4a44", kant="#ffd98a", ph=.9, naklon=4.0)
    zh = A.ease(A.seg(t, 2.4, 1.0))
    h1, (g1x, g1y), _ = _ruka_mimo(hx, hy, hh, -1, hh * .44, 34 - 54 * zh, t,
                              "#3a4a44", "#ffd98a", .9, 5.0)
    h2, (g2x, g2y), _ = _ruka_mimo(hx, hy, hh, 1, hh * .30, 56, t,
                              "#3a4a44", "#ffd98a", .3, 4.0)
    hoz += h1 + h2
    hoz += (f'<path d="M{hx-62:.0f},{hy-hh*.52:.0f} L{hx+62:.0f},{hy-hh*.52:.0f}'
            f' L{hx+76:.0f},{hy-hh*.08:.0f} L{hx-76:.0f},{hy-hh*.08:.0f} Z"'
            f' fill="#e8e0ca" {o(5)}/>')
    s += SL(Z_SRED, hoz)
    s += SL(Z_SRED, ten(hx, hy + 8, 178, 26, .45))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(s2x + 20, s2y + 6, bh, t, .8)
            + _varezhka(g1x, g1y, hh, t, .9))
    s += SL(Z_SRED, _pol_shvy(pol + 16, 1078, 23, 6, "#503c28"))
    # низ кадра
    s += SL(Z_SRED, _gorodskoy_hlam(96, pol + 92, 460, t, 11,
                                    ["korobka", "kust", "yaschik"])
            + _kot_zhivoy(1760, pol + 78, t, 1.05, "#3e3934", .5)
            + _valenki_u_dveri(1480, pol + 86, .82, t)
            + kartoshka(1230, pol + 96, t, 5, 6, .85))
    # ещё хрусталь: ваза с конфетами на столе, рюмки, графин и этажерка
    s += SL(Z_SRED, f'<path d="M620,{pol-246:.0f} q46,46 92,0 l-10,-56 h-72 Z"'
                    f' fill="#dbeaf4" opacity=".9" {o(4)}/>'
            + f'<ellipse cx="666" cy="{pol-300:.0f}" rx="52" ry="16"'
              f' fill="#cfe0ea" {o(3)}/>'
            + f'<path d="M940,{pol-240:.0f} q-16,-96 34,-130 q50,34 34,130 Z"'
              f' fill="#e2eef6" opacity=".92" {o(5)}/>'
            + f'<rect x="952" y="{pol-394:.0f}" width="44" height="30" rx="8"'
              f' fill="#cfe0ea" {o(3)}/>')
    for i in range(4):
        s += SL(Z_SRED, f'<path d="M{846+i*54:.0f},{pol-240:.0f}'
                        f' l24,0 l-4,-34 l6,-30 l-28,0 l6,30 Z"'
                        f' fill="#dbeaf4" opacity=".9" {o(3)}/>')
    s += SL(Z_SRED, f'<rect x="1832" y="{pol-520:.0f}" width="88" height="520"'
                    f' rx="8" fill="url(#derev)" {o(6)}/>')
    for i in range(3):
        s += SL(Z_SRED, f'<rect x="1826" y="{pol-460+i*160:.0f}" width="100"'
                        f' height="18" rx="6" fill="#6a5030" {o(4)}/>'
                f'<circle cx="1876" cy="{pol-480+i*160:.0f}" r="26"'
                f' fill="#8a9a58" opacity=".85" {o(3)}/>')
    s += SL(Z_SRED, teplo(960, 240, 520, 340, .46))
    s += SL(Z_PERED, ramka_pp("pravo"))
    s += SL(Z_LETIT, iskra_let(t, 960, 190, 5, 9, 160, .26))
    s += vinetka(.42)
    return s


def syad_ya_sama(t):
    """Кухня у мойки: гость в жилете вскочил из-за стола с тарелкой и
    прибором, хозяйка забирает у него тарелку левой рукой и указывает
    правой на стул. На столе чайник, варенье, сахарница."""
    rnd = random.Random(227)
    pol = 972
    s = f'<rect width="{W}" height="{H}" fill="#2d3135"/>'
    s += SL(Z_DAL, _kafel(760, 40, 1160, 520, t, 17, "#d0d9d9"))
    s += SL(Z_DAL, doski(0, 0, 760, pol, 92, True, "dosk"))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-8:.0f}" width="{W}" height="{H-pol+8:.0f}"'
                   f' fill="#60513f"/>' + _polovik(640, pol + 20, 760, 92))
    s += SL(Z_DAL, _polka_s_utvaryu(70, 244, 600, t, 31, 5))
    s += SL(Z_DAL, tusklaya_lampochka(1340, 170, t, 1.1, True))
    # мойка справа — главный предмет
    s += SL(Z_SRED, _moyka(900, 600, 1000, t, 19, True, .4))
    s += SL(Z_SRED, _stopka_tarelok(1760, 588, 5, t, 59, 176))
    s += SL(Z_SRED, _polotence(1858, 400, 210, t, .6, "#ded6bd", True))
    # стол слева: чайник, варенье в розетке, сахарница
    s += SL(Z_SRED, stol(70, pol - 300, 700, 36, True))
    s += SL(Z_SRED, _chaynik(220, pol - 302, 1.15, t)
            + _kruzhka(400, pol - 300, .95, 0, "#efe3d4", 1)
            + f'<path d="M520,{pol-302:.0f} q44,-26 88,0 q-10,44 -44,48'
              f' q-34,-4 -44,-48 Z" fill="#9c2f28" {o(5)}/>'
            + f'<ellipse cx="564" cy="{pol-302:.0f}" rx="44" ry="13"'
              f' fill="#c24a3a" opacity=".9"/>'
            + f'<rect x="640" y="{pol-358:.0f}" width="96" height="60" rx="12"'
              f' fill="#f0eade" {o(5)}/>'
            + f'<ellipse cx="688" cy="{pol-358:.0f}" rx="48" ry="14"'
              f' fill="#dcd4c4" {o(4)}/>')
    s += SL(Z_SRED, par(220, pol - 410, t, 4, .46, 180, .4, 1.0))
    # гость вскочил: правая нога шагнула к мойке
    sht = A.ease(A.seg(t, .3, 1.0))
    sad = A.ease(A.seg(t, 2.6, 1.2))
    gx = 620 + 150 * sht - 130 * sad
    gy, gh = pol + 36 - 80 * (1 - sad) * 0, 790 - 240 * sad
    _figury_kadra((gx, pol + 36 - 150 * sad, gh), (1180, pol + 44, 814))
    gost = figura(gx, pol + 36 - 150 * sad, gh, t, col="#4a4a56", kant="#ffd98a",
                  boroda=True, ph=.2, naklon=7 - 10 * sad)
    g1, (t1x, t1y), _ = _ruka_mimo(gx, pol + 36 - 150 * sad, gh, 1, gh * .44,
                              22 + 24 * sad, t, "#4a4a56", "#ffd98a", .2, 5.0)
    g2, (t2x, t2y), _ = _ruka_mimo(gx, pol + 36 - 150 * sad, gh, -1, gh * .36,
                              34 + 20 * sad, t, "#4a4a56", "#ffd98a", .6, 5.0)
    gost += g1 + g2
    # жилет поверх рубахи
    gost += (f'<path d="M{gx-54:.0f},{pol+36-150*sad-gh*.58:.0f}'
             f' L{gx-18:.0f},{pol+36-150*sad-gh*.56:.0f}'
             f' L{gx-24:.0f},{pol+36-150*sad-gh*.18:.0f}'
             f' L{gx-62:.0f},{pol+36-150*sad-gh*.20:.0f} Z" fill="#33333d" {o(4)}/>'
             f'<path d="M{gx+54:.0f},{pol+36-150*sad-gh*.58:.0f}'
             f' L{gx+18:.0f},{pol+36-150*sad-gh*.56:.0f}'
             f' L{gx+24:.0f},{pol+36-150*sad-gh*.18:.0f}'
             f' L{gx+62:.0f},{pol+36-150*sad-gh*.20:.0f} Z" fill="#33333d" {o(4)}/>')
    s += SL(Z_SRED, gost)
    # хозяйка у мойки: левая забирает тарелку, правая указывает на стул
    hx, hy, hh = 1180, pol + 44, 814
    hoz = figura(hx, hy, hh, t, col="#3f4a58", kant="#ffd98a", platok=True,
                 ph=.7, naklon=-3.0)
    h1, (z1x, z1y), _ = _ruka_mimo(hx, hy, hh, -1, hh * .44, 30, t,
                              "#3f4a58", "#ffd98a", .7, 5.0)
    h2, (z2x, z2y), _ = _ruka_mimo(hx, hy, hh, 1, hh * .42, 18 + 34 * sad, t,
                              "#3f4a58", "#ffd98a", .3, 4.0)
    hoz += h1 + h2
    s += SL(Z_SRED, hoz)
    # тарелка переходит из руки гостя в руку хозяйки
    per = A.ease(A.seg(t, 1.5, 1.1))
    pxx = t1x + (z1x - t1x) * per
    pyy = t1y + (z1y - t1y) * per
    s += SL(Z_SRED, _tarelka(pxx, pyy, 78, t, .2, False, -10 + 12 * per))
    # вилка и нож в левой руке гостя
    s += SL(Z_SRED, f'<g transform="rotate({-18 + 4 * A.w(t, 2.0, .3):.1f}'
                    f' {t2x:.0f} {t2y:.0f})">'
                    f'<rect x="{t2x-8:.0f}" y="{t2y-96:.0f}" width="16" height="106"'
                    f' rx="6" fill="#b9c4c9" {o(3)}/>'
            + f'<rect x="{t2x+18:.0f}" y="{t2y-88:.0f}" width="14" height="98" rx="6"'
              f' fill="#cfd8dc" {o(3)}/></g>')
    # стул, на который указывают и куда гость садится
    s += SL(Z_SRED, _venskiy_stul(448, pol + 6, 540, t, 1.5, False))
    s += SL(Z_SRED, ten(hx, hy + 8, 180, 26, .45))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(t2x, t2y, gh, t, .6)
            + _varezhka(z1x, z1y, hh, t, .7) + _varezhka(z2x, z2y, hh, t, .3))
    s += SL(Z_SRED, _pol_shvy(pol + 10, 1078, 29, 6, "#463a2c"))
    # низ кадра
    s += SL(Z_SRED, _dvorovaya_utvar(1560, pol + 84, 340, t, 43, ["vedro", "korob"])
            + _yaschiki(70, pol + 80, t, 13, 2, .78)
            + _kot_zhivoy(880, pol + 70, t, 1.0, "#423b35", .9)
            + kartoshka(1400, pol + 96, t, 6, 6, .95))
    s += SL(Z_PERED, _stolb_pered(1870, 76, "#191310", 0, H))
    s += SL(Z_LETIT, _pena_gorka(1260, 700, 70, t, 61, 5, .4))
    s += vinetka(.42)
    return s


def pero_nad_bumagoy(t):
    """Письменный стол: лист с пустой строкой внизу, чернильница,
    пресс-папье, очки, свеча. Видна правая рука до локтя: держит перо над
    строкой, капля набухает на кончике, потом перо уходит в чернильницу."""
    rnd = random.Random(229)
    s = f'<rect width="{W}" height="{H}" fill="#1d1a16"/>'
    s += SL(Z_DAL, doski(0, 0, 1240, 690, 104, True, "dosk"))
    s += SL(Z_DAL, doski(1240, 0, 680, 690, 104, True, "dosk"))
    s += SL(Z_DAL, _polka_s_utvaryu(1300, 232, 560, t, 37, 4))
    s += SL(Z_DAL, _knizhnaya_polka(130, 300, 740, t, 41, 2, 206))
    s += SL(Z_DAL, _ramki_na_stene(950, 120, 330, t, 43, 2))
    s += SL(Z_DAL, f'<rect x="0" y="672" width="{W}" height="36" rx="8"'
                   f' fill="#4a3522" {o(5)}/>')
    # СТОЛ — главный предмет
    s += SL(Z_SRED, _pismennyy_stol(300, H + 60, 1340, t, 420))
    stol_y = H + 60 - 420
    # свеча — единственное тёплое пятно
    s += SL(Z_SRED, f'<rect x="1398" y="{stol_y-34:.0f}" width="86" height="34"'
                    f' rx="12" fill="url(#zhel)" {o(5)}/>')
    s += SL(Z_SRED, svecha(1440, stol_y - 150, t, .2, 1.5, 120))
    # лист бумаги с пустой строкой
    s += SL(Z_SRED, _list_bumagi(620, stol_y - 26, 560, 330, t, -3.0, 5, True))
    # чернильница, пресс-папье, очки, песочница
    s += SL(Z_SRED, _chernilnica(1260, stol_y - 10, 1.5, t))
    s += SL(Z_SRED, f'<path d="M418,{stol_y-10:.0f} q86,-74 172,0 Z"'
                    f' fill="#6a5030" {o(6)}/>'
            + f'<rect x="400" y="{stol_y-16:.0f}" width="208" height="22" rx="8"'
              f' fill="#8a6a44" {o(5)}/>'
            + f'<rect x="478" y="{stol_y-106:.0f}" width="52" height="40" rx="10"'
              f' fill="url(#zhel)" {o(4)}/>')
    s += SL(Z_SRED, _ochki(390, stol_y - 148, 1.25, t))
    # свитки, папки и стакан с ручками — обжитой стол конторщика
    s += SL(Z_SRED, _svitki_i_papki(640, stol_y - 14, t, 5, 4))
    s += SL(Z_SRED, f'<path d="M1556,{stol_y-10:.0f} L1664,{stol_y-10:.0f}'
                    f' L1652,{stol_y-128:.0f} L1568,{stol_y-128:.0f} Z"'
                    f' fill="#5e676e" {o(5)}/>')
    for i in range(5):
        s += SL(Z_SRED, f'<line x1="{1584+i*20:.0f}" y1="{stol_y-120:.0f}"'
                        f' x2="{1572+i*26:.0f}" y2="{stol_y-250-i*14:.0f}"'
                        f' stroke="{["#8a6a44","#6a5030","#9c7a4c","#7b5c38","#5b4428"][i]}"'
                        f' stroke-width="13" stroke-linecap="round"/>')
    s += SL(Z_SRED, f'<ellipse cx="1140" cy="{stol_y-16:.0f}" rx="72" ry="20"'
                    f' fill="#b9a988" {o(4)}/>'
            + f'<path d="M1082,{stol_y-24:.0f} q58,-40 116,0" fill="none"'
              f' stroke="#cdbf9c" stroke-width="10"/>')
    # ПРАВАЯ РУКА ДО ЛОКТЯ — ничья: человека в кадре нет
    otv = A.ease(A.seg(t, 1.3, 1.2))
    kist_x = 980 + (1260 - 980) * otv
    kist_y = stol_y - 230 + 180 * otv
    # предплечье лежит НА СТОЛЕШНИЦЕ: от правого края кадра к листу, и
    # опора видна — манжета на доске (осмотр порции 2: перо висело в воздухе)
    ruk, (ex, ey) = rukav(1900, stol_y + 120, 700, -168 + 14 * otv, t,
                          "#4a4450", "#ffd98a", .2, 3.0, True)
    s += SL(Z_SRED, ruk)
    s += SL(Z_SRED, f'<rect x="{ex+30:.0f}" y="{ey+6:.0f}" width="170" height="52"'
                    f' rx="20" fill="#4a4450" {o(5)}/>'
            + f'<path d="M{ex+40:.0f},{ey+16:.0f} q80,18 150,6" fill="none"'
              f' stroke="#f2e4d0" stroke-width="9" opacity=".7"/>'
            + ten(ex + 90, stol_y - 8, 130, 18, .45))
    # перо в кисти: висит над пустой строкой, капля набухает
    kap = .3 + .7 * abs(A.w(t, 1.9, .1)) * (1 - otv)
    # перо: кончик стоит над пустой строкой листа, потом уходит в чернильницу
    perx = ex + 6 + (1260 - ex - 6) * otv
    pery = ey + 6 + (stol_y - 60 - ey - 6) * otv
    s += SL(Z_SRED, _pero_pisma(perx, pery, t, 1.3, -26 + 22 * otv, kap))
    s += SL(Z_SRED, _varezhka(perx - 4, pery - 8, 760, t, .2))
    s += SL(Z_SRED, ten(perx + 10, stol_y - 14, 110, 20, .4))
    s += SL(Z_SRED, _konus_sveta(1440, stol_y - 180, 620, 330, 8, .42))
    s += SL(Z_SRED, _pol_shvy(730, 1070, 31, 6, "#3a2a1a"))
    # нижняя треть: сундучок, корзина с бумагами, кот, ведро для бумаг
    s += SL(Z_PERED, _yaschiki(96, 1072, t, 17, 2, .92)
            + _dvorovaya_utvar(1560, 1066, 340, t, 47, ["korzina", "korob"])
            + _kot_zhivoy(1340, 1060, t, 1.15, "#3a332e", .4, True, True))
    s += SL(Z_SRED, teplo(1440, stol_y - 180, 520, 430, .42))
    s += SL(Z_PERED, _stolb_pered(-8, 104, "#140f0c", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 1440, stol_y - 230, 6, 3, 220, .4))
    s += vinetka(.44)
    return s


# ── ПОМОЩНИКИ ВТОРОЙ ПАРТИИ ────────────────────────────────────────────────

def _stolb_pogranichnyy(x, y, h_, t, w_=96):
    """Полосатый пограничный столб: косые полосы, железная шляпка, скоба,
    у основания насыпь камней. Качается от ветра самую малость."""
    kach = .8 * A.w(t, 5.2, .1)
    s = (f'<g transform="rotate({kach:.2f} {x:.0f} {y:.0f})">'
         f'{ten(x, y + 8, w_ * .9, 20, .5)}'
         f'<rect x="{x-w_/2:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="10" fill="#efe8da" {o(7)}/>')
    n = int(h_ / 92)
    for i in range(n):
        if i % 2 == 0:
            continue
        yy = y - h_ + i * 92
        s += (f'<path d="M{x-w_/2:.0f},{yy+76:.0f} L{x-w_/2:.0f},{yy+16:.0f}'
              f' L{x+w_/2:.0f},{yy-28:.0f} L{x+w_/2:.0f},{yy+32:.0f} Z"'
              f' fill="#b8352c" opacity=".92"/>')
    s += (f'<path d="M{x-w_*.72:.0f},{y-h_:.0f} L{x+w_*.72:.0f},{y-h_:.0f}'
          f' L{x+w_*.5:.0f},{y-h_-34:.0f} L{x-w_*.5:.0f},{y-h_-34:.0f} Z"'
          f' fill="{ZHELEZ}" {o(5)}/>'
          f'<rect x="{x-w_*.56:.0f}" y="{y-h_*.52:.0f}" width="{w_*1.12:.0f}"'
          f' height="22" rx="8" fill="#6a7278" {o(4)}/></g>')
    rnd = random.Random(int(x))
    for i in range(7):
        rr = rnd.uniform(22, 44)
        s += (f'<ellipse cx="{x+rnd.uniform(-110, 110):.0f}" cy="{y+rnd.uniform(-6, 22):.0f}"'
              f' rx="{rr:.0f}" ry="{rr*.6:.0f}" fill="#6a6256" {o(3)}/>')
    return s


def _stog(x, y, s_=1.0, t=0.0, kol=True):
    """Стог сена: шапка из соломы прядями, жердь по центру, подпорки и
    растрёпанный низ. Рыжая осень в кадре."""
    h2, w2 = 330 * s_, 400 * s_
    s = (f'{ten(x, y + 10, w2 * .52, 24, .45)}'
         f'<path d="M{x-w2/2:.0f},{y:.0f} q{w2*.10:.0f},{-h2*.82:.0f}'
         f' {w2*.5:.0f},{-h2:.0f} q{w2*.40:.0f},{h2*.18:.0f} {w2*.5:.0f},{h2:.0f} Z"'
         f' fill="url(#solom)" {o(6)}/>')
    rnd = random.Random(int(x) + 3)
    for i in range(22):
        px = x + rnd.uniform(-w2 * .46, w2 * .46)
        py = y - rnd.uniform(0, h2 * .86)
        dl = rnd.uniform(40, 96) * s_
        s += (f'<line x1="{px:.0f}" y1="{py:.0f}" x2="{px+dl*.5:.0f}"'
              f' y2="{py+dl*.4:.0f}" stroke="#b08a3c" stroke-width="5"'
              f' opacity=".8"/>')
    if kol:
        s += (f'<line x1="{x:.0f}" y1="{y-h2-50*s_:.0f}" x2="{x:.0f}" y2="{y:.0f}"'
              f' stroke="url(#derev)" stroke-width="{16*s_:.0f}"/>'
              f'<line x1="{x-w2*.42:.0f}" y1="{y:.0f}" x2="{x-w2*.18:.0f}"'
              f' y2="{y-h2*.52:.0f}" stroke="#5e472e" stroke-width="{11*s_:.0f}"/>')
    return s


def _snegovik(x, y, s_=1.0, t=0.0):
    """Снеговик: три кома с инеем, ведро на голове, угольки, морковь,
    веточки-руки и шарф, который чуть шевелится."""
    kach = 3.0 * A.w(t, 3.6, .2)
    r1, r2, r3 = 104 * s_, 76 * s_, 54 * s_
    y1 = y - r1
    y2 = y1 - r1 * .76 - r2 * .5
    y3 = y2 - r2 * .72 - r3 * .5
    s = (f'{ten(x, y + 6, r1 * 1.1, 20, .45)}'
         f'<circle cx="{x:.0f}" cy="{y1:.0f}" r="{r1:.0f}" fill="url(#sneg)" {o(6)}/>'
         f'<circle cx="{x:.0f}" cy="{y2:.0f}" r="{r2:.0f}" fill="url(#sneg)" {o(6)}/>'
         f'<circle cx="{x:.0f}" cy="{y3:.0f}" r="{r3:.0f}" fill="url(#sneg)" {o(6)}/>')
    for i in range(3):
        s += (f'<circle cx="{x:.0f}" cy="{y2-r2*.3+i*r2*.4:.0f}" r="{9*s_:.0f}"'
              f' fill="{CHUGUN}"/>')
    for i in (-1, 1):
        s += (f'<circle cx="{x+i*r3*.38:.0f}" cy="{y3-r3*.18:.0f}" r="{8*s_:.0f}"'
              f' fill="{CHUGUN}"/>')
    s += (f'<path d="M{x+r3*.1:.0f},{y3+r3*.06:.0f} l{54*s_:.0f},{14*s_:.0f}'
          f' l{-50*s_:.0f},{14*s_:.0f} Z" fill="#d87a2c" {o(3)}/>'
          f'<path d="M{x-r3*.9:.0f},{y3-r3*.62:.0f} L{x+r3*.9:.0f},{y3-r3*.62:.0f}'
          f' L{x+r3*.72:.0f},{y3-r3*1.5:.0f} L{x-r3*.72:.0f},{y3-r3*1.5:.0f} Z"'
          f' fill="#5e676e" {o(5)}/>'
          f'<ellipse cx="{x:.0f}" cy="{y3-r3*1.5:.0f}" rx="{r3*.74:.0f}"'
          f' ry="{r3*.16:.0f}" fill="#49535b" {o(4)}/>')
    for i in (-1, 1):
        s += (f'<line x1="{x+i*r2*.9:.0f}" y1="{y2:.0f}" x2="{x+i*(r2*.9+78*s_):.0f}"'
              f' y2="{y2-54*s_:.0f}" stroke="#4e3a26" stroke-width="{10*s_:.0f}"'
              f' stroke-linecap="round"/>'
              f'<line x1="{x+i*(r2*.9+46*s_):.0f}" y1="{y2-28*s_:.0f}"'
              f' x2="{x+i*(r2*.9+68*s_):.0f}" y2="{y2-72*s_:.0f}" stroke="#4e3a26"'
              f' stroke-width="{7*s_:.0f}"/>')
    s += (f'<g transform="rotate({kach:.1f} {x:.0f} {y3+r3*.8:.0f})">'
          f'<rect x="{x-r3*1.0:.0f}" y="{y3+r3*.7:.0f}" width="{r3*2.0:.0f}"'
          f' height="{22*s_:.0f}" rx="9" fill="{TKAN}" {o(4)}/>'
          f'<path d="M{x+r3*.7:.0f},{y3+r3*.9:.0f} q{22*s_:.0f},{44*s_:.0f}'
          f' {4*s_:.0f},{78*s_:.0f} l{-28*s_:.0f},{-8*s_:.0f}'
          f' q{14*s_:.0f},{-34*s_:.0f} {-4*s_:.0f},{-64*s_:.0f} Z"'
          f' fill="{TKAN}" {o(3)}/></g>')
    return s


def _sani(x, y, s_=1.0, t=0.0, gruz=True):
    """Сани-розвальни: два полоза с загибом, вязки, борт из прутьев,
    охапка сена и верёвка. Стоят на снегу."""
    s = (f'{ten(x, y + 8, 180 * s_, 18, .4)}')
    for i, dy in enumerate((0, -26 * s_)):
        s += (f'<path d="M{x-180*s_:.0f},{y+dy:.0f} L{x+140*s_:.0f},{y+dy:.0f}'
              f' q{50*s_:.0f},{-4*s_:.0f} {56*s_:.0f},{-48*s_:.0f}"'
              f' fill="none" stroke="#5b4428" stroke-width="{16*s_:.0f}"'
              f' stroke-linecap="round"/>')
    for i in range(4):
        px = x - 150 * s_ + i * 96 * s_
        s += (f'<line x1="{px:.0f}" y1="{y:.0f}" x2="{px:.0f}" y2="{y-82*s_:.0f}"'
              f' stroke="#6a5030" stroke-width="{13*s_:.0f}"/>')
    s += (f'<rect x="{x-174*s_:.0f}" y="{y-96*s_:.0f}" width="{330*s_:.0f}"'
          f' height="{22*s_:.0f}" rx="9" fill="url(#derev)" {o(4)}/>')
    for i in range(7):
        px = x - 160 * s_ + i * 52 * s_
        s += (f'<path d="M{px:.0f},{y-96*s_:.0f} q{-10*s_:.0f},{-44*s_:.0f}'
              f' {6*s_:.0f},{-76*s_:.0f}" fill="none" stroke="#6a5030"'
              f' stroke-width="{8*s_:.0f}"/>')
    if gruz:
        s += (f'<path d="M{x-150*s_:.0f},{y-168*s_:.0f} q{80*s_:.0f},{-60*s_:.0f}'
              f' {160*s_:.0f},{-20*s_:.0f} q{70*s_:.0f},{26*s_:.0f}'
              f' {60*s_:.0f},{54*s_:.0f} Z" fill="url(#solom)" {o(5)}/>')
        for i in range(9):
            s += (f'<line x1="{x-130*s_+i*34*s_:.0f}" y1="{y-170*s_:.0f}"'
                  f' x2="{x-110*s_+i*34*s_:.0f}" y2="{y-214*s_:.0f}"'
                  f' stroke="#b08a3c" stroke-width="{5*s_:.0f}" opacity=".85"/>')
        s += (f'<path d="M{x-150*s_:.0f},{y-150*s_:.0f} q{150*s_:.0f},{40*s_:.0f}'
              f' {300*s_:.0f},{-16*s_:.0f}" fill="none" stroke="#8a7a58"'
              f' stroke-width="{7*s_:.0f}"/>')
    return s


def _svyazka_klyuchey(x, y, t, s_=1.0, ph=.0, n=4):
    """Связка ключей на кольце: кольцо, бородки разной формы, качается."""
    kach = 10 * A.w(t, 1.5, ph)
    s = (f'<g transform="rotate({kach:.1f} {x:.0f} {y:.0f})">'
         f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{30*s_:.0f}" fill="none"'
         f' stroke="url(#zhel)" stroke-width="{11*s_:.0f}"/>')
    for i in range(n):
        a = math.radians(58 + i * (64.0 / max(1, n - 1)))
        kx = x + 26 * s_ * math.cos(a)
        ky = y + 26 * s_ * math.sin(a)
        dl = (96 + i * 16) * s_
        ex = kx + dl * math.cos(a)
        ey = ky + dl * math.sin(a)
        s += (f'<line x1="{kx:.0f}" y1="{ky:.0f}" x2="{ex:.0f}" y2="{ey:.0f}"'
              f' stroke="url(#zhel)" stroke-width="{10*s_:.0f}"'
              f' stroke-linecap="round"/>'
              f'<rect x="{ex-16*s_:.0f}" y="{ey-6*s_:.0f}" width="{30*s_:.0f}"'
              f' height="{26*s_:.0f}" rx="4" fill="url(#zhel)" {o(3)}/>'
              f'<rect x="{ex-6*s_:.0f}" y="{ey+4*s_:.0f}" width="{14*s_:.0f}"'
              f' height="{10*s_:.0f}" fill="#7a4d1c"/>'
              f'<circle cx="{kx:.0f}" cy="{ky:.0f}" r="{12*s_:.0f}" fill="none"'
              f' stroke="url(#zhel)" stroke-width="{6*s_:.0f}"/>')
    return s + "</g>"


def _krovat(x, y, w_, t, seed=5, loskut=True, h_=300):
    """Кровать: высокая спинка с шишечками, лоскутное покрывало квадратами,
    подзор по низу и тень под ней."""
    rnd = random.Random(seed)
    s = (f'{ten(x + w_ / 2, y + 10, w_ * .46, 22, .5)}'
         f'<rect x="{x:.0f}" y="{y-h_-170:.0f}" width="40" height="{h_+170:.0f}"'
         f' rx="12" fill="#5b4428" {o(5)}/>'
         f'<rect x="{x+w_-40:.0f}" y="{y-h_-110:.0f}" width="40" height="{h_+110:.0f}"'
         f' rx="12" fill="#5b4428" {o(5)}/>'
         f'<rect x="{x:.0f}" y="{y-h_-170:.0f}" width="{w_*.34:.0f}" height="30"'
         f' rx="11" fill="#6a5030" {o(4)}/>'
         f'<circle cx="{x+20:.0f}" cy="{y-h_-182:.0f}" r="22" fill="url(#zhel)" {o(4)}/>'
         f'<circle cx="{x+w_-20:.0f}" cy="{y-h_-122:.0f}" r="20" fill="url(#zhel)" {o(4)}/>'
         f'<rect x="{x+16:.0f}" y="{y-h_:.0f}" width="{w_-32:.0f}" height="{h_*.52:.0f}"'
         f' rx="16" fill="#cdbfa4" {o(6)}/>')
    if loskut:
        cols = ["#8a4a44", "#3f5c7a", "#8a6a2c", "#4a6a48", "#7a5a62", "#b0864a"]
        kk = 86
        for r in range(int(h_ * .50 / kk) + 1):
            for c in range(int((w_ - 40) / kk)):
                s += (f'<rect x="{x+24+c*kk:.0f}" y="{y-h_+8+r*kk:.0f}"'
                      f' width="{kk-8}" height="{kk-8}" rx="6"'
                      f' fill="{cols[(r*3+c) % len(cols)]}" stroke="{K}"'
                      f' stroke-width="3" opacity=".92"/>')
    s += (f'<path d="M{x+16:.0f},{y-h_+h_*.52:.0f} L{x+w_-16:.0f},{y-h_+h_*.52:.0f}'
          f' L{x+w_-26:.0f},{y:.0f} L{x+26:.0f},{y:.0f} Z" fill="#e8e0ca" {o(5)}/>')
    for i in range(int((w_ - 60) / 54)):
        s += (f'<path d="M{x+40+i*54:.0f},{y-h_*.30:.0f} q{14:.0f},{30:.0f}'
              f' {0:.0f},{h_*.26:.0f}" fill="none" stroke="#cdc5ae"'
              f' stroke-width="6" opacity=".85"/>')
    return s


def _podushka(x, y, w_, h_, t, ph=.0, pod=.0, hlop=.0):
    """Пуховая подушка: наволочка с мережкой, вдавленный угол, приподнятый
    край (pod 0..1) и хлопок ладонями (hlop 0..1 сплющивает)."""
    lift = 54 * pod
    sq = 1.0 - .14 * hlop
    return (f'<g transform="translate(0,{lift * .2:.1f})">'
            f'{ten(x, y + h_ * .5 + 10, w_ * .46, 16, .4)}'
            f'<path d="M{x-w_/2:.0f},{y+h_*sq*.5:.0f}'
            f' q{-28:.0f},{-h_*sq*.62:.0f} {46:.0f},{-h_*sq*.86:.0f}'
            f' q{w_*.44:.0f},{-26-lift:.0f} {w_*.86:.0f},{4-lift*.4:.0f}'
            f' q{70:.0f},{h_*sq*.26:.0f} {38:.0f},{h_*sq*.82:.0f}'
            f' q{-w_*.44:.0f},{36:.0f} {-w_*.92:.0f},0 Z"'
            f' fill="#f2ece0" {o(6)}/>'
            f'<path d="M{x-w_*.38:.0f},{y+h_*sq*.34:.0f}'
            f' q{w_*.38:.0f},{26:.0f} {w_*.76:.0f},{-6:.0f}" fill="none"'
            f' stroke="#d8d0bc" stroke-width="7"/>'
            f'<path d="M{x-w_*.34:.0f},{y-h_*sq*.28:.0f}'
            f' q{w_*.18:.0f},{-20:.0f} {w_*.36:.0f},{-4:.0f}" fill="none"'
            f' stroke="#e4dcc8" stroke-width="9" opacity=".9"/>'
            f'<path d="M{x+w_*.20:.0f},{y-h_*sq*.42:.0f}'
            f' q{w_*.12:.0f},{16:.0f} {w_*.04:.0f},{34:.0f}" fill="none"'
            f' stroke="#ddd5c2" stroke-width="6"/></g>')


def _bumaga_znachok(x, y, s_=1.0, vid="ruka", ug=0.0):
    """Бумага со значком вместо текста (своих букв не рисуем): рукопожатие,
    галочка, черта-отказ, перо. Лист с уголком и печатью."""
    w2, h2 = 150 * s_, 196 * s_
    s = (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
         f'<path d="M{x-w2/2:.0f},{y-h2:.0f} L{x+w2/2-22*s_:.0f},{y-h2:.0f}'
         f' L{x+w2/2:.0f},{y-h2+22*s_:.0f} L{x+w2/2:.0f},{y:.0f}'
         f' L{x-w2/2:.0f},{y:.0f} Z" fill="#f4efe0" {o(5)}/>'
         f'<path d="M{x+w2/2-22*s_:.0f},{y-h2:.0f} L{x+w2/2:.0f},{y-h2+22*s_:.0f}'
         f' L{x+w2/2-22*s_:.0f},{y-h2+22*s_:.0f} Z" fill="#ddd5c2" {o(2)}/>')
    cx, cy = x, y - h2 * .54
    if vid == "ruka":
        s += (f'<path d="M{cx-44*s_:.0f},{cy+12*s_:.0f} l{40*s_:.0f},{-26*s_:.0f}'
              f' l{48*s_:.0f},{10*s_:.0f} l{-40*s_:.0f},{28*s_:.0f} Z"'
              f' fill="#8a6a44" {o(4)}/>'
              f'<rect x="{cx-62*s_:.0f}" y="{cy+6*s_:.0f}" width="{34*s_:.0f}"'
              f' height="{18*s_:.0f}" rx="8" fill="#6a5030" {o(3)}/>'
              f'<rect x="{cx+34*s_:.0f}" y="{cy-22*s_:.0f}" width="{34*s_:.0f}"'
              f' height="{18*s_:.0f}" rx="8" fill="#6a5030" {o(3)}/>')
    elif vid == "galka":
        s += (f'<path d="M{cx-40*s_:.0f},{cy:.0f} L{cx-10*s_:.0f},{cy+32*s_:.0f}'
              f' L{cx+46*s_:.0f},{cy-40*s_:.0f}" fill="none" stroke="#3f7a44"'
              f' stroke-width="{16*s_:.0f}" stroke-linecap="round"/>')
    elif vid == "cherta":
        s += (f'<line x1="{cx-46*s_:.0f}" y1="{cy:.0f}" x2="{cx+46*s_:.0f}"'
              f' y2="{cy:.0f}" stroke="#9c2f28" stroke-width="{17*s_:.0f}"'
              f' stroke-linecap="round"/>')
    else:
        s += (f'<path d="M{cx+18*s_:.0f},{cy+34*s_:.0f} L{cx-12*s_:.0f},{cy-40*s_:.0f}'
              f' L{cx+4*s_:.0f},{cy-44*s_:.0f} L{cx+32*s_:.0f},{cy+30*s_:.0f} Z"'
              f' fill="#efe8da" {o(4)}/>'
              f'<line x1="{cx-6*s_:.0f}" y1="{cy-26*s_:.0f}" x2="{cx-34*s_:.0f}"'
              f' y2="{cy-36*s_:.0f}" stroke="#d8cfbd" stroke-width="{6*s_:.0f}"/>')
    s += (f'<circle cx="{x+w2*.26:.0f}" cy="{y-h2*.16:.0f}" r="{20*s_:.0f}"'
          f' fill="#9c2f28" opacity=".85" {o(2)}/>'
          f'<path d="M{x-w2*.32:.0f},{y-h2*.18:.0f} q{w2*.14:.0f},{-8*s_:.0f}'
          f' {w2*.28:.0f},0" fill="none" stroke="#6b6354" stroke-width="{5*s_:.0f}"/></g>')
    return s


def _vesy(x, y, t, s_=1.0, levo=.0, dreb=.0, h_=300):
    """Чашечные весы: чугунное основание, колонка, коромысло со стрелкой,
    две чаши на тройных цепях. levo −1..1 — перекос, dreb 0..1 — дрожь."""
    kren = levo * 11 + dreb * 7 * A.w(t, .22, .1)
    bal = 300 * s_
    s = (f'{ten(x, y + 8, 150 * s_, 20, .5)}'
         f'<path d="M{x-120*s_:.0f},{y:.0f} L{x+120*s_:.0f},{y:.0f}'
         f' L{x+86*s_:.0f},{y-34*s_:.0f} L{x-86*s_:.0f},{y-34*s_:.0f} Z"'
         f' fill="{CHUGUN}" {o(6)}/>'
         f'<rect x="{x-22*s_:.0f}" y="{y-h_*s_:.0f}" width="{44*s_:.0f}"'
         f' height="{h_*s_:.0f}" rx="14" fill="#5e676e" {o(6)}/>'
         f'<circle cx="{x:.0f}" cy="{y-h_*s_:.0f}" r="{30*s_:.0f}"'
         f' fill="url(#zhel)" {o(5)}/>')
    s += (f'<g transform="rotate({kren:.2f} {x:.0f} {y-h_*s_:.0f})">'
          f'<rect x="{x-bal:.0f}" y="{y-h_*s_-13*s_:.0f}" width="{bal*2:.0f}"'
          f' height="{26*s_:.0f}" rx="12" fill="url(#zhel)" {o(5)}/>'
          f'<path d="M{x:.0f},{y-h_*s_:.0f} l{-16*s_:.0f},{-76*s_:.0f}'
          f' l{32*s_:.0f},0 Z" fill="#8a5a22" {o(4)}/>')
    for sgn in (-1, 1):
        px = x + sgn * bal
        for k in (-.5, 0, .5):
            s += (f'<line x1="{px:.0f}" y1="{y-h_*s_:.0f}"'
                  f' x2="{px+k*76*s_:.0f}" y2="{y-h_*s_+112*s_:.0f}"'
                  f' stroke="#8a6a3c" stroke-width="{5*s_:.0f}"/>')
        s += (f'<path d="M{px-88*s_:.0f},{y-h_*s_+112*s_:.0f}'
              f' q{88*s_:.0f},{68*s_:.0f} {176*s_:.0f},0 Z" fill="url(#zhel)" {o(5)}/>'
              f'<ellipse cx="{px:.0f}" cy="{y-h_*s_+112*s_:.0f}" rx="{88*s_:.0f}"'
              f' ry="{18*s_:.0f}" fill="#d6a358" opacity=".85"/>')
    return s + "</g>"


def _veshalka_s_paltom(x, y, w_, t, seed=3):
    """Вешалка прихожей: планка с крючками, два пальто и плащ складками,
    шапка на верхней полке, зонт на крайнем крюке."""
    rnd = random.Random(seed)
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="34" rx="10"'
         f' fill="url(#dosk)" {o(6)}/>'
         f'<rect x="{x+10:.0f}" y="{y-56:.0f}" width="{w_-20:.0f}" height="26" rx="9"'
         f' fill="#6a5030" {o(5)}/>')
    for i in range(5):
        hx = x + 56 + i * (w_ - 120) / 4.0
        s += (f'<path d="M{hx:.0f},{y+34:.0f} q{6:.0f},{26:.0f} {-16:.0f},{30:.0f}"'
              f' fill="none" stroke="{ZHELEZ}" stroke-width="10"/>')
    cols = ["#3f4a58", "#5a3a2c", "#4a5a46"]
    for i in range(3):
        px = x + 110 + i * (w_ - 240) / 2.0
        hh = rnd.uniform(390, 470)
        s += (f'<path d="M{px-78:.0f},{y+70:.0f} q{78:.0f},{-44:.0f} {156:.0f},0'
              f' L{px+96:.0f},{y+hh:.0f} q{-96:.0f},{34:.0f} {-192:.0f},0 Z"'
              f' fill="{cols[i]}" {o(6)}/>'
              f'<line x1="{px:.0f}" y1="{y+84:.0f}" x2="{px:.0f}" y2="{y+hh:.0f}"'
              f' stroke="{K}" stroke-width="5" opacity=".6"/>')
        for k in range(3):
            s += (f'<circle cx="{px+14:.0f}" cy="{y+150+k*78:.0f}" r="11"'
                  f' fill="#d8c08a" {o(2)}/>')
    s += (f'<ellipse cx="{x+w_-80:.0f}" cy="{y-70:.0f}" rx="62" ry="28"'
          f' fill="#4a3a2c" {o(5)}/>'
          f'<path d="M{x+w_-130:.0f},{y-74:.0f} q{50:.0f},{-44:.0f} {100:.0f},0 Z"'
          f' fill="#5a4636" {o(4)}/>')
    return s


def _zont_v_podstavke(x, y, t, s_=1.0):
    """Зонт в подставке: тулья сложена, спицы, ручка крюком, латунное
    ведёрко с каплями на дне."""
    kach = 1.6 * A.w(t, 4.4, .3)
    return (f'<g transform="rotate({kach:.2f} {x:.0f} {y:.0f})">'
            f'{ten(x, y + 6, 46 * s_, 11, .4)}'
            f'<path d="M{x-44*s_:.0f},{y:.0f} L{x+44*s_:.0f},{y:.0f}'
            f' L{x+38*s_:.0f},{y-130*s_:.0f} L{x-38*s_:.0f},{y-130*s_:.0f} Z"'
            f' fill="url(#zhel)" {o(5)}/>'
            f'<ellipse cx="{x:.0f}" cy="{y-130*s_:.0f}" rx="{38*s_:.0f}"'
            f' ry="{11*s_:.0f}" fill="#8a5a22" {o(3)}/>'
            f'<path d="M{x-16*s_:.0f},{y-126*s_:.0f} q{-10*s_:.0f},{-150*s_:.0f}'
            f' {16*s_:.0f},{-230*s_:.0f} q{28*s_:.0f},{78*s_:.0f} {18*s_:.0f},{230*s_:.0f} Z"'
            f' fill="#3f4a58" {o(5)}/>'
            f'<line x1="{x+2*s_:.0f}" y1="{y-356*s_:.0f}" x2="{x+2*s_:.0f}"'
            f' y2="{y-120*s_:.0f}" stroke="#6a7278" stroke-width="{7*s_:.0f}"/>'
            f'<path d="M{x+2*s_:.0f},{y-356*s_:.0f} q{30*s_:.0f},{-34*s_:.0f}'
            f' {44*s_:.0f},{4*s_:.0f}" fill="none" stroke="#5b4428"'
            f' stroke-width="{13*s_:.0f}"/>'
            f'<ellipse cx="{x-10*s_:.0f}" cy="{y-10*s_:.0f}" rx="{20*s_:.0f}"'
            f' ry="{7*s_:.0f}" fill="#7e97ad" opacity=".7"/></g>')


def _chislennik(x, y, w_, h_, t, otryv=.0):
    """Отрывной численник: щиток с жестяной шапкой, толстый блок листков
    торцом, верхний листок пустой (цифру кладёт надпись поверх) и
    волнистая строка под ним. Листок шевелится."""
    kach = 1.8 * A.w(t, 2.6, .2)
    s = (f'{ten(x + w_ / 2, y + h_ + 14, w_ * .4, 14, .35)}'
         f'<rect x="{x-18:.0f}" y="{y-18:.0f}" width="{w_+36:.0f}"'
         f' height="{h_+36:.0f}" rx="12" fill="#6a5030" {o(6)}/>'
         f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}" rx="8"'
         f' fill="#b8352c" {o(5)}/>'
         f'<rect x="{x-24:.0f}" y="{y-46:.0f}" width="{w_+48:.0f}" height="40" rx="12"'
         f' fill="{ZHELEZ}" {o(5)}/>'
         f'<circle cx="{x+w_/2:.0f}" cy="{y-26:.0f}" r="13" fill="#3e4348" {o(3)}/>')
    for i in range(7):
        s += (f'<rect x="{x+16:.0f}" y="{y+h_*.22+i*5:.0f}" width="{w_-32:.0f}"'
              f' height="{h_*.70:.0f}" rx="6" fill="#efe8da" opacity=".55"/>')
    s += (f'<g transform="rotate({kach + 8 * otryv:.1f} {x+22:.0f} {y+h_*.24:.0f})">'
          f'<rect x="{x+12:.0f}" y="{y+h_*.20:.0f}" width="{w_-24:.0f}"'
          f' height="{h_*.72:.0f}" rx="7" fill="#f6f1e4" {o(5)}/>'
          f'<path d="M{x+w_*.22:.0f},{y+h_*.80:.0f} q{w_*.14:.0f},{-12:.0f}'
          f' {w_*.28:.0f},0 q{w_*.14:.0f},{12:.0f} {w_*.28:.0f},0" fill="none"'
          f' stroke="#9a8a68" stroke-width="7"/>'
          f'<rect x="{x+w_*.14:.0f}" y="{y+h_*.26:.0f}" width="{w_*.72:.0f}"'
          f' height="10" rx="5" fill="#c9b79c" opacity=".8"/></g>')
    return s


def _zavalinka(x, y, w_, t, h_=170):
    """Завалинка у избы: земляная присыпка вдоль сруба, тёсаная доска
    сверху, подпорные колья и палая листва у подножия."""
    rnd = random.Random(int(x) + 7)
    s = (f'<path d="M{x:.0f},{y:.0f} L{x+w_:.0f},{y:.0f} L{x+w_-36:.0f},{y-h_:.0f}'
         f' L{x+36:.0f},{y-h_:.0f} Z" fill="#6b5a44" {o(6)}/>'
         f'<rect x="{x+18:.0f}" y="{y-h_-26:.0f}" width="{w_-36:.0f}" height="34"'
         f' rx="10" fill="url(#dosk)" {o(6)}/>')
    for i in range(int(w_ / 150)):
        px = x + 60 + i * 150
        s += (f'<line x1="{px:.0f}" y1="{y:.0f}" x2="{px+8:.0f}" y2="{y-h_:.0f}"'
              f' stroke="#4e3a26" stroke-width="15"/>')
    for i in range(14):
        rr = rnd.uniform(18, 34)
        s += (f'<ellipse cx="{x+rnd.uniform(0, w_):.0f}" cy="{y+rnd.uniform(-8, 26):.0f}"'
              f' rx="{rr:.0f}" ry="{rr*.5:.0f}"'
              f' fill="{["#9a5a28", "#b4762f", "#7d4a24"][i % 3]}" opacity=".9"/>')
    return s


def _sglaz(x, y, t, s_=1.0, ph=.0, op=.92):
    """Сглаз: серое облачко с ОДНИМ прищуренным глазом, клубится по краю,
    снизу тянется дымный хвостик. Рисованный персонаж, не пятно."""
    dr = 1.0 + .05 * A.w(t, 1.6, ph)
    s = (f'<g transform="translate({x:.0f} {y:.0f}) scale({dr:.3f})'
         f' translate({-x:.0f} {-y:.0f})" opacity="{op:.2f}">')
    rnd = random.Random(int(ph * 100) + 5)
    for i in range(7):
        a = math.radians(i * 51)
        s += (f'<circle cx="{x+math.cos(a)*62*s_:.0f}" cy="{y+math.sin(a)*34*s_:.0f}"'
              f' r="{(38+rnd.uniform(0, 16))*s_:.0f}" fill="#7a818a" {o(4)}/>')
    s += (f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{96*s_:.0f}" ry="{58*s_:.0f}"'
          f' fill="#8a919a" {o(5)}/>'
          f'<ellipse cx="{x:.0f}" cy="{y-4*s_:.0f}" rx="{40*s_:.0f}"'
          f' ry="{27*s_:.0f}" fill="#f2f6fa" {o(4)}/>'
          f'<circle cx="{x+8*s_:.0f}" cy="{y-2*s_:.0f}" r="{17*s_:.0f}"'
          f' fill="#2b3f52"/>'
          f'<circle cx="{x+14*s_:.0f}" cy="{y-8*s_:.0f}" r="{6*s_:.0f}"'
          f' fill="#eaf4ff" opacity=".9"/>'
          f'<path d="M{x-44*s_:.0f},{y-18*s_:.0f} q{44*s_:.0f},{-26*s_:.0f}'
          f' {88*s_:.0f},{-4*s_:.0f}" fill="none" stroke="#3c434a"'
          f' stroke-width="{10*s_:.0f}" stroke-linecap="round"/>'
          f'<path d="M{x-40*s_:.0f},{y+14*s_:.0f} q{40*s_:.0f},{20*s_:.0f}'
          f' {80*s_:.0f},{-2*s_:.0f}" fill="none" stroke="#5c646c"'
          f' stroke-width="{8*s_:.0f}"/>')
    for i in range(3):
        k = (t * .5 + ph + i * .33) % 1.0
        s += (f'<circle cx="{x-70*s_-40*k*s_:.0f}" cy="{y+40*s_+30*k*s_:.0f}"'
              f' r="{(20-10*k)*s_:.0f}" fill="#8a919a"'
              f' opacity="{.6*(1-k):.2f}"/>')
    return s + "</g>"


def _sapogi_novye(x, y, s_=1.0, t=0.0, blesk=1.0):
    """Новые сапоги: голенище гармошкой, скошенный каблук, подкова на
    подошве и бегущий блик по голенищу."""
    bl = .3 + .5 * abs(A.w(t, 1.8, .2)) * blesk
    s = ""
    for i, dx in enumerate((-52, 46)):
        hh = (168 if i == 0 else 158) * s_
        s += (f'{ten(x + dx * s_, y + 6 * s_, 46 * s_, 11 * s_, .45)}'
              f'<path d="M{x+dx*s_-38*s_:.0f},{y:.0f} L{x+dx*s_+42*s_:.0f},{y:.0f}'
              f' L{x+dx*s_+30*s_:.0f},{y-hh:.0f} L{x+dx*s_-26*s_:.0f},{y-hh:.0f} Z"'
              f' fill="#2e2620" {o(5)}/>')
        for k in range(4):
            s += (f'<path d="M{x+dx*s_-28*s_:.0f},{y-hh*.30-k*26*s_:.0f}'
                  f' q{30*s_:.0f},{10*s_:.0f} {60*s_:.0f},{-2*s_:.0f}" fill="none"'
                  f' stroke="#4a3f36" stroke-width="{7*s_:.0f}" opacity=".9"/>')
        s += (f'<rect x="{x+dx*s_-40*s_:.0f}" y="{y-16*s_:.0f}" width="{84*s_:.0f}"'
              f' height="{18*s_:.0f}" rx="5" fill="#1d1812" {o(3)}/>'
              f'<path d="M{x+dx*s_-22*s_:.0f},{y-hh*.84:.0f}'
              f' L{x+dx*s_-14*s_:.0f},{y-hh*.18:.0f}" fill="none" stroke="#cfe4f5"'
              f' stroke-width="{8*s_:.0f}" opacity="{bl:.2f}"/>')
    return s


def _ambar_s_meshkami(x, y, w_, h_, t, otkr=.0, seed=5):
    """Амбар с распахнутыми воротами: бревенчатые щиты створок на кованых
    петлях, внутри мешки горой, над дверью скоба и рябиновая гроздь."""
    rnd = random.Random(seed)
    s = brevna(x, y, w_, h_, 92)
    s += (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
          f' fill="none" {o(9)}/>')
    pw = w_ * .34
    px = x + w_ * .33
    s += (f'<rect x="{px:.0f}" y="{y+h_*.18:.0f}" width="{pw:.0f}"'
          f' height="{h_*.82:.0f}" rx="6" fill="#2a2018"/>')
    for i in range(6):
        mx = px + 40 + rnd.uniform(0, pw - 110)
        my = y + h_ - 20 - (i % 3) * 86
        s += (f'<path d="M{mx-54:.0f},{my:.0f} q{-14:.0f},{-80:.0f} {24:.0f},{-104:.0f}'
              f' q{32:.0f},{-12:.0f} {58:.0f},{8:.0f} q{30:.0f},{34:.0f}'
              f' {20:.0f},{96:.0f} Z" fill="#d8c8a4" {o(5)}/>'
              f'<path d="M{mx-18:.0f},{my-102:.0f} q{20:.0f},{-14:.0f} {42:.0f},{4:.0f}"'
              f' fill="none" stroke="{TKAN}" stroke-width="8"/>')
    for sgn, ug in ((-1, -62 * otkr), (1, 62 * otkr)):
        vx = px + (0 if sgn < 0 else pw)
        s += (f'<g transform="rotate({ug:.1f} {vx:.0f} {y+h_*.2:.0f})">'
              f'<rect x="{vx - (pw * .5 if sgn < 0 else 0):.0f}" y="{y+h_*.18:.0f}"'
              f' width="{pw*.5:.0f}" height="{h_*.82:.0f}" rx="6"'
              f' fill="url(#derev)" {o(6)}/>')
        for k in range(4):
            s += (f'<rect x="{vx - (pw * .5 if sgn < 0 else 0) + 10 + k * (pw * .5 - 24) / 4:.0f}"'
                  f' y="{y+h_*.21:.0f}" width="{(pw*.5-30)/4.6:.0f}"'
                  f' height="{h_*.76:.0f}" rx="5" fill="#6a5030" {o(3)}/>')
        s += (f'<rect x="{vx - (pw * .5 if sgn < 0 else 0):.0f}" y="{y+h_*.42:.0f}"'
              f' width="{pw*.5:.0f}" height="24" rx="8" fill="{ZHELEZ}" {o(4)}/></g>')
    s += (f'<rect x="{px-26:.0f}" y="{y+h_*.10:.0f}" width="{pw+52:.0f}" height="34"'
          f' rx="10" fill="#4a3522" {o(5)}/>')
    s += grozd_ryabiny(px + pw + 70, y + h_ * .22, t, 1.1, 13, 7, .3)
    return s


def _rog_izobiliya(x, y, t, s_=1.0, ph=.0):
    """Рог изобилия: плетёный рог витком, из него сыплются яблоки, колосья
    и калач. Его держат обеими руками у груди."""
    s = (f'<path d="M{x:.0f},{y:.0f} q{-80*s_:.0f},{-30*s_:.0f} {-116*s_:.0f},{-96*s_:.0f}'
         f' q{-24*s_:.0f},{-54*s_:.0f} {26*s_:.0f},{-66*s_:.0f}'
         f' q{40*s_:.0f},{-8*s_:.0f} {48*s_:.0f},{32*s_:.0f}'
         f' q{10*s_:.0f},{48*s_:.0f} {60*s_:.0f},{72*s_:.0f} Z"'
         f' fill="url(#solom)" {o(6)}/>')
    for i in range(5):
        s += (f'<path d="M{x-24*s_-i*20*s_:.0f},{y-18*s_-i*14*s_:.0f}'
              f' q{-14*s_:.0f},{-26*s_:.0f} {6*s_:.0f},{-44*s_:.0f}" fill="none"'
              f' stroke="#8a6a3c" stroke-width="{6*s_:.0f}" opacity=".85"/>')
    rnd = random.Random(int(ph * 50) + 11)
    for i in range(6):
        k = ((t * .4 + ph + i * .17) % 1.0)
        ax = x + 30 * s_ + i * 26 * s_ + 40 * k * s_
        ay = y - 20 * s_ + 120 * k * s_
        if i % 3 == 2:
            s += (f'<path d="M{ax:.0f},{ay:.0f} q{10*s_:.0f},{-34*s_:.0f}'
                  f' {2*s_:.0f},{-58*s_:.0f}" fill="none" stroke="#c9a05a"'
                  f' stroke-width="{7*s_:.0f}" opacity="{1-k*.5:.2f}"/>')
        else:
            s += (f'<circle cx="{ax:.0f}" cy="{ay:.0f}" r="{22*s_:.0f}"'
                  f' fill="{"#b8352c" if i % 2 else "#c9772c"}" {o(3)}/>')
    s += (f'<path d="M{x+56*s_:.0f},{y+16*s_:.0f} a{34*s_:.0f},{34*s_:.0f} 0 1 0'
          f' {2*s_:.0f},0 Z" fill="url(#med)" {o(5)}/>')
    return s


def _vorota_dvora(x, y, w_, h_, t, otkr=.0):
    """Створчатые ворота двора: две плахи на кованых полосах, столбы с
    шапками, кольцо-ручка. Одна створка отведена (otkr 0..1)."""
    s = ""
    for sgn in (-1, 1):
        sx = x + (0 if sgn < 0 else w_ * .5)
        ug = sgn * 46 * otkr
        ax = x if sgn < 0 else x + w_
        s += (f'<g transform="rotate({ug:.1f} {ax:.0f} {y:.0f})">'
              f'<rect x="{sx:.0f}" y="{y-h_:.0f}" width="{w_*.5:.0f}" height="{h_:.0f}"'
              f' rx="6" fill="url(#derev)" {o(7)}/>')
        for k in range(5):
            s += (f'<rect x="{sx+12+k*(w_*.5-30)/5:.0f}" y="{y-h_+10:.0f}"'
                  f' width="{(w_*.5-40)/5.4:.0f}" height="{h_-20:.0f}" rx="5"'
                  f' fill="#6a5030" {o(3)}/>')
        s += (f'<rect x="{sx:.0f}" y="{y-h_*.72:.0f}" width="{w_*.5:.0f}" height="22"'
              f' rx="8" fill="{ZHELEZ}" {o(4)}/>'
              f'<rect x="{sx:.0f}" y="{y-h_*.28:.0f}" width="{w_*.5:.0f}" height="22"'
              f' rx="8" fill="{ZHELEZ}" {o(4)}/>'
              f'<circle cx="{sx + (w_ * .46 if sgn < 0 else w_ * .04):.0f}"'
              f' cy="{y-h_*.5:.0f}" r="20" fill="none" stroke="{ZHELEZ}"'
              f' stroke-width="9"/></g>')
    for px in (x - 30, x + w_ - 20):
        s += (f'<rect x="{px:.0f}" y="{y-h_-40:.0f}" width="52" height="{h_+40:.0f}"'
              f' rx="8" fill="#4e3a26" {o(6)}/>'
              f'<path d="M{px-14:.0f},{y-h_-40:.0f} L{px+26:.0f},{y-h_-78:.0f}'
              f' L{px+66:.0f},{y-h_-40:.0f} Z" fill="#5b4428" {o(4)}/>')
    return s


# ── ДЕКОРАЦИИ, ВТОРАЯ ПАРТИЯ ───────────────────────────────────────────────

def granica_oseni_i_zimy(t):
    """Поле, разделённое надвое полосатым пограничным столбом: слева рыжая
    осень со стогом и лужей, справа белая зима с сугробом, снеговиком и
    санями. Осень передаёт зиме связку ключей через столб."""
    rnd = random.Random(233)
    gor = 560
    s = f'<rect width="{W}" height="{H}" fill="url(#nsumer)"/>'
    s += nebo("sumer", t, True, 19)
    s += oblaka(t, 150, 5, 23, .42, "#cdd7e4", 14.0)
    # дальний план: слева бурая деревня с дымком, справа белый лес
    s += SL(Z_DAL, izba_snaruzhi(250, gor - 10, 330, t, True, True, 5)
            + izba_snaruzhi(560, gor - 24, 250, t, True, True, 11))
    s += SL(Z_DAL, goloe_derevo(130, gor + 10, 520, t, 7, 9, "#3a3b43", False)
            + goloe_derevo(820, gor + 4, 400, t, 13, 8, "#3a3b43", False))
    for i in range(5):
        s += SL(Z_DAL, f'<path d="M{1180+i*170:.0f},{gor:.0f}'
                       f' l{-72:.0f},0 l{72:.0f},{-230-i*26:.0f}'
                       f' l{72:.0f},{230+i*26:.0f} Z" fill="#cfd8e6"'
                       f' opacity=".92" {o(4)}/>')
    s += SL(Z_DAL, _zabor_dosok(-30, gor - 170, 860, 180, 5, 54))
    # земля: слева мёрзлая рыжая, справа снег. Два щита, не фон
    s += SL(Z_SRED, f'<path d="M-20,{gor:.0f} L960,{gor:.0f} L960,1080 L-20,1080 Z"'
                    f' fill="#5a4630"/>'
            + _zemlya_faktura(gor + 40, 1050, 3, 15, "#46382a")
            + _listya(27, 46, gor + 50, 1060)
            + _trava(rnd, 14, gor + 60, 1040))
    s += SL(Z_SRED, f'<path d="M960,{gor:.0f} L1940,{gor:.0f} L1940,1080 L960,1080 Z"'
                    f' fill="#d8e2ee"/>'
            + f'<path d="M980,{gor+80:.0f} q240,-56 480,-8 q240,46 460,-24'
              f' L1940,1080 L980,1080 Z" fill="url(#sneg)" {o(0)}/>'
            + _inej(37, 54, gor + 60, 1060))
    s += SL(Z_SRED, _stog(300, 1010, 1.12, t, True))
    s += SL(Z_SRED, _luzha(690, 1012, 196, t, .2))
    s += SL(Z_SRED, _kucha_listev(96, 1050, 320, 41, 92))
    s += SL(Z_SRED, _snegovik(1660, 1010, 1.18, t))
    s += SL(Z_SRED, _sani(1290, 1040, 1.0, t, True))
    s += SL(Z_SRED, _sledy(1880, 1066, 1480, 900, 7, 43, "#8fa3b4", 1.3))
    # великаны по пояс над горизонтом: сначала фигуры, потом полоса земли
    kl = A.ease(A.seg(t, 1.0, 2.2))
    ox, oy, oh = 560, gor + 300, 760
    osen = figura(ox, oy, oh, t, col="#9c5a28", kant="#ffd98a", platok=True,
                  ph=.2, naklon=4.0)
    o1, (k1x, k1y), _ = _ruka(ox, oy, oh, 1, oh * .44, 10, t,
                              "#9c5a28", "#ffd98a", .2, 5.0)
    o2, (k2x, k2y), _ = _ruka(ox, oy, oh, 1, oh * .34, 30, t,
                              "#b4762f", "#ffd98a", .6, 4.0)
    osen += o1 + o2
    # платок из листьев
    for i in range(9):
        a = math.radians(-168 + i * 21)
        osen += (f'<path d="M{ox+126*math.cos(a):.0f},{oy-oh*.86+96*math.sin(a):.0f}'
                 f' q{22:.0f},{-20:.0f} {44:.0f},{4:.0f} q{-20:.0f},{22:.0f}'
                 f' {-44:.0f},{-4:.0f} Z"'
                 f' fill="{["#b4762f", "#9a5a28", "#c08a3a"][i % 3]}" {o(3)}/>')
    s += SL(Z_SRED, osen)
    zx, zy, zh = 1360, gor + 300, 790
    zima = figura(zx, zy, zh, t, col="#e4eaf2", kant="#8fb0c4", tulup=True,
                  boroda=True, ph=.7, naklon=-3.0)
    z1, (p1x, p1y), _ = _ruka(zx, zy, zh, -1, zh * .42, 8, t,
                              "#e4eaf2", "#8fb0c4", .7, 5.0)
    z2, (p2x, p2y), _ = _ruka(zx, zy, zh, 1, zh * .46, 56, t,
                              "#e4eaf2", "#8fb0c4", .3, 4.0)
    zima += z1 + z2
    s += SL(Z_SRED, zima)
    # ледяной посох под правой рукой зимы
    s += SL(Z_SRED, f'<line x1="{p2x:.0f}" y1="{p2y-30:.0f}" x2="{p2x+30:.0f}"'
                    f' y2="{p2y+330:.0f}" stroke="#9fc4d8" stroke-width="22"'
                    f' stroke-linecap="round"/>'
            + f'<circle cx="{p2x-2:.0f}" cy="{p2y-48:.0f}" r="30" fill="#cfe4f5"'
              f' {o(5)}/>')
    # связка ключей идёт из рук осени в руку зимы
    kx = k1x + (p1x - k1x) * kl
    ky = k1y + (p1y - k1y) * kl
    s += SL(Z_SRED, _svyazka_klyuchey(kx, ky + 16, t, 1.25, .2, 4))
    s += SL(Z_SRED, para_izo_rta(ox + 96, oy - oh * .80, t, .2, 1.3, .5)
            + para_izo_rta(zx - 96, zy - zh * .80, t, .6, 1.4, .55))
    # СТОЛБ — главный предмет, ровно по стыку половин
    s += SL(Z_SRED, _stolb_pogranichnyy(960, 1016, 660, t, 104))
    # мужичок с топором и бревном на плече: подходит и уходит
    sh = A.seg(t, .2, 6.0)
    mx = 240 + 1340 * sh
    mh = 300
    muz = figura(mx, 1046, mh, t, col="#4a4a56", kant="#cfe4f5", shapka=True,
                 ph=.5, profil=True, naklon=5.0)
    m1, (b1x, b1y), _ = _ruka(mx, 1046, mh, 1, mh * .40, -32, t,
                              "#4a4a56", "#cfe4f5", .5, 6.0)
    m2, (b2x, b2y), _ = _ruka(mx, 1046, mh, -1, mh * .36, 44, t,
                              "#4a4a56", "#cfe4f5", .1, 6.0)
    muz += m1 + m2
    muz += (f'<line x1="{b1x-130:.0f}" y1="{b1y-56:.0f}" x2="{b1x+140:.0f}"'
            f' y2="{b1y+22:.0f}" stroke="url(#derev)" stroke-width="40"'
            f' stroke-linecap="round"/>'
            f'<line x1="{b2x:.0f}" y1="{b2y:.0f}" x2="{b2x+10:.0f}"'
            f' y2="{b2y+86:.0f}" stroke="url(#derev)" stroke-width="13"/>'
            f'<path d="M{b2x+4:.0f},{b2y+86:.0f} l{44:.0f},{-14:.0f} l{8:.0f},{40:.0f}'
            f' l{-48:.0f},{10:.0f} Z" fill="{ZHELEZ}" {o(4)}/>')
    s += SL(Z_SRED, muz)
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(k2x, k2y, oh, t, .6, "#f0d8b0")
            + _varezhka(p1x, p1y, zh, t, .7, "#dfe8f0")
            + _varezhka(p2x, p2y, zh, t, .3, "#dfe8f0")
            + _varezhka(kx, ky + 16, oh * .7, t, .2, "#f0d8b0"))
    s += SL(Z_PERED, _vetka_pered(-70, 110, 760, 26, t, 7, "#241c16", 6))
    s += SL(Z_LETIT, mokryy_sneg(t, 26, 5, .55, .9))
    s += ramka_pp("pravo")
    s += vinetka(.42)
    return s


def okno_noch_i_utro(t):
    """Спальня: кровать с высокими подушками, тумбочка с будильником и
    стаканом, окно на пол-кадра — за ним настоящий рассвет над городом.
    Мужчина в пижаме кладёт лист под будильник и гасит ночник."""
    rnd = random.Random(239)
    pol = 962
    s = f'<rect width="{W}" height="{H}" fill="#1b2130"/>'
    s += SL(Z_DAL, doski(0, 0, 820, pol, 102, True, "dosk"))
    s += SL(Z_DAL, f'<rect x="820" y="0" width="1100" height="{pol:.0f}"'
                   f' fill="#3c4556"/>')
    for i in range(11):
        s += SL(Z_DAL, f'<rect x="{830+i*100:.0f}" y="0" width="52"'
                       f' height="{pol:.0f}" fill="#465063" opacity=".6"/>')
    s += SL(Z_DAL, _ramki_na_stene(140, 180, 560, t, 17, 3))
    s += SL(Z_DAL, _knizhnaya_polka(96, 630, 620, t, 139, 1, 180))
    # комод с ящиками, графин и обувная полка — вещи спальни среднего плана
    s += SL(Z_DAL, f'<rect x="96" y="700" width="560" height="250" rx="10"'
                   f' fill="url(#derev)" {o(6)}/>')
    for i in range(3):
        s += SL(Z_DAL, f'<rect x="{116+i*180:.0f}" y="724" width="166"'
                       f' height="100" rx="7" fill="#8a6a44" {o(4)}/>'
                f'<rect x="{116+i*180:.0f}" y="836" width="166" height="96"'
                f' rx="7" fill="#9c7a4c" {o(4)}/>'
                f'<rect x="{176+i*180:.0f}" y="766" width="48" height="14" rx="7"'
                f' fill="url(#zhel)" {o(3)}/>'
                f'<rect x="{176+i*180:.0f}" y="876" width="48" height="14" rx="7"'
                f' fill="url(#zhel)" {o(3)}/>')
    s += SL(Z_DAL, f'<rect x="0" y="{pol-12:.0f}" width="{W}"'
                   f' height="{H-pol+12:.0f}" fill="#4e4336"/>'
            + _polovik(560, pol + 24, 760, 104, "#b9a888", "#6a5a44"))
    # ОКНО: сначала рисованный вид, потом метка, потом переплёт поверх
    px, py, pw, ph_ = 940, 130, 900, 470
    put = kontur_proema(px, py, pw, ph_, "pryam")
    zar = A.ease(A.seg(t, .2, 1.8))
    s += SL(Z_SRED, _vid_za_proemom(put, t, "zarya", 5, px + pw * .5)
            + mesto_stoka(px, py, pw, ph_, "pryam"))
    # переплёт и наличники ПОВЕРХ кадра — это и есть «кадр внутри сцены»
    ram = (f'<path d="{put}" fill="none" stroke="#6a5a46" stroke-width="30"/>'
           f'<rect x="{px-34:.0f}" y="{py-42:.0f}" width="{pw+68:.0f}" height="36"'
           f' rx="10" fill="#7d6a52" {o(5)}/>'
           f'<rect x="{px-50:.0f}" y="{py+ph_-10:.0f}" width="{pw+100:.0f}"'
           f' height="44" rx="10" fill="url(#dosk)" {o(6)}/>'
           f'<line x1="{px+pw*.5:.0f}" y1="{py:.0f}" x2="{px+pw*.5:.0f}"'
           f' y2="{py+ph_:.0f}" stroke="#6a5a46" stroke-width="22"/>'
           f'<line x1="{px:.0f}" y1="{py+ph_*.46:.0f}" x2="{px+pw:.0f}"'
           f' y2="{py+ph_*.46:.0f}" stroke="#6a5a46" stroke-width="20"/>'
           f'<path d="M{px+40:.0f},{py+ph_*.40:.0f} L{px+pw*.44:.0f},{py+30:.0f}"'
           f' fill="none" stroke="#eaf4ff" stroke-width="12"'
           f' opacity="{.12+.22*zar:.2f}"/>')
    s += SL(Z_SRED, ram)
    s += SL(Z_SRED, zanaveska(px - 30, py - 20, 560, 150, "#c9bca0", t, 1)
            + zanaveska(px + pw + 30, py - 20, 560, 150, "#c9bca0", t, -1))
    # КРОВАТЬ — главный предмет
    s += SL(Z_SRED, _krovat(90, pol, 980, t, 7, True, 330))
    s += SL(Z_SRED, _podushka(300, pol - 420, 320, 180, t, .2, .0, .0)
            + _podushka(560, pol - 452, 300, 170, t, .5, .0, .0))
    # тумбочка, будильник, стакан, ночник
    tx = 1240
    s += SL(Z_SRED, f'{ten(tx + 70, pol + 6, 110, 18, .45)}'
                    f'<rect x="{tx:.0f}" y="{pol-290:.0f}" width="250" height="290"'
                    f' rx="10" fill="url(#derev)" {o(6)}/>'
            + f'<rect x="{tx+18:.0f}" y="{pol-262:.0f}" width="214" height="110"'
              f' rx="7" fill="#8a6a44" {o(4)}/>'
            + f'<rect x="{tx+100:.0f}" y="{pol-214:.0f}" width="54" height="16"'
              f' rx="7" fill="url(#zhel)" {o(3)}/>')
    s += SL(Z_SRED, f'<circle cx="{tx+86:.0f}" cy="{pol-346:.0f}" r="56"'
                    f' fill="#e8e0cc" {o(6)}/>'
            + f'<circle cx="{tx+86:.0f}" cy="{pol-346:.0f}" r="42"'
              f' fill="#f6f2e4" {o(3)}/>'
            + f'<line x1="{tx+86:.0f}" y1="{pol-346:.0f}"'
              f' x2="{tx+86+30*math.cos(t*1.1):.0f}"'
              f' y2="{pol-346+30*math.sin(t*1.1):.0f}" stroke="{K}" stroke-width="6"/>'
            + f'<line x1="{tx+86:.0f}" y1="{pol-346:.0f}"'
              f' x2="{tx+86+18*math.cos(t*.2):.0f}"'
              f' y2="{pol-346+18*math.sin(t*.2):.0f}" stroke="{K}" stroke-width="8"/>'
            + f'<circle cx="{tx+50:.0f}" cy="{pol-392:.0f}" r="17" fill="{ZHELEZ}" {o(3)}/>'
            + f'<circle cx="{tx+122:.0f}" cy="{pol-392:.0f}" r="17" fill="{ZHELEZ}" {o(3)}/>')
    s += SL(Z_SRED, f'<path d="M{tx+180:.0f},{pol-294:.0f} L{tx+244:.0f},{pol-294:.0f}'
                    f' L{tx+236:.0f},{pol-384:.0f} L{tx+188:.0f},{pol-384:.0f} Z"'
                    f' fill="url(#stekl)" opacity=".9" {o(4)}/>'
            + f'<ellipse cx="{tx+212:.0f}" cy="{pol-340:.0f}" rx="22" ry="8"'
              f' fill="#8fb6cc" opacity=".8"/>')
    # ночник гаснет к концу плана
    gas = 1 - A.ease(A.seg(t, 1.1, .8))
    s += SL(Z_SRED, lampa(1596, pol - 300, t, .92, True))
    if gas > .25:
        s += SL(Z_SRED, teplo(1596, pol - 400, 420, 330, .50 * gas))
    # стул с брошенной одеждой и пара книг на нём
    s += SL(Z_SRED, _venskiy_stul(1760, pol + 2, 500, t, 2.0, False)
            + f'<path d="M1690,{pol-250:.0f} q70,-40 140,0 l-16,150 q-56,24 -112,0 Z"'
              f' fill="#5a6a7a" {o(5)}/>'
            + f'<rect x="1704" y="{pol-110:.0f}" width="120" height="34" rx="6"'
              f' fill="#7a3a42" {o(4)}/>')
    # мужчина в пижаме на краю кровати, ноги в тапках
    fx, fy, fh = 880, pol - 8, 540
    lozh = A.ease(A.seg(t, .2, .9))
    muz = figura(fx, fy - 236, fh, t, col="#5a6a7a", kant="#ffd98a", ph=.4,
                 naklon=6.0)
    m1, (r1x, r1y), _ = _ruka(fx, fy - 236, fh, 1, fh * .52, 40 + 14 * lozh, t,
                              "#5a6a7a", "#ffd98a", .4, 4.0)
    m2, (r2x, r2y), _ = _ruka(fx, fy - 236, fh, -1, fh * .40, 22, t,
                              "#5a6a7a", "#ffd98a", .8, 4.0)
    muz += m1 + m2
    for i in range(4):
        muz += (f'<line x1="{fx-50+i*28:.0f}" y1="{fy-236-fh*.58:.0f}"'
                f' x2="{fx-54+i*28:.0f}" y2="{fy-236-fh*.14:.0f}"'
                f' stroke="#6e8294" stroke-width="7" opacity=".8"/>')
    s += SL(Z_SRED, muz)
    s += SL(Z_SRED, f'<ellipse cx="{fx-60:.0f}" cy="{fy-4:.0f}" rx="62" ry="22"'
                    f' fill="#6a4a3c" {o(5)}/>'
            + f'<ellipse cx="{fx+66:.0f}" cy="{fy-2:.0f}" rx="62" ry="22"'
              f' fill="#6a4a3c" {o(5)}/>')
    # лист ложится под будильник
    lk = A.ease(A.seg(t, .9, .9))
    # пока рука не донесла — лист В РУКЕ (варежка его перекрывает), после —
    # ЛЕЖИТ на тумбочке под будильником. В воздухе он не висит.
    lx = r1x + (tx + 86 - r1x) * lk
    ly = r1y + (pol - 296 - r1y) * lk
    s += SL(Z_SRED, f'<g transform="rotate({-16 + 10 * lk:.1f} {lx:.0f} {ly:.0f})">'
                    f'<rect x="{lx-66:.0f}" y="{ly-46:.0f}" width="132" height="92"'
                    f' rx="6" fill="#f4efe0" {o(5)}/>'
            + f'<path d="M{lx-50:.0f},{ly-14:.0f} q32,-10 64,0" fill="none"'
              f' stroke="#9a8a68" stroke-width="6"/>'
            + f'<line x1="{lx-66:.0f}" y1="{ly:.0f}" x2="{lx+66:.0f}" y2="{ly+4:.0f}"'
              f' stroke="#d8cfbd" stroke-width="5"/></g>')
    if lk < .98:
        s += SL(Z_SRED, _varezhka(lx + 40, ly + 18, fh, t, .4))
    else:
        s += SL(Z_SRED, ten(lx, ly + 48, 70, 12, .4))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _konus_sveta(1596, pol - 400, 460, 300, -8, .40))
    s += SL(Z_SRED, _pol_shvy(pol + 14, 1078, 37, 6, "#3c3228"))
    # низ кадра: коврик, тапки второй пары, книга, корзина с бельём
    s += SL(Z_SRED, _valenki_u_dveri(430, pol + 86, .86, t)
            + _dvorovaya_utvar(1520, pol + 84, 360, t, 53, ["korzina", "korob"])
            + _kot_zhivoy(1180, pol + 72, t, 1.05, "#3a342e", .6, True, True))
    s += SL(Z_SRED, _knizhnaya_polka(70, 420, 420, t, 59, 1, 180))
    s += SL(Z_PERED, _stolb_pered(-6, 92, "#140f0c", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 1596, pol - 340, 5, 11, 170, .3))
    s += vinetka(.44)
    return s


def slovo_kotoroe_ne_vzyat_nazad(t):
    """Стол в конторе: папки, печать, календарь без года, стакан с ручками.
    Женщина в очках с ручкой, напротив мужчина в костюме. Изо рта вылетают
    слова-птички, она промахивается, и они улетают в окно."""
    rnd = random.Random(241)
    s = f'<rect width="{W}" height="{H}" fill="#242a30"/>'
    s += SL(Z_DAL, doski(0, 0, 1060, 700, 98, True, "dosk"))
    s += SL(Z_DAL, f'<rect x="1060" y="0" width="860" height="700"'
                   f' fill="#5a6470"/>')
    # окно конторы, куда улетают птички (без стока — просто окно)
    s += SL(Z_DAL, okno_izby(1420, 120, 420, 420, t, None, .0, False, True))
    s += SL(Z_DAL, f'<rect x="1400" y="100" width="460" height="40" rx="10"'
                   f' fill="#6a5a46" {o(5)}/>')
    s += SL(Z_DAL, _knizhnaya_polka(96, 320, 760, t, 61, 2, 200))
    s += SL(Z_DAL, _ramki_na_stene(880, 130, 300, t, 67, 2))
    s += SL(Z_DAL, f'<rect x="0" y="686" width="{W}" height="394"'
                   f' fill="#4a4036"/>' + _polovik(520, 760, 900, 130,
                                                   "#a89880", "#6a5a44"))
    # СТОЛ — главный предмет
    s += SL(Z_SRED, _pismennyy_stol(300, 1070, 1340, t, 400))
    sy = 1070 - 400
    # настольная лампа — живой огонёк конторы
    s += SL(Z_SRED, tusklaya_lampochka(1480, sy - 150, t, 1.3, True))
    # папки, печать, календарь, стакан с ручками
    s += SL(Z_SRED, _svitki_i_papki(360, sy - 10, t, 7, 3))
    s += SL(Z_SRED, f'<rect x="1150" y="{sy-124:.0f}" width="150" height="124"'
                    f' rx="10" fill="#6a5030" {o(6)}/>'
            + f'<rect x="1162" y="{sy-108:.0f}" width="126" height="88" rx="6"'
              f' fill="#f2ece0" {o(4)}/>'
            + f'<path d="M1180,{sy-74:.0f} q44,-14 88,0" fill="none"'
              f' stroke="#9a8a68" stroke-width="6"/>'
            + f'<rect x="1150" y="{sy-140:.0f}" width="150" height="22" rx="8"'
              f' fill="{ZHELEZ}" {o(3)}/>')
    s += SL(Z_SRED, f'<rect x="1328" y="{sy-96:.0f}" width="72" height="96" rx="10"'
                    f' fill="#5e676e" {o(5)}/>'
            + f'<rect x="1314" y="{sy-116:.0f}" width="100" height="26" rx="9"'
              f' fill="#49535b" {o(4)}/>'
            + f'<circle cx="1364" cy="{sy-14:.0f}" r="26" fill="#9c2f28"'
              f' opacity=".85" {o(3)}/>')
    s += SL(Z_SRED, f'<path d="M1046,{sy-10:.0f} L1118,{sy-10:.0f}'
                    f' L1106,{sy-130:.0f} L1058,{sy-130:.0f} Z" fill="#6e757c" {o(5)}/>')
    for i in range(5):
        s += SL(Z_SRED, f'<line x1="{1066+i*12:.0f}" y1="{sy-124:.0f}"'
                        f' x2="{1056+i*18:.0f}" y2="{sy-244-i*12:.0f}"'
                        f' stroke="{["#3f5c7a", "#8a4a3c", "#4a6a48", "#8a6a2c", "#5a4a62"][i]}"'
                        f' stroke-width="12" stroke-linecap="round"/>')
    # лист с мигающей строкой под подпись
    s += SL(Z_SRED, _list_bumagi(700, sy - 20, 420, 270, t, 2.0, 4, True))
    # женщина в очках за столом
    jx, jy, jh = 560, sy + 300, 560
    s += SL(Z_SRED, _venskiy_stul(jx - 40, sy + 310, 540, t, -2.0, True))
    jen = figura(jx, jy - 230, jh, t, col="#5a4a62", kant="#ffd98a", ph=.3,
                 naklon=5.0)
    j1, (w1x, w1y), _ = _ruka(jx, jy - 230, jh, 1, jh * .48,
                              30 - 44 * abs(A.w(t, 2.4, .1)), t,
                              "#5a4a62", "#ffd98a", .3, 6.0)
    j2, (w2x, w2y), _ = _ruka(jx, jy - 230, jh, 1, jh * .36, 56, t,
                              "#5a4a62", "#ffd98a", .7, 4.0)
    jen += j1 + j2
    jen += _ochki(jx, jy - 230 - jh * .845, .78, t)
    s += SL(Z_SRED, jen)
    s += SL(Z_SRED, f'<line x1="{w1x:.0f}" y1="{w1y:.0f}" x2="{w1x+64:.0f}"'
                    f' y2="{w1y-44:.0f}" stroke="#2b3038" stroke-width="13"'
                    f' stroke-linecap="round"/>')
    # мужчина в костюме напротив, обе руки сложены на столе
    mx, my, mh = 1316, sy + 320, 600
    muz = figura(mx, my - 250, mh, t, col="#2f3540", kant="#ffd98a", ph=.8,
                 naklon=-3.0)
    m1, (v1x, v1y), _ = _ruka(mx, my - 250, mh, -1, mh * .42, 58, t,
                              "#2f3540", "#ffd98a", .8, 3.0)
    m2, (v2x, v2y), _ = _ruka(mx, my - 250, mh, -1, mh * .34, 72, t,
                              "#2f3540", "#ffd98a", .2, 3.0)
    muz += m1 + m2
    muz += (f'<path d="M{mx-22:.0f},{my-250-mh*.60:.0f} L{mx+22:.0f},{my-250-mh*.60:.0f}'
            f' L{mx+10:.0f},{my-250-mh*.40:.0f} L{mx-10:.0f},{my-250-mh*.40:.0f} Z"'
            f' fill="#9c2f28" {o(3)}/>')
    s += SL(Z_SRED, muz)
    # СЛОВА-ПТИЧКИ: вылетают изо рта, рука промахивается, уходят в окно
    for i in range(4):
        k = A.seg(t, .5 + i * .55, 2.6)
        # старт дальше от лица: первая птица стояла у самого глаза
        bx = jx + 190 + (1560 - jx - 130) * A.ease(k)
        by = jy - 230 - jh * .78 - 90 - 240 * math.sin(math.pi * k) - 30 * k
        kr = 26 * A.w(t * 2.4, 1.0, i * .3)
        s += SL(Z_SRED, f'<g transform="translate({bx:.0f} {by:.0f})">'
                        f'<ellipse cx="0" cy="0" rx="40" ry="24" fill="#e8dcc0" {o(4)}/>'
                f'<circle cx="32" cy="-14" r="18" fill="#efe6d2" {o(3)}/>'
                f'<path d="M48,-16 l24,8 l-24,8 Z" fill="#d8a53c" {o(2)}/>'
                f'<circle cx="38" cy="-18" r="4" fill="{K}"/>'
                f'<path d="M-6,-6 q24,{-30 - kr:.0f} 54,{-14 - kr * .4:.0f}'
                f' q-26,{26 + kr * .5:.0f} -56,{12:.0f} Z" fill="#cfc3a4" {o(3)}/>'
                f'<path d="M-36,4 l-40,{10 + kr * .3:.0f} l34,{6:.0f} Z"'
                f' fill="#d8cfbd" {o(2)}/></g>')
    s += SL(Z_SRED, ten(jx, sy + 306, 150, 22, .4))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(w2x, w2y, jh, t, .7)
            + _varezhka(v1x, v1y, mh, t, .8))
    s += SL(Z_SRED, _konus_sveta(1480, sy - 150, 520, 300, 10, .40))
    s += SL(Z_SRED, _pol_shvy(760, 1078, 41, 6, "#3a3228"))
    # низ кадра
    s += SL(Z_PERED, _yaschiki(96, 1072, t, 23, 2, .88)
            + _dvorovaya_utvar(1560, 1068, 340, t, 71, ["korzina", "korob"])
            + _kot_zhivoy(1240, 1058, t, 1.1, "#3e3833", .3))
    s += SL(Z_PERED, _stolb_pered(1862, 86, "#191410", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 1480, sy - 190, 5, 13, 160, .26))
    s += vinetka(.42)
    return s


def chetyre_bumagi_pod_podushkoy(t):
    """Кровать с лоскутным покрывалом, большая пуховая подушка на пол-кадра,
    на тумбочке лампа, очки, клубок. Бабушка в сорочке и чепце приподнимает
    подушку и кладёт под неё по одной четыре бумаги со значками."""
    rnd = random.Random(251)
    pol = 972
    s = f'<rect width="{W}" height="{H}" fill="#201a16"/>'
    s += SL(Z_DAL, brevna(0, 40, 1120, pol - 40, 98)
            + brevna(1120, 40, 800, pol - 40, 98))
    s += SL(Z_DAL, _kover_na_stene(120, 130, 880, 430, t, 19))
    s += SL(Z_DAL, _polka_s_utvaryu(1180, 250, 620, t, 73, 5))
    s += SL(Z_DAL, _polka_s_utvaryu(100, 600, 580, t, 149, 5))
    s += SL(Z_DAL, _knizhnaya_polka(760, 250, 380, t, 151, 1, 180))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-14:.0f}" width="{W}"'
                   f' height="{H-pol+14:.0f}" fill="#5e4a34"/>'
            + polovicy(pol + 16))
    s += SL(Z_DAL, _polovik(620, pol + 30, 700, 96))
    # КРОВАТЬ и ПОДУШКА — главный предмет
    s += SL(Z_SRED, _krovat(360, pol, 1180, t, 11, True, 320))
    pod = A.ease(A.seg(t, .5, 1.1)) * (1 - A.ease(A.seg(t, 4.4, .7)))
    hlop = A.ease(A.seg(t, 4.9, .5)) * (1 - A.ease(A.seg(t, 5.5, .5)))
    s += SL(Z_SRED, _podushka(700, pol - 440, 520, 250, t, .2, pod, hlop))
    # бумаги уходят под подушку по одной
    vidy = ("ruka", "galka", "cherta", "pero")
    for i in range(4):
        k = A.ease(A.seg(t, 1.0 + i * .75, .7))
        bx = 1140 - 300 * k
        by = pol - 520 + 150 * k
        if k < 1.0:
            s += SL(Z_SRED, _bumaga_znachok(bx, by, .92, vidy[i],
                                            -14 + 20 * k + 6 * A.w(t, 2.0, i * .2)))
        else:
            s += SL(Z_SRED, _bumaga_znachok(760 + i * 34, pol - 356, .74,
                                            vidy[i], -8 + i * 5))
    # тумбочка: лампа, очки, клубок
    tx = 150
    s += SL(Z_SRED, f'{ten(tx + 110, pol + 6, 120, 18, .45)}'
                    f'<rect x="{tx:.0f}" y="{pol-300:.0f}" width="230" height="300"'
                    f' rx="10" fill="url(#derev)" {o(6)}/>'
            + f'<rect x="{tx+16:.0f}" y="{pol-272:.0f}" width="198" height="116"'
              f' rx="7" fill="#8a6a44" {o(4)}/>'
            + f'<rect x="{tx+88:.0f}" y="{pol-220:.0f}" width="54" height="16"'
              f' rx="7" fill="url(#zhel)" {o(3)}/>')
    gas = 1 - A.ease(A.seg(t, 5.8, .7))
    s += SL(Z_SRED, lampa(tx + 110, pol - 306, t, 1.05, False))
    s += SL(Z_SRED, teplo(tx + 110, pol - 430, 480, 380, .50 * gas))
    s += SL(Z_SRED, _ochki(tx + 196, pol - 318, 1.0, t))
    s += SL(Z_SRED, f'<circle cx="{tx+40:.0f}" cy="{pol-330:.0f}" r="44"'
                    f' fill="#8a4a52" {o(5)}/>')
    for i in range(5):
        s += SL(Z_SRED, f'<path d="M{tx+4:.0f},{pol-352+i*14:.0f}'
                        f' q{40:.0f},{-14:.0f} {76:.0f},{6:.0f}" fill="none"'
                        f' stroke="#a35a62" stroke-width="5" opacity=".85"/>')
    s += SL(Z_SRED, f'<line x1="{tx+84:.0f}" y1="{pol-320:.0f}" x2="{tx+150:.0f}"'
                    f' y2="{pol-284:.0f}" stroke="#8a4a52" stroke-width="6"/>')
    # бабушка у кровати: ложится к концу плана
    lozh = A.ease(A.seg(t, 5.4, 1.2))
    bx, by_, bh = 1380, pol + 18, 760 - 300 * lozh
    bab = figura(bx + 90 * lozh, by_ - 240 * lozh, bh, t, col="#e4dcc8",
                 kant="#ffd98a", platok=True, ph=.4, naklon=8 - 24 * lozh)
    b1, (q1x, q1y), _ = _ruka(bx + 90 * lozh, by_ - 240 * lozh, bh, -1,
                              bh * .48, 24 - 30 * pod, t,
                              "#e4dcc8", "#ffd98a", .4, 4.0)
    b2, (q2x, q2y), _ = _ruka(bx + 90 * lozh, by_ - 240 * lozh, bh, -1,
                              bh * .38, 48 - 20 * pod, t,
                              "#e4dcc8", "#ffd98a", .8, 4.0)
    bab += b1 + b2
    # чепец с рюшем поверх платка
    bab += (f'<path d="M{bx+90*lozh-96:.0f},{by_-240*lozh-bh*.90:.0f}'
            f' q{96:.0f},{-54:.0f} {192:.0f},0 q{-20:.0f},{26:.0f} {-192:.0f},0 Z"'
            f' fill="#f2ece0" {o(4)}/>')
    s += SL(Z_SRED, bab)
    s += SL(Z_SRED, ten(bx + 90 * lozh, by_ + 6, 160, 24, .45))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(q1x, q1y, bh, t, .4))
    s += SL(Z_SRED, _konus_sveta(tx + 110, pol - 330, 560, 330, -14, .42))
    s += SL(Z_SRED, _pol_shvy(pol + 16, 1078, 43, 6, "#4a3824"))
    # лавка с крынками у стены и вязанки лука — обжитой средний план
    s += SL(Z_SRED, _lavka_krupno(96, pol - 10, 620, t, 130, False))
    for i in range(5):
        s += SL(Z_SRED, krynka(150 + i * 120, pol - 140, 1.42 + (i % 3) * .18))
    # два сундука с кованой полосой и прялка в углу
    for i in (0, 1):
        cx_ = 1540 + i * 250
        s += SL(Z_SRED, f'<rect x="{cx_-110:.0f}" y="{pol-180:.0f}" width="220"'
                        f' height="180" rx="10" fill="url(#derev)" {o(6)}/>'
                f'<path d="M{cx_-110:.0f},{pol-180:.0f} q{110:.0f},{-60:.0f}'
                f' {220:.0f},0 Z" fill="url(#med)" {o(5)}/>'
                f'<rect x="{cx_-116:.0f}" y="{pol-126:.0f}" width="232" height="20"'
                f' rx="7" fill="{ZHELEZ}" {o(3)}/>'
                f'<rect x="{cx_-22:.0f}" y="{pol-104:.0f}" width="44" height="34"'
                f' rx="8" fill="url(#zhel)" {o(3)}/>')
    s += SL(Z_SRED, f'<rect x="100" y="{pol-430:.0f}" width="40" height="430"'
                    f' rx="12" fill="url(#derev)" {o(6)}/>'
            + f'<path d="M80,{pol-430:.0f} q40,-70 80,0 Z" fill="#6a5030" {o(5)}/>'
            + f'<ellipse cx="120" cy="{pol-150:.0f}" rx="86" ry="30"'
              f' fill="url(#dosk)" {o(5)}/>')
    # рушники на жерди под потолком
    for i in range(4):
        rx_ = 860 + i * 150
        kach = 2.4 * A.w(t, 3.6, i * .3)
        s += SL(Z_SRED, f'<g transform="rotate({kach:.1f} {rx_:.0f} 150)">'
                        f'<rect x="{rx_-44:.0f}" y="150" width="88" height="270"'
                        f' rx="8" fill="url(#rush)" {o(5)}/>'
                f'<rect x="{rx_-44:.0f}" y="300" width="88" height="16"'
                f' fill="{TKAN}" opacity=".8"/>'
                f'<rect x="{rx_-44:.0f}" y="386" width="88" height="16"'
                f' fill="{TKAN2}" opacity=".7"/></g>')
    s += SL(Z_SRED, f'<rect x="820" y="132" width="700" height="22" rx="9"'
                    f' fill="url(#derev)" {o(5)}/>')
    # ушат, короб с шерстью и подсвечник у лавки
    s += SL(Z_SRED, _dvorovaya_utvar(760, pol - 8, 420, t, 181,
                                     ["kadka", "korob", "korzina"]))
    for i in range(3):
        s += SL(Z_SRED, f'<path d="M{1700+i*74:.0f},240 q{-26:.0f},{80:.0f}'
                        f' {4:.0f},{150:.0f} q{30:.0f},{20:.0f} {44:.0f},{-14:.0f}'
                        f' q{14:.0f},{-76:.0f} {-18:.0f},{-136:.0f} Z"'
                        f' fill="#c9a05a" {o(5)}/>'
                f'<line x1="{1708+i*74:.0f}" y1="240" x2="{1724+i*74:.0f}"'
                f' y2="200" stroke="#8a7a46" stroke-width="7"/>')
    # низ кадра: сундук, валенки, кот, корзина с клубками
    s += SL(Z_SRED, _yaschiki(1600, pol + 86, t, 29, 2, .9)
            + _valenki_u_dveri(1300, pol + 96, .92, t)
            + _kot_zhivoy(560, pol + 76, t, 1.15, "#3b342f", .5, True, True)
            + _dvorovaya_utvar(96, pol + 96, 280, t, 79, ["korzina"]))
    s += SL(Z_PERED, _stolb_pered(1874, 70, "#17120e", 0, H))
    s += SL(Z_LETIT, iskra_let(t, tx + 110, pol - 360, 6, 17, 180, .34))
    s += vinetka(.44)
    return s


def chashi_vesov_segodnya_i_zavtra(t):
    """Кухонный стол: старые чашечные весы на пол-кадра, рядом чайник,
    записная книжка и карандаш. Женщина подпирает щёку левой ладонью,
    правой перекладывает листок с чаши «сегодня» на чашу «завтра»."""
    rnd = random.Random(257)
    pol = 980
    s = f'<rect width="{W}" height="{H}" fill="#2a2a2e"/>'
    s += SL(Z_DAL, _kafel(0, 30, 1060, 630, t, 23, "#d0d8d8"))
    s += SL(Z_DAL, doski(1060, 0, 860, 840, 92, True, "dosk"))
    s += SL(Z_DAL, doski(1060, 840, 860, 140, 92, True, "dosk"))
    # правая стена: полка с банками и связка сушёных травок в центре кадра
    s += SL(Z_DAL, _polka_s_utvaryu(1200, 420, 600, t, 173, 4))
    s += SL(Z_DAL, _polki_otkrytye(1120, 120, 740, t, 83, 2, True, .0))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-10:.0f}" width="{W}"'
                   f' height="{H-pol+10:.0f}" fill="#5a4c3c"/>'
            + _polovik(560, pol + 22, 820, 92, "#c0b094", "#7a6a52"))
    s += SL(Z_DAL, tusklaya_lampochka(620, 150, t, 1.2, True))
    # навесной шкафчик и полка в середине стены: центр кадра не пустует
    # ШКАФЧИК УХОДИТ ВЛЕВО: он стоял ровно за весами, и чашечные весы
    # пропадали в его тёмной дверце (осмотр порции 2)
    s += SL(Z_DAL, f'<rect x="60" y="240" width="520" height="300" rx="10"'
                   f' fill="url(#derev)" {o(6)}/>')
    for i in (0, 1):
        s += SL(Z_DAL, f'<rect x="{80+i*256:.0f}" y="262" width="236"'
                       f' height="256" rx="8" fill="#8a6a44" {o(5)}/>'
                f'<rect x="{102+i*256:.0f}" y="286" width="192" height="208"'
                f' rx="6" fill="url(#stekl)" opacity=".62" {o(3)}/>'
                f'<rect x="{186+i*256:.0f}" y="376" width="44" height="14" rx="7"'
                f' fill="url(#zhel)" {o(3)}/>')
    for i in range(4):
        s += SL(Z_DAL, _kruzhka(110 + i * 130, 530, .86, 0, "#eceff0", 1))
    s += SL(Z_DAL, _polki_otkrytye(70, 560, 460, t, 157, 1, True, .0))
    # за весами — светлый кафель и тёмная полоса под ними: латунь читается
    s += SL(Z_DAL, _kafel(620, 180, 700, 460, t, 191, "#e2e8e8"))
    # СТОЛ — крупный предмет
    s += SL(Z_SRED, stol(260, pol - 330, 1240, 40, True))
    sy = pol - 330
    # ВЕСЫ: чаша «сегодня» ходит ходуном, потом встают ровно
    per = A.ease(A.seg(t, 3.0, 1.4))
    dreb = (1 - per) * (1 - A.ease(A.seg(t, 2.6, .5)))
    # ВЕСЫ КРУПНЕЕ И ВЫШЕ: главный предмет сцены читается со стоп-кадра
    # ВЕСЫ ПРАВЕЕ: при x=960 левая чаша стояла ровно за фигурой (осмотр)
    s += SL(Z_SRED, _vesy(1180, sy - 8, t, 1.26, -.55 * (1 - per) + .04 * per,
                          dreb, 340))
    # листок перекладывается с левой чаши на правую
    lk = per
    lx = 1180 - 378 + 756 * lk
    ly = sy - 420 + 140 - 60 * math.sin(math.pi * lk)
    s += SL(Z_SRED, f'<g transform="rotate({-8 + 16 * lk:.1f} {lx:.0f} {ly:.0f})">'
                    f'<rect x="{lx-56:.0f}" y="{ly-40:.0f}" width="112" height="76"'
                    f' rx="6" fill="#f4efe0" {o(5)}/>'
            + f'<path d="M{lx-40:.0f},{ly-12:.0f} q26,-10 52,0" fill="none"'
              f' stroke="#9a8a68" stroke-width="6"/>'
            + f'<path d="M{lx-40:.0f},{ly+10:.0f} q26,-8 52,2" fill="none"'
              f' stroke="#b8a888" stroke-width="5"/></g>')
    # чайник, записная книжка, карандаш, чашка
    s += SL(Z_SRED, _chaynik(400, sy - 8, 1.2, t))
    s += SL(Z_SRED, par(400, sy - 140, t, 5, .5, 200, .44, 1.1))
    s += SL(Z_SRED, f'<rect x="1320" y="{sy-66:.0f}" width="190" height="66"'
                    f' rx="8" fill="#7a3a42" {o(6)}/>'
            + f'<rect x="1332" y="{sy-54:.0f}" width="166" height="48" rx="5"'
              f' fill="#f2ece0" {o(3)}/>'
            + f'<path d="M1350,{sy-30:.0f} q40,-12 80,2" fill="none"'
              f' stroke="#9a8a68" stroke-width="5"/>'
            + f'<line x1="1540" y1="{sy-16:.0f}" x2="1680" y2="{sy-40:.0f}"'
              f' stroke="#c9a05a" stroke-width="14" stroke-linecap="round"/>'
            + f'<path d="M1680,{sy-40:.0f} l26,-6 l-8,20 Z" fill="#3a3a42" {o(2)}/>')
    s += SL(Z_SRED, _kruzhka(1210, sy - 6, 1.05, 0, "#efe3d4", 1))
    # под столом и справа от него: корзина, вёдра, ящики, хлебница
    s += SL(Z_SRED, _dvorovaya_utvar(1080, pol - 4, 420, t, 167,
                                     ["korzina", "vedro", "korob"]))
    s += SL(Z_SRED, _yaschiki(1560, pol - 6, t, 169, 2, .96))
    # под столом: корзина с клубками, кадушка и кошачья плошка
    s += SL(Z_SRED, _dvorovaya_utvar(620, pol - 10, 420, t, 179,
                                     ["kadka", "korzina", "vedro"]))
    s += SL(Z_SRED, f'<ellipse cx="1040" cy="{pol-24:.0f}" rx="56" ry="20"'
                    f' fill="url(#glina)" {o(5)}/>'
            + f'<ellipse cx="1040" cy="{pol-30:.0f}" rx="42" ry="13"'
              f' fill="#8a5a30" opacity=".9"/>')
    s += SL(Z_SRED, f'<rect x="1120" y="{sy-96:.0f}" width="210" height="86"'
                    f' rx="18" fill="url(#solom)" {o(5)}/>'
            + f'<path d="M1130,{sy-96:.0f} q104,-42 190,0" fill="none"'
              f' stroke="#8a6a3c" stroke-width="9"/>'
            + karavay(1226, sy - 92, .5, False))
    # женщина за столом: подбородок на левой ладони, правая работает
    fx, fy, fh = 500, pol + 20, 640
    s += SL(Z_SRED, _venskiy_stul(430, pol + 10, 560, t, -2.0, True))
    jen = figura(fx, fy - 250, fh, t, col="#6a5a4a", kant="#ffd98a", ph=.3,
                 naklon=-6.0)
    j1, (n1x, n1y), _ = _ruka_so_sgibom(fx, fy - 250, fh, -1, fh * .26, 34,
                                        fh * .30, -48, t, "#6a5a4a",
                                        "#ffd98a", .3, 3.0)
    j2, (n2x, n2y), _ = _ruka(fx, fy - 250, fh, 1, fh * .56, 30 + 16 * lk, t,
                              "#6a5a4a", "#ffd98a", .7, 5.0)
    jen += j1 + j2
    # кардиган: borта и пуговицы
    jen += (f'<path d="M{fx-56:.0f},{fy-250-fh*.60:.0f} L{fx-20:.0f},{fy-250-fh*.58:.0f}'
            f' L{fx-26:.0f},{fy-250-fh*.16:.0f} L{fx-66:.0f},{fy-250-fh*.18:.0f} Z"'
            f' fill="#55473a" {o(4)}/>'
            f'<path d="M{fx+56:.0f},{fy-250-fh*.60:.0f} L{fx+20:.0f},{fy-250-fh*.58:.0f}'
            f' L{fx+26:.0f},{fy-250-fh*.16:.0f} L{fx+66:.0f},{fy-250-fh*.18:.0f} Z"'
            f' fill="#55473a" {o(4)}/>')
    s += SL(Z_SRED, jen)
    s += SL(Z_SRED, ten(fx, pol + 10, 150, 22, .4))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(n1x, n1y, fh, t, .3) + _varezhka(n2x, n2y, fh, t, .7))
    s += SL(Z_SRED, _pol_shvy(pol + 10, 1078, 47, 6, "#443828"))
    # низ кадра
    s += SL(Z_SRED, _dvorovaya_utvar(1540, pol + 86, 360, t, 89,
                                     ["vedro", "korzina"])
            + _yaschiki(96, pol + 80, t, 31, 2, .8)
            + _kot_zhivoy(1000, pol + 70, t, 1.0, "#443d37", .8)
            + kartoshka(1300, pol + 96, t, 6, 6, .95))
    s += SL(Z_PERED, ramka_pp("levo"))
    s += SL(Z_LETIT, par(1180, sy - 520, t, 3, .26, 150, .28, 1.2))
    s += vinetka(.42)
    return s


def toroplivyy_gost_v_dveryah(t):
    """Прихожая: вешалка с пальто, зеркало, зонт в подставке, коврик.
    Напористый мужчина в плаще тычет ручкой в бумагу, хозяйка спокойно
    выставила ладонь и держится за ручку двери."""
    rnd = random.Random(263)
    pol = 968
    s = f'<rect width="{W}" height="{H}" fill="#262a2e"/>'
    s += SL(Z_DAL, doski(0, 0, 1180, pol, 96, True, "dosk"))
    s += SL(Z_DAL, f'<rect x="1180" y="0" width="740" height="{pol:.0f}"'
                   f' fill="#3f4650"/>')
    s += SL(Z_DAL, f'<rect x="0" y="{pol-12:.0f}" width="{W}"'
                   f' height="{H-pol+12:.0f}" fill="#4a4136"/>')
    s += SL(Z_DAL, tusklaya_lampochka(520, 140, t, 1.15, True))
    # ВЕШАЛКА С ПАЛЬТО — крупный предмет
    s += SL(Z_SRED, _veshalka_s_paltom(120, 230, 1020, t, 3))
    # зеркало и зонт
    s += SL(Z_SRED, f'<rect x="1176" y="250" width="34" height="520" rx="12"'
                    f' fill="#6a5030" {o(6)}/>'
            + f'<path d="M1210,270 L1210,740 Q1210,760 1230,760 L1340,760'
              f' Q1360,760 1360,740 L1360,270 Q1360,250 1340,250 L1230,250'
              f' Q1210,250 1210,270 Z" fill="#6a5030" {o(6)}/>'
            + f'<rect x="1226" y="266" width="118" height="478" rx="10"'
              f' fill="#4a5a66" opacity=".92" {o(3)}/>'
            + f'<path d="M1240,700 L1300,300 L1330,300 L1264,700 Z"'
              f' fill="#9fc0d4" opacity="{.18+.1*abs(A.w(t,3.4)):.2f}"/>')
    s += SL(Z_SRED, _zont_v_podstavke(1420, pol - 10, t, 1.15))
    # обувная полка во всю вешалку и комод прихожей
    s += SL(Z_SRED, f'<rect x="150" y="{pol-240:.0f}" width="940" height="26"'
                    f' rx="8" fill="url(#dosk)" {o(5)}/>'
            + f'<rect x="150" y="{pol-130:.0f}" width="940" height="26" rx="8"'
              f' fill="url(#dosk)" {o(5)}/>')
    for i in range(6):
        bx = 200 + i * 150
        s += SL(Z_SRED, f'<path d="M{bx-54:.0f},{pol-240:.0f}'
                        f' q{20:.0f},{-70:.0f} {60:.0f},{-66:.0f}'
                        f' q{44:.0f},{10:.0f} {46:.0f},{66:.0f} Z"'
                        f' fill="{["#3a2e26", "#5a3a2c", "#2e3540"][i % 3]}" {o(5)}/>'
                f'<path d="M{bx-30:.0f},{pol-130:.0f} l{86:.0f},0 l{-10:.0f},{-80:.0f}'
                f' l{-62:.0f},0 Z" fill="{["#4a3a2c", "#3f4650"][i % 2]}" {o(4)}/>')
    s += SL(Z_SRED, _dvorovaya_utvar(1140, pol - 6, 400, t, 163,
                                     ["korzina", "korob"]))
    # дверь, которую хозяйка плавно закрывает
    zak = A.ease(A.seg(t, 2.8, 1.5))
    s += SL(Z_SRED, dver(1560, pol - 840, 360, 840, .55 - .5 * zak,
                         "url(#derev)", True, True))
    s += SL(Z_SRED, f'<rect x="1532" y="{pol-872:.0f}" width="416" height="40"'
                    f' rx="10" fill="#5b4428" {o(6)}/>')
    # мужчина в плаще в дверях
    gx, gy, gh = 1476, pol + 18, 790
    hlop = A.ease(A.seg(t, 2.1, .6))
    _figury_kadra((1476, pol + 18, 790), (940, pol + 44, 820))
    muz = figura(gx, gy, gh, t, col="#4a4e46", kant="#cfe4f5", shapka=True,
                 ph=.2, naklon=-5.0)
    g1, (t1x, t1y), _ = _ruka_mimo(gx, gy, gh, -1, gh * .40,
                              18 + 12 * A.w(t, .5, .1) * (1 - hlop), t,
                              "#4a4e46", "#cfe4f5", .2, 7.0)
    g2, (t2x, t2y), _ = _ruka_mimo(gx, gy, gh, -1, gh * .30, 44, t,
                              "#4a4e46", "#cfe4f5", .6, 5.0)
    muz += g1 + g2
    muz += (f'<path d="M{gx-70:.0f},{gy-gh*.60:.0f} q{70:.0f},{-28:.0f} {140:.0f},0'
            f' L{gx+86:.0f},{gy-gh*.10:.0f} q{-86:.0f},{26:.0f} {-172:.0f},0 Z"'
            f' fill="#565a50" {o(6)}/>'
            f'<path d="M{gx:.0f},{gy-gh*.58:.0f} L{gx+14:.0f},{gy-gh*.12:.0f}"'
            f' fill="none" stroke="{K}" stroke-width="5" opacity=".6"/>')
    s += SL(Z_SRED, muz)
    # раскрытая папка в левой руке: захлопывается
    s += SL(Z_SRED, f'<g transform="rotate({-10 + 8 * hlop:.1f} {t2x:.0f} {t2y:.0f})">'
                    f'<path d="M{t2x-130:.0f},{t2y-70:.0f} L{t2x+8:.0f},{t2y-86:.0f}'
                    f' L{t2x+8:.0f},{t2y+54:.0f} L{t2x-130:.0f},{t2y+70:.0f} Z"'
                    f' fill="#7a4a3c" {o(5)}/>'
            + f'<path d="M{t2x+8:.0f},{t2y-86:.0f}'
              f' L{t2x+8+130*(1-hlop):.0f},{t2y-70-16*(1-hlop):.0f}'
              f' L{t2x+8+130*(1-hlop):.0f},{t2y+70-16*(1-hlop):.0f}'
              f' L{t2x+8:.0f},{t2y+54:.0f} Z" fill="#f2ece0" {o(5)}/>'
            + f'<path d="M{t2x+30:.0f},{t2y-40:.0f} q{40*(1-hlop):.0f},{-12:.0f}'
              f' {80*(1-hlop):.0f},{2:.0f}" fill="none" stroke="#9a8a68"'
              f' stroke-width="6"/></g>')
    # ручка тычет в бумагу
    tyk = 16 * A.w(t, .45, .2) * (1 - hlop)
    s += SL(Z_SRED, f'<line x1="{t1x:.0f}" y1="{t1y:.0f}" x2="{t1x-70-tyk:.0f}"'
                    f' y2="{t1y+26:.0f}" stroke="#2b3038" stroke-width="13"'
                    f' stroke-linecap="round"/>')
    # хозяйка на коврике: правая ладонь вперёд, левая на ручке двери
    hx, hy, hh = 940, pol + 44, 820
    hoz = figura(hx, hy, hh, t, col="#6a4a52", kant="#ffd98a", platok=False,
                 ph=.7, naklon=2.0)
    h1, (d1x, d1y), _ = _ruka_mimo(hx, hy, hh, 1, hh * .44, 4, t,
                              "#6a4a52", "#ffd98a", .7, 3.0)
    h2, (d2x, d2y), _ = _ruka_mimo(hx, hy, hh, 1, hh * .30, 40, t,
                              "#6a4a52", "#ffd98a", .3, 3.0)
    hoz += h1 + h2
    s += SL(Z_SRED, hoz)
    # ладонь-стоп: раскрытая кисть рукавицей (пальцев не рисуем)
    s += SL(Z_SRED, f'<ellipse cx="{d1x+34:.0f}" cy="{d1y:.0f}" rx="46" ry="58"'
                    f' fill="#e8d8c0" {o(6)}/>'
            + f'<path d="M{d1x+54:.0f},{d1y-30:.0f} q24,16 0,40" fill="none"'
              f' stroke="#e8d8c0" stroke-width="22" stroke-linecap="round"/>')
    s += SL(Z_SRED, _polovik(820, pol + 20, 420, 110, "#8a5a52", "#c9a05a"))
    s += SL(Z_SRED, ten(hx, hy + 8, 176, 26, .45))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(t1x, t1y, gh, t, .2, "#dcd0bc")
            + _varezhka(t2x, t2y, gh, t, .6, "#dcd0bc")
            + _varezhka(d2x, d2y, hh, t, .3))
    s += SL(Z_SRED, _pol_shvy(pol + 12, 1078, 53, 6, "#3e3428"))
    # низ кадра
    s += SL(Z_SRED, _valenki_u_dveri(680, pol + 96, 1.0, t)
            + _gorodskoy_hlam(96, pol + 92, 420, t, 37,
                              ["korobka", "yaschik", "kust"])
            + _kot_zhivoy(1260, pol + 80, t, 1.0, "#423b35", .4))
    s += SL(Z_PERED, _stolb_pered(-8, 96, "#171210", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 520, 190, 5, 19, 150, .24))
    s += vinetka(.42)
    return s


def listok_chislennika_za_hozyayku(t):
    """Стена прихожей: отрывной численник на пол-кадра, под ним полочка с
    ключами, щётка для обуви, варежки. Хозяйка показывает на сегодняшний
    листок, за её плечом полупрозрачным контуром кивает бабушка."""
    rnd = random.Random(269)
    pol = 960
    s = f'<rect width="{W}" height="{H}" fill="#282c30"/>'
    s += SL(Z_DAL, doski(0, 0, 1080, pol, 100, True, "dosk"))
    s += SL(Z_DAL, f'<rect x="1080" y="0" width="840" height="{pol:.0f}"'
                   f' fill="#454c56"/>')
    for i in range(9):
        s += SL(Z_DAL, f'<rect x="{1090+i*94:.0f}" y="0" width="46"'
                       f' height="{pol:.0f}" fill="#4e5660" opacity=".6"/>')
    s += SL(Z_DAL, _ramki_na_stene(1150, 160, 700, t, 97, 4))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-12:.0f}" width="{W}"'
                   f' height="{H-pol+12:.0f}" fill="#4e4234"/>'
            + _polovik(640, pol + 26, 700, 96))
    s += SL(Z_DAL, tusklaya_lampochka(1480, 130, t, 1.1, True))
    # ПОЛКА во всю стену — крупный предмет, на ней хозяйство прихожей
    s += SL(Z_SRED, f'<rect x="60" y="640" width="1020" height="34" rx="10"'
                    f' fill="url(#dosk)" {o(6)}/>'
            + f'<rect x="60" y="674" width="1020" height="18" rx="7"'
              f' fill="#5b4428" {o(4)}/>')
    for i in range(5):
        s += SL(Z_SRED, f'<path d="M{130+i*220:.0f},692 l26,44 l-30,0 Z"'
                        f' fill="{ZHELEZ}" {o(3)}/>')
    # ЧИСЛЕННИК — главный предмет (листок пустой: цифру кладёт надпись)
    s += SL(Z_SRED, _chislennik(300, 160, 390, 460, t, .0))
    # ключи на крючках покачиваются
    for i in range(3):
        s += SL(Z_SRED, _svyazka_klyuchey(760 + i * 110, 730 + (i % 2) * 24, t,
                                          .96, i * .3, 3))
    # щётка для обуви и варежки на полке
    s += SL(Z_SRED, f'<rect x="150" y="588" width="230" height="52" rx="16"'
                    f' fill="#6a5030" {o(6)}/>')
    for i in range(14):
        s += SL(Z_SRED, f'<line x1="{162+i*16:.0f}" y1="640" x2="{162+i*16:.0f}"'
                        f' y2="672" stroke="#2e2620" stroke-width="7"/>')
    for i in (0, 1):
        mx = 470 + i * 150
        s += SL(Z_SRED, f'<path d="M{mx:.0f},590 q{-34:.0f},{34:.0f} {-18:.0f},{50:.0f}'
                        f' q{40:.0f},{14:.0f} {64:.0f},{-4:.0f}'
                        f' q{12:.0f},{-34:.0f} {-10:.0f},{-48:.0f} Z"'
                        f' fill="{["#8a4a52", "#3f5c7a"][i]}" {o(5)}/>'
                f'<path d="M{mx+54:.0f},612 q{30:.0f},{10:.0f} {18:.0f},{32:.0f}"'
                f' fill="none" stroke="{["#8a4a52", "#3f5c7a"][i]}" stroke-width="18"/>')
    s += SL(Z_SRED, _polka_s_utvaryu(1180, 400, 620, t, 101, 4))
    # контур бабушки за плечом: полупрозрачная фигура, кивает
    kiv = 7 * A.w(t, 1.7, .2)
    kx, ky, kh = 1230, pol + 30, 700
    _figury_kadra((1230, pol + 30, 700), (880, pol + 46, 828))
    kon = figura(kx, ky, kh, t, col="#9fb4c8", kant="#eaf4ff", platok=True,
                 ph=.5, op=.95, naklon=kiv * .3)
    k1, (u1x, u1y), _ = _ruka_mimo(kx, ky, kh, -1, kh * .34, 56, t,
                              "#9fb4c8", "#eaf4ff", .5, 3.0)
    k2, (u2x, u2y), _ = _ruka_mimo(kx, ky, kh, 1, kh * .32, 60, t,
                              "#9fb4c8", "#eaf4ff", .1, 3.0)
    kon += k1 + k2
    # ФИГУРА НЕПРОЗРАЧНАЯ (op не ниже 0,9): сквозь «контур бабушки» была
    # видна мебель, и фигура читалась дырой. Память показана ХОЛОДНЫМ
    # цветом и светлым кантом, а не прозрачностью.
    s += SL(Z_SRED, f'<g opacity=".92">{kon}</g>')
    # хозяйка: правая показывает на листок, левая на груди
    hx, hy, hh = 880, pol + 46, 828
    pok = A.ease(A.seg(t, .3, .9))
    hoz = figura(hx, hy, hh, t, col="#4a5a6a", kant="#ffd98a", ph=.8,
                 naklon=-4.0)
    h1, (y1x, y1y), _ = _ruka_mimo(hx, hy, hh, -1, hh * .48, -26 - 22 * pok, t,
                              "#4a5a6a", "#ffd98a", .8, 4.0)
    h2, (y2x, y2y), _ = _ruka_sgib_mimo(hx, hy, hh, 1, hh * .22, 50,
                                        hh * .24, -6, t, "#4a5a6a",
                                        "#ffd98a", .2, 3.0)
    hoz += h1 + h2
    s += SL(Z_SRED, hoz)
    s += SL(Z_SRED, f'<ellipse cx="{y1x-20:.0f}" cy="{y1y-14:.0f}" rx="40" ry="30"'
                    f' fill="#e8d8c0" {o(5)}/>'
            + f'<path d="M{y1x-44:.0f},{y1y-22:.0f} l-70,-26" fill="none"'
              f' stroke="#e8d8c0" stroke-width="20" stroke-linecap="round"/>')
    s += SL(Z_SRED, ten(hx, hy + 8, 178, 26, .45))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, _varezhka(y2x, y2y, hh, t, .2))
    s += SL(Z_SRED, _pol_shvy(pol + 12, 1078, 59, 6, "#413528"))
    # низ кадра
    s += SL(Z_SRED, _valenki_u_dveri(400, pol + 92, 1.05, t)
            + _gorodskoy_hlam(1480, pol + 90, 420, t, 41,
                              ["korobka", "kust", "yaschik"])
            + _kot_zhivoy(1080, pol + 76, t, 1.1, "#3f3933", .7)
            + _dvorovaya_utvar(96, pol + 96, 260, t, 103, ["korzina"]))
    s += SL(Z_PERED, ramka_pp("levo"))
    s += SL(Z_LETIT, iskra_let(t, 1480, 180, 5, 23, 140, .22))
    s += vinetka(.42)
    return s


def hvastun_na_zavalinke(t):
    """Завалинка у избы: трое мужиков. Средний в новой шапке встал, бьёт себя
    в грудь и показывает на новые сапоги, двое по бокам сидят. Из-за угла
    избы на хвастуна смотрит прищуренный Сглаз."""
    rnd = random.Random(271)
    gor = 700
    s = f'<rect width="{W}" height="{H}" fill="url(#nsumer)"/>'
    s += nebo("sumer", t, True, 29)
    s += oblaka(t, 170, 4, 31, .4, "#cdd7e4", 13.0)
    # ИЗБА — крупный предмет, с дымком из трубы
    s += SL(Z_DAL, izba_snaruzhi(640, gor - 40, 1040, t, True, True, 7))
    s += SL(Z_DAL, _derevnya_ryad(gor - 110, t, 13, ((1560, 330), (1860, 270))))
    s += SL(Z_DAL, goloe_derevo(1330, gor - 20, 520, t, 17, 9, "#3a3b43", True))
    s += SL(Z_DAL, _zabor_dosok(1180, gor - 180, 740, 190, 11, 56))
    s += SL(Z_SRED, f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor:.0f}"'
                    f' fill="#4e4030"/>'
            + _zemlya_faktura(gor + 40, 1050, 7, 16, "#3f3326")
            + _listya(53, 44, gor + 50, 1060)
            + _inej(59, 40, gor + 60, 1060))
    # ЗАВАЛИНКА
    s += SL(Z_SRED, _zavalinka(170, gor + 160, 1180, t, 180))
    zav_y = gor + 160 - 180 - 26
    # трое мужиков: рост через одного крупный/мелкий, наклон разный
    # сидящий слева — чешет затылок правой рукой
    ax, ay, ah = 380, zav_y + 30, 420
    _figury_kadra((380, zav_y + 30, 420), (1120, zav_y + 34, 390),
                  (740, zav_y + 48, 760))
    sid1 = figura(ax, ay, ah, t, col="#4e4a46", kant="#cfe4f5", shapka=True,
                  ph=.2, naklon=-7.0, profil=False)
    a1, (c1x, c1y), _ = _ruka_mimo(ax, ay, ah, 1, ah * .44, -48, t,
                              "#4e4a46", "#cfe4f5", .2, 8.0)
    a2, (c2x, c2y), _ = _ruka_mimo(ax, ay, ah, -1, ah * .34, 58, t,
                              "#4e4a46", "#cfe4f5", .6, 4.0)
    sid1 += a1 + a2
    s += SL(Z_SRED, sid1)
    # сидящий справа — обеими руками держит шапку на коленях, в профиль
    bx, by_, bh = 1120, zav_y + 34, 390
    sid2 = figura(bx, by_, bh, t, col="#5a5248", kant="#cfe4f5", boroda=True,
                  ph=.7, naklon=9.0, profil=True)
    b1, (e1x, e1y), _ = _ruka_mimo(bx, by_, bh, -1, bh * .40, 62, t,
                              "#5a5248", "#cfe4f5", .7, 4.0)
    b2, (e2x, e2y), _ = _ruka_mimo(bx, by_, bh, -1, bh * .32, 76, t,
                              "#5a5248", "#cfe4f5", .3, 4.0)
    sid2 += b1 + b2
    s += SL(Z_SRED, sid2)
    s += SL(Z_SRED, f'<ellipse cx="{(e1x+e2x)/2-16:.0f}" cy="{(e1y+e2y)/2:.0f}"'
                    f' rx="68" ry="34" fill="#4a3a2c" {o(5)}/>'
            + f'<path d="M{(e1x+e2x)/2-74:.0f},{(e1y+e2y)/2-6:.0f}'
              f' q{58:.0f},{-54:.0f} {116:.0f},{0:.0f} Z" fill="#5a4636" {o(4)}/>')
    # ХВАСТУН встал в середине — вдвое выше сидящих
    hx, hy, hh = 740, zav_y + 48, 760
    bit = 18 * A.w(t, .7, .1)
    hva = figura(hx, hy, hh, t, col="#3f5a6a", kant="#ffd98a", shapka=True,
                 ph=.4, naklon=3.0)
    h1, (g1x, g1y), _ = _ruka_sgib_mimo(hx, hy, hh, 1, hh * .24, 40,
                                        hh * .24, -14 + bit * .4, t,
                                        "#3f5a6a", "#ffd98a", .4, 6.0)
    h2, (g2x, g2y), _ = _ruka_mimo(hx, hy, hh, -1, hh * .46, 60, t,
                              "#3f5a6a", "#ffd98a", .8, 5.0)
    hva += h1 + h2
    s += SL(Z_SRED, hva)
    # новые сапоги, на которые он показывает
    s += SL(Z_SRED, _sapogi_novye(hx + 10, hy + 6, 1.18, t, 1.0))
    s += SL(Z_SRED, para_izo_rta(hx + 64, hy - hh * .80, t, .3, 1.2, .5)
            + para_izo_rta(ax + 50, ay - ah * .80, t, .7, .8, .4))
    # СГЛАЗ выглядывает из-за угла избы
    sg = A.ease(A.seg(t, .6, 1.2))
    s += SL(Z_SRED, _sglaz(1380 - 120 * sg, gor - 250, t, 1.15, .2, .92))
    s += SL(Z_SRED, ten(hx, hy + 8, 160, 24, .45))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    s += SL(Z_SRED, ""
            + ""
            + _varezhka(e1x, e1y, bh, t, .7, "#dcd0bc")
            + ""
            + _varezhka(g1x, g1y, hh, t, .4, "#dcd0bc")
            + _varezhka(g2x, g2y, hh, t, .8, "#dcd0bc"))
    # низ кадра: поленница, кадушка, кот, корзина, следы
    s += SL(Z_SRED, _polenica(1480, gor + 150, 400, 200, 7, 60)
            + _dvorovaya_utvar(96, gor + 330, 300, t, 107, ["kadka", "vedro"])
            + _kucha_listev(1320, 1050, 320, 109, 94)
            + _kot_zhivoy(560, gor + 340, t, 1.0, "#3b342f", .2)
            + _sledy(300, 1060, 740, 900, 6, 113, "#33281d", 1.2))
    # НИЗ КАДРА ОБЖИТ: корзина с репой, кадка, ведро, сани-волокуши,
    # охапка хвороста и грабли у завалинки (осмотр: низ пустовал)
    s += SL(Z_SRED, _kadushki_i_grabli(700, gor + 420, t, 151)
            + _dvorovaya_utvar(1060, gor + 400, 420, t, 157,
                               ["korzina", "meshok", "korob"])
            + _yaschiki(380, gor + 420, t, 163, 2, .92)
            + _luzha(1180, 1030, 170, t, .3))
    s += SL(Z_PERED, _vetka_pered(1980, 130, 780, 158, t, 11, "#241c16", 6))
    s += SL(Z_LETIT, mokryy_sneg(t, 22, 5, .5, .85))
    s += ramka_pp("levo")
    s += vinetka(.42)
    return s


def udacha_otvorachivaetsya(t):
    """Двор в три сцены по словам: та же хвастунья распахивает амбар с
    мешками, показывает силу, выставляет вперёд мужа и детей. Над каждой
    сценой проплывает Сглаз, а Удача с рогом изобилия уходит за ворота."""
    rnd = random.Random(277)
    gor = 640
    s = f'<rect width="{W}" height="{H}" fill="url(#nsumer)"/>'
    s += nebo("sumer", t, True, 37)
    s += oblaka(t, 150, 5, 41, .4, "#cdd7e4", 15.0)
    s += SL(Z_DAL, izba_snaruzhi(1700, gor - 30, 420, t, True, True, 19))
    s += SL(Z_DAL, goloe_derevo(120, gor, 560, t, 23, 9, "#3a3b43", True))
    s += SL(Z_DAL, _zabor_dosok(-20, gor - 150, 560, 160, 13, 54))
    s += SL(Z_SRED, f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor:.0f}"'
                    f' fill="#52412f"/>'
            + _zemlya_faktura(gor + 50, 1050, 11, 16, "#43362a")
            + _koleya(gor + 300, 127, 2)
            + _listya(61, 40, gor + 60, 1060)
            + _inej(67, 36, gor + 70, 1060))
    # АМБАР С МЕШКАМИ — крупный предмет, створки распахиваются
    rsk = A.ease(A.seg(t, .3, 1.1))
    s += SL(Z_SRED, _ambar_s_meshkami(40, gor - 430, 1020, 470, t, rsk, 5))
    # ПЕРВАЯ СЦЕНА: распахивает амбар обеими руками
    f1x, f1y, f1h = 430, gor + 340, 700
    _figury_kadra((430, gor + 340, 700), (960, gor + 210, 420),
                  (1430, gor + 400, 680), (1700, gor + 350, 580),
                  (1210, gor + 356, 290), (1596, gor + 362, 230))
    hv1 = figura(f1x, f1y, f1h, t, col="#8a3a42", kant="#ffd98a", platok=True,
                 ph=.2, naklon=-4.0)
    a1, (i1x, i1y), _ = _ruka_mimo(f1x, f1y, f1h, 1, f1h * .44, 10 - 26 * rsk, t,
                              "#8a3a42", "#ffd98a", .2, 5.0)
    a2, (i2x, i2y), _ = _ruka_mimo(f1x, f1y, f1h, -1, f1h * .44, 12 - 24 * rsk, t,
                              "#8a3a42", "#ffd98a", .6, 5.0)
    hv1 += a1 + a2
    s += SL(Z_SRED, hv1)
    # ВТОРАЯ СЦЕНА: сгибает правую руку, левая на поясе
    f2x, f2y, f2h = 960, gor + 210, 420
    sil = .5 + .5 * abs(A.w(t, 1.1, .2))
    hv2 = figura(f2x, f2y, f2h, t, col="#8a3a42", kant="#ffd98a", platok=True,
                 ph=.5, naklon=3.0)
    b1, (j1x, j1y), _ = _ruka_sgib_mimo(f2x, f2y, f2h, 1, f2h * .26, 6,
                                        f2h * .28, -52 + 10 * sil, t,
                                        "#8a3a42", "#ffd98a", .5, 5.0)
    b2, (j2x, j2y), _ = _ruka_sgib_mimo(f2x, f2y, f2h, -1, f2h * .20, 36,
                                        f2h * .22, 4, t, "#8a3a42",
                                        "#ffd98a", .9, 3.0)
    hv2 += b1 + b2
    s += SL(Z_SRED, hv2)
    # ТРЕТЬЯ СЦЕНА: обнимает мужа и детей, выставляя их вперёд.
    # Рост через одного: муж крупный, дети мелкие, один ребёнок со спины
    f3x, f3y, f3h = 1430, gor + 400, 680
    hv3 = figura(f3x, f3y, f3h, t, col="#8a3a42", kant="#ffd98a", platok=True,
                 ph=.8, naklon=-3.0)
    # ОБЪЯТИЕ БЕЗ НАРУЖНЫХ РУК: муж и дети стоят ВПЕРЕДИ и перекрывают её,
    # свои рукава фигуры видны по сторонам. Наружная рука здесь шла сквозь
    # голову Удачи — осмотр порции 2.
    s += SL(Z_SRED, hv3)
    # муж крупный, дети мелкие и РАЗНЫЕ: 580 / 290 / 230 — через одного,
    # один со спины, двое в профиль, наклон ±11°
    s += SL(Z_SRED, figura(1700, gor + 350, 580, t, col="#46506a",
                           kant="#cfe4f5", shapka=True, ph=.3, naklon=4.0,
                           profil=True))
    s += SL(Z_SRED, figura(1210, gor + 356, 290, t, col="#5a6a52",
                           kant="#cfe4f5", ph=.6, naklon=-11.0, lico=False))
    s += SL(Z_SRED, figura(1596, gor + 362, 230, t, col="#6a5a46",
                           kant="#cfe4f5", ph=.9, naklon=11.0, profil=True))
    s += SL(Z_SRED, para_izo_rta(f2x + 70, f2y - f2h * .80, t, .3, 1.1, .45)
            + para_izo_rta(f3x + 66, f3y - f3h * .80, t, .8, 1.0, .4))
    # СГЛАЗ над каждой сценой
    for i, sx in enumerate((430, 920, 1410)):
        pl = ((t * .22 + i * .33) % 1.0)
        s += SL(Z_SRED, _sglaz(sx + 160 * pl - 80, gor - 290 - 30 * math.sin(pl * 6.28),
                               t, .88, i * .3, .88))
    # УДАЧА поворачивается спиной и уходит за ворота
    # Удача уходит ПЕРЕДНИМ планом, ниже и крупнее: её рука больше не
    # проходит сквозь голову хвастуньи
    ux = 1060 + 420 * A.ease(A.seg(t, 2.6, 3.4))
    uh = 680
    spin = A.ease(A.seg(t, 2.2, .8))
    uda = figura(ux, gor + 470, uh, t, col="#c9a05a", kant="#ffd98a",
                 platok=True, ph=.1, naklon=2.0, lico=(spin < .5))
    s += SL(Z_SRED, uda)
    # рог изобилия прижат к груди СБОКУ, своими рукавами фигуры: наружная
    # рука отсюда шла сквозь голову ребёнка (осмотр порции 2)
    s += SL(Z_SRED, _rog_izobiliya(ux - uh * .34, gor + 470 - uh * .46,
                                   t, 1.0, .2))
    # ВОРОТА, за которые она уходит
    s += SL(Z_SRED, _vorota_dvora(1620, gor + 300, 360, 440, t,
                                  A.ease(A.seg(t, 2.4, 1.6))))
    # варежки на концах рукавов: предмет уже нарисован, хват ложится поверх
    # ВАРЕЖКИ СНЯТЫ: здесь руки ничего не держат (распахнутый амбар, показ
    # силы, объятие) — варежка без предмета читается светлым пятном и обещает
    # хват, которого нет (решение по осмотру порции 2).
    # низ кадра
    s += SL(Z_SRED, _kadushki_i_grabli(300, gor + 400, t, 11)
            + _polenica(840, gor + 250, 300, 180, 13, 58)
            + _kot_zhivoy(1080, gor + 420, t, 1.05, "#3b342f", .4)
            + _sledy(1880, 1060, 1300, 880, 7, 131, "#33281d", 1.2)
            + _kucha_listev(620, 1056, 300, 137, 90))
    s += SL(Z_PERED, _stolb_pered(-10, 110, "#1a120c", 0, H))
    s += SL(Z_LETIT, mokryy_sneg(t, 24, 5, .5, .9))
    s += vinetka(.42)
    return s


# ── ПОМОЩНИКИ ТРЕТЬЕЙ ПАРТИИ ───────────────────────────────────────────────

def _zmeyka_zavisti(x0, y0, x1, y1, t, ph=.0, s_=1.0):
    """Змейка зависти: зелёное тело волной, светлое брюшко, голова с глазом
    и раздвоенный язычок. Ползёт от окна к чужому дому."""
    k = ((t * .34 + ph) % 1.0)
    cx = x0 + (x1 - x0) * k
    cy = y0 + (y1 - y0) * k
    ug = math.degrees(math.atan2(y1 - y0, x1 - x0))
    s = (f'<g transform="rotate({ug:.1f} {cx:.0f} {cy:.0f})">'
         f'<path d="M{cx-140*s_:.0f},{cy:.0f}'
         f' q{35*s_:.0f},{-30*s_ + 12 * A.w(t, .9, ph):.0f} {70*s_:.0f},0'
         f' q{35*s_:.0f},{30*s_:.0f} {70*s_:.0f},0'
         f' q{35*s_:.0f},{-26*s_:.0f} {60*s_:.0f},{-6*s_:.0f}"'
         f' fill="none" stroke="#4e7a3c" stroke-width="{19*s_:.0f}"'
         f' stroke-linecap="round"/>'
         f'<path d="M{cx-140*s_:.0f},{cy+6*s_:.0f}'
         f' q{35*s_:.0f},{-30*s_:.0f} {70*s_:.0f},0'
         f' q{35*s_:.0f},{30*s_:.0f} {70*s_:.0f},0" fill="none"'
         f' stroke="#8fae5c" stroke-width="{7*s_:.0f}" opacity=".8"/>'
         f'<ellipse cx="{cx+66*s_:.0f}" cy="{cy-8*s_:.0f}" rx="{26*s_:.0f}"'
         f' ry="{17*s_:.0f}" fill="#4e7a3c" {o(4)}/>'
         f'<circle cx="{cx+74*s_:.0f}" cy="{cy-14*s_:.0f}" r="{6*s_:.0f}"'
         f' fill="#f4e06a"/>'
         f'<circle cx="{cx+76*s_:.0f}" cy="{cy-14*s_:.0f}" r="{2.6*s_:.0f}"'
         f' fill="{K}"/>'
         f'<path d="M{cx+90*s_:.0f},{cy-4*s_:.0f} l{20*s_:.0f},{-6*s_:.0f}'
         f' m{-20*s_:.0f},{6*s_:.0f} l{20*s_:.0f},{6*s_:.0f}" fill="none"'
         f' stroke="#b8352c" stroke-width="{5*s_:.0f}"/></g>')
    return s


def _korova(x, y, s_=1.0, t=0.0, otvorot=.0):
    """Корова в профиль: тулово с пятнами, рога, вымя, хвост с кистью.
    otvorot 0..1 — отворачивает голову от ведра."""
    gol = -26 * otvorot
    hv = 12 * A.w(t, 2.2, .1)
    s = (f'{ten(x, y + 8 * s_, 150 * s_, 24 * s_, .45)}'
         f'<ellipse cx="{x:.0f}" cy="{y-150*s_:.0f}" rx="{168*s_:.0f}"'
         f' ry="{104*s_:.0f}" fill="#e8e2d6" {o(7)}/>')
    for i, (dx, dy, rr) in enumerate(((-70, -30, 46), (40, -60, 38), (90, 10, 30))):
        s += (f'<ellipse cx="{x+dx*s_:.0f}" cy="{y-150*s_+dy*s_:.0f}"'
              f' rx="{rr*s_:.0f}" ry="{rr*.74*s_:.0f}" fill="#4a3e34"'
              f' opacity=".9"/>')
    for dx in (-120, -70, 70, 120):
        s += (f'<rect x="{x+dx*s_-17*s_:.0f}" y="{y-66*s_:.0f}" width="{34*s_:.0f}"'
              f' height="{66*s_:.0f}" rx="{10*s_:.0f}" fill="#e0d8ca" {o(5)}/>'
              f'<rect x="{x+dx*s_-19*s_:.0f}" y="{y-16*s_:.0f}" width="{38*s_:.0f}"'
              f' height="{18*s_:.0f}" rx="6" fill="#3a332c" {o(3)}/>')
    s += (f'<ellipse cx="{x+20*s_:.0f}" cy="{y-58*s_:.0f}" rx="{44*s_:.0f}"'
          f' ry="{32*s_:.0f}" fill="#f0c8c0" {o(4)}/>')
    s += (f'<g transform="rotate({gol:.1f} {x+160*s_:.0f} {y-200*s_:.0f})">'
          f'<ellipse cx="{x+216*s_:.0f}" cy="{y-176*s_:.0f}" rx="{74*s_:.0f}"'
          f' ry="{58*s_:.0f}" fill="#e8e2d6" {o(6)}/>'
          f'<ellipse cx="{x+268*s_:.0f}" cy="{y-150*s_:.0f}" rx="{40*s_:.0f}"'
          f' ry="{30*s_:.0f}" fill="#d8b0a8" {o(5)}/>'
          f'<circle cx="{x+278*s_:.0f}" cy="{y-156*s_:.0f}" r="{7*s_:.0f}"'
          f' fill="#5a4a42"/>'
          f'<circle cx="{x+252*s_:.0f}" cy="{y-144*s_:.0f}" r="{7*s_:.0f}"'
          f' fill="#5a4a42"/>'
          f'<ellipse cx="{x+232*s_:.0f}" cy="{y-204*s_:.0f}" rx="{12*s_:.0f}"'
          f' ry="{15*s_:.0f}" fill="{K}"/>'
          f'<path d="M{x+192*s_:.0f},{y-218*s_:.0f} q{-30*s_:.0f},{-34*s_:.0f}'
          f' {-8*s_:.0f},{-56*s_:.0f}" fill="none" stroke="#cdbf9c"'
          f' stroke-width="{15*s_:.0f}" stroke-linecap="round"/>'
          f'<path d="M{x+252*s_:.0f},{y-220*s_:.0f} q{28*s_:.0f},{-32*s_:.0f}'
          f' {8*s_:.0f},{-54*s_:.0f}" fill="none" stroke="#cdbf9c"'
          f' stroke-width="{15*s_:.0f}" stroke-linecap="round"/>'
          f'<path d="M{x+170*s_:.0f},{y-190*s_:.0f} q{-40*s_:.0f},{4*s_:.0f}'
          f' {-50*s_:.0f},{30*s_:.0f}" fill="none" stroke="#e0d8ca"'
          f' stroke-width="{22*s_:.0f}"/></g>')
    s += (f'<g transform="rotate({hv:.1f} {x-166*s_:.0f} {y-200*s_:.0f})">'
          f'<line x1="{x-166*s_:.0f}" y1="{y-200*s_:.0f}" x2="{x-186*s_:.0f}"'
          f' y2="{y-50*s_:.0f}" stroke="#d8d0c2" stroke-width="{11*s_:.0f}"/>'
          f'<ellipse cx="{x-188*s_:.0f}" cy="{y-34*s_:.0f}" rx="{13*s_:.0f}"'
          f' ry="{24*s_:.0f}" fill="#4a3e34" {o(3)}/></g>')
    return s


def _cvetok_v_gorshke(x, y, t, s_=1.0, vyanet=.0):
    """Цветок в глиняном горшке: поддон, земля, три листа и бутон. vyanet
    0..1 — листья опускаются и бледнеют, лепестки осыпаются."""
    s = (f'{ten(x, y + 6 * s_, 54 * s_, 11 * s_, .4)}'
         f'<path d="M{x-50*s_:.0f},{y-96*s_:.0f} L{x+50*s_:.0f},{y-96*s_:.0f}'
         f' L{x+38*s_:.0f},{y:.0f} L{x-38*s_:.0f},{y:.0f} Z"'
         f' fill="url(#glina)" {o(5)}/>'
         f'<rect x="{x-56*s_:.0f}" y="{y-110*s_:.0f}" width="{112*s_:.0f}"'
         f' height="{20*s_:.0f}" rx="7" fill="#9c6a44" {o(4)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-100*s_:.0f}" rx="{44*s_:.0f}"'
         f' ry="{11*s_:.0f}" fill="#4a3a28"/>')
    for i, a0 in enumerate((-150, -90, -30)):
        a = math.radians(a0 + 54 * vyanet + 5 * A.w(t, 3.0, i * .3))
        dl = 110 * s_
        ex = x + dl * math.cos(a)
        ey = y - 100 * s_ + dl * math.sin(a)
        col = "#6f8c4a" if vyanet < .5 else "#8a8a54"
        s += (f'<path d="M{x:.0f},{y-100*s_:.0f}'
              f' Q{(x+ex)/2+20*s_:.0f},{(y-100*s_+ey)/2-30*s_:.0f} {ex:.0f},{ey:.0f}'
              f' Q{(x+ex)/2-14*s_:.0f},{(y-100*s_+ey)/2+24*s_:.0f} {x:.0f},{y-100*s_:.0f} Z"'
              f' fill="{col}" {o(4)}/>')
    s += (f'<line x1="{x:.0f}" y1="{y-100*s_:.0f}" x2="{x+8*s_:.0f}"'
          f' y2="{y-200*s_+30*s_*vyanet:.0f}" stroke="#6f8c4a"'
          f' stroke-width="{8*s_:.0f}"/>')
    for i in range(5):
        a = math.radians(i * 72)
        pd = 1 - vyanet
        s += (f'<ellipse cx="{x+8*s_+22*s_*math.cos(a)*pd:.0f}"'
              f' cy="{y-200*s_+30*s_*vyanet+20*s_*math.sin(a)*pd:.0f}"'
              f' rx="{17*s_:.0f}" ry="{12*s_:.0f}" fill="#d6452a"'
              f' opacity="{.4+.6*pd:.2f}" {o(3)}/>')
    return s


def _sumka_hozyaystvennaya(x, y, t, s_=1.0, zast=.0):
    """Хозяйственная сумка: кожаные боковины, две дуги ручек, застёжка
    на замке и выпирающий бок. zast 0..1 — застёгивается."""
    return (f'{ten(x, y + 6 * s_, 86 * s_, 13 * s_, .45)}'
            f'<path d="M{x-96*s_:.0f},{y-130*s_:.0f} L{x+96*s_:.0f},{y-130*s_:.0f}'
            f' L{x+84*s_:.0f},{y:.0f} L{x-84*s_:.0f},{y:.0f} Z"'
            f' fill="#6a4a32" {o(6)}/>'
            f'<path d="M{x-96*s_:.0f},{y-130*s_:.0f} q{96*s_:.0f},{-34*s_*(1-zast):.0f}'
            f' {192*s_:.0f},0 l0,{18*s_:.0f} q{-96*s_:.0f},{-14*s_*(1-zast):.0f}'
            f' {-192*s_:.0f},0 Z" fill="#7d5a3c" {o(4)}/>'
            f'<path d="M{x-54*s_:.0f},{y-132*s_:.0f} q{18*s_:.0f},{-72*s_:.0f}'
            f' {52*s_:.0f},{-70*s_:.0f}" fill="none" stroke="#5a3a28"'
            f' stroke-width="{13*s_:.0f}"/>'
            f'<path d="M{x+54*s_:.0f},{y-132*s_:.0f} q{-18*s_:.0f},{-72*s_:.0f}'
            f' {-52*s_:.0f},{-70*s_:.0f}" fill="none" stroke="#5a3a28"'
            f' stroke-width="{13*s_:.0f}"/>'
            f'<rect x="{x-24*s_:.0f}" y="{y-128*s_:.0f}" width="{48*s_:.0f}"'
            f' height="{30*s_:.0f}" rx="8" fill="url(#zhel)" {o(4)}/>'
            f'<rect x="{x-34*s_:.0f}" y="{y-80*s_:.0f}" width="{68*s_:.0f}"'
            f' height="{14*s_:.0f}" rx="6" fill="#4a3222" opacity=".8"/>')


def _skameyka_podezda(x, y, w_, t, h_=150):
    """Скамейка у подъезда: две бетонные тумбы, три крашеные доски сиденья,
    облупившаяся краска и доска спинки."""
    s = (f'{ten(x + w_ / 2, y + 8, w_ * .44, 18, .45)}')
    for i in (0, 1):
        bx = x + 40 + i * (w_ - 150)
        s += (f'<rect x="{bx:.0f}" y="{y-h_:.0f}" width="110" height="{h_:.0f}"'
              f' rx="8" fill="{BETON}" {o(6)}/>'
              f'<rect x="{bx+12:.0f}" y="{y-h_+16:.0f}" width="86" height="{h_-40:.0f}"'
              f' rx="6" fill="{BETON2}" opacity=".7"/>')
    for i in range(3):
        s += (f'<rect x="{x:.0f}" y="{y-h_-28+i*2:.0f}" width="{w_:.0f}" height="26"'
              f' rx="8" fill="#4e7a52" {o(5)}/>'
              f'<rect x="{x+60+i*180:.0f}" y="{y-h_-26+i*2:.0f}" width="120"'
              f' height="12" rx="5" fill="#6b9a6e" opacity=".8"/>')
        y -= 0
    s += (f'<rect x="{x+20:.0f}" y="{y-h_-190:.0f}" width="{w_-40:.0f}" height="28"'
          f' rx="9" fill="#4e7a52" {o(5)}/>')
    for i in (0, 1):
        s += (f'<rect x="{x+60+i*(w_-180):.0f}" y="{y-h_-190:.0f}" width="26"'
              f' height="166" rx="8" fill="{BETON2}" {o(4)}/>')
    return s


def _golub(x, y, t, s_=1.0, ph=.0, hodit=True):
    """Голубь у скамейки: сизое тело, зелёная шейка, красные лапки, клюёт и
    переступает. Живая мелочь нижней трети."""
    sh = 16 * s_ * A.w(t, 1.9, ph) if hodit else 0
    kl = 14 * s_ * max(.0, A.w(t, 1.3, ph))
    return (f'<g transform="translate({sh:.1f},0)">'
            f'{ten(x, y + 4 * s_, 34 * s_, 8 * s_, .4)}'
            f'<ellipse cx="{x:.0f}" cy="{y-34*s_:.0f}" rx="{44*s_:.0f}"'
            f' ry="{28*s_:.0f}" fill="#8694a4" {o(4)}/>'
            f'<path d="M{x-40*s_:.0f},{y-40*s_:.0f} q{30*s_:.0f},{-18*s_:.0f}'
            f' {62*s_:.0f},{2*s_:.0f} q{-26*s_:.0f},{22*s_:.0f} {-62*s_:.0f},{-2*s_:.0f} Z"'
            f' fill="#6e7c8c" {o(3)}/>'
            f'<path d="M{x-44*s_:.0f},{y-30*s_:.0f} l{-28*s_:.0f},{8*s_:.0f}'
            f' l{26*s_:.0f},{10*s_:.0f} Z" fill="#7a8898" {o(3)}/>'
            f'<circle cx="{x+36*s_:.0f}" cy="{y-56*s_+kl:.0f}" r="{17*s_:.0f}"'
            f' fill="#9aa8b8" {o(3)}/>'
            f'<ellipse cx="{x+32*s_:.0f}" cy="{y-46*s_+kl:.0f}" rx="{13*s_:.0f}"'
            f' ry="{9*s_:.0f}" fill="#5c8a72" opacity=".9"/>'
            f'<path d="M{x+50*s_:.0f},{y-54*s_+kl:.0f} l{16*s_:.0f},{4*s_:.0f}'
            f' l{-16*s_:.0f},{5*s_:.0f} Z" fill="#3a3a42" {o(2)}/>'
            f'<circle cx="{x+42*s_:.0f}" cy="{y-60*s_+kl:.0f}" r="{3.4*s_:.0f}"'
            f' fill="{K}"/>'
            f'<line x1="{x-6*s_:.0f}" y1="{y-10*s_:.0f}" x2="{x-10*s_:.0f}"'
            f' y2="{y:.0f}" stroke="#b8503c" stroke-width="{5*s_:.0f}"/>'
            f'<line x1="{x+14*s_:.0f}" y1="{y-10*s_:.0f}" x2="{x+20*s_:.0f}"'
            f' y2="{y:.0f}" stroke="#b8503c" stroke-width="{5*s_:.0f}"/></g>')


def _komochek_radosti(x, y, t, s_=1.0, ph=.0):
    """Комочек-радость: тёплый светящийся шарик с улыбкой, щёчками и
    лучиками. Светится в сложенных лодочкой ладонях."""
    puls = 1.0 + .07 * A.w(t, 1.1, ph)
    s = (f'<g transform="translate({x:.0f} {y:.0f}) scale({puls:.3f})'
         f' translate({-x:.0f} {-y:.0f})">')
    for i in range(8):
        a = math.radians(i * 45 + 14 * A.w(t, 2.4, ph))
        s += (f'<line x1="{x+56*s_*math.cos(a):.0f}" y1="{y+56*s_*math.sin(a):.0f}"'
              f' x2="{x+(84+10*math.sin(t*2+i))*s_*math.cos(a):.0f}"'
              f' y2="{y+(84+10*math.sin(t*2+i))*s_*math.sin(a):.0f}"'
              f' stroke="#ffd98a" stroke-width="{7*s_:.0f}" opacity=".8"'
              f' stroke-linecap="round"/>')
    s += (f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{48*s_:.0f}" fill="#ffd98a"'
          f' {o(4)}/>'
          f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{34*s_:.0f}" fill="#fff0c4"'
          f' opacity=".9"/>')
    for i in (-1, 1):
        s += (f'<path d="M{x+i*17*s_-7*s_:.0f},{y-8*s_:.0f}'
              f' q{7*s_:.0f},{-9*s_:.0f} {14*s_:.0f},0" fill="none" stroke="#8a5a22"'
              f' stroke-width="{5*s_:.0f}" stroke-linecap="round"/>'
              f'<circle cx="{x+i*26*s_:.0f}" cy="{y+9*s_:.0f}" r="{8*s_:.0f}"'
              f' fill="#e08a74" opacity=".55"/>')
    s += (f'<path d="M{x-14*s_:.0f},{y+10*s_:.0f} q{14*s_:.0f},{14*s_:.0f}'
          f' {28*s_:.0f},0" fill="none" stroke="#8a5a22" stroke-width="{6*s_:.0f}"'
          f' stroke-linecap="round"/>'
          f'{teplo(x, y, 210 * s_, 190 * s_, .5)}</g>')
    return s


def _samovar(x, y, t, s_=1.0):
    """Самовар: пузатое тулово на поддоне, труба с коленом, краник с
    вентилем, две ручки и блик дугой. Пускает пар."""
    return (f'{ten(x, y + 8 * s_, 86 * s_, 15 * s_, .5)}'
            f'<path d="M{x-74*s_:.0f},{y-34*s_:.0f} L{x+74*s_:.0f},{y-34*s_:.0f}'
            f' L{x+54*s_:.0f},{y:.0f} L{x-54*s_:.0f},{y:.0f} Z"'
            f' fill="url(#med)" {o(5)}/>'
            f'<path d="M{x-88*s_:.0f},{y-150*s_:.0f}'
            f' q{-16*s_:.0f},{-80*s_:.0f} {30*s_:.0f},{-104*s_:.0f}'
            f' q{58*s_:.0f},{-18*s_:.0f} {116*s_:.0f},0'
            f' q{46*s_:.0f},{24*s_:.0f} {30*s_:.0f},{104*s_:.0f}'
            f' q{-10*s_:.0f},{36*s_:.0f} {-88*s_:.0f},{34*s_:.0f}'
            f' q{-78*s_:.0f},{2*s_:.0f} {-88*s_:.0f},{-34*s_:.0f} Z"'
            f' fill="url(#zol)" {o(7)}/>'
            f'<ellipse cx="{x:.0f}" cy="{y-254*s_:.0f}" rx="{74*s_:.0f}"'
            f' ry="{20*s_:.0f}" fill="#b5803a" {o(5)}/>'
            f'<rect x="{x-26*s_:.0f}" y="{y-330*s_:.0f}" width="{52*s_:.0f}"'
            f' height="{80*s_:.0f}" rx="8" fill="{ZHELEZ}" {o(5)}/>'
            f'<path d="M{x-26*s_:.0f},{y-330*s_:.0f} l{-40*s_:.0f},{-30*s_:.0f}'
            f' l{18*s_:.0f},{-26*s_:.0f} l{48*s_:.0f},{32*s_:.0f} Z"'
            f' fill="{ZHELEZ}" {o(4)}/>'
            f'<path d="M{x-96*s_:.0f},{y-190*s_:.0f} q{-44*s_:.0f},{20*s_:.0f}'
            f' {-6*s_:.0f},{54*s_:.0f}" fill="none" stroke="#8a5a22"'
            f' stroke-width="{15*s_:.0f}"/>'
            f'<path d="M{x+96*s_:.0f},{y-190*s_:.0f} q{44*s_:.0f},{20*s_:.0f}'
            f' {6*s_:.0f},{54*s_:.0f}" fill="none" stroke="#8a5a22"'
            f' stroke-width="{15*s_:.0f}"/>'
            f'<path d="M{x+56*s_:.0f},{y-112*s_:.0f} l{44*s_:.0f},{10*s_:.0f}'
            f' l{-6*s_:.0f},{26*s_:.0f} l{-42*s_:.0f},{-10*s_:.0f} Z"'
            f' fill="#b5803a" {o(4)}/>'
            f'<circle cx="{x+104*s_:.0f}" cy="{y-120*s_:.0f}" r="{14*s_:.0f}"'
            f' fill="url(#zhel)" {o(3)}/>'
            f'<path d="M{x-54*s_:.0f},{y-220*s_:.0f} q{20*s_:.0f},{-44*s_:.0f}'
            f' {10*s_:.0f},{-66*s_:.0f}" fill="none" stroke="#fff0c8"'
            f' stroke-width="{11*s_:.0f}" opacity="{.35+.3*abs(A.w(t,2.4)):.2f}"/>')


def _baranki(x, y, t, n=5, s_=1.0, svyazka=True):
    """Связка баранок: кольца с маковой обсыпкой на бечёвке, пара лежит
    рядом на столе. Качается, если висит."""
    rnd = random.Random(int(x) + n)
    kach = 2.6 * A.w(t, 2.8, .2)
    s = f'<g transform="rotate({kach:.1f} {x:.0f} {y:.0f})">'
    if svyazka:
        s += (f'<path d="M{x-120*s_:.0f},{y:.0f} q{120*s_:.0f},{54*s_:.0f}'
              f' {240*s_:.0f},0" fill="none" stroke="#cbbb98"'
              f' stroke-width="{6*s_:.0f}"/>')
    for i in range(n):
        p = i / max(1, n - 1.0)
        bx = x - 120 * s_ + 240 * s_ * p
        by = y + 54 * s_ * (1 - (2 * p - 1) ** 2) * .9
        rr = (30 + rnd.uniform(0, 7)) * s_
        s += (f'<circle cx="{bx:.0f}" cy="{by:.0f}" r="{rr:.0f}" fill="url(#med)"'
              f' {o(4)}/>'
              f'<circle cx="{bx:.0f}" cy="{by:.0f}" r="{rr*.36:.0f}" fill="none"'
              f' stroke="{K}" stroke-width="4"/>')
        for k in range(4):
            a = math.radians(k * 90 + 20)
            s += (f'<circle cx="{bx+rr*.66*math.cos(a):.0f}"'
                  f' cy="{by+rr*.66*math.sin(a):.0f}" r="{2.6*s_:.0f}"'
                  f' fill="#4a3522"/>')
    return s + "</g>"


def _kulak(x, y, s_=1.0, t=0.0, ph=.0, col="#e8d8c0"):
    """КУЛАК КОСТЯШКАМИ ВНИЗ: овал кисти, три бугра костяшек, тёмная тень
    под ними и светлый блик сверху. Ставится там, где рука стучит по столу
    и держать ей нечего — варежка-перекрытие тут неуместна."""
    s_ = max(.5, s_)
    return (f'{ten(x, y + 26 * s_, 40 * s_, 10 * s_, .45)}'
            f'<path d="M{x-40*s_:.0f},{y:.0f} q{-6*s_:.0f},{-34*s_:.0f}'
            f' {26*s_:.0f},{-38*s_:.0f} q{34*s_:.0f},{-6*s_:.0f}'
            f' {56*s_:.0f},{10*s_:.0f} q{14*s_:.0f},{28*s_:.0f}'
            f' {-6*s_:.0f},{44*s_:.0f} q{-38*s_:.0f},{14*s_:.0f}'
            f' {-76*s_:.0f},{-16*s_:.0f} Z" fill="{col}" {o(5)}/>'
            + "".join(
                f'<path d="M{x-26*s_+i*26*s_:.0f},{y+16*s_:.0f}'
                f' q{10*s_:.0f},{-14*s_:.0f} {22*s_:.0f},{-2*s_:.0f}"'
                f' fill="none" stroke="#c9a884" stroke-width="{max(2, 5 * s_):.0f}"/>'
                for i in range(3))
            + f'<path d="M{x-28*s_:.0f},{y-24*s_:.0f} q{26*s_:.0f},{-14*s_:.0f}'
              f' {54*s_:.0f},{-2*s_:.0f}" fill="none" stroke="#fff4e2"'
              f' stroke-width="{max(2, 5 * s_):.0f}" opacity=".6"/>')


def _krugi_po_stolu(cx, cy, t, n=3, ph=.0, rmax=260):
    """Круги, расходящиеся по столешнице от стука: три кольца догоняют друг
    друга, у каждого свой возраст и толщина."""
    s = ""
    for i in range(n):
        k = ((t * .9 + ph + i * .33) % 1.0)
        rr = rmax * k
        s += (f'<ellipse cx="{cx:.0f}" cy="{cy:.0f}" rx="{rr:.0f}"'
              f' ry="{rr*.32:.0f}" fill="none" stroke="#f6ead0"'
              f' stroke-width="{max(5, 14 - 8 * k):.0f}"'
              f' opacity="{.85*(1-k):.2f}"/>')
    return s


def _ploshka_s_meloch(x, y, t, s_=1.0, n=7, seed=5):
    """Глиняная плошка с безделушками: монетки, бусины, ленточка, глиняная
    свистулька и тряпичная куколка. Позвякивает, когда её несут."""
    rnd = random.Random(seed)
    dr = 2.4 * A.w(t, 1.4, .2)
    s = (f'<g transform="translate({dr:.1f},0)">'
         f'{ten(x, y + 8 * s_, 76 * s_, 13 * s_, .4)}'
         f'<path d="M{x-88*s_:.0f},{y-56*s_:.0f} q{16*s_:.0f},{62*s_:.0f}'
         f' {88*s_:.0f},{58*s_:.0f} q{72*s_:.0f},{4*s_:.0f} {88*s_:.0f},{-58*s_:.0f} Z"'
         f' fill="url(#glina)" {o(6)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-56*s_:.0f}" rx="{88*s_:.0f}"'
         f' ry="{20*s_:.0f}" fill="#8a5a30" {o(4)}/>')
    for i in range(n):
        mx = x + rnd.uniform(-62, 62) * s_
        my = y - 58 * s_ + rnd.uniform(-10, 6) * s_
        vid = i % 4
        if vid == 0:
            s += (f'<ellipse cx="{mx:.0f}" cy="{my:.0f}" rx="{17*s_:.0f}"'
                  f' ry="{9*s_:.0f}" fill="url(#med)" {o(3)}/>'
                  f'<ellipse cx="{mx-4*s_:.0f}" cy="{my-2*s_:.0f}" rx="{6*s_:.0f}"'
                  f' ry="{3*s_:.0f}" fill="#fff0c4"'
                  f' opacity="{.4+.4*abs(A.w(t,2.2,i*.2)):.2f}"/>')
        elif vid == 1:
            s += (f'<circle cx="{mx:.0f}" cy="{my:.0f}" r="{11*s_:.0f}"'
                  f' fill="{["#3f5c7a", "#8a4a52", "#4a6a48"][i % 3]}" {o(3)}/>'
                  f'<circle cx="{mx:.0f}" cy="{my:.0f}" r="{3.4*s_:.0f}"'
                  f' fill="{K}"/>')
        elif vid == 2:
            s += (f'<path d="M{mx-24*s_:.0f},{my:.0f} q{12*s_:.0f},{-14*s_:.0f}'
                  f' {24*s_:.0f},0 q{12*s_:.0f},{14*s_:.0f} {24*s_:.0f},0"'
                  f' fill="none" stroke="{TKAN}" stroke-width="{8*s_:.0f}"/>')
        else:
            s += (f'<path d="M{mx-14*s_:.0f},{my+6*s_:.0f} l{26*s_:.0f},{-8*s_:.0f}'
                  f' l{10*s_:.0f},{14*s_:.0f} l{-30*s_:.0f},{6*s_:.0f} Z"'
                  f' fill="#9c6a44" {o(3)}/>')
    s += (f'<path d="M{x+30*s_:.0f},{y-70*s_:.0f} q{14*s_:.0f},{-26*s_:.0f}'
          f' {34*s_:.0f},{-18*s_:.0f} q{-8*s_:.0f},{22*s_:.0f} {-18*s_:.0f},{28*s_:.0f} Z"'
          f' fill="#cfa0a8" {o(3)}/>'
          f'<circle cx="{x+54*s_:.0f}" cy="{y-96*s_:.0f}" r="{13*s_:.0f}"'
          f' fill="#e8d8c0" {o(3)}/></g>')
    return s



def _polati(x, y, w_, t, seed=3):
    """Полати над входом: настил на брусьях, свесившаяся рука, край одеяла,
    которое «дышит», и детская пятка. Спящие домашние, без лиц."""
    dyh = 5 * A.w(t, 3.4, .2)
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="34" rx="8"'
         f' fill="url(#dosk)" {o(6)}/>'
         f'<rect x="{x:.0f}" y="{y-26:.0f}" width="{w_:.0f}" height="30" rx="7"'
         f' fill="#5b4428" {o(5)}/>')
    for i in range(4):
        s += (f'<rect x="{x+30+i*(w_-100)/3:.0f}" y="{y+34:.0f}" width="26"'
              f' height="50" rx="7" fill="#4a3522" {o(4)}/>')
    s += (f'<g transform="translate(0,{dyh:.1f})">'
          f'<path d="M{x+80:.0f},{y-26:.0f} q{w_*.2:.0f},{-56:.0f} {w_*.44:.0f},{-20:.0f}'
          f' q{w_*.18:.0f},{30:.0f} {w_*.30:.0f},{20:.0f} l0,{26:.0f}'
          f' l{-w_*.74:.0f},0 Z" fill="#8a4a52" {o(5)}/>')
    for i in range(5):
        s += (f'<path d="M{x+120+i*90:.0f},{y-30:.0f} q{18:.0f},{-20:.0f}'
              f' {38:.0f},{-6:.0f}" fill="none" stroke="#a35a62"'
              f' stroke-width="7" opacity=".85"/>')
    s += "</g>"
    s += (f'<path d="M{x+w_*.72:.0f},{y+24:.0f} q{26:.0f},{64:.0f} {6:.0f},{104:.0f}"'
          f' fill="none" stroke="#e8d8c0" stroke-width="30" stroke-linecap="round"/>'
          f'<ellipse cx="{x+w_*.76:.0f}" cy="{y+140:.0f}" rx="26" ry="20"'
          f' fill="#e8d8c0" {o(4)}/>'
          f'<ellipse cx="{x+w_*.30:.0f}" cy="{y+40:.0f}" rx="30" ry="22"'
          f' fill="#f0cfae" {o(4)}/>'
          f'<ellipse cx="{x+w_*.38:.0f}" cy="{y+40:.0f}" rx="30" ry="22"'
          f' fill="#f0cfae" {o(4)}/>')
    return s


def _redka(cx, cy, s_=1.0, t=0.0, ug=0.0, kach=.0, cvet="#2e2b2a"):
    """ЧЁРНАЯ РЕДЬКА, КОТОРУЮ ВИДНО СО СТОП-КАДРА (R-0047): тёмное тулово
    каплей с продольными бороздами и светлыми чечевичками, срез кожуры,
    хвостик-корешок с волосками и пучок зелёной ботвы с прожилками.
    kach 0..1 — насколько сильно качается ботва."""
    rnd = random.Random(int(cx) + int(s_ * 100))
    sway = (3.0 + 7.0 * kach) * A.w(t, 2.2, .2)
    r = 86 * s_
    s = (f'<g transform="rotate({ug:.1f} {cx:.0f} {cy:.0f})">'
         f'{ten(cx, cy + r * .92, r * 1.0, r * .22, .5)}'
         f'<path d="M{cx-r:.0f},{cy-r*.34:.0f}'
         f' q{r*.10:.0f},{-r*.76:.0f} {r*1.0:.0f},{-r*.70:.0f}'
         f' q{r*.90:.0f},{r*.02:.0f} {r*1.0:.0f},{r*.70:.0f}'
         f' q{r*.06:.0f},{r*.84:.0f} {-r*1.0:.0f},{r*1.10:.0f}'
         f' q{-r*1.06:.0f},{-r*.26:.0f} {-r*1.0:.0f},{-r*1.10:.0f} Z"'
         f' fill="{cvet}" {o(7)}/>')
    for i in range(5):
        dx = -r * .62 + i * r * .32
        s += (f'<path d="M{cx+dx:.0f},{cy-r*.92:.0f}'
              f' q{r*.10:.0f},{r*.84:.0f} {dx*.14:.0f},{r*1.60:.0f}"'
              f' fill="none" stroke="#4a4644" stroke-width="{max(3, 7 * s_):.0f}"'
              f' opacity=".75"/>')
    for i in range(7):
        lx = cx + rnd.uniform(-r * .72, r * .72)
        ly = cy + rnd.uniform(-r * .70, r * .80)
        s += (f'<ellipse cx="{lx:.0f}" cy="{ly:.0f}" rx="{7 * s_:.0f}"'
              f' ry="{3.4 * s_:.0f}" fill="#8f8a84" opacity=".7"/>')
    s += (f'<path d="M{cx-r*.70:.0f},{cy-r*.52:.0f}'
          f' q{r*.40:.0f},{-r*.30:.0f} {r*.84:.0f},{-r*.12:.0f}" fill="none"'
          f' stroke="#cfc9c2" stroke-width="{max(3, 10 * s_):.0f}" opacity=".45"/>'
          f'<path d="M{cx+r*.30:.0f},{cy+r*.96:.0f}'
          f' q{r*.16:.0f},{r*.46:.0f} {-r*.04:.0f},{r*.78:.0f}" fill="none"'
          f' stroke="#cdbf9c" stroke-width="{max(3, 9 * s_):.0f}"'
          f' stroke-linecap="round"/>')
    for i in range(4):
        s += (f'<line x1="{cx+r*(.30+i*.04):.0f}" y1="{cy+r*(1.10+i*.16):.0f}"'
              f' x2="{cx+r*(.44+i*.05):.0f}" y2="{cy+r*(1.22+i*.16):.0f}"'
              f' stroke="#cdbf9c" stroke-width="{max(2, 4 * s_):.0f}"'
              f' opacity=".8"/>')
    # БОТВА: пять резных листьев веером, с прожилкой у каждого
    s += f'<g transform="rotate({sway:.1f} {cx:.0f} {cy - r * .96:.0f})">'
    for i in range(5):
        a = math.radians(-150 + i * 30)
        dl = (140 + (i % 2) * 44) * s_
        ex = cx + dl * math.cos(a)
        ey = cy - r * .96 + dl * math.sin(a)
        s += (f'<path d="M{cx:.0f},{cy-r*.96:.0f}'
              f' Q{(cx+ex)/2+30*s_:.0f},{(cy-r*.96+ey)/2-28*s_:.0f} {ex:.0f},{ey:.0f}'
              f' Q{(cx+ex)/2-24*s_:.0f},{(cy-r*.96+ey)/2+30*s_:.0f}'
              f' {cx:.0f},{cy-r*.96:.0f} Z" fill="{["#4e7a3c", "#5c8a40", "#3f6a34"][i % 3]}"'
              f' {o(4)}/>'
              f'<line x1="{cx:.0f}" y1="{cy-r*.96:.0f}" x2="{ex:.0f}" y2="{ey:.0f}"'
              f' stroke="#8fae5c" stroke-width="{max(2, 5 * s_):.0f}" opacity=".8"/>')
    s += "</g></g>"
    return s


# ── ДЕКОРАЦИИ, ТРЕТЬЯ ПАРТИЯ ───────────────────────────────────────────────

def zavist_v_chuzhih_oknah(t):
    """Деревенская улица, три избы в ряд: в каждом окне по соседу, руки на
    подоконниках, глаза позеленели. От окон к нарядному дому хвастуньи
    ползут зелёные змейки зависти, во дворе вянет цветок."""
    rnd = random.Random(281)
    gor = 690
    s = f'<rect width="{W}" height="{H}" fill="url(#nsumer)"/>'
    s += nebo("sumer", t, True, 43)
    s += oblaka(t, 160, 5, 47, .42, "#cdd7e4", 14.0)
    # три избы в ряд — средний план, у каждой своё окно с соседом
    mesta = ((190, 400), (620, 380), (1030, 420))
    for i, (bx, bw) in enumerate(mesta):
        s += SL(Z_DAL, izba_snaruzhi(bx, gor - 120 + i * 14, bw, t, True, True,
                                     7 + i * 5))
    s += SL(Z_DAL, goloe_derevo(1500, gor - 40, 520, t, 53, 9, "#3a3b43", True))
    s += SL(Z_DAL, _zabor_dosok(-30, gor - 210, 1300, 190, 17, 56))
    s += SL(Z_SRED, f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor:.0f}"'
                    f' fill="#4e4030"/>'
            + _zemlya_faktura(gor + 40, 1050, 19, 16, "#3f3326")
            + _koleya(gor + 230, 283, 2)
            + _listya(71, 44, gor + 50, 1060)
            + _inej(73, 40, gor + 60, 1060)
            + _pol_shvy(gor + 40, 1070, 79, 5, "#3a2c20"))
    # НАРЯДНЫЙ ДОМ ХВАСТУНЬИ справа — крупный предмет кадра
    s += SL(Z_SRED, izba_snaruzhi(1620, gor + 30, 1000, t, True, True, 23))
    s += SL(Z_SRED, _kryl_co(1450, gor + 60, 320, 120, t, 3, True, True))
    # три соседа в окнах: рост через одного, один в профиль, один со спины
    for i, (bx, bw) in enumerate(mesta):
        ox = bx + bw * .5
        oy = gor - 120 + i * 14 - bw * .30
        s += SL(Z_SRED, f'<rect x="{ox-96:.0f}" y="{oy-110:.0f}" width="192"'
                        f' height="150" rx="8" fill="#1b2029" {o(6)}/>'
                f'<rect x="{ox-110:.0f}" y="{oy+36:.0f}" width="220" height="26"'
                f' rx="8" fill="url(#dosk)" {o(5)}/>')
        fh = (270, 150, 230)[i]
        _figury_kadra((ox, oy + 42 + fh * .52, fh))
        sos = figura(ox, oy + 42 + fh * .52, fh, t,
                     col=("#4a4a56", "#5a5248", "#46506a")[i],
                     kant="#cfe4f5", platok=(i == 1), shapka=(i == 0),
                     boroda=(i == 2), ph=.2 + i * .3,
                     profil=(i == 2), lico=(i != 1), naklon=(-8, 12, -5)[i])
        r1, (s1x, s1y), _ = _ruka_mimo(ox, oy + 42 + fh * .52, fh, 1, fh * .42, 66, t,
                                  ("#4a4a56", "#5a5248", "#46506a")[i],
                                  "#cfe4f5", .2 + i * .2, 3.0)
        r2, (s2x, s2y), _ = _ruka_mimo(ox, oy + 42 + fh * .52, fh, -1, fh * .42, 70, t,
                                  ("#4a4a56", "#5a5248", "#46506a")[i],
                                  "#cfe4f5", .6 + i * .2, 3.0)
        sos += r1 + r2
        s += SL(Z_SRED, sos)
        s += SL(Z_SRED, ""
               )
        # позеленевшие глаза: зелёный отсвет поверх лица
        zel = .4 + .5 * abs(A.w(t, 1.6, i * .3))
        for sgn in (-1, 1):
            s += SL(Z_SRED, f'<circle cx="{ox+sgn*fh*.044:.0f}"'
                            f' cy="{oy+42+fh*.52-fh*.86:.0f}" r="{fh*.030:.0f}"'
                            f' fill="#6fae4c" opacity="{zel:.2f}"/>')
        s += SL(Z_SRED, para_izo_rta(ox + fh * .14, oy + 42 + fh * .52 - fh * .80,
                                     t, i * .3, .7, .4))
    # ЗМЕЙКИ ЗАВИСТИ ползут через улицу к дому
    for i, (bx, bw) in enumerate(mesta):
        s += SL(Z_SRED, _zmeyka_zavisti(bx + bw * .5, gor + 120 + i * 40,
                                        1540, gor + 230, t, i * .33, 1.05))
    # во дворе: цветок вянет, корова отворачивается от ведра
    vyan = A.ease(A.seg(t, .8, 2.4))
    s += SL(Z_SRED, _cvetok_v_gorshke(1420, gor + 64, t, 1.15, vyan))
    s += SL(Z_SRED, _korova(1080, 1052, .78, t, A.ease(A.seg(t, 1.6, 1.6))))
    s += SL(Z_SRED, _dvorovaya_utvar(1180, 1058, 180, t, 191, ["vedro"]))
    # пыль на новой шапке мужа: шапка на колу у крыльца
    s += SL(Z_SRED, f'<line x1="1760" y1="{gor+40:.0f}" x2="1764" y2="{gor-130:.0f}"'
                    f' stroke="url(#derev)" stroke-width="15"/>'
            + f'<ellipse cx="1764" cy="{gor-150:.0f}" rx="58" ry="30"'
              f' fill="#4a3a2c" {o(5)}/>'
            + f'<path d="M1710,{gor-154:.0f} q54,-50 108,0 Z" fill="#5a4636" {o(4)}/>')
    for i in range(7):
        k = ((t * .3 + i * .14) % 1.0)
        s += SL(Z_LETIT, f'<circle cx="{1740+i*12:.0f}"'
                         f' cy="{gor-210+40*k:.0f}" r="{4+2*i%4:.0f}"'
                         f' fill="#b9b2a4" opacity="{.5*(1-k):.2f}"/>')
    # низ кадра
    s += SL(Z_SRED, _polenica(130, gor + 220, 360, 190, 29, 58)
            + _kucha_listev(700, 1054, 330, 193, 92)
            + _kot_zhivoy(480, gor + 330, t, 1.0, "#3b342f", .6)
            + _sledy(1880, 1066, 1420, 880, 6, 197, "#33281d", 1.2))
    # НИЗ КАДРА ОБЖИТ: вёдра у колодезной лавки, кадка, корзина, лужа и
    # грабли поперёк улицы (осмотр: низ пустовал)
    s += SL(Z_SRED, _kadushki_i_grabli(300, 1040, t, 173)
            + _dvorovaya_utvar(860, 1046, 460, t, 179,
                               ["vedro", "korzina", "korob"])
            + _luzha(1560, 1020, 190, t, .5)
            + _yaschiki(1640, 1060, t, 181, 2, .86))
    s += SL(Z_PERED, _stolb_pered(-10, 108, "#1a120c", 0, H))
    s += SL(Z_LETIT, mokryy_sneg(t, 22, 5, .5, .85))
    s += vinetka(.40)
    return s


def tri_novosti_pri_sebe(t):
    """Скамейка у подъезда, три соседки. Средняя в берете по словам убирает
    в сумку коробку, дневник внука и тонометр, застёгивает её и кладёт на
    неё обе ладони. Вместо новостей показывает на небо."""
    rnd = random.Random(283)
    pol = 920
    s = f'<rect width="{W}" height="{H}" fill="#3a4048"/>'
    s += SL(Z_DAL, panelka(60, 620, 900, t, 5, True, 7))
    s += SL(Z_DAL, panelka(1020, 600, 860, t, 5, True, 13))
    s += SL(Z_DAL, goloe_derevo(960, 640, 520, t, 59, 9, "#3a3b43", False))
    s += SL(Z_SRED, _asfalt(pol - 40, 1080, 7, 30))
    s += SL(Z_SRED, _pol_shvy(pol + 20, 1070, 83, 6, "#3c3d40"))
    # подъезд: крыльцо с навесом, дверь, урна, столбики — крупный предмет
    s += SL(Z_SRED, f'<rect x="60" y="{pol-560:.0f}" width="520" height="560"'
                    f' rx="8" fill="{BETON2}" {o(7)}/>'
            + f'<rect x="100" y="{pol-500:.0f}" width="440" height="460" rx="8"'
              f' fill="#3f4650" {o(6)}/>'
            + f'<rect x="120" y="{pol-470:.0f}" width="190" height="430" rx="6"'
              f' fill="url(#derev)" {o(5)}/>'
            + f'<rect x="330" y="{pol-470:.0f}" width="190" height="430" rx="6"'
              f' fill="url(#derev)" {o(5)}/>'
            + f'<rect x="40" y="{pol-600:.0f}" width="580" height="46" rx="10"'
              f' fill="#6a7278" {o(6)}/>')
    s += SL(Z_SRED, tusklaya_lampochka(320, pol - 548, t, 1.1, False))
    s += SL(Z_SRED, _konus_sveta(320, pol - 520, 520, 460, 0, .38))
    # СКАМЕЙКА
    s += SL(Z_SRED, _skameyka_podezda(700, pol + 10, 1020, t, 160))
    # три соседки: рост через одного, одна в профиль, одна со спины
    ros = (470, 300, 450)
    cvet = ("#6a4a52", "#4a5a6a", "#5a4a62")
    tochki = []
    for i in range(3):
        fx = 830 + i * 320
        fh = ros[i]
        fig = figura(fx, pol - 90, fh, t, col=cvet[i], kant="#ffd98a",
                     platok=(i != 1), ph=.2 + i * .35,
                     profil=(i == 2), lico=(i != 0),
                     naklon=(-6, 4, 9)[i])
        u1 = (58, 30 - 26 * A.ease(A.seg(t, 3.6, 1.0)), 62)[i]
        r1, (p1x, p1y), _ = _ruka(fx, pol - 90, fh, 1, fh * .46, u1, t,
                                  cvet[i], "#ffd98a", .2 + i * .2, 4.0)
        r2, (p2x, p2y), _ = _ruka(fx, pol - 90, fh, -1, fh * .44, 62, t,
                                  cvet[i], "#ffd98a", .6 + i * .2, 4.0)
        fig += r1 + r2
        if i == 1:
            # БЕРЕТ НА ТЕМЕНИ, А НЕ НА ГЛАЗАХ: на .90 роста он садился ровно
            # на лицо (осмотр порции 2). Верх головы = рост × .99.
            fig += (f'<ellipse cx="{fx:.0f}" cy="{pol-90-fh*.985:.0f}"'
                    f' rx="{fh*.17:.0f}" ry="{fh*.055:.0f}" fill="#8a4a52" {o(4)}/>'
                    f'<path d="M{fx-fh*.17:.0f},{pol-90-fh*.985:.0f}'
                    f' q{fh*.17:.0f},{-fh*.075:.0f} {fh*.34:.0f},0 Z"'
                    f' fill="#9c5a62" {o(3)}/>'
                    f'<circle cx="{fx+fh*.05:.0f}" cy="{pol-90-fh*1.045:.0f}"'
                    f' r="{fh*.026:.0f}" fill="#8a4a52" {o(2)}/>')
        s += SL(Z_SRED, fig)
        tochki.append((p1x, p1y, p2x, p2y, fh, i))
    # СУМКА на коленях средней: вещи уходят в неё по одной
    # сумка НА КОЛЕНЯХ: при pol-180 она ложилась ровно на лицо средней
    # соседки (осмотр порции 2 — закрыто 100%)
    sx = 1150
    zast = A.ease(A.seg(t, 3.2, .8))
    veschi = ("korobka", "dnevnik", "tonometr")
    for i, v in enumerate(veschi):
        k = A.ease(A.seg(t, .4 + i * .85, .7))
        vx = 1480 - 190 * k
        vy = pol - 300 + 190 * k
        if k >= 1.0:
            # вещь уже в сумке, но ВИДНА: торчит над её краем, а не исчезает
            vx, vy = sx - 120 + i * 120, pol - 140
        if v == "korobka":
            s += SL(Z_SRED, f'<rect x="{vx-66:.0f}" y="{vy-56:.0f}" width="132"'
                            f' height="100" rx="8" fill="#c9b79c" {o(5)}/>'
                    f'<path d="M{vx-66:.0f},{vy-20:.0f} h132" stroke="#9a8a68"'
                    f' stroke-width="6"/>'
                    f'<path d="M{vx-70:.0f},{vy-56:.0f} q{70:.0f},{-34:.0f}'
                    f' {140:.0f},0" fill="none" stroke="#b8352c" stroke-width="8"/>')
        elif v == "dnevnik":
            s += SL(Z_SRED, f'<rect x="{vx-50:.0f}" y="{vy-62:.0f}" width="100"'
                            f' height="126" rx="7" fill="#3f5c7a" {o(5)}/>'
                    f'<rect x="{vx-40:.0f}" y="{vy-50:.0f}" width="80" height="102"'
                    f' rx="5" fill="#f2ece0" opacity=".9"/>'
                    f'<path d="M{vx-28:.0f},{vy-20:.0f} q26,-10 52,2" fill="none"'
                    f' stroke="#9a8a68" stroke-width="5"/>')
        else:
            s += SL(Z_SRED, f'<rect x="{vx-56:.0f}" y="{vy-40:.0f}" width="112"'
                            f' height="80" rx="12" fill="#5e676e" {o(5)}/>'
                    f'<circle cx="{vx-16:.0f}" cy="{vy:.0f}" r="22"'
                    f' fill="#eaf0f4" {o(3)}/>'
                    f'<path d="M{vx+20:.0f},{vy-16:.0f} q{30:.0f},{18:.0f}'
                    f' {8:.0f},{44:.0f}" fill="none" stroke="#3a4049"'
                    f' stroke-width="9"/>')
    s += SL(Z_SRED, _sumka_hozyaystvennaya(sx, pol - 50, t, .78, zast))
    # варежки поверх вещей и сумки
    for p1x, p1y, p2x, p2y, fh, i in tochki:
        s += SL(Z_SRED, ""
               )
    # голуби у скамейки и урна
    for i in range(4):
        s += SL(Z_SRED, _golub(620 + i * 230, 1050 + (i % 2) * 20, t,
                               1.05 + (i % 3) * .12, i * .3, True))
    s += SL(Z_SRED, f'<path d="M1800,{pol+10:.0f} L1900,{pol+10:.0f}'
                    f' L1884,{pol-170:.0f} L1816,{pol-170:.0f} Z"'
                    f' fill="#5e676e" {o(6)}/>'
            + f'<ellipse cx="1850" cy="{pol-170:.0f}" rx="34" ry="12"'
              f' fill="#3e4348" {o(4)}/>')
    # низ кадра
    s += SL(Z_SRED, _gorodskoy_hlam(170, pol + 40, 420, t, 43,
                                    ["stolbik", "korobka", "kust"])
            + _kot_zhivoy(1660, 1056, t, 1.1, "#423b35", .5)
            + _kucha_listev(520, 1062, 300, 199, 86))
    s += SL(Z_PERED, _vetka_pered(1980, 120, 740, 160, t, 19, "#241c16", 6))
    s += SL(Z_LETIT, mokryy_sneg(t, 20, 5, .45, .8))
    s += vinetka(.40)
    return s


def radost_v_ladonyah(t):
    """Окно дома снаружи: на подоконнике цветы, занавеска. Женщина в комнате
    держит в сложенных лодочкой ладонях светящийся комочек-радость и
    задёргивает занавеску локтем. Сглаз заглядывает и летит дальше."""
    rnd = random.Random(293)
    gor = 760
    s = f'<rect width="{W}" height="{H}" fill="url(#nsumer)"/>'
    s += nebo("sumer", t, True, 61)
    s += oblaka(t, 150, 4, 67, .38, "#cdd7e4", 15.0)
    # СТЕНА ДОМА с наличниками — крупный предмет, окно в середине
    s += SL(Z_DAL, brevna(120, 60, 1100, gor - 60, 96)
            + brevna(1220, 110, 700, gor - 110, 96))
    s += SL(Z_DAL, f'<path d="M80,80 L700,-40 L1320,80 Z" fill="#4a3a28" {o(7)}/>'
            + f'<rect x="60" y="60" width="1280" height="44" rx="10"'
              f' fill="#5b4428" {o(6)}/>')
    # окно: рама, наличники с резьбой, подоконник с цветами
    ox, oy, ow, oh = 420, 230, 620, 420
    s += SL(Z_SRED, f'<rect x="{ox-40:.0f}" y="{oy-40:.0f}" width="{ow+80:.0f}"'
                    f' height="{oh+80:.0f}" rx="10" fill="#6a5030" {o(7)}/>'
            + f'<rect x="{ox:.0f}" y="{oy:.0f}" width="{ow:.0f}" height="{oh:.0f}"'
              f' fill="#2b3550" opacity=".95"/>')
    for i in range(7):
        s += SL(Z_SRED, f'<path d="M{ox-46+i*106:.0f},{oy-46:.0f} l34,-44 l34,44 Z"'
                        f' fill="#7d5a3c" {o(4)}/>')
    s += SL(Z_SRED, f'<rect x="{ox-70:.0f}" y="{oy+oh:.0f}" width="{ow+140:.0f}"'
                    f' height="44" rx="10" fill="url(#dosk)" {o(6)}/>')
    # ЗАНАВЕСКА задёргивается
    zad = A.ease(A.seg(t, .8, 1.5))
    s += SL(Z_SRED, zanaveska(ox + 10, oy + 10, oh - 20, 180 + 220 * zad,
                              "#e8dcc0", t, 1)
            + zanaveska(ox + ow - 10, oy + 10, oh - 20, 180 + 220 * zad,
                        "#e8dcc0", t, -1))
    # женщина в комнате у окна: обе ладони лодочкой у груди
    fx, fy, fh = 730, oy + oh + 110, 520
    jen = figura(fx, fy, fh, t, col="#5a4a62", kant="#ffd98a", platok=True,
                 ph=.3, naklon=-4.0)
    j1, (l1x, l1y), _ = _ruka_so_sgibom(fx, fy, fh, 1, fh * .22, 42,
                                        fh * .24, -18, t, "#5a4a62",
                                        "#ffd98a", .3, 3.0)
    j2, (l2x, l2y), _ = _ruka_so_sgibom(fx, fy, fh, -1, fh * .22, 46,
                                        fh * .24, -14, t, "#5a4a62",
                                        "#ffd98a", .7, 3.0)
    jen += j1 + j2
    s += SL(Z_SRED, f'<g clip-path="none">{jen}</g>')
    # КОМОЧЕК-РАДОСТЬ светится между ладонями
    # КОМОЧЕК НИЖЕ И МЕЛЬЧЕ: у груди, а не под подбородком. С мимикой и в
    # размер головы он читался ВТОРЫМ ЛИЦОМ под лицом фигуры (осмотр).
    kx, ky = (l1x + l2x) / 2, (l1y + l2y) / 2 + 58
    s += SL(Z_SRED, _komochek_radosti(kx, ky, t, .62, .1))
    s += SL(Z_SRED, "")
    # комочек живой: от него летят искорки — это и есть тёплое пятно сцены
    s += SL(Z_SRED, iskra_let(t, kx, ky, 9, 103, 150, .5))
    # цветы на подоконнике покачиваются
    for i in range(4):
        s += SL(Z_SRED, _cvetok_v_gorshke(ox + 70 + i * 160, oy + oh + 44, t,
                                          .92 + (i % 3) * .1, .0))
    # СГЛАЗ пролетает мимо окна и ничего не видит
    pl = A.seg(t, .2, 3.0)
    s += SL(Z_PERED, _sglaz(-120 + 2200 * pl, oy - 60 + 60 * math.sin(pl * 6.0),
                            t, .8, .2, .9))
    # земля под окном: завалинка, поленница, кадушка, следы, кот
    s += SL(Z_SRED, f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor:.0f}"'
                    f' fill="#4e4030"/>'
            + _zemlya_faktura(gor + 30, 1050, 23, 15, "#3f3326")
            + _listya(101, 42, gor + 40, 1060)
            + _inej(103, 36, gor + 50, 1060)
            + _pol_shvy(gor + 30, 1070, 107, 5, "#3a2c20"))
    s += SL(Z_SRED, _zavalinka(140, gor + 150, 1060, t, 160))
    s += SL(Z_SRED, _polenica(1300, gor + 120, 420, 200, 31, 60)
            + _kadushki_i_grabli(170, gor + 330, t, 13)
            + _kucha_listev(900, 1056, 320, 109, 90)
            + _kot_zhivoy(700, gor + 330, t, 1.05, "#3b342f", .3)
            + _sledy(1880, 1066, 1360, 900, 6, 113, "#33281d", 1.2))
    s += SL(Z_SRED, teplo(730, oy + oh * .5, 520, 420, .40))
    s += SL(Z_PERED, _vetka_pered(-70, 130, 700, 24, t, 23, "#241c16", 6))
    s += SL(Z_LETIT, mokryy_sneg(t, 22, 5, .5, .85))
    s += vinetka(.40)
    return s


def babushka_shepchet_na_uho(t):
    """Кухня, стол с самоваром, баранки, варенье в розетках. Бабушка
    наклонилась к дочери и прикрывает рот ладонью, как ширмой; дочь слушает
    с чашкой, а за окном соседка идёт с вёдрами на коромысле."""
    rnd = random.Random(307)
    pol = 964
    s = f'<rect width="{W}" height="{H}" fill="#2a241c"/>'
    s += SL(Z_DAL, brevna(0, 40, 1060, pol - 40, 96)
            + brevna(1060, 40, 860, pol - 40, 96))
    s += SL(Z_DAL, _polka_s_utvaryu(80, 230, 620, t, 109, 5))
    s += SL(Z_DAL, _polka_s_utvaryu(96, 520, 560, t, 113, 4))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-16:.0f}" width="{W}"'
                   f' height="{H-pol+16:.0f}" fill="#5e4a34"/>'
            + polovicy(pol + 18) + _pol_shvy(pol + 20, 1070, 127, 6, "#4a3824"))
    # ОКНО: за ним улица, по ней идёт соседка с коромыслом
    wx, wy, ww, wh = 1180, 210, 620, 400
    s += SL(Z_DAL, f'<rect x="{wx:.0f}" y="{wy:.0f}" width="{ww:.0f}"'
                   f' height="{wh:.0f}" fill="#46536b"/>')
    s += SL(Z_DAL, ulica_dal(wx, wy + wh - 40, ww, t, False, 29))
    kx = wx - 160 + 940 * A.seg(t, .2, 4.6)
    kh2 = 210
    sos = figura(kx, wy + wh - 30, kh2, t, col="#46506a", kant="#cfe4f5",
                 platok=True, ph=.4, profil=True, naklon=4.0)
    # она в слое Z_DAL за стеклом — обычная `_ruka`, обходить фигуры
    # другого плана ей не нужно
    c1, (m1x, m1y), _ = _ruka(kx, wy + wh - 30, kh2, 1, kh2 * .34, -30, t,
                              "#46506a", "#cfe4f5", .4, 4.0)
    c2, (m2x, m2y), _ = _ruka(kx, wy + wh - 30, kh2, -1, kh2 * .34, -26, t,
                              "#46506a", "#cfe4f5", .8, 4.0)
    sos += c1 + c2
    # коромысло с вёдрами — палка 300 px, держится обеими руками
    sos += (f'<line x1="{m2x-26:.0f}" y1="{m2y-16:.0f}" x2="{m1x+26:.0f}"'
            f' y2="{m1y-16:.0f}" stroke="url(#derev)" stroke-width="15"'
            f' stroke-linecap="round"/>')
    for ex in (m2x - 14, m1x + 14):
        sos += (f'<line x1="{ex:.0f}" y1="{m1y-12:.0f}" x2="{ex:.0f}"'
                f' y2="{m1y+40:.0f}" stroke="#8a6a3c" stroke-width="5"/>'
                f'<path d="M{ex-26:.0f},{m1y+40:.0f} L{ex+26:.0f},{m1y+40:.0f}'
                f' L{ex+18:.0f},{m1y+94:.0f} L{ex-18:.0f},{m1y+94:.0f} Z"'
                f' fill="url(#zhel)" {o(4)}/>')
    sos += _varezhka(m1x, m1y, kh2, t, .4, "#dcd0bc")
    sos += ""
    s += SL(Z_DAL, f'<g clip-path="none">{sos}</g>')
    s += SL(Z_SRED, f'<rect x="{wx-34:.0f}" y="{wy-34:.0f}" width="{ww+68:.0f}"'
                    f' height="{wh+68:.0f}" rx="10" fill="none" stroke="#6a5030"'
                    f' stroke-width="30"/>'
            + f'<line x1="{wx+ww*.5:.0f}" y1="{wy:.0f}" x2="{wx+ww*.5:.0f}"'
              f' y2="{wy+wh:.0f}" stroke="#6a5030" stroke-width="20"/>'
            + f'<line x1="{wx:.0f}" y1="{wy+wh*.5:.0f}" x2="{wx+ww:.0f}"'
              f' y2="{wy+wh*.5:.0f}" stroke="#6a5030" stroke-width="18"/>'
            + f'<rect x="{wx-54:.0f}" y="{wy+wh+30:.0f}" width="{ww+108:.0f}"'
              f' height="42" rx="10" fill="url(#dosk)" {o(6)}/>')
    # СТОЛ — крупный предмет, на нём самовар, баранки, варенье
    s += SL(Z_SRED, stol(180, pol - 320, 1180, 40, True))
    sy = pol - 320
    s += SL(Z_SRED, _samovar(500, sy - 6, t, 1.0))
    s += SL(Z_SRED, par(500, sy - 350, t, 5, .5, 210, .42, 1.2))
    s += SL(Z_SRED, _baranki(880, sy - 60, t, 5, 1.0, True))
    s += SL(Z_SRED, _baranki(1180, sy - 10, t, 3, .92, False))
    for i in range(3):
        s += SL(Z_SRED, f'<path d="M{700+i*120:.0f},{sy-8:.0f}'
                        f' q{40:.0f},{40:.0f} {80:.0f},0 Z" fill="#f0ece0" {o(5)}/>'
                f'<ellipse cx="{740+i*120:.0f}" cy="{sy-10:.0f}" rx="40" ry="13"'
                f' fill="#9c2f28" opacity=".9"/>')
    s += SL(Z_SRED, _kruzhka(1300, sy - 6, 1.0, 0, "#efe3d4", 1))
    # бабушка наклонилась к дочери: ладонь ширмой у рта
    bx, by_, bh = 660, pol + 10, 540
    s += SL(Z_SRED, _tabyret(bx - 30, pol + 6, t, 180, 180))
    _figury_kadra((660, pol + 10 - 180, 540), (1180, pol + 16 - 190, 620))
    bab = figura(bx, by_ - 180, bh, t, col="#54505e", kant="#ffd98a",
                 platok=True, ph=.4, naklon=10.0, profil=True)
    b1, (h1x, h1y), _ = _ruka_sgib_mimo(bx, by_ - 180, bh, 1, bh * .20, 30,
                                        bh * .22, -34, t, "#54505e",
                                        "#ffd98a", .4, 4.0)
    b2, (h2x, h2y), _ = _ruka_mimo(bx, by_ - 180, bh, -1, bh * .44, 62, t,
                              "#54505e", "#ffd98a", .8, 3.0)
    bab += b1 + b2
    s += SL(Z_SRED, bab)
    # ладонь-ширма у рта и шёпот волной
    s += SL(Z_SRED, f'<ellipse cx="{h1x:.0f}" cy="{h1y:.0f}" rx="40" ry="52"'
                    f' fill="#e8d8c0" {o(6)}/>')
    for i in range(3):
        k = ((t * .7 + i * .33) % 1.0)
        s += SL(Z_SRED, f'<path d="M{h1x+30:.0f},{h1y-10:.0f}'
                        f' q{30+40*k:.0f},{-18:.0f} {60+80*k:.0f},{4:.0f}"'
                        f' fill="none" stroke="#eaf4ff" stroke-width="6"'
                        f' opacity="{.6*(1-k):.2f}"/>')
    # дочь слушает: обе руки на чашке, глаза округляются
    dx, dy_, dh = 1180, pol + 16, 620
    s += SL(Z_SRED, _venskiy_stul(1232, pol + 8, 600, t, 2.0, True))
    doch = figura(dx, dy_ - 190, dh, t, col="#6a4a52", kant="#ffd98a",
                  ph=.9, naklon=-6.0)
    d1, (g1x, g1y), _ = _ruka_mimo(dx, dy_ - 190, dh, -1, dh * .40, 36, t,
                              "#6a4a52", "#ffd98a", .9, 3.0)
    d2, (g2x, g2y), _ = _ruka_mimo(dx, dy_ - 190, dh, -1, dh * .32, 56, t,
                              "#6a4a52", "#ffd98a", .5, 3.0)
    doch += d1 + d2
    s += SL(Z_SRED, doch)
    s += SL(Z_SRED, _kruzhka((g1x + g2x) / 2 - 10, (g1y + g2y) / 2 + 20, 1.0,
                             4 * A.w(t, 1.9, .3), "#f0eade", 1))
    s += SL(Z_SRED, _varezhka(g1x, g1y, dh, t, .9) + _varezhka(g2x, g2y, dh, t, .5))
    # округлившиеся глаза дочери
    for sgn in (-1, 1):
        s += SL(Z_SRED, f'<circle cx="{dx+sgn*dh*.044:.0f}"'
                        f' cy="{dy_-190-dh*.86:.0f}" r="{dh*.026:.0f}"'
                        f' fill="#f2f6fa" opacity=".8"/>')
    s += SL(Z_SRED, par(dx, dy_ - 190 - dh * .70, t, 3, .3, 110, .3, .8))
    # низ кадра
    s += SL(Z_SRED, _polovik(640, pol + 30, 620, 104)
            + _dvorovaya_utvar(96, pol + 92, 320, t, 211, ["kadka", "korzina"])
            + _yaschiki(1600, pol + 86, t, 223, 2, .86)
            + _kot_zhivoy(1420, pol + 70, t, 1.1, "#3b342f", .7, True, True)
            + kartoshka(430, pol + 96, t, 6, 6, .95))
    s += SL(Z_SRED, teplo(500, sy - 240, 520, 420, .40))
    s += SL(Z_PERED, _stolb_pered(-8, 96, "#181209", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 500, sy - 320, 6, 29, 190, .3))
    s += vinetka(.40)
    return s


def tri_stuka_po_stolu(t):
    """Край деревянного кухонного стола на пол-кадра: хлебница, солонка,
    чашка. Мужчина трижды стучит костяшками по столешнице, от каждого стука
    расходится круг, и Сглаз над его левым плечом лопается."""
    rnd = random.Random(311)
    pol = 1000
    s = f'<rect width="{W}" height="{H}" fill="#2c2620"/>'
    s += SL(Z_DAL, doski(0, 0, 1140, 760, 98, True, "dosk"))
    s += SL(Z_DAL, doski(1140, 0, 780, 760, 98, True, "dosk"))
    s += SL(Z_DAL, _polka_s_utvaryu(1180, 250, 640, t, 127, 5))
    s += SL(Z_DAL, _knizhnaya_polka(120, 300, 600, t, 131, 2, 196))
    s += SL(Z_DAL, f'<rect x="0" y="744" width="{W}" height="40" rx="8"'
                   f' fill="#4a3522" {o(5)}/>')
    s += SL(Z_DAL, tusklaya_lampochka(960, 130, t, 1.3, True))
    s += SL(Z_DAL, _konus_sveta(960, 180, 760, 560, 0, .38))
    s += SL(Z_DAL, _polka_s_utvaryu(760, 300, 420, t, 383, 3))
    s += SL(Z_DAL, _polki_otkrytye(760, 480, 420, t, 389, 1, True, .0))
    # вязанки лука и сушёных травок на гвоздях, рушник и сито на стене
    for i in range(4):
        s += SL(Z_DAL, f'<path d="M{1620+i*76:.0f},200 q{-26:.0f},{80:.0f}'
                       f' {4:.0f},{148:.0f} q{30:.0f},{20:.0f} {44:.0f},{-14:.0f}'
                       f' q{14:.0f},{-74:.0f} {-18:.0f},{-134:.0f} Z"'
                       f' fill="#c9a05a" {o(5)}/>'
                f'<line x1="{1628+i*76:.0f}" y1="200" x2="{1644+i*76:.0f}"'
                f' y2="162" stroke="#8a7a46" stroke-width="7"/>')
    s += SL(Z_DAL, f'<circle cx="300" cy="620" r="86" fill="none" stroke="#6a5030"'
                   f' stroke-width="22"/>'
            + f'<circle cx="300" cy="620" r="70" fill="#cdbf9c" opacity=".7"/>')
    for i in range(7):
        s += SL(Z_DAL, f'<line x1="{238+i*18:.0f}" y1="556" x2="{238+i*18:.0f}"'
                       f' y2="684" stroke="#9a8a68" stroke-width="4"'
                       f' opacity=".8"/>')
    s += SL(Z_DAL, f'<rect x="520" y="560" width="110" height="280" rx="9"'
                   f' fill="url(#rush)" {o(5)}/>'
            + f'<rect x="520" y="660" width="110" height="18" fill="{TKAN}"'
              f' opacity=".8"/>'
            + f'<rect x="520" y="760" width="110" height="18" fill="{TKAN2}"'
              f' opacity=".7"/>')
    # СТОЛ КРУПНО: край столешницы во всю ширину кадра
    sy = 700
    s += SL(Z_SRED, f'{ten(960, pol + 40, 640, 30, .5)}'
                    f'<path d="M-20,{sy:.0f} L1940,{sy:.0f} L1940,{sy+86:.0f}'
                    f' L-20,{sy+86:.0f} Z" fill="url(#derev)" {o(8)}/>'
            + f'<rect x="60" y="{sy+86:.0f}" width="1400" height="28" rx="8"'
              f' fill="#5b4428" {o(5)}/>')
    for i in range(9):
        s += SL(Z_SRED, f'<path d="M{-20+i*230:.0f},{sy+10:.0f}'
                        f' q{60:.0f},{24:.0f} {120:.0f},{6:.0f}" fill="none"'
                        f' stroke="#8a6a44" stroke-width="6" opacity=".6"/>')
    for i in (0, 1):
        s += SL(Z_SRED, f'<rect x="{200+i*1300:.0f}" y="{sy+114:.0f}" width="80"'
                        f' height="{pol+70-sy-114:.0f}" rx="12"'
                        f' fill="#5b4428" {o(6)}/>')
    # КРУГИ от стуков по столешнице
    # (круги и кулак ставятся НИЖЕ, по фактической точке кисти: жёсткие
    # 870 расходились в 153 px от руки — осмотр порции 2)
    # хлебница, солонка, чашка — вздрагивает от стука
    drog = 6 * math.sin(t * 22) * max(.0, 1 - abs(((t - .5) % .7) * 6))
    s += SL(Z_SRED, f'<rect x="1180" y="{sy-96:.0f}" width="260" height="96"'
                    f' rx="20" fill="url(#solom)" {o(6)}/>'
            + f'<path d="M1192,{sy-96:.0f} q128,-54 236,0" fill="none"'
              f' stroke="#8a6a3c" stroke-width="10"/>'
            + karavay(1310, sy - 92, .58, False))
    s += SL(Z_SRED, f'<path d="M1520,{sy-6:.0f} L1596,{sy-6:.0f}'
                    f' L1584,{sy-78:.0f} L1532,{sy-78:.0f} Z" fill="#f0ece0" {o(5)}/>'
            + f'<ellipse cx="1558" cy="{sy-78:.0f}" rx="26" ry="9"'
              f' fill="#dcd4c4" {o(3)}/>')
    s += SL(Z_SRED, f'<g transform="translate({drog:.1f},0)">'
                    f'{_kruzhka(1700, sy - 6, 1.15, 0, "#e8eef0", -1)}</g>')
    s += SL(Z_SRED, par(1700, sy - 110, t, 3, .36, 130, .34, .9))
    # мужчина за столом: левая держит чашку, правая стучит костяшками
    fx, fy, fh = 700, pol + 150, 700
    pov = A.ease(A.seg(t, 2.6, .9))
    muz = figura(fx, fy - 230, fh, t, col="#4a5a52", kant="#ffd98a", ph=.3,
                 naklon=-4 + 6 * pov, profil=(pov > .5))
    m1, (r1x, r1y), _ = _ruka(fx, fy - 230, fh, 1, fh * .44,
                              44 + 10 * math.sin(t * 9), t,
                              "#4a5a52", "#ffd98a", .3, 4.0)
    m2, (r2x, r2y), _ = _ruka(fx, fy - 230, fh, -1, fh * .40, 50, t,
                              "#4a5a52", "#ffd98a", .7, 3.0)
    muz += m1 + m2
    s += SL(Z_SRED, muz)
    s += SL(Z_SRED, _kruzhka(r2x - 10, r2y + 20, 1.0, 0, "#f0eade", -1))
    s += SL(Z_SRED, _varezhka(r2x, r2y, fh, t, .7))
    # КУЛАК РОВНО НА КОНЦЕ РУКАВА, круги расходятся от него
    kulx, kuly = r1x, r1y + 10
    udar = 14 * max(.0, math.sin(t * 9))
    s += SL(Z_SRED, _krugi_po_stolu(kulx, kuly + 18, t, 3, .0, 300))
    s += SL(Z_SRED, _kulak(kulx, kuly - udar, 1.3, t, .2))
    # СГЛАЗ над левым плечом лопается, как мыльный шарик
    lop = A.ease(A.seg(t, 2.1, .5))
    if lop < 1.0:
        s += SL(Z_SRED, _sglaz(fx - 230, fy - 230 - fh * .92, t, .92 + .3 * lop,
                               .3, .92 * (1 - lop)))
    for i in range(7):
        if lop > 0:
            a = math.radians(i * 51)
            rr = 120 * lop
            s += SL(Z_SRED, f'<circle cx="{fx-230+rr*math.cos(a):.0f}"'
                            f' cy="{fy-230-fh*.92+rr*math.sin(a):.0f}"'
                            f' r="{14*(1-lop):.0f}" fill="#8a919a"'
                            f' opacity="{.8*(1-lop):.2f}"/>')
    # низ кадра: табурет, половик, валенки, кот, ящик
    s += SL(Z_PERED, _polovik(560, pol + 40, 760, 110)
            + _valenki_u_dveri(300, pol + 70, 1.0, t)
            + _kot_zhivoy(1480, pol + 60, t, 1.2, "#3b342f", .4)
            + _yaschiki(96, pol + 60, t, 137, 2, .9))
    # НИЗ КАДРА: кадка, вёдра, корзина и кошачья плошка под столом
    s += SL(Z_SRED, _dvorovaya_utvar(620, pol + 30, 520, t, 167,
                                     ["kadka", "vedro", "korzina", "korob"])
            + f'<ellipse cx="1360" cy="{pol+36:.0f}" rx="58" ry="21"'
              f' fill="url(#glina)" {o(5)}/>'
            + f'<ellipse cx="1360" cy="{pol+30:.0f}" rx="44" ry="14"'
              f' fill="#8a5a30" opacity=".9"/>')
    s += SL(Z_PERED, _stolb_pered(1860, 88, "#171209", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 960, 180, 6, 31, 170, .24))
    s += vinetka(.40)
    return s


def dvor_s_tremya_zabotami(t):
    """Яркий морозный день: деревенский двор одним кадром. У калитки девушка
    бросает монету, на крыльце мать держит чёрную редьку, справа отец несёт
    дрова к баньке. В окне избы — настоящая редька в корзине."""
    rnd = random.Random(313)
    gor = 640
    s = f'<rect width="{W}" height="{H}" fill="url(#nden)"/>'
    s += nebo("den", t, False, 71)
    s += oblaka(t, 140, 5, 73, .5, "#eef4fa", 16.0)
    s += SL(Z_DAL, _derevnya_ryad(gor - 90, t, 31, ((120, 300), (430, 250))))
    s += SL(Z_DAL, goloe_derevo(760, gor - 30, 480, t, 79, 8, "#4a4b53", True))
    s += SL(Z_DAL, _zabor_dosok(-30, gor - 170, 820, 180, 41, 56))
    s += SL(Z_SRED, f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor:.0f}"'
                    f' fill="#c8cfd8"/>'
            + f'<path d="M-20,{gor+70:.0f} Q480,{gor+20:.0f} 980,{gor+86:.0f}'
              f' Q1480,{gor+150:.0f} 1940,{gor+96:.0f} L1940,1080 L-20,1080 Z"'
              f' fill="url(#sneg)" {o(0)}/>'
            + _inej(139, 60, gor + 60, 1060)
            + _pol_shvy(gor + 60, 1070, 149, 5, "#9fb0c0"))
    # ИЗБА С КРЫЛЬЦОМ — крупный предмет; в окне настоящий кадр
    s += SL(Z_SRED, f'{ten(1020, gor + 120, 400, 30, .4)}'
                    f'<rect x="620" y="{gor-420:.0f}" width="1020" height="500"'
                    f' rx="10" fill="url(#brev)" {o(8)}/>')
    s += SL(Z_SRED, brevna(620, gor - 420, 1020, 500, 92))
    s += SL(Z_SRED, f'<path d="M580,{gor-420:.0f} L1130,{gor-610:.0f}'
                    f' L1680,{gor-420:.0f} Z" fill="#5a4636" {o(7)}/>'
            + f'<path d="M580,{gor-420:.0f} L1130,{gor-610:.0f} L1680,{gor-420:.0f}'
              f' l-40,0 L1130,{gor-566:.0f} L620,{gor-420:.0f} Z"'
              f' fill="url(#sneg)" opacity=".92"/>')
    # НАСТОЯЩИЙ КАДР в окне над крыльцом: вид, метка, наличник поверх
    px, py, pw, ph_ = 760, gor - 390, 800, 330
    put = kontur_proema(px, py, pw, ph_, "pryam")
    vid = (f'<clipPath id="okn3"><path d="{put}"/></clipPath>'
           f'<g clip-path="url(#okn3)">'
           f'<rect x="{px:.0f}" y="{py:.0f}" width="{pw:.0f}" height="{ph_:.0f}"'
           f' fill="#4a4034"/>'
           f'<path d="M{px:.0f},{py+ph_*.58:.0f} L{px+pw:.0f},{py+ph_*.58:.0f}'
           f' L{px+pw:.0f},{py+ph_:.0f} L{px:.0f},{py+ph_:.0f} Z"'
           f' fill="url(#solom)"/>')
    for i in range(5):
        vid += (f'<ellipse cx="{px+150+i*130:.0f}" cy="{py+ph_*.62:.0f}" rx="58"'
                f' ry="36" fill="#2e2b2a" opacity=".9"/>'
                f'<path d="M{px+150+i*130:.0f},{py+ph_*.52:.0f}'
                f' q{20:.0f},{-54:.0f} {48:.0f},{-70:.0f}" fill="none"'
                f' stroke="#5c7a40" stroke-width="10"/>')
    vid += "</g>"
    s += SL(Z_SRED, vid + mesto_stoka(px, py, pw, ph_, "pryam"))
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#6a5030"'
                    f' stroke-width="30"/>'
            + f'<rect x="{px-40:.0f}" y="{py-48:.0f}" width="{pw+80:.0f}"'
              f' height="40" rx="10" fill="#7d5a3c" {o(5)}/>'
            + f'<rect x="{px-54:.0f}" y="{py+ph_-10:.0f}" width="{pw+108:.0f}"'
              f' height="42" rx="10" fill="url(#dosk)" {o(6)}/>'
            + f'<line x1="{px+pw*.5:.0f}" y1="{py:.0f}" x2="{px+pw*.5:.0f}"'
              f' y2="{py+ph_:.0f}" stroke="#6a5030" stroke-width="22"/>')
    s += SL(Z_SRED, _kryl_co(430, gor + 60, 420, 130, t, 3, True, True))
    # БАНЬКА справа с дымом из трубы
    s += SL(Z_SRED, izba_snaruzhi(1640, gor - 40, 330, t, True, True, 43))
    s += SL(Z_SRED, dym(1690, gor - 240, t, 6, .3, 340, .42, "#e2e8ee", 1.4))
    # КАЛИТКА слева, девушка бросает монету за неё
    s += SL(Z_SRED, _vorota_dvora(120, gor + 180, 300, 330, t, .25))
    dvx, dvy, dvh = 340, gor + 300, 560
    bros = A.ease(A.seg(t, .4, .8))
    _figury_kadra((340, gor + 300, 560), (590, gor - 50, 470),
                  (1810, gor + 330, 660))
    dev = figura(dvx, dvy, dvh, t, col="#6a4a62", kant="#ffd98a", platok=True,
                 ph=.2, naklon=5.0)
    d1, (a1x, a1y), _ = _ruka_mimo(dvx, dvy, dvh, 1, dvh * .44, 20 - 62 * bros, t,
                              "#6a4a62", "#ffd98a", .2, 5.0)
    d2, (a2x, a2y), _ = _ruka_mimo(dvx, dvy, dvh, -1, dvh * .36, 44, t,
                              "#6a4a62", "#ffd98a", .6, 4.0)
    dev += d1 + d2
    s += SL(Z_SRED, dev)
    s += SL(Z_SRED, _ploshka_s_meloch(a2x - 30, a2y + 30, t, .78, 6, 151))
    s += SL(Z_SRED, _varezhka(a1x, a1y, dvh, t, .2) + _varezhka(a2x, a2y, dvh, t, .6))
    # монета летит за калитку
    mk = A.seg(t, 1.0, 1.6)
    s += SL(Z_SRED, _moneta_krupno(a1x - 220 * mk, a1y - 120 * math.sin(math.pi * mk) + 200 * mk,
                                   46, t, .2, True, True, .3))
    # МАТЬ на крыльце с чёрной редькой в обеих руках
    mx, my, mh = 590, gor + 70, 470
    s += SL(Z_SRED, _lavka_krupno(430, gor + 76, 420, t, 120, False))
    mat = figura(mx, my - 120, mh, t, col="#4a5a6a", kant="#ffd98a",
                 platok=True, ph=.5, naklon=-3.0)
    m1, (b1x, b1y), _ = _ruka_mimo(mx, my - 120, mh, 1, mh * .40, 28, t,
                              "#4a5a6a", "#ffd98a", .5, 3.0)
    m2, (b2x, b2y), _ = _ruka_mimo(mx, my - 120, mh, -1, mh * .40, 30, t,
                              "#4a5a6a", "#ffd98a", .9, 3.0)
    mat += m1 + m2
    s += SL(Z_SRED, mat)
    # РЕДЬКА НА КОЛЕНЯХ, А НЕ НА ЛИЦЕ: при s_=1,35 её ботва вставала ровно
    # в лицо матери и читалась кадкой с растением (осмотр порции 2)
    s += SL(Z_SRED, _redka((b1x + b2x) / 2, (b1y + b2y) / 2 + 142, .78, t, -14, .3))
    s += SL(Z_SRED, "")
    # ОТЕЦ несёт дрова в обеих руках — крупнее матери, в профиль
    ox2, oy2, oh2 = 1810, gor + 330, 660
    shag = A.seg(t, .2, 5.0)
    otec = figura(ox2 - 120 + 120 * shag, oy2, oh2, t, col="#46506a",
                  kant="#cfe4f5", shapka=True, boroda=True, ph=.8,
                  profil=True, naklon=6.0)
    o1, (c1x, c1y), _ = _ruka_mimo(ox2 - 120 + 120 * shag, oy2, oh2, -1, oh2 * .34,
                              28, t, "#46506a", "#cfe4f5", .8, 4.0)
    o2, (c2x, c2y), _ = _ruka_mimo(ox2 - 120 + 120 * shag, oy2, oh2, -1, oh2 * .28,
                              52, t, "#46506a", "#cfe4f5", .4, 4.0)
    otec += o1 + o2
    s += SL(Z_SRED, otec)
    # охапка поленьев в руках
    for i in range(6):
        s += SL(Z_SRED, f'<rect x="{c1x-120+ (i % 3) * 56:.0f}"'
                        f' y="{c1y-30+(i//3)*40:.0f}" width="130" height="36"'
                        f' rx="16" fill="url(#derev)" {o(5)}/>'
                f'<ellipse cx="{c1x-120+(i % 3) * 56:.0f}"'
                f' cy="{c1y-12+(i//3)*40:.0f}" rx="12" ry="17"'
                f' fill="#8a6a44" {o(3)}/>')
    s += SL(Z_SRED, _varezhka(c1x, c1y, oh2, t, .8, "#dcd0bc")
           )
    s += SL(Z_SRED, para_izo_rta(ox2 - 80 + 120 * shag, oy2 - oh2 * .80, t,
                                 .2, 1.3, .5))
    # низ кадра
    s += SL(Z_SRED, _polenica(1700, gor + 330, 300, 190, 47, 58)
            + _dvorovaya_utvar(540, gor + 400, 420, t, 229,
                               ["korzina", "vedro", "korob"])
            + _kot_zhivoy(820, gor + 420, t, 1.05, "#3b342f", .5)
            + _sledy(300, 1066, 900, 860, 7, 233, "#8fa3b4", 1.3)
            + _kucha_listev(1360, 1058, 300, 239, 84))
    # ветка поднята: её контур резал лицо матери слева (осмотр)
    s += SL(Z_PERED, _vetka_pered(-70, 40, 560, 16, t, 29, "#241c16", 5))
    s += SL(Z_LETIT, mokryy_sneg(t, 20, 5, .4, .8))
    s += vinetka(.34)
    return s


def devushka_kradetsya_iz_spyaschey_iz(t):
    """Сени спящей избы в синих сумерках перед зарёй: на лавке храпит дед,
    на печи детские пятки, на гвозде тулупы. Девушка в сорочке крадётся на
    цыпочках к двери, прижимая к груди плошку с безделушками."""
    rnd = random.Random(317)
    pol = 980
    s = f'<rect width="{W}" height="{H}" fill="#1a2238"/>'
    s += SL(Z_DAL, brevna(0, 30, 1080, pol - 30, 96)
            + brevna(1080, 30, 840, pol - 30, 96))
    s += SL(Z_DAL, _polka_s_utvaryu(96, 240, 540, t, 241, 4))
    s += SL(Z_DAL, _polka_s_utvaryu(100, 540, 500, t, 397, 4))
    s += SL(Z_DAL, _polati(640, 180, 620, t, 3))
    # кадки, вёдра и короба вдоль стены сеней
    s += SL(Z_SRED, _dvorovaya_utvar(500, pol - 6, 520, t, 401,
                                     ["kadka", "vedro", "korob", "korzina"]))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-16:.0f}" width="{W}"'
                   f' height="{H-pol+16:.0f}" fill="#4a3c2c"/>'
            + polovicy(pol + 16) + _pol_shvy(pol + 20, 1070, 251, 6, "#3a2c1e"))
    # ПЕЧЬ с детскими пятками на лежанке — крупный предмет
    s += SL(Z_SRED, pech(1300, 300, 600, 600, t, True, True, True))
    s += SL(Z_SRED, ugli(1430, 790, 300, t, 7, 3))
    s += SL(Z_SRED, teplo(1560, 800, 480, 380, .40))
    for i in (0, 1):
        s += SL(Z_SRED, f'<ellipse cx="{1420+i*86:.0f}" cy="330" rx="40" ry="30"'
                        f' fill="#f0cfae" {o(5)}/>'
                f'<path d="M{1392+i*86:.0f},316 q28,-14 56,0" fill="none"'
                f' stroke="#e0bb98" stroke-width="7"/>')
    s += SL(Z_SRED, f'<path d="M1360,352 q140,-40 280,0 l0,40 q-140,34 -280,0 Z"'
                    f' fill="#8a4a52" {o(5)}/>')
    # ЛАВКА с храпящим дедом
    s += SL(Z_SRED, _lavka_krupno(120, pol - 6, 620, t, 150, False))
    ded = figura(300, pol - 150, 330, t, col="#5a5248", kant="#ffd98a",
                 boroda=True, ph=.6, naklon=-4.0, lico=True)
    s += SL(Z_SRED, f'<g transform="rotate(78 300 {pol-150:.0f})">{ded}</g>')
    for i in range(3):
        k = ((t * .45 + i * .33) % 1.0)
        s += SL(Z_SRED, f'<path d="M{600+60*k:.0f},{pol-250-30*k:.0f}'
                        f' q{20:.0f},{-20:.0f} {44:.0f},{-6:.0f}" fill="none"'
                        f' stroke="#cfe4f5" stroke-width="7"'
                        f' opacity="{.6*(1-k):.2f}"/>')
    # ТУЛУПЫ на гвозде
    for i in range(3):
        tx = 760 + i * 150
        kach = 1.4 * A.w(t, 4.2, i * .3)
        s += SL(Z_SRED, f'<g transform="rotate({kach:.1f} {tx:.0f} 250)">'
                        f'<circle cx="{tx:.0f}" cy="244" r="11" fill="{ZHELEZ}"/>'
                f'<path d="M{tx-80:.0f},300 q{80:.0f},{-56:.0f} {160:.0f},0'
                f' l{16:.0f},{330:.0f} q{-96:.0f},{34:.0f} {-192:.0f},0 Z"'
                f' fill="{["#5a4636", "#4a4e46", "#6a5a46"][i]}" {o(6)}/>'
                f'<ellipse cx="{tx:.0f}" cy="306" rx="60" ry="22"'
                f' fill="#cdbf9c" opacity=".8"/></g>')
    # ДВЕРЬ приоткрывается от локтя
    otkr = A.ease(A.seg(t, 2.6, 2.0))
    s += SL(Z_SRED, dver(60, pol - 820, 330, 820, .2 + .5 * otkr,
                         "url(#derev)", True, False))
    s += SL(Z_SRED, f'<rect x="30" y="{pol-852:.0f}" width="390" height="40"'
                    f' rx="10" fill="#5b4428" {o(6)}/>')
    # ДЕВУШКА крадётся на цыпочках: обе руки прижимают плошку
    shag = A.ease(A.seg(t, .2, 4.0))
    fx = 1020 - 480 * shag
    fy, fh = pol + 10, 740
    zam = max(.0, A.w(t, 3.2, .2))
    # дед лежит на лавке головой вправо: в реестр идёт точка его разворота
    _figury_kadra((300, pol - 150, 330), (fx, fy - 26 * zam, fh))
    dev = figura(fx, fy - 26 * zam, fh, t, col="#e8dcc8", kant="#ffd98a",
                 platok=True, ph=.3, naklon=7.0, profil=True)
    d1, (p1x, p1y), _ = _ruka_sgib_mimo(fx, fy - 26 * zam, fh, -1, fh * .20, 34,
                                        fh * .22, -10, t, "#e8dcc8",
                                        "#ffd98a", .3, 3.0)
    d2, (p2x, p2y), _ = _ruka_sgib_mimo(fx, fy - 26 * zam, fh, 1, fh * .20, 38,
                                        fh * .22, -6, t, "#e8dcc8",
                                        "#ffd98a", .7, 3.0)
    dev += d1 + d2
    s += SL(Z_SRED, dev)
    s += SL(Z_SRED, _ploshka_s_meloch((p1x + p2x) / 2, (p1y + p2y) / 2 + 24, t,
                                      1.05, 7, 257))
    s += SL(Z_SRED, "")
    # скрипнувшая половица под её ногой
    s += SL(Z_SRED, f'<path d="M{fx-120:.0f},{pol+30:.0f} L{fx+140:.0f},{pol+30:.0f}'
                    f' L{fx+170:.0f},{pol+80:.0f} L{fx-150:.0f},{pol+80:.0f} Z"'
                    f' fill="#5e4a34" {o(5)}/>')
    s += SL(Z_SRED, luchina(760, pol - 6, t, 1.2, .2))
    # сени холодные: кадушка с водой, вёдра, лопата и корзины у стены
    s += SL(Z_SRED, _kadushki_i_grabli(1060, pol - 4, t, 419))
    for i in range(3):
        s += SL(Z_SRED, krynka(150 + i * 120, 232, 1.35 + (i % 2) * .2))
    # низ кадра
    s += SL(Z_SRED, _valenki_u_dveri(300, pol + 76, 1.05, t)
            + _dvorovaya_utvar(1180, pol + 90, 380, t, 263, ["kadka", "vedro"])
            + _kot_zhivoy(640, pol + 70, t, 1.1, "#2f2a26", .6, True, True)
            + _yaschiki(1620, pol + 84, t, 269, 2, .84)
            + kartoshka(900, pol + 96, t, 6, 6, .9))
    s += SL(Z_PERED, _stolb_pered(1870, 76, "#140f0c", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 1560, 790, 7, 37, 240, .34))
    s += vinetka(.44)
    return s


def zhenihi_idut_na_blesk(t):
    """Дорога перед калиткой сплошь усыпана блестящей мелочью. По ней один за
    другим шагают три жениха — с гармонью, с пряником в платке и долговязый
    с букетом рябины. Девушка выглядывает из-за калитки и считает."""
    rnd = random.Random(331)
    gor = 620
    s = f'<rect width="{W}" height="{H}" fill="url(#nrassv)"/>'
    s += nebo("rassv", t, False, 83)
    s += oblaka(t, 150, 5, 89, .44, "#e4e8f0", 15.0)
    s += SL(Z_DAL, _derevnya_ryad(gor - 60, t, 37, ((230, 320), (640, 260),
                                                    (1560, 300))))
    s += SL(Z_DAL, goloe_derevo(1080, gor - 10, 520, t, 97, 9, "#3a3b43", True))
    s += SL(Z_DAL, _zabor_dosok(620, gor - 190, 1300, 200, 53, 58))
    s += SL(Z_SRED, f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor:.0f}"'
                    f' fill="#5a4a36"/>'
            + _zemlya_faktura(gor + 40, 1050, 29, 16, "#473a2c")
            + _koleya(gor + 250, 337, 2)
            + _pol_shvy(gor + 40, 1070, 347, 6, "#3e3226")
            + _listya(349, 40, gor + 50, 1060))
    # ДОРОГА, УСЫПАННАЯ МЕЛОЧЬЮ: монетки блестят по всей полосе
    for i in range(54):
        mx = rnd.uniform(60, W - 60)
        my = rnd.uniform(gor + 120, 1060)
        rr = 13 + (my - gor - 120) * .022
        bl = .4 + .6 * abs(A.w(t, 1.6 + (i % 5) * .3, i * .11))
        s += SL(Z_SRED, f'<ellipse cx="{mx:.0f}" cy="{my:.0f}" rx="{rr:.0f}"'
                        f' ry="{rr*.48:.0f}" fill="url(#med)" {o(3)}/>'
                f'<ellipse cx="{mx-rr*.26:.0f}" cy="{my-rr*.12:.0f}"'
                f' rx="{rr*.38:.0f}" ry="{rr*.17:.0f}" fill="#fff0c4"'
                f' opacity="{bl:.2f}"/>')
    # КАЛИТКА — крупный предмет; за ней девушка
    s += SL(Z_SRED, _vorota_dvora(90, gor + 250, 420, 420, t, .12))
    s += SL(Z_SRED, _zabor_dosok(-30, gor + 60, 560, 210, 59, 56))
    dvh = 560
    dev = figura(230, gor + 300, dvh, t, col="#6a4a62", kant="#ffd98a",
                 platok=True, ph=.3, naklon=-5.0)
    d1, (v1x, v1y), _ = _ruka_mimo(230, gor + 300, dvh, 1, dvh * .24, -8, t,
                              "#6a4a62", "#ffd98a", .3, 4.0)
    d2, (v2x, v2y), _ = _ruka_mimo(230, gor + 300, dvh, -1, dvh * .24, -6, t,
                              "#6a4a62", "#ffd98a", .7, 4.0)
    dev += d1 + d2
    s += SL(Z_SRED, dev)
    s += SL(Z_SRED, _varezhka(v1x, v1y, dvh, t, .3))
    # ТРИ ЖЕНИХА вереницей: рост через одного, шаг рваный, заходят друг за друга
    shag = A.seg(t, .2, 3.6)
    # рост СТРОГО через одного: 760 / 440 / 700 — разница 1,7× и 1,6×;
    # шаг рваный (0.0 / 0.52 / 0.16), средний со спины, третий в профиль
    zhen = ((0, 760, "#4a5a72", 0.0, "garmon", 4.0, False),
            (1, 440, "#5a4636", 0.52, "pryanik", -9.0, False),
            (2, 700, "#46506a", 0.16, "ryabina", 12.0, True))
    _figury_kadra((230, gor + 300, 560),
                  *[(760 + j * 430 - 120 * shag * (1 - o_ * .55),
                     gor + 330 + j * 46, h_) for j, h_, _c, o_, _p, _n, _pr in zhen])
    for i, fh, col, ot, pred, nak, prof in zhen:
        fx = 760 + i * 430 - 120 * shag * (1 - ot * .55)
        fy = gor + 330 + i * 46
        fig = figura(fx, fy, fh, t, col=col, kant="#cfe4f5", shapka=(i != 2),
                     ph=.2 + i * .33, profil=prof, naklon=nak,
                     lico=(i != 1))        # средний — СО СПИНЫ
        r1, (w1x, w1y), _ = _ruka_mimo(fx, fy, fh, 1, fh * .40,
                                  (24, 30, -46)[i], t, col, "#cfe4f5",
                                  .2 + i * .2, 6.0)
        r2, (w2x, w2y), _ = _ruka_mimo(fx, fy, fh, -1, fh * .36,
                                  (46, 34, 30)[i], t, col, "#cfe4f5",
                                  .6 + i * .2, 5.0)
        fig += r1 + r2
        s += SL(Z_SRED, fig)
        if pred == "garmon":
            rast = 30 * abs(A.w(t, 1.3, .2))
            s += SL(Z_SRED, f'<rect x="{w1x-10:.0f}" y="{w1y-20:.0f}" width="54"'
                            f' height="110" rx="10" fill="#8a3a32" {o(5)}/>'
                    f'<rect x="{w1x+44+rast:.0f}" y="{w1y-20:.0f}" width="54"'
                    f' height="110" rx="10" fill="#8a3a32" {o(5)}/>')
            for k in range(6):
                s += SL(Z_SRED, f'<path d="M{w1x+44:.0f},{w1y-14+k*18:.0f}'
                                f' l{14+rast*.5:.0f},{-6:.0f} l{14+rast*.5:.0f},{6:.0f}"'
                                f' fill="none" stroke="#efe2c2" stroke-width="5"/>')
            for k in range(4):
                s += SL(Z_SRED, f'<circle cx="{w1x+16:.0f}"'
                                f' cy="{w1y+4+k*24:.0f}" r="7"'
                                f' fill="#efe2c2" {o(2)}/>')
        elif pred == "pryanik":
            s += SL(Z_SRED, f'<path d="M{w1x-80:.0f},{w1y+10:.0f}'
                            f' q{80:.0f},{-54:.0f} {160:.0f},0'
                            f' q{-80:.0f},{40:.0f} {-160:.0f},0 Z" fill="{RUSH}"'
                            f' {o(5)}/>'
                    f'<ellipse cx="{w1x:.0f}" cy="{w1y-6:.0f}" rx="56" ry="34"'
                    f' fill="url(#med)" {o(5)}/>'
                    f'<path d="M{w1x-30:.0f},{w1y-14:.0f} q30,-16 60,2"'
                    f' fill="none" stroke="#efe2c2" stroke-width="6"/>'
                    f'<path d="M{w1x-70:.0f},{w1y+16:.0f} l-26,40 M{w1x+70:.0f},'
                    f'{w1y+16:.0f} l26,40" stroke="{TKAN}" stroke-width="9"'
                    f' fill="none"/>')
        else:
            s += SL(Z_SRED, grozd_ryabiny(w2x + 20, w2y + 40, t, 1.2, 15, 101, .3)
                    + f'<line x1="{w2x+16:.0f}" y1="{w2y+10:.0f}"'
                      f' x2="{w2x+24:.0f}" y2="{w2y+80:.0f}" stroke="{ZEL}"'
                      f' stroke-width="9"/>')
            # приглаживает чуб правой рукой
            s += SL(Z_SRED, f'<path d="M{w1x-10:.0f},{w1y-16:.0f}'
                            f' q{26:.0f},{-26:.0f} {58:.0f},{-10:.0f}" fill="none"'
                            f' stroke="#4a3526" stroke-width="14"/>')
        # варежка — только на той руке, где предмет: у первых двух это
        # правая (гармонь, пряник), у долговязого левая (букет рябины),
        # а чуб он приглаживает рукавом без кисти
        if i != 2:
            s += SL(Z_SRED, _varezhka(w1x, w1y, fh, t, .2 + i * .2, "#dcd0bc"))
        else:
            s += SL(Z_SRED, _varezhka(w2x, w2y, fh, t, .6 + i * .2, "#dcd0bc"))
        s += SL(Z_SRED, para_izo_rta(fx + fh * .10, fy - fh * .80, t,
                                     i * .3, 1.0, .42))
    # низ кадра
    s += SL(Z_SRED, _kucha_listev(620, 1060, 320, 353, 88)
            + _luzha(1500, 1020, 180, t, .4)
            + _kot_zhivoy(140, 1050, t, 1.0, "#3b342f", .2)
            + _sledy(1880, 1066, 1240, 880, 6, 359, "#33281d", 1.2)
            + _dvorovaya_utvar(1680, gor + 280, 240, t, 367, ["korzina"]))
    s += SL(Z_PERED, _stolb_pered(-10, 100, "#1a120c", 0, H))
    s += SL(Z_LETIT, mokryy_sneg(t, 18, 5, .4, .75))
    s += vinetka(.38)
    return s


def blyudce_s_melochyu_u_zerkala(t):
    """Прихожая шестидесятых: подзеркальник у круглого зеркала, фарфоровое
    блюдце с мелочью на пол-кадра, расчёска, ключи, коробок спичек. Рука до
    локтя раскладывает монеты в три кучки, над ними встают значки."""
    rnd = random.Random(337)
    s = f'<rect width="{W}" height="{H}" fill="#2a262a"/>'
    s += SL(Z_DAL, f'<rect x="0" y="0" width="1080" height="820" fill="#8a7a62"/>')
    for i in range(11):
        s += SL(Z_DAL, f'<rect x="{i*100:.0f}" y="0" width="52" height="820"'
                       f' fill="#9a8a70" opacity=".55"/>')
    s += SL(Z_DAL, f'<rect x="1080" y="0" width="840" height="820"'
                   f' fill="#7e6f58"/>')
    s += SL(Z_DAL, _ramki_na_stene(1140, 120, 700, t, 373, 4))
    s += SL(Z_DAL, _veshalka_s_paltom(60, 150, 820, t, 409))
    # полка с обувью под вешалкой и две шляпные коробки сверху
    s += SL(Z_DAL, f'<rect x="80" y="640" width="780" height="26" rx="8"'
                   f' fill="url(#dosk)" {o(5)}/>')
    for i in range(5):
        bx = 150 + i * 150
        s += SL(Z_DAL, f'<path d="M{bx-70:.0f},640 q{24:.0f},{-80:.0f}'
                       f' {74:.0f},{-74:.0f} q{54:.0f},{12:.0f} {58:.0f},{74:.0f} Z"'
                       f' fill="{["#3a2e26", "#5a3a2c", "#2e3540"][i % 3]}" {o(5)}/>'
                f'<rect x="{bx-74:.0f}" y="628" width="140" height="16" rx="6"'
                f' fill="#1d1812" {o(3)}/>')
    for i in (0, 1):
        s += SL(Z_DAL, f'<ellipse cx="{300+i*220:.0f}" cy="96" rx="96" ry="34"'
                       f' fill="#c9b79c" {o(5)}/>'
                f'<rect x="{204+i*220:.0f}" y="96" width="192" height="76" rx="12"'
                f' fill="#b8a68c" {o(5)}/>'
                f'<path d="M{216+i*220:.0f},130 h168" stroke="#9a8a68"'
                f' stroke-width="6"/>')
    s += SL(Z_DAL, tusklaya_lampochka(540, 120, t, 1.2, True))
    s += SL(Z_DAL, _konus_sveta(540, 170, 360, 480, 0, .38))
    # ПОДЗЕРКАЛЬНИК и круглое зеркало — крупный предмет
    s += SL(Z_SRED, f'{ten(760, 946, 420, 26, .5)}'
                    f'<rect x="300" y="700" width="1100" height="48" rx="12"'
                    f' fill="url(#derev)" {o(7)}/>'
            + f'<rect x="330" y="748" width="1040" height="30" rx="8"'
              f' fill="#5b4428" {o(5)}/>')
    for i in (0, 1):
        s += SL(Z_SRED, f'<rect x="{400+i*880:.0f}" y="778" width="46"'
                        f' height="170" rx="14" fill="#4a3522" {o(5)}/>'
                f'<ellipse cx="{423+i*880:.0f}" cy="860" rx="34" ry="20"'
                f' fill="#5e442a" {o(3)}/>')
    s += SL(Z_SRED, f'<rect x="520" y="778" width="660" height="150" rx="10"'
                    f' fill="url(#dosk)" {o(5)}/>'
            + f'<line x1="520" y1="850" x2="1180" y2="850" stroke="#3a2a1a"'
              f' stroke-width="8" opacity=".7"/>'
            + f'<circle cx="700" cy="818" r="16" fill="url(#zhel)" {o(3)}/>'
            + f'<circle cx="1000" cy="818" r="16" fill="url(#zhel)" {o(3)}/>')
    # круглое зеркало с отражением руки
    s += SL(Z_SRED, f'<circle cx="860" cy="400" r="280" fill="#6a5030" {o(8)}/>'
            + f'<circle cx="860" cy="400" r="246" fill="#4a5a66" opacity=".95"'
              f' {o(4)}/>'
            + f'<path d="M700,560 L900,230 L960,230 L760,560 Z" fill="#9fc0d4"'
              f' opacity="{.16+.1*abs(A.w(t,3.2)):.2f}"/>')
    # отражение руки в зеркале
    otr, (orx, ory) = rukav(1120, 620, 300, -140, t, "#6a4a52", "#eaf4ff", .4,
                            3.0, True)
    s += SL(Z_SRED, f'<g opacity=".55" clip-path="none">{otr}'
                    f'<ellipse cx="{orx:.0f}" cy="{ory:.0f}" rx="42" ry="32"'
                    f' fill="#d8c8b0" {o(4)}/></g>')
    # БЛЮДЦЕ С МЕЛОЧЬЮ на пол-кадра
    # БЛЮДЦЕ 260 px, а не 500: при rx=250 оно занимало четверть кадра и
    # наезжало на раму зеркала (осмотр порции 2)
    s += SL(Z_SRED, f'<ellipse cx="700" cy="692" rx="130" ry="44"'
                    f' fill="#f2ece0" {o(6)}/>'
            + f'<ellipse cx="700" cy="684" rx="110" ry="34" fill="#e4dfd0" {o(4)}/>'
            + f'<ellipse cx="700" cy="678" rx="88" ry="25" fill="#f6f2e8"'
              f' opacity=".9"/>'
            + f'<path d="M570,692 q130,40 260,0" fill="none" stroke="url(#zol)"'
              f' stroke-width="7"/>')
    ost = 1 - A.ease(A.seg(t, .4, 3.2))
    for i in range(9):
        a = math.radians(i * 40)
        rr = 62 * ost
        s += SL(Z_SRED, f'<ellipse cx="{700+rr*math.cos(a):.0f}"'
                        f' cy="{672+rr*.3*math.sin(a):.0f}" rx="22" ry="10"'
                        f' fill="url(#med)" {o(3)}/>'
                f'<ellipse cx="{694+rr*math.cos(a):.0f}"'
                f' cy="{668+rr*.3*math.sin(a):.0f}" rx="8" ry="4"'
                f' fill="#fff0c4" opacity="{.4+.5*abs(A.w(t,2.0,i*.2)):.2f}"/>')
    # ТРИ КУЧКИ монет и значки над ними
    znaki = ("buhanka", "tramvay", "korobok")
    for i, zn in enumerate(znaki):
        k = A.ease(A.seg(t, .8 + i * .8, .7))
        cx = 1020 + i * 190
        # КУЧКА, А НЕ ДВЕ МОНЕТЫ: семь монет горкой, с гуртом и бликом
        for m in range(7):
            s += SL(Z_SRED, f'<ellipse cx="{cx+rnd.uniform(-24, 24):.0f}"'
                            f' cy="{702-m*13*k:.0f}" rx="44" ry="19"'
                            f' fill="url(#med)" opacity="{k:.2f}" {o(3)}/>'
                    f'<ellipse cx="{cx-8+rnd.uniform(-18, 18):.0f}"'
                    f' cy="{698-m*13*k:.0f}" rx="12" ry="5" fill="#fff0c4"'
                    f' opacity="{k*(.35+.5*abs(A.w(t,2.2,m*.2))):.2f}"/>')
        if k > .3:
            zy = 480 - 60 * k
            if zn == "buhanka":
                s += SL(Z_SRED, f'<path d="M{cx-66:.0f},{zy:.0f}'
                                f' q{66:.0f},{-60:.0f} {132:.0f},0 Z"'
                                f' fill="url(#med)" opacity="{k:.2f}" {o(5)}/>'
                        f'<path d="M{cx-40:.0f},{zy-24:.0f} l14,-20 M{cx:.0f},'
                        f'{zy-34:.0f} l14,-20" stroke="#8a5a22" stroke-width="6"'
                        f' fill="none" opacity="{k:.2f}"/>')
            elif zn == "tramvay":
                s += SL(Z_SRED, f'<rect x="{cx-70:.0f}" y="{zy-70:.0f}"'
                                f' width="140" height="76" rx="12" fill="#8a4a3c"'
                                f' opacity="{k:.2f}" {o(5)}/>'
                        f'<rect x="{cx-56:.0f}" y="{zy-58:.0f}" width="42"'
                        f' height="34" rx="5" fill="#cfe0ea" opacity="{k:.2f}"/>'
                        f'<rect x="{cx+8:.0f}" y="{zy-58:.0f}" width="42"'
                        f' height="34" rx="5" fill="#cfe0ea" opacity="{k:.2f}"/>'
                        f'<path d="M{cx:.0f},{zy-70:.0f} l0,-40 l40,-16"'
                        f' fill="none" stroke="{ZHELEZ}" stroke-width="6"'
                        f' opacity="{k:.2f}"/>'
                        f'<circle cx="{cx-40:.0f}" cy="{zy+4:.0f}" r="13"'
                        f' fill="{CHUGUN}" opacity="{k:.2f}"/>'
                        f'<circle cx="{cx+40:.0f}" cy="{zy+4:.0f}" r="13"'
                        f' fill="{CHUGUN}" opacity="{k:.2f}"/>')
            else:
                s += SL(Z_SRED, f'<rect x="{cx-58:.0f}" y="{zy-54:.0f}"'
                                f' width="116" height="68" rx="8" fill="#c9b79c"'
                                f' opacity="{k:.2f}" {o(5)}/>'
                        f'<rect x="{cx-46:.0f}" y="{zy-42:.0f}" width="92"'
                        f' height="44" rx="5" fill="#8a4a3c" opacity="{k:.2f}"/>'
                        f'<path d="M{cx-30:.0f},{zy-20:.0f} h60" stroke="#efe2c2"'
                        f' stroke-width="6" opacity="{k:.2f}"/>')
    # РУКА ДО ЛОКТЯ — ничья, с варежкой на конце
    ruk, (ex, ey) = rukav(1880, 1050, 760, -148, t, "#6a4a52", "#ffd98a", .2,
                          3.0, True)
    s += SL(Z_SRED, ruk)
    s += SL(Z_SRED, f'<rect x="{ex+40:.0f}" y="{ey+10:.0f}" width="170" height="46"'
                    f' rx="18" fill="#6a4a52" {o(5)}/>')
    s += SL(Z_SRED, _varezhka(ex, ey, 900, t, .2))
    # расчёска, ключи, коробок спичек на подзеркальнике
    s += SL(Z_SRED, f'<rect x="1240" y="664" width="190" height="36" rx="10"'
                    f' fill="#3f4650" {o(5)}/>')
    for i in range(14):
        s += SL(Z_SRED, f'<line x1="{1252+i*13:.0f}" y1="664" x2="{1252+i*13:.0f}"'
                        f' y2="634" stroke="#3f4650" stroke-width="6"/>')
    s += SL(Z_SRED, _svyazka_klyuchey(1520, 640, t, 1.15, .3, 3))
    s += SL(Z_SRED, _zont_v_podstavke(1840, 980, t, 1.1))
    s += SL(Z_SRED, _sumka_hozyaystvennaya(1700, 976, t, .92, 1.0))
    s += SL(Z_SRED, f'<rect x="200" y="840" width="230" height="160" rx="12"'
                    f' fill="#5a3a2c" {o(6)}/>'
            + f'<rect x="216" y="860" width="198" height="42" rx="8"'
              f' fill="#6a4a38" {o(4)}/>'
            + f'<path d="M270,840 q46,-56 92,0" fill="none" stroke="#4a2e22"'
              f' stroke-width="13"/>'
            + f'<rect x="286" y="910" width="60" height="22" rx="8"'
              f' fill="url(#zhel)" {o(3)}/>')
    s += SL(Z_SRED, f'<line x1="1460" y1="990" x2="1488" y2="770" stroke="#5b4428"'
                    f' stroke-width="15" stroke-linecap="round"/>'
            + f'<path d="M1488,770 q30,-32 46,2" fill="none" stroke="#3a2a1a"'
              f' stroke-width="15"/>')
    s += SL(Z_SRED, f'<path d="M1296,700 q46,-40 92,0 q-10,66 -46,74'
                    f' q-36,-8 -46,-74 Z" fill="#dbeaf4" opacity=".9" {o(5)}/>'
            + f'<ellipse cx="1342" cy="640" rx="46" ry="15" fill="#cfe0ea" {o(3)}/>')
    # галошница под подзеркальником: три полки обуви парами
    for p_ in range(2):
        py_ = 834 + p_ * 56
        s += SL(Z_SRED, f'<rect x="540" y="{py_:.0f}" width="620" height="20"'
                        f' rx="7" fill="#5b4428" {o(4)}/>')
        for i in range(4):
            bx = 600 + i * 150
            s += SL(Z_SRED, f'<path d="M{bx-64:.0f},{py_:.0f} q{22:.0f},{-56:.0f}'
                            f' {66:.0f},{-54:.0f} q{48:.0f},{10:.0f} {52:.0f},{54:.0f} Z"'
                            f' fill="{["#3a2e26", "#5a3a2c", "#2e3540", "#6a4a3c"][i]}"'
                            f' {o(4)}/>'
                    f'<rect x="{bx-68:.0f}" y="{py_-12:.0f}" width="128"'
                    f' height="14" rx="5" fill="#1d1812" {o(3)}/>')
    # телефон с диском и записная книжка рядом с блюдцем
    s += SL(Z_SRED, f'<path d="M1060,700 L1250,700 L1232,614 L1078,614 Z"'
                    f' fill="#3f4650" {o(6)}/>'
            + f'<circle cx="1155" cy="658" r="42" fill="#5a6168" {o(4)}/>'
            + f'<circle cx="1155" cy="658" r="18" fill="#2b3038" {o(3)}/>'
            + f'<rect x="1066" y="586" width="180" height="40" rx="18"'
              f' fill="#2b3038" {o(5)}/>'
            + f'<ellipse cx="1080" cy="606" rx="30" ry="22" fill="#3f4650" {o(3)}/>'
            + f'<ellipse cx="1232" cy="606" rx="30" ry="22" fill="#3f4650" {o(3)}/>')
    for i in range(8):
        a = math.radians(i * 45 + 12)
        s += SL(Z_SRED, f'<circle cx="{1155+32*math.cos(a):.0f}"'
                        f' cy="{658+32*math.sin(a):.0f}" r="7" fill="#eaf0f4"'
                        f' opacity=".85"/>')
    s += SL(Z_SRED, f'<rect x="1300" y="700" width="150" height="46" rx="7"'
                    f' fill="#7a3a42" {o(5)}/>'
            + f'<rect x="1310" y="710" width="130" height="30" rx="4"'
              f' fill="#f2ece0" opacity=".9"/>')
    s += SL(Z_SRED, f'<rect x="1660" y="650" width="130" height="50" rx="8"'
                    f' fill="#8a4a3c" {o(5)}/>'
            + f'<rect x="1672" y="662" width="106" height="28" rx="4"'
              f' fill="#efe2c2" opacity=".9"/>'
            + f'<path d="M1690,676 h70" stroke="#8a5a22" stroke-width="5"/>')
    # низ кадра
    s += SL(Z_PERED, _polovik(520, 982, 820, 98, "#8a5a52", "#c9a05a")
            + _valenki_u_dveri(300, 1050, 1.0, t)
            + _gorodskoy_hlam(1560, 1060, 360, t, 379, ["korobka", "yaschik"])
            + _kot_zhivoy(1180, 1046, t, 1.1, "#423b35", .5))
    s += SL(Z_PERED, _stolb_pered(-8, 92, "#181310", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 540, 170, 5, 41, 150, .22))
    s += vinetka(.38)
    return s


# ── ПОМОЩНИКИ ЧЕТВЁРТОЙ ПАРТИИ ─────────────────────────────────────────────

def _terka(x, y, t, s_=1.0, ug=-8.0):
    """Тёрка: жестяное полотно рядами пробитых зубцов, деревянная ручка,
    загнутый борт и блик по кромке."""
    s = (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
         f'{ten(x, y + 10 * s_, 54 * s_, 11 * s_, .4)}'
         f'<rect x="{x-56*s_:.0f}" y="{y-250*s_:.0f}" width="{112*s_:.0f}"'
         f' height="{250*s_:.0f}" rx="{10*s_:.0f}" fill="#b6bcc2" {o(5)}/>'
         f'<rect x="{x-56*s_:.0f}" y="{y-250*s_:.0f}" width="{112*s_:.0f}"'
         f' height="{16*s_:.0f}" fill="#8b9299" opacity=".85"/>')
    for r in range(8):
        for c in range(4):
            zx = x - 40 * s_ + c * 27 * s_
            zy = y - 230 * s_ + r * 26 * s_
            s += (f'<path d="M{zx:.0f},{zy:.0f} l{9*s_:.0f},{-11*s_:.0f}'
                  f' l{9*s_:.0f},{11*s_:.0f} Z" fill="#e4e9ec" opacity=".9"/>')
    s += (f'<rect x="{x-30*s_:.0f}" y="{y-20*s_:.0f}" width="{60*s_:.0f}"'
          f' height="{76*s_:.0f}" rx="{14*s_:.0f}" fill="url(#derev)" {o(5)}/>'
          f'<line x1="{x-46*s_:.0f}" y1="{y-240*s_:.0f}" x2="{x-46*s_:.0f}"'
          f' y2="{y-40*s_:.0f}" stroke="#eaf4ff" stroke-width="{7*s_:.0f}"'
          f' opacity="{.3+.25*abs(A.w(t,2.6)):.2f}"/></g>')
    return s


def _butyl_masla(x, y, s_=1.0, t=0.0, naklon=.0, lej=.0):
    """Бутыль с маслом: тёмное стекло, масло до плеча, пробка, бумажный
    хомутик. lej 0..1 — наклоняется и льёт струйку."""
    ug = -naklon * 62
    s = (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
         f'{ten(x, y + 6 * s_, 44 * s_, 10 * s_, .4)}'
         f'<path d="M{x-44*s_:.0f},{y:.0f} L{x+44*s_:.0f},{y:.0f}'
         f' L{x+44*s_:.0f},{y-140*s_:.0f} q{-10*s_:.0f},{-40*s_:.0f}'
         f' {-30*s_:.0f},{-54*s_:.0f} L{x+14*s_:.0f},{y-248*s_:.0f}'
         f' L{x-14*s_:.0f},{y-248*s_:.0f} L{x-14*s_:.0f},{y-194*s_:.0f}'
         f' q{-20*s_:.0f},{14*s_:.0f} {-30*s_:.0f},{54*s_:.0f} Z"'
         f' fill="#7a6a3c" opacity=".9" {o(5)}/>'
         f'<path d="M{x-40*s_:.0f},{y-6*s_:.0f} L{x+40*s_:.0f},{y-6*s_:.0f}'
         f' L{x+40*s_:.0f},{y-120*s_:.0f} q{-40*s_:.0f},{10*s_:.0f}'
         f' {-80*s_:.0f},0 Z" fill="#d8a53c" opacity=".92"/>'
         f'<rect x="{x-18*s_:.0f}" y="{y-266*s_:.0f}" width="{36*s_:.0f}"'
         f' height="{22*s_:.0f}" rx="6" fill="#8a6a3c" {o(4)}/>'
         f'<rect x="{x-30*s_:.0f}" y="{y-176*s_:.0f}" width="{60*s_:.0f}"'
         f' height="{40*s_:.0f}" rx="5" fill="#f2ead6" {o(3)}/>'
         f'<line x1="{x-30*s_:.0f}" y1="{y-110*s_:.0f}" x2="{x-30*s_:.0f}"'
         f' y2="{y-30*s_:.0f}" stroke="#fff0c8" stroke-width="{7*s_:.0f}"'
         f' opacity=".45"/></g>')
    if lej > 0:
        s += (f'<path d="M{x+36*s_:.0f},{y-230*s_:.0f}'
              f' q{30*s_:.0f},{80*s_*lej:.0f} {20*s_:.0f},{190*s_*lej:.0f}"'
              f' fill="none" stroke="#e8b84c" stroke-width="{11*s_:.0f}"'
              f' stroke-linecap="round" opacity=".92"/>')
    return s


def _kadushka_kapusty(x, y, t, s_=1.0):
    """Кадушка с квашеной капустой: клёпки, два обруча, деревянный круг с
    гнётом-камнем, рассол и выбившийся капустный лист."""
    h2, w2 = 190 * s_, 180 * s_
    return (f'{ten(x, y + 8 * s_, w2 * .52, 14 * s_, .45)}'
            f'<path d="M{x-w2/2:.0f},{y-h2:.0f} L{x+w2/2:.0f},{y-h2:.0f}'
            f' L{x+w2*.40:.0f},{y:.0f} L{x-w2*.40:.0f},{y:.0f} Z"'
            f' fill="url(#derev)" {o(6)}/>'
            f'<rect x="{x-w2/2-5:.0f}" y="{y-h2*.86:.0f}" width="{w2+10:.0f}"'
            f' height="{16*s_:.0f}" rx="6" fill="{ZHELEZ}" {o(3)}/>'
            f'<rect x="{x-w2*.44:.0f}" y="{y-h2*.26:.0f}" width="{w2*.88:.0f}"'
            f' height="{16*s_:.0f}" rx="6" fill="{ZHELEZ}" {o(3)}/>'
            f'<ellipse cx="{x:.0f}" cy="{y-h2:.0f}" rx="{w2/2:.0f}"'
            f' ry="{w2*.15:.0f}" fill="#3e3228" {o(4)}/>'
            f'<ellipse cx="{x:.0f}" cy="{y-h2+8*s_:.0f}" rx="{w2*.42:.0f}"'
            f' ry="{w2*.12:.0f}" fill="#cdbf9c" opacity=".9"/>'
            f'<ellipse cx="{x+w2*.10:.0f}" cy="{y-h2-16*s_:.0f}"'
            f' rx="{w2*.20:.0f}" ry="{w2*.16:.0f}" fill="#6a6256" {o(4)}/>'
            f'<path d="M{x-w2*.34:.0f},{y-h2-4*s_:.0f}'
            f' q{w2*.16:.0f},{-30*s_:.0f} {w2*.34:.0f},{-8*s_:.0f}'
            f' q{-w2*.12:.0f},{22*s_:.0f} {-w2*.34:.0f},{8*s_:.0f} Z"'
            f' fill="#cfd8a8" {o(3)}/>')


def _pugalo(x, y, t, s_=1.0):
    """Пугало: крестовина из жердей, мешковина рубахой, ведро вместо головы,
    солома из рукавов и тряпица, которая хлопает на ветру."""
    kach = 2.6 * A.w(t, 3.2, .2)
    s = (f'<g transform="rotate({kach:.1f} {x:.0f} {y:.0f})">'
         f'<line x1="{x:.0f}" y1="{y:.0f}" x2="{x+6*s_:.0f}" y2="{y-420*s_:.0f}"'
         f' stroke="url(#derev)" stroke-width="{20*s_:.0f}"/>'
         f'<line x1="{x-150*s_:.0f}" y1="{y-300*s_:.0f}" x2="{x+156*s_:.0f}"'
         f' y2="{y-310*s_:.0f}" stroke="url(#derev)" stroke-width="{16*s_:.0f}"/>'
         f'<path d="M{x-120*s_:.0f},{y-300*s_:.0f} L{x+126*s_:.0f},{y-306*s_:.0f}'
         f' L{x+90*s_:.0f},{y-110*s_:.0f} L{x-84*s_:.0f},{y-104*s_:.0f} Z"'
         f' fill="#b9a883" {o(6)}/>')
    for i in range(5):
        s += (f'<path d="M{x-110*s_+i*54*s_:.0f},{y-110*s_:.0f}'
              f' q{8*s_:.0f},{40*s_:.0f} {-6*s_:.0f},{70*s_:.0f}" fill="none"'
              f' stroke="#c9a05a" stroke-width="{7*s_:.0f}"/>')
    for sgn in (-1, 1):
        for i in range(4):
            a = math.radians(-20 + i * 18) * sgn
            s += (f'<line x1="{x+sgn*140*s_:.0f}" y1="{y-302*s_:.0f}"'
                  f' x2="{x+sgn*140*s_+sgn*60*s_*math.cos(a):.0f}"'
                  f' y2="{y-302*s_+60*s_*math.sin(a):.0f}" stroke="#c9a05a"'
                  f' stroke-width="{6*s_:.0f}"/>')
    s += (f'<path d="M{x-54*s_:.0f},{y-316*s_:.0f} L{x+60*s_:.0f},{y-320*s_:.0f}'
          f' L{x+48*s_:.0f},{y-424*s_:.0f} L{x-42*s_:.0f},{y-420*s_:.0f} Z"'
          f' fill="#6a7278" {o(6)}/>'
          f'<ellipse cx="{x+4*s_:.0f}" cy="{y-424*s_:.0f}" rx="{52*s_:.0f}"'
          f' ry="{15*s_:.0f}" fill="#49535b" {o(4)}/>'
          f'<path d="M{x+60*s_:.0f},{y-290*s_:.0f}'
          f' q{40*s_+14*s_*A.w(t, 1.1, .3):.0f},{30*s_:.0f} {30*s_:.0f},{76*s_:.0f}'
          f' l{-30*s_:.0f},{-10*s_:.0f} q{16*s_:.0f},{-34*s_:.0f}'
          f' {-14*s_:.0f},{-62*s_:.0f} Z" fill="{TKAN}" {o(3)}/></g>')
    return s


def _vorona(x, y, t, s_=1.0, ph=.0, letit=.0):
    """Ворона: чёрное тело с сизым отливом, крупный клюв, лапы с когтями.
    letit 0..1 — слетает, крылья раскрываются."""
    kr = 40 * s_ * letit + 7 * s_ * A.w(t, 1.1, ph)
    pod = -180 * s_ * letit
    s = (f'<g transform="translate({120 * s_ * letit:.1f},{pod:.1f})">'
         f'<ellipse cx="{x:.0f}" cy="{y-40*s_:.0f}" rx="{54*s_:.0f}"'
         f' ry="{32*s_:.0f}" fill="#23262c" {o(4)}/>'
         f'<path d="M{x-50*s_:.0f},{y-48*s_:.0f} q{36*s_:.0f},{-24*s_-kr:.0f}'
         f' {80*s_:.0f},{-4*s_:.0f} q{-32*s_:.0f},{28*s_+kr*.4:.0f}'
         f' {-80*s_:.0f},{4*s_:.0f} Z" fill="#33373f" {o(3)}/>'
         f'<path d="M{x-54*s_:.0f},{y-34*s_:.0f} l{-40*s_:.0f},{10*s_:.0f}'
         f' l{36*s_:.0f},{14*s_:.0f} Z" fill="#2a2e35" {o(3)}/>'
         f'<circle cx="{x+40*s_:.0f}" cy="{y-70*s_:.0f}" r="{21*s_:.0f}"'
         f' fill="#23262c" {o(3)}/>'
         f'<path d="M{x+58*s_:.0f},{y-70*s_:.0f} l{34*s_:.0f},{7*s_:.0f}'
         f' l{-32*s_:.0f},{10*s_:.0f} Z" fill="#5e676e" {o(2)}/>'
         f'<circle cx="{x+44*s_:.0f}" cy="{y-76*s_:.0f}" r="{4.4*s_:.0f}"'
         f' fill="#e4e9ec"/>'
         f'<circle cx="{x+45*s_:.0f}" cy="{y-76*s_:.0f}" r="{2.2*s_:.0f}"'
         f' fill="{K}"/>')
    if letit < .5:
        for dx in (-10, 12):
            s += (f'<line x1="{x+dx*s_:.0f}" y1="{y-12*s_:.0f}"'
                  f' x2="{x+dx*s_-4*s_:.0f}" y2="{y:.0f}" stroke="#5e676e"'
                  f' stroke-width="{5*s_:.0f}"/>')
    return s + "</g>"


def _gryadka_redki(x, y, w_, t, seed=5, n=6, vyrvana=-1, vyh=.0):
    """Грядка редьки: земляной гребень, из него торчат чёрные макушки с
    ботвой. vyrvana — номер редьки, которая выскакивает (vyh 0..1)."""
    rnd = random.Random(seed)
    s = (f'<path d="M{x:.0f},{y:.0f} q{w_*.25:.0f},{-54:.0f} {w_*.5:.0f},{-20:.0f}'
         f' q{w_*.25:.0f},{34:.0f} {w_*.5:.0f},{-14:.0f} L{x+w_:.0f},{y+120:.0f}'
         f' L{x:.0f},{y+120:.0f} Z" fill="#4a3c2c" {o(5)}/>')
    for i in range(16):
        s += (f'<ellipse cx="{x+rnd.uniform(20, w_-20):.0f}"'
              f' cy="{y+rnd.uniform(10, 100):.0f}" rx="{rnd.uniform(26, 56):.0f}"'
              f' ry="{rnd.uniform(9, 17):.0f}" fill="#3b3024" opacity=".8"/>')
    for i in range(n):
        gx = x + (i + .5) * w_ / n + rnd.uniform(-16, 16)
        gy = y - 10 + rnd.uniform(-14, 14)
        if i == vyrvana:
            gy -= 320 * vyh
        s += _redka(gx, gy, .62 + (i % 3) * .07, t, rnd.uniform(-12, 12),
                    .3 + (.7 if i == vyrvana else .0) * vyh)
    return s


def _kladovaya_polka(x, y, w_, t, seed=7):
    """Полка зимней кладовой: толстая доска на кронштейнах, связки лука,
    банка мёда с деревянной лопаткой, мешочек сушёной малины с завязкой и
    градусник в деревянном футляре."""
    rnd = random.Random(seed)
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="34" rx="10"'
         f' fill="url(#dosk)" {o(6)}/>'
         f'<rect x="{x:.0f}" y="{y+34:.0f}" width="{w_:.0f}" height="18" rx="7"'
         f' fill="#5b4428" {o(4)}/>')
    for k in (x + 90, x + w_ * .5, x + w_ - 120):
        s += (f'<path d="M{k:.0f},{y+52:.0f} l34,56 l-38,0 Z" fill="{ZHELEZ}" {o(4)}/>')
    # связки лука под полкой
    for i in range(3):
        lx = x + 150 + i * 160
        kach = 2.2 * A.w(t, 3.4, i * .3)
        s += (f'<g transform="rotate({kach:.1f} {lx:.0f} {y+52:.0f})">')
        for k in range(5):
            s += (f'<ellipse cx="{lx-34+k*17:.0f}" cy="{y+120+(k%2)*26:.0f}"'
                  f' rx="26" ry="32" fill="#c9a05a" {o(4)}/>'
                  f'<line x1="{lx-34+k*17:.0f}" y1="{y+88+(k%2)*26:.0f}"'
                  f' x2="{lx-28+k*17:.0f}" y2="{y+54:.0f}" stroke="#8a7a46"'
                  f' stroke-width="6"/>')
        s += "</g>"
    # банка мёда с лопаткой
    bx = x + w_ - 300
    s += (f'<rect x="{bx:.0f}" y="{y-150:.0f}" width="150" height="150" rx="12"'
          f' fill="url(#stekl)" opacity=".92" {o(5)}/>'
          f'<rect x="{bx+8:.0f}" y="{y-104:.0f}" width="134" height="104" rx="8"'
          f' fill="#d8a53c"/>'
          f'<rect x="{bx-6:.0f}" y="{y-168:.0f}" width="162" height="24" rx="9"'
          f' fill="{ZHELEZ}" {o(4)}/>'
          f'<line x1="{bx+112:.0f}" y1="{y-160:.0f}" x2="{bx+128:.0f}"'
          f' y2="{y-250:.0f}" stroke="url(#derev)" stroke-width="15"/>'
          f'<ellipse cx="{bx+130:.0f}" cy="{y-262:.0f}" rx="24" ry="16"'
          f' fill="url(#derev)" {o(4)}/>')
    # мешочек сушёной малины
    mx = x + 140
    s += (f'<path d="M{mx-60:.0f},{y-8:.0f} q{-16:.0f},{-104:.0f} {28:.0f},{-130:.0f}'
          f' q{34:.0f},{-12:.0f} {64:.0f},{8:.0f} q{34:.0f},{34:.0f}'
          f' {24:.0f},{122:.0f} Z" fill="#cdbf9c" {o(6)}/>'
          f'<path d="M{mx-28:.0f},{y-134:.0f} q{30:.0f},{-18:.0f} {58:.0f},{4:.0f}"'
          f' fill="none" stroke="{TKAN}" stroke-width="10"/>')
    for i in range(5):
        s += (f'<circle cx="{mx-30+i*22:.0f}" cy="{y-78+(i%2)*20:.0f}" r="13"'
              f' fill="#9c2f3c" opacity=".9" {o(2)}/>')
    # градусник в футляре
    gx = x + 420
    s += (f'<rect x="{gx:.0f}" y="{y-190:.0f}" width="54" height="190" rx="10"'
          f' fill="url(#derev)" {o(5)}/>'
          f'<rect x="{gx+16:.0f}" y="{y-174:.0f}" width="22" height="160" rx="8"'
          f' fill="#efe8da" {o(3)}/>'
          f'<rect x="{gx+22:.0f}" y="{y-94:.0f}" width="10" height="76" rx="5"'
          f' fill="#b8352c"/>')
    for i in range(7):
        s += (f'<line x1="{gx+16:.0f}" y1="{y-166+i*22:.0f}" x2="{gx+28:.0f}"'
              f' y2="{y-166+i*22:.0f}" stroke="#8a8274" stroke-width="3"/>')
    return s


def _romashka(x, y, t, s_=1.0, lep=8, oborvan=.0, ug=0.0):
    """Ромашка: жёлтая сердцевина с точками, белые лепестки веером, стебель
    с резными листьями. oborvan 0..1 — последний лепесток отрывается."""
    s = (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
         f'<path d="M{x:.0f},{y:.0f} q{-16*s_:.0f},{120*s_:.0f} {4*s_:.0f},{250*s_:.0f}"'
         f' fill="none" stroke="#5c8a40" stroke-width="{11*s_:.0f}"/>')
    for i in (0, 1):
        yy = y + 110 * s_ + i * 70 * s_
        sgn = 1 if i % 2 == 0 else -1
        s += (f'<path d="M{x-8*s_+i*4*s_:.0f},{yy:.0f}'
              f' q{sgn*44*s_:.0f},{-26*s_:.0f} {sgn*76*s_:.0f},{10*s_:.0f}'
              f' q{-sgn*40*s_:.0f},{22*s_:.0f} {-sgn*76*s_:.0f},{-10*s_:.0f} Z"'
              f' fill="#4e7a3c" {o(3)}/>')
    for i in range(lep):
        a = math.radians(i * 360.0 / lep + 8 * A.w(t, 3.2, .2))
        dl = 74 * s_
        ex, ey = x + dl * math.cos(a), y + dl * math.sin(a)
        op = 1.0
        if i == lep - 1:
            ex += 90 * s_ * oborvan
            ey -= 40 * s_ * oborvan
            op = 1 - oborvan * .5
        s += (f'<ellipse cx="{ex:.0f}" cy="{ey:.0f}" rx="{36*s_:.0f}"'
              f' ry="{17*s_:.0f}" transform="rotate({math.degrees(a):.0f}'
              f' {ex:.0f} {ey:.0f})" fill="#f8f6ee" opacity="{op:.2f}"'
              f' stroke="{K}" stroke-width="{max(2, 4 * s_):.1f}"/>')
    s += (f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{34*s_:.0f}" fill="#e8b84c"'
          f' {o(4)}/>')
    rnd = random.Random(int(x))
    for i in range(9):
        a = rnd.uniform(0, 6.28)
        rr = rnd.uniform(0, 26) * s_
        s += (f'<circle cx="{x+rr*math.cos(a):.0f}" cy="{y+rr*math.sin(a):.0f}"'
              f' r="{3.4*s_:.0f}" fill="#b5803a" opacity=".85"/>')
    return s + "</g>"


def _troyka(x, y, t, s_=1.0, k=.0):
    """Тройка с бубенцами: дуга с колокольцем, три коня в упряжке (ноги в
    беге), розвальни, ямщик на облучке. k 0..1 — проезд мимо окна."""
    nog = lambda f: 26 * s_ * math.sin(t * 9 + f)
    s = f'<g transform="translate({x:.0f},{y:.0f})">'
    # КОНИ ВРОЗЬ: при шаге 150 px тулова по 208 px слипались в кучу
    for i, (dx, sc, col) in enumerate(((-280, .88, "#6a4a32"),
                                       (0, 1.0, "#3e3630"),
                                       (280, .94, "#7d5a3c"))):
        hx = dx * s_
        s += (f'<ellipse cx="{hx:.0f}" cy="{-150*sc*s_:.0f}" rx="{104*sc*s_:.0f}"'
              f' ry="{56*sc*s_:.0f}" fill="{col}" {o(5)}/>'
              # шея: от тулова к голове, короткая и толстая
              f'<path d="M{hx+74*sc*s_:.0f},{-180*sc*s_:.0f}'
              f' q{40*sc*s_:.0f},{-20*sc*s_:.0f} {52*sc*s_:.0f},{-58*sc*s_:.0f}'
              f' l{44*sc*s_:.0f},{16*sc*s_:.0f}'
              f' q{-16*sc*s_:.0f},{56*sc*s_:.0f} {-56*sc*s_:.0f},{70*sc*s_:.0f} Z"'
              f' fill="{col}" {o(5)}/>'
              # ГОЛОВА КРУПНАЯ И БЛИЖЕ (была 74×52 с выносом 138 — читалась
              # котом): 110×68 при выносе 85
              f'<ellipse cx="{hx+128*sc*s_:.0f}" cy="{-256*sc*s_:.0f}"'
              f' rx="{55*sc*s_:.0f}" ry="{34*sc*s_:.0f}" fill="{col}" {o(5)}/>'
              f'<path d="M{hx+160*sc*s_:.0f},{-236*sc*s_:.0f}'
              f' q{30*sc*s_:.0f},{6*sc*s_:.0f} {34*sc*s_:.0f},{26*sc*s_:.0f}'
              f' q{-26*sc*s_:.0f},{10*sc*s_:.0f} {-44*sc*s_:.0f},{-6*sc*s_:.0f} Z"'
              f' fill="#2e2620" {o(3)}/>'
              f'<circle cx="{hx+150*sc*s_:.0f}" cy="{-268*sc*s_:.0f}"'
              f' r="{7*s_:.0f}" fill="{K}"/>'
              f'<circle cx="{hx+152*sc*s_:.0f}" cy="{-270*sc*s_:.0f}"'
              f' r="{2.6*s_:.0f}" fill="#eaf4ff"/>'
              # уши парой
              f'<path d="M{hx+112*sc*s_:.0f},{-286*sc*s_:.0f} l{-4*s_:.0f},{-30*s_:.0f}'
              f' l{22*s_:.0f},{18*s_:.0f} Z" fill="{col}" {o(2)}/>'
              f'<path d="M{hx+142*sc*s_:.0f},{-288*sc*s_:.0f} l{6*s_:.0f},{-28*s_:.0f}'
              f' l{18*s_:.0f},{22*s_:.0f} Z" fill="{col}" {o(2)}/>')
        # ГРИВА прядями по шее и хвост метёлкой
        for j in range(6):
            s += (f'<path d="M{hx+86*sc*s_+j*12*sc*s_:.0f},{-212*sc*s_-j*8*sc*s_:.0f}'
                  f' q{-18*sc*s_:.0f},{22*sc*s_:.0f} {-26*sc*s_:.0f},{48*sc*s_:.0f}"'
                  f' fill="none" stroke="#2e2620" stroke-width="{7*sc*s_:.0f}"'
                  f' opacity=".8"/>')
        s += (f'<path d="M{hx-104*sc*s_:.0f},{-186*sc*s_:.0f}'
              f' q{-50*sc*s_:.0f},{50*sc*s_:.0f} {-30*sc*s_:.0f},{124*sc*s_:.0f}"'
              f' fill="none" stroke="#2e2620" stroke-width="{16*sc*s_:.0f}"'
              f' stroke-linecap="round"/>')
        for j, fz in enumerate((0, 1.6, 3.1, 4.6)):
            lx = hx - 70 * sc * s_ + j * 48 * sc * s_
            s += (f'<line x1="{lx:.0f}" y1="{-120*sc*s_:.0f}"'
                  f' x2="{lx+nog(fz):.0f}" y2="{-6*s_:.0f}" stroke="{col}"'
                  f' stroke-width="{19*sc*s_:.0f}" stroke-linecap="round"/>'
                  # КОПЫТО: без него нога читалась палкой
                  f'<rect x="{lx+nog(fz)-11*sc*s_:.0f}" y="{-20*s_:.0f}"'
                  f' width="{22*sc*s_:.0f}" height="{20*s_:.0f}" rx="{5*s_:.0f}"'
                  f' fill="#1d1812" {o(2)}/>')
        s += (f'<path d="M{hx-104*sc*s_:.0f},{-200*sc*s_:.0f}'
              f' q{-40*sc*s_:.0f},{40*sc*s_:.0f} {-16*sc*s_:.0f},{100*sc*s_:.0f}"'
              f' fill="none" stroke="#2e2620" stroke-width="{9*s_:.0f}"/>')
    # дуга с бубенцами
    s += (f'<path d="M{-90*s_:.0f},{-230*s_:.0f} q{90*s_:.0f},{-150*s_:.0f}'
          f' {180*s_:.0f},0" fill="none" stroke="#b8352c"'
          f' stroke-width="{20*s_:.0f}"/>')
    for i in range(3):
        bx = -50 * s_ + i * 50 * s_
        s += (f'<circle cx="{bx:.0f}" cy="{-320*s_+10*s_*math.sin(t*8+i):.0f}"'
              f' r="{15*s_:.0f}" fill="url(#zhel)" {o(3)}/>'
              f'<circle cx="{bx:.0f}" cy="{-316*s_:.0f}" r="{5*s_:.0f}"'
              f' fill="#7a4d1c"/>')
    # розвальни и ямщик
    s += (f'<path d="M{-430*s_:.0f},{-30*s_:.0f} L{-130*s_:.0f},{-30*s_:.0f}'
          f' q{40*s_:.0f},{-4*s_:.0f} {46*s_:.0f},{-44*s_:.0f}" fill="none"'
          f' stroke="#5b4428" stroke-width="{15*s_:.0f}" stroke-linecap="round"/>'
          f'<rect x="{-420*s_:.0f}" y="{-140*s_:.0f}" width="{300*s_:.0f}"'
          f' height="{110*s_:.0f}" rx="{14*s_:.0f}" fill="url(#derev)" {o(6)}/>')
    for i in range(6):
        s += (f'<line x1="{-400*s_+i*54*s_:.0f}" y1="{-140*s_:.0f}"'
              f' x2="{-400*s_+i*54*s_:.0f}" y2="{-30*s_:.0f}" stroke="#6a5030"'
              f' stroke-width="{8*s_:.0f}"/>')
    return s + "</g>"


def _zayac(x, y, t, s_=1.0, k=.0):
    """Заяц перебегает дорогу: серо-белое тело, длинные уши прижаты, прыжок
    дугой. k 0..1 — доля перебега."""
    sk = abs(math.sin(k * math.pi * 3)) * 70 * s_
    xx = x + (1920 - x) * k * .5
    return (f'<g transform="translate({xx-x:.0f},{-sk:.1f})">'
            f'{ten(x, y + 6 * s_, 44 * s_, 10 * s_, .35)}'
            f'<ellipse cx="{x:.0f}" cy="{y-40*s_:.0f}" rx="{58*s_:.0f}"'
            f' ry="{34*s_:.0f}" fill="#cdc6bb" {o(4)}/>'
            f'<ellipse cx="{x+52*s_:.0f}" cy="{y-66*s_:.0f}" rx="{28*s_:.0f}"'
            f' ry="{22*s_:.0f}" fill="#d8d2c8" {o(3)}/>'
            f'<path d="M{x+46*s_:.0f},{y-84*s_:.0f} q{30*s_:.0f},{-54*s_:.0f}'
            f' {52*s_:.0f},{-44*s_:.0f} q{-14*s_:.0f},{40*s_:.0f}'
            f' {-38*s_:.0f},{54*s_:.0f} Z" fill="#cdc6bb" {o(3)}/>'
            f'<path d="M{x+34*s_:.0f},{y-86*s_:.0f} q{18*s_:.0f},{-56*s_:.0f}'
            f' {36*s_:.0f},{-52*s_:.0f} q{-6*s_:.0f},{42*s_:.0f}'
            f' {-26*s_:.0f},{56*s_:.0f} Z" fill="#b9b2a8" {o(3)}/>'
            f'<circle cx="{x+62*s_:.0f}" cy="{y-70*s_:.0f}" r="{5*s_:.0f}"'
            f' fill="{K}"/>'
            f'<ellipse cx="{x-54*s_:.0f}" cy="{y-48*s_:.0f}" rx="{16*s_:.0f}"'
            f' ry="{13*s_:.0f}" fill="#f2efe8" {o(2)}/>'
            f'<line x1="{x-20*s_:.0f}" y1="{y-16*s_:.0f}" x2="{x-34*s_:.0f}"'
            f' y2="{y:.0f}" stroke="#b9b2a8" stroke-width="{10*s_:.0f}"/>'
            f'<line x1="{x+22*s_:.0f}" y1="{y-16*s_:.0f}" x2="{x+34*s_:.0f}"'
            f' y2="{y:.0f}" stroke="#b9b2a8" stroke-width="{10*s_:.0f}"/></g>')


def _gitara_na_stene(x, y, t, s_=1.0):
    """Гитара на стене: корпус восьмёркой, розетка, гриф с ладами, шесть
    струн и лента-подвес."""
    s = (f'<path d="M{x:.0f},{y:.0f} q{-78*s_:.0f},{10*s_:.0f} {-80*s_:.0f},{96*s_:.0f}'
         f' q{-2*s_:.0f},{86*s_:.0f} {80*s_:.0f},{92*s_:.0f}'
         f' q{82*s_:.0f},{-6*s_:.0f} {80*s_:.0f},{-92*s_:.0f}'
         f' q{-2*s_:.0f},{-86*s_:.0f} {-80*s_:.0f},{-96*s_:.0f} Z"'
         f' fill="url(#med)" {o(6)}/>'
         f'<path d="M{x-62*s_:.0f},{y+76*s_:.0f} q{62*s_:.0f},{-34*s_:.0f}'
         f' {124*s_:.0f},0" fill="none" stroke="#8a5a22" stroke-width="{7*s_:.0f}"/>'
         f'<circle cx="{x:.0f}" cy="{y+118*s_:.0f}" r="{34*s_:.0f}" fill="#2e2620"'
         f' {o(4)}/>'
         f'<circle cx="{x:.0f}" cy="{y+118*s_:.0f}" r="{42*s_:.0f}" fill="none"'
         f' stroke="#8a5a22" stroke-width="{6*s_:.0f}"/>'
         f'<rect x="{x-20*s_:.0f}" y="{y-180*s_:.0f}" width="{40*s_:.0f}"'
         f' height="{190*s_:.0f}" rx="{8*s_:.0f}" fill="#5b4428" {o(5)}/>'
         f'<rect x="{x-26*s_:.0f}" y="{y-216*s_:.0f}" width="{52*s_:.0f}"'
         f' height="{44*s_:.0f}" rx="{8*s_:.0f}" fill="#4a3522" {o(4)}/>')
    for i in range(6):
        s += (f'<line x1="{x-18*s_:.0f}" y1="{y-150*s_+i*26*s_:.0f}"'
              f' x2="{x+18*s_:.0f}" y2="{y-150*s_+i*26*s_:.0f}" stroke="#cdbf9c"'
              f' stroke-width="{4*s_:.0f}" opacity=".8"/>')
    for i in range(6):
        s += (f'<line x1="{x-15*s_+i*6*s_:.0f}" y1="{y-196*s_:.0f}"'
              f' x2="{x-15*s_+i*6*s_:.0f}" y2="{y+172*s_:.0f}" stroke="#efe8da"'
              f' stroke-width="{2.4*s_:.0f}" opacity=".9"/>')
    s += (f'<path d="M{x-10*s_:.0f},{y-212*s_:.0f} q{-70*s_:.0f},{-50*s_:.0f}'
          f' {-110*s_:.0f},{-6*s_:.0f}" fill="none" stroke="{TKAN}"'
          f' stroke-width="{10*s_:.0f}"/>')
    return s


def _kovrik_s_olenyami(x, y, w_, h_, t):
    """Коврик с оленями над кроватью: бордовое поле, кайма зигзагом, два
    оленя с рогами у ёлочки — рисованный ковёр шестидесятых."""
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}" rx="8"'
         f' fill="#7a2f33" {o(6)}/>'
         f'<rect x="{x+24:.0f}" y="{y+24:.0f}" width="{w_-48:.0f}"'
         f' height="{h_-48:.0f}" rx="6" fill="none" stroke="#c9a05a"'
         f' stroke-width="9"/>')
    for i in range(int((w_ - 60) / 40)):
        s += (f'<path d="M{x+34+i*40:.0f},{y+h_-34:.0f} l20,-22 l20,22"'
              f' fill="none" stroke="#d8b070" stroke-width="6" opacity=".85"/>')
    for sgn, ox_ in ((-1, x + w_ * .32), (1, x + w_ * .68)):
        s += (f'<g transform="translate({ox_:.0f},{y+h_*.58:.0f}) scale({sgn},1)">'
              f'<ellipse cx="0" cy="0" rx="74" ry="40" fill="#c9a05a" {o(4)}/>'
              f'<path d="M50,-26 q40,-16 46,-70" fill="none" stroke="#c9a05a"'
              f' stroke-width="15"/>'
              f'<ellipse cx="100" cy="-104" rx="28" ry="20" fill="#c9a05a" {o(3)}/>'
              f'<path d="M86,-124 q-12,-54 -46,-70 M112,-124 q14,-56 50,-66"'
              f' fill="none" stroke="#d8b070" stroke-width="8"/>'
              f'<path d="M60,-134 l-16,-30 M130,-130 l20,-28" fill="none"'
              f' stroke="#d8b070" stroke-width="6"/>')
        for dx in (-50, -14, 22, 54):
            s += (f'<line x1="{dx}" y1="30" x2="{dx - 8}" y2="104"'
                  f' stroke="#c9a05a" stroke-width="11"/>')
        s += "</g>"
    s += (f'<path d="M{x+w_*.5:.0f},{y+h_*.26:.0f} l-54,96 l108,0 Z"'
          f' fill="#4e7a3c" {o(4)}/>'
          f'<path d="M{x+w_*.5:.0f},{y+h_*.40:.0f} l-70,110 l140,0 Z"'
          f' fill="#3f6a34" {o(4)}/>')
    return s


# ── ДЕКОРАЦИИ, ЧЕТВЁРТАЯ ПАРТИЯ ────────────────────────────────────────────

def gorstka_protiv_buhanki(t):
    """Стол в избе: чашечные весы на пол-кадра, крынка, нож, полотенце.
    Девушка кладёт на левую чашу горстку монет, на правую — круглый каравай
    и крынку молока. Чаши встают ровно, кулак с монетами сжимается."""
    rnd = random.Random(401)
    pol = 980
    s = f'<rect width="{W}" height="{H}" fill="#2a241c"/>'
    s += SL(Z_DAL, brevna(0, 40, 1060, pol - 40, 96)
            + brevna(1060, 40, 860, pol - 40, 96))
    s += SL(Z_DAL, _polka_s_utvaryu(90, 240, 600, t, 421, 5))
    s += SL(Z_DAL, _polka_s_utvaryu(1180, 260, 620, t, 431, 5))
    # ЗА ВЕСАМИ НЕ ГОЛАЯ СТЕНА: полка с утварью ровно за чашами
    s += SL(Z_DAL, _polka_s_utvaryu(700, 330, 560, t, 193, 4))
    s += SL(Z_DAL, _polka_s_utvaryu(100, 540, 560, t, 433, 4))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-16:.0f}" width="{W}"'
                   f' height="{H-pol+16:.0f}" fill="#5e4a34"/>'
            + polovicy(pol + 16) + _pol_shvy(pol + 20, 1070, 439, 6, "#4a3824"))
    s += SL(Z_SRED, svecha(1700, pol - 420, t, .2, 1.7, 130))
    s += SL(Z_SRED, _konus_sveta(1700, pol - 540, 520, 360, 12, .40))
    # СТОЛ и ВЕСЫ — главный предмет
    s += SL(Z_SRED, stol(240, pol - 330, 1200, 40, True))
    sy = pol - 330
    rov = A.ease(A.seg(t, 1.6, 1.2))
    # ВЕСЫ ПРАВЕЕ: левая чаша с горсткой стояла прямо за головой девушки
    s += SL(Z_SRED, _vesy(1160, sy - 8, t, 1.2, -.5 * (1 - rov), (1 - rov) * .5, 300))
    # монеты на левую чашу, каравай и крынка — на правую
    mk = A.ease(A.seg(t, .3, .8))
    # ГОРСТКА МЕЛОЧИ — настоящая горка из двенадцати монет с гуртом и бликом
    for i in range(12):
        a = math.radians(i * 30 + 12)
        rr = 16 + (i % 3) * 22
        s += SL(Z_SRED, f'<ellipse cx="{1160-310+rr*math.cos(a):.0f}"'
                        f' cy="{sy-312+100-7*(i%4)*mk+rr*.34*math.sin(a):.0f}"'
                        f' rx="30" ry="14" fill="url(#med)" opacity="{mk:.2f}"'
                        f' {o(3)}/>'
                f'<ellipse cx="{1160-316+rr*math.cos(a):.0f}"'
                f' cy="{sy-316+100-7*(i%4)*mk+rr*.34*math.sin(a):.0f}" rx="11"'
                f' ry="5" fill="#fff0c4" opacity="{mk*(.4+.5*abs(A.w(t,2.0,i*.2))):.2f}"/>')
    # КАРАВАЙ и КРЫНКА на другой чаше — крупно, с рушником
    s += SL(Z_SRED, karavay(1160 + 310, sy - 312 + 86, 1.34, True))
    s += SL(Z_SRED, krynka(1160 + 420, sy - 312 + 100, 1.4))
    # крынка, нож, полотенце на столе
    s += SL(Z_SRED, krynka(400, sy - 8, 1.5)
            + f'<line x1="520" y1="{sy-16:.0f}" x2="690" y2="{sy-40:.0f}"'
              f' stroke="#cfd8dc" stroke-width="16" stroke-linecap="round"/>'
            + f'<rect x="490" y="{sy-30:.0f}" width="70" height="26" rx="10"'
              f' fill="url(#derev)" {o(4)}/>'
            + f'<path d="M1180,{sy-10:.0f} L1400,{sy-10:.0f} L1384,{sy+70:.0f}'
              f' L1196,{sy+70:.0f} Z" fill="url(#rush)" {o(5)}/>'
            + f'<rect x="1196" y="{sy+30:.0f}" width="188" height="14"'
              f' fill="{TKAN}" opacity=".8"/>')
    # девушка у стола
    fx, fy, fh = 540, pol + 20, 800
    kul = A.ease(A.seg(t, 3.0, 1.0))
    dev = figura(fx, fy, fh, t, col="#6a4a62", kant="#ffd98a", platok=True,
                 ph=.3, naklon=5 - 8 * kul)
    d1, (a1x, a1y), _ = _ruka(fx, fy, fh, 1, fh * .44, 22 + 18 * kul, t,
                              "#6a4a62", "#ffd98a", .3, 5.0)
    d2, (a2x, a2y), _ = _ruka(fx, fy, fh, 1, fh * .34, 48, t,
                              "#6a4a62", "#ffd98a", .7, 4.0)
    dev += d1 + d2
    s += SL(Z_SRED, dev)
    # кулак с монетами: монеты уходят в ладонь и варежка сжимается
    if kul > .2:
        for i in range(4):
            s += SL(Z_SRED, f'<ellipse cx="{a1x+(i-2)*8:.0f}" cy="{a1y-6:.0f}"'
                            f' rx="22" ry="10" fill="url(#med)"'
                            f' opacity="{kul:.2f}" {o(3)}/>')
    s += SL(Z_SRED, "")
    s += SL(Z_SRED, ten(fx, fy + 8, 170, 26, .45))
    # низ кадра
    s += SL(Z_SRED, _polovik(640, pol + 34, 640, 106)
            + _dvorovaya_utvar(96, pol + 92, 420, t, 443,
                               ["kadka", "korzina", "vedro"])
            + _yaschiki(1600, pol + 86, t, 449, 2, .88)
            + _kot_zhivoy(1380, pol + 70, t, 1.1, "#3b342f", .4)
            + kartoshka(430, pol + 96, t, 6, 6, .95))
    # лавка с крынками, вязанки лука и короба — обжитой средний план
    s += SL(Z_SRED, _lavka_krupno(1180, pol - 8, 600, t, 140, False))
    for i in range(4):
        s += SL(Z_SRED, krynka(1250 + i * 150, pol - 150, 1.3 + (i % 2) * .2))
    # вязанки лука подняты: висели ровно на лице девушки (осмотр)
    for i in range(3):
        s += SL(Z_SRED, f'<path d="M{760+i*86:.0f},70 q{-28:.0f},{70:.0f}'
                        f' {4:.0f},{128:.0f} q{32:.0f},{18:.0f} {46:.0f},{-12:.0f}'
                        f' q{14:.0f},{-64:.0f} {-18:.0f},{-116:.0f} Z"'
                        f' fill="#c9a05a" {o(5)}/>'
                f'<line x1="{768+i*86:.0f}" y1="70" x2="{784+i*86:.0f}"'
                f' y2="34" stroke="#8a7a46" stroke-width="7"/>')
    s += SL(Z_SRED, _kadushka_kapusty(1860, pol - 6, t, .9))
    # ряд мисок унесён вправо: две из четырёх висели на лице (осмотр)
    for i in range(4):
        s += SL(Z_SRED, f'<path d="M{1180+i*150:.0f},232 q{54:.0f},{44:.0f}'
                        f' {108:.0f},0 l{-12:.0f},{-54:.0f} l{-84:.0f},0 Z"'
                        f' fill="#e7edf0" {o(5)}/>'
                f'<ellipse cx="{1234+i*150:.0f}" cy="178" rx="54" ry="16"'
                f' fill="#cfd8dc" {o(3)}/>')
    s += SL(Z_SRED, teplo(1700, pol - 480, 480, 400, .40))
    s += SL(Z_PERED, _stolb_pered(-8, 96, "#181209", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 1700, pol - 500, 6, 53, 190, .3))
    s += vinetka(.40)
    return s


def okoshko_devushki(t):
    """Окошко избы изнутри на пол-кадра, наличник, на подоконнике свеча в
    плошке и клубок. За стеклом настоящая ночная зимняя дорога под луной.
    Девушка подпирает щёку локтем и протирает стекло рукавом."""
    rnd = random.Random(409)
    pol = 1000
    s = f'<rect width="{W}" height="{H}" fill="#161d2e"/>'
    s += SL(Z_DAL, brevna(0, 30, 1040, pol - 30, 96)
            + brevna(1040, 30, 880, pol - 30, 96))
    s += SL(Z_DAL, _polka_s_utvaryu(96, 250, 520, t, 457, 4))
    s += SL(Z_DAL, _polka_s_utvaryu(100, 560, 480, t, 659, 4))
    s += SL(Z_DAL, _knizhnaya_polka(1420, 640, 440, t, 661, 1, 180))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-16:.0f}" width="{W}"'
                   f' height="{H-pol+16:.0f}" fill="#4a3c2c"/>'
            + polovicy(pol + 16) + _pol_shvy(pol + 20, 1070, 461, 6, "#3a2c1e"))
    # ПОЛАТИ за спиной: спят домашние
    s += SL(Z_DAL, _polati(1240, 180, 660, t, 5))
    # ОКОШКО: сначала нарисованный вид, потом метка, потом наличник поверх
    px, py, pw, ph_ = 310, 300, 900, 480
    put = kontur_proema(px, py, pw, ph_, "pryam")
    # СТОКА ЗДЕСЬ НЕТ: в plany.json у плана 70 столбец «сток» = «убрано»
    # (в задании porciya2.md он ещё описан — расхождение, гейт свежее текста).
    # Поэтому за стеклом только наш рисованный вид: ночная зимняя дорога.
    s += SL(Z_SRED, _vid_za_proemom(put, t, "les", 11, px + pw * .5))
    s += SL(Z_SRED, f'<clipPath id="dor4"><path d="{put}"/></clipPath>'
            + f'<g clip-path="url(#dor4)">'
            + f'<path d="M{px+pw*.18:.0f},{py+ph_:.0f} L{px+pw*.44:.0f},'
              f'{py+ph_*.52:.0f} L{px+pw*.58:.0f},{py+ph_*.52:.0f}'
              f' L{px+pw*.86:.0f},{py+ph_:.0f} Z" fill="#dbe6f2" opacity=".92"/>'
            + f'<circle cx="{px+pw*.74:.0f}" cy="{py+ph_*.24:.0f}" r="52"'
              f' fill="#f2f6fa" opacity=".95"/>'
            + f'<circle cx="{px+pw*.74:.0f}" cy="{py+ph_*.24:.0f}" r="96"'
              f' fill="#cfe4f5" opacity=".24"/></g>')
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#6a5030"'
                    f' stroke-width="34"/>'
            + f'<line x1="{px+pw*.5:.0f}" y1="{py:.0f}" x2="{px+pw*.5:.0f}"'
              f' y2="{py+ph_:.0f}" stroke="#6a5030" stroke-width="24"/>'
            + f'<line x1="{px:.0f}" y1="{py+ph_*.46:.0f}" x2="{px+pw:.0f}"'
              f' y2="{py+ph_*.46:.0f}" stroke="#6a5030" stroke-width="22"/>')
    # наличник с резьбой и подоконник
    for i in range(9):
        s += SL(Z_SRED, f'<path d="M{px-52+i*112:.0f},{py-54:.0f} l36,-48 l36,48 Z"'
                        f' fill="#7d5a3c" {o(4)}/>')
    s += SL(Z_SRED, f'<rect x="{px-60:.0f}" y="{py-58:.0f}" width="{pw+120:.0f}"'
                    f' height="36" rx="10" fill="#8a6a44" {o(6)}/>'
            + f'<rect x="{px-74:.0f}" y="{py+ph_-10:.0f}" width="{pw+148:.0f}"'
              f' height="50" rx="12" fill="url(#dosk)" {o(7)}/>')
    # свеча в плошке и клубок на подоконнике — не в самом проёме, а на борту
    s += SL(Z_SRED, f'<ellipse cx="{px+90:.0f}" cy="{py+ph_+40:.0f}" rx="58"'
                    f' ry="20" fill="url(#glina)" {o(5)}/>')
    s += SL(Z_SRED, svecha(px + 90, py + ph_ - 70, t, .1, 1.45, 110))
    s += SL(Z_SRED, f'<circle cx="{px+pw-80:.0f}" cy="{py+ph_+10:.0f}" r="48"'
                    f' fill="#8a4a52" {o(5)}/>')
    for i in range(5):
        s += SL(Z_SRED, f'<path d="M{px+pw-124:.0f},{py+ph_-14+i*16:.0f}'
                        f' q{44:.0f},{-16:.0f} {86:.0f},{6:.0f}" fill="none"'
                        f' stroke="#a35a62" stroke-width="5" opacity=".85"/>')
    # ДЕВУШКА на лавке боком к окну
    s += SL(Z_SRED, _lavka_krupno(560, pol - 6, 620, t, 150, False))
    for i in range(4):
        s += SL(Z_SRED, f'<path d="M{150+i*130:.0f},288 q{50:.0f},{40:.0f}'
                        f' {100:.0f},0 l{-10:.0f},{-50:.0f} l{-80:.0f},0 Z"'
                        f' fill="url(#glina)" {o(5)}/>'
                f'<ellipse cx="{200+i*130:.0f}" cy="238" rx="50" ry="15"'
                f' fill="#8a5a30" {o(3)}/>')
    s += SL(Z_SRED, _sapogi_novye(1420, pol + 4, 1.0, t, .4))
    fx, fy, fh = 840, pol - 150, 620
    prot = A.w(t, 1.6, .2)
    dev = figura(fx, fy, fh, t, col="#e4dcc8", kant="#ffd98a", platok=True,
                 ph=.3, profil=True, naklon=-7.0)
    d1, (s1x, s1y), _ = _ruka_so_sgibom(fx, fy, fh, -1, fh * .22, 30,
                                        fh * .24, -46, t, "#e4dcc8",
                                        "#ffd98a", .3, 3.0)
    d2, (s2x, s2y), _ = _ruka(fx, fy, fh, -1, fh * .46, -24 + 10 * prot, t,
                              "#e4dcc8", "#ffd98a", .7, 5.0)
    dev += d1 + d2
    s += SL(Z_SRED, dev)
    # рукав протирает стекло: светлый след по стеклу
    s += SL(Z_SRED, f'<path d="M{s2x-30:.0f},{s2y-40:.0f}'
                    f' q{60:.0f},{-50+20*prot:.0f} {130:.0f},{-20:.0f}"'
                    f' fill="none" stroke="#eaf4ff" stroke-width="26"'
                    f' opacity=".30" stroke-linecap="round"/>')
    s += SL(Z_SRED, _varezhka(s1x, s1y, fh, t, .3) + _varezhka(s2x, s2y, fh, t, .7))
    # крынки и короба на лавке, вязанки травы у наличника
    for i in range(4):
        s += SL(Z_SRED, krynka(620 + i * 130, pol - 160, 1.25 + (i % 2) * .2))
    for i in range(3):
        s += SL(Z_SRED, f'<path d="M{1300+i*80:.0f},240 q{-26:.0f},{78:.0f}'
                        f' {4:.0f},{146:.0f} q{30:.0f},{18:.0f} {44:.0f},{-14:.0f}'
                        f' q{14:.0f},{-72:.0f} {-18:.0f},{-132:.0f} Z"'
                        f' fill="#8a9a58" {o(5)}/>'
                f'<line x1="{1308+i*80:.0f}" y1="240" x2="{1324+i*80:.0f}"'
                f' y2="204" stroke="#6f7a44" stroke-width="7"/>')
    s += SL(Z_SRED, teplo(px + 90, py + ph_ - 110, 460, 380, .42))
    # низ кадра
    s += SL(Z_SRED, _valenki_u_dveri(400, pol + 70, 1.05, t)
            + _dvorovaya_utvar(1180, pol + 90, 420, t, 463,
                               ["kadka", "korzina", "vedro"])
            + _kot_zhivoy(700, pol + 66, t, 1.15, "#2f2a26", .5, True, True)
            + _yaschiki(96, pol + 84, t, 467, 2, .82))
    s += SL(Z_PERED, _stolb_pered(1874, 76, "#140f0c", 0, H))
    s += SL(Z_LETIT, iskra_let(t, px + 90, py + ph_ - 150, 6, 59, 170, .3))
    s += vinetka(.42)
    return s


def troyka_pod_oknom(t):
    """То же окошко снаружи, в нём силуэт девушки с ладонями на стекле. Мимо
    летит тройка с бубенцами: ямщик на облучке, в санях трое гуляк. Потом
    дорога пустеет, и только заяц перебегает её."""
    rnd = random.Random(419)
    gor = 700
    s = f'<rect width="{W}" height="{H}" fill="url(#nnoch)"/>'
    s += nebo("noch", t, True, 97)
    s += oblaka(t, 150, 4, 101, .3, "#9fb0c4", 18.0)
    s += SL(Z_DAL, f'<circle cx="1560" cy="200" r="86" fill="#f2f6fa"'
                   f' opacity=".92"/>'
            + f'<circle cx="1560" cy="200" r="150" fill="#cfe4f5" opacity=".22"/>')
    s += SL(Z_DAL, _derevnya_ryad(gor - 90, t, 61, ((1480, 300), (1820, 260))))
    s += SL(Z_DAL, goloe_derevo(1180, gor - 30, 540, t, 103, 9, "#2a2b33", True))
    # СТЕНА ИЗБЫ С ОКОШКОМ — крупный предмет
    s += SL(Z_DAL, brevna(60, 120, 1040, gor - 120, 94))
    s += SL(Z_DAL, f'<path d="M20,140 L580,-10 L1140,140 Z" fill="#3a2e24" {o(7)}/>'
            + f'<rect x="20" y="120" width="1120" height="44" rx="10"'
              f' fill="#4a3a28" {o(6)}/>')
    ox, oy, ow, oh = 330, 260, 520, 360
    s += SL(Z_SRED, f'<rect x="{ox-40:.0f}" y="{oy-40:.0f}" width="{ow+80:.0f}"'
                    f' height="{oh+80:.0f}" rx="10" fill="#6a5030" {o(7)}/>'
            + f'<rect x="{ox:.0f}" y="{oy:.0f}" width="{ow:.0f}" height="{oh:.0f}"'
              f' fill="#2b3550"/>'
            + f'<rect x="{ox:.0f}" y="{oy:.0f}" width="{ow:.0f}" height="{oh:.0f}"'
              f' fill="#ffd98a" opacity=".30"/>')
    for i in range(5):
        s += SL(Z_SRED, f'<path d="M{ox-46+i*126:.0f},{oy-46:.0f} l40,-46 l40,46 Z"'
                        f' fill="#7d5a3c" {o(4)}/>')
    s += SL(Z_SRED, f'<rect x="{ox-64:.0f}" y="{oy+oh-6:.0f}" width="{ow+128:.0f}"'
                    f' height="44" rx="10" fill="url(#dosk)" {o(6)}/>'
            + f'<line x1="{ox+ow*.5:.0f}" y1="{oy:.0f}" x2="{ox+ow*.5:.0f}"'
              f' y2="{oy+oh:.0f}" stroke="#6a5030" stroke-width="20"/>'
            + f'<line x1="{ox:.0f}" y1="{oy+oh*.48:.0f}" x2="{ox+ow:.0f}"'
              f' y2="{oy+oh*.48:.0f}" stroke="#6a5030" stroke-width="18"/>')
    # ДЕВУШКА в окне: обе ладони прижаты к стеклу, потом опускает
    opu = A.ease(A.seg(t, 2.8, 1.0))
    dvh = 420
    dev = figura(ox + ow * .5, oy + oh - 10, dvh, t, col="#3a3448",
                 kant="#ffd98a", platok=True, ph=.4, naklon=-3.0)
    v1, (g1x, g1y), _ = _ruka_mimo(ox + ow * .5, oy + oh - 10, dvh, 1, dvh * .34,
                              -36 + 70 * opu, t, "#3a3448", "#ffd98a", .4, 3.0)
    v2, (g2x, g2y), _ = _ruka_mimo(ox + ow * .5, oy + oh - 10, dvh, -1, dvh * .34,
                              -34 + 68 * opu, t, "#3a3448", "#ffd98a", .8, 3.0)
    dev += v1 + v2
    s += SL(Z_SRED, dev)
    s += SL(Z_SRED, "")
    s += SL(Z_SRED, teplo(ox + ow * .5, oy + oh * .5, 460, 360, .40))
    # ДОРОГА и снег
    s += SL(Z_SRED, f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor:.0f}"'
                    f' fill="#c2cedc"/>'
            + f'<path d="M-20,{gor+80:.0f} Q480,{gor+30:.0f} 980,{gor+96:.0f}'
              f' Q1480,{gor+160:.0f} 1940,{gor+106:.0f} L1940,1080 L-20,1080 Z"'
              f' fill="url(#sneg)" {o(0)}/>'
            + _koleya(gor + 230, 467, 2)
            + _inej(479, 58, gor + 60, 1060)
            + _pol_shvy(gor + 60, 1070, 487, 5, "#9fb0c0"))
    # ТРОЙКА летит мимо окна, потом дорога пустеет
    pr = A.seg(t, .2, 2.6)
    if pr < 1.0:
        tx = -520 + 2600 * pr
        s += SL(Z_SRED, _troyka(tx, gor + 300, t, .92, pr))
        # ямщик на облучке и трое гуляк в санях
        yh = 330
        _figury_kadra((ox + ow * .5, oy + oh - 10, 420),
                      (tx - 160, gor + 268, 330), (tx - 330, gor + 236, 310),
                      (tx - 470, gor + 250, 190), (tx - 600, gor + 240, 290))
        yam = figura(tx - 160, gor + 268, yh, t, col="#4a4e46",
                     kant="#cfe4f5", shapka=True, ph=.2, profil=True,
                     naklon=6.0)
        y1, (q1x, q1y), _ = _ruka_mimo(tx - 160, gor + 268, yh, 1, yh * .40, -14, t,
                                  "#4a4e46", "#cfe4f5", .2, 6.0)
        y2, (q2x, q2y), _ = _ruka_mimo(tx - 160, gor + 268, yh, 1, yh * .32, 4, t,
                                  "#4a4e46", "#cfe4f5", .6, 6.0)
        yam += y1 + y2
        yam += (f'<path d="M{q1x:.0f},{q1y:.0f} Q{q1x+180:.0f},{q1y-40:.0f}'
                f' {q1x+330:.0f},{q1y-120:.0f}" fill="none" stroke="#2e2620"'
                f' stroke-width="7"/>')
        yam += ""
        yam += ""
        s += SL(Z_SRED, yam)
        # трое гуляк: рост через одного, один машет шапкой, двое обнялись
        # трое гуляк: рост через одного 310 / 190 / 290, шаг рваный,
        # один в профиль, один со спины
        for i, (dx, fh2, nak, prof, dy_) in enumerate(((-330, 310, -9, False, -4),
                                                       (-470, 190, 13, True, 10),
                                                       (-600, 290, -6, False, 0))):
            gx = tx + dx
            gul = figura(gx, gor + 240 + dy_, fh2, t,
                         col=("#5a4636", "#46506a", "#6a5a46")[i],
                         kant="#cfe4f5", shapka=(i != 1), boroda=(i == 2),
                         ph=.2 + i * .3, profil=prof, naklon=nak,
                         lico=(i != 2))
            # НАРУЖНЫЕ РУКИ ТОЛЬКО У ТОГО, КТО МАШЕТ ШАПКОЙ, и его рука
            # идёт ВВЕРХ, от соседей. У двоих поющих — свои рукава фигуры:
            # объятие читается перекрытием и наклоном, а не рукой сквозь
            # корпус соседа (осмотр порции 2).
            z1x, z1y, z2x, z2y = gx, gor + 240 + dy_, gx, gor + 240 + dy_
            if i == 0:
                r1, (z1x, z1y), _ = _ruka_mimo(gx, gor + 240 + dy_, fh2, 1,
                                          fh2 * .46, -52, t,
                                          "#5a4636", "#cfe4f5", .2, 8.0)
                gul += r1
            if i == 0:
                # шапка ЛЕЖИТ ПОД варежкой: хват читается перекрытием
                gul += (f'<ellipse cx="{z1x:.0f}" cy="{z1y-16:.0f}" rx="56"'
                        f' ry="30" fill="#4a3a2c" {o(5)}/>'
                        f'<path d="M{z1x-48:.0f},{z1y-20:.0f} q48,-50 96,0 Z"'
                        f' fill="#5a4636" {o(4)}/>')
                gul += _varezhka(z1x, z1y, fh2, t, .2, "#dcd0bc")
            gul += para_izo_rta(gx + fh2 * .12, gor + 240 + dy_ - fh2 * .80, t,
                                i * .3, 1.0, .5)
            s += SL(Z_SRED, gul)
    else:
        # дорога опустела, заяц перебегает
        s += SL(Z_SRED, _zayac(620, gor + 330, t, 1.25,
                               A.seg(t, 2.8, 2.4)))
    s += SL(Z_SRED, dym(620, 110, t, 5, .26, 300, .36, "#cfd6de", 1.2))
    # низ кадра
    s += SL(Z_DAL, _zavalinka(90, gor + 120, 980, t, 150))
    s += SL(Z_SRED, (
            _polenica(1240, gor + 120, 420, 200, 67, 60)
            + _sledy(1880, 1066, 1240, 880, 7, 491, "#8fa3b4", 1.25)
            + _dvorovaya_utvar(140, gor + 300, 420, t, 499,
                               ["kadka", "vedro", "korzina"])
            + _kot_zhivoy(1680, gor + 320, t, 1.0, "#2f2a26", .3)))
    s += SL(Z_PERED, _vetka_pered(1980, 130, 740, 156, t, 31, "#241c16", 6))
    s += SL(Z_LETIT, mokryy_sneg(t, 26, 5, .55, .9))
    s += vinetka(.42)
    return s


def romashka_v_devichih_palcah(t):
    """Летнее окно с распахнутыми створками на пол-кадра, за ним настоящий
    ромашковый луг. Девушка сидит на подоконнике боком, ноги свесила в
    комнату: в левой руке ромашка, правой обрывает лепесток."""
    rnd = random.Random(421)
    pol = 1010
    s = f'<rect width="{W}" height="{H}" fill="#2e2a24"/>'
    s += SL(Z_DAL, f'<rect x="0" y="0" width="1920" height="{pol:.0f}"'
                   f' fill="#9a8a70"/>')
    for i in range(19):
        s += SL(Z_DAL, f'<rect x="{i*101:.0f}" y="0" width="54"'
                       f' height="{pol:.0f}" fill="#a89a80" opacity=".5"/>')
    s += SL(Z_DAL, f'<rect x="0" y="{pol-16:.0f}" width="{W}"'
                   f' height="{H-pol+16:.0f}" fill="#7a6a52"/>'
            + _pol_shvy(pol + 20, 1070, 503, 6, "#5a4a36"))
    # ОКНО: вид-луг, метка, створки и переплёт поверх
    px, py, pw, ph_ = 240, 180, 900, 540
    put = kontur_proema(px, py, pw, ph_, "pryam")
    lug = (f'<clipPath id="lug4"><path d="{put}"/></clipPath>'
           f'<g clip-path="url(#lug4)">'
           f'<rect x="{px:.0f}" y="{py:.0f}" width="{pw:.0f}" height="{ph_:.0f}"'
           f' fill="#9fc0d4"/>'
           f'<rect x="{px:.0f}" y="{py+ph_*.42:.0f}" width="{pw:.0f}"'
           f' height="{ph_*.58:.0f}" fill="#8fae5c"/>')
    for i in range(26):
        lx = px + rnd.uniform(10, pw - 10)
        ly = py + ph_ * .46 + rnd.uniform(0, ph_ * .52)
        rr = 14 + (ly - py - ph_ * .46) * .05
        lug += (f'<circle cx="{lx:.0f}" cy="{ly:.0f}" r="{rr:.0f}"'
                f' fill="#f8f6ee" opacity=".92"/>'
                f'<circle cx="{lx:.0f}" cy="{ly:.0f}" r="{rr*.42:.0f}"'
                f' fill="#e8b84c"/>')
    lug += "</g>"
    s += SL(Z_SRED, lug + mesto_stoka(px, py, pw, ph_, "pryam"))
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#efe8da"'
                    f' stroke-width="34"/>'
            + f'<line x1="{px+pw*.5:.0f}" y1="{py:.0f}" x2="{px+pw*.5:.0f}"'
              f' y2="{py+ph_:.0f}" stroke="#efe8da" stroke-width="22"/>'
            + f'<rect x="{px-70:.0f}" y="{py+ph_-10:.0f}" width="{pw+140:.0f}"'
              f' height="52" rx="12" fill="#e4dcc8" {o(6)}/>'
            + f'<rect x="{px-56:.0f}" y="{py-54:.0f}" width="{pw+112:.0f}"'
              f' height="40" rx="10" fill="#d8cfbd" {o(5)}/>')
    # распахнутые створки по сторонам — передний план перед проёмом
    for sgn, sx in ((-1, px), (1, px + pw)):
        s += SL(Z_SRED, f'<g transform="rotate({sgn*24:.1f} {sx:.0f} {py:.0f})">'
                        f'<rect x="{sx - (240 if sgn < 0 else 0):.0f}"'
                        f' y="{py:.0f}" width="240" height="{ph_:.0f}" rx="8"'
                        f' fill="#efe8da" {o(6)}/>'
                f'<rect x="{sx - (210 if sgn < 0 else -30):.0f}"'
                f' y="{py+30:.0f}" width="180" height="{ph_*.42:.0f}" rx="6"'
                f' fill="#cfe0ea" opacity=".5" {o(4)}/>'
                f'<rect x="{sx - (210 if sgn < 0 else -30):.0f}"'
                f' y="{py+ph_*.52:.0f}" width="180" height="{ph_*.40:.0f}" rx="6"'
                f' fill="#cfe0ea" opacity=".5" {o(4)}/></g>')
    # комната: кровать с подзорами, коврик с оленями, гитара, лампа
    s += SL(Z_SRED, _krovat(1240, pol, 640, t, 13, True, 300))
    s += SL(Z_SRED, _kovrik_s_olenyami(1300, 180, 540, 360, t))
    s += SL(Z_SRED, _gitara_na_stene(1760, 300, t, .92))
    # комод с ящиками, стул, этажерка с книгами и подушки на кровати
    s += SL(Z_SRED, f'<rect x="1180" y="620" width="520" height="280" rx="10"'
                    f' fill="url(#derev)" {o(6)}/>')
    for i in range(3):
        s += SL(Z_SRED, f'<rect x="1200" y="{644+i*86:.0f}" width="480"'
                        f' height="74" rx="7" fill="#8a6a44" {o(4)}/>'
                f'<rect x="1400" y="{672+i*86:.0f}" width="80" height="16" rx="7"'
                f' fill="url(#zhel)" {o(3)}/>')
    s += SL(Z_SRED, _podushka(1340, 720, 300, 160, t, .2, .0, .0)
            + _podushka(1560, 700, 260, 150, t, .6, .0, .0))
    s += SL(Z_SRED, _venskiy_stul(1080, pol + 4, 520, t, -2.0, False))
    s += SL(Z_SRED, _knizhnaya_polka(1740, 620, 170, t, 673, 2, 180))
    s += SL(Z_SRED, _ramki_na_stene(1200, 110, 520, t, 677, 3))
    s += SL(Z_SRED, krynka(1240, 616, 1.5) + krynka(1360, 616, 1.2))
    s += SL(Z_SRED, _kruzhka(1470, 612, 1.3, 0, "#efe3d4", 1)
            + _kruzhka(1570, 614, 1.15, 0, "#e8dcc8", -1))
    s += SL(Z_SRED, lampa(1180, 560, t, .9, True))
    s += SL(Z_SRED, _konus_sveta(1180, 600, 420, 300, 0, .38))
    # ДЕВУШКА на подоконнике боком, ноги в комнату
    fx, fy, fh = 700, py + ph_ + 40, 620
    obr = A.ease(A.seg(t, .6, 1.1))
    dev = figura(fx, fy, fh, t, col="#6a7a98", kant="#ffd98a", ph=.3,
                 profil=True, naklon=-6.0)
    d1, (r1x, r1y), _ = _ruka(fx, fy, fh, -1, fh * .40, -22, t,
                              "#6a7a98", "#ffd98a", .3, 4.0)
    d2, (r2x, r2y), _ = _ruka(fx, fy, fh, 1, fh * .34, -30 + 16 * obr, t,
                              "#6a7a98", "#ffd98a", .7, 5.0)
    dev += d1 + d2
    # коса на плече
    dev += (f'<path d="M{fx+fh*.10:.0f},{fy-fh*.76:.0f}'
            f' q{fh*.08:.0f},{fh*.16:.0f} {fh*.02:.0f},{fh*.30:.0f}"'
            f' fill="none" stroke="#8a6a3c" stroke-width="{fh*.044:.0f}"'
            f' stroke-linecap="round"/>'
            f'<path d="M{fx+fh*.12:.0f},{fy-fh*.46:.0f} l{fh*.03:.0f},{fh*.05:.0f}'
            f' l{-fh*.04:.0f},{fh*.02:.0f} Z" fill="{TKAN}" {o(2)}/>')
    s += SL(Z_SRED, dev)
    # РОМАШКА в левой руке, лепесток отрывается правой
    # цветок МЕЛЬЧЕ ГОЛОВЫ девушки (голова 180 px, ромашка 130): было
    # крупнее головы и перетягивала кадр на себя
    s += SL(Z_SRED, _romashka(r1x + 14, r1y - 26, t, .62, 8, obr, -12))
    # варежка только на той руке, что держит стебель; правая обрывает
    # лепесток рукавом без кисти — ей перекрывать нечего
    s += SL(Z_SRED, _varezhka(r1x + 8, r1y - 18, fh, t, .3))
    # оторванный лепесток падает
    if obr > .5:
        pk = A.seg(t, 1.7, 1.8)
        s += SL(Z_LETIT, f'<ellipse cx="{r1x+50+30*pk:.0f}"'
                         f' cy="{r1y-10+260*pk:.0f}" rx="22" ry="11"'
                         f' transform="rotate({40+200*pk:.0f} {r1x+70+40*pk:.0f}'
                         f' {r1y-20+260*pk:.0f})" fill="#f8f6ee"'
                         f' opacity="{1-pk*.5:.2f}" {o(3)}/>')
    s += SL(Z_SRED, ten(fx, py + ph_ + 50, 150, 22, .4))
    # низ кадра
    s += SL(Z_SRED, _polovik(520, pol + 30, 760, 110, "#8a5a52", "#c9a05a")
            + _valenki_u_dveri(300, pol + 76, .92, t)
            + _gorodskoy_hlam(1540, pol + 70, 380, t, 509,
                              ["korobka", "yaschik"])
            + _kot_zhivoy(1000, pol + 64, t, 1.15, "#423b35", .6, True, True))
    s += SL(Z_PERED, _stolb_pered(-8, 92, "#1b1612", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 1180, 600, 5, 61, 140, .2))
    s += vinetka(.34)
    return s


def babushka_podglyadyvaet_v_schelku(t):
    """Дверной проём в ту же комнату, дверь приоткрыта на ладонь. Бабушка в
    фартуке с полотенцем в левой руке прикрывает улыбку правой и заглядывает
    в щель, где внучка с ромашкой. Потом скрещивает пальцы и отходит."""
    rnd = random.Random(431)
    pol = 1000
    s = f'<rect width="{W}" height="{H}" fill="#2a2620"/>'
    s += SL(Z_DAL, f'<rect x="0" y="0" width="1920" height="{pol:.0f}"'
                   f' fill="#8a7a62"/>')
    for i in range(19):
        s += SL(Z_DAL, f'<rect x="{i*101:.0f}" y="0" width="52"'
                       f' height="{pol:.0f}" fill="#9a8a70" opacity=".5"/>')
    # рамки левее и выше: третья садилась на правый край лица бабушки
    s += SL(Z_DAL, _ramki_na_stene(40, 140, 430, t, 521, 2))
    s += SL(Z_DAL, _veshalka_s_paltom(60, 420, 1040, t, 523))
    # полка с обувью и две шляпные коробки в коридоре
    s += SL(Z_DAL, f'<rect x="80" y="900" width="760" height="26" rx="8"'
                   f' fill="url(#dosk)" {o(5)}/>')
    for i in range(5):
        bx = 150 + i * 150
        s += SL(Z_DAL, f'<path d="M{bx-66:.0f},900 q{22:.0f},{-74:.0f}'
                       f' {70:.0f},{-70:.0f} q{50:.0f},{12:.0f} {54:.0f},{70:.0f} Z"'
                       f' fill="{["#3a2e26", "#5a3a2c", "#2e3540"][i % 3]}" {o(5)}/>'
                f'<rect x="{bx-70:.0f}" y="888" width="134" height="16" rx="6"'
                f' fill="#1d1812" {o(3)}/>')
    for i in (0, 1):
        s += SL(Z_DAL, f'<ellipse cx="{200+i*230:.0f}" cy="370" rx="92" ry="32"'
                       f' fill="#c9b79c" {o(5)}/>'
                f'<rect x="{108+i*230:.0f}" y="370" width="184" height="72" rx="12"'
                f' fill="#b8a68c" {o(5)}/>')
    s += SL(Z_DAL, f'<rect x="0" y="{pol-14:.0f}" width="{W}"'
                   f' height="{H-pol+14:.0f}" fill="#6a5440"/>'
            + _pol_shvy(pol + 18, 1070, 541, 6, "#4e3e2c"))
    s += SL(Z_DAL, tusklaya_lampochka(420, 130, t, 1.15, True))
    s += SL(Z_DAL, _konus_sveta(420, 180, 560, 480, 0, .38))
    # ДВЕРНОЙ ПРОЁМ — крупный предмет; дверь приоткрыта на ладонь
    dx0, dy0, dw, dh = 900, 140, 760, 860
    s += SL(Z_SRED, f'<rect x="{dx0-50:.0f}" y="{dy0-50:.0f}" width="{dw+100:.0f}"'
                    f' height="{dh+50:.0f}" rx="10" fill="#6a5030" {o(8)}/>'
            + f'<rect x="{dx0:.0f}" y="{dy0:.0f}" width="{dw:.0f}"'
              f' height="{dh:.0f}" fill="#1b2029"/>')
    # в щели видна внучка на подоконнике с ромашкой
    sch = 190
    s += SL(Z_SRED, f'<clipPath id="schel4"><rect x="{dx0:.0f}" y="{dy0:.0f}"'
                    f' width="{sch:.0f}" height="{dh:.0f}"/></clipPath>'
            + f'<g clip-path="url(#schel4)">'
            + f'<rect x="{dx0:.0f}" y="{dy0:.0f}" width="{sch:.0f}"'
              f' height="{dh:.0f}" fill="#9fc0d4"/>'
            + f'<rect x="{dx0:.0f}" y="{dy0+360:.0f}" width="{sch:.0f}"'
              f' height="{dh-360:.0f}" fill="#a89a80"/>'
            + f'<rect x="{dx0+20:.0f}" y="{dy0+560:.0f}" width="{sch:.0f}"'
              f' height="60" rx="10" fill="#e4dcc8" {o(5)}/>'
            # внучка ВИДНА ЦЕЛИКОМ, с головой: на dy0+300 её голова уходила
            # выше щели, и в щели оставалась фигура без лица (осмотр порции 2)
            + figura(dx0 + 110, dy0 + 560, 400, t, col="#6a7a98",
                     kant="#ffd98a", ph=.4, profil=True, naklon=-6.0)
            + _romashka(dx0 + 150, dy0 + 300, t, .5, 8, .4, -10)
            + "</g>")
    # створка двери поверх, приоткрыта
    s += SL(Z_SRED, f'<g transform="translate({sch:.0f},0)">'
                    f'{dver(dx0, dy0, dw - sch, dh, .0, "url(#derev)", True, False)}'
                    f'</g>')
    s += SL(Z_SRED, f'<rect x="{dx0-50:.0f}" y="{dy0-86:.0f}" width="{dw+100:.0f}"'
                    f' height="46" rx="12" fill="#7d5a3c" {o(6)}/>')
    # БАБУШКА в коридоре у двери
    ott = A.ease(A.seg(t, 2.4, 1.2))
    # в коридоре у двери стоит ОДНА фигура: внучка видна в щели, но она за
    # дверью, в другом плане, и обходить её рукой не нужно
    _figury_kadra((700 - 120 * ott, pol + 24, 790))
    fx, fy, fh = 700 - 120 * ott, pol + 24, 790
    bab = figura(fx, fy, fh, t, col="#4a5a6a", kant="#ffd98a", platok=True,
                 ph=.5, naklon=8 - 4 * ott)
    b1, (p1x, p1y), _ = _ruka_so_sgibom(fx, fy, fh, 1, fh * .22, 22,
                                        fh * .22, -40, t, "#4a5a6a",
                                        "#ffd98a", .5, 3.0)
    b2, (p2x, p2y), _ = _ruka(fx, fy, fh, -1, fh * .42, 50, t,
                              "#4a5a6a", "#ffd98a", .9, 4.0)
    bab += b1 + b2
    bab += (f'<path d="M{fx-62:.0f},{fy-fh*.52:.0f} L{fx+62:.0f},{fy-fh*.52:.0f}'
            f' L{fx+76:.0f},{fy-fh*.08:.0f} L{fx-76:.0f},{fy-fh*.08:.0f} Z"'
            f' fill="#e8e0ca" {o(5)}/>'
            f'<path d="M{fx-76:.0f},{fy-fh*.32:.0f} q{76:.0f},{16:.0f} {152:.0f},0"'
            f' fill="none" stroke="#c4b79c" stroke-width="7"/>')
    s += SL(Z_SRED, bab)
    # полотенце в левой руке
    s += SL(Z_SRED, f'<path d="M{p2x-36:.0f},{p2y:.0f} L{p2x+36:.0f},{p2y-10:.0f}'
                    f' L{p2x+46:.0f},{p2y+180:.0f} L{p2x-28:.0f},{p2y+190:.0f} Z"'
                    f' fill="url(#rush)" {o(5)}/>'
            + f'<rect x="{p2x-30:.0f}" y="{p2y+100:.0f}" width="74" height="16"'
              f' fill="{TKAN}" opacity=".8"/>')
    # правая ладонь прикрывает улыбку; к концу — скрещённые пальцы на удачу
    s += SL(Z_SRED, _varezhka(p2x, p2y, fh, t, .9))
    if ott > .3:
        s += SL(Z_SRED, f'<g transform="rotate(-16 {p1x:.0f} {p1y:.0f})">'
                        f'<rect x="{p1x-10:.0f}" y="{p1y-66:.0f}" width="20"'
                        f' height="70" rx="10" fill="#e8d8c0" {o(4)}/>'
                f'<rect x="{p1x+6:.0f}" y="{p1y-62:.0f}" width="20" height="66"'
                f' rx="10" fill="#e8d8c0" {o(4)}/>'
                f'<path d="M{p1x-14:.0f},{p1y-44:.0f} l48,-14" fill="none"'
                f' stroke="#b89a74" stroke-width="7"/></g>')
    s += SL(Z_SRED, ten(fx, fy + 8, 176, 26, .45))
    # кошка идёт за бабушкой
    s += SL(Z_SRED, _kot_zhivoy(fx - 230, pol + 60, t, 1.2, "#423b35", .4))
    # комод коридора, зонт и сумка — вещи среднего плана
    s += SL(Z_SRED, f'<rect x="60" y="{pol-300:.0f}" width="460" height="300"'
                    f' rx="10" fill="url(#derev)" {o(6)}/>')
    for i in range(3):
        s += SL(Z_SRED, f'<rect x="{80+i*150:.0f}" y="{pol-274:.0f}" width="134"'
                        f' height="120" rx="7" fill="#8a6a44" {o(4)}/>'
                f'<rect x="{80+i*150:.0f}" y="{pol-140:.0f}" width="134"'
                f' height="110" rx="7" fill="#9c7a4c" {o(4)}/>'
                f'<rect x="{126+i*150:.0f}" y="{pol-224:.0f}" width="46"'
                f' height="14" rx="7" fill="url(#zhel)" {o(3)}/>')
    s += SL(Z_SRED, _zont_v_podstavke(640, pol - 6, t, 1.1))
    s += SL(Z_SRED, _sumka_hozyaystvennaya(790, pol - 10, t, .86, 1.0))
    s += SL(Z_SRED, _ramki_na_stene(740, 150, 180, t, 683, 1))
    # низ кадра
    s += SL(Z_SRED, _polovik(420, pol + 30, 720, 110, "#8a5a52", "#c9a05a")
            + _valenki_u_dveri(200, pol + 80, 1.0, t)
            + _gorodskoy_hlam(1680, pol + 70, 240, t, 547, ["korobka"])
            + _dvorovaya_utvar(1180, pol + 90, 300, t, 557, ["korzina"]))
    s += SL(Z_PERED, _stolb_pered(1876, 76, "#171209", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 420, 180, 5, 67, 140, .2))
    s += vinetka(.38)
    return s


def poslednyaya_gryadka_redki(t):
    """Огород в первом инее: последняя грядка, из земли торчат чёрные макушки
    редьки с ботвой. Отец обеими руками тянет за ботву огромную редьку, сын
    на корточках укладывает корзину. Рядом лопата, пугало, ворона."""
    rnd = random.Random(433)
    gor = 600
    s = f'<rect width="{W}" height="{H}" fill="url(#nrassv)"/>'
    s += nebo("rassv", t, False, 107)
    s += oblaka(t, 150, 5, 109, .44, "#e4e8f0", 15.0)
    s += SL(Z_DAL, _derevnya_ryad(gor - 70, t, 71, ((180, 300), (520, 250))))
    s += SL(Z_DAL, goloe_derevo(1700, gor - 20, 520, t, 113, 9, "#3a3b43", True))
    s += SL(Z_DAL, _zabor_dosok(820, gor - 180, 1100, 190, 73, 56))
    s += SL(Z_DAL, dym(260, gor - 290, t, 5, .26, 300, .4, "#cfd6de", 1.2))
    s += SL(Z_SRED, f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor:.0f}"'
                    f' fill="#5a4a36"/>'
            + _zemlya_faktura(gor + 40, 1050, 31, 16, "#473a2c")
            + _inej(569, 62, gor + 50, 1060)
            + _pol_shvy(gor + 40, 1070, 571, 6, "#3e3226"))
    # ГРЯДКИ РЕДЬКИ — крупный предмет кадра, одна редька выскакивает
    vyh = A.ease(A.seg(t, 1.4, 1.0))
    s += SL(Z_SRED, _gryadka_redki(60, gor + 300, 1040, t, 577, 6, 3, vyh))
    s += SL(Z_SRED, _gryadka_redki(1120, gor + 200, 760, t, 587, 4, -1, .0))
    # ПУГАЛО и ворона, которая слетает
    s += SL(Z_SRED, _pugalo(1480, gor + 190, t, 1.05))
    s += SL(Z_SRED, _vorona(1480, gor - 240, t, 1.1, .2,
                            A.ease(A.seg(t, 2.2, 1.0))))
    # лопата воткнута в грядку
    s += SL(Z_SRED, f'<line x1="300" y1="{gor+120:.0f}" x2="322"'
                    f' y2="{gor+330:.0f}" stroke="url(#derev)" stroke-width="19"'
                    f' stroke-linecap="round"/>'
            + f'<path d="M300,{gor+322:.0f} L376,{gor+338:.0f} L364,{gor+426:.0f}'
              f' L288,{gor+410:.0f} Z" fill="url(#zhel)" {o(5)}/>'
            + f'<path d="M290,{gor+120:.0f} l12,-34 l26,32 Z" fill="#5b4428" {o(3)}/>')
    # ОТЕЦ тянет редьку обеими руками, откинувшись назад
    sad = A.ease(A.seg(t, 2.4, .9))
    ox2, oy2, oh2 = 700, gor + 420 + 110 * sad, 800 - 240 * sad
    otec = figura(ox2, oy2, oh2, t, col="#46506a", kant="#cfe4f5",
                  shapka=True, boroda=True, ph=.3, naklon=-16 + 24 * sad)
    o1, (a1x, a1y), _ = _ruka(ox2, oy2, oh2, 1, oh2 * .44, -30 + 50 * sad, t,
                              "#46506a", "#cfe4f5", .3, 6.0)
    o2, (a2x, a2y), _ = _ruka(ox2, oy2, oh2, 1, oh2 * .36, -12 + 46 * sad, t,
                              "#46506a", "#cfe4f5", .7, 6.0)
    otec += o1 + o2
    s += SL(Z_SRED, otec)
    # ОГРОМНАЯ РЕДЬКА в руках: выскакивает из земли
    s += SL(Z_SRED, _redka(a1x + 70, a1y + 40 - 60 * vyh, 1.5, t, 14 - 20 * vyh,
                           .6 + .4 * vyh))
    s += SL(Z_SRED, _varezhka(a1x, a1y, oh2, t, .3, "#dcd0bc")
            + _varezhka(a2x, a2y, oh2, t, .7, "#dcd0bc"))
    s += SL(Z_SRED, para_izo_rta(ox2 + 70, oy2 - oh2 * .80, t, .3, 1.3, .55))
    # СЫН на корточках у корзины — вдвое меньше отца, в профиль
    syx, syy, syh = 1130, gor + 430, 340
    syn = figura(syx, syy, syh, t, col="#5a6a52", kant="#cfe4f5", ph=.8,
                 profil=True, naklon=12.0)
    s1, (b1x, b1y), _ = _ruka(syx, syy, syh, -1, syh * .44, 46, t,
                              "#5a6a52", "#cfe4f5", .8, 5.0)
    s2, (b2x, b2y), _ = _ruka(syx, syy, syh, -1, syh * .36, 64, t,
                              "#5a6a52", "#cfe4f5", .4, 5.0)
    syn += s1 + s2
    s += SL(Z_SRED, syn)
    # корзина с уже выдернутыми редьками
    s += SL(Z_SRED, _dvorovaya_utvar(900, gor + 440, 240, t, 593, ["korzina"]))
    for i in range(4):
        s += SL(Z_SRED, _redka(960 + i * 44, gor + 350 + (i % 2) * 20, .54, t,
                               -18 + i * 12, .2))
    s += SL(Z_SRED, _varezhka(b1x, b1y, syh, t, .8, "#dcd0bc")
            + _varezhka(b2x, b2y, syh, t, .4, "#dcd0bc"))
    s += SL(Z_SRED, para_izo_rta(syx + 50, syy - syh * .80, t, .8, .9, .45))
    # низ кадра
    s += SL(Z_SRED, _kucha_listev(400, 1058, 320, 599, 86)
            + _luzha(1660, 1030, 180, t, .3)
            + _kot_zhivoy(180, 1046, t, 1.0, "#3b342f", .2)
            + _sledy(1880, 1066, 1300, 900, 6, 601, "#33281d", 1.2)
            + _dvorovaya_utvar(1700, gor + 430, 220, t, 607, ["vedro"]))
    s += SL(Z_PERED, _vetka_pered(-70, 120, 700, 24, t, 37, "#241c16", 6))
    s += SL(Z_LETIT, mokryy_sneg(t, 18, 5, .4, .75))
    s += vinetka(.36)
    return s


def chernaya_redka_na_stole(t):
    """Кухонный стол на пол-кадра: доска, тёрка, миска, бутыль масла,
    луковица, солонка, кадушка с капустой. В окне кухни — настоящий кадр, где
    редьку трут на тёрке. Хозяйка режет, льёт масло и сыплет соль."""
    rnd = random.Random(439)
    pol = 1000
    s = f'<rect width="{W}" height="{H}" fill="#2a241c"/>'
    s += SL(Z_DAL, brevna(0, 40, 1020, 700, 96)
            + brevna(1020, 40, 900, 700, 96))
    s += SL(Z_DAL, _polka_s_utvaryu(70, 240, 580, t, 613, 5))
    s += SL(Z_DAL, _polka_s_utvaryu(80, 520, 540, t, 617, 4))
    s += SL(Z_DAL, f'<rect x="0" y="684" width="{W}" height="40" rx="8"'
                   f' fill="#4a3522" {o(5)}/>')
    s += SL(Z_DAL, f'<rect x="0" y="{pol-16:.0f}" width="{W}"'
                   f' height="{H-pol+16:.0f}" fill="#5e4a34"/>'
            + polovicy(pol + 16) + _pol_shvy(pol + 20, 1070, 619, 6, "#4a3824"))
    # НАСТОЯЩИЙ КАДР в окне над столом: вид, метка, наличник поверх
    px, py, pw, ph_ = 1020, 170, 820, 400
    put = kontur_proema(px, py, pw, ph_, "pryam")
    vid = (f'<clipPath id="ter4"><path d="{put}"/></clipPath>'
           f'<g clip-path="url(#ter4)">'
           f'<rect x="{px:.0f}" y="{py:.0f}" width="{pw:.0f}" height="{ph_:.0f}"'
           f' fill="#8a9aa8"/>'
           f'<rect x="{px:.0f}" y="{py+ph_*.56:.0f}" width="{pw:.0f}"'
           f' height="{ph_*.44:.0f}" fill="#a89a80"/>')
    for i in range(7):
        vid += (f'<ellipse cx="{px+90+i*110:.0f}" cy="{py+ph_*.70:.0f}" rx="44"'
                f' ry="16" fill="#f2efe8" opacity=".9"/>')
    vid += (f'<circle cx="{px+pw*.5:.0f}" cy="{py+ph_*.3:.0f}" r="92"'
            f' fill="#ffd98a" opacity=".2"/></g>')
    s += SL(Z_SRED, vid + mesto_stoka(px, py, pw, ph_, "pryam"))
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#6a5030"'
                    f' stroke-width="32"/>'
            + f'<rect x="{px-42:.0f}" y="{py-50:.0f}" width="{pw+84:.0f}"'
              f' height="40" rx="10" fill="#7d5a3c" {o(5)}/>'
            + f'<rect x="{px-56:.0f}" y="{py+ph_-10:.0f}" width="{pw+112:.0f}"'
              f' height="46" rx="10" fill="url(#dosk)" {o(6)}/>'
            + f'<line x1="{px+pw*.5:.0f}" y1="{py:.0f}" x2="{px+pw*.5:.0f}"'
              f' y2="{py+ph_:.0f}" stroke="#6a5030" stroke-width="22"/>')
    # СТОЛ — крупный предмет
    s += SL(Z_SRED, f'{ten(960, pol + 20, 600, 28, .5)}'
                    f'<rect x="120" y="700" width="1420" height="54" rx="12"'
                    f' fill="url(#derev)" {o(8)}/>'
            + f'<rect x="150" y="754" width="1360" height="26" rx="8"'
              f' fill="#5b4428" {o(5)}/>')
    for px2 in (220, 1380):
        s += SL(Z_SRED, f'<rect x="{px2:.0f}" y="780" width="70"'
                        f' height="{pol-780:.0f}" rx="12" fill="#5b4428" {o(6)}/>')
    # доска с ломтиками, тёрка, миска, бутыль, луковица, солонка
    s += SL(Z_SRED, f'<path d="M300,700 L720,700 L700,620 L320,620 Z"'
                    f' fill="url(#dosk)" {o(6)}/>'
            + f'<circle cx="326" cy="636" r="15" fill="none" stroke="#5b4428"'
              f' stroke-width="7"/>')
    # (редька рисуется ПОСЛЕ фигуры, ниже по сцене: корпус хозяйки
    # закрывал её на 57-81% — осмотр порции 2)
    rez = A.ease(A.seg(t, .4, 1.2))
    for i in range(5):
        if rez > i * .2:
            s += SL(Z_SRED, f'<ellipse cx="{560+i*44:.0f}" cy="{668-i*4:.0f}"'
                            f' rx="30" ry="12" fill="#efe8da" {o(4)}/>'
                    f'<ellipse cx="{560+i*44:.0f}" cy="{664-i*4:.0f}" rx="22"'
                    f' ry="8" fill="#f8f6ee" opacity=".9"/>')
    s += SL(Z_SRED, _terka(900, 700, t, 1.0, -10))
    s += SL(Z_SRED, f'<path d="M1010,700 q90,54 180,0 q-14,-74 -90,-78'
                    f' q-76,4 -90,78 Z" fill="#e7edf0" {o(6)}/>'
            + f'<ellipse cx="1100" cy="630" rx="90" ry="26" fill="#f6fbff"'
              f' opacity=".92"/>')
    lej = A.ease(A.seg(t, 2.2, 1.0)) * (1 - A.ease(A.seg(t, 3.6, .8)))
    s += SL(Z_SRED, _butyl_masla(980, 700, 1.05, t, lej, lej))
    s += SL(Z_SRED, f'<ellipse cx="800" cy="676" rx="54" ry="44"'
                    f' fill="#d8b070" {o(5)}/>'
            + f'<path d="M800,634 q10,-26 26,-32" fill="none" stroke="#8a7a46"'
              f' stroke-width="7"/>')
    for i in range(4):
        s += SL(Z_SRED, f'<path d="M{760+i*26:.0f},676 q{14:.0f},{-34:.0f}'
                        f' {6:.0f},{-40:.0f}" fill="none" stroke="#c9a05a"'
                        f' stroke-width="4" opacity=".7"/>')
    s += SL(Z_SRED, f'<path d="M1420,700 L1500,700 L1488,624 L1432,624 Z"'
                    f' fill="url(#derev)" {o(5)}/>'
            + f'<ellipse cx="1460" cy="624" rx="30" ry="11" fill="#efe8da" {o(3)}/>')
    s += SL(Z_SRED, _kadushka_kapusty(1700, pol - 6, t, 1.05))
    # ХОЗЯЙКА у стола
    fx, fy, fh = 600, pol + 24, 830
    sol = A.ease(A.seg(t, 4.2, .9))
    hoz = figura(fx, fy, fh, t, col="#4a5a6a", kant="#ffd98a", platok=True,
                 ph=.4, naklon=7.0)
    h1, (c1x, c1y), _ = _ruka(fx, fy, fh, 1, fh * .46,
                              34 - 30 * lej - 20 * sol, t,
                              "#4a5a6a", "#ffd98a", .4, 5.0)
    h2, (c2x, c2y), _ = _ruka(fx, fy, fh, 1, fh * .36, 52, t,
                              "#4a5a6a", "#ffd98a", .8, 4.0)
    hoz += h1 + h2
    hoz += (f'<path d="M{fx-64:.0f},{fy-fh*.54:.0f} L{fx+64:.0f},{fy-fh*.54:.0f}'
            f' L{fx+78:.0f},{fy-fh*.08:.0f} L{fx-78:.0f},{fy-fh*.08:.0f} Z"'
            f' fill="#e4dcc8" {o(5)}/>')
    s += SL(Z_SRED, hoz)
    # нож в правой руке и щепоть соли
    if lej < .2 and sol < .2:
        # НОЖ: широкое полотно с обухом, пята и деревянная рукоять с
        # заклёпками — раньше читался серой палкой
        s += SL(Z_SRED, f'<g transform="rotate({34 - 20 * rez:.1f} {c1x:.0f}'
                        f' {c1y:.0f})">'
                        f'<path d="M{c1x+8:.0f},{c1y-16:.0f} L{c1x+186:.0f},'
                        f'{c1y-6:.0f} L{c1x+196:.0f},{c1y+12:.0f} L{c1x+8:.0f},'
                        f'{c1y+22:.0f} Z" fill="#dce4e8" {o(5)}/>'
                f'<path d="M{c1x+14:.0f},{c1y-12:.0f} L{c1x+180:.0f},{c1y-4:.0f}"'
                f' stroke="#a8b4ba" stroke-width="6" fill="none"/>'
                f'<rect x="{c1x-72:.0f}" y="{c1y-18:.0f}" width="84" height="40"'
                f' rx="12" fill="url(#derev)" {o(5)}/>'
                f'<circle cx="{c1x-46:.0f}" cy="{c1y+2:.0f}" r="5"'
                f' fill="{ZHELEZ}"/>'
                f'<circle cx="{c1x-18:.0f}" cy="{c1y+2:.0f}" r="5"'
                f' fill="{ZHELEZ}"/></g>')
    if sol > .1:
        for i in range(7):
            k = ((t * 1.3 + i * .14) % 1.0)
            s += SL(Z_SRED, f'<circle cx="{c1x+20+i*6+10*k:.0f}"'
                            f' cy="{c1y+30+140*k:.0f}" r="4"'
                            f' fill="#f8f6ee" opacity="{.9*(1-k):.2f}"/>')
    s += SL(Z_SRED, _varezhka(c1x, c1y, fh, t, .4) + _varezhka(c2x, c2y, fh, t, .8))
    # РЕДЬКА — ГЛАВНЫЙ ПРЕДМЕТ, поверх всего и крупно: половина на доске
    # и целая на свободном правом краю стола
    s += SL(Z_SRED, _redka(1280, 646, 1.6, t, -12, .35))
    s += SL(Z_SRED, _redka(1020, 676, 1.15, t, 24, .25))
    s += SL(Z_SRED, lampa(300, 560, t, .95, True))
    s += SL(Z_SRED, _konus_sveta(300, 600, 480, 340, 0, .40))
    s += SL(Z_SRED, ten(fx, fy + 8, 176, 26, .45))
    # низ кадра
    s += SL(Z_SRED, _dvorovaya_utvar(820, pol + 90, 420, t, 631,
                                     ["kadka", "korzina", "vedro"])
            + _yaschiki(96, pol + 84, t, 641, 2, .86)
            + _kot_zhivoy(1420, pol + 70, t, 1.15, "#3b342f", .5)
            + kartoshka(600, pol + 96, t, 7, 6, 1.0))
    s += SL(Z_PERED, _stolb_pered(1874, 80, "#181209", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 300, 600, 5, 71, 150, .22))
    s += vinetka(.38)
    return s


def redka_v_zimney_kladovoy(t):
    """Полка кладовой на пол-кадра: в ряд чёрные редьки, связки лука, банка
    мёда, сушёная малина в мешочке, градусник в футляре. Мать перекладывает
    редьки из корзины, одна редька чихает и получает от соседней шарф."""
    rnd = random.Random(443)
    pol = 1010
    s = f'<rect width="{W}" height="{H}" fill="#1f1a14"/>'
    s += SL(Z_DAL, kladka(0, 0, 1060, 760, 78, "#6e6256"))
    s += SL(Z_DAL, kladka(1060, 0, 860, 760, 78, "#655c50"))
    s += SL(Z_DAL, svody(t, "#4b443b", 3))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-16:.0f}" width="{W}"'
                   f' height="{H-pol+16:.0f}" fill="#4a4036"/>'
            + _pol_shvy(pol + 20, 1070, 643, 6, "#3a3028"))
    s += SL(Z_SRED, svecha(1740, 520, t, .2, 1.6, 120))
    s += SL(Z_SRED, _konus_sveta(1740, 420, 520, 420, -10, .40))
    # ПОЛКА КЛАДОВОЙ — крупный предмет
    s += SL(Z_SRED, _kladovaya_polka(120, 560, 1400, t, 7))
    # РЕДЬКИ в ряд на полке; одна чихает, соседняя повязывает ей шарф
    chih = A.ease(A.seg(t, 1.0, .5)) * (1 - A.ease(A.seg(t, 1.8, .5)))
    shrf = A.ease(A.seg(t, 2.0, .9))
    for i in range(6):
        rx_ = 250 + i * 190
        ry_ = 540 - (14 if i % 2 else 0)
        s += SL(Z_SRED, _redka(rx_, ry_, .86, t, -14 + i * 6,
                               .2 + (.8 * chih if i == 2 else .0)))
        if i == 2:
            # облачко чиха
            for k in range(4):
                kk = ((t * .9 + k * .25) % 1.0)
                s += SL(Z_SRED, f'<circle cx="{rx_-90-50*kk:.0f}"'
                                f' cy="{ry_-30-30*kk:.0f}" r="{(16+16*kk):.0f}"'
                                f' fill="#eaf4ff"'
                                f' opacity="{.55*chih*(1-kk):.2f}"/>')
            # шарф от соседки
            if shrf > .1:
                s += SL(Z_SRED, f'<rect x="{rx_-58:.0f}" y="{ry_+34:.0f}"'
                                f' width="116" height="26" rx="10"'
                                f' fill="{TKAN}" opacity="{shrf:.2f}" {o(4)}/>'
                        f'<path d="M{rx_+40:.0f},{ry_+56:.0f} q{18:.0f},{40:.0f}'
                        f' {2:.0f},{70:.0f} l{-26:.0f},{-8:.0f}'
                        f' q{12:.0f},{-30:.0f} {-2:.0f},{-56:.0f} Z"'
                        f' fill="{TKAN}" opacity="{shrf:.2f}" {o(3)}/>')
    # МАТЬ перед полкой: левая держит корзину у бедра, правая кладёт редьку
    fx, fy, fh = 1300, pol + 30, 820
    per = A.ease(A.seg(t, .4, 1.0))
    mat = figura(fx, fy, fh, t, col="#4a5a6a", kant="#ffd98a", platok=True,
                 ph=.4, naklon=-5.0)
    m1, (a1x, a1y), _ = _ruka(fx, fy, fh, -1, fh * .46, -24 + 48 * (1 - per), t,
                              "#4a5a6a", "#ffd98a", .4, 5.0)
    m2, (a2x, a2y), _ = _ruka(fx, fy, fh, 1, fh * .36, 54, t,
                              "#4a5a6a", "#ffd98a", .8, 4.0)
    mat += m1 + m2
    s += SL(Z_SRED, mat)
    # корзина с редьками у бедра
    s += SL(Z_SRED, f'<path d="M{a2x-14:.0f},{a2y+30:.0f}'
                    f' L{a2x+180:.0f},{a2y+30:.0f} L{a2x+152:.0f},{a2y+170:.0f}'
                    f' L{a2x+14:.0f},{a2y+170:.0f} Z" fill="url(#solom)" {o(6)}/>')
    for k in range(3):
        s += SL(Z_SRED, f'<path d="M{a2x-6:.0f},{a2y+60+k*38:.0f}'
                        f' q{90:.0f},{18:.0f} {178:.0f},0" fill="none"'
                        f' stroke="#8a6a3c" stroke-width="6"/>')
    for k in range(3):
        s += SL(Z_SRED, _redka(a2x + 40 + k * 56, a2y + 36, .46, t,
                               -10 + k * 14, .2))
    # редька едет из корзины на полку
    rx2 = a2x + 80 + (560 - a2x - 80 + 240) * per
    ry2 = a2y + 20 - (a2y + 20 - 540) * per
    s += SL(Z_SRED, _redka(rx2, ry2, .78, t, 20 - 30 * per, .4))
    s += SL(Z_SRED, _varezhka(a1x, a1y, fh, t, .4) + _varezhka(a2x, a2y, fh, t, .8))
    s += SL(Z_SRED, para_izo_rta(fx - 80, fy - fh * .80, t, .4, 1.1, .45))
    s += SL(Z_SRED, ten(fx, fy + 8, 176, 26, .45))
    # низ кадра: кадки, мешки, корзины, кот
    s += SL(Z_SRED, _dvorovaya_utvar(130, pol - 4, 520, t, 647,
                                     ["kadka", "meshok", "korzina", "korob"])
            + _yaschiki(760, pol - 6, t, 653, 3, .92)
            + _kot_zhivoy(1680, pol + 50, t, 1.1, "#2f2a26", .6, True, True)
            + kartoshka(1100, pol + 60, t, 8, 6, 1.1))
    s += SL(Z_SRED, teplo(1740, 470, 480, 400, .40))
    s += SL(Z_PERED, _stolb_pered(-8, 100, "#140f0c", 0, H))
    s += SL(Z_LETIT, iskra_let(t, 1740, 470, 6, 79, 180, .3))
    s += vinetka(.42)
    return s


# ═══ из chast3.py ═══
def _repka(x, y, s_=1.0, t=0.0, ph=.0, par_=True):
    """ПАРЕНАЯ РЕПКА: жёлтый шар с поперечными поясками, срез-плечико,
    корешок-хвостик книзу, два листа-обрубка сверху и пар над ней. Шар без
    пояска и хвостика читается просто кружком (R-0047)."""
    r = 54 * s_
    s = (f'{ten(x, y + r * .86, r * .92, r * .22, .45)}'
         f'<path d="M{x-r:.0f},{y-r*.18:.0f}'
         f' q{r*.06:.0f},{-r*.86:.0f} {r*1.0:.0f},{-r*.80:.0f}'
         f' q{r*.94:.0f},{-r*.06:.0f} {r*1.0:.0f},{r*.80:.0f}'
         f' q{r*.04:.0f},{r*.92:.0f} {-r*1.0:.0f},{r*.96:.0f}'
         f' q{-r*1.04:.0f},{-r*.04:.0f} {-r*1.0:.0f},{-r*.96:.0f} Z"'
         f' fill="#e8c64e" {o(6)}/>')
    for i in range(3):
        s += (f'<path d="M{x-r*.84:.0f},{y-r*.46+i*r*.44:.0f}'
              f' q{r*.84:.0f},{r*.22:.0f} {r*1.68:.0f},0" fill="none"'
              f' stroke="#c9a331" stroke-width="{max(3, 6 * s_):.0f}" opacity=".7"/>')
    s += (f'<path d="M{x-r*.70:.0f},{y-r*.56:.0f} q{r*.42:.0f},{-r*.28:.0f}'
          f' {r*.86:.0f},{-r*.08:.0f}" fill="none" stroke="#fdf0b4"'
          f' stroke-width="{max(3, 9 * s_):.0f}" opacity=".6"/>'
          f'<path d="M{x+r*.10:.0f},{y+r*.92:.0f} q{r*.16:.0f},{r*.40:.0f}'
          f' {-r*.06:.0f},{r*.66:.0f}" fill="none" stroke="#d8c08a"'
          f' stroke-width="{max(2, 6 * s_):.0f}" stroke-linecap="round"/>')
    for i in (-1, 1):
        s += (f'<path d="M{x+i*r*.22:.0f},{y-r*.92:.0f}'
              f' q{i*r*.34:.0f},{-r*.42:.0f} {i*r*.62:.0f},{-r*.22:.0f}'
              f' q{-i*r*.22:.0f},{r*.34:.0f} {-i*r*.62:.0f},{r*.22:.0f} Z"'
              f' fill="#5c8a40" {o(4)}/>')
    if par_:
        s += par(x, y - r * 1.5, t, 3, .42, 120, .5)
    return s


def _chugunok(x, y, s_=1.0, t=0.0, vyezd=.0, repok=5):
    """ЧУГУНОК С ПАРЕНОЙ РЕПОЙ — главный предмет сцены: пузатое чёрное
    тулово с обручем по плечу, две литые ушки, отблеск огня по боку, горка
    жёлтых репок через край. `vyezd` 0..1 — насколько он выехал из устья."""
    dx = 150 * vyezd
    r = 118 * s_
    s = (f'<g transform="translate({dx:.0f},0)">'
         f'{ten(x, y + r * .30, r * 1.02, r * .24, .55)}'
         f'<path d="M{x-r*.62:.0f},{y-r*1.26:.0f}'
         f' q{-r*.56:.0f},{r*.52:.0f} {-r*.26:.0f},{r*.96:.0f}'
         f' q{r*.40:.0f},{r*.46:.0f} {r*1.76:.0f},0'
         f' q{r*.30:.0f},{-r*.44:.0f} {-r*.26:.0f},{-r*.96:.0f} Z"'
         f' fill="url(#chug)" {o(8)}/>'
         f'<rect x="{x-r*.70:.0f}" y="{y-r*1.30:.0f}" width="{r*1.40:.0f}"'
         f' height="{r*.20:.0f}" rx="{r*.09:.0f}" fill="#4a4442" {o(5)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-r*1.28:.0f}" rx="{r*.66:.0f}"'
         f' ry="{r*.16:.0f}" fill="#1f1d1c" {o(4)}/>')
    for i in (-1, 1):
        s += (f'<path d="M{x+i*r*.70:.0f},{y-r*1.18:.0f} q{i*r*.30:.0f},{r*.04:.0f}'
              f' {i*r*.24:.0f},{r*.28:.0f}" fill="none" stroke="#3a3634"'
              f' stroke-width="{max(5, 13 * s_):.0f}"/>')
    s += (f'<path d="M{x-r*.54:.0f},{y-r*.84:.0f} q{-r*.18:.0f},{r*.46:.0f}'
          f' {r*.04:.0f},{r*.76:.0f}" fill="none" stroke="#ffb45a"'
          f' stroke-width="{max(4, 12 * s_):.0f}" opacity="{.42+.28*abs(A.w(t,1.3,.2)):.2f}"/>'
          f'<path d="M{x+r*.46:.0f},{y-r*.92:.0f} q{r*.20:.0f},{r*.40:.0f}'
          f' {r*.02:.0f},{r*.70:.0f}" fill="none" stroke="#ffd98a"'
          f' stroke-width="{max(3, 8 * s_):.0f}" opacity=".35"/>')
    rnd = random.Random(301 + repok)
    for i in range(repok):
        a = -2.4 + i * (2.0 / max(1, repok - 1))
        rx_ = x + math.cos(a) * r * .50
        ry_ = y - r * 1.34 - abs(math.sin(a)) * r * .22 + rnd.uniform(-6, 6)
        s += _repka(rx_, ry_, s_ * .62, t, i * .3, i % 2 == 0)
    return s + "</g>"


def _uhvat_rogi(cx, cy, dl, ug, t, kach=1.0):
    """УХВАТ: короткий черенок (<= 340 px) и железные рога полукольцом,
    которые обхватывают тулово чугунка. Рога крупные — при мелком масштабе
    ухват читается скобой (грабли 14.11, пункт 6)."""
    a = math.radians(ug + 1.4 * kach * A.w(t, 2.4, .2))
    ex, ey = cx + dl * math.cos(a), cy + dl * math.sin(a)
    nx, ny = math.cos(a + 1.5708), math.sin(a + 1.5708)
    s = (f'<line x1="{cx:.0f}" y1="{cy:.0f}" x2="{ex:.0f}" y2="{ey:.0f}"'
         f' stroke="url(#derev)" stroke-width="20" stroke-linecap="round"/>'
         f'<line x1="{cx:.0f}" y1="{cy:.0f}" x2="{ex:.0f}" y2="{ey:.0f}"'
         f' stroke="#3a2a1a" stroke-width="5" opacity=".5"/>'
         f'<path d="M{ex-nx*86:.0f},{ey-ny*86:.0f}'
         f' Q{ex+math.cos(a)*96:.0f},{ey+math.sin(a)*96:.0f}'
         f' {ex+nx*86:.0f},{ey+ny*86:.0f}" fill="none" stroke="{ZHELEZ}"'
         f' stroke-width="19" stroke-linecap="round"/>'
         f'<circle cx="{ex:.0f}" cy="{ey:.0f}" r="13" fill="#6f767c" {o(4)}/>'
         f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="15" fill="none"'
         f' stroke="#5b4428" stroke-width="7"/>')
    return s, (ex, ey)


def _zaslonka_pechi(x, y, w_, h_, t, kach=1.0):
    """Заслонка устья, прислонённая рядом: лист с клёпками, дуга-ручка,
    нагар по низу. Покачивается на пятке, а не ездит целиком."""
    ug = 2.6 * kach * A.w(t, 2.9, .4)
    return (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
            f'{ten(x, y + 8, w_ * .52, 14, .5)}'
            f'<path d="M{x-w_*.5:.0f},{y:.0f} L{x-w_*.44:.0f},{y-h_:.0f}'
            f' Q{x:.0f},{y-h_*1.12:.0f} {x+w_*.44:.0f},{y-h_:.0f}'
            f' L{x+w_*.5:.0f},{y:.0f} Z" fill="#4e4a47" {o(7)}/>'
            f'<path d="M{x-w_*.34:.0f},{y-h_*.18:.0f} L{x-w_*.30:.0f},{y-h_*.82:.0f}'
            f' Q{x:.0f},{y-h_*.94:.0f} {x+w_*.30:.0f},{y-h_*.82:.0f}'
            f' L{x+w_*.34:.0f},{y-h_*.18:.0f} Z" fill="#5f5a56" opacity=".8"/>'
            f'<path d="M{x-w_*.22:.0f},{y-h_*.96:.0f} q{w_*.22:.0f},{-h_*.30:.0f}'
            f' {w_*.44:.0f},0" fill="none" stroke="{ZHELEZ}" stroke-width="17"/>'
            + "".join(f'<circle cx="{x-w_*.36+i*w_*.18:.0f}" cy="{y-h_*.10:.0f}"'
                      f' r="7" fill="#8f979d"/>' for i in range(5))
            + f'<path d="M{x-w_*.46:.0f},{y-h_*.08:.0f} q{w_*.46:.0f},{h_*.10:.0f}'
              f' {w_*.92:.0f},0" fill="none" stroke="#1d1a18" stroke-width="12"'
              f' opacity=".7"/></g>')


def _lozhka_derev(x, y, s_=1.0, ug=0.0, kovsh=1.0):
    """Деревянная ложка: черпак-лопатка с ободком, перехват и ручка с
    расписной насечкой. Без ободка черпак читается пятном."""
    return (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
            f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{40*s_*kovsh:.0f}"'
            f' ry="{30*s_*kovsh:.0f}" fill="url(#derev)" {o(5)}/>'
            f'<ellipse cx="{x:.0f}" cy="{y+3*s_:.0f}" rx="{28*s_*kovsh:.0f}"'
            f' ry="{20*s_*kovsh:.0f}" fill="#8a6038" opacity=".9"/>'
            f'<rect x="{x-9*s_:.0f}" y="{y+22*s_:.0f}" width="{18*s_:.0f}"'
            f' height="{120*s_:.0f}" rx="{8*s_:.0f}" fill="url(#derev)" {o(4)}/>'
            f'<circle cx="{x:.0f}" cy="{y+140*s_:.0f}" r="{12*s_:.0f}"'
            f' fill="#9c7049" {o(3)}/>'
            + "".join(f'<line x1="{x-8*s_:.0f}" y1="{y+(48+i*22)*s_:.0f}"'
                      f' x2="{x+8*s_:.0f}" y2="{y+(48+i*22)*s_:.0f}"'
                      f' stroke="{KRAS}" stroke-width="{max(2,4*s_):.0f}"'
                      f' opacity=".7"/>' for i in range(3))
            + "</g>")


def _rushnik_vyshityy(x, y, w_, h_=96, t=0.0, seed=5):
    """Длинный вышитый рушник: полотно со складками, две красные полосы
    узора (ромбы и петушиные гребешки), бахрома по концам. Узор — геометрия,
    своих букв не рисуем."""
    rnd = random.Random(seed)
    s = (f'<path d="M{x:.0f},{y:.0f} L{x+w_:.0f},{y-6:.0f} L{x+w_:.0f},{y+h_-4:.0f}'
         f' L{x:.0f},{y+h_:.0f} Z" fill="{RUSH}" {o(5)}/>')
    for p in (.26, .72):
        yy = y + h_ * p
        s += (f'<rect x="{x+10:.0f}" y="{yy:.0f}" width="{w_-20:.0f}"'
              f' height="{h_*.14:.0f}" fill="{TKAN}" opacity=".9"/>')
        for i in range(int(w_ / 76)):
            cx = x + 36 + i * 76
            s += (f'<path d="M{cx:.0f},{yy-h_*.11:.0f} l{18:.0f},{h_*.11:.0f}'
                  f' l{-18:.0f},{h_*.11:.0f} l{-18:.0f},{-h_*.11:.0f} Z"'
                  f' fill="{TKAN}" opacity=".85"/>')
    for i in range(int(w_ / 54)):
        cx = x + 20 + i * 54
        s += (f'<path d="M{cx:.0f},{y+4:.0f} q{6:.0f},{h_*.5:.0f} {-2:.0f},{h_-6:.0f}"'
              f' fill="none" stroke="#d3c3a0" stroke-width="5" opacity=".8"/>')
    for e in (x + 4, x + w_ - 4):
        for i in range(7):
            s += (f'<line x1="{e:.0f}" y1="{y+10+i*(h_-18)/7.0:.0f}"'
                  f' x2="{e+(-26 if e < x + w_ / 2 else 26):.0f}"'
                  f' y2="{y+16+i*(h_-18)/7.0+rnd.uniform(-5,5):.0f}"'
                  f' stroke="#d9cbaa" stroke-width="5"/>')
    return s


def _blyudo_pirogov(x, y, w_, t, razlom=.0, n=5, seed=7):
    """БЛЮДО РУМЯНЫХ ПИРОГОВ — главный предмет: овальное блюдо с бортом,
    пироги защипом вверх, подпалины на корочке. Верхний пирог разламывается:
    из разлома идёт пар и видна оранжевая начинка."""
    rnd = random.Random(seed)
    s = (f'{ten(x, y + 18, w_ * .54, 24, .5)}'
         f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{w_*.5:.0f}" ry="{w_*.17:.0f}"'
         f' fill="#eae2d2" {o(7)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-4:.0f}" rx="{w_*.42:.0f}"'
         f' ry="{w_*.13:.0f}" fill="#d8ccb6" opacity=".9"/>'
         f'<path d="M{x-w_*.46:.0f},{y-w_*.05:.0f} q{w_*.20:.0f},{-w_*.10:.0f}'
         f' {w_*.46:.0f},{-w_*.07:.0f}" fill="none" stroke="#fffaf0"'
         f' stroke-width="9" opacity=".55"/>')
    for i in range(n):
        px = x - w_ * .32 + i * (w_ * .64 / max(1, n - 1))
        py = y - 22 - (i % 2) * 16
        pw = w_ * .20 * rnd.uniform(.9, 1.1)
        s += (f'<path d="M{px-pw*.5:.0f},{py:.0f} q{pw*.10:.0f},{-pw*.52:.0f}'
              f' {pw*.5:.0f},{-pw*.50:.0f} q{pw*.40:.0f},{-pw*.02:.0f}'
              f' {pw*.5:.0f},{pw*.50:.0f} q{-pw*.5:.0f},{pw*.26:.0f}'
              f' {-pw*1.0:.0f},0 Z" fill="#d79b4e" {o(5)}/>'
              f'<path d="M{px-pw*.34:.0f},{py-pw*.30:.0f} q{pw*.34:.0f},{-pw*.14:.0f}'
              f' {pw*.68:.0f},0" fill="none" stroke="#b5752f" stroke-width="7"'
              f' opacity=".85"/>')
        for j in range(4):
            s += (f'<circle cx="{px-pw*.26+j*pw*.17:.0f}" cy="{py-pw*.18:.0f}"'
                  f' r="{5+rnd.random()*4:.0f}" fill="#9c5a24" opacity=".7"/>')
    # ВЕРХНИЙ ПИРОГ: разламывается на две половинки, начинка наружу
    tx, ty = x - w_ * .06, y - w_ * .30
    rz = 46 * razlom
    for sgn in (-1, 1):
        s += (f'<path d="M{tx+sgn*rz:.0f},{ty:.0f}'
              f' q{sgn*14:.0f},{-70:.0f} {sgn*86:.0f},{-62:.0f}'
              f' q{sgn*22:.0f},{34:.0f} {sgn*10:.0f},{66:.0f} Z"'
              f' fill="#dca254" {o(6)}/>'
              f'<path d="M{tx+sgn*rz:.0f},{ty-4:.0f} q{sgn*18:.0f},{-30:.0f}'
              f' {sgn*16:.0f},{-56:.0f}" fill="none" stroke="{ORA}"'
              f' stroke-width="{10+12*razlom:.0f}" opacity=".95"/>')
    if razlom > .05:
        s += (f'<ellipse cx="{tx:.0f}" cy="{ty-26:.0f}" rx="{16+30*razlom:.0f}"'
              f' ry="{10+18*razlom:.0f}" fill="{ORA}" opacity=".9"/>')
        for i in range(4):
            s += (f'<circle cx="{tx-20+i*14:.0f}" cy="{ty-24-i*4:.0f}"'
                  f' r="{6+i:.0f}" fill="#f0a93c" opacity=".85"/>')
        s += par(tx, ty - 52, t, 4, .5, 150, .5)
    return s


def _morkov_botva(x, y, s_=1.0, t=0.0, ph=.0):
    """Морковь с ботвой: конус с поперечными насечками и перистая зелень,
    которая поводит от тепла."""
    sway = 4.0 * A.w(t, 2.6, ph)
    s = (f'<path d="M{x-26*s_:.0f},{y-86*s_:.0f} L{x+26*s_:.0f},{y-86*s_:.0f}'
         f' Q{x+10*s_:.0f},{y+30*s_:.0f} {x:.0f},{y+54*s_:.0f}'
         f' Q{x-10*s_:.0f},{y+30*s_:.0f} {x-26*s_:.0f},{y-86*s_:.0f} Z"'
         f' fill="{ORA}" {o(5)}/>')
    for i in range(5):
        s += (f'<path d="M{x-22*s_+i*2:.0f},{y-(70-i*26)*s_:.0f}'
              f' q{20*s_:.0f},{7*s_:.0f} {40*s_-i*4:.0f},0" fill="none"'
              f' stroke="#b85c18" stroke-width="{max(2,4*s_):.0f}" opacity=".7"/>')
    s += f'<g transform="rotate({sway:.1f} {x:.0f} {y-86*s_:.0f})">'
    for i in range(5):
        a = math.radians(-150 + i * 30)
        ex = x + 70 * s_ * math.cos(a)
        ey = y - 86 * s_ + 70 * s_ * math.sin(a)
        s += (f'<line x1="{x:.0f}" y1="{y-86*s_:.0f}" x2="{ex:.0f}" y2="{ey:.0f}"'
              f' stroke="#4e7a3c" stroke-width="{max(3,6*s_):.0f}"/>')
        for j in range(3):
            s += (f'<ellipse cx="{x+(ex-x)*(.4+j*.26):.0f}"'
                  f' cy="{y-86*s_+(ey-(y-86*s_))*(.4+j*.26):.0f}"'
                  f' rx="{11*s_:.0f}" ry="{6*s_:.0f}" fill="#5c8a40"'
                  f' opacity=".9"/>')
    return s + "</g>"


def _lukovica(x, y, s_=1.0, t=0.0, ph=.0):
    """Луковица: золотая шелуха дольками, сухой хвостик и корешки."""
    r = 46 * s_
    s = (f'{ten(x, y + r * .80, r * .86, r * .20, .4)}'
         f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{r:.0f}" ry="{r*.88:.0f}"'
         f' fill="{ZOL}" {o(5)}/>')
    for i in (-1, 0, 1):
        s += (f'<path d="M{x+i*r*.40:.0f},{y-r*.84:.0f} q{i*r*.22:.0f},{r*.84:.0f}'
              f' {i*r*.10:.0f},{r*1.66:.0f}" fill="none" stroke="#b5803a"'
              f' stroke-width="{max(2,5*s_):.0f}" opacity=".75"/>')
    s += (f'<path d="M{x-r*.10:.0f},{y-r*.86:.0f} q{r*.14:.0f},{-r*.52:.0f}'
          f' {r*.34:.0f},{-r*.66:.0f}" fill="none" stroke="#c9b06a"'
          f' stroke-width="{max(3,8*s_):.0f}" stroke-linecap="round"/>'
          f'<ellipse cx="{x-r*.34:.0f}" cy="{y-r*.34:.0f}" rx="{r*.22:.0f}"'
          f' ry="{r*.14:.0f}" fill="#f0dca0" opacity=".5"/>')
    for i in range(4):
        s += (f'<line x1="{x-r*.22+i*r*.15:.0f}" y1="{y+r*.82:.0f}"'
              f' x2="{x-r*.30+i*r*.20:.0f}" y2="{y+r*1.10:.0f}"'
              f' stroke="#c4a870" stroke-width="{max(2,3*s_):.0f}"/>')
    return s


def _skalka(x, y, s_=1.0, ug=0.0):
    """Скалка: валик с двумя ручками и прожилиной по дереву."""
    return (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
            f'{ten(x, y + 18 * s_, 110 * s_, 12 * s_, .4)}'
            f'<rect x="{x-100*s_:.0f}" y="{y-20*s_:.0f}" width="{200*s_:.0f}"'
            f' height="{40*s_:.0f}" rx="{19*s_:.0f}" fill="url(#derev)" {o(5)}/>'
            f'<rect x="{x-146*s_:.0f}" y="{y-10*s_:.0f}" width="{48*s_:.0f}"'
            f' height="{20*s_:.0f}" rx="{10*s_:.0f}" fill="#9c7049" {o(4)}/>'
            f'<rect x="{x+98*s_:.0f}" y="{y-10*s_:.0f}" width="{48*s_:.0f}"'
            f' height="{20*s_:.0f}" rx="{10*s_:.0f}" fill="#9c7049" {o(4)}/>'
            f'<path d="M{x-84*s_:.0f},{y-8*s_:.0f} q{84*s_:.0f},{-8*s_:.0f}'
            f' {168*s_:.0f},0" fill="none" stroke="#c9a47a" stroke-width="{5*s_:.0f}"'
            f' opacity=".6"/></g>')


def _miska_nachinki(x, y, s_=1.0, t=0.0, col=ORA):
    """Глиняная миска с начинкой: борт, полоска поливы, горка начинки и
    деревянная ложка поперёк борта."""
    r = 78 * s_
    s = (f'{ten(x, y + r * .26, r * .96, r * .20, .45)}'
         f'<path d="M{x-r:.0f},{y-r*.34:.0f} q{r*.14:.0f},{r*.76:.0f}'
         f' {r*1.0:.0f},{r*.76:.0f} q{r*.86:.0f},0 {r*1.0:.0f},{-r*.76:.0f} Z"'
         f' fill="url(#glina)" {o(6)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-r*.34:.0f}" rx="{r:.0f}" ry="{r*.26:.0f}"'
         f' fill="#b08050" {o(5)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-r*.32:.0f}" rx="{r*.82:.0f}"'
         f' ry="{r*.19:.0f}" fill="{col}" opacity=".95"/>')
    rnd = random.Random(int(x) + 17)
    for i in range(7):
        s += (f'<circle cx="{x+rnd.uniform(-r*.6,r*.6):.0f}"'
              f' cy="{y-r*.40+rnd.uniform(-r*.08,r*.10):.0f}"'
              f' r="{rnd.uniform(7,13)*s_:.0f}" fill="#f0a93c" opacity=".9"/>')
    s += (f'<path d="M{x-r*.92:.0f},{y-r*.10:.0f} q{r*.92:.0f},{r*.18:.0f}'
          f' {r*1.84:.0f},0" fill="none" stroke="{KREM}" stroke-width="{8*s_:.0f}"'
          f' opacity=".7"/>')
    s += _lozhka_derev(x + r * .62, y - r * .52, s_ * .6, 118 + 4 * A.w(t, 2.2, .3))
    return s


def _muka_sypletsya(x, y, t, n=10, seed=3, R=120):
    """Мука сыплется с рук: мелкие крупинки падают и редеют книзу."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        p = ((t * .7 + i / float(n)) % 1.0)
        px = x + rnd.uniform(-40, 40) + 12 * math.sin(p * 6 + i)
        py = y + p * R
        s += (f'<circle cx="{px:.0f}" cy="{py:.0f}" r="{rnd.uniform(3,7):.0f}"'
              f' fill="#f4efe2" opacity="{1 - p:.2f}"/>')
    s += (f'<ellipse cx="{x:.0f}" cy="{y+R:.0f}" rx="{R*.5:.0f}" ry="{R*.12:.0f}"'
          f' fill="#efe8d8" opacity=".55"/>')
    return s


def _yaschik_peska(x, y, w_, h_, t, vyhod=.0, seed=9):
    """ЯЩИК С ПЕСКОМ — главный предмет погреба: дощатый короб с угловыми
    стойками и скобой, песок горкой с бороздками, из песка торчат чёрные
    макушки редьки и рыжие морковки, по краю сыплется струйка песка."""
    rnd = random.Random(seed)
    s = (f'{ten(x + w_ * .5, y + 14, w_ * .54, 22, .55)}'
         f'<path d="M{x:.0f},{y-h_:.0f} L{x+w_:.0f},{y-h_:.0f} L{x+w_-24:.0f},{y:.0f}'
         f' L{x+24:.0f},{y:.0f} Z" fill="url(#dosk)" {o(8)}/>')
    for i in range(4):
        yy = y - h_ + 26 + i * (h_ - 30) / 4.0
        s += (f'<line x1="{x+10:.0f}" y1="{yy:.0f}" x2="{x+w_-10:.0f}"'
              f' y2="{yy:.0f}" stroke="#5b4428" stroke-width="7" opacity=".8"/>')
    for bx in (x + 6, x + w_ - 36):
        s += (f'<rect x="{bx:.0f}" y="{y-h_-6:.0f}" width="30" height="{h_+8:.0f}"'
              f' rx="7" fill="#7d5636" {o(5)}/>')
    s += (f'<rect x="{x+w_*.44:.0f}" y="{y-h_*.56:.0f}" width="86" height="26"'
          f' rx="9" fill="{ZHELEZ}" {o(4)}/>')
    # ПЕСОК: горка с бороздками и ямкой, откуда вынимают редьку
    s += (f'<path d="M{x+16:.0f},{y-h_+42:.0f} Q{x+w_*.3:.0f},{y-h_+4:.0f}'
          f' {x+w_*.52:.0f},{y-h_+30:.0f} Q{x+w_*.8:.0f},{y-h_+56:.0f}'
          f' {x+w_-16:.0f},{y-h_+34:.0f} L{x+w_-16:.0f},{y-20:.0f}'
          f' L{x+16:.0f},{y-20:.0f} Z" fill="#c9a97a" {o(5)}/>')
    for i in range(6):
        yy = y - h_ + 70 + i * 24
        s += (f'<path d="M{x+30:.0f},{yy:.0f} Q{x+w_*.5:.0f},{yy-12:.0f}'
              f' {x+w_-30:.0f},{yy+6:.0f}" fill="none" stroke="#b08f62"'
              f' stroke-width="6" opacity=".6"/>')
    yam = 18 + 26 * vyhod
    s += (f'<ellipse cx="{x+w_*.36:.0f}" cy="{y-h_+44:.0f}" rx="{64+22*vyhod:.0f}"'
          f' ry="{yam:.0f}" fill="#a98a5e" opacity=".9"/>')
    for i in range(4):
        mx = x + w_ * (.56 + i * .10)
        s += _morkov_botva(mx, y - h_ + 30 - (i % 2) * 10, .58, t, i * .4)
    for i in range(3):
        bx = x + w_ * (.14 + i * .09)
        s += (f'<path d="M{bx-34:.0f},{y-h_+40:.0f} q{34:.0f},{-44:.0f}'
              f' {68:.0f},0 q{-34:.0f},{20:.0f} {-68:.0f},0 Z" fill="#2e2b2a" {o(5)}/>'
              f'<line x1="{bx:.0f}" y1="{y-h_+16:.0f}" x2="{bx+6:.0f}"'
              f' y2="{y-h_-12:.0f}" stroke="#5c8a40" stroke-width="7"/>')
    for i in range(9):
        p = ((t * .9 + i / 9.0) % 1.0)
        s += (f'<circle cx="{x+w_*.30+rnd.uniform(-26,26):.0f}"'
              f' cy="{y-h_+50+p*110:.0f}" r="{rnd.uniform(2.5,5):.0f}"'
              f' fill="#e2c898" opacity="{1-p:.2f}"/>')
    return s


def _lestnica(x, y, h_, t, stup=5, ug=-6.0):
    """Приставная лестница погреба: две тетивы и ступени на шипах, нижняя
    ступень стёрта светлее. Чуть покачивается."""
    k = .6 * A.w(t, 3.6, .3)
    s = f'<g transform="rotate({ug + k:.1f} {x:.0f} {y:.0f})">'
    for i in (-1, 1):
        s += (f'<rect x="{x+i*64-11:.0f}" y="{y-h_:.0f}" width="22"'
              f' height="{h_:.0f}" rx="8" fill="#8a6038" {o(5)}/>')
    for i in range(stup):
        yy = y - 30 - i * (h_ - 50) / max(1, stup - 1.0)
        col = "#c9a47a" if i == 0 else "url(#derev)"
        s += (f'<rect x="{x-62:.0f}" y="{yy:.0f}" width="124" height="20"'
              f' rx="7" fill="{col}" {o(4)}/>'
              f'<line x1="{x-56:.0f}" y1="{yy+16:.0f}" x2="{x+56:.0f}"'
              f' y2="{yy+16:.0f}" stroke="#5b4428" stroke-width="4" opacity=".7"/>')
    return s + "</g>"


def _fonar_ruchnoy(x, y, t, s_=1.0, kach=1.0, ph=.0):
    """Ручной фонарь-керосинка: скоба, стекло с язычком огня, донце с
    гайкой, пятно света под ним. Качается на скобе."""
    ug = 6.0 * kach * A.w(t, 2.1, ph)
    return (f'<g transform="rotate({ug:.1f} {x:.0f} {y-110*s_:.0f})">'
            f'<path d="M{x-30*s_:.0f},{y-104*s_:.0f} q{30*s_:.0f},{-46*s_:.0f}'
            f' {60*s_:.0f},0" fill="none" stroke="{ZHELEZ}"'
            f' stroke-width="{9*s_:.0f}"/>'
            f'<rect x="{x-34*s_:.0f}" y="{y-104*s_:.0f}" width="{68*s_:.0f}"'
            f' height="{18*s_:.0f}" rx="{7*s_:.0f}" fill="#6f767c" {o(4)}/>'
            f'<path d="M{x-30*s_:.0f},{y-86*s_:.0f} L{x+30*s_:.0f},{y-86*s_:.0f}'
            f' L{x+26*s_:.0f},{y-18*s_:.0f} L{x-26*s_:.0f},{y-18*s_:.0f} Z"'
            f' fill="url(#stekl)" opacity=".85" {o(4)}/>'
            f'<rect x="{x-32*s_:.0f}" y="{y-18*s_:.0f}" width="{64*s_:.0f}"'
            f' height="{22*s_:.0f}" rx="{8*s_:.0f}" fill="{ZHELEZ}" {o(4)}/>'
            f'<circle cx="{x:.0f}" cy="{y+2*s_:.0f}" r="{8*s_:.0f}"'
            f' fill="#8f979d" {o(3)}/>'
            f'{svecha(x, y - 30 * s_, t, ph, s_ * .72, 46 * s_)}'
            f'{teplo(x, y - 54 * s_, 150 * s_, 130 * s_, .45)}</g>')


def _banki_v_pogrebe(x, y, w_, t, seed=11, n=5):
    """Полка с банками закруток: стекло, цветное содержимое слоями, жестяные
    крышки, пара банок с мутным блеском и паутинка в углу."""
    rnd = random.Random(seed)
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="26" rx="7"'
         f' fill="url(#dosk)" {o(6)}/>'
         f'<rect x="{x+16:.0f}" y="{y+26:.0f}" width="26" height="54" rx="6"'
         f' fill="#5b4428" {o(4)}/>'
         f'<rect x="{x+w_-42:.0f}" y="{y+26:.0f}" width="26" height="54" rx="6"'
         f' fill="#5b4428" {o(4)}/>')
    cols = ["#9c3a2a", "#6f8c4a", "#c9a331", "#8a4a5c", "#4e7a3c"]
    for i in range(n):
        bx = x + 44 + i * (w_ - 88) / max(1, n - 1.0)
        bh = rnd.uniform(118, 158)
        bw = rnd.uniform(66, 86)
        s += (f'<rect x="{bx-bw/2:.0f}" y="{y-bh:.0f}" width="{bw:.0f}"'
              f' height="{bh:.0f}" rx="10" fill="url(#stekl)" opacity=".88" {o(5)}/>'
              f'<rect x="{bx-bw/2+7:.0f}" y="{y-bh*.70:.0f}" width="{bw-14:.0f}"'
              f' height="{bh*.64:.0f}" rx="7" fill="{cols[i % 5]}" opacity=".92"/>'
              f'<rect x="{bx-bw/2-5:.0f}" y="{y-bh-16:.0f}" width="{bw+10:.0f}"'
              f' height="20" rx="7" fill="{ZHELEZ}" {o(4)}/>'
              f'<path d="M{bx-bw*.30:.0f},{y-bh*.86:.0f} q{bw*.08:.0f},{bh*.34:.0f}'
              f' {0:.0f},{bh*.62:.0f}" fill="none" stroke="#ffffff"'
              f' stroke-width="7" opacity="{.22+.18*abs(A.w(t,2.6,i*.3)):.2f}"/>')
    s += (f'<path d="M{x+w_-30:.0f},{y-26:.0f} q{-40:.0f},{-30:.0f} {-74:.0f},{-6:.0f}"'
          f' fill="none" stroke="#cfd6de" stroke-width="3" opacity=".4"/>')
    return s


def _naves_polosatyy(x, y, w_, t, h_=120, seed=5):
    """Полосатый навес рынка: зубчатый подзор, красно-белые полосы, две
    стойки с растяжками. Колышется волной, а не целиком."""
    s = (f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_*.56:.0f}"'
         f' rx="10" fill="#efe8d8" {o(6)}/>')
    n = int(w_ / 86)
    for i in range(n):
        if i % 2 == 0:
            s += (f'<rect x="{x+i*86:.0f}" y="{y-h_:.0f}" width="86"'
                  f' height="{h_*.56:.0f}" fill="{TKAN}" opacity=".92"/>')
    for i in range(n):
        kol = 10 * math.sin(t * 1.6 + i * .7)
        s += (f'<path d="M{x+i*86:.0f},{y-h_*.44:.0f} q{43:.0f},{54+kol:.0f}'
              f' {86:.0f},0 Z" fill="{TKAN if i % 2 == 0 else "#efe8d8"}" {o(4)}/>')
    for sx in (x + 26, x + w_ - 26):
        s += (f'<rect x="{sx-10:.0f}" y="{y-h_:.0f}" width="20" height="{h_+130:.0f}"'
              f' rx="8" fill="{ZHELEZ}" {o(4)}/>')
    s += (f'<line x1="{x+30:.0f}" y1="{y-h_+10:.0f}" x2="{x+w_-30:.0f}"'
          f' y2="{y-h_+10:.0f}" stroke="#6f767c" stroke-width="7"/>')
    return s


def _cenniki_bez_cifr(x, y, n=4, t=0.0, seed=3):
    """Ценники на спицах: картонка с волнистой строкой вместо букв и цифр
    (своих букв в декорации не рисуем — ряд палочек читается надписью)."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        cx = x + i * 112
        ug = 4.0 * A.w(t, 2.8, i * .4)
        s += (f'<g transform="rotate({ug:.1f} {cx:.0f} {y:.0f})">'
              f'<line x1="{cx:.0f}" y1="{y:.0f}" x2="{cx:.0f}" y2="{y-62:.0f}"'
              f' stroke="{ZHELEZ}" stroke-width="6"/>'
              f'<rect x="{cx-40:.0f}" y="{y-116:.0f}" width="80" height="56"'
              f' rx="7" fill="#f4eedc" {o(4)}/>')
        for j in range(2):
            s += (f'<path d="M{cx-28:.0f},{y-98+j*22:.0f} q{14:.0f},{-8:.0f}'
                  f' {28:.0f},0 q{14:.0f},{8:.0f} {28:.0f},0" fill="none"'
                  f' stroke="#8a7a5c" stroke-width="5"/>')
        s += "</g>"
    return s


def _puchki_zeleni(x, y, w_, t, seed=7, n=4):
    """Пучки зелени, перевязанные нитью: перья лука и укроп веером."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        px = x + i * (w_ / max(1, n - 1.0))
        sway = 3.4 * A.w(t, 2.4, i * .5)
        s += f'<g transform="rotate({sway:.1f} {px:.0f} {y:.0f})">'
        for j in range(7):
            a = math.radians(-152 + j * 24 + rnd.uniform(-6, 6))
            dl = rnd.uniform(86, 136)
            s += (f'<path d="M{px:.0f},{y:.0f} Q{px+dl*.6*math.cos(a):.0f},'
                  f'{y+dl*.6*math.sin(a)-14:.0f} {px+dl*math.cos(a):.0f},'
                  f'{y+dl*math.sin(a):.0f}" fill="none" stroke="#4e7a3c"'
                  f' stroke-width="{rnd.uniform(6,11):.0f}" stroke-linecap="round"/>')
        s += (f'<rect x="{px-18:.0f}" y="{y-16:.0f}" width="36" height="22"'
              f' rx="8" fill="#b8a86a" {o(3)}/>'
              f'<line x1="{px-18:.0f}" y1="{y-5:.0f}" x2="{px+18:.0f}"'
              f' y2="{y-5:.0f}" stroke="#8a7a46" stroke-width="5"/></g>')
    return s


def _svekla(x, y, s_=1.0, t=0.0, ph=.0):
    """Свёкла: бордовый шар с пояском, хвостик и две ножки ботвы."""
    r = 48 * s_
    s = (f'{ten(x, y + r * .80, r * .86, r * .18, .4)}'
         f'<path d="M{x-r:.0f},{y-r*.20:.0f} q{r*.08:.0f},{-r*.82:.0f}'
         f' {r*1.0:.0f},{-r*.76:.0f} q{r*.92:.0f},{-r*.06:.0f} {r*1.0:.0f},{r*.76:.0f}'
         f' q{r*.04:.0f},{r*.92:.0f} {-r*1.0:.0f},{r*.94:.0f}'
         f' q{-r*1.04:.0f},{-r*.02:.0f} {-r*1.0:.0f},{-r*.94:.0f} Z"'
         f' fill="#7a2338" {o(5)}/>'
         f'<path d="M{x-r*.80:.0f},{y-r*.10:.0f} q{r*.80:.0f},{r*.26:.0f}'
         f' {r*1.60:.0f},0" fill="none" stroke="#5a1626" stroke-width="{6*s_:.0f}"'
         f' opacity=".7"/>'
         f'<ellipse cx="{x-r*.32:.0f}" cy="{y-r*.42:.0f}" rx="{r*.22:.0f}"'
         f' ry="{r*.12:.0f}" fill="#b05a74" opacity=".45"/>'
         f'<path d="M{x+r*.12:.0f},{y+r*.86:.0f} q{r*.16:.0f},{r*.40:.0f}'
         f' {-r*.04:.0f},{r*.62:.0f}" fill="none" stroke="#8a4a5c"'
         f' stroke-width="{max(2,5*s_):.0f}" stroke-linecap="round"/>')
    sway = 4.0 * A.w(t, 2.3, ph)
    s += f'<g transform="rotate({sway:.1f} {x:.0f} {y-r*.80:.0f})">'
    for i in (-1, 1):
        s += (f'<path d="M{x+i*r*.16:.0f},{y-r*.80:.0f}'
              f' Q{x+i*r*.56:.0f},{y-r*1.56:.0f} {x+i*r*.30:.0f},{y-r*2.00:.0f}'
              f' Q{x+i*r*.06:.0f},{y-r*1.50:.0f} {x+i*r*.16:.0f},{y-r*.80:.0f} Z"'
              f' fill="#4e5a2c" {o(4)}/>'
              f'<line x1="{x+i*r*.16:.0f}" y1="{y-r*.80:.0f}"'
              f' x2="{x+i*r*.30:.0f}" y2="{y-r*1.96:.0f}" stroke="#9c3a2a"'
              f' stroke-width="{max(2,5*s_):.0f}"/>')
    return s + "</g>"


def _kapusta(x, y, s_=1.0, t=0.0):
    """Кочан капусты: плотная голова, отогнутые верхние листья с
    прожилками, срез кочерыжки внизу."""
    r = 62 * s_
    s = (f'{ten(x, y + r * .72, r * .96, r * .20, .45)}'
         f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{r:.0f}" fill="#b8c99a" {o(6)}/>')
    for i in range(4):
        s += (f'<path d="M{x-r*.80+i*r*.18:.0f},{y-r*.70:.0f}'
              f' q{r*.28:.0f},{r*.70:.0f} {r*.04:.0f},{r*1.44:.0f}" fill="none"'
              f' stroke="#8fa36e" stroke-width="{max(3,7*s_):.0f}" opacity=".8"/>')
    for i in (-1, 1):
        sway = 3.0 * A.w(t, 2.7, .2 + (0 if i < 0 else .4))
        s += (f'<g transform="rotate({sway*i:.1f} {x:.0f} {y+r*.4:.0f})">'
              f'<path d="M{x+i*r*.56:.0f},{y+r*.30:.0f}'
              f' Q{x+i*r*1.30:.0f},{y-r*.20:.0f} {x+i*r*1.12:.0f},{y+r*.60:.0f}'
              f' Q{x+i*r*.80:.0f},{y+r*.84:.0f} {x+i*r*.56:.0f},{y+r*.30:.0f} Z"'
              f' fill="#9cb47a" {o(4)}/>'
              f'<line x1="{x+i*r*.60:.0f}" y1="{y+r*.36:.0f}"'
              f' x2="{x+i*r*1.08:.0f}" y2="{y+r*.56:.0f}" stroke="#e2ecd0"'
              f' stroke-width="{max(2,5*s_):.0f}" opacity=".8"/></g>')
    s += (f'<ellipse cx="{x:.0f}" cy="{y+r*.86:.0f}" rx="{r*.20:.0f}"'
          f' ry="{r*.10:.0f}" fill="#efe8d8" {o(3)}/>')
    return s


def _glubokaya_miska(x, y, s_=1.0, t=0.0, napoln=.0):
    """Глубокая миска под тёркой: высокий борт с поливой, в ней горка белой
    стружки редьки, которая растёт по ходу сцены."""
    r = 112 * s_
    s = (f'{ten(x, y + r * .22, r * 1.0, r * .20, .5)}'
         f'<path d="M{x-r:.0f},{y-r*.56:.0f} q{r*.10:.0f},{r*.98:.0f}'
         f' {r*1.0:.0f},{r*.98:.0f} q{r*.90:.0f},0 {r*1.0:.0f},{-r*.98:.0f} Z"'
         f' fill="#e7edf0" {o(7)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-r*.56:.0f}" rx="{r:.0f}" ry="{r*.28:.0f}"'
         f' fill="#cfd8dc" {o(5)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-r*.54:.0f}" rx="{r*.86:.0f}"'
         f' ry="{r*.22:.0f}" fill="#b9c6cc" opacity=".9"/>'
         f'<rect x="{x-r*.96:.0f}" y="{y-r*.26:.0f}" width="{r*1.92:.0f}"'
         f' height="{r*.12:.0f}" fill="{TKAN2}" opacity=".65"/>')
    rnd = random.Random(int(x) + 29)
    m = int(4 + 16 * napoln)
    for i in range(m):
        a = rnd.uniform(0, 6.28)
        rr = rnd.uniform(.1, .86)
        px = x + math.cos(a) * r * .74 * rr
        py = y - r * .52 - abs(math.sin(a)) * r * .20 * rr - napoln * 14
        s += (f'<path d="M{px-22:.0f},{py:.0f} q{22:.0f},{-9:.0f} {44:.0f},{2:.0f}"'
              f' fill="none" stroke="#f8f6ee" stroke-width="{rnd.uniform(6,11):.0f}"'
              f' stroke-linecap="round"/>')
    s += (f'<path d="M{x-r*.70:.0f},{y+r*.18:.0f} q{r*.30:.0f},{r*.22:.0f}'
          f' {r*.66:.0f},{r*.10:.0f}" fill="none" stroke="#ffffff"'
          f' stroke-width="{9*s_:.0f}" opacity=".4"/>')
    return s


def _struzhka_letit(x, y, t, n=8, seed=5, R=130):
    """Стружка редьки падает с тёрки в миску: белые завитки, часть с тёмной
    кожурой по кромке."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        p = ((t * 1.1 + i / float(n)) % 1.0)
        px = x + rnd.uniform(-34, 34) + 16 * math.sin(p * 5 + i)
        py = y + p * R
        ug = rnd.uniform(-40, 40) + p * 90
        s += (f'<g transform="rotate({ug:.0f} {px:.0f} {py:.0f})">'
              f'<path d="M{px-18:.0f},{py:.0f} q{18:.0f},{-11:.0f} {36:.0f},{2:.0f}"'
              f' fill="none" stroke="#f8f6ee" stroke-width="9"'
              f' stroke-linecap="round" opacity="{1-p*.5:.2f}"/>'
              f'<path d="M{px-16:.0f},{py+5:.0f} q{16:.0f},{-9:.0f} {32:.0f},{2:.0f}"'
              f' fill="none" stroke="#5a5450" stroke-width="3" opacity="{.7-p*.4:.2f}"/>'
              f'</g>')
    return s


def _solonka(x, y, s_=1.0, t=0.0, tryaska=.0):
    """Солонка-деревянный шалашик с крышечкой и щепоткой соли, которая
    сыплется, когда её трясут."""
    ug = 9.0 * tryaska * A.w(t, 9.0, .1)
    s = (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
         f'{ten(x, y + 6 * s_, 40 * s_, 10 * s_, .4)}'
         f'<path d="M{x-36*s_:.0f},{y:.0f} L{x+36*s_:.0f},{y:.0f}'
         f' L{x+28*s_:.0f},{y-64*s_:.0f} L{x-28*s_:.0f},{y-64*s_:.0f} Z"'
         f' fill="url(#derev)" {o(5)}/>'
         f'<path d="M{x-34*s_:.0f},{y-64*s_:.0f} L{x:.0f},{y-98*s_:.0f}'
         f' L{x+34*s_:.0f},{y-64*s_:.0f} Z" fill="#9c7049" {o(4)}/>'
         f'<circle cx="{x:.0f}" cy="{y-100*s_:.0f}" r="{8*s_:.0f}"'
         f' fill="#7d5636" {o(3)}/>'
         f'<rect x="{x-30*s_:.0f}" y="{y-40*s_:.0f}" width="{60*s_:.0f}"'
         f' height="{10*s_:.0f}" fill="#8a6038" opacity=".8"/></g>')
    if tryaska > .05:
        rnd = random.Random(31)
        for i in range(9):
            p = ((t * 1.6 + i / 9.0) % 1.0)
            s += (f'<circle cx="{x+rnd.uniform(-20,20):.0f}"'
                  f' cy="{y+10*s_+p*120:.0f}" r="{rnd.uniform(2.5,4.5):.0f}"'
                  f' fill="#ffffff" opacity="{(1-p)*tryaska:.2f}"/>')
    return s


def _blyudce(x, y, s_=1.0, sok=.0, t=0.0):
    """Блюдце с бортиком и кольцом дна; по мере сцены в нём набегает
    янтарный сок с бликом."""
    r = 96 * s_
    s = (f'{ten(x, y + r * .20, r * 1.0, r * .18, .45)}'
         f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{r:.0f}" ry="{r*.30:.0f}"'
         f' fill="#eef2f4" {o(6)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-2*s_:.0f}" rx="{r*.80:.0f}"'
         f' ry="{r*.22:.0f}" fill="#dde6ea" {o(4)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y+r*.12:.0f}" rx="{r*.44:.0f}"'
         f' ry="{r*.11:.0f}" fill="#e7edf0" opacity=".9"/>')
    if sok > .02:
        s += (f'<ellipse cx="{x:.0f}" cy="{y-1*s_:.0f}" rx="{r*(.46+.32*sok):.0f}"'
              f' ry="{r*(.13+.08*sok):.0f}" fill="#d6a63f" opacity=".95"/>'
              f'<ellipse cx="{x-r*.20:.0f}" cy="{y-r*.05:.0f}"'
              f' rx="{r*.18*sok:.0f}" ry="{r*.05*sok:.0f}" fill="#f2d78a"'
              f' opacity="{.5+.3*abs(A.w(t,2.2,.2)):.2f}"/>')
    s += (f'<path d="M{x-r*.74:.0f},{y-r*.10:.0f} q{r*.30:.0f},{-r*.16:.0f}'
          f' {r*.62:.0f},{-r*.04:.0f}" fill="none" stroke="#ffffff"'
          f' stroke-width="{8*s_:.0f}" opacity=".5"/>')
    return s


def _redka_s_yamkoy(x, y, s_=1.0, t=0.0, yamka=.0, med=.0):
    """Чёрная редька на блюдце с СРЕЗАННОЙ ВЕРХУШКОЙ-крышечкой: в тулове
    выбрана ямка, в ямку кладут мёд. Сам корень берём готовым (`_redka`),
    чтобы один предмет не рисовать дважды; здесь — срез, ямка и мёд."""
    r = 86 * s_
    s = _redka(x, y, s_, t, 0.0, .18, "#2e2b2a")
    s += (f'<ellipse cx="{x:.0f}" cy="{y-r*.86:.0f}" rx="{r*.62:.0f}"'
          f' ry="{r*.20:.0f}" fill="#4a4644" {o(5)}/>'
          f'<ellipse cx="{x:.0f}" cy="{y-r*.88:.0f}" rx="{r*.52:.0f}"'
          f' ry="{r*.15:.0f}" fill="#efe8d8" opacity=".95"/>')
    gl = r * (.10 + .34 * yamka)
    s += (f'<ellipse cx="{x:.0f}" cy="{y-r*.84:.0f}" rx="{r*(.20+.20*yamka):.0f}"'
          f' ry="{gl*.42:.0f}" fill="#2b2826" opacity=".95"/>')
    if med > .02:
        s += (f'<ellipse cx="{x:.0f}" cy="{y-r*.82:.0f}"'
              f' rx="{r*(.16+.18*yamka)*med:.0f}" ry="{gl*.34*med:.0f}"'
              f' fill="{ZOL}" opacity=".95"/>'
              f'<ellipse cx="{x-r*.08:.0f}" cy="{y-r*.84:.0f}" rx="{r*.07*med:.0f}"'
              f' ry="{r*.03*med:.0f}" fill="#f6e2a0" opacity=".8"/>')
    # СРЕЗАННАЯ ВЕРХУШКА лежит рядом крышечкой, срезом вверх
    s += (f'<g transform="rotate(-14 {x+r*1.40:.0f} {y+r*.20:.0f})">'
          f'{ten(x + r * 1.40, y + r * .38, r * .52, r * .14, .4)}'
          f'<path d="M{x+r*.94:.0f},{y+r*.20:.0f} q{r*.46:.0f},{-r*.52:.0f}'
          f' {r*.92:.0f},0 q{-r*.46:.0f},{r*.26:.0f} {-r*.92:.0f},0 Z"'
          f' fill="#2e2b2a" {o(5)}/>'
          f'<ellipse cx="{x+r*1.40:.0f}" cy="{y+r*.20:.0f}" rx="{r*.46:.0f}"'
          f' ry="{r*.12:.0f}" fill="#efe8d8" opacity=".9"/></g>')
    return s


def _banka_meda(x, y, s_=1.0, t=0.0, lozhka=True):
    """Банка мёда: стекло, густой мёд с медленной волной, жестяная крышка
    рядом, ложка с тянущейся струйкой."""
    w2, h2 = 92 * s_, 136 * s_
    s = (f'{ten(x, y + 8 * s_, w2 * .56, 12 * s_, .45)}'
         f'<rect x="{x-w2/2:.0f}" y="{y-h2:.0f}" width="{w2:.0f}" height="{h2:.0f}"'
         f' rx="12" fill="url(#stekl)" opacity=".9" {o(6)}/>'
         f'<path d="M{x-w2/2+8:.0f},{y-h2*.70:.0f}'
         f' q{w2*.24:.0f},{-10 - 6 * A.w(t, 3.0, .2):.0f} {w2*.46:.0f},0'
         f' q{w2*.24:.0f},{10:.0f} {w2*.38:.0f},{-2:.0f} L{x+w2/2-8:.0f},{y-10:.0f}'
         f' L{x-w2/2+8:.0f},{y-10:.0f} Z" fill="{ZOL}" opacity=".95"/>'
         f'<rect x="{x-w2/2-6:.0f}" y="{y-h2-18:.0f}" width="{w2+12:.0f}"'
         f' height="24" rx="9" fill="{ZHELEZ}" {o(4)}/>'
         f'<path d="M{x-w2*.28:.0f},{y-h2*.86:.0f} q{w2*.06:.0f},{h2*.30:.0f}'
         f' {0:.0f},{h2*.56:.0f}" fill="none" stroke="#ffffff" stroke-width="8"'
         f' opacity=".3"/>')
    if lozhka:
        kap = (t * .55) % 1.0
        s += (f'<g transform="rotate(26 {x+w2*.84:.0f} {y-h2*.86:.0f})">'
              f'<ellipse cx="{x+w2*.84:.0f}" cy="{y-h2*.86:.0f}" rx="{30*s_:.0f}"'
              f' ry="{20*s_:.0f}" fill="#cfd8dc" {o(4)}/>'
              f'<rect x="{x+w2*.84-7:.0f}" y="{y-h2*.86:.0f}" width="{14*s_:.0f}"'
              f' height="{96*s_:.0f}" rx="6" fill="#b9c6cc" {o(3)}/></g>'
              f'<path d="M{x+w2*.70:.0f},{y-h2*.76:.0f} q{6:.0f},{40+40*kap:.0f}'
              f' {-2:.0f},{70+50*kap:.0f}" fill="none" stroke="{ZOL}"'
              f' stroke-width="{13-5*kap:.0f}" stroke-linecap="round"/>')
    return s


def _nozh(x, y, s_=1.0, ug=0.0):
    """Нож: клинок с обушком и светлой фаской, деревянная рукоять с
    заклёпками."""
    return (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
            f'{ten(x + 40 * s_, y + 8 * s_, 90 * s_, 8 * s_, .35)}'
            f'<path d="M{x:.0f},{y:.0f} L{x+156*s_:.0f},{y-10*s_:.0f}'
            f' L{x+162*s_:.0f},{y+2*s_:.0f} L{x:.0f},{y+16*s_:.0f} Z"'
            f' fill="#c9d2d8" {o(4)}/>'
            f'<path d="M{x+6*s_:.0f},{y+2*s_:.0f} L{x+150*s_:.0f},{y-6*s_:.0f}"'
            f' fill="none" stroke="#ffffff" stroke-width="{4*s_:.0f}" opacity=".6"/>'
            f'<rect x="{x-86*s_:.0f}" y="{y-4*s_:.0f}" width="{88*s_:.0f}"'
            f' height="{26*s_:.0f}" rx="{9*s_:.0f}" fill="#7d5636" {o(4)}/>'
            f'<circle cx="{x-62*s_:.0f}" cy="{y+9*s_:.0f}" r="{4*s_:.0f}"'
            f' fill="#9aa3aa"/>'
            f'<circle cx="{x-24*s_:.0f}" cy="{y+9*s_:.0f}" r="{4*s_:.0f}"'
            f' fill="#9aa3aa"/></g>')


def _batareya_s_noskom(x, y, w_, t, nosok=True, seed=3):
    """Чугунная батарея под подоконником: секции с перехватами, вентиль,
    на ней шерстяной носок, над ней дрожит тёплый воздух."""
    n = int(w_ / 46)
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="26" rx="8"'
         f' fill="#b6bcc2" {o(5)}/>'
         f'<rect x="{x:.0f}" y="{y+150:.0f}" width="{w_:.0f}" height="26" rx="8"'
         f' fill="#b6bcc2" {o(5)}/>')
    for i in range(n):
        bx = x + 8 + i * 46
        s += (f'<rect x="{bx:.0f}" y="{y+18:.0f}" width="30" height="138" rx="13"'
              f' fill="#cfd5da" {o(4)}/>'
              f'<rect x="{bx+6:.0f}" y="{y+30:.0f}" width="9" height="112" rx="4"'
              f' fill="#eef2f4" opacity=".7"/>')
    s += (f'<circle cx="{x+w_+12:.0f}" cy="{y+22:.0f}" r="20" fill="{ZHELEZ}" {o(4)}/>'
          f'<rect x="{x+w_-4:.0f}" y="{y+16:.0f}" width="30" height="14" rx="6"'
          f' fill="#8f979d"/>')
    if nosok:
        kach = 2.4 * A.w(t, 3.2, .3)
        s += (f'<g transform="rotate({kach:.1f} {x+w_*.42:.0f} {y+10:.0f})">'
              f'<path d="M{x+w_*.30:.0f},{y-6:.0f} L{x+w_*.54:.0f},{y-6:.0f}'
              f' L{x+w_*.56:.0f},{y+96:.0f} Q{x+w_*.56:.0f},{y+128:.0f}'
              f' {x+w_*.74:.0f},{y+128:.0f} L{x+w_*.76:.0f},{y+154:.0f}'
              f' L{x+w_*.30:.0f},{y+150:.0f} Z" fill="#b8323a" {o(5)}/>'
              f'<rect x="{x+w_*.30:.0f}" y="{y-8:.0f}" width="{w_*.25:.0f}"'
              f' height="24" rx="8" fill="#efe3c8" opacity=".9"/>'
              + "".join(f'<line x1="{x+w_*.32+i*14:.0f}" y1="{y+20:.0f}"'
                        f' x2="{x+w_*.33+i*14:.0f}" y2="{y+140:.0f}"'
                        f' stroke="#9c2a32" stroke-width="4" opacity=".7"/>'
                        for i in range(6))
              + "</g>")
    s += vozduh(x + w_ * .5, y + 40, t, 420, .1)
    return s


def _mishka_plyush(x, y, s_=1.0, t=0.0, szhat=.0):
    """Плюшевый мишка: голова с круглыми ушами, мордочка со швом, лапы в
    стороны, на шее лоскут. Когда его сжимают, лапы прижимаются к тулову."""
    r = 44 * s_
    pr = 1.0 - .34 * szhat
    s = (f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{r*1.10:.0f}" ry="{r*1.26:.0f}"'
         f' fill="#a87a4a" {o(5)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y+r*.26:.0f}" rx="{r*.68:.0f}"'
         f' ry="{r*.78:.0f}" fill="#c99c68" opacity=".9"/>')
    for i in (-1, 1):
        s += (f'<ellipse cx="{x+i*r*1.26*pr:.0f}" cy="{y+r*.10:.0f}"'
              f' rx="{r*.40:.0f}" ry="{r*.26:.0f}" fill="#a87a4a" {o(4)}/>'
              f'<ellipse cx="{x+i*r*.56:.0f}" cy="{y+r*1.34:.0f}"'
              f' rx="{r*.34:.0f}" ry="{r*.42:.0f}" fill="#a87a4a" {o(4)}/>')
    s += (f'<circle cx="{x:.0f}" cy="{y-r*1.42:.0f}" r="{r*.76:.0f}"'
          f' fill="#a87a4a" {o(5)}/>')
    for i in (-1, 1):
        s += (f'<circle cx="{x+i*r*.62:.0f}" cy="{y-r*1.96:.0f}" r="{r*.26:.0f}"'
              f' fill="#8a6038" {o(4)}/>')
    s += (f'<ellipse cx="{x:.0f}" cy="{y-r*1.22:.0f}" rx="{r*.40:.0f}"'
          f' ry="{r*.30:.0f}" fill="#e2c898" opacity=".95"/>'
          f'<ellipse cx="{x:.0f}" cy="{y-r*1.26:.0f}" rx="{r*.12:.0f}"'
          f' ry="{r*.09:.0f}" fill="{K}"/>'
          f'<circle cx="{x-r*.26:.0f}" cy="{y-r*1.58:.0f}" r="{r*.09:.0f}" fill="{K}"/>'
          f'<circle cx="{x+r*.26:.0f}" cy="{y-r*1.58:.0f}" r="{r*.09:.0f}" fill="{K}"/>'
          f'<path d="M{x:.0f},{y-r*1.16:.0f} q{r*.14:.0f},{r*.16:.0f}'
          f' {r*.26:.0f},{r*.02:.0f}" fill="none" stroke="{K}"'
          f' stroke-width="{max(2,3.4*s_):.0f}"/>'
          f'<path d="M{x-r*.90:.0f},{y-r*.76:.0f} q{r*.90:.0f},{r*.26:.0f}'
          f' {r*1.80:.0f},0" fill="none" stroke="{TKAN}"'
          f' stroke-width="{max(4,11*s_):.0f}"/>')
    return s


def _tumbochka_veschi(x, y, w_, t, h_=190):
    """Тумбочка у кровати и что на ней: градусник в стакане, стакан воды с
    блеском, книжка с закладкой, пузырёк. Ящик с ручкой-скобой."""
    s = (f'{ten(x + w_ * .5, y + 8, w_ * .54, 16, .5)}'
         f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="10" fill="url(#dosk)" {o(7)}/>'
         f'<rect x="{x+12:.0f}" y="{y-h_+16:.0f}" width="{w_-24:.0f}" height="58"'
         f' rx="7" fill="#8a6038" {o(4)}/>'
         f'<rect x="{x+w_*.36:.0f}" y="{y-h_+40:.0f}" width="{w_*.28:.0f}"'
         f' height="12" rx="6" fill="{ZHELEZ}" {o(3)}/>'
         f'<rect x="{x-10:.0f}" y="{y-h_-14:.0f}" width="{w_+20:.0f}" height="18"'
         f' rx="7" fill="#9c7049" {o(5)}/>')
    gx = x + w_ * .24
    s += (f'<path d="M{gx-26:.0f},{y-h_-14:.0f} L{gx+26:.0f},{y-h_-14:.0f}'
          f' L{gx+20:.0f},{y-h_-94:.0f} L{gx-20:.0f},{y-h_-94:.0f} Z"'
          f' fill="url(#stekl)" opacity=".86" {o(4)}/>'
          f'<path d="M{gx-18:.0f},{y-h_-20:.0f} L{gx+18:.0f},{y-h_-20:.0f}'
          f' L{gx+15:.0f},{y-h_-64:.0f} L{gx-15:.0f},{y-h_-64:.0f} Z"'
          f' fill="{VODA}" opacity=".55"/>'
          f'<line x1="{gx+6:.0f}" y1="{y-h_-20:.0f}" x2="{gx+16:.0f}"'
          f' y2="{y-h_-116:.0f}" stroke="#eef2f4" stroke-width="8"/>'
          f'<circle cx="{gx+16:.0f}" cy="{y-h_-118:.0f}" r="6" fill="#d6452a"/>'
          f'<path d="M{gx-14:.0f},{y-h_-30:.0f} q{6:.0f},{-20:.0f} {2:.0f},{-34:.0f}"'
          f' fill="none" stroke="#ffffff" stroke-width="5"'
          f' opacity="{.3+.25*abs(A.w(t,2.4,.2)):.2f}"/>')
    kx = x + w_ * .70
    s += (f'<path d="M{kx-54:.0f},{y-h_-16:.0f} L{kx+54:.0f},{y-h_-16:.0f}'
          f' L{kx+54:.0f},{y-h_-44:.0f} L{kx-54:.0f},{y-h_-38:.0f} Z"'
          f' fill="#8a4a5c" {o(4)}/>'
          f'<rect x="{kx-50:.0f}" y="{y-h_-38:.0f}" width="100" height="8"'
          f' fill="#efe8d8"/>'
          f'<rect x="{kx+18:.0f}" y="{y-h_-44:.0f}" width="14" height="42"'
          f' rx="4" fill="{ZOL}" {o(3)}/>')
    s += (f'<rect x="{x+w_*.50:.0f}" y="{y-h_-62:.0f}" width="34" height="46"'
          f' rx="8" fill="#6f8c4a" opacity=".9" {o(3)}/>')
    return s


def _odeyalo_kray(x, y, w_, h_, t, scep=.0, col=TKAN2):
    """Край одеяла, в который вцепились руками: лоскутные квадраты, светлая
    подкладка отворотом и две складки, которые стягиваются при хвате."""
    rnd = random.Random(53)
    sg = 16 * scep
    s = (f'<path d="M{x:.0f},{y:.0f} Q{x+w_*.5:.0f},{y-26-sg:.0f} {x+w_:.0f},{y:.0f}'
         f' L{x+w_:.0f},{y+h_:.0f} L{x:.0f},{y+h_:.0f} Z" fill="{col}" {o(7)}/>')
    for r in range(3):
        for c in range(int(w_ / 120)):
            if (r + c) % 2:
                continue
            s += (f'<rect x="{x+10+c*120:.0f}" y="{y+30+r*110:.0f}" width="108"'
                  f' height="98" rx="8" fill="#5a7a9c" opacity=".55"/>')
    s += (f'<path d="M{x:.0f},{y:.0f} Q{x+w_*.5:.0f},{y-26-sg:.0f} {x+w_:.0f},{y:.0f}'
          f' L{x+w_:.0f},{y+34:.0f} Q{x+w_*.5:.0f},{y+8-sg:.0f} {x:.0f},{y+34:.0f} Z"'
          f' fill="{KREM}" {o(5)}/>')
    for i in range(4):
        px = x + w_ * (.18 + i * .22)
        s += (f'<path d="M{px:.0f},{y+18:.0f} q{10 + sg:.0f},{h_*.4:.0f}'
              f' {-4:.0f},{h_*.8:.0f}" fill="none" stroke="#2f4a66"'
              f' stroke-width="8" opacity=".6"/>')
    return s


def _banya_srub(x, base, w_, t, seed=7, dver=.0):
    """БАНЬКА НА ОГОРОДЕ — главный предмет: низкий сруб в пять венцов,
    двускатная крыша с тёсом и снегом, кирпичная труба с дымом, стреха с
    вениками, маленькое окошко с тёплым светом, дверь на пяте."""
    rnd = random.Random(seed)
    h_ = w_ * .74
    s = (f'{ten(x + w_ * .5, base + 12, w_ * .56, 26, .5)}'
         f'<rect x="{x:.0f}" y="{base-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' fill="url(#brev)" {o(8)}/>')
    for i in range(6):
        yy = base - h_ + 18 + i * (h_ - 20) / 6.0
        s += (f'<rect x="{x:.0f}" y="{yy:.0f}" width="{w_:.0f}" height="{(h_-20)/6.0-6:.0f}"'
              f' rx="14" fill="{BREVNO if i % 2 == 0 else BREVNO2}" {o(5)}/>'
              f'<path d="M{x+16:.0f},{yy+(h_-20)/9.0:.0f} q{w_*.44:.0f},{8:.0f}'
              f' {w_-32:.0f},0" fill="none" stroke="#a97a4e" stroke-width="5"'
              f' opacity=".55"/>')
    # крыша
    s += (f'<path d="M{x-40:.0f},{base-h_+10:.0f} L{x+w_*.5:.0f},{base-h_-170:.0f}'
          f' L{x+w_+40:.0f},{base-h_+10:.0f} Z" fill="#6b5340" {o(7)}/>'
          f'<path d="M{x-40:.0f},{base-h_+10:.0f} L{x+w_*.5:.0f},{base-h_-170:.0f}'
          f' L{x+w_*.5:.0f},{base-h_-140:.0f} L{x-10:.0f},{base-h_+4:.0f} Z"'
          f' fill="{SNEG}" opacity=".92"/>')
    for i in range(7):
        s += (f'<line x1="{x-30+i*(w_+50)/7.0:.0f}" y1="{base-h_+8:.0f}"'
              f' x2="{x+w_*.5:.0f}" y2="{base-h_-166:.0f}" stroke="#4e3c2c"'
              f' stroke-width="5" opacity=".6"/>')
    # труба с дымом
    tx = x + w_ * .70
    s += (f'<rect x="{tx:.0f}" y="{base-h_-230:.0f}" width="76" height="120"'
          f' rx="6" fill="{KAMEN}" {o(5)}/>'
          + kladka(tx, base - h_ - 230, 76, 120, 34, KAMEN)
          + f'<rect x="{tx-12:.0f}" y="{base-h_-244:.0f}" width="100" height="22"'
            f' rx="7" fill="{KAMEN2}" {o(4)}/>')
    s += dym(tx + 38, base - h_ - 252, t, 6, .30, 340, .42, "#d6dde4", 1.5)
    # окошко с тёплым светом
    ox = x + w_ * .20
    s += (f'<rect x="{ox:.0f}" y="{base-h_*.74:.0f}" width="120" height="104"'
          f' rx="8" fill="#2a1d12" {o(6)}/>'
          f'<rect x="{ox+8:.0f}" y="{base-h_*.74+8:.0f}" width="104" height="88"'
          f' fill="{SVET}" opacity="{.74+.16*abs(A.w(t,2.4,.3)):.2f}"/>'
          f'<line x1="{ox+60:.0f}" y1="{base-h_*.74:.0f}" x2="{ox+60:.0f}"'
          f' y2="{base-h_*.74+104:.0f}" stroke="#4e3c2c" stroke-width="9"/>'
          f'<rect x="{ox-14:.0f}" y="{base-h_*.74-22:.0f}" width="148" height="20"'
          f' rx="7" fill="#7d5636" {o(4)}/>')
    # веники под стрехой
    for i in range(4):
        vx = x + w_ * .40 + i * 58
        s += _venik(vx, base - h_ - 36, 150, t, "#b8a86a", "#5a4a2e", False,
                    .10, i * .3, .52, 71 + i)
    s += (f'<rect x="{x+w_*.34:.0f}" y="{base-h_-58:.0f}" width="260" height="14"'
          f' rx="6" fill="{ZHELEZ}" {o(3)}/>')
    return s


def _hvor(x, y, s_=1.0, t=0.0, ph=.0, beg=.0):
    """ХВОРЬ — серый комок с красным носом, тремя космами, кривыми ножками
    и кислой гримасой: выкатывается из бани и убегает в сугроб. Не человек и
    не лицо в горе — рисованная нежить, по образцу комка радости из порции 2,
    но своя: серая, с носом и ножками."""
    r = 38 * s_
    pryg = abs(math.sin(t * 5.0 + ph)) * 16 * s_ * (0.3 + beg)
    s = (f'<g transform="translate({beg * 240 * s_:.0f},{-pryg:.0f})">'
         f'{ten(x, y + r * .36 + pryg, r * .86, r * .18, .4)}'
         f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{r:.0f}" ry="{r*.88:.0f}"'
         f' fill="#8d939a" {o(5)}/>'
         f'<ellipse cx="{x-r*.26:.0f}" cy="{y-r*.26:.0f}" rx="{r*.26:.0f}"'
         f' ry="{r*.18:.0f}" fill="#aab1b8" opacity=".6"/>')
    for i in (-1, 0, 1):
        s += (f'<path d="M{x+i*r*.30:.0f},{y-r*.82:.0f} q{i*r*.20:.0f},{-r*.44:.0f}'
              f' {i*r*.44:.0f},{-r*.30:.0f}" fill="none" stroke="#6f767c"'
              f' stroke-width="{max(3,7*s_):.0f}" stroke-linecap="round"/>')
    for i in (-1, 1):
        s += (f'<path d="M{x+i*r*.40:.0f},{y+r*.72:.0f} q{i*r*.24:.0f},{r*.30:.0f}'
              f' {i*r*.10:.0f},{r*.52:.0f}" fill="none" stroke="#6f767c"'
              f' stroke-width="{max(4,9*s_):.0f}" stroke-linecap="round"/>'
              f'<ellipse cx="{x+i*r*.50:.0f}" cy="{y+r*1.26:.0f}" rx="{r*.20:.0f}"'
              f' ry="{r*.10:.0f}" fill="#5b6168" {o(3)}/>')
    s += (f'<ellipse cx="{x:.0f}" cy="{y+r*.06:.0f}" rx="{r*.22:.0f}"'
          f' ry="{r*.18:.0f}" fill="{KRAS}" {o(3)}/>'
          f'<circle cx="{x-r*.34:.0f}" cy="{y-r*.22:.0f}" r="{r*.12:.0f}" fill="{K}"/>'
          f'<circle cx="{x+r*.34:.0f}" cy="{y-r*.22:.0f}" r="{r*.12:.0f}" fill="{K}"/>'
          f'<path d="M{x-r*.30:.0f},{y+r*.46:.0f} q{r*.30:.0f},{-r*.20:.0f}'
          f' {r*.60:.0f},0" fill="none" stroke="{K}"'
          f' stroke-width="{max(2,4*s_):.0f}"/></g>')
    return s


def _taz_i_svertok(x, y, s_=1.0, t=0.0, ug=0.0):
    """Таз под рукой и свёрток чистого белья, перевязанный тесьмой: таз —
    жестяной с обручем и бликом, свёрток — скатка с узлом."""
    s = (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
         f'<path d="M{x-96*s_:.0f},{y-60*s_:.0f} q{10*s_:.0f},{84*s_:.0f}'
         f' {96*s_:.0f},{84*s_:.0f} q{86*s_:.0f},0 {96*s_:.0f},{-84*s_:.0f} Z"'
         f' fill="#b6bcc2" {o(6)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-60*s_:.0f}" rx="{96*s_:.0f}"'
         f' ry="{24*s_:.0f}" fill="#cfd5da" {o(5)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-58*s_:.0f}" rx="{80*s_:.0f}"'
         f' ry="{17*s_:.0f}" fill="#8f979d" opacity=".8"/>'
         f'<path d="M{x-70*s_:.0f},{y-20*s_:.0f} q{18*s_:.0f},{34*s_:.0f}'
         f' {44*s_:.0f},{44*s_:.0f}" fill="none" stroke="#eef2f4"'
         f' stroke-width="{9*s_:.0f}" opacity=".5"/></g>')
    return s


def _svertok_belya(x, y, s_=1.0, t=0.0, ug=-8.0):
    """Свёрток чистого белья: скатка полотна со складками и крест-накрест
    тесьма с узлом."""
    w2, h2 = 150 * s_, 96 * s_
    s = (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
         f'{ten(x, y + h2 * .54, w2 * .54, 12 * s_, .4)}'
         f'<rect x="{x-w2/2:.0f}" y="{y-h2/2:.0f}" width="{w2:.0f}" height="{h2:.0f}"'
         f' rx="{22*s_:.0f}" fill="{KREM}" {o(6)}/>')
    for i in range(4):
        s += (f'<path d="M{x-w2*.42+i*w2*.24:.0f},{y-h2*.44:.0f}'
              f' q{8*s_:.0f},{h2*.44:.0f} {-2*s_:.0f},{h2*.86:.0f}" fill="none"'
              f' stroke="#d6cbb0" stroke-width="{max(3,6*s_):.0f}"/>')
    s += (f'<rect x="{x-w2*.08:.0f}" y="{y-h2*.56:.0f}" width="{w2*.16:.0f}"'
          f' height="{h2*1.12:.0f}" fill="{TKAN}" opacity=".9"/>'
          f'<rect x="{x-w2*.54:.0f}" y="{y-h2*.10:.0f}" width="{w2*1.08:.0f}"'
          f' height="{h2*.16:.0f}" fill="{TKAN}" opacity=".9"/>'
          f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{13*s_:.0f}" fill="{TKAN}" {o(3)}/></g>')
    return s


def _bochka_vody(x, y, s_=1.0, t=0.0, ledok=True):
    """Бочка с водой: клёпки, два обруча, вода с ледком и отражением,
    по краю наледь."""
    w2, h2 = 150 * s_, 170 * s_
    s = (f'{ten(x, y + 10 * s_, w2 * .56, 16 * s_, .5)}'
         f'<path d="M{x-w2/2:.0f},{y-h2:.0f} q{-12*s_:.0f},{h2*.5:.0f} 0,{h2:.0f}'
         f' L{x+w2/2:.0f},{y:.0f} q{12*s_:.0f},{-h2*.5:.0f} 0,{-h2:.0f} Z"'
         f' fill="url(#derev)" {o(7)}/>')
    for i in range(6):
        s += (f'<line x1="{x-w2*.42+i*w2*.17:.0f}" y1="{y-h2+8*s_:.0f}"'
              f' x2="{x-w2*.46+i*w2*.19:.0f}" y2="{y-6*s_:.0f}" stroke="#5b4428"'
              f' stroke-width="{max(3,5*s_):.0f}" opacity=".8"/>')
    for p in (.22, .74):
        s += (f'<rect x="{x-w2*.54:.0f}" y="{y-h2+h2*p:.0f}" width="{w2*1.08:.0f}"'
              f' height="{16*s_:.0f}" rx="{6*s_:.0f}" fill="{ZHELEZ}" {o(4)}/>')
    s += (f'<ellipse cx="{x:.0f}" cy="{y-h2:.0f}" rx="{w2*.5:.0f}" ry="{w2*.17:.0f}"'
          f' fill="{VODA2}" {o(5)}/>'
          f'<ellipse cx="{x:.0f}" cy="{y-h2+4*s_:.0f}" rx="{w2*.42:.0f}"'
          f' ry="{w2*.12:.0f}" fill="{VODA}" opacity=".9"/>'
          f'<ellipse cx="{x-w2*.14:.0f}" cy="{y-h2:.0f}" rx="{w2*.16:.0f}"'
          f' ry="{w2*.05:.0f}" fill="#9fc4d8"'
          f' opacity="{.4+.3*abs(A.w(t,2.6,.2)):.2f}"/>')
    if ledok:
        s += (f'<path d="M{x-w2*.40:.0f},{y-h2-2*s_:.0f} q{w2*.20:.0f},{-10*s_:.0f}'
              f' {w2*.40:.0f},{2*s_:.0f} q{w2*.20:.0f},{8*s_:.0f} {w2*.38:.0f},{-4*s_:.0f}"'
              f' fill="none" stroke="{LED}" stroke-width="{10*s_:.0f}" opacity=".8"/>')
    return s


def _kovsh_na_gvozde(x, y, s_=1.0, t=0.0, ph=.0):
    """Ковш на гвозде: долблёный черпак с ручкой-уткой, качается на гвозде."""
    ug = 5.0 * A.w(t, 2.5, ph)
    return (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
            f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{6*s_:.0f}" fill="{ZHELEZ}"/>'
            f'<path d="M{x:.0f},{y:.0f} q{18*s_:.0f},{38*s_:.0f} {8*s_:.0f},{66*s_:.0f}"'
            f' fill="none" stroke="url(#derev)" stroke-width="{14*s_:.0f}"/>'
            f'<path d="M{x-54*s_:.0f},{y+66*s_:.0f} q{10*s_:.0f},{62*s_:.0f}'
            f' {62*s_:.0f},{62*s_:.0f} q{52*s_:.0f},0 {62*s_:.0f},{-62*s_:.0f} Z"'
            f' fill="url(#derev)" {o(6)}/>'
            f'<ellipse cx="{x+8*s_:.0f}" cy="{y+66*s_:.0f}" rx="{62*s_:.0f}"'
            f' ry="{17*s_:.0f}" fill="#8a6038" {o(4)}/>'
            f'<path d="M{x-28*s_:.0f},{y+96*s_:.0f} q{30*s_:.0f},{18*s_:.0f}'
            f' {62*s_:.0f},{-4*s_:.0f}" fill="none" stroke="#c9a47a"'
            f' stroke-width="{6*s_:.0f}" opacity=".6"/></g>')


# ── ДЕКОРАЦИИ ──────────────────────────────────────────────────────────────

def parenaya_repa_iz_pechi(t):
    """Устье печи и шесток крупно: хозяйка ухватом вынимает на шесток
    чугунок с пареной репой, малыш на лавке держится за печь и тянется к
    репке, дуя на пальцы. Рядом заслонка, деревянная ложка, печная утварь."""
    rnd = random.Random(331)
    pol = 1010
    s = f'<rect width="{W}" height="{H}" fill="#241a12"/>'
    # задник: бревенчатая стена справа, где стоит хозяйка, и полка с утварью
    s += SL(Z_DAL, brevna(1180, 40, 740, pol - 40, 96))
    s += SL(Z_DAL, _polka_s_utvaryu(1250, 250, 580, t, 331, 5))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-20:.0f}" width="{W}" height="34"'
                   f' fill="#3b2a1a" opacity=".9"/>' + polovicy(pol + 14)
            + _pol_shvy(pol + 18, 1074, 333, 6, "#4a3824"))
    # ПЕЧЬ слева и в центре: массив, кладка, устье рамкой, огонь в глубине
    s += SL(Z_SRED, pech(-60, 20, 1240, 880, t, True, True, False))
    s += SL(Z_SRED, kladka(20, 60, 1060, 340, 76, PECH2))
    put = kontur_proema(430, 470, 620, 400, "ustie")
    s += SL(Z_SRED, f'<path d="{put}" fill="#190c05"/>'
            + ogon(740, 820, t, 1.5, .2, 8) + ugli(560, 846, 420, t, 9, 2)
            + iskra_let(t, 740, 790, 9, 4, 240, .6)
            + f'<path d="{put}" fill="none" stroke="#2a1a0e" stroke-width="10"/>')
    s += SL(Z_SRED, kirpich_ustya(430, 470, 620, 400, t, True))
    # ШЕСТОК — полка перед устьем, на неё и выезжает чугунок
    s += SL(Z_SRED, f'{ten(740, 902, 330, 22, .5)}'
                    f'<rect x="360" y="864" width="770" height="40" rx="10"'
                    f' fill="{PECH2}" {o(7)}/>'
            + f'<rect x="388" y="904" width="714" height="22" rx="8"'
              f' fill="#c2b393" {o(4)}/>'
            + kladka(360, 926, 770, 84, 42, PECH2))
    # ГЛАВНЫЙ ПРЕДМЕТ: чугунок с репой выезжает из устья на шесток
    vyezd = A.ease(A.seg(t, .35, 1.5))
    s += SL(Z_SRED, dym(700, 700, t, 4, .22, 220, .26, "#d6dde4", 1.1))
    s += SL(Z_SRED, _chugunok(690, 862, 1.0, t, vyezd, 5))
    # заслонка у края устья и деревянная ложка на шестке
    s += SL(Z_SRED, _zaslonka_pechi(1180, 900, 230, 300, t, 1.0))
    s += SL(Z_SRED, _lozhka_derev(980, 846, 1.1, 104))
    # ДВЕ ФИГУРЫ: реестр объявляется до первой руки
    hx, hy, hh = 1370, pol, 730
    mx, my, mh = 330, 872, 420
    _figury_kadra((hx, hy, hh), (mx, my, mh))
    tyan = A.ease(A.seg(t, .4, 1.1))
    duet = A.ease(A.seg(t, 1.8, .9))
    # хозяйка: ОБЕ руки на черенке ухвата, обе наружу влево
    hoz = figura(hx, hy, hh, t, col="#54505e", kant="#ffd98a", platok=True,
                 ph=.3, naklon=3.0)
    h1, (u1x, u1y), _ = _ruka_mimo(hx, hy, hh, -1, hh * .44, 16 + 10 * vyezd, t,
                                   "#54505e", "#ffd98a", .2, 5.0)
    h2, (u2x, u2y), _ = _ruka_sgib_mimo(hx, hy, hh, -1, hh * .26, 34,
                                        hh * .24, 20 + 8 * vyezd, t,
                                        "#54505e", "#ffd98a", .6, 4.0)
    hoz += h1 + h2
    # малыш на лавке: левая держится за печь, правая тянется к репке
    mal = figura(mx, my, mh, t, col="#b8a86a", kant="#ffd98a", ph=.7,
                 naklon=5.0)
    m1, (p1x, p1y), _ = _ruka_mimo(mx, my, mh, -1, mh * .46, 10, t,
                                   "#b8a86a", "#ffd98a", .1, 4.0)
    m2, (p2x, p2y), _ = _ruka_mimo(mx, my, mh, 1, mh * .50, 4 - 26 * tyan, t,
                                   "#b8a86a", "#ffd98a", .5, 7.0)
    mal += m1 + m2
    s += SL(Z_SRED, _lavka_krupno(340, my + 4, 420, t, 150, False))
    s += SL(Z_SRED, hoz)
    s += SL(Z_SRED, mal)
    # УХВАТ: черенок приходит ровно в кисти хозяйки, рога обхватывают чугунок
    uh, (rx_, ry_) = _uhvat_rogi(min(u1x, u2x) + 24, (u1y + u2y) * .5,
                                 250 - 30 * vyezd, 182, t, 1.0)
    s += SL(Z_SRED, uh)
    # варежки ПОВЕРХ черенка — хват читается перекрытием, а не соседством
    s += SL(Z_SRED, _varezhka(u1x, u1y + 2, hh, t, .2)
            + _varezhka(u2x, u2y + 2, hh, t, .5))
    # малыш дует на пальцы: пар у его правой кисти, варежки нет (нечего брать)
    s += SL(Z_SRED, par(p2x + 26, p2y - 10, t, 3, .40 + .3 * duet, 90, .7))
    s += SL(Z_SRED, _repka(p2x + 92, 846, .64, t, .4, True))
    # нижняя треть: вещи, а не пустой пол
    s += SL(Z_SRED, _ugol_pechnoy_utvari(1300, pol + 10, t, 3))
    s += SL(Z_SRED, _polenica(60, pol + 70, 300, 170, 337, 25)
            + _dvorovaya_utvar(620, pol + 72, 320, t, 339, ["kadka", "vedro"])
            + kartoshka(1080, pol + 60, t, 7, 341, 1.0)
            + _polovik(1420, pol + 40, 440, 110)
            + _valenki_u_dveri(1740, pol + 30, 1.05, t))
    s += SL(Z_SRED, _kot_zhivoy(1010, pol + 56, t, 1.1, "#38332e", .3))
    s += SL(Z_SRED, teplo(740, 800, 560, 420, .42))
    s += SL(Z_PERED, _stolb_pered(1890, 120, "#1a120c", 0, H))
    s += vinetka(.42)
    return s


def pirogi_na_rushnike(t):
    """Стол под длинным вышитым рушником: блюдо румяных пирогов крупно,
    морковь с ботвой, луковицы, скалка, миска с начинкой. Бабушка в переднике
    левой рукой держит блюдо, правой разламывает верхний пирог — из разлома
    идёт пар, с рук сыплется мука."""
    rnd = random.Random(347)
    pol = 1012
    s = f'<rect width="{W}" height="{H}" fill="#2a2018"/>'
    s += SL(Z_DAL, _stena_gornicy(t, 349, True, 700, True))
    s += SL(Z_DAL, _polka_s_utvaryu(80, 190, 560, t, 351, 5)
            + _polka_s_utvaryu(1230, 170, 560, t, 353, 4))
    s += SL(Z_DAL, utvar_pekarni(620, 196, 560, t, 355))
    # жердь над столом: связка лука, пучки зелени, рушник на стене — иначе
    # простенок между полками остаётся голым (замер пустоты центра)
    s += SL(Z_DAL, f'<rect x="660" y="300" width="560" height="18" rx="7"'
                   f' fill="#5b4428" {o(5)}/>')
    for i in range(6):
        s += SL(Z_DAL, _lukovica(700 + i * 92, 420 + (i % 2) * 34, .78, t,
                                 i * .3)
                + f'<line x1="{700+i*92:.0f}" y1="318" x2="{700+i*92:.0f}"'
                  f' y2="{388+(i%2)*34:.0f}" stroke="#b8a86a" stroke-width="6"/>')
    s += SL(Z_DAL, _puchki_zeleni(760, 520, 400, t, 371, 4))
    s += SL(Z_DAL, _rushnik_vyshityy(690, 92, 500, 84, t, 373))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="32"'
                   f' fill="#3f2d1d" opacity=".9"/>' + polovicy(pol + 16)
            + _pol_shvy(pol + 20, 1076, 357, 6, "#4a3824"))
    # печной угол справа — одно тёплое пятно кадра
    s += SL(Z_SRED, kladka(1660, 420, 260, 300, 70, PECH2)
            + f'<path d="{kontur_proema(1700, 560, 180, 150, "ustie")}"'
              f' fill="#190c05"/>' + ogon(1790, 686, t, .9, .4, 5))
    # СТОЛ и рушник
    s += SL(Z_SRED, f'{ten(840, pol + 18, 640, 26, .5)}'
                    f'<rect x="90" y="700" width="1500" height="56" rx="12"'
                    f' fill="url(#derev)" {o(8)}/>'
            + f'<rect x="124" y="756" width="1432" height="28" rx="9"'
              f' fill="#5b4428" {o(5)}/>')
    for px in (200, 1420):
        s += SL(Z_SRED, f'<rect x="{px:.0f}" y="784" width="74"'
                        f' height="{pol-784:.0f}" rx="12" fill="#5b4428" {o(6)}/>')
    s += SL(Z_SRED, _rushnik_vyshityy(120, 684, 1440, 100, t, 359))
    # ГЛАВНЫЙ ПРЕДМЕТ: блюдо пирогов, верхний разламывается
    razlom = A.ease(A.seg(t, .45, 1.3))
    s += SL(Z_SRED, _blyudo_pirogov(830, 666, 560, t, razlom, 5, 361))
    # сопутствующие вещи НА столе
    s += SL(Z_SRED, _morkov_botva(300, 660, 1.05, t, .2)
            + _morkov_botva(382, 666, .92, t, .6)
            + _lukovica(470, 660, 1.0, t, .3)
            + _lukovica(552, 664, .86, t, .7)
            + _skalka(1280, 652, 1.0, -8)
            + _miska_nachinki(1480, 668, 1.0, t, ORA))
    s += SL(Z_SRED, lampa(170, 640, t, 1.0, True))
    # ОДНА ФИГУРА: обе руки наружу влево, к блюду
    bx, by_, bh = 1330, pol, 750
    bab = figura(bx, by_, bh, t, col="#6a5a4a", kant="#ffd98a", platok=True,
                 ph=.4, naklon=4.0)
    r1, (k1x, k1y), _ = _ruka_so_sgibom(bx, by_, bh, -1, bh * .24, 30,
                                        bh * .26, 46, t, "#6a5a4a", "#ffd98a",
                                        .2, 5.0)
    r2, (k2x, k2y), _ = _ruka_so_sgibom(bx, by_, bh, -1, bh * .28, 12,
                                        bh * .30, 30 - 14 * razlom, t,
                                        "#6a5a4a", "#ffd98a", .6, 6.0)
    bab += r1 + r2
    # передник поверх одежды — роль видна с кадра
    s += SL(Z_SRED, f'<path d="M{bx-bh*.14:.0f},{by_-bh*.58:.0f}'
                    f' L{bx+bh*.14:.0f},{by_-bh*.58:.0f}'
                    f' L{bx+bh*.18:.0f},{by_-bh*.16:.0f}'
                    f' L{bx-bh*.18:.0f},{by_-bh*.16:.0f} Z" fill="{KREM}"'
                    f' {o(5)}/>'
            + f'<path d="M{bx-bh*.18:.0f},{by_-bh*.28:.0f} q{bh*.18:.0f},{bh*.03:.0f}'
              f' {bh*.36:.0f},0" fill="none" stroke="{TKAN}" stroke-width="9"'
              f' opacity=".8"/>')
    s += SL(Z_SRED, bab)
    # мука сыплется с рук, варежек нет: пирог держат пальцами, перекрытия нет
    s += SL(Z_SRED, _muka_sypletsya(k1x, k1y + 10, t, 11, 363, 120)
            + _muka_sypletsya(k2x, k2y + 8, t, 8, 365, 100))
    # нижняя треть
    s += SL(Z_SRED, _dvorovaya_utvar(70, pol + 76, 330, t, 367,
                                     ["korzina", "meshok"])
            + _yaschiki(620, pol + 10, t, 375, 3, .92)
            + _dvorovaya_utvar(880, pol + 70, 300, t, 377, ["vedro", "kadka"])
            + kartoshka(640, pol + 64, t, 8, 369, 1.05)
            + _kadushka_kapusty(1700, pol + 50, t, .9)
            + _polovik(900, pol + 48, 520, 120))
    s += SL(Z_SRED, _kot_zhivoy(1120, pol + 58, t, 1.05, "#4a3f36", .5))
    s += SL(Z_SRED, teplo(1790, 660, 420, 360, .34))
    s += SL(Z_PERED, _stolb_pered(-6, 112, "#1a120c", 0, H))
    s += vinetka(.42)
    return s


def yaschik_s_peskom_v_pogrebe(t):
    """Погреб со светом из люка: дощатый ящик с песком крупно, из песка
    торчат чёрные макушки редьки и рыжие морковки. Хозяин в телогрейке
    присел у ящика, левой держит фонарь, правой разгребает песок и тянет
    редьку за хвост. Рядом кадка, полка с банками, приставная лестница."""
    rnd = random.Random(379)
    pol = 1008
    s = f'<rect width="{W}" height="{H}" fill="#1b150f"/>'
    # земляные стены и своды — каменная кладка даёт сетку, а не обои
    s += SL(Z_DAL, svody(t, "#3b332a", 3))
    s += SL(Z_DAL, kladka(0, 120, 760, 620, 78, "#6a5c4c")
            + kladka(1180, 120, 740, 620, 78, "#6a5c4c"))
    s += SL(Z_DAL, kladka(760, 300, 420, 440, 72, "#5e5244"))
    # матица и подпорный столб погреба: длинная балка держит крупную
    # вертикаль кадра, а главный предмет остаётся в коридоре 420-700 px
    s += SL(Z_DAL, f'<rect x="-20" y="132" width="1120" height="52" rx="10"'
                   f' fill="#5a4530" {o(7)}/>'
            + f'<rect x="-20" y="184" width="1120" height="16" rx="6"'
              f' fill="#3f2d1d" opacity=".8"/>'
            + f'<rect x="300" y="184" width="54" height="{pol-184:.0f}" rx="10"'
              f' fill="#6b5340" {o(6)}/>'
            + f'<rect x="286" y="170" width="84" height="24" rx="8"'
              f' fill="#5a4530" {o(4)}/>')
    s += SL(Z_DAL, f'<rect x="0" y="{pol-24:.0f}" width="{W}" height="{H-pol+24:.0f}"'
                   f' fill="#3f3326"/>'
            + _zemlya_faktura(pol - 10, 1072, 381, 18, "#342a1e"))
    # ЛЮК В ПОТОЛКЕ и косой столб света из него
    s += SL(Z_DAL, f'<rect x="700" y="60" width="520" height="34" rx="8"'
                   f' fill="#2a2118" {o(6)}/>'
            + f'<path d="M740,94 L1180,94 L1120,34 L800,34 Z" fill="#5a4a36"'
              f' {o(5)}/>'
            + f'<rect x="1140" y="30" width="180" height="24" rx="8"'
              f' fill="#6b5340" {o(4)}/>')
    s += SL(Z_SRED, _konus_sveta(960, 96, 440, 820, 0.0, .38))
    s += SL(Z_SRED, luch(700, 94, 520, 820, t, .18))
    # ПОЛКА С БАНКАМИ и лестница — обстановка погреба
    s += SL(Z_SRED, _banki_v_pogrebe(1380, 520, 480, t, 383, 5))
    # огарок на полке: живой огонёк погреба, кроме фонаря в руке
    s += SL(Z_SRED, svecha(1670, 512, t, .3, 1.15, 104)
            + teplo(1670, 470, 220, 190, .38))
    s += SL(Z_SRED, _banki_v_pogrebe(60, 470, 420, t, 385, 4))
    s += SL(Z_SRED, _lestnica(1700, pol, 760, t, 6, -7.0))
    # ГЛАВНЫЙ ПРЕДМЕТ: ящик с песком на пол-кадра
    vyhod = A.ease(A.seg(t, .4, 1.6))
    s += SL(Z_SRED, _yaschik_peska(560, pol - 10, 690, 290, t, vyhod, 387))
    # ОДНА ФИГУРА: присел у ящика, корпус наклонён к песку
    gx, gy, gh = 1230, pol, 640
    goz = figura(gx, gy, gh, t, col="#4e5a46", kant="#ffd98a", ph=.3,
                 shapka=True, tulup=True, naklon=7.0)
    g1, (f1x, f1y), _ = _ruka_so_sgibom(gx, gy, gh, 1, gh * .26, 6,
                                        gh * .24, 30, t, "#4e5a46", "#ffd98a",
                                        .1, 4.0)
    g2, (f2x, f2y), _ = _ruka_so_sgibom(gx, gy, gh, -1, gh * .30, 22,
                                        gh * .32, 56 - 12 * vyhod, t,
                                        "#4e5a46", "#ffd98a", .5, 6.0)
    goz += g1 + g2
    s += SL(Z_SRED, goz)
    # ФОНАРЬ в левой кисти: живой огонёк кадра, варежка перекрывает скобу
    s += SL(Z_SRED, _fonar_ruchnoy(f1x + 20, f1y + 150, t, 1.0, 1.0, .2))
    s += SL(Z_SRED, _varezhka(f1x, f1y + 4, gh, t, .1))
    # РЕДЬКА, которую вынимают за хвост: идёт вверх из песка вслед за кистью
    s += SL(Z_SRED, _redka(f2x - 30, f2y + 78 - 40 * vyhod, .92, t,
                           -12 + 8 * vyhod, .5, "#2e2b2a"))
    s += SL(Z_SRED, _varezhka(f2x, f2y + 6, gh, t, .5))
    # нижняя треть: земляной пол с вещами
    s += SL(Z_SRED, _kadushka_kapusty(240, pol + 54, t, 1.0)
            + _yaschiki(1560, pol + 20, t, 389, 3, 1.0)
            + kartoshka(800, pol + 56, t, 9, 391, 1.1)
            + _luzha(1120, pol + 62, 160, t, .3)
            + _dvorovaya_utvar(1300, pol + 70, 260, t, 393, ["vedro"]))
    s += SL(Z_SRED, _kot_zhivoy(520, pol + 58, t, .95, "#2f2a26", .6, True, True))
    s += SL(Z_PERED, _stolb_pered(-8, 126, "#120d08", 0, H))
    s += SL(Z_PERED, _stolb_pered(1884, 126, "#120d08", 0, H))
    s += vinetka(.46)
    return s


def rynochnyy_prilavok_s_redkoy(t):
    """Городской рынок: погребной ящик стал прилавком под полосатым навесом.
    В витрине прилавка — настоящая чёрная редька; на прилавке весы, ценники
    без цифр, пучки зелени, свёкла, капуста. Продавщица кладёт редьку на
    весы и придерживает чашу, покупательница держит раскрытую сумку и
    показывает на редьку."""
    rnd = random.Random(397)
    pol = 1014
    s = f'<rect width="{W}" height="{H}" fill="url(#nsumer)"/>'
    s += nebo("sumer", t, False, 41)
    s += oblaka(t, 150, 5, 43, .40, "#cdd7e4", 13.0)
    s += SL(Z_DAL, _derevnya_ryad(560, t, 47, ((160, 330), (1700, 300))))
    s += SL(Z_DAL, _zabor_dosok(-30, 420, 540, 170, 49, 56))
    s += SL(Z_DAL, goloe_derevo(1560, 580, 460, t, 51, 8, "#3a3b43", True))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-26:.0f}" width="{W}" height="{H-pol+26:.0f}"'
                   f' fill="#55504a"/>' + _bulyzhnik(pol - 16, 1074, 53, 86))
    # ПРИЛАВОК: тумба из того же дощатого короба, что был ящиком в погребе
    px, py, pw, ph_ = 440, 470, 800, 420
    s += SL(Z_SRED, _naves_polosatyy(360, 430, 1340, t, 130, 55))
    s += SL(Z_SRED, f'{ten(960, pol + 16, 520, 24, .5)}'
                    f'<rect x="380" y="890" width="1280" height="40" rx="10"'
                    f' fill="url(#dosk)" {o(8)}/>'
            + f'<rect x="402" y="930" width="1236" height="{pol-930+16:.0f}"'
              f' rx="8" fill="#7d5636" {o(6)}/>'
            + "".join(f'<line x1="{424+i*72:.0f}" y1="940" x2="{424+i*72:.0f}"'
                      f' y2="{pol+10:.0f}" stroke="#5b4428" stroke-width="7"'
                      f' opacity=".8"/>' for i in range(17)))
    # НАСТОЯЩИЙ КАДР в витрине прилавка: сначала рисованный вид, потом метка,
    # потом обвязка поверх — переплёт витрины и бортик
    put = kontur_proema(px, py, pw, ph_, "pryam")
    s += SL(Z_SRED, f'<path d="{put}" fill="#2b2622"/>'
            + _vid_za_proemom(put, t, "lavka", 57, px + pw * .5)
            + mesto_stoka(px, py, pw, ph_, "pryam"))
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#5f4a34"'
                    f' stroke-width="30"/>'
            + f'<rect x="{px-40:.0f}" y="{py-44:.0f}" width="{pw+80:.0f}"'
              f' height="38" rx="10" fill="#6b5340" {o(5)}/>'
            + f'<rect x="{px-26:.0f}" y="{py+ph_-12:.0f}" width="{pw+52:.0f}"'
              f' height="34" rx="10" fill="url(#dosk)" {o(6)}/>'
            + f'<line x1="{px:.0f}" y1="{py+ph_*.5:.0f}" x2="{px+pw:.0f}"'
              f' y2="{py+ph_*.5:.0f}" stroke="#5f4a34" stroke-width="16"/>'
            + f'<path d="M{px+40:.0f},{py+ph_*.18:.0f} L{px+pw*.42:.0f},'
              f'{py+ph_*.06:.0f}" fill="none" stroke="#ffffff" stroke-width="12"'
              f' opacity="{.16+.10*abs(A.w(t,3.4,.2)):.2f}"/>')
    # ВЕСЫ, ценники и товар на прилавке
    klad = A.ease(A.seg(t, .5, 1.2))
    s += SL(Z_SRED, _vesy(1500, 886, t, .62, .22 * klad, .5, 240))
    s += SL(Z_SRED, _cenniki_bez_cifr(1250, 886, 3, t, 59))
    s += SL(Z_SRED, _puchki_zeleni(1310, 878, 220, t, 61, 3)
            + _svekla(1600, 862, .9, t, .3)
            + _svekla(1648, 872, .74, t, .7)
            + _kapusta(1420, 856, .86, t))
    # редька горкой на левом краю прилавка — на неё и показывает покупательница
    for i, (rx0, ry0, rs) in enumerate(((410, 862, .54), (466, 872, .44),
                                        (372, 878, .40))):
        s += SL(Z_SRED, _redka(rx0, ry0, rs, t, -8 + i * 11, .22))
    # ДВЕ ФИГУРЫ: реестр до первой руки
    prx, pry, prh = 1790, pol, 730
    pux, puy, puh = 250, pol, 700
    _figury_kadra((prx, pry, prh), (pux, puy, puh))
    pok = A.ease(A.seg(t, .4, 1.0))
    # продавщица: обе руки влево, к весам
    prod = figura(prx, pry, prh, t, col="#3f5c7a", kant="#cfe4f5", platok=True,
                  ph=.2, naklon=3.0)
    a1, (v1x, v1y), _ = _ruka_mimo(prx, pry, prh, -1, prh * .40, 20 + 10 * klad, t,
                                   "#3f5c7a", "#cfe4f5", .1, 5.0)
    a2, (v2x, v2y), _ = _ruka_sgib_mimo(prx, pry, prh, -1, prh * .22, 40,
                                        prh * .22, 56, t, "#3f5c7a",
                                        "#cfe4f5", .5, 4.0)
    prod += a1 + a2
    # нарукавники и фартук — роль читается со стоп-кадра
    s += SL(Z_SRED, f'<path d="M{prx-prh*.13:.0f},{pry-prh*.56:.0f}'
                    f' L{prx+prh*.13:.0f},{pry-prh*.56:.0f}'
                    f' L{prx+prh*.17:.0f},{pry-prh*.14:.0f}'
                    f' L{prx-prh*.17:.0f},{pry-prh*.14:.0f} Z" fill="#dfd6c0"'
                    f' {o(5)}/>')
    s += SL(Z_SRED, prod)
    s += SL(Z_SRED, f'<ellipse cx="{v1x+16:.0f}" cy="{v1y:.0f}" rx="26"'
                    f' ry="20" fill="#efe8d8" {o(4)}/>')
    # редька в кисти продавщицы ложится на чашу весов
    s += SL(Z_SRED, _redka(v1x - 54, v1y + 44 + 26 * klad, .64, t, 14, .3))
    s += SL(Z_SRED, _varezhka(v1x, v1y + 4, prh, t, .1))
    # покупательница: левая с раскрытой сумкой, правая показывает на редьку
    pokup = figura(pux, puy, puh, t, col="#54505e", kant="#cfe4f5", ph=.6,
                   platok=True, naklon=4.0)
    b1, (s1x, s1y), _ = _ruka_mimo(pux, puy, puh, -1, puh * .34, 54, t,
                                   "#54505e", "#cfe4f5", .2, 5.0)
    b2, (s2x, s2y), _ = _ruka_mimo(pux, puy, puh, 1, puh * .34, 58 - 10 * pok, t,
                                   "#54505e", "#cfe4f5", .6, 6.0)
    pokup += b1 + b2
    s += SL(Z_SRED, pokup)
    s += SL(Z_SRED, _sumka_hozyaystvennaya(s1x - 10, s1y + 118, t, 1.0, pok))
    s += SL(Z_SRED, _varezhka(s1x, s1y + 6, puh, t, .2))
    s += SL(Z_SRED, para_izo_rta(pux + 40, puy - puh * .80, t, .3, 1.0, .5)
            + para_izo_rta(prx - 44, pry - prh * .80, t, .7, 1.0, .45))
    # нижняя треть: городская мостовая с вещами
    s += SL(Z_SRED, _yaschiki(170, pol + 16, t, 63, 3, 1.0)
            + _yaschiki(1500, pol + 24, t, 65, 2, .9)
            + _kucha_listev(760, pol + 56, 300, 67, 70)
            + _luzha(1120, pol + 58, 190, t, .4)
            + _golub(620, pol + 50, t, 1.0, .2, True)
            + _golub(690, pol + 58, t, .86, .6, False))
    s += SL(Z_LETIT, mokryy_sneg(t, 26, 69, .54, .9))
    s += SL(Z_PERED, _stolb_pered(1892, 118, "#171310", 0, H))
    s += vinetka(.42)
    return s


def salat_iz_redki_za_tri_shaga(t):
    """Городская кухня у окна: тёрка над глубокой миской крупно, рядом
    бутылка масла без этикетки, солонка, ложка, полотенце. Женщина левой
    рукой держит тёрку за ручку, правой водит по ней редькой, потом льёт
    масло ложкой, потом трясёт солонкой — три шага подряд."""
    rnd = random.Random(401)
    pol = 1016
    s = f'<rect width="{W}" height="{H}" fill="#2e3334"/>'
    s += SL(Z_DAL, _kafel(0, 90, 1920, 640, t, 403))
    # окно кухни: вечер за стеклом, огоньки в домах напротив
    s += SL(Z_DAL, okno_izby(1320, 150, 520, 420, t,
                             f'<rect x="1320" y="150" width="520" height="420"'
                             f' fill="#2b3550"/>'
                             + "".join(f'<rect x="{1360+i*96:.0f}"'
                                       f' y="{300+(i%3)*54:.0f}" width="62"'
                                       f' height="46" rx="5" fill="{SVET}"'
                                       f' opacity="{.5+.3*abs(A.w(t,2.6,i*.4)):.2f}"/>'
                                       for i in range(5)),
                             .14, False, True))
    s += SL(Z_DAL, _polki_otkrytye(60, 170, 520, t, 405, 3, True, .0))
    s += SL(Z_DAL, _kover_na_stene(640, 150, 1, 1, t, 407)
            if False else _knizhnaya_polka(640, 210, 560, t, 409, 2, 170))
    s += SL(Z_DAL, tusklaya_lampochka(960, 40, t, 1.1, True))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-20:.0f}" width="{W}" height="{H-pol+20:.0f}"'
                   f' fill="#6a615a"/>' + _pol_shvy(pol - 10, 1074, 411, 6, "#4e463f"))
    # СТОЛ-столешница на тумбах
    s += SL(Z_SRED, f'{ten(900, pol + 14, 620, 24, .5)}'
                    f'<rect x="80" y="720" width="1500" height="46" rx="10"'
                    f' fill="#b9b2a4" {o(7)}/>'
            + f'<rect x="110" y="766" width="1440" height="{pol-766+10:.0f}"'
              f' rx="8" fill="#7e6c56" {o(6)}/>'
            + "".join(f'<rect x="{160+i*300:.0f}" y="800" width="250"'
                      f' height="180" rx="9" fill="#8f7b61" {o(4)}/>'
                      f'<circle cx="{280+i*300:.0f}" cy="890" r="13"'
                      f' fill="{ZHELEZ}" {o(3)}/>' for i in range(5)))
    # ТРИ ШАГА ПОДРЯД: тёрка, масло, соль
    sh1 = A.seg(t, .3, 1.2)
    sh2 = A.seg(t, 1.5, 1.1)
    sh3 = A.seg(t, 2.6, 1.0)
    napoln = min(1.0, A.ease(sh1) * .7 + A.ease(sh2) * .3)
    # ГЛАВНЫЙ ПРЕДМЕТ: тёрка над глубокой миской
    s += SL(Z_SRED, _glubokaya_miska(780, 712, 1.1, t, napoln))
    s += SL(Z_SRED, _terka(780, 580 - 14 * A.w(t, .9, .2), t, 1.25, -9.0))
    if sh1 < 1.0:
        s += SL(Z_SRED, _redka(790 + 30 * A.w(t, .7, .1),
                               470 + 120 * A.ease(sh1), .66, t, 18, .4))
        s += SL(Z_SRED, _struzhka_letit(780, 640, t, 9, 413, 120))
    # сопутствующие вещи
    s += SL(Z_SRED, _butyl_masla(1180, 718, 1.15, t, .3 * A.ease(sh2),
                                 A.ease(sh2)))
    s += SL(Z_SRED, _lozhka_derev(1040, 660 - 40 * A.ease(sh2), 1.0,
                                  128 - 40 * A.ease(sh2)))
    s += SL(Z_SRED, _solonka(1340, 716, 1.15, t, A.ease(sh3)))
    s += SL(Z_SRED, _polotence(1660, 700, 230, t, .3, "#e3ddc6", True))
    s += SL(Z_SRED, _kruzhka(240, 716, 1.0, 0, "#e8eef0", 1)
            + _banka_krupy(380, 716, 1.0, "#d8c08a")
            + _tarelka(500, 690, 66, t, .3, False, 0, "#eef2f4"))
    # ОДНА ФИГУРА: обе руки наружу, к тёрке и к миске
    zx, zy, zh = 1520, pol, 740
    zhen = figura(zx, zy, zh, t, col="#8a4a5c", kant="#cfe4f5", ph=.3,
                  naklon=4.0)
    q1, (w1x, w1y), _ = _ruka_so_sgibom(zx, zy, zh, -1, zh * .24, 24,
                                        zh * .28, 48, t, "#8a4a5c",
                                        "#cfe4f5", .2, 5.0)
    q2, (w2x, w2y), _ = _ruka_so_sgibom(zx, zy, zh, -1, zh * .26, 8,
                                        zh * .30, 26 + 10 * A.ease(sh3), t,
                                        "#8a4a5c", "#cfe4f5", .6, 7.0)
    zhen += q1 + q2
    s += SL(Z_SRED, zhen)
    # варежка только там, где кисть перекрывает ручку тёрки
    s += SL(Z_SRED, _varezhka(w1x, w1y + 4, zh, t, .2))
    s += SL(Z_SRED, f'<rect x="{w1x-60:.0f}" y="{w1y-8:.0f}" width="90"'
                    f' height="22" rx="10" fill="#9aa3aa" {o(4)}/>')
    # нижняя треть
    s += SL(Z_SRED, _gorodskoy_hlam(120, pol + 46, 300, t, 415,
                                    ["yaschik", "paket"])
            + _polovik(820, pol + 38, 520, 110, "#6a7a8c", "#3f5c7a")
            + _kot_zhivoy(1240, pol + 48, t, 1.05, "#4a4440", .4)
            + _dvorovaya_utvar(1660, pol + 48, 240, t, 417, ["vedro"]))
    s += SL(Z_SRED, teplo(960, 140, 460, 300, .30))
    s += SL(Z_PERED, _stolb_pered(-8, 104, "#1c1a18", 0, H))
    s += vinetka(.40)
    return s


def redka_s_medom_na_blyudce(t):
    """Кухонный подоконник: чёрная редька на блюдце крупно, срезанная
    верхушка лежит рядом крышечкой. В стекле окна за редькой — настоящий
    кадр, где мёд стекает с ложки. Видны руки до локтя: одна придерживает
    редьку, другая чайной ложкой выбирает ямку и кладёт в неё мёд. Рядом
    банка мёда, нож, шерстяной носок на батарее."""
    rnd = random.Random(419)
    pod = 760
    s = f'<rect width="{W}" height="{H}" fill="#2b2f31"/>'
    s += SL(Z_DAL, _kafel(0, 60, 1920, 600, t, 421, "#cfd8d4", "#a4b0ac"))
    s += SL(Z_DAL, _polki_otkrytye(1480, 120, 420, t, 423, 2, False, .0))
    s += SL(Z_DAL, tusklaya_lampochka(300, 30, t, .95, True))
    # НАСТОЯЩИЙ КАДР в стекле окна: вид, метка, переплёт и наличник поверх
    px, py, pw, ph_ = 480, 150, 900, 470
    put = kontur_proema(px, py, pw, ph_, "pryam")
    s += SL(Z_SRED, f'<path d="{put}" fill="#1d2630"/>'
            + _vid_za_proemom(put, t, "dvor", 425, px + pw * .5)
            + mesto_stoka(px, py, pw, ph_, "pryam"))
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#6f6a60"'
                    f' stroke-width="34"/>'
            + f'<line x1="{px+pw*.5:.0f}" y1="{py:.0f}" x2="{px+pw*.5:.0f}"'
              f' y2="{py+ph_:.0f}" stroke="#6f6a60" stroke-width="22"/>'
            + f'<line x1="{px:.0f}" y1="{py+ph_*.46:.0f}" x2="{px+pw:.0f}"'
              f' y2="{py+ph_*.46:.0f}" stroke="#6f6a60" stroke-width="18"/>'
            + f'<path d="M{px+60:.0f},{py+ph_*.30:.0f} L{px+pw*.34:.0f},'
              f'{py+ph_*.10:.0f}" fill="none" stroke="#ffffff" stroke-width="14"'
              f' opacity="{.14+.10*abs(A.w(t,3.2,.3)):.2f}"/>'
            + f'<rect x="{px-54:.0f}" y="{py-46:.0f}" width="{pw+108:.0f}"'
              f' height="40" rx="10" fill="#7e776c" {o(5)}/>')
    # ПОДОКОННИК — широкая доска, на ней всё и стоит
    s += SL(Z_SRED, f'{ten(930, pod + 16, 560, 22, .5)}'
                    f'<rect x="300" y="{pod-34:.0f}" width="1320" height="48"'
                    f' rx="12" fill="#cfc9bc" {o(7)}/>'
            + f'<rect x="330" y="{pod+14:.0f}" width="1260" height="22" rx="8"'
              f' fill="#a8a299" {o(4)}/>')
    # БАТАРЕЯ с шерстяным носком под подоконником
    s += SL(Z_SRED, _batareya_s_noskom(620, pod + 60, 560, t, True, 427))
    # ГЛАВНЫЙ ПРЕДМЕТ: редька с выбранной ямкой и мёдом
    yamka = A.ease(A.seg(t, .5, 2.0))
    med = A.ease(A.seg(t, 2.8, 1.6))
    s += SL(Z_SRED, _blyudce(900, pod - 30, 1.0, med, t))
    s += SL(Z_SRED, _redka_s_yamkoy(880, pod - 46, 1.0, t, yamka, med))
    # сопутствующие вещи подоконника
    s += SL(Z_SRED, _banka_meda(1330, pod - 34, 1.0, t, True))
    s += SL(Z_SRED, _nozh(1120, pod - 36, 1.0, -6))
    s += SL(Z_SRED, _kruzhka(420, pod - 34, 1.05, 0, "#e8eef0", -1)
            + _banka_krupy(540, pod - 34, .92, "#e2d6a8")
            + _cvetok_v_gorshke(1540, pod - 32, t, .9, .2))
    # РУКИ ДО ЛОКТЯ, без человека: nichya=True — такая кисть не гасит
    # рукав соседней фигуры и браком не считается
    lx, ly = 700, 1072
    r1, (e1x, e1y) = rukav(lx, ly, 300, -74, t, "#c2a07a", "#e8d8c0", .2, 4.0,
                           True)
    rx2, ry2 = 1140, 1074
    hod = A.w(t, 1.6, .1)
    r2, (e2x, e2y) = rukav(rx2, ry2, 318, -104 + 5 * hod, t, "#c2a07a",
                           "#e8d8c0", .6, 5.0, True)
    s += SL(Z_SRED, r1 + r2)
    # варежки ставим: обе кисти перекрывают предмет — редьку и черенок ложки
    s += SL(Z_SRED, _varezhka(e1x, e1y, 760, t, .2, "#e8d8c0", "#b89a74"))
    s += SL(Z_SRED, f'<g transform="rotate(-38 {e2x:.0f} {e2y:.0f})">'
                    f'<ellipse cx="{e2x-22:.0f}" cy="{e2y-46:.0f}" rx="26"'
                    f' ry="18" fill="#cfd8dc" {o(4)}/>'
                    f'<rect x="{e2x-6:.0f}" y="{e2y-46:.0f}" width="13"'
                    f' height="76" rx="6" fill="#b9c6cc" {o(3)}/></g>')
    s += SL(Z_SRED, _varezhka(e2x, e2y, 760, t, .6, "#e8d8c0", "#b89a74"))
    if med > .05:
        s += SL(Z_SRED, f'<path d="M{e2x-26:.0f},{e2y-52:.0f} q{6:.0f},'
                        f'{30+26*med:.0f} {-10:.0f},{54+30*med:.0f}" fill="none"'
                        f' stroke="{ZOL}" stroke-width="{12-4*med:.0f}"'
                        f' stroke-linecap="round"/>')
    # нижняя треть: кухонный низ занят вещами
    s += SL(Z_SRED, _gorodskoy_hlam(170, 1020, 260, t, 429, ["yaschik"])
            + _dvorovaya_utvar(1700, 1026, 210, t, 431, ["vedro"])
            + _polovik(1420, 1016, 400, 96, "#6a7a8c", "#3f5c7a"))
    s += SL(Z_SRED, teplo(900, pod + 80, 520, 260, .26))
    s += SL(Z_PERED, _stolb_pered(1896, 96, "#1a1816", 0, H))
    s += vinetka(.40)
    return s


def sok_redki_k_utru(t):
    """Та же редька на блюдце у окна, за которым ночь сменяется утром, и
    блюдце наполняется янтарным соком. Малыш с завязанным шарфом горлом
    сидит в кровати среди подушек и обеими руками держит плюшевого мишку.
    Мать на краю кровати: левой держит блюдце, правой подносит ложку с
    соком. На тумбочке градусник, стакан, книжка."""
    rnd = random.Random(433)
    pol = 1018
    utro = A.ease(A.seg(t, .6, 2.6))
    s = f'<rect width="{W}" height="{H}" fill="#242a33"/>'
    s += SL(Z_DAL, _stena_gornicy(t, 435, True, 720, True))
    s += SL(Z_DAL, _kover_na_stene(1140, 150, 700, 400, t, 437))
    # окно: ночь светлеет до рассвета, за стеклом огоньки и первый снег
    s += SL(Z_DAL, okno_izby(120, 170, 560, 440, t,
                             f'<rect x="120" y="170" width="560" height="440"'
                             f' fill="{SUMER}" opacity="{1-utro*.7:.2f}"/>'
                             f'<rect x="120" y="170" width="560" height="440"'
                             f' fill="{RASSV}" opacity="{utro*.8:.2f}"/>'
                             + f'<circle cx="300" cy="300" r="{54:.0f}"'
                               f' fill="#e8eef6" opacity="{1-utro:.2f}"/>'
                             + f'<circle cx="560" cy="330" r="{70:.0f}"'
                               f' fill="{SVET}" opacity="{utro*.7:.2f}"/>'
                             + "".join(f'<rect x="{170+i*96:.0f}" y="440"'
                                       f' width="56" height="44" rx="5"'
                                       f' fill="{SVET}"'
                                       f' opacity="{(1-utro)*(.4+.3*abs(A.w(t,2.4,i*.3))):.2f}"/>'
                                       for i in range(5))
                             + f'<rect x="120" y="500" width="560" height="110"'
                               f' fill="{SNEG}" opacity=".7"/>',
                             .22, True, True))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="{H-pol+18:.0f}"'
                   f' fill="#5e4a34"/>' + polovicy(pol + 14)
            + _pol_shvy(pol + 16, 1074, 439, 6, "#4a3824"))
    # ПОДОКОННИК с блюдцем: сок набегает к утру
    s += SL(Z_SRED, f'<rect x="90" y="614" width="640" height="40" rx="10"'
                    f' fill="#cfc9bc" {o(6)}/>')
    s += SL(Z_SRED, _blyudce(300, 606, .92, utro, t))
    s += SL(Z_SRED, _redka_s_yamkoy(290, 594, .80, t, 1.0, .9 - .5 * utro))
    s += SL(Z_SRED, _banka_meda(560, 610, .7, t, False))
    # КРОВАТЬ с подушками — обстановка плана
    s += SL(Z_SRED, _krovat(800, pol, 1000, t, 441, True, 330))
    s += SL(Z_SRED, _podushka(1000, 700, 320, 190, t, .2, .3, .0)
            + _podushka(1250, 684, 290, 180, t, .6, .2, .0))
    s += SL(Z_SRED, _odeyalo_kray(830, 814, 820, 200, t, .2, TKAN2))
    s += SL(Z_SRED, _tumbochka_veschi(1600, pol, 270, t, 200))
    s += SL(Z_SRED, lampa(1700, pol - 212, t, .9, True))
    # ДВЕ ФИГУРЫ: малыш в кровати и мать на краю
    mx, my, mh = 1120, 806, 440
    mtx, mty, mth = 660, pol, 720
    _figury_kadra((mx, my, mh), (mtx, mty, mth))
    nes = A.ease(A.seg(t, 1.1, 1.3))
    # малыш: обе руки обнимают мишку, шарф на горле
    mal = figura(mx, my, mh, t, col="#e2d6c2", kant="#ffd98a", ph=.4,
                 naklon=3.0)
    d1, (c1x, c1y), _ = _ruka_mimo(mx, my, mh, -1, mh * .36, 44, t,
                                   "#e2d6c2", "#ffd98a", .2, 4.0)
    d2, (c2x, c2y), _ = _ruka_mimo(mx, my, mh, 1, mh * .36, 42, t,
                                   "#e2d6c2", "#ffd98a", .6, 4.0)
    mal += d1 + d2
    s += SL(Z_SRED, mal)
    s += SL(Z_SRED, f'<path d="M{mx-mh*.14:.0f},{my-mh*.70:.0f}'
                    f' q{mh*.14:.0f},{mh*.07:.0f} {mh*.28:.0f},0'
                    f' q{-mh*.04:.0f},{mh*.07:.0f} {-mh*.28:.0f},{mh*.02:.0f} Z"'
                    f' fill="{TKAN}" {o(4)}/>'
            + f'<path d="M{mx+mh*.10:.0f},{my-mh*.64:.0f} q{mh*.10:.0f},'
              f'{mh*.14:.0f} {mh*.02:.0f},{mh*.24:.0f}" fill="none"'
              f' stroke="{TKAN}" stroke-width="{mh*.05:.0f}"/>')
    # МИШКА — ровно между кистями малыша, видно, что его держат
    s += SL(Z_SRED, _mishka_plyush((c1x + c2x) * .5, (c1y + c2y) * .5 + 24,
                                   1.0, t, .3 + .5 * abs(A.w(t, 2.0, .2))))
    # мать: левая с блюдцем, правая с ложкой — обе наружу вправо, к малышу
    mat = figura(mtx, mty, mth, t, col="#54505e", kant="#ffd98a", platok=True,
                 ph=.7, naklon=5.0)
    e1, (g1x, g1y), _ = _ruka_mimo(mtx, mty, mth, 1, mth * .40, 34, t,
                                   "#54505e", "#ffd98a", .3, 5.0)
    e2, (g2x, g2y), _ = _ruka_sgib_mimo(mtx, mty, mth, 1, mth * .26, 16,
                                        mth * .26, 4 - 14 * nes, t,
                                        "#54505e", "#ffd98a", .8, 5.0)
    mat += e1 + e2
    s += SL(Z_SRED, mat)
    # блюдце в левой кисти, ложка в правой: варежки перекрывают оба предмета
    s += SL(Z_SRED, _blyudce(g1x + 40, g1y + 16, .62, utro * .8, t))
    s += SL(Z_SRED, _varezhka(g1x, g1y + 2, mth, t, .3))
    s += SL(Z_SRED, f'<g transform="rotate({12 + 8 * nes:.1f} {g2x:.0f} {g2y:.0f})">'
                    f'<rect x="{g2x:.0f}" y="{g2y-7:.0f}" width="96" height="14"'
                    f' rx="7" fill="#b9c6cc" {o(3)}/>'
                    f'<ellipse cx="{g2x+116:.0f}" cy="{g2y:.0f}" rx="30"'
                    f' ry="21" fill="#cfd8dc" {o(4)}/>'
                    f'<ellipse cx="{g2x+116:.0f}" cy="{g2y-2:.0f}" rx="21"'
                    f' ry="13" fill="{ZOL}" opacity=".95"/></g>')
    s += SL(Z_SRED, _varezhka(g2x + 16, g2y + 2, mth, t, .8))
    # нижняя треть
    s += SL(Z_SRED, _polovik(900, pol + 40, 620, 120)
            + _valenki_u_dveri(300, pol + 32, 1.0, t)
            + _kot_zhivoy(1480, pol + 52, t, 1.05, "#3b3430", .4, True, True)
            + _dvorovaya_utvar(1760, pol + 54, 190, t, 443, ["korzina"]))
    s += SL(Z_SRED, teplo(1700, pol - 240, 440, 340, .34))
    s += SL(Z_PERED, _stolb_pered(-8, 110, "#1a120c", 0, H))
    s += vinetka(.42)
    return s


def babushka_s_lozhkoy(t):
    """Мальчик лет шести крупно: зажмурился, плечи подняты, обе руки
    вцепились в край одеяла. Бабушка в очках наклонилась у кровати: в правой
    руке чайная ложка у самых его губ, левую держит ковшиком под ложкой,
    потом гладит его по голове. Ложка подходит к губам СБОКУ — лицо остаётся
    видно целиком (правило «предмет не ложится на лицо»)."""
    rnd = random.Random(447)
    pol = 1022
    s = f'<rect width="{W}" height="{H}" fill="#282019"/>'
    s += SL(Z_DAL, _stena_gornicy(t, 449, True, 740, True))
    s += SL(Z_DAL, _ramki_na_stene(140, 180, 520, t, 451, 4))
    s += SL(Z_DAL, _polka_s_utvaryu(1420, 170, 440, t, 453, 4))
    # простенок над кроватью занят вещами: без них центр кадра жидкий
    s += SL(Z_DAL, _polka_s_utvaryu(940, 180, 380, t, 459, 4)
            + _kover_na_stene(700, 300, 560, 330, t, 461))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="{H-pol+18:.0f}"'
                   f' fill="#5e4a34"/>' + polovicy(pol + 14)
            + _pol_shvy(pol + 16, 1078, 455, 6, "#4a3824"))
    s += SL(Z_SRED, _krovat(240, pol, 1120, t, 457, True, 340))
    s += SL(Z_SRED, _podushka(420, 686, 360, 210, t, .3, .4, .0))
    s += SL(Z_SRED, lampa(1760, pol - 30, t, 1.1, True))
    # МАЛЬЧИК КРУПНО: рост взят так, что в кадр входят голова и плечи, а
    # опора (кровать) остаётся под ним — ноги уходят за нижний край
    bx, by_, bh = 700, 1620, 1340
    gx, gy, gh = 1430, pol, 760
    _figury_kadra((bx, by_, bh), (gx, gy, gh))
    glot = A.ease(A.seg(t, 2.6, .8))
    glad = A.ease(A.seg(t, 4.4, 1.2))
    drozh = 7.0 * glot * A.w(t, 11.0, .2)
    s += SL(Z_SRED, f'<g transform="translate({drozh:.1f},0)">')
    mal = figura(bx, by_, bh, t, col="#e2d6c2", kant="#ffd98a", ph=.2,
                 naklon=2.0)
    b1, (y1x, y1y), _ = _ruka_mimo(bx, by_, bh, -1, bh * .22, 58, t,
                                   "#e2d6c2", "#ffd98a", .1, 3.0)
    b2, (y2x, y2y), _ = _ruka_mimo(bx, by_, bh, 1, bh * .22, 56, t,
                                   "#e2d6c2", "#ffd98a", .5, 3.0)
    mal += b1 + b2
    s += SL(Z_SRED, mal + "</g>")
    # одеяло, в которое вцепились обе руки: край стягивается при хвате
    s += SL(Z_SRED, _odeyalo_kray(240, max(y1y, y2y) + 10, 1020, 240, t,
                                  .4 + .5 * abs(A.w(t, 2.2, .1)), TKAN2))
    # БАБУШКА В ОЧКАХ: обе руки наружу влево, к губам мальчика
    bab = figura(gx, gy, gh, t, col="#6a5a4a", kant="#ffd98a", platok=True,
                 ph=.6, naklon=9.0)
    k1, (z1x, z1y), _ = _ruka_sgib_mimo(gx, gy, gh, -1, gh * .24, 18,
                                        gh * .26, 34 - 10 * glot, t,
                                        "#6a5a4a", "#ffd98a", .2, 4.0)
    k2, (z2x, z2y), _ = _ruka_sgib_mimo(gx, gy, gh, -1, gh * .24, 34,
                                        gh * .24, 54 - 46 * glad, t,
                                        "#6a5a4a", "#ffd98a", .7, 5.0)
    bab += k1 + k2
    s += SL(Z_SRED, bab)
    s += SL(Z_SRED, _ochki(gx - 6, gy - gh * .845, 1.15, t))
    # ЛОЖКА у губ: черенок от кисти, черпак останавливается у края лица
    hh_ = bh * .145
    cel_x = bx + hh_ * .98
    cel_y = by_ - bh * .845 + hh_ * .42
    ug_l = math.degrees(math.atan2(cel_y - z1y, cel_x - z1x))
    dl_l = min(150.0, max(70.0, math.hypot(cel_x - z1x, cel_y - z1y) - 26))
    lx2 = z1x + dl_l * math.cos(math.radians(ug_l))
    ly2 = z1y + dl_l * math.sin(math.radians(ug_l))
    s += SL(Z_SRED, f'<line x1="{z1x:.0f}" y1="{z1y:.0f}" x2="{lx2:.0f}"'
                    f' y2="{ly2:.0f}" stroke="#b9c6cc" stroke-width="15"'
                    f' stroke-linecap="round"/>'
            + f'<ellipse cx="{lx2:.0f}" cy="{ly2:.0f}" rx="32" ry="22"'
              f' fill="#cfd8dc" {o(4)}/>'
            + f'<ellipse cx="{lx2:.0f}" cy="{ly2-2:.0f}" rx="22" ry="13"'
              f' fill="{ZOL}" opacity="{.95-.7*glot:.2f}"/>')
    s += SL(Z_SRED, _varezhka(z1x, z1y + 2, gh, t, .2))
    # левая ладонь ковшиком ПОД ложкой, пока не гладит по голове
    if glad < .2:
        s += SL(Z_SRED, f'<path d="M{z2x-34:.0f},{z2y:.0f} q{34:.0f},{40:.0f}'
                        f' {68:.0f},0 q{-34:.0f},{14:.0f} {-68:.0f},0 Z"'
                        f' fill="#e8d8c0" {o(4)}/>')
    else:
        s += SL(Z_SRED, _varezhka(z2x, z2y + 2, gh, t, .7))
    # передёргивание и «бр-р»: капля с ложки и дрожь плеч уже заданы
    if glot > .1:
        for i in range(3):
            s += SL(Z_LETIT, f'<circle cx="{lx2+10+i*14:.0f}"'
                             f' cy="{ly2+28+i*22+40*glot:.0f}"'
                             f' r="{7-i:.0f}" fill="{ZOL}"'
                             f' opacity="{(1-glot)*.8:.2f}"/>')
    # нижняя треть
    s += SL(Z_SRED, _yaschiki(110, pol + 16, t, 463, 3, 1.0)
            + _dvorovaya_utvar(1560, pol + 60, 230, t, 465, ["kadka"]))
    s += SL(Z_SRED, _tabyret(1180, pol + 8, t, 160, 180)
            + _kruzhka(1180, pol - 150, 1.0, 0, "#e8eef0", 1)
            + _polovik(900, pol + 40, 560, 120)
            + _valenki_u_dveri(1680, pol + 34, 1.05, t)
            + _kot_zhivoy(1310, pol + 54, t, 1.05, "#3b3430", .5))
    s += SL(Z_SRED, teplo(1760, pol - 60, 420, 320, .32))
    s += SL(Z_PERED, _stolb_pered(1898, 96, "#1a120c", 0, H))
    s += vinetka(.42)
    return s


def banya_na_ogorode(t):
    """Бревенчатая банька на краю огорода: дым валит из трубы, бочка с
    водой, ковш на гвозде, веники под стрехой, тропинка в снегу. Дверь
    приоткрыта, в проёме клубится пар и стоит берёзовый веник. Мужик в
    тулупе идёт по тропинке: под левой рукой таз, в правой свёрток чистого
    белья. Из двери выкатываются и убегают в сугроб три серые хвори."""
    rnd = random.Random(467)
    gor = 700
    s = f'<rect width="{W}" height="{H}" fill="url(#nsumer)"/>'
    s += nebo("sumer", t, True, 71)
    s += oblaka(t, 150, 5, 73, .42, "#cdd7e4", 13.0)
    s += SL(Z_DAL, _derevnya_ryad(gor - 150, t, 75, ((140, 300), (1760, 260))))
    s += SL(Z_DAL, goloe_derevo(360, gor - 40, 520, t, 77, 9, "#3a3b43", True)
            + goloe_derevo(1700, gor - 10, 460, t, 79, 8, "#3a3b43", True))
    s += SL(Z_DAL, pleten(-20, gor - 190, 620, 180, 9)
            + _zabor_dosok(1480, gor - 180, 460, 170, 81, 56))
    s += SL(Z_DAL, _stog(220, gor + 40, .9, t, True))
    s += SL(Z_DAL, f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor:.0f}"'
                   f' fill="#55564e"/>' + sneg_lezhit(gor + 20, 28)
            + _zemlya_faktura(gor + 70, 1070, 83, 16, "#3f4238"))
    # ГЛАВНЫЙ ПРЕДМЕТ: банька с трубой, дымом, окошком и вениками
    s += SL(Z_SRED, _banya_srub(700, gor + 80, 660, t, 85, .0))
    # ДВЕРЬ ПРИОТКРЫТА: нарисованный пар и берёзовый веник в самом проёме —
    # настоящего кадра здесь НЕ ставим: в раскадровке по этому плану сток
    # помечен «убрано», а лишняя метка — брак гейта
    dx_, dy_, dw, dh = 860, gor - 300, 230, 380
    putd = kontur_proema(dx_, dy_, dw, dh, "arka")
    s += SL(Z_SRED, f'<path d="{putd}" fill="#140d08"/>'
            + f'<path d="{putd}" fill="{SVET}" opacity=".16"/>')
    s += SL(Z_SRED, par(dx_ + dw * .5, dy_ + dh * .72, t, 5, .62, 220, .55, 1.6))
    s += SL(Z_SRED, _venik(dx_ + dw * .62, dy_ + dh - 20, 260, t, "#cdbf9c",
                           "#b8352c", True, .14, .2, .86, 87))
    s += SL(Z_SRED, f'<path d="{putd}" fill="none" stroke="#4e3c2c"'
                    f' stroke-width="26"/>'
            + dver(dx_ - 210, dy_ + 20, 200, dh - 20, .55, "url(#derev)",
                   True, False))
    s += SL(Z_SRED, par(dx_ + dw * .5, dy_ + dh * .40, t, 4, .46, 180, .4, 1.3))
    # бочка, ковш на гвозде, поленница — обстановка двора
    s += SL(Z_SRED, _bochka_vody(1430, gor + 150, 1.0, t, True))
    s += SL(Z_SRED, _kovsh_na_gvozde(1330, gor - 120, 1.0, t, .3))
    s += SL(Z_SRED, _polenica(1500, gor + 230, 380, 210, 89, 26))
    s += SL(Z_SRED, _kadushki_i_grabli(360, gor + 250, t, 91))
    # ТРОПИНКА В СНЕГУ и следы по ней
    s += SL(Z_SRED, f'<path d="M120,1070 Q520,920 {dx_+dw*.5:.0f},{gor+90:.0f}'
                    f' L{dx_+dw*.5+150:.0f},{gor+90:.0f} Q700,940 460,1072 Z"'
                    f' fill="#6b6a60" {o(5)}/>'
            + f'<path d="M150,1064 Q540,916 {dx_+dw*.5+20:.0f},{gor+100:.0f}"'
              f' fill="none" stroke="#7d7c70" stroke-width="22" opacity=".8"/>')
    s += SL(Z_SRED, _sledy(300, 1040, dx_ + dw * .5, gor + 110, 9, 93,
                           "#43423a", 1.1))
    # ОДНА ФИГУРА: мужик в тулупе на тропинке, таз под левой, свёрток в правой
    shag = A.ease(A.seg(t, .3, 2.4))
    ux = 560 + 170 * shag
    uy = 1010 - 120 * shag
    uh = 760 - 150 * shag
    _figury_kadra((ux, uy, uh))
    muzh = figura(ux, uy, uh, t, col="#4e4036", kant="#cfe4f5", ph=.3,
                  shapka=True, tulup=True, naklon=4.0)
    n1, (t1x, t1y), _ = _ruka_mimo(ux, uy, uh, -1, uh * .30, 56, t,
                                   "#4e4036", "#cfe4f5", .2, 4.0)
    n2, (t2x, t2y), _ = _ruka_mimo(ux, uy, uh, 1, uh * .34, 60, t,
                                   "#4e4036", "#cfe4f5", .6, 5.0)
    muzh += n1 + n2
    s += SL(Z_SRED, muzh)
    s += SL(Z_SRED, _taz_i_svertok(t1x - 46, t1y + 60, .62 * uh / 760.0, t, -12))
    s += SL(Z_SRED, _varezhka(t1x, t1y + 4, uh, t, .2))
    s += SL(Z_SRED, _svertok_belya(t2x + 36, t2y + 42, .62 * uh / 760.0, t, -10))
    s += SL(Z_SRED, _varezhka(t2x, t2y + 6, uh, t, .6))
    s += SL(Z_SRED, para_izo_rta(ux + 40, uy - uh * .80, t, .4, 1.1, .55))
    # ТРИ ХВОРИ: рост через одного крупная/мелкая, шаг рваный, разбег < 0,4 с
    for i, (hx_, hs, hp) in enumerate(((1030, 1.30, .0), (1130, .64, .22),
                                       (1230, 1.08, .40))):
        beg = A.ease(A.seg(t, .5 + i * .32, 1.6))
        s += SL(Z_SRED, _hvor(hx_, gor + 120 + i * 26, hs, t, hp, beg))
    s += SL(Z_SRED, f'<path d="M1560,1052 q120,-60 250,-8" fill="none"'
                    f' stroke="{SNEG}" stroke-width="40" opacity=".8"/>')
    s += SL(Z_SRED, _snegovik(1800, gor + 320, .74, t))
    s += SL(Z_SRED, teplo(900, gor - 180, 480, 380, .30))
    s += SL(Z_LETIT, mokryy_sneg(t, 30, 95, .6, 1.0))
    s += SL(Z_PERED, _vetka_pered(-40, 150, 620, 26, t, 97, "#241c16", 7))
    s += vinetka(.44)
    return s


# ── ПОМОЩНИКИ ВТОРОЙ ПАРТИИ ───────────────────────────────────────────────

def _dverca_pechi(x, y, w_, h_, t, otkr=.0, seed=3):
    """ЧУГУННАЯ ДВЕРЦА БАННОЙ ПЕЧИ — главный предмет: литая рама с
    завитками по углам, решётчатая отдушина, ручка-завёртка, а за открытой
    створкой видна топка с углями. Створка ходит на петлях, не ездит целиком."""
    ug = -82.0 * otkr
    s = (f'{kladka(x - 40, y - h_ - 50, w_ + 80, h_ + 70, 54, "#6a5c4c")}'
         f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="14" fill="#1b1512" {o(8)}/>'
         f'{ugli(x + 20, y - 26, w_ - 40, t, 8, seed)}'
         f'{ogon(x + w_ * .5, y - h_ * .40, t, 1.25, .2, 7)}')
    s += (f'<rect x="{x-26:.0f}" y="{y-h_-26:.0f}" width="{w_+52:.0f}"'
          f' height="{h_+40:.0f}" rx="16" fill="none" stroke="#3d3a38"'
          f' stroke-width="26"/>')
    for i in (-1, 1):
        for j in (-1, 1):
            cx = x + w_ * .5 + i * (w_ * .5 + 10)
            cy = y - h_ * .5 + j * (h_ * .5 + 6)
            s += (f'<path d="M{cx:.0f},{cy:.0f} q{i*30:.0f},{j*6:.0f}'
                  f' {i*26:.0f},{j*30:.0f}" fill="none" stroke="#4e4a47"'
                  f' stroke-width="11"/>')
    # створка
    s += (f'<g transform="rotate({ug:.1f} {x:.0f} {y-h_*.5:.0f})">'
          f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
          f' rx="12" fill="#4e4a47" {o(7)}/>'
          f'<rect x="{x+18:.0f}" y="{y-h_+18:.0f}" width="{w_-36:.0f}"'
          f' height="{h_-36:.0f}" rx="9" fill="#5f5a56" opacity=".9"/>')
    for i in range(5):
        s += (f'<rect x="{x+w_*.26:.0f}" y="{y-h_*.74+i*h_*.09:.0f}"'
              f' width="{w_*.48:.0f}" height="{h_*.045:.0f}" rx="5"'
              f' fill="#2a2726"/>')
    s += (f'<circle cx="{x+w_*.84:.0f}" cy="{y-h_*.5:.0f}" r="{h_*.09:.0f}"'
          f' fill="#8f979d" {o(5)}/>'
          f'<rect x="{x+w_*.80:.0f}" y="{y-h_*.56:.0f}" width="{w_*.22:.0f}"'
          f' height="{h_*.055:.0f}" rx="6" fill="#6f767c" {o(3)}/>')
    for j in (-1, 1):
        s += (f'<rect x="{x-14:.0f}" y="{y-h_*.5+j*h_*.34:.0f}" width="30"'
              f' height="{h_*.14:.0f}" rx="7" fill="#3d3a38" {o(4)}/>')
    s += "</g>"
    s += (f'<ellipse cx="{x+w_*.5:.0f}" cy="{y+16:.0f}" rx="{w_*.56:.0f}"'
          f' ry="22" fill="#2a2118" opacity=".6"/>')
    return s


def _poleno(x, y, s_=1.0, ug=0.0, bereza=True):
    """Берёзовое полено: колотая плашка, торец с годовыми кольцами и
    трещиной, белая кора с чёрными штрихами."""
    w2, h2 = 190 * s_, 56 * s_
    s = (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
         f'<rect x="{x-w2/2:.0f}" y="{y-h2/2:.0f}" width="{w2:.0f}"'
         f' height="{h2:.0f}" rx="{10*s_:.0f}"'
         f' fill="{"#e8e2d6" if bereza else "url(#derev)"}" {o(5)}/>')
    if bereza:
        for i in range(5):
            s += (f'<path d="M{x-w2*.40+i*w2*.19:.0f},{y-h2*.44:.0f}'
                  f' q{6*s_:.0f},{h2*.30:.0f} {-2*s_:.0f},{h2*.50:.0f}"'
                  f' fill="none" stroke="#3a352e" stroke-width="{max(2,5*s_):.0f}"'
                  f' opacity=".8"/>')
    s += (f'<ellipse cx="{x+w2/2:.0f}" cy="{y:.0f}" rx="{10*s_:.0f}"'
          f' ry="{h2/2:.0f}" fill="#c9a47a" {o(4)}/>')
    for i in range(3):
        s += (f'<ellipse cx="{x+w2/2:.0f}" cy="{y:.0f}" rx="{(7-i*2)*s_:.0f}"'
              f' ry="{h2*(.36-i*.10):.0f}" fill="none" stroke="#a98a5e"'
              f' stroke-width="{max(2,3*s_):.0f}"/>')
    s += (f'<line x1="{x+w2/2:.0f}" y1="{y-h2*.34:.0f}" x2="{x+w2/2:.0f}"'
          f' y2="{y+h2*.34:.0f}" stroke="#8a6038" stroke-width="{max(2,4*s_):.0f}"/>'
          f'</g>')
    return s


def _vanna(x, y, w_, t, h_=250):
    """БЕЛАЯ ВАННА — главный предмет: чугунный борт с заворотом, четыре
    ножки-лапы, смеситель с душевой лейкой, вода с рябью и густой пар."""
    s = (f'{ten(x + w_ * .5, y + 22, w_ * .52, 24, .5)}'
         f'<path d="M{x:.0f},{y-h_:.0f} q{-26:.0f},{h_*.56:.0f} {30:.0f},{h_:.0f}'
         f' L{x+w_-30:.0f},{y:.0f} q{56:.0f},{-h_*.44:.0f} {30:.0f},{-h_:.0f} Z"'
         f' fill="#eef2f4" {o(8)}/>'
         f'<ellipse cx="{x+w_*.5:.0f}" cy="{y-h_:.0f}" rx="{w_*.5:.0f}"'
         f' ry="{w_*.09:.0f}" fill="#dde6ea" {o(6)}/>'
         f'<ellipse cx="{x+w_*.5:.0f}" cy="{y-h_+10:.0f}" rx="{w_*.44:.0f}"'
         f' ry="{w_*.07:.0f}" fill="#b9c6cc" opacity=".9"/>'
         f'<ellipse cx="{x+w_*.5:.0f}" cy="{y-h_+16:.0f}" rx="{w_*.40:.0f}"'
         f' ry="{w_*.055:.0f}" fill="{VODA}" opacity=".55"/>')
    for i in range(4):
        s += (f'<path d="M{x+w_*(.18+i*.18):.0f},{y-h_+16:.0f}'
              f' q{w_*.05:.0f},{-7 - 4 * A.w(t, 2.0, i * .3):.0f} {w_*.10:.0f},0"'
              f' fill="none" stroke="#dff0fa" stroke-width="7" opacity=".7"/>')
    for i in (0, 1):
        for j in (0, 1):
            lx = x + 40 + i * (w_ - 80)
            s += (f'<path d="M{lx-16:.0f},{y:.0f} q{4:.0f},{34:.0f} {-10:.0f},{46:.0f}'
                  f' q{26:.0f},{10:.0f} {46:.0f},{-4:.0f} q{-16:.0f},{-14:.0f}'
                  f' {-12:.0f},{-42:.0f} Z" fill="#cfd5da" {o(5)}/>')
            break
    s += (f'<rect x="{x+w_*.84:.0f}" y="{y-h_-150:.0f}" width="24" height="160"'
          f' rx="10" fill="#9aa3aa" {o(4)}/>'
          f'<path d="M{x+w_*.86:.0f},{y-h_-150:.0f} q{-10:.0f},{-54:.0f}'
          f' {-86:.0f},{-46:.0f}" fill="none" stroke="#9aa3aa" stroke-width="20"/>'
          f'<ellipse cx="{x+w_*.80-86:.0f}" cy="{y-h_-192:.0f}" rx="34" ry="14"'
          f' fill="#8f979d" {o(4)}/>')
    kap = (t * .7) % 1.0
    s += (f'<ellipse cx="{x+w_*.80-86:.0f}" cy="{y-h_-176+kap*120:.0f}" rx="7"'
          f' ry="{11+6*kap:.0f}" fill="#d6e8f4" opacity="{1-kap:.2f}"/>')
    s += par(x + w_ * .44, y - h_ - 10, t, 6, .62, 300, .45, 1.9)
    s += par(x + w_ * .66, y - h_ - 20, t, 5, .5, 260, .55, 1.6)
    return s


def _mochalka(x, y, s_=1.0, t=0.0, ph=.0):
    """Лыковая мочалка: жгут из светлого лыка с распушёнными концами и
    верёвочной петлёй."""
    sway = 3.0 * A.w(t, 2.6, ph)
    s = f'<g transform="rotate({sway:.1f} {x:.0f} {y:.0f})">'
    for i in range(7):
        s += (f'<path d="M{x-72*s_+i*10*s_:.0f},{y:.0f}'
              f' q{40*s_:.0f},{(-26+i*5)*s_:.0f} {120*s_:.0f},{(4-i*2)*s_:.0f}"'
              f' fill="none" stroke="{"#d8c08a" if i % 2 else "#c9ad74"}"'
              f' stroke-width="{max(4,11*s_):.0f}" stroke-linecap="round"/>')
    for e in (-1, 1):
        for j in range(5):
            s += (f'<line x1="{x+e*58*s_:.0f}" y1="{y+(-16+j*8)*s_:.0f}"'
                  f' x2="{x+e*92*s_:.0f}" y2="{y+(-24+j*12)*s_:.0f}"'
                  f' stroke="#b89a6a" stroke-width="{max(2,4*s_):.0f}"/>')
    s += (f'<circle cx="{x:.0f}" cy="{y-30*s_:.0f}" r="{18*s_:.0f}" fill="none"'
          f' stroke="#9c8a62" stroke-width="{max(3,6*s_):.0f}"/></g>')
    return s


def _mylo_v_mylnice(x, y, s_=1.0, t=0.0):
    """Мыло в мыльнице: пластмассовая ванночка с рёбрами, брусок мыла с
    фаской и мокрый блик."""
    return (f'{ten(x, y + 8 * s_, 58 * s_, 10 * s_, .4)}'
            f'<path d="M{x-62*s_:.0f},{y-26*s_:.0f} q{8*s_:.0f},{34*s_:.0f}'
            f' {62*s_:.0f},{34*s_:.0f} q{54*s_:.0f},0 {62*s_:.0f},{-34*s_:.0f} Z"'
            f' fill="#6a9cc2" {o(5)}/>'
            + "".join(f'<line x1="{x-40*s_+i*20*s_:.0f}" y1="{y-16*s_:.0f}"'
                      f' x2="{x-40*s_+i*20*s_:.0f}" y2="{y+4*s_:.0f}"'
                      f' stroke="#4e7a9c" stroke-width="{max(2,4*s_):.0f}"/>'
                      for i in range(5))
            + f'<path d="M{x-46*s_:.0f},{y-30*s_:.0f} q{8*s_:.0f},{-26*s_:.0f}'
              f' {46*s_:.0f},{-26*s_:.0f} q{40*s_:.0f},0 {46*s_:.0f},{26*s_:.0f} Z"'
              f' fill="#efe3c8" {o(4)}/>'
            + f'<path d="M{x-28*s_:.0f},{y-44*s_:.0f} q{18*s_:.0f},{-10*s_:.0f}'
              f' {40*s_:.0f},{-4*s_:.0f}" fill="none" stroke="#ffffff"'
              f' stroke-width="{7*s_:.0f}"'
              f' opacity="{.4+.3*abs(A.w(t,2.4,.3)):.2f}"/>')


def _utochka(x, y, s_=1.0, t=0.0, ph=.0):
    """Резиновая уточка: жёлтое тулово, клюв оранжевым, глаз точкой,
    покачивается на воде."""
    kol = 4.0 * A.w(t, 1.9, ph)
    r = 30 * s_
    return (f'<g transform="rotate({kol:.1f} {x:.0f} {y:.0f})">'
            f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{r*1.30:.0f}" ry="{r*.80:.0f}"'
            f' fill="#e8c64e" {o(4)}/>'
            f'<path d="M{x+r*.80:.0f},{y-r*.20:.0f} q{r*.60:.0f},{-r*.50:.0f}'
            f' {r*.30:.0f},{-r*.90:.0f}" fill="none" stroke="#e8c64e"'
            f' stroke-width="{r*.46:.0f}"/>'
            f'<circle cx="{x+r*1.02:.0f}" cy="{y-r*1.08:.0f}" r="{r*.46:.0f}"'
            f' fill="#e8c64e" {o(3)}/>'
            f'<path d="M{x+r*1.40:.0f},{y-r*1.06:.0f} l{r*.46:.0f},{r*.14:.0f}'
            f' l{-r*.44:.0f},{r*.20:.0f} Z" fill="{ORA}" {o(3)}/>'
            f'<circle cx="{x+r*1.02:.0f}" cy="{y-r*1.20:.0f}" r="{r*.09:.0f}"'
            f' fill="{K}"/>'
            f'<path d="M{x-r*1.20:.0f},{y-r*.30:.0f} q{r*.40:.0f},{-r*.40:.0f}'
            f' {r*.70:.0f},{-r*.06:.0f}" fill="none" stroke="#c9a331"'
            f' stroke-width="{max(2,5*s_):.0f}"/></g>')


def _halat_na_dveri(x, y, h_, t, ph=.0, col="#e3ddc6"):
    """Махровый халат на крючке двери: плечи, пояс висит петлёй, махровая
    фактура точками, чуть качается."""
    kach = 1.8 * A.w(t, 3.4, ph)
    s = (f'<g transform="rotate({kach:.1f} {x:.0f} {y:.0f})">'
         f'<path d="M{x-16:.0f},{y-24:.0f} q{16:.0f},{-22:.0f} {32:.0f},{-4:.0f}"'
         f' fill="none" stroke="{ZHELEZ}" stroke-width="10"/>'
         f'<path d="M{x:.0f},{y:.0f} q{-80:.0f},{20:.0f} {-96:.0f},{90:.0f}'
         f' L{x-78:.0f},{y+h_:.0f} L{x+78:.0f},{y+h_:.0f} L{x+96:.0f},{y+90:.0f}'
         f' q{-16:.0f},{-70:.0f} {-96:.0f},{-90:.0f} Z" fill="{col}" {o(6)}/>'
         f'<path d="M{x:.0f},{y+6:.0f} L{x-24:.0f},{y+h_:.0f}" fill="none"'
         f' stroke="#c9c1a6" stroke-width="12"/>'
         f'<path d="M{x:.0f},{y+6:.0f} L{x+24:.0f},{y+h_:.0f}" fill="none"'
         f' stroke="#c9c1a6" stroke-width="12"/>'
         f'<path d="M{x-70:.0f},{y+h_*.52:.0f} q{70:.0f},{18:.0f} {140:.0f},0"'
         f' fill="none" stroke="{TKAN2}" stroke-width="16"/>'
         f'<path d="M{x+60:.0f},{y+h_*.56:.0f} q{30:.0f},{70:.0f} {-10:.0f},{110:.0f}"'
         f' fill="none" stroke="{TKAN2}" stroke-width="13"/>')
    rnd = random.Random(int(x) + 7)
    for i in range(26):
        s += (f'<circle cx="{x+rnd.uniform(-82,82):.0f}"'
              f' cy="{y+rnd.uniform(30,h_-10):.0f}" r="{rnd.uniform(3,6):.0f}"'
              f' fill="#cfc7ad" opacity=".7"/>')
    return s + "</g>"


def _zerkalo_zapot(x, y, w_, h_, t, zapot=.0):
    """Зеркало над раковиной: рама, отражение кафеля полосами, запотевание
    от низа вверх и протёртая полоса пальцем — без буквы, дугой."""
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="10" fill="#cfe0e8" {o(7)}/>'
         f'<rect x="{x+14:.0f}" y="{y+14:.0f}" width="{w_-28:.0f}"'
         f' height="{h_-28:.0f}" rx="7" fill="#b9d6e8" opacity=".92"/>')
    for i in range(4):
        s += (f'<rect x="{x+24:.0f}" y="{y+30+i*(h_-56)/4.0:.0f}"'
              f' width="{w_-48:.0f}" height="{(h_-56)/6.0:.0f}" rx="5"'
              f' fill="#a4c4d8" opacity=".55"/>')
    s += (f'<path d="M{x+30:.0f},{y+40:.0f} L{x+w_*.5:.0f},{y+h_*.3:.0f}"'
          f' fill="none" stroke="#ffffff" stroke-width="12" opacity=".4"/>')
    if zapot > .02:
        s += (f'<rect x="{x+14:.0f}" y="{y+h_-14-(h_-28)*zapot:.0f}"'
              f' width="{w_-28:.0f}" height="{(h_-28)*zapot:.0f}" rx="6"'
              f' fill="#e8f1f6" opacity="{.50+.30*zapot:.2f}"/>')
        if zapot > .5:
            s += (f'<path d="M{x+w_*.26:.0f},{y+h_*.62:.0f}'
                  f' q{w_*.22:.0f},{-h_*.20:.0f} {w_*.46:.0f},{h_*.04:.0f}"'
                  f' fill="none" stroke="#9fc4d8" stroke-width="22"'
                  f' opacity=".8"/>')
    s += (f'<rect x="{x-10:.0f}" y="{y-12:.0f}" width="{w_+20:.0f}" height="20"'
          f' rx="8" fill="#9aa3aa" {o(4)}/>')
    return s


def _stopka_belya(x, y, w_, t, zavitki=True, seed=5):
    """СТОПКА ЧИСТОГО БЕЛЬЯ — главный предмет: сорочка сложенная квадратом,
    поверх неё полотенце с каймой, сверху скатанные носки клубком. От стопки
    поднимаются рисованные завитки свежести."""
    rnd = random.Random(seed)
    h2 = 0
    s = f'{ten(x + w_ * .5, y + 14, w_ * .52, 20, .45)}'
    cols = ["#efe8d8", "#e3ddc6", "#f4eedc", "#dfd6c0"]
    for i in range(4):
        hh = 44 - i * 4
        yy = y - h2 - hh
        dx = rnd.uniform(-10, 10)
        s += (f'<rect x="{x+dx+i*8:.0f}" y="{yy:.0f}" width="{w_-i*16:.0f}"'
              f' height="{hh:.0f}" rx="9" fill="{cols[i]}" {o(5)}/>'
              f'<line x1="{x+dx+i*8+14:.0f}" y1="{yy+hh*.5:.0f}"'
              f' x2="{x+dx+w_-i*16-14:.0f}" y2="{yy+hh*.5:.0f}"'
              f' stroke="#cfc7ad" stroke-width="5" opacity=".8"/>')
        h2 += hh + 4
    # полотенце с каймой поверх стопки
    s += (f'<rect x="{x+16:.0f}" y="{y-h2-50:.0f}" width="{w_-40:.0f}"'
          f' height="54" rx="10" fill="{RUSH}" {o(5)}/>'
          f'<rect x="{x+24:.0f}" y="{y-h2-34:.0f}" width="{w_-56:.0f}"'
          f' height="14" fill="{TKAN}" opacity=".85"/>'
          f'<rect x="{x+24:.0f}" y="{y-h2-50:.0f}" width="{w_-56:.0f}"'
          f' height="8" fill="{TKAN2}" opacity=".7"/>')
    # скатанные носки клубком — две шайбы с резинкой
    for i in (0, 1):
        nx = x + w_ * (.30 + i * .38)
        s += (f'<ellipse cx="{nx:.0f}" cy="{y-h2-76:.0f}" rx="44" ry="28"'
              f' fill="#8fa3c2" {o(5)}/>'
              f'<ellipse cx="{nx:.0f}" cy="{y-h2-82:.0f}" rx="32" ry="17"'
              f' fill="#a4b8d2" opacity=".9"/>')
        for j in range(3):
            s += (f'<path d="M{nx-34:.0f},{y-h2-82+j*9:.0f} q{34:.0f},{-8:.0f}'
                  f' {68:.0f},0" fill="none" stroke="#7288a8"'
                  f' stroke-width="4" opacity=".8"/>')
    if zavitki:
        for i in range(5):
            p = ((t * .5 + i / 5.0) % 1.0)
            zx = x + w_ * (.18 + i * .17)
            zy = y - h2 - 110 - p * 190
            s += (f'<path d="M{zx:.0f},{zy:.0f} q{22:.0f},{-26:.0f} {2:.0f},{-48:.0f}'
                  f' q{-22:.0f},{-22:.0f} {6:.0f},{-44:.0f}" fill="none"'
                  f' stroke="#cfe4f5" stroke-width="{8-3*p:.0f}"'
                  f' stroke-linecap="round" opacity="{(1-p)*.85:.2f}"/>')
    return s


def _shkafchiki_bani(x, y, w_, h_, t, n=5, seed=7):
    """Шкафчики раздевалки: дверцы с филёнкой, вентиляционные прорези,
    кольцо-ручка и жестяной номерок на гвоздике — номер не рисуем, на
    номерке волнистая насечка."""
    rnd = random.Random(seed)
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' fill="#8a6038" {o(7)}/>')
    dw = w_ / float(n)
    for i in range(n):
        dx = x + i * dw
        s += (f'<rect x="{dx+8:.0f}" y="{y+10:.0f}" width="{dw-16:.0f}"'
              f' height="{h_-20:.0f}" rx="9" fill="url(#dosk)" {o(5)}/>'
              f'<rect x="{dx+28:.0f}" y="{y+36:.0f}" width="{dw-56:.0f}"'
              f' height="{h_-80:.0f}" rx="7" fill="#9c7049" opacity=".85"/>')
        for j in range(3):
            s += (f'<rect x="{dx+dw*.3:.0f}" y="{y+52+j*22:.0f}"'
                  f' width="{dw*.4:.0f}" height="9" rx="4" fill="#5b4428"/>')
        s += (f'<circle cx="{dx+dw-34:.0f}" cy="{y+h_*.52:.0f}" r="13"'
              f' fill="none" stroke="{ZHELEZ}" stroke-width="8"/>')
        kol = 6.0 * A.w(t, 2.4, i * .4)
        s += (f'<g transform="rotate({kol:.1f} {dx+dw*.5:.0f} {y+h_*.18:.0f})">'
              f'<line x1="{dx+dw*.5:.0f}" y1="{y+h_*.18:.0f}"'
              f' x2="{dx+dw*.5:.0f}" y2="{y+h_*.18+30:.0f}" stroke="#8f979d"'
              f' stroke-width="4"/>'
              f'<circle cx="{dx+dw*.5:.0f}" cy="{y+h_*.18+46:.0f}" r="19"'
              f' fill="#c9ad74" {o(4)}/>'
              f'<path d="M{dx+dw*.5-10:.0f},{y+h_*.18+46:.0f} q{5:.0f},{-6:.0f}'
              f' {10:.0f},0 q{5:.0f},{6:.0f} {10:.0f},0" fill="none"'
              f' stroke="#8a7a46" stroke-width="4"/></g>')
    return s


def _taz_bannyy(x, y, s_=1.0, t=0.0, soderzh=True):
    """ОЦИНКОВАННЫЙ ТАЗ — главный предмет: конусное тулово с обручем и
    двумя ушками, оцинковка пятнами и блик дугой. Внутри лыковая мочалка,
    кусок мыла и берёзовый веник через край."""
    w2, h2 = 300 * s_, 128 * s_
    s = (f'{ten(x, y + 12 * s_, w2 * .56, 18 * s_, .5)}'
         f'<path d="M{x-w2*.5:.0f},{y-h2:.0f} q{6*s_:.0f},{h2*1.08:.0f}'
         f' {w2*.5:.0f},{h2*1.02:.0f} q{w2*.44:.0f},{2*s_:.0f}'
         f' {w2*.5:.0f},{-h2*1.02:.0f} Z" fill="#b6bcc2" {o(8)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-h2:.0f}" rx="{w2*.5:.0f}"'
         f' ry="{w2*.14:.0f}" fill="#cfd5da" {o(6)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-h2+8*s_:.0f}" rx="{w2*.43:.0f}"'
         f' ry="{w2*.11:.0f}" fill="#8f979d" opacity=".9"/>')
    rnd = random.Random(int(x) + 11)
    for i in range(9):
        s += (f'<ellipse cx="{x+rnd.uniform(-w2*.4,w2*.4):.0f}"'
              f' cy="{y+rnd.uniform(-h2*.8,-h2*.1):.0f}"'
              f' rx="{rnd.uniform(12,26)*s_:.0f}" ry="{rnd.uniform(7,15)*s_:.0f}"'
              f' fill="#c9ced4" opacity=".55"/>')
    for i in (-1, 1):
        s += (f'<path d="M{x+i*w2*.50:.0f},{y-h2+4*s_:.0f} q{i*42*s_:.0f},'
              f'{6*s_:.0f} {i*34*s_:.0f},{38*s_:.0f}" fill="none"'
              f' stroke="{ZHELEZ}" stroke-width="{13*s_:.0f}"/>')
    s += (f'<path d="M{x-w2*.36:.0f},{y-h2*.52:.0f} q{w2*.14:.0f},{h2*.40:.0f}'
          f' {w2*.30:.0f},{h2*.44:.0f}" fill="none" stroke="#eef2f4"'
          f' stroke-width="{12*s_:.0f}" opacity=".55"/>')
    if soderzh:
        s += _mochalka(x - w2 * .18, y - h2 - 6 * s_, s_ * .74, t, .2)
        s += _mylo_v_mylnice(x + w2 * .24, y - h2 + 4 * s_, s_ * .62, t)
        s += _venik(x + w2 * .40, y - h2 - 10 * s_, 230 * s_, t, "#cdbf9c",
                    "#b8352c", False, .12, .3, s_ * .72, 113)
    return s


def _stakan_podstakannik(x, y, s_=1.0, t=0.0, chay=.8, lozhka=True):
    """Гранёный стакан в подстаканнике: грани вертикальными блеснами,
    мельхиоровый подстаканник с завитком-ручкой, чай с ободком и ложечка."""
    w2, h2 = 72 * s_, 112 * s_
    s = (f'{ten(x, y + 6 * s_, w2 * .6, 9 * s_, .4)}'
         f'<path d="M{x-w2/2:.0f},{y-h2:.0f} L{x+w2/2:.0f},{y-h2:.0f}'
         f' L{x+w2*.42:.0f},{y:.0f} L{x-w2*.42:.0f},{y:.0f} Z"'
         f' fill="url(#stekl)" opacity=".9" {o(5)}/>'
         f'<path d="M{x-w2*.44:.0f},{y-h2*chay:.0f} L{x+w2*.44:.0f},{y-h2*chay:.0f}'
         f' L{x+w2*.42:.0f},{y-4*s_:.0f} L{x-w2*.42:.0f},{y-4*s_:.0f} Z"'
         f' fill="#8a4a1c" opacity=".88"/>'
         f'<ellipse cx="{x:.0f}" cy="{y-h2*chay:.0f}" rx="{w2*.44:.0f}"'
         f' ry="{w2*.11:.0f}" fill="#b5803a" opacity=".9"/>')
    for i in range(4):
        s += (f'<line x1="{x-w2*.30+i*w2*.20:.0f}" y1="{y-h2+6*s_:.0f}"'
              f' x2="{x-w2*.27+i*w2*.18:.0f}" y2="{y-6*s_:.0f}"'
              f' stroke="#ffffff" stroke-width="{max(2,4*s_):.0f}" opacity=".35"/>')
    s += (f'<path d="M{x-w2*.52:.0f},{y-h2*.70:.0f} L{x+w2*.52:.0f},{y-h2*.70:.0f}'
          f' L{x+w2*.46:.0f},{y+4*s_:.0f} L{x-w2*.46:.0f},{y+4*s_:.0f} Z"'
          f' fill="none" stroke="#b9c6cc" stroke-width="{11*s_:.0f}"/>'
          f'<path d="M{x+w2*.52:.0f},{y-h2*.54:.0f} q{44*s_:.0f},{10*s_:.0f}'
          f' {4*s_:.0f},{46*s_:.0f}" fill="none" stroke="#b9c6cc"'
          f' stroke-width="{10*s_:.0f}"/>')
    for i in range(3):
        s += (f'<circle cx="{x-w2*.30+i*w2*.30:.0f}" cy="{y-h2*.44:.0f}"'
              f' r="{6*s_:.0f}" fill="#cfd8dc" opacity=".9"/>')
    if lozhka:
        ug = 14 + 4 * A.w(t, 1.8, .2)
        s += (f'<g transform="rotate({ug:.1f} {x+w2*.2:.0f} {y-h2:.0f})">'
              f'<rect x="{x+w2*.14:.0f}" y="{y-h2-56*s_:.0f}" width="{8*s_:.0f}"'
              f' height="{78*s_:.0f}" rx="4" fill="#cfd8dc" {o(3)}/>'
              f'<ellipse cx="{x+w2*.18:.0f}" cy="{y-h2-62*s_:.0f}"'
              f' rx="{13*s_:.0f}" ry="{9*s_:.0f}" fill="#dde6ea" {o(3)}/></g>')
    s += par(x, y - h2 - 30 * s_, t, 3, .45, 120 * s_, .5)
    return s


def _sushka_odna(x, y, s_=1.0, t=0.0, makaet=.0, ug=0.0):
    """Сушка: твёрдое кольцо с маковой крошкой и блеском; когда её макают,
    низ кольца темнеет от чая и с него срывается капля."""
    r = 34 * s_
    s = (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
         f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{r:.0f}" fill="none"'
         f' stroke="#d7a860" stroke-width="{r*.52:.0f}"/>'
         f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{r:.0f}" fill="none"'
         f' stroke="{K}" stroke-width="{max(2,3.6*s_):.0f}" opacity=".9"/>'
         f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{r*.74:.0f}" fill="none"'
         f' stroke="{K}" stroke-width="{max(2,3*s_):.0f}" opacity=".7"/>')
    rnd = random.Random(int(x) + 13)
    for i in range(8):
        a = rnd.uniform(0, 6.28)
        s += (f'<circle cx="{x+math.cos(a)*r*.88:.0f}" cy="{y+math.sin(a)*r*.88:.0f}"'
              f' r="{2.6*s_:.0f}" fill="#5a3a18"/>')
    if makaet > .05:
        s += (f'<path d="M{x-r*.9:.0f},{y+r*.5:.0f} a{r:.0f},{r:.0f} 0 0 0'
              f' {r*1.8:.0f},0" fill="none" stroke="#8a4a1c"'
              f' stroke-width="{r*.44:.0f}" opacity="{makaet:.2f}"/>'
              f'<ellipse cx="{x:.0f}" cy="{y+r*1.5+18*makaet:.0f}" rx="{5*s_:.0f}"'
              f' ry="{9*s_:.0f}" fill="#8a4a1c" opacity="{makaet*.8:.2f}"/>')
    s += (f'<path d="M{x-r*.5:.0f},{y-r*.8:.0f} q{r*.4:.0f},{-r*.2:.0f}'
          f' {r*.9:.0f},{r*.1:.0f}" fill="none" stroke="#f0d8a0"'
          f' stroke-width="{max(2,5*s_):.0f}" opacity=".6"/></g>')
    return s


def _nogi_v_noskah(x, y, s_=1.0, t=0.0):
    """ДВЕ НОГИ В ПОЛОСАТЫХ НОСКАХ из-под одеяла — главный предмет: у каждой
    видно пятку, подъём, бугорок пальцев и рубчик резинки, носки в полоску
    двух цветов. Шевелятся во сне по очереди, а не вместе (иначе читаются
    цветными колбасками — R-0047)."""
    s = ""
    for i, (dx, ph) in enumerate(((-96 * s_, .0), (96 * s_, .5))):
        kol = 5.0 * A.w(t, 2.2, ph)
        nx = x + dx
        s += (f'<g transform="rotate({kol:.1f} {nx:.0f} {y-150*s_:.0f})">'
              f'{ten(nx + 20 * s_, y + 10 * s_, 86 * s_, 14 * s_, .45)}'
              f'<path d="M{nx-56*s_:.0f},{y-168*s_:.0f}'
              f' L{nx+56*s_:.0f},{y-168*s_:.0f} L{nx+60*s_:.0f},{y-40*s_:.0f}'
              f' Q{nx+66*s_:.0f},{y:.0f} {nx+116*s_:.0f},{y-6*s_:.0f}'
              f' Q{nx+140*s_:.0f},{y-14*s_:.0f} {nx+134*s_:.0f},{y-44*s_:.0f}'
              f' Q{nx+120*s_:.0f},{y-78*s_:.0f} {nx+60*s_:.0f},{y-86*s_:.0f}'
              f' L{nx-56*s_:.0f},{y-86*s_:.0f} Z" fill="#8fa3c2" {o(6)}/>')
        for j in range(7):
            yy = y - 160 * s_ + j * 22 * s_
            if yy > y - 86 * s_:
                break
            s += (f'<rect x="{nx-56*s_:.0f}" y="{yy:.0f}" width="{116*s_:.0f}"'
                  f' height="{11*s_:.0f}" fill="{"#b8323a" if j % 2 else "#efe3c8"}"'
                  f' opacity=".9"/>')
        s += (f'<path d="M{nx+58*s_:.0f},{y-76*s_:.0f} q{40*s_:.0f},{10*s_:.0f}'
              f' {72*s_:.0f},{34*s_:.0f}" fill="none" stroke="#efe3c8"'
              f' stroke-width="{12*s_:.0f}" opacity=".9"/>'
              f'<rect x="{nx-60*s_:.0f}" y="{y-176*s_:.0f}" width="{124*s_:.0f}"'
              f' height="{26*s_:.0f}" rx="{10*s_:.0f}" fill="#7288a8" {o(4)}/>')
        for j in range(5):
            s += (f'<line x1="{nx-52*s_+j*26*s_:.0f}" y1="{y-174*s_:.0f}"'
                  f' x2="{nx-52*s_+j*26*s_:.0f}" y2="{y-154*s_:.0f}"'
                  f' stroke="#5e7294" stroke-width="{max(2,4*s_):.0f}"/>')
        for j in range(3):
            s += (f'<ellipse cx="{nx+(100+j*14)*s_:.0f}" cy="{y-(26-j*6)*s_:.0f}"'
                  f' rx="{13*s_:.0f}" ry="{10*s_:.0f}" fill="#a4b8d2"'
                  f' opacity=".9"/>')
        s += "</g>"
    return s


def _oblachko_sna(x, y, s_=1.0, t=0.0, seed=3):
    """Облачко сна с банным паром: пухлая гряда пузырей, три пузырька-хвоста
    к спящему и внутри — веник с паром. Плывёт по кругу, не стоит."""
    rnd = random.Random(seed)
    hod = 26 * s_ * math.sin(t * .6)
    s = f'<g transform="translate({hod:.0f},{-8 * s_ * math.sin(t * .9):.0f})">'
    for i, (dx, dy, rr) in enumerate(((-150, 10, 74), (-60, -24, 96),
                                      (52, -14, 86), (140, 16, 66))):
        s += (f'<circle cx="{x+dx*s_:.0f}" cy="{y+dy*s_:.0f}" r="{rr*s_:.0f}"'
              f' fill="#e8f1f6" {o(5)}/>')
    s += (f'<ellipse cx="{x:.0f}" cy="{y+30*s_:.0f}" rx="{190*s_:.0f}"'
          f' ry="{54*s_:.0f}" fill="#e8f1f6" {o(5)}/>')
    s += _venik(x + 10 * s_, y + 54 * s_, 150 * s_, t, "#b8a86a", "#5a4a2e",
                False, .16, .2, s_ * .5, 117)
    s += par(x - 50 * s_, y + 10 * s_, t, 3, .5, 110 * s_, .6)
    s += "</g>"
    for i in range(3):
        s += (f'<circle cx="{x-200*s_-i*44*s_:.0f}" cy="{y+96*s_+i*40*s_:.0f}"'
              f' r="{(22-i*6)*s_:.0f}" fill="#e8f1f6" {o(3)}/>')
    return s


def _budilnik(x, y, s_=1.0, t=0.0):
    """Будильник: круглый корпус на ножках, две чашки-звонка, молоточек,
    циферблат БЕЗ цифр (своих букв не рисуем) со стрелками и секундной,
    которая идёт."""
    r = 62 * s_
    sek = (t * 60.0) % 60.0
    a_s = math.radians(sek * 6 - 90)
    s = (f'{ten(x, y + 8 * s_, r * .9, 11 * s_, .45)}'
         f'<circle cx="{x:.0f}" cy="{y-r*.9:.0f}" r="{r:.0f}" fill="#9c3a2a" {o(6)}/>'
         f'<circle cx="{x:.0f}" cy="{y-r*.9:.0f}" r="{r*.80:.0f}"'
         f' fill="#efe8d8" {o(4)}/>')
    for i in range(12):
        a = math.radians(i * 30)
        s += (f'<line x1="{x+math.cos(a)*r*.66:.0f}" y1="{y-r*.9+math.sin(a)*r*.66:.0f}"'
              f' x2="{x+math.cos(a)*r*.74:.0f}" y2="{y-r*.9+math.sin(a)*r*.74:.0f}"'
              f' stroke="{K}" stroke-width="{max(2,4*s_):.0f}"/>')
    s += (f'<line x1="{x:.0f}" y1="{y-r*.9:.0f}" x2="{x+r*.40:.0f}"'
          f' y2="{y-r*1.22:.0f}" stroke="{K}" stroke-width="{max(3,7*s_):.0f}"/>'
          f'<line x1="{x:.0f}" y1="{y-r*.9:.0f}" x2="{x-r*.16:.0f}"'
          f' y2="{y-r*1.50:.0f}" stroke="{K}" stroke-width="{max(3,6*s_):.0f}"/>'
          f'<line x1="{x:.0f}" y1="{y-r*.9:.0f}"'
          f' x2="{x+math.cos(a_s)*r*.64:.0f}"'
          f' y2="{y-r*.9+math.sin(a_s)*r*.64:.0f}" stroke="{KRAS}"'
          f' stroke-width="{max(2,4*s_):.0f}"/>'
          f'<circle cx="{x:.0f}" cy="{y-r*.9:.0f}" r="{6*s_:.0f}" fill="{K}"/>')
    for i in (-1, 1):
        s += (f'<path d="M{x+i*r*.72:.0f},{y-r*1.52:.0f} q{i*r*.34:.0f},'
              f'{-r*.30:.0f} {i*r*.10:.0f},{-r*.44:.0f}" fill="none"'
              f' stroke="#8f979d" stroke-width="{max(3,7*s_):.0f}"/>'
              f'<ellipse cx="{x+i*r*.76:.0f}" cy="{y-r*1.92:.0f}" rx="{r*.34:.0f}"'
              f' ry="{r*.22:.0f}" fill="#b9c6cc" {o(4)}/>')
    s += (f'<rect x="{x-r*.10:.0f}" y="{y-r*2.02:.0f}" width="{r*.20:.0f}"'
          f' height="{r*.30:.0f}" rx="{r*.08:.0f}" fill="#8f979d" {o(3)}/>')
    for i in (-1, 1):
        s += (f'<path d="M{x+i*r*.52:.0f},{y-r*.18:.0f} q{i*r*.14:.0f},'
              f'{r*.22:.0f} {i*r*.04:.0f},{r*.26:.0f}" fill="none"'
              f' stroke="#8f979d" stroke-width="{max(3,8*s_):.0f}"/>')
    return s


def _staya_vetra(t, n=22, seed=5, y0=120, y1=520):
    """ВЕТЕР НАРИСОВАН СТАЕЙ ВОРОБЬЁВ ИЗ ЗАВИТКОВ: у каждого тельце-запятая,
    крыло росчерком и хвост вилкой; стая несётся слева направо рваным
    строем, часть птиц мелкая, часть крупная (через одного)."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        ph = rnd.uniform(0, 1)
        p = ((t * .42 + ph) % 1.0)
        px = -220 + p * (W + 440)
        py = y0 + (y1 - y0) * rnd.random() + 22 * math.sin(t * 3 + i)
        sc = (1.5 if i % 2 == 0 else .62) * rnd.uniform(.8, 1.15)
        kr = 16 * sc * A.w(t, .36, ph)
        s += (f'<path d="M{px:.0f},{py:.0f} q{22*sc:.0f},{-12*sc:.0f}'
              f' {40*sc:.0f},{2*sc:.0f} q{-14*sc:.0f},{12*sc:.0f}'
              f' {-40*sc:.0f},{-2*sc:.0f} Z" fill="#8e9ab0" {o(3)}/>'
              f'<path d="M{px+14*sc:.0f},{py-2*sc:.0f} q{14*sc:.0f},'
              f'{-20*sc-kr:.0f} {34*sc:.0f},{-6*sc:.0f}" fill="none"'
              f' stroke="#a8b4c6" stroke-width="{max(2,4*sc):.0f}"/>'
              f'<path d="M{px:.0f},{py:.0f} l{-18*sc:.0f},{-7*sc:.0f}'
              f' l{4*sc:.0f},{7*sc:.0f} l{-16*sc:.0f},{6*sc:.0f}" fill="none"'
              f' stroke="#8e9ab0" stroke-width="{max(2,3.4*sc):.0f}"/>')
    return s


def _bereza_sognuta(x, base, h_, t, seed=3, storona=1, vetok=7):
    """Берёза, согнутая ветром в одну сторону: белый ствол с чёрными
    чечевичками, ветки свисают по ходу ветра и хлещут все вместе."""
    rnd = random.Random(seed)
    gib = (.26 + .10 * abs(A.w(t, 1.3, .2))) * storona
    vx = x + h_ * gib
    s = (f'<path d="M{x-h_*.030:.0f},{base:.0f} Q{x+h_*gib*.4:.0f},'
         f'{base-h_*.55:.0f} {vx:.0f},{base-h_:.0f}'
         f' L{vx+h_*.026:.0f},{base-h_:.0f} Q{x+h_*gib*.4+h_*.034:.0f},'
         f'{base-h_*.55:.0f} {x+h_*.030:.0f},{base:.0f} Z"'
         f' fill="#e6e2d8" {o(5)}/>')
    for i in range(9):
        yy = base - h_ * (.08 + i * .10)
        xx = x + h_ * gib * ((i + 1) / 10.0) ** 1.4
        s += (f'<path d="M{xx-h_*.022:.0f},{yy:.0f} q{h_*.014:.0f},{4:.0f}'
              f' {h_*.030:.0f},{-2:.0f}" fill="none" stroke="#2f2b26"'
              f' stroke-width="{max(2, h_*.011):.0f}" opacity=".85"/>')
    for i in range(vetok):
        p = .40 + i * (.56 / max(1, vetok - 1.0))
        bx = x + h_ * gib * p ** 1.4
        by = base - h_ * p
        dl = h_ * (.30 - .02 * i)
        hl = 14 * storona * A.w(t, .9, i * .2)
        s += (f'<path d="M{bx:.0f},{by:.0f} Q{bx+storona*dl*.6:.0f},'
              f'{by+dl*.12:.0f} {bx+storona*dl+hl:.0f},{by+dl*.52:.0f}"'
              f' fill="none" stroke="#5a564e"'
              f' stroke-width="{max(2, h_*.010):.0f}"/>')
        for j in range(4):
            s += (f'<path d="M{bx+storona*dl*(.3+j*.18):.0f},'
                  f'{by+dl*(.16+j*.10):.0f} q{storona*dl*.14:.0f},{dl*.14:.0f}'
                  f' {storona*dl*.10:.0f},{dl*.28:.0f}" fill="none"'
                  f' stroke="#4e4a44" stroke-width="{max(2, h_*.006):.0f}"/>')
    return s


def _kalitka_hlopaet(x, y, w_, h_, t, stolby=True):
    """Калитка, которая хлопает на ветру: дощатое полотнище на двух петлях,
    косина-подкос, кольцо-ручка, два столба с набалдашниками."""
    hlop = abs(math.sin(t * 2.2)) ** 2
    ug = -58.0 * hlop
    s = ""
    if stolby:
        for sx in (x - 26, x + w_ + 26):
            s += (f'<rect x="{sx-20:.0f}" y="{y-h_-30:.0f}" width="40"'
                  f' height="{h_+40:.0f}" rx="9" fill="#5a4530" {o(5)}/>'
                  f'<path d="M{sx-26:.0f},{y-h_-30:.0f} q{26:.0f},{-26:.0f}'
                  f' {52:.0f},0 Z" fill="#6b5340" {o(4)}/>')
    s += f'<g transform="rotate({ug:.1f} {x:.0f} {y-h_*.5:.0f})">'
    for i in range(5):
        s += (f'<rect x="{x+6+i*(w_-12)/5.0:.0f}" y="{y-h_:.0f}"'
              f' width="{(w_-12)/5.0-7:.0f}" height="{h_:.0f}" rx="6"'
              f' fill="url(#derev)" {o(4)}/>')
    for p in (.22, .78):
        s += (f'<rect x="{x:.0f}" y="{y-h_+h_*p:.0f}" width="{w_:.0f}"'
              f' height="16" rx="6" fill="#7d5636" {o(4)}/>')
    s += (f'<line x1="{x+4:.0f}" y1="{y-10:.0f}" x2="{x+w_-4:.0f}"'
          f' y2="{y-h_+20:.0f}" stroke="#7d5636" stroke-width="16"/>'
          f'<circle cx="{x+w_-24:.0f}" cy="{y-h_*.52:.0f}" r="14" fill="none"'
          f' stroke="{ZHELEZ}" stroke-width="7"/>'
          f'<rect x="{x-10:.0f}" y="{y-h_*.80:.0f}" width="34" height="16"'
          f' rx="6" fill="{ZHELEZ}" {o(3)}/>'
          f'<rect x="{x-10:.0f}" y="{y-h_*.24:.0f}" width="34" height="16"'
          f' rx="6" fill="{ZHELEZ}" {o(3)}/></g>')
    return s


def _gorshok_letit(x, y, t, s_=1.0, k=.0, seed=5):
    """Глиняный горшок, слетающий с забора: тулово с венчиком и поливой,
    летит по дуге и кувыркается; за ним пыль с кола."""
    px = x + k * 420
    py = y - math.sin(k * 3.14) * 170 + k * 60
    ug = k * 420
    r = 44 * s_
    s = (f'<g transform="rotate({ug:.0f} {px:.0f} {py:.0f})">'
         f'<path d="M{px-r:.0f},{py-r*.30:.0f} q{r*.10:.0f},{r*1.00:.0f}'
         f' {r*1.0:.0f},{r*1.00:.0f} q{r*.90:.0f},0 {r*1.0:.0f},{-r*1.00:.0f} Z"'
         f' fill="url(#glina)" {o(6)}/>'
         f'<ellipse cx="{px:.0f}" cy="{py-r*.30:.0f}" rx="{r:.0f}"'
         f' ry="{r*.28:.0f}" fill="#b08050" {o(5)}/>'
         f'<ellipse cx="{px:.0f}" cy="{py-r*.26:.0f}" rx="{r*.78:.0f}"'
         f' ry="{r*.20:.0f}" fill="#4a3a2a" opacity=".9"/>'
         f'<path d="M{px-r*.92:.0f},{py+r*.14:.0f} q{r*.92:.0f},{r*.26:.0f}'
         f' {r*1.84:.0f},0" fill="none" stroke="{KREM}"'
         f' stroke-width="{8*s_:.0f}" opacity=".7"/></g>')
    if k < .3:
        for i in range(5):
            s += (f'<circle cx="{x+i*12:.0f}" cy="{y+16+i*6:.0f}"'
                  f' r="{7-i:.0f}" fill="#cfd6de" opacity="{(.3-k)*2:.2f}"/>')
    return s


def _tulup_na_gvozde(x, y, h_, t, ph=.0, shapka=True):
    """Тулуп и шапка на гвозде: овчинная опушка по вороту, запах полой,
    рукава висят, подол вздрагивает от сквозняка."""
    drog = 2.6 * A.w(t, 2.2, ph) + 1.4 * A.w(t, 7.0, ph)
    s = (f'<g transform="rotate({drog:.1f} {x:.0f} {y:.0f})">'
         f'<rect x="{x-20:.0f}" y="{y-22:.0f}" width="40" height="14" rx="6"'
         f' fill="{ZHELEZ}" {o(3)}/>'
         f'<path d="M{x:.0f},{y:.0f} q{-96:.0f},{26:.0f} {-110:.0f},{110:.0f}'
         f' L{x-96:.0f},{y+h_:.0f} L{x+96:.0f},{y+h_:.0f} L{x+110:.0f},{y+110:.0f}'
         f' q{-14:.0f},{-84:.0f} {-110:.0f},{-110:.0f} Z" fill="#6b5340" {o(7)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y+8:.0f}" rx="64" ry="24" fill="#cfc1a4"'
         f' {o(5)}/>'
         f'<path d="M{x:.0f},{y+22:.0f} L{x+22:.0f},{y+h_:.0f}" fill="none"'
         f' stroke="#4e3c2c" stroke-width="12"/>'
         f'<path d="M{x-104:.0f},{y+96:.0f} q{-26:.0f},{86:.0f} {-6:.0f},{140:.0f}'
         f' q{30:.0f},{16:.0f} {46:.0f},{-14:.0f}" fill="#5e4a38" {o(5)}/>'
         f'<path d="M{x+104:.0f},{y+96:.0f} q{26:.0f},{86:.0f} {6:.0f},{140:.0f}'
         f' q{-30:.0f},{16:.0f} {-46:.0f},{-14:.0f}" fill="#5e4a38" {o(5)}/>'
         f'<rect x="{x-96:.0f}" y="{y+h_-30:.0f}" width="192" height="26"'
         f' rx="9" fill="#cfc1a4" opacity=".85"/></g>')
    if shapka:
        s += (f'<g transform="rotate({-drog:.1f} {x+170:.0f} {y-10:.0f})">'
              f'<rect x="{x+150:.0f}" y="{y-28:.0f}" width="40" height="14"'
              f' rx="6" fill="{ZHELEZ}" {o(3)}/>'
              f'<path d="M{x+118:.0f},{y+48:.0f} q{52:.0f},{-72:.0f}'
              f' {104:.0f},0 q{-20:.0f},{26:.0f} {-104:.0f},0 Z" fill="#4a3f36"'
              f' {o(5)}/>'
              f'<ellipse cx="{x+170:.0f}" cy="{y+50:.0f}" rx="56" ry="20"'
              f' fill="#cfc1a4" {o(4)}/></g>')
    return s


def _volny_zvuka(x, y, t, n=4, ug=0.0, dl=260, col="#cfe4f5"):
    """Волны звука от стены к уху: три-четыре дуги разного радиуса бегут
    одна за другой и гаснут на подходе."""
    s = ""
    for i in range(n):
        p = ((t * 1.3 + i / float(n)) % 1.0)
        r = dl * (.22 + .78 * p)
        s += (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
              f'<path d="M{x:.0f},{y-r*.62:.0f} A{r:.0f},{r*.62:.0f} 0 0 1'
              f' {x:.0f},{y+r*.62:.0f}" fill="none" stroke="{col}"'
              f' stroke-width="{11-6*p:.0f}" opacity="{(1-p)*.8:.2f}"/></g>')
    return s


def _pryalka(x, y, t, s_=1.0, kruzh=True):
    """Прялка с колесом: станина на трёх ножках, большое колесо со спицами,
    стойка с куделью и шнур привода. Колесо медленно крутится."""
    r = 110 * s_
    ug = (t * 40.0) % 360.0
    s = (f'{ten(x, y + 8 * s_, 110 * s_, 14 * s_, .45)}'
         f'<rect x="{x-110*s_:.0f}" y="{y-40*s_:.0f}" width="{230*s_:.0f}"'
         f' height="{26*s_:.0f}" rx="{10*s_:.0f}" fill="url(#dosk)" {o(6)}/>')
    for i in (-1, 0, 1):
        s += (f'<rect x="{x+i*92*s_-9*s_:.0f}" y="{y-16*s_:.0f}"'
              f' width="{18*s_:.0f}" height="{22*s_:.0f}" rx="{7*s_:.0f}"'
              f' fill="#5b4428" {o(4)}/>')
    if kruzh:
        s += f'<g transform="rotate({ug:.1f} {x-40*s_:.0f} {y-r-24*s_:.0f})">'
        s += (f'<circle cx="{x-40*s_:.0f}" cy="{y-r-24*s_:.0f}" r="{r:.0f}"'
              f' fill="none" stroke="#8a6038" stroke-width="{14*s_:.0f}"/>'
              f'<circle cx="{x-40*s_:.0f}" cy="{y-r-24*s_:.0f}" r="{r*.14:.0f}"'
              f' fill="#7d5636" {o(4)}/>')
        for i in range(8):
            a = math.radians(i * 45)
            s += (f'<line x1="{x-40*s_:.0f}" y1="{y-r-24*s_:.0f}"'
                  f' x2="{x-40*s_+math.cos(a)*r*.92:.0f}"'
                  f' y2="{y-r-24*s_+math.sin(a)*r*.92:.0f}" stroke="#9c7049"'
                  f' stroke-width="{max(3,7*s_):.0f}"/>')
        s += "</g>"
    s += (f'<rect x="{x+76*s_:.0f}" y="{y-240*s_:.0f}" width="{18*s_:.0f}"'
          f' height="{212*s_:.0f}" rx="{8*s_:.0f}" fill="#8a6038" {o(5)}/>'
          f'<path d="M{x+86*s_:.0f},{y-240*s_:.0f} q{-46*s_:.0f},{-50*s_:.0f}'
          f' {-10*s_:.0f},{-96*s_:.0f} q{46*s_:.0f},{34*s_:.0f} {10*s_:.0f},{96*s_:.0f} Z"'
          f' fill="#e2d6c2" {o(4)}/>')
    for i in range(5):
        s += (f'<path d="M{x+72*s_+i*6*s_:.0f},{y-290*s_:.0f} q{-14*s_:.0f},'
              f'{-30*s_:.0f} {-4*s_:.0f},{-56*s_:.0f}" fill="none"'
              f' stroke="#cfc7ad" stroke-width="{max(2,4*s_):.0f}"/>')
    s += (f'<line x1="{x-40*s_:.0f}" y1="{y-r-24*s_:.0f}" x2="{x+84*s_:.0f}"'
          f' y2="{y-200*s_:.0f}" stroke="#4e4a44" stroke-width="{max(2,4*s_):.0f}"/>')
    return s


def _lar_kovanyy(x, y, w_, h_, t, seed=3):
    """Кованый ларь: толстые доски, железные полосы с заклёпками, накладной
    замок с пробоем и кольцо-ручка по боку."""
    s = (f'{ten(x + w_ * .5, y + 10, w_ * .52, 18, .5)}'
         f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="10" fill="url(#dosk)" {o(8)}/>'
         f'<path d="M{x-10:.0f},{y-h_:.0f} q{w_*.5:.0f},{-54:.0f} {w_+20:.0f},0 Z"'
         f' fill="#8a6038" {o(6)}/>')
    for i in range(4):
        s += (f'<line x1="{x+10:.0f}" y1="{y-h_+28+i*(h_-34)/4.0:.0f}"'
              f' x2="{x+w_-10:.0f}" y2="{y-h_+28+i*(h_-34)/4.0:.0f}"'
              f' stroke="#5b4428" stroke-width="6" opacity=".8"/>')
    for i in range(3):
        bx = x + 30 + i * (w_ - 90) / 2.0
        s += (f'<rect x="{bx:.0f}" y="{y-h_-18:.0f}" width="34"'
              f' height="{h_+22:.0f}" rx="7" fill="#4e4a47" {o(4)}/>')
        for j in range(4):
            s += (f'<circle cx="{bx+17:.0f}" cy="{y-h_+16+j*(h_-26)/3.0:.0f}"'
                  f' r="6" fill="#8f979d"/>')
    s += (f'<rect x="{x+w_*.46:.0f}" y="{y-h_*.56:.0f}" width="{w_*.14:.0f}"'
          f' height="{h_*.26:.0f}" rx="8" fill="#5f5a56" {o(5)}/>'
          f'<path d="M{x+w_*.50:.0f},{y-h_*.56:.0f} q{w_*.03:.0f},{-28:.0f}'
          f' {w_*.06:.0f},0" fill="none" stroke="#8f979d" stroke-width="11"/>'
          f'<circle cx="{x+w_*.53:.0f}" cy="{y-h_*.44:.0f}" r="7" fill="#2a2726"/>'
          f'<circle cx="{x+w_-26:.0f}" cy="{y-h_*.52:.0f}" r="16" fill="none"'
          f' stroke="{ZHELEZ}" stroke-width="8"/>')
    return s


def _kadka_kvashni(x, y, s_=1.0, t=0.0):
    """Кадка с квашнёй: клёпки с обручами, тесто подошло горбом и дышит,
    поверх марля и деревянный гнёт-кружок рядом."""
    w2, h2 = 170 * s_, 150 * s_
    dysh = 10 * s_ * abs(A.w(t, 1.5, .2))
    s = (f'{ten(x, y + 10 * s_, w2 * .56, 15 * s_, .5)}'
         f'<path d="M{x-w2/2:.0f},{y-h2:.0f} q{-10*s_:.0f},{h2*.5:.0f}'
         f' {4*s_:.0f},{h2:.0f} L{x+w2/2-4*s_:.0f},{y:.0f}'
         f' q{14*s_:.0f},{-h2*.5:.0f} {4*s_:.0f},{-h2:.0f} Z"'
         f' fill="url(#derev)" {o(7)}/>')
    for i in range(6):
        s += (f'<line x1="{x-w2*.44+i*w2*.18:.0f}" y1="{y-h2+6*s_:.0f}"'
              f' x2="{x-w2*.46+i*w2*.19:.0f}" y2="{y-6*s_:.0f}"'
              f' stroke="#5b4428" stroke-width="{max(3,5*s_):.0f}" opacity=".8"/>')
    for p in (.26, .78):
        s += (f'<rect x="{x-w2*.54:.0f}" y="{y-h2+h2*p:.0f}" width="{w2*1.08:.0f}"'
              f' height="{15*s_:.0f}" rx="6" fill="{ZHELEZ}" {o(4)}/>')
    s += (f'<ellipse cx="{x:.0f}" cy="{y-h2:.0f}" rx="{w2*.5:.0f}"'
          f' ry="{w2*.16:.0f}" fill="#8a6038" {o(5)}/>'
          f'<path d="M{x-w2*.46:.0f},{y-h2:.0f} q{w2*.24:.0f},{-56*s_-dysh:.0f}'
          f' {w2*.92:.0f},0 Z" fill="#efe3c8" {o(5)}/>'
          f'<path d="M{x-w2*.30:.0f},{y-h2-28*s_-dysh*.6:.0f} q{w2*.14:.0f},'
          f'{-14*s_:.0f} {w2*.30:.0f},{-2*s_:.0f}" fill="none" stroke="#fffaf0"'
          f' stroke-width="{8*s_:.0f}" opacity=".6"/>'
          f'<path d="M{x-w2*.52:.0f},{y-h2+6*s_:.0f} q{w2*.26:.0f},{-34*s_:.0f}'
          f' {w2*1.04:.0f},{2*s_:.0f}" fill="none" stroke="#e8f1f6"'
          f' stroke-width="{7*s_:.0f}" opacity=".5"/>'
          f'<ellipse cx="{x+w2*.72:.0f}" cy="{y-18*s_:.0f}" rx="{w2*.22:.0f}"'
          f' ry="{w2*.07:.0f}" fill="url(#dosk)" {o(4)}/>')
    return s


def _puchki_trav(x, y, n=4, t=0.0, seed=5, step=108):
    """Пучки сушёных трав на стене: перевязь, стебли вниз, сухие соцветия,
    пара листьев отпала. Шевелятся от сквозняка."""
    rnd = random.Random(seed)
    s = ""
    for i in range(n):
        px = x + i * step
        kach = 2.4 * A.w(t, 2.6, i * .4)
        s += (f'<g transform="rotate({kach:.1f} {px:.0f} {y:.0f})">'
              f'<rect x="{px-6:.0f}" y="{y-16:.0f}" width="12" height="14"'
              f' rx="4" fill="{ZHELEZ}"/>'
              f'<rect x="{px-22:.0f}" y="{y-6:.0f}" width="44" height="22"'
              f' rx="8" fill="#b8a86a" {o(3)}/>')
        for j in range(7):
            a = math.radians(66 + (j - 3) * 11)
            dl = rnd.uniform(96, 150)
            s += (f'<path d="M{px:.0f},{y+14:.0f} Q{px+dl*.5*math.cos(a)+8:.0f},'
                  f'{y+14+dl*.5*math.sin(a):.0f} {px+dl*math.cos(a):.0f},'
                  f'{y+14+dl*math.sin(a):.0f}" fill="none" stroke="#7b8450"'
                  f' stroke-width="{rnd.uniform(4,7):.0f}"/>'
                  f'<ellipse cx="{px+dl*math.cos(a):.0f}"'
                  f' cy="{y+14+dl*math.sin(a):.0f}" rx="9" ry="13"'
                  f' fill="#9ca86a" opacity=".9"/>')
        s += "</g>"
    return s


def _kontur_televizora(x, y, w_, h_, t, prost=.0, diktor=True):
    """Прозрачный КОНТУР телевизора, который проступает на миг и тает: сам
    ящик нарисован ЛИНИЯМИ (не мутным пятном), внутри — контур диктора в
    галстуке, рот открывается. Плотность кадра держат настоящие вещи, этот
    контур только проступает."""
    op = prost
    if op <= .01:
        return ""
    s = (f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="16" fill="none" stroke="#9fd8f0" stroke-width="9"'
         f' opacity="{op*.9:.2f}"/>'
         f'<rect x="{x+22:.0f}" y="{y-h_+22:.0f}" width="{w_-100:.0f}"'
         f' height="{h_-44:.0f}" rx="22" fill="none" stroke="#9fd8f0"'
         f' stroke-width="7" opacity="{op*.8:.2f}"/>')
    for i in range(2):
        s += (f'<circle cx="{x+w_-40:.0f}" cy="{y-h_+60+i*54:.0f}" r="15"'
              f' fill="none" stroke="#9fd8f0" stroke-width="6"'
              f' opacity="{op*.8:.2f}"/>')
    for i in (0, 1):
        s += (f'<line x1="{x+w_*(.26+i*.4):.0f}" y1="{y:.0f}"'
              f' x2="{x+w_*(.22+i*.44):.0f}" y2="{y+44:.0f}" stroke="#9fd8f0"'
              f' stroke-width="7" opacity="{op*.8:.2f}"/>')
    s += (f'<line x1="{x+w_*.78:.0f}" y1="{y-h_:.0f}" x2="{x+w_*.92:.0f}"'
          f' y2="{y-h_-120:.0f}" stroke="#9fd8f0" stroke-width="6"'
          f' opacity="{op*.7:.2f}"/>'
          f'<line x1="{x+w_*.78:.0f}" y1="{y-h_:.0f}" x2="{x+w_*.62:.0f}"'
          f' y2="{y-h_-108:.0f}" stroke="#9fd8f0" stroke-width="6"'
          f' opacity="{op*.7:.2f}"/>')
    if diktor:
        cx, cy = x + w_ * .38, y - h_ * .52
        rot = 6 + 12 * abs(A.w(t, 1.1, .2))
        s += (f'<circle cx="{cx:.0f}" cy="{cy-56:.0f}" r="40" fill="none"'
              f' stroke="#9fd8f0" stroke-width="7" opacity="{op*.9:.2f}"/>'
              f'<path d="M{cx-66:.0f},{y-h_*.12:.0f} q{10:.0f},{-86:.0f}'
              f' {66:.0f},{-92:.0f} q{56:.0f},{6:.0f} {66:.0f},{92:.0f}"'
              f' fill="none" stroke="#9fd8f0" stroke-width="7"'
              f' opacity="{op*.9:.2f}"/>'
              f'<path d="M{cx-16:.0f},{cy-20:.0f} L{cx:.0f},{cy+6:.0f}'
              f' L{cx+16:.0f},{cy-20:.0f}" fill="none" stroke="#9fd8f0"'
              f' stroke-width="6" opacity="{op*.9:.2f}"/>'
              f'<path d="M{cx:.0f},{cy+6:.0f} l{-11:.0f},{44:.0f} l{11:.0f},{18:.0f}'
              f' l{11:.0f},{-18:.0f} Z" fill="none" stroke="#9fd8f0"'
              f' stroke-width="6" opacity="{op*.9:.2f}"/>'
              f'<ellipse cx="{cx:.0f}" cy="{cy-42:.0f}" rx="13" ry="{rot:.0f}"'
              f' fill="none" stroke="#9fd8f0" stroke-width="5"'
              f' opacity="{op*.9:.2f}"/>'
              f'<circle cx="{cx-16:.0f}" cy="{cy-68:.0f}" r="5" fill="#9fd8f0"'
              f' opacity="{op*.9:.2f}"/>'
              f'<circle cx="{cx+16:.0f}" cy="{cy-68:.0f}" r="5" fill="#9fd8f0"'
              f' opacity="{op*.9:.2f}"/>')
    return s


# ── ДЕКОРАЦИИ, ВТОРАЯ ПАРТИЯ ──────────────────────────────────────────────

def drova_v_bannoy_pechi(t):
    """Предбанник: чугунная дверца банной печи крупно, рядом поленница,
    кочерга, ведро, лавка с вениками. Хозяин в вязаной шапке присел у печи:
    левой рукой в рукавице придерживает открытую створку, правой закладывает
    в топку берёзовое полено, отблеск огня ложится на лицо и бороду."""
    rnd = random.Random(503)
    pol = 1010
    s = f'<rect width="{W}" height="{H}" fill="#1e1510"/>'
    s += SL(Z_DAL, brevna(0, 40, 980, pol - 40, 92)
            + brevna(980, 40, 940, pol - 40, 92))
    s += SL(Z_DAL, _stennoe_hozyaystvo(1600, 240, t, 505))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-20:.0f}" width="{W}" height="{H-pol+20:.0f}"'
                   f' fill="#4a3a2a"/>' + polovicy(pol + 14)
            + _pol_shvy(pol + 16, 1074, 507, 6, "#3a2c1e"))
    # ГЛАВНЫЙ ПРЕДМЕТ: чугунная дверца с топкой, створка открыта и закрывается
    otkr = 1.0 - A.ease(A.seg(t, 1.5, .9))
    s += SL(Z_SRED, _dverca_pechi(360, 790, 440, 420, t, otkr, 509))
    s += SL(Z_SRED, dym(520, 330, t, 4, .24, 230, .26, "#cfd6de", 1.2))
    s += SL(Z_SRED, iskra_let(t, 560, 650, 8, 511, 240, .6))
    # обстановка предбанника
    s += SL(Z_SRED, _polenica(880, pol - 8, 420, 300, 513, 27))
    s += SL(Z_SRED, _ugol_pechnoy_utvari(1340, pol, t, 515))
    s += SL(Z_SRED, _lavka_krupno(1620, pol, 400, t, 160, True))
    for i in range(3):
        s += SL(Z_SRED, _venik(1520 + i * 92, pol - 162, 210, t, "#cdbf9c",
                               "#b8352c", False, .12, i * .3, .7, 517 + i))
    s += SL(Z_SRED, _dvorovaya_utvar(1180, pol + 46, 240, t, 519, ["vedro"]))
    # ОДНА ФИГУРА: присел у печи, обе руки наружу влево
    gx, gy, gh = 980, pol, 660
    zak = A.ease(A.seg(t, .3, 1.1))
    hoz = figura(gx, gy, gh, t, col="#4e4036", kant="#ffd98a", ph=.3,
                 shapka=True, boroda=True, naklon=8.0)
    r1, (a1x, a1y), _ = _ruka_so_sgibom(gx, gy, gh, -1, gh * .24, 10,
                                        gh * .26, 28, t, "#4e4036",
                                        "#ffd98a", .2, 4.0)
    r2, (a2x, a2y), _ = _ruka_so_sgibom(gx, gy, gh, -1, gh * .24, 34,
                                        gh * .26, 52 - 16 * zak, t,
                                        "#4e4036", "#ffd98a", .7, 5.0)
    hoz += r1 + r2
    s += SL(Z_SRED, hoz)
    # РУКАВИЦА на левой кисти придерживает створку: перекрытие по кромке
    s += SL(Z_SRED, _varezhka(a1x, a1y + 2, gh, t, .2, "#c9ad74", "#8a7a46"))
    # ПОЛЕНО уходит в топку из правой кисти
    plx = a2x - 60 - 180 * zak
    s += SL(Z_SRED, _poleno(plx, a2y + 26, 1.0, -8 + 14 * zak, True))
    s += SL(Z_SRED, _varezhka(a2x, a2y + 4, gh, t, .7, "#c9ad74", "#8a7a46"))
    # ОТБЛЕСК ОГНЯ на лице и бороде — тёплое пятно одно, от печи
    s += SL(Z_SRED, teplo(gx - gh * .22, gy - gh * .82, 180, 150,
                          .32 + .22 * abs(A.w(t, 1.1, .2))))
    s += SL(Z_SRED, teplo(580, 700, 560, 440, .44))
    # нижняя треть
    s += SL(Z_SRED, _polovik(1060, pol + 40, 480, 110, "#cdbf9c", "#b8352c")
            + _sledy(1880, 1066, 1240, pol + 30, 7, 521, "#3a2c1e", 1.1)
            + _kot_zhivoy(1480, pol + 54, t, 1.0, "#3b3430", .4)
            + _valenki_u_dveri(240, pol + 40, 1.1, t))
    s += SL(Z_PERED, _stolb_pered(1892, 118, "#150f0a", 0, H))
    s += vinetka(.44)
    return s


def vanna_s_parom(t):
    """Городская ванная: белая ванна крупно, над ней густой пар, на бортике
    мочалка, мыло в мыльнице, резиновая уточка, на двери махровый халат.
    Видна одна рука до локтя: пробует ладонью пар над ванной и вешает на
    крючок полотенце. Зеркало над раковиной запотевает."""
    rnd = random.Random(523)
    pol = 1012
    zapot = A.ease(A.seg(t, .5, 2.4))
    s = f'<rect width="{W}" height="{H}" fill="#39434a"/>'
    s += SL(Z_DAL, _kafel(0, 40, 1920, 720, t, 525, "#cfdcdc", "#a0b0b0"))
    s += SL(Z_DAL, tusklaya_lampochka(640, 20, t, 1.0, True))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="{H-pol+18:.0f}"'
                   f' fill="#8f9c9c"/>' + _kafel(0, pol - 10, 1920, 110, t, 527,
                                                 "#b8c4c4", "#8f9c9c"))
    # дверь с махровым халатом и раковина с зеркалом
    s += SL(Z_DAL, dver(1540, 180, 360, 790, .0, "#cfd8dc", True, False))
    s += SL(Z_SRED, _halat_na_dveri(1700, 300, 420, t, .2, "#e3ddc6"))
    s += SL(Z_SRED, f'<rect x="100" y="640" width="330" height="48" rx="14"'
                    f' fill="#eef2f4" {o(6)}/>'
            + f'<ellipse cx="265" cy="664" rx="120" ry="32" fill="#dde6ea" {o(4)}/>'
            + f'<ellipse cx="265" cy="668" rx="96" ry="22" fill="#b9c6cc"'
              f' opacity=".9"/>'
            + f'<rect x="240" y="688" width="50" height="{pol-688:.0f}" rx="12"'
              f' fill="#cfd5da" {o(4)}/>'
            + f'<rect x="248" y="560" width="22" height="86" rx="10"'
              f' fill="#9aa3aa" {o(4)}/>'
            + f'<path d="M258,560 q0,-40 56,-36" fill="none" stroke="#9aa3aa"'
              f' stroke-width="20"/>')
    s += SL(Z_SRED, _zerkalo_zapot(110, 180, 330, 360, t, zapot))
    # ГЛАВНЫЙ ПРЕДМЕТ: ванна с водой и паром
    s += SL(Z_SRED, _vanna(520, pol - 6, 900, t, 260))
    # на бортике: мочалка, мыло, уточка
    s += SL(Z_SRED, _mochalka(640, pol - 272, 1.0, t, .2))
    s += SL(Z_SRED, _mylo_v_mylnice(870, pol - 262, 1.05, t))
    s += SL(Z_SRED, _utochka(1120, pol - 250, 1.15, t, .4))
    s += SL(Z_SRED, _polotence(1430, 420, 300, t, .4, "#e3ddc6", True))
    # РУКА ДО ЛОКТЯ над бортиком, без человека (nichya=True)
    ves = A.ease(A.seg(t, 1.6, 1.3))
    rk, (ex, ey) = rukav(1400, 1074, 330, -104 + 16 * ves, t, "#c2a07a",
                         "#e8d8c0", .3, 5.0, True)
    s += SL(Z_SRED, rk)
    # ладонь пробует пар: варежка перекрывает полотенце, когда вешает
    s += SL(Z_SRED, _polotence(ex - 28, ey - 10, 210 + 60 * ves, t, .2,
                               "#efe3c8", False))
    s += SL(Z_SRED, _varezhka(ex, ey, 760, t, .3, "#e8d8c0", "#b89a74"))
    s += SL(Z_SRED, par(ex - 20, ey - 40, t, 4, .52, 170, .6, 1.3))
    # нижняя треть
    s += SL(Z_SRED, _polovik(760, pol + 44, 520, 110, "#6a9cc2", "#3f5c7a")
            + _dvorovaya_utvar(1300, pol + 50, 230, t, 529, ["vedro"])
            + _gorodskoy_hlam(170, pol + 42, 260, t, 531, ["yaschik"])
            + _utochka(980, pol + 34, .9, t, .7))
    s += SL(Z_SRED, teplo(900, pol - 280, 520, 300, .28))
    s += SL(Z_LETIT, par(760, 560, t, 5, .40, 320, .35, 2.1))
    s += SL(Z_PERED, _stolb_pered(-8, 100, "#20262a", 0, H))
    s += vinetka(.40)
    return s


def chistoe_bele_i_pervyy_sneg(t):
    """Спальня: на кровати стопка чистого белья крупно — сорочка, носки,
    полотенце, от стопки поднимаются завитки свежести. Женщина в халате с
    полотенцем-тюрбаном левой рукой придерживает тюрбан, правой открывает
    створку окна, за которым падает первый снег. Рядом трюмо, гребень,
    флакон."""
    rnd = random.Random(533)
    pol = 1014
    s = f'<rect width="{W}" height="{H}" fill="#2d3238"/>'
    s += SL(Z_DAL, _stena_gornicy(t, 535, True, 740, True))
    s += SL(Z_DAL, _ramki_na_stene(700, 130, 420, t, 537, 3))
    s += SL(Z_DAL, _polka_s_utvaryu(150, 170, 500, t, 551, 5)
            + _knizhnaya_polka(700, 400, 480, t, 553, 2, 150))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="{H-pol+18:.0f}"'
                   f' fill="#5e4a34"/>' + polovicy(pol + 14)
            + _pol_shvy(pol + 16, 1074, 539, 6, "#4a3824"))
    # ОКНО со створкой, которая открывается, и первым снегом за ним
    stv = A.ease(A.seg(t, 1.4, 1.6))
    s += SL(Z_DAL, okno_izby(1260, 160, 560, 470, t,
                             f'<rect x="1260" y="160" width="560" height="470"'
                             f' fill="{SUMER}"/>'
                             + "".join(f'<rect x="{1300+i*104:.0f}" y="440"'
                                       f' width="60" height="48" rx="5"'
                                       f' fill="{SVET}"'
                                       f' opacity="{.4+.25*abs(A.w(t,2.2,i*.4)):.2f}"/>'
                                       for i in range(5))
                             + f'<rect x="1260" y="500" width="560" height="130"'
                               f' fill="{SNEG}" opacity=".72"/>',
                             .12, False, True))
    s += SL(Z_SRED, f'<g transform="rotate({-36 * stv:.1f} 1540 400)">'
                    f'<rect x="1540" y="180" width="270" height="430" rx="8"'
                    f' fill="none" stroke="#6a5030" stroke-width="26"/>'
                    f'<rect x="1548" y="188" width="254" height="414" rx="6"'
                    f' fill="{STEKLO}" opacity="{.30-.18*stv:.2f}"/>'
                    f'<line x1="1675" y1="188" x2="1675" y2="602"'
                    f' stroke="#6a5030" stroke-width="16"/></g>')
    s += SL(Z_LETIT, mokryy_sneg(t, 30, 541, .62, .9))
    # КРОВАТЬ и ГЛАВНЫЙ ПРЕДМЕТ: стопка чистого белья
    s += SL(Z_SRED, _krovat(90, pol, 1010, t, 543, True, 320))
    s += SL(Z_SRED, _podushka(300, 710, 320, 190, t, .3, .2, .0))
    s += SL(Z_SRED, _stopka_belya(440, 700, 460, t, True, 545))
    # трюмо с гребнем и флаконом
    s += SL(Z_SRED, _tryumo(990, pol, 420, 560, t, 547))
    s += SL(Z_SRED, f'<path d="M1046,{pol-566:.0f} l96,0 l0,24 l-96,0 Z"'
                    f' fill="#c9ad74" {o(4)}/>'
            + "".join(f'<line x1="{1052+i*11:.0f}" y1="{pol-542:.0f}"'
                      f' x2="{1052+i*11:.0f}" y2="{pol-520:.0f}"'
                      f' stroke="#c9ad74" stroke-width="5"/>' for i in range(9))
            + f'<rect x="1180" y="{pol-592:.0f}" width="52" height="66" rx="10"'
              f' fill="#b8323a" opacity=".9" {o(4)}/>'
            + f'<rect x="1196" y="{pol-606:.0f}" width="20" height="18" rx="6"'
              f' fill="{ZOL}" {o(3)}/>')
    s += SL(Z_SRED, svecha(900, pol - 580, t, .2, 1.2, 108)
            + teplo(900, pol - 640, 230, 200, .36))
    # ОДНА ФИГУРА: левая держит тюрбан, правая открывает створку
    zx, zy, zh = 1430, pol, 760
    plech_r = A.ease(A.seg(t, 2.6, 1.0))
    zhen = figura(zx, zy, zh, t, col="#b8323a", kant="#cfe4f5", ph=.4,
                  naklon=3.0 - 2.0 * plech_r)
    r1, (b1x, b1y), _ = _ruka_so_sgibom(zx, zy, zh, -1, zh * .20, -28,
                                        zh * .20, -52, t, "#b8323a",
                                        "#cfe4f5", .2, 4.0)
    r2, (b2x, b2y), _ = _ruka_mimo(zx, zy, zh, 1, zh * .42, -14 - 20 * stv, t,
                                   "#b8323a", "#cfe4f5", .7, 5.0)
    zhen += r1 + r2
    s += SL(Z_SRED, zhen)
    # ТЮРБАН из полотенца на голове — отдельный виток поверх убора
    gy_ = zy - zh * .845
    s += SL(Z_SRED, f'<path d="M{zx-zh*.105:.0f},{gy_-zh*.095:.0f}'
                    f' q{zh*.105:.0f},{-zh*.105:.0f} {zh*.21:.0f},0'
                    f' q{-zh*.02:.0f},{zh*.042:.0f} {-zh*.21:.0f},{zh*.008:.0f} Z"'
                    f' fill="{RUSH}" {o(5)}/>'
            + f'<path d="M{zx-zh*.10:.0f},{gy_-zh*.12:.0f} q{zh*.10:.0f},'
              f'{-zh*.06:.0f} {zh*.20:.0f},{-zh*.01:.0f}" fill="none"'
              f' stroke="{TKAN}" stroke-width="{zh*.013:.0f}"/>'
            + f'<path d="M{zx+zh*.10:.0f},{gy_-zh*.105:.0f} q{zh*.07:.0f},'
              f'{zh*.03:.0f} {zh*.04:.0f},{zh*.09:.0f}" fill="none"'
              f' stroke="{RUSH}" stroke-width="{zh*.026:.0f}"/>')
    s += SL(Z_SRED, _varezhka(b1x, b1y, zh, t, .2))
    s += SL(Z_SRED, para_izo_rta(zx + 30, gy_ + 10, t, .5, .9, .4))
    # нижняя треть
    s += SL(Z_SRED, _polovik(820, pol + 42, 540, 118, "#6a7a8c", "#3f5c7a")
            + _valenki_u_dveri(1760, pol + 36, 1.05, t)
            + _dvorovaya_utvar(140, pol + 52, 230, t, 549, ["korzina"])
            + _kot_zhivoy(700, pol + 52, t, 1.05, "#3b3430", .3))
    s += SL(Z_PERED, _stolb_pered(-8, 110, "#1a120c", 0, H))
    s += vinetka(.42)
    return s


def bannyy_den_taz_i_mochalka(t):
    """Раздевалка городской бани: деревянные шкафчики с номерками, длинная
    лавка, на ней оцинкованный таз крупно — в тазу лыковая мочалка, кусок
    мыла, берёзовый веник. Отец в простыне сидит на лавке и обеими руками
    держит гранёный стакан чая в подстаканнике. Сын рядом болтает ногами,
    левой держит свой стакан, правой макает в него сушку."""
    rnd = random.Random(557)
    pol = 1016
    lav = 806
    s = f'<rect width="{W}" height="{H}" fill="#2f2a24"/>'
    s += SL(Z_DAL, _kafel(0, 40, 1920, 230, t, 559, "#c4ccc8", "#98a49e"))
    s += SL(Z_SRED, _shkafchiki_bani(0, 250, 1340, 540, t, 6, 561))
    s += SL(Z_DAL, _shkafchiki_bani(1340, 250, 580, 540, t, 3, 563))
    s += SL(Z_DAL, tusklaya_lampochka(1700, 40, t, 1.0, True))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-20:.0f}" width="{W}" height="{H-pol+20:.0f}"'
                   f' fill="#7a6a58"/>' + _kafel(0, pol - 12, 1920, 110, t, 565,
                                                 "#a89c8c", "#80745f"))
    # ЛАВКА во всю ширину — опора обеих фигур
    s += SL(Z_SRED, f'{ten(960, pol + 12, 720, 22, .5)}'
                    f'<rect x="60" y="{lav:.0f}" width="1800" height="54" rx="12"'
                    f' fill="url(#dosk)" {o(8)}/>'
            + f'<rect x="90" y="{lav+54:.0f}" width="1740" height="26" rx="9"'
              f' fill="#5b4428" {o(5)}/>')
    for px in (180, 900, 1700):
        s += SL(Z_SRED, f'<rect x="{px:.0f}" y="{lav+80:.0f}" width="68"'
                        f' height="{pol-lav-80+12:.0f}" rx="12" fill="#5b4428"'
                        f' {o(6)}/>')
    # ГЛАВНЫЙ ПРЕДМЕТ: оцинкованный таз с мочалкой, мылом и веником
    s += SL(Z_SRED, _taz_bannyy(420, lav - 4, 1.0, t, True))
    # ДВЕ ФИГУРЫ сидят на лавке: уровень пола у них — сама лавка
    ox, oy, oh = 1080, lav + 6, 560
    sx_, sy_, sh = 1480, lav + 6, 420
    _figury_kadra((ox, oy, oh), (sx_, sy_, sh))
    mak = A.ease(A.seg(t, .6, 1.2)) * (1 - A.ease(A.seg(t, 2.6, 1.0)))
    otec = figura(ox, oy, oh, t, col="#efe8d8", kant="#ffd98a", ph=.3,
                  naklon=3.0)
    o1, (c1x, c1y), _ = _ruka_mimo(ox, oy, oh, -1, oh * .32, 52, t,
                                   "#efe8d8", "#ffd98a", .2, 4.0)
    o2, (c2x, c2y), _ = _ruka_mimo(ox, oy, oh, 1, oh * .30, 54, t,
                                   "#efe8d8", "#ffd98a", .6, 4.0)
    otec += o1 + o2
    syn = figura(sx_, sy_, sh, t, col="#efe8d8", kant="#ffd98a", ph=.7,
                 naklon=4.0)
    p1, (d1x, d1y), _ = _ruka_mimo(sx_, sy_, sh, 1, sh * .34, 50, t,
                                   "#efe8d8", "#ffd98a", .1, 4.0)
    p2, (d2x, d2y), _ = _ruka_sgib_mimo(sx_, sy_, sh, 1, sh * .22, 24,
                                        sh * .22, 44 + 14 * mak, t,
                                        "#efe8d8", "#ffd98a", .5, 5.0)
    syn += p1 + p2
    s += SL(Z_SRED, otec)
    # ПРОСТЫНЯ, в которую завёрнут отец: распаренное лицо и пар от плеч
    s += SL(Z_SRED, f'<path d="M{ox-oh*.22:.0f},{oy-oh*.60:.0f}'
                    f' q{oh*.22:.0f},{-oh*.06:.0f} {oh*.44:.0f},0'
                    f' L{ox+oh*.26:.0f},{oy-oh*.08:.0f}'
                    f' L{ox-oh*.26:.0f},{oy-oh*.08:.0f} Z" fill="#f4eedc"'
                    f' {o(5)}/>'
            + f'<path d="M{ox-oh*.24:.0f},{oy-oh*.34:.0f} q{oh*.24:.0f},'
              f'{oh*.04:.0f} {oh*.48:.0f},0" fill="none" stroke="#d9d0b8"'
              f' stroke-width="9"/>'
            + "".join(f'<ellipse cx="{ox+i*oh*.085:.0f}"'
                      f' cy="{oy-oh*.825:.0f}" rx="{oh*.038:.0f}"'
                      f' ry="{oh*.026:.0f}" fill="#d9705a" opacity=".45"/>'
                      for i in (-1, 1)))
    s += SL(Z_SRED, par(ox - oh * .22, oy - oh * .66, t, 4, .50, 170, .5)
            + par(ox + oh * .22, oy - oh * .62, t, 3, .44, 150, .6))
    s += SL(Z_SRED, syn)
    s += SL(Z_SRED, f'<path d="M{sx_-sh*.22:.0f},{sy_-oh*.44:.0f}'
                    f' q{sh*.22:.0f},{-sh*.08:.0f} {sh*.44:.0f},0'
                    f' L{sx_+sh*.26:.0f},{sy_-sh*.10:.0f}'
                    f' L{sx_-sh*.26:.0f},{sy_-sh*.10:.0f} Z" fill="#f4eedc"'
                    f' {o(5)}/>')
    # БОЛТАЮЩИЕСЯ НОГИ сына: ступни над полом, качаются в противофазе
    for i, ph in ((-1, .0), (1, .5)):
        kol = 16 * A.w(t, 1.3, ph)
        nx = sx_ + i * sh * .14
        s += SL(Z_SRED, f'<g transform="rotate({kol:.1f} {nx:.0f} {sy_-sh*.08:.0f})">'
                        f'<rect x="{nx-18:.0f}" y="{sy_-sh*.08:.0f}" width="36"'
                        f' height="130" rx="15" fill="#e2d6c2" {o(5)}/>'
                        f'<path d="M{nx-20:.0f},{sy_-sh*.08+130:.0f}'
                        f' q{20:.0f},{26:.0f} {58:.0f},{14:.0f}'
                        f' q{8:.0f},{-20:.0f} {-18:.0f},{-28:.0f} Z"'
                        f' fill="#8fa3c2" {o(4)}/></g>')
    # СТАКАНЫ В ПОДСТАКАННИКАХ: ровно в кистях, варежки перекрывают их
    sta_x = (c1x + c2x) * .5
    s += SL(Z_SRED, _stakan_podstakannik(sta_x, c1y + 56, 1.0, t, .78, True))
    s += SL(Z_SRED, _varezhka(c1x, c1y + 4, oh, t, .2)
            + _varezhka(c2x, c2y + 4, oh, t, .6))
    s += SL(Z_SRED, _stakan_podstakannik(d1x + 30, d1y + 48, .84, t, .72, False))
    s += SL(Z_SRED, _varezhka(d1x, d1y + 4, sh, t, .1))
    s += SL(Z_SRED, _sushka_odna(d2x + 20, d2y + 36 + 26 * mak, .92, t, mak, 10))
    s += SL(Z_SRED, _varezhka(d2x, d2y + 4, sh, t, .5))
    # нижняя треть
    s += SL(Z_SRED, _taz_bannyy(1760, pol + 8, .62, t, False)
            + _valenki_u_dveri(300, pol + 36, 1.15, t)
            + _polovik(960, pol + 40, 560, 110, "#cdbf9c", "#b8352c")
            + _dvorovaya_utvar(680, pol + 46, 230, t, 567, ["vedro"]))
    s += SL(Z_SRED, teplo(1700, 180, 420, 300, .26))
    s += SL(Z_PERED, _stolb_pered(1894, 104, "#1c1710", 0, H))
    s += vinetka(.42)
    return s


def suhie_noski_i_krepkiy_son(t):
    """Кровать с железными шишечками, толстое ватное одеяло, из-под одеяла
    торчат две ноги в полосатых шерстяных носках. Мальчик спит на правом
    боку, правая ладонь под щекой, левая рука поверх одеяла. На стуле
    простыня и веник, на стене коврик, на тумбочке будильник, над мальчиком
    плывёт облачко сна с банным паром."""
    rnd = random.Random(571)
    pol = 1020
    s = f'<rect width="{W}" height="{H}" fill="#241c16"/>'
    s += SL(Z_DAL, _stena_gornicy(t, 573, True, 760, True))
    s += SL(Z_DAL, _kovrik_s_olenyami(900, 120, 700, 400, t))
    s += SL(Z_DAL, _polka_s_utvaryu(120, 150, 480, t, 575, 4))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="{H-pol+18:.0f}"'
                   f' fill="#5e4a34"/>' + polovicy(pol + 14)
            + _pol_shvy(pol + 16, 1078, 577, 6, "#4a3824"))
    # КРОВАТЬ с железными шишечками на спинках
    s += SL(Z_SRED, _krovat(300, pol, 1180, t, 579, True, 330))
    for i, (bx, n) in enumerate(((330, 3), (1430, 3))):
        s += SL(Z_SRED, f'<rect x="{bx-16:.0f}" y="{pol-430:.0f}" width="32"'
                        f' height="430" rx="14" fill="#8f979d" {o(5)}/>')
        for j in range(n):
            s += SL(Z_SRED, f'<circle cx="{bx:.0f}" cy="{pol-446-j*4:.0f}"'
                            f' r="{26-j*6:.0f}" fill="#b9c6cc" {o(4)}/>')
        s += SL(Z_SRED, f'<rect x="{bx-10:.0f}" y="{pol-300:.0f}" width="{(1430-330) if i == 0 else 10:.0f}"'
                        f' height="22" rx="9" fill="#9aa3aa" {o(4)}/>')
    s += SL(Z_SRED, _podushka(560, 716, 360, 200, t, .3, .5, .0))
    # ВАТНОЕ ОДЕЯЛО дышит
    s += SL(Z_SRED, _odeyalo_kray(360, 780, 1060, 240, t,
                                  .2 + .3 * abs(A.w(t, 1.7, .1)), "#8a4a5c"))
    # ГЛАВНЫЙ ПРЕДМЕТ: две ноги в полосатых носках из-под одеяла
    s += SL(Z_SRED, _nogi_v_noskah(1300, 1010, 1.15, t))
    # МАЛЬЧИК спит на правом боку: рост мал, голова на подушке
    bx_, by_, bh = 700, 806, 420
    _figury_kadra((bx_, by_, bh))
    mal = figura(bx_, by_, bh, t, col="#e2d6c2", kant="#ffd98a", ph=.3,
                 naklon=10.0)
    m1, (h1x, h1y), _ = _ruka_mimo(bx_, by_, bh, -1, bh * .28, -34, t,
                                   "#e2d6c2", "#ffd98a", .2, 3.0)
    m2, (h2x, h2y), _ = _ruka_mimo(bx_, by_, bh, 1, bh * .40, 58, t,
                                   "#e2d6c2", "#ffd98a", .6, 3.0)
    mal += m1 + m2
    s += SL(Z_SRED, mal)
    # ладонь под щекой: варежка перекрывает край подушки (хват читается)
    s += SL(Z_SRED, _varezhka(h1x, h1y + 4, bh, t, .2))
    # ОБЛАЧКО СНА с банным паром над мальчиком
    s += SL(Z_SRED, _oblachko_sna(900, 330, 1.0, t, 581))
    # стул с простынёй и веником, тумбочка с будильником
    s += SL(Z_SRED, _venskiy_stul(1640, pol, 420, t, -6, False))
    s += SL(Z_SRED, f'<path d="M1540,{pol-390:.0f} q110,-46 220,0'
                    f' q{-20:.0f},{70:.0f} {-110:.0f},{96:.0f}'
                    f' q{-90:.0f},{-26:.0f} {-110:.0f},{-96:.0f} Z"'
                    f' fill="#f4eedc" {o(5)}/>')
    s += SL(Z_SRED, _venik(1700, pol - 300, 260, t, "#cdbf9c", "#b8352c",
                           False, .12, .3, .8, 583))
    s += SL(Z_SRED, _tumbochka_veschi(130, pol, 250, t, 210))
    s += SL(Z_SRED, _budilnik(255, pol - 224, 1.0, t))
    s += SL(Z_SRED, svecha(190, pol - 226, t, .4, 1.0, 96)
            + teplo(200, pol - 280, 230, 200, .34))
    # нижняя треть
    s += SL(Z_SRED, _polovik(900, pol + 42, 540, 118, "#cdbf9c", "#b8352c")
            + _valenki_u_dveri(1860, pol + 38, 1.0, t)
            + _kot_zhivoy(640, pol + 52, t, 1.1, "#3b3430", .3, True, True)
            + _dvorovaya_utvar(420, pol + 48, 220, t, 585, ["korzina"]))
    s += SL(Z_PERED, _stolb_pered(-8, 110, "#1a120c", 0, H))
    s += vinetka(.44)
    return s


def vorobinaya_noch_nad_derevney(t):
    """Тёмно-синяя ночь под луной: деревня пригнулась под ветром — дым из
    труб лежит вбок, берёзы согнуты в одну сторону, калитка хлопает, с
    забора летит горшок. Ветер нарисован огромной стаей воробьёв из
    завитков, она несётся над крышами слева направо. Людей нет, во всех
    избах темно, в одном окне горит огонёк."""
    rnd = random.Random(587)
    gor = 720
    s = f'<rect width="{W}" height="{H}" fill="url(#nnoch)"/>'
    s += nebo("noch", t, True, 83)
    s += oblaka(t, 140, 6, 85, .36, "#8e9ab0", 5.0)
    s += SL(Z_NEBO, f'<circle cx="1560" cy="190" r="104" fill="#e8eef6"'
                    f' opacity=".92"/>'
            + f'<circle cx="1560" cy="190" r="150" fill="#cfe4f5" opacity=".16"/>'
            + f'<circle cx="1596" cy="162" r="22" fill="#cfd6de" opacity=".5"/>'
            + f'<circle cx="1528" cy="216" r="15" fill="#cfd6de" opacity=".45"/>')
    # ДЕРЕВНЯ: избы в три плана, свет только в одном окне
    s += SL(Z_DAL, _derevnya_ryad(gor - 170, t, 87,
                                  ((120, 300), (520, 260), (1120, 280),
                                   (1700, 240))))
    for i, (bx, bw, sv_) in enumerate(((200, 470, False), (660, 790, True),
                                       (1400, 450, False))):
        s += SL(Z_SRED, izba_snaruzhi(bx, gor + 40 + i * 12, bw, t, sv_, True,
                                      89 + i * 4))
    # дым из труб ЛЕЖИТ ВБОК: сдвиг по ходу ветра
    for i, (dx_, dy_) in enumerate(((330, gor - 330), (860, gor - 366),
                                    (1440, gor - 342))):
        s += SL(Z_SRED, f'<g transform="translate({120 + 40 * i:.0f},0)'
                        f' rotate(62 {dx_:.0f} {dy_:.0f})">'
                        + dym(dx_, dy_, t, 6, .40, 420, .40, "#8e9ab0", 2.2)
                        + "</g>")
    # БЕРЁЗЫ согнуты в одну сторону
    for i, (bx, bh) in enumerate(((120, 560), (640, 480), (1180, 520),
                                  (1820, 440))):
        s += SL(Z_DAL, _bereza_sognuta(bx, gor + 60, bh, t, 93 + i, 1, 7))
    # ЗАБОР, КАЛИТКА и летящий горшок
    s += SL(Z_SRED, _zabor_dosok(1480, gor - 100, 440, 170, 97, 54))
    s += SL(Z_SRED, _kalitka_hlopaet(1060, gor + 110, 210, 280, t, True))
    for i, (gx_, gy_, gs) in enumerate(((1560, gor - 118, 1.0),
                                        (1700, gor - 110, .74))):
        k = A.ease(A.seg(t, .4 + i * .34, 2.2))
        s += SL(Z_SRED, _gorshok_letit(gx_, gy_, t, gs, k, 99 + i))
    # ЗЕМЛЯ и нижняя треть — настоящие вещи, а не пустое поле
    s += SL(Z_SRED, f'<rect x="0" y="{gor+60:.0f}" width="{W}"'
                    f' height="{H-gor-60:.0f}" fill="#2b3038"/>'
            + sneg_lezhit(gor + 90, 30)
            + _zemlya_faktura(gor + 130, 1072, 101, 16, "#232830"))
    s += SL(Z_SRED, _polenica(80, 1040, 380, 210, 103, 26)
            + _sani(560, 1040, .86, t, True)
            + _kucha_listev(1360, 1052, 320, 105, 76)
            + _dvorovaya_utvar(1660, 1046, 240, t, 107, ["kadka", "vedro"])
            + _sledy(300, 1070, 1020, gor + 150, 8, 109, "#1d2128", 1.1))
    s += SL(Z_SRED, _stog(1860, 1010, .76, t, True))
    s += SL(Z_SRED, _vorona(420, gor - 420, t, 1.0, .2, .6)
            + _vorona(1240, gor - 470, t, .74, .6, .4))
    # ВЕТЕР СТАЕЙ: два яруса, над крышами и чуть выше
    s += SL(Z_LETIT, _staya_vetra(t, 20, 111, 180, 420))
    s += SL(Z_LETIT, _staya_vetra(t, 14, 113, 440, 640))
    s += SL(Z_LETIT, mokryy_sneg(t, 34, 115, .46, 2.1))
    s += SL(Z_SRED, teplo(900, gor - 180, 420, 300, .30))
    s += SL(Z_PERED, _vetka_pered(1960, 170, 640, 154, t, 117, "#141017", 7))
    s += vinetka(.48)
    return s


def uho_u_steny(t):
    """Бревенчатая стена избы изнутри, пакля между брёвнами, на гвозде тулуп
    и шапка. Дед в исподнем стоит босиком на половике боком к стене: ухо
    прижал к бревну, ладонь приложил к уху раковиной, второй рукой держит
    кальсоны. От стены к уху бегут рисованные волны звука, в плошке мечется
    огонёк."""
    rnd = random.Random(601)
    pol = 1012
    s = f'<rect width="{W}" height="{H}" fill="#241a12"/>'
    # СТЕНА КРУПНО: брёвна в полкадра и пакля между венцами
    s += SL(Z_DAL, brevna(0, 0, 1100, pol, 118))
    s += SL(Z_DAL, brevna(1100, 0, 820, pol, 118, 40))
    for i in range(9):
        yy = 116 + i * 118
        s += SL(Z_DAL, "".join(
            f'<path d="M{20+j*96:.0f},{yy:.0f} q{22:.0f},{-11:.0f} {46:.0f},{2:.0f}"'
            f' fill="none" stroke="#c9b48a" stroke-width="{rnd.uniform(7,13):.0f}"'
            f' opacity=".8"/>' for j in range(19)))
    s += SL(Z_DAL, _polka_s_utvaryu(1420, 170, 440, t, 603, 4)
            + _polka_s_utvaryu(60, 200, 460, t, 611, 5))
    # стенное хозяйство и подкова-оберег: без них стена читается обоями
    s += SL(Z_DAL, _stennoe_hozyaystvo(230, 520, t, 613))
    s += SL(Z_DAL, podkova(1020, 150, 1.5, t))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="{H-pol+18:.0f}"'
                   f' fill="#5e4a34"/>' + polovicy(pol + 14)
            + _pol_shvy(pol + 16, 1074, 605, 6, "#4a3824"))
    # ТУЛУП И ШАПКА НА ГВОЗДЕ — вздрагивают от сквозняка
    s += SL(Z_SRED, _tulup_na_gvozde(1180, 210, 480, t, .3, True))
    # плошка с лучиной: огонёк мечется
    s += SL(Z_SRED, f'<rect x="1560" y="{pol-330:.0f}" width="300" height="26"'
                    f' rx="9" fill="url(#dosk)" {o(5)}/>'
            + f'<path d="M1660,{pol-330:.0f} q50,-34 100,0 Z" fill="#b08050"'
              f' {o(4)}/>')
    s += SL(Z_SRED, luchina(1710, pol - 338, t, 1.25, .2)
            + teplo(1710, pol - 380, 300, 250, .40))
    # ОДНА ФИГУРА: дед в исподнем, босиком, в профиль к стене
    dx_, dy_, dh = 700, pol, 780
    _figury_kadra((dx_, dy_, dh))
    brov = A.w(t, 1.6, .2)
    ded = figura(dx_, dy_, dh, t, col="#efe8d8", kant="#ffd98a", ph=.3,
                 profil=True, boroda=True, naklon=4.0)
    # ПРАВАЯ рука идёт ВВЕРХ и НАРУЖУ к уху: `_ruka` не пускает кисть в свою
    # же голову, поэтому ладонь встаёт РЯДОМ с ухом, у самого его края —
    # это и есть «ладонь раковиной», коридор угла держит код
    r1, (u1x, u1y), _ = _ruka_so_sgibom(dx_, dy_, dh, 1, dh * .18, -38,
                                        dh * .14, -56, t, "#efe8d8",
                                        "#ffd98a", .2, 3.0)
    r2, (u2x, u2y), _ = _ruka_mimo(dx_, dy_, dh, -1, dh * .26, 62, t,
                                   "#efe8d8", "#ffd98a", .7, 4.0)
    ded += r1 + r2
    s += SL(Z_SRED, ded)
    # ЛАДОНЬ РАКОВИНОЙ у уха: полукольцо от кисти к голове, пальцев нет
    s += SL(Z_SRED, f'<path d="M{u1x-10:.0f},{u1y-40:.0f}'
                    f' q{44:.0f},{-14:.0f} {52:.0f},{40:.0f}'
                    f' q{6:.0f},{44:.0f} {-40:.0f},{54:.0f}"'
                    f' fill="none" stroke="#e8d8c0" stroke-width="30"'
                    f' stroke-linecap="round"/>')
    # ВОЛНЫ ЗВУКА от стены к уху
    s += SL(Z_SRED, _volny_zvuka(u1x - 180, u1y + 10, t, 4, 0.0, 240))
    s += SL(Z_SRED, _volny_zvuka(u1x - 130, u1y - 90, t, 3, -14.0, 190))
    # БРОВИ ходят вверх-вниз: короткий штрих над глазом, поверх лица
    gy_ = dy_ - dh * .845
    for i in (-1, 1):
        s += SL(Z_SRED, f'<path d="M{dx_+i*dh*.045-dh*.022:.0f},'
                        f'{gy_-dh*.052+brov*dh*.008:.0f}'
                        f' q{dh*.022:.0f},{-dh*.014:.0f} {dh*.044:.0f},0"'
                        f' fill="none" stroke="{K}"'
                        f' stroke-width="{dh*.009:.0f}" stroke-linecap="round"/>')
    # КАЛЬСОНЫ, которые он придерживает второй рукой
    s += SL(Z_SRED, f'<path d="M{dx_-dh*.15:.0f},{dy_-dh*.40:.0f}'
                    f' q{dh*.15:.0f},{dh*.03:.0f} {dh*.30:.0f},0'
                    f' L{dh*.015+dx_+dh*.14:.0f},{dy_-dh*.08:.0f}'
                    f' L{dx_-dh*.16:.0f},{dy_-dh*.08:.0f} Z" fill="#e2dccc"'
                    f' {o(5)}/>'
            + f'<path d="M{dx_-dh*.16:.0f},{dy_-dh*.36:.0f} q{dh*.16:.0f},'
              f'{dh*.03:.0f} {dh*.32:.0f},0" fill="none" stroke="#c4bba6"'
              f' stroke-width="{dh*.016:.0f}"/>')
    s += SL(Z_SRED, _varezhka(u2x, u2y + 2, dh, t, .7))
    # БОСЫЕ НОГИ НА ПОЛОВИКЕ — опора названа
    s += SL(Z_SRED, _polovik(dx_ - 250, pol + 16, 520, 120, "#cdbf9c", "#b8352c"))
    # нижняя треть
    s += SL(Z_SRED, _valenki_u_dveri(1860, pol + 36, 1.05, t)
            + _dvorovaya_utvar(120, pol + 52, 240, t, 607, ["korzina", "vedro"])
            + _kot_zhivoy(1240, pol + 54, t, 1.1, "#3b3430", .4)
            + _yaschiki(1500, pol + 16, t, 609, 2, .9)
            + _polenica(300, pol + 60, 300, 170, 615, 25)
            + kartoshka(1020, pol + 58, t, 8, 617, 1.05))
    s += SL(Z_SRED, _kadushki_i_grabli(1680, pol + 44, t, 619))
    s += SL(Z_PERED, _stolb_pered(-8, 124, "#140e09", 0, H))
    s += vinetka(.44)
    return s


def pustoy_ugol_bez_televizora(t):
    """Красный угол старой избы, где сегодня стоял бы телевизор: вместо него
    прялка, кованый ларь, кадка с квашнёй, на стене ходики и пучки трав. На
    ларе на миг проступает прозрачный контур телевизора с диктором в
    галстуке, диктор открывает рот — и контур тает. Дед сидит на лавке
    рядом: правой рукой машет на контур, левая лежит на колене."""
    rnd = random.Random(623)
    pol = 1014
    s = f'<rect width="{W}" height="{H}" fill="#26190f"/>'
    s += SL(Z_DAL, brevna(0, 0, 1180, pol, 104)
            + brevna(1180, 0, 740, pol, 104, 52))
    s += SL(Z_DAL, _polka_s_utvaryu(100, 150, 500, t, 625, 5))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="{H-pol+18:.0f}"'
                   f' fill="#5e4a34"/>' + polovicy(pol + 14)
            + _pol_shvy(pol + 16, 1074, 627, 6, "#4a3824"))
    # ХОДИКИ и пучки трав на стене
    s += SL(Z_SRED, hodiki(1000, 190, t, 1.5))
    s += SL(Z_SRED, _puchki_trav(620, 200, 4, t, 629, 108))
    # ПРЯЛКА, КОВАНЫЙ ЛАРЬ, КАДКА С КВАШНЁЙ — то, что стоит вместо экрана
    s += SL(Z_SRED, _pryalka(300, pol, t, 1.0, True))
    s += SL(Z_SRED, _lar_kovanyy(760, pol, 560, 300, t, 631))
    s += SL(Z_SRED, _kadka_kvashni(1480, pol, 1.15, t))
    s += SL(Z_SRED, svecha(1320, pol - 8, t, .3, 1.35, 120)
            + teplo(1320, pol - 70, 300, 260, .40))
    # КОНТУР ТЕЛЕВИЗОРА проступает на ларе и тает
    prost = A.ease(A.seg(t, .6, .9)) * (1 - A.ease(A.seg(t, 2.0, 1.2)))
    s += SL(Z_SRED, _kontur_televizora(840, pol - 310, 420, 320, t, prost, True))
    # ОДНА ФИГУРА: дед на лавке, правая машет, левая на колене
    s += SL(Z_SRED, _lavka_krupno(1640, pol, 470, t, 170, True))
    dx_, dy_, dh = 1660, pol - 160, 560
    _figury_kadra((dx_, dy_, dh))
    mash = A.w(t, 1.1, .2)
    ded = figura(dx_, dy_, dh, t, col="#54505e", kant="#ffd98a", ph=.4,
                 boroda=True, naklon=5.0)
    r1, (m1x, m1y), _ = _ruka_mimo(dx_, dy_, dh, -1, dh * .46,
                                   -4 + 22 * mash, t, "#54505e", "#ffd98a",
                                   .2, 9.0)
    r2, (m2x, m2y), _ = _ruka_so_sgibom(dx_, dy_, dh, 1, dh * .22, 30,
                                        dh * .22, 62, t, "#54505e",
                                        "#ffd98a", .7, 3.0)
    ded += r1 + r2
    s += SL(Z_SRED, ded)
    # машущая кисть: предмета в ней нет, значит варежки НЕТ — рукав без кисти
    s += SL(Z_SRED, f'<path d="M{m1x-26:.0f},{m1y-20:.0f} q{30:.0f},{-16:.0f}'
                    f' {52:.0f},{10:.0f}" fill="none" stroke="#ffd98a"'
                    f' stroke-width="7" opacity="{.25+.3*abs(mash):.2f}"/>')
    # нижняя треть
    s += SL(Z_SRED, _polovik(900, pol + 40, 560, 118, "#cdbf9c", "#b8352c")
            + _dvorovaya_utvar(120, pol + 52, 240, t, 633, ["kadka", "vedro"])
            + _kot_zhivoy(1180, pol + 54, t, 1.1, "#3b3430", .3)
            + kartoshka(640, pol + 60, t, 8, 635, 1.0)
            + _valenki_u_dveri(1870, pol + 36, 1.0, t))
    s += SL(Z_SRED, _yaschiki(420, pol + 14, t, 637, 2, .86))
    s += SL(Z_PERED, _stolb_pered(-8, 118, "#150e08", 0, H))
    s += vinetka(.44)
    return s


def stariki_slushayut_noch(t):
    """Деревянная кровать с горой подушек под окном, окно на пол-кадра — в
    нём настоящая луна в бегущих облаках. Дед лежит на спине, обе руки
    поверх одеяла, смотрит в потолок и слушает. Бабка на правом боку лицом
    к нему, левую руку высунула из-под одеяла и подняла: тише. На второй
    половине фразы в окне утро, и дед сидит на кровати, уверенно показывая
    рукой на небо."""
    rnd = random.Random(641)
    pol = 1016
    utro = A.ease(A.seg(t, 2.0, 1.1))
    sel = A.ease(A.seg(t, 2.2, 1.0))
    s = f'<rect width="{W}" height="{H}" fill="#1e2430"/>'
    s += SL(Z_DAL, _stena_gornicy(t, 643, True, 700, True))
    s += SL(Z_DAL, _polka_s_utvaryu(80, 150, 420, t, 645, 4)
            + _ramki_na_stene(1560, 170, 320, t, 647, 3))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="{H-pol+18:.0f}"'
                   f' fill="#5e4a34"/>' + polovicy(pol + 14)
            + _pol_shvy(pol + 16, 1074, 649, 6, "#4a3824"))
    # НАСТОЯЩИЙ КАДР в окне над кроватью: вид, метка, переплёт поверх
    px, py, pw, ph_ = 540, 110, 860, 420
    put = kontur_proema(px, py, pw, ph_, "pryam")
    vid = (f'<path d="{put}" fill="{NOCH}" opacity="{1-utro*.75:.2f}"/>'
           f'<path d="{put}" fill="{RASSV}" opacity="{utro*.85:.2f}"/>'
           f'<circle cx="{px+pw*.56:.0f}" cy="{py+ph_*.40:.0f}" r="86"'
           f' fill="#e8eef6" opacity="{1-utro*.8:.2f}"/>'
           f'<circle cx="{px+pw*.30:.0f}" cy="{py+ph_*.32:.0f}" r="94"'
           f' fill="{SVET}" opacity="{utro*.7:.2f}"/>')
    for i in range(4):
        ox_ = px + ((t * 40 + i * 260) % (pw + 300)) - 150
        vid += (f'<ellipse cx="{ox_:.0f}" cy="{py+ph_*(.30+i*.14):.0f}"'
                f' rx="{130-i*16:.0f}" ry="{40-i*5:.0f}" fill="#8e9ab0"'
                f' opacity="{.44-utro*.2:.2f}"/>')
    s += SL(Z_SRED, vid + mesto_stoka(px, py, pw, ph_, "pryam"))
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#6a5030"'
                    f' stroke-width="34"/>'
            + f'<line x1="{px+pw*.5:.0f}" y1="{py:.0f}" x2="{px+pw*.5:.0f}"'
              f' y2="{py+ph_:.0f}" stroke="#6a5030" stroke-width="24"/>'
            + f'<line x1="{px:.0f}" y1="{py+ph_*.48:.0f}" x2="{px+pw:.0f}"'
              f' y2="{py+ph_*.48:.0f}" stroke="#6a5030" stroke-width="20"/>'
            + f'<rect x="{px-56:.0f}" y="{py-52:.0f}" width="{pw+112:.0f}"'
              f' height="44" rx="12" fill="#7d5a3c" {o(5)}/>'
            + f'<rect x="{px-40:.0f}" y="{py+ph_-10:.0f}" width="{pw+80:.0f}"'
              f' height="42" rx="12" fill="url(#dosk)" {o(6)}/>'
            + zanaveska(px + 30, py + 10, 230, 130, None, t, 1)
            + zanaveska(px + pw - 30, py + 10, 230, 130, None, t, -1))
    # КРОВАТЬ с горой подушек
    s += SL(Z_SRED, _krovat(360, pol, 1180, t, 651, True, 340))
    s += SL(Z_SRED, _podushka(560, 700, 330, 200, t, .2, .4, .0)
            + _podushka(820, 672, 300, 190, t, .5, .3, .0)
            + _podushka(1070, 694, 310, 190, t, .8, .35, .0))
    # ОДЕЯЛО ДЫШИТ — лоскутное, одно на двоих
    s += SL(Z_SRED, _odeyalo_kray(400, 800, 1100, 230, t,
                                  .2 + .3 * abs(A.w(t, 1.9, .2)), TKAN2))
    s += SL(Z_SRED, _tumbochka_veschi(1680, pol, 230, t, 200))
    s += SL(Z_SRED, lampa(1780, pol - 206, t, .85, True))
    s += SL(Z_SRED, hodiki(170, 300, t, 1.2))
    # ДВЕ ФИГУРЫ лежат, к утру дед садится
    dx_, dy_, dh = 760, 812 - 180 * sel, 430 + 190 * sel
    bx_, by_, bh = 1180, 806, 400
    _figury_kadra((dx_, dy_, dh), (bx_, by_, bh))
    ded = figura(dx_, dy_, dh, t, col="#e2d6c2", kant="#ffd98a", ph=.3,
                 boroda=True, naklon=4.0 - 3.0 * sel)
    g1, (n1x, n1y), _ = _ruka_mimo(dx_, dy_, dh, -1, dh * .34, 52 - 26 * sel, t,
                                   "#e2d6c2", "#ffd98a", .2, 4.0)
    g2, (n2x, n2y), _ = _ruka_mimo(dx_, dy_, dh, 1, dh * .40,
                                   50 - 96 * sel, t, "#e2d6c2", "#ffd98a",
                                   .6, 4.0)
    ded += g1 + g2
    bab = figura(bx_, by_, bh, t, col="#e2d6c2", kant="#ffd98a", platok=True,
                 ph=.7, profil=True, naklon=9.0)
    b1, (q1x, q1y), _ = _ruka_mimo(bx_, by_, bh, 1, bh * .34, 48, t,
                                   "#e2d6c2", "#ffd98a", .1, 3.0)
    b2, (q2x, q2y), _ = _ruka_so_sgibom(bx_, by_, bh, -1, bh * .22, 20,
                                        bh * .22, -40, t, "#e2d6c2",
                                        "#ffd98a", .5, 3.0)
    bab += b1 + b2
    s += SL(Z_SRED, ded)
    s += SL(Z_SRED, bab)
    # ПОДНЯТАЯ РУКА БАБКИ «тише»: кисть варежкой, пальцев не рисуем — хват
    # читается по вертикальному рукаву и светлому овалу на его конце
    s += SL(Z_SRED, f'<ellipse cx="{q2x:.0f}" cy="{q2y-26:.0f}" rx="13"'
                    f' ry="30" fill="#e8d8c0" {o(4)}/>')
    s += SL(Z_SRED, _varezhka(q2x, q2y + 6, bh, t, .5))
    # УВЕРЕННЫЙ ЖЕСТ деда на небо к утру — рукав вверх и наружу, без предмета
    if sel > .3:
        s += SL(Z_SRED, f'<path d="M{n2x-14:.0f},{n2y+16:.0f} q{22:.0f},{-20:.0f}'
                        f' {44:.0f},{-6:.0f}" fill="none" stroke="#ffd98a"'
                        f' stroke-width="8" opacity="{sel*.6:.2f}"/>')
    # нижняя треть
    s += SL(Z_SRED, _polovik(900, pol + 40, 560, 118, "#cdbf9c", "#b8352c")
            + _valenki_u_dveri(300, pol + 36, 1.1, t)
            + _kot_zhivoy(1480, pol + 52, t, 1.1, "#3b3430", .4, True, True)
            + _dvorovaya_utvar(130, pol + 52, 230, t, 653, ["korzina"])
            + _yaschiki(1860, pol + 14, t, 655, 2, .8))
    s += SL(Z_SRED, teplo(1780, pol - 240, 420, 320, .32))
    s += SL(Z_PERED, _stolb_pered(-8, 110, "#150f0c", 0, H))
    s += vinetka(.44)
    return s


# ── ПОМОЩНИКИ ТРЕТЬЕЙ ПАРТИИ ──────────────────────────────────────────────

def _flyuger_petuh(x, y, s_=1.0, t=0.0, ug=0.0, roza=True):
    """КОВАНЫЙ ФЛЮГЕР-ПЕТУХ — главный предмет: тело с прорезным хвостом,
    гребень зубцами, бородка, клюв, лапы на штыре. Поворачивается на штыре
    целиком, со скрипом-дрожью. Роза ветров под ним — ЧЕТЫРЕ СТРЕЛЫ, север
    отмечен двойным наконечником: СВОИХ БУКВ НЕ РИСУЕМ ВООБЩЕ, поэтому ни
    «С», ни «Ю» на розе нет (правило ролика сильнее буквы задания)."""
    drozh = 1.6 * A.w(t, 7.0, .2)
    s = (f'<rect x="{x-9*s_:.0f}" y="{y:.0f}" width="{18*s_:.0f}"'
         f' height="{150*s_:.0f}" rx="{8*s_:.0f}" fill="{ZHELEZ}" {o(5)}/>')
    if roza:
        s += (f'<circle cx="{x:.0f}" cy="{y+40*s_:.0f}" r="{70*s_:.0f}"'
              f' fill="none" stroke="#4e4a47" stroke-width="{7*s_:.0f}"/>')
        for i in range(4):
            a = math.radians(i * 90)
            ex = x + math.cos(a) * 92 * s_
            ey = y + 40 * s_ + math.sin(a) * 92 * s_
            s += (f'<line x1="{x:.0f}" y1="{y+40*s_:.0f}" x2="{ex:.0f}"'
                  f' y2="{ey:.0f}" stroke="#4e4a47" stroke-width="{9*s_:.0f}"/>'
                  f'<path d="M{ex:.0f},{ey:.0f} l{-math.cos(a)*22*s_-math.sin(a)*11*s_:.0f},'
                  f'{-math.sin(a)*22*s_+math.cos(a)*11*s_:.0f}'
                  f' l{0:.0f},{0:.0f} l{-math.cos(a)*22*s_+math.sin(a)*11*s_:.0f},'
                  f'{-math.sin(a)*22*s_-math.cos(a)*11*s_:.0f} Z" fill="#5f5a56"'
                  f' {o(3)}/>')
        # север отмечен не буквой, а двойным наконечником и звездой
        s += (f'<path d="M{x:.0f},{y-76*s_:.0f} l{14*s_:.0f},{26*s_:.0f}'
              f' l{-28*s_:.0f},0 Z" fill="#cfe4f5" {o(3)}/>'
              f'<path d="M{x:.0f},{y-108*s_:.0f} l{7*s_:.0f},{18*s_:.0f}'
              f' l{19*s_:.0f},{3*s_:.0f} l{-15*s_:.0f},{13*s_:.0f}'
              f' l{5*s_:.0f},{19*s_:.0f} l{-16*s_:.0f},{-10*s_:.0f}'
              f' l{-16*s_:.0f},{10*s_:.0f} l{5*s_:.0f},{-19*s_:.0f}'
              f' l{-15*s_:.0f},{-13*s_:.0f} l{19*s_:.0f},{-3*s_:.0f} Z"'
              f' fill="#cfe4f5" {o(3)}/>')
    s += f'<g transform="rotate({ug + drozh:.1f} {x:.0f} {y:.0f})">'
    s += (f'<path d="M{x-120*s_:.0f},{y-10*s_:.0f}'
          f' q{30*s_:.0f},{-64*s_:.0f} {104*s_:.0f},{-58*s_:.0f}'
          f' q{46*s_:.0f},{6*s_:.0f} {58*s_:.0f},{34*s_:.0f}'
          f' q{10*s_:.0f},{34*s_:.0f} {-38*s_:.0f},{48*s_:.0f}'
          f' q{-66*s_:.0f},{16*s_:.0f} {-124*s_:.0f},{-24*s_:.0f} Z"'
          f' fill="#3d3a38" {o(7)}/>')
    for i in range(5):
        s += (f'<path d="M{x-118*s_+i*6*s_:.0f},{y-14*s_:.0f}'
              f' q{-48*s_:.0f},{(-34+i*18)*s_:.0f} {-86*s_:.0f},{(-52+i*26)*s_:.0f}'
              f' q{40*s_:.0f},{8*s_:.0f} {86*s_:.0f},{10*s_:.0f} Z"'
              f' fill="#4e4a47" {o(4)}/>')
    s += (f'<circle cx="{x+118*s_:.0f}" cy="{y-56*s_:.0f}" r="{30*s_:.0f}"'
          f' fill="#3d3a38" {o(5)}/>'
          f'<path d="M{x+146*s_:.0f},{y-56*s_:.0f} l{42*s_:.0f},{10*s_:.0f}'
          f' l{-40*s_:.0f},{16*s_:.0f} Z" fill="{ORA}" {o(4)}/>'
          f'<circle cx="{x+124*s_:.0f}" cy="{y-64*s_:.0f}" r="{6*s_:.0f}"'
          f' fill="#ffd98a"/>')
    for i in range(4):
        s += (f'<path d="M{x+100*s_+i*12*s_:.0f},{y-84*s_:.0f}'
              f' l{6*s_:.0f},{-22*s_:.0f} l{8*s_:.0f},{20*s_:.0f} Z"'
              f' fill="{KRAS}" {o(3)}/>')
    s += (f'<path d="M{x+134*s_:.0f},{y-30*s_:.0f} q{10*s_:.0f},{22*s_:.0f}'
          f' {-6*s_:.0f},{30*s_:.0f}" fill="none" stroke="{KRAS}"'
          f' stroke-width="{12*s_:.0f}"/>')
    for i in (-1, 1):
        s += (f'<line x1="{x+i*18*s_:.0f}" y1="{y+10*s_:.0f}"'
              f' x2="{x+i*26*s_:.0f}" y2="{y+46*s_:.0f}" stroke="#3d3a38"'
              f' stroke-width="{max(3,7*s_):.0f}"/>')
    return s + "</g>"


def _konek_kryshi(x, y, w_, t, seed=3, sneg=True):
    """Конёк крыши крупно: тёс в два скатa, охлупень по гребню, снеговая
    подушка и стропильные выпуски."""
    rnd = random.Random(seed)
    s = (f'<path d="M{x:.0f},{y+200:.0f} L{x+w_*.5:.0f},{y:.0f}'
         f' L{x+w_:.0f},{y+200:.0f} L{x+w_:.0f},{y+440:.0f} L{x:.0f},{y+440:.0f} Z"'
         f' fill="#6b5340" {o(8)}/>')
    for i in range(14):
        s += (f'<line x1="{x+i*(w_/14.0):.0f}" y1="{y+440:.0f}"'
              f' x2="{x+w_*.5:.0f}" y2="{y+4:.0f}" stroke="#4e3c2c"'
              f' stroke-width="6" opacity=".6"/>')
    s += (f'<path d="M{x+w_*.5-30:.0f},{y-16:.0f} q{30:.0f},{-22:.0f} {60:.0f},0'
          f' L{x+w_*.5+26:.0f},{y+42:.0f} L{x+w_*.5-26:.0f},{y+42:.0f} Z"'
          f' fill="#5a4530" {o(6)}/>')
    if sneg:
        s += (f'<path d="M{x-20:.0f},{y+214:.0f} Q{x+w_*.5:.0f},{y-18:.0f}'
              f' {x+w_+20:.0f},{y+214:.0f} Q{x+w_*.5:.0f},{y+150:.0f}'
              f' {x-20:.0f},{y+214:.0f} Z" fill="url(#sneg)" opacity=".92"/>')
    for i in range(5):
        bx = x + 60 + i * (w_ - 120) / 4.0
        s += (f'<rect x="{bx:.0f}" y="{y+430:.0f}" width="34" height="56"'
              f' rx="8" fill="#5a4530" {o(4)}/>')
    return s


def _bele_na_verevke(x, y, w_, t, veter=1.0, n=4, seed=5, derev=.0):
    """Бельё на верёвке: рубаха, простыня, полотенце, наволочка. `veter`
    сносит все вещи в ОДНУ сторону, `derev` — бельё деревенеет на морозе и
    висит коробом, почти не шевелясь."""
    rnd = random.Random(seed)
    s = (f'<path d="M{x:.0f},{y:.0f} Q{x+w_*.5:.0f},{y+26-20*derev:.0f}'
         f' {x+w_:.0f},{y:.0f}" fill="none" stroke="#c9b48a" stroke-width="7"/>')
    for i in range(n):
        px = x + 40 + i * (w_ - 80) / max(1, n - 1.0)
        py = y + 18 - 14 * derev
        hh = rnd.uniform(150, 230)
        ww = rnd.uniform(110, 170)
        sn = (26 * veter + 16 * veter * A.w(t, 1.6, i * .3)) * (1 - .82 * derev)
        s += (f'<path d="M{px-ww*.5:.0f},{py:.0f} L{px+ww*.5:.0f},{py:.0f}'
              f' Q{px+ww*.5+sn:.0f},{py+hh*.5:.0f} {px+ww*.46+sn:.0f},{py+hh:.0f}'
              f' Q{px:.0f},{py+hh+18:.0f} {px-ww*.46+sn*.5:.0f},{py+hh:.0f}'
              f' Q{px-ww*.5:.0f},{py+hh*.5:.0f} {px-ww*.5:.0f},{py:.0f} Z"'
              f' fill="{["#f4eedc", "#e8eef0", "#efe3c8", "#dde6ea"][i % 4]}"'
              f' {o(5)}/>')
        for j in range(3):
            s += (f'<path d="M{px-ww*.3+j*ww*.3:.0f},{py+12:.0f}'
                  f' q{6+sn*.2:.0f},{hh*.4:.0f} {sn*.4:.0f},{hh*.86:.0f}"'
                  f' fill="none" stroke="#cfc7ad" stroke-width="5" opacity=".8"/>')
        if derev > .4:
            s += (f'<path d="M{px-ww*.5:.0f},{py+hh:.0f} L{px+ww*.5:.0f},{py+hh:.0f}"'
                  f' fill="none" stroke="{INEY}" stroke-width="11" opacity=".8"/>')
        for e in (-1, 1):
            s += (f'<rect x="{px+e*ww*.34-7:.0f}" y="{py-14:.0f}" width="14"'
                  f' height="30" rx="5" fill="#c9a47a" {o(3)}/>')
    return s


def _luzha_so_ldom(x, y, rx, t, led=.0, ph=.0):
    """Лужа, которая схватывается льдом: вода с отражением (берём готовую
    `_luzha`), поверх растут ледяные перья и матовая корка, по кромке иней."""
    s = _luzha(x, y, rx, t, ph, rx * .34, "#7e97ad")
    if led > .02:
        s += (f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{rx*led*.96:.0f}"'
              f' ry="{rx*.33*led:.0f}" fill="{LED}" opacity="{.42+.38*led:.2f}"/>')
        for i in range(9):
            a = math.radians(i * 40)
            s += (f'<path d="M{x:.0f},{y:.0f} L{x+math.cos(a)*rx*led*.9:.0f},'
                  f'{y+math.sin(a)*rx*.30*led:.0f}" fill="none" stroke="#e8f1f6"'
                  f' stroke-width="{5*led:.0f}" opacity=".8"/>')
        s += (f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{rx*1.02:.0f}"'
              f' ry="{rx*.35:.0f}" fill="none" stroke="{INEY}"'
              f' stroke-width="{9*led:.0f}" opacity=".8"/>')
    return s


def _kolodec(x, y, w_, t, h_=330, vorot=True):
    """КОЛОДЕЦ С ВОРОТОМ — главный предмет: сруб в венцы, стойки, вал с
    рукоятью, цепь с ведром, двускатная кровелька. Середина сруба остаётся
    ТЁМНЫМ ПРОЁМОМ — там и стоит настоящий кадр."""
    s = (f'{ten(x + w_ * .5, y + 14, w_ * .54, 22, .55)}'
         f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="10" fill="url(#brev)" {o(8)}/>')
    for i in range(4):
        yy = y - h_ + 20 + i * (h_ - 26) / 4.0
        s += (f'<rect x="{x-14:.0f}" y="{yy:.0f}" width="{w_+28:.0f}"'
              f' height="{(h_-26)/4.0-8:.0f}" rx="14"'
              f' fill="{BREVNO if i % 2 == 0 else BREVNO2}" {o(5)}/>')
    for i in (0, 1):
        sx = x + 30 + i * (w_ - 86)
        s += (f'<rect x="{sx:.0f}" y="{y-h_-300:.0f}" width="56" height="320"'
              f' rx="10" fill="#6b5340" {o(6)}/>')
    s += (f'<path d="M{x-30:.0f},{y-h_-290:.0f} L{x+w_*.5:.0f},{y-h_-396:.0f}'
          f' L{x+w_+30:.0f},{y-h_-290:.0f} Z" fill="#5a4530" {o(6)}/>'
          f'<path d="M{x-30:.0f},{y-h_-290:.0f} L{x+w_*.5:.0f},{y-h_-396:.0f}'
          f' L{x+w_*.5:.0f},{y-h_-370:.0f} L{x+10:.0f},{y-h_-294:.0f} Z"'
          f' fill="{SNEG}" opacity=".9"/>')
    if vorot:
        kr = (t * 26.0) % 360.0
        s += (f'<rect x="{x+40:.0f}" y="{y-h_-160:.0f}" width="{w_-74:.0f}"'
              f' height="52" rx="24" fill="url(#derev)" {o(6)}/>')
        for i in range(5):
            s += (f'<line x1="{x+60+i*(w_-120)/4.0:.0f}" y1="{y-h_-158:.0f}"'
                  f' x2="{x+60+i*(w_-120)/4.0:.0f}" y2="{y-h_-112:.0f}"'
                  f' stroke="#5b4428" stroke-width="5" opacity=".8"/>')
        s += (f'<g transform="rotate({kr:.0f} {x+w_-30:.0f} {y-h_-134:.0f})">'
              f'<rect x="{x+w_-34:.0f}" y="{y-h_-140:.0f}" width="86" height="16"'
              f' rx="7" fill="{ZHELEZ}" {o(4)}/>'
              f'<rect x="{x+w_+42:.0f}" y="{y-h_-144:.0f}" width="18" height="46"'
              f' rx="8" fill="#8a6038" {o(4)}/></g>')
        for i in range(7):
            s += (f'<circle cx="{x+w_*.5+3*math.sin(t+i):.0f}"'
                  f' cy="{y-h_-100+i*17:.0f}" r="9" fill="none"'
                  f' stroke="{ZHELEZ}" stroke-width="5"/>')
    return s


def _koromyslo(x, y, s_=1.0, t=0.0, vedra=True):
    """Коромысло с двумя вёдрами, прислонённое к срубу: дуга с зарубками,
    крючья, вёдра покачиваются."""
    s = (f'<path d="M{x-150*s_:.0f},{y:.0f} Q{x:.0f},{y-70*s_:.0f}'
         f' {x+150*s_:.0f},{y:.0f}" fill="none" stroke="url(#derev)"'
         f' stroke-width="{24*s_:.0f}" stroke-linecap="round"/>'
         f'<path d="M{x-140*s_:.0f},{y-6*s_:.0f} Q{x:.0f},{y-64*s_:.0f}'
         f' {x+140*s_:.0f},{y-6*s_:.0f}" fill="none" stroke="#c9a47a"'
         f' stroke-width="{6*s_:.0f}" opacity=".6"/>')
    if vedra:
        for i in (-1, 1):
            kol = 4.0 * A.w(t, 2.3, .2 + (0 if i < 0 else .4))
            vx = x + i * 150 * s_
            s += (f'<g transform="rotate({kol:.1f} {vx:.0f} {y:.0f})">'
                  f'<path d="M{vx-10*s_:.0f},{y:.0f} q{2*s_:.0f},{34*s_:.0f}'
                  f' {10*s_:.0f},{40*s_:.0f}" fill="none" stroke="{ZHELEZ}"'
                  f' stroke-width="{7*s_:.0f}"/>'
                  f'<path d="M{vx-44*s_:.0f},{y+40*s_:.0f} q{6*s_:.0f},{78*s_:.0f}'
                  f' {44*s_:.0f},{78*s_:.0f} q{38*s_:.0f},0 {44*s_:.0f},{-78*s_:.0f} Z"'
                  f' fill="#b6bcc2" {o(5)}/>'
                  f'<ellipse cx="{vx:.0f}" cy="{y+40*s_:.0f}" rx="{44*s_:.0f}"'
                  f' ry="{13*s_:.0f}" fill="#cfd5da" {o(4)}/>'
                  f'<ellipse cx="{vx:.0f}" cy="{y+44*s_:.0f}" rx="{34*s_:.0f}"'
                  f' ry="{9*s_:.0f}" fill="{VODA}" opacity=".7"/></g>')
    return s


def _rogozha(x, y, w_, t, h_=120, seed=5):
    """Рогожа, которой накрывают поленницу: плетёное полотно с бахромой,
    углы прихвачены камнями, край хлопает на ветру."""
    rnd = random.Random(seed)
    hlop = 10 * A.w(t, 1.7, .2)
    s = (f'<path d="M{x:.0f},{y:.0f} Q{x+w_*.5:.0f},{y-30:.0f} {x+w_:.0f},{y:.0f}'
         f' L{x+w_-10:.0f},{y+h_+hlop:.0f} Q{x+w_*.5:.0f},{y+h_+20:.0f}'
         f' {x+10:.0f},{y+h_:.0f} Z" fill="#9c8a62" {o(6)}/>')
    for i in range(int(w_ / 48)):
        s += (f'<line x1="{x+10+i*48:.0f}" y1="{y-6:.0f}" x2="{x+14+i*48:.0f}"'
              f' y2="{y+h_+8:.0f}" stroke="#8a7a46" stroke-width="5"'
              f' opacity=".7"/>')
    for i in range(3):
        s += (f'<path d="M{x+6:.0f},{y+18+i*(h_-30)/3.0:.0f}'
              f' Q{x+w_*.5:.0f},{y+6+i*(h_-30)/3.0:.0f}'
              f' {x+w_-6:.0f},{y+20+i*(h_-30)/3.0:.0f}" fill="none"'
              f' stroke="#b8a86a" stroke-width="6" opacity=".7"/>')
    for ex in (x + 14, x + w_ - 14):
        s += (f'<ellipse cx="{ex:.0f}" cy="{y+4:.0f}" rx="26" ry="18"'
              f' fill="{KAMEN}" {o(4)}/>')
    for i in range(int(w_ / 36)):
        s += (f'<line x1="{x+12+i*36:.0f}" y1="{y+h_+6:.0f}"'
              f' x2="{x+10+i*36+rnd.uniform(-6,6):.0f}" y2="{y+h_+26:.0f}"'
              f' stroke="#8a7a46" stroke-width="4"/>')
    return s


def _zont_mokryy(x, y, t, s_=1.0, ph=.0):
    """Мокрый зонт на гвозде: сложенный купол клиньями, спицы наружу,
    крючковатая ручка, с кончика срывается капля."""
    kap = (t * .6 + ph) % 1.0
    s = (f'<rect x="{x-16:.0f}" y="{y-22:.0f}" width="32" height="14" rx="6"'
         f' fill="{ZHELEZ}" {o(3)}/>'
         f'<path d="M{x-26:.0f},{y:.0f} q{26:.0f},{-30:.0f} {52:.0f},0'
         f' L{x+30:.0f},{y+230*s_:.0f} q{-30:.0f},{26:.0f} {-60:.0f},0 Z"'
         f' fill="#3f5c7a" {o(6)}/>')
    for i in range(4):
        s += (f'<path d="M{x-20+i*14:.0f},{y+8:.0f} q{6:.0f},{110*s_:.0f}'
              f' {2:.0f},{216*s_:.0f}" fill="none" stroke="#2f4a66"'
              f' stroke-width="6" opacity=".85"/>')
    s += (f'<path d="M{x:.0f},{y+230*s_:.0f} l{-16:.0f},{34*s_:.0f}'
          f' l{10:.0f},{4*s_:.0f} l{8:.0f},{-20*s_:.0f} l{8:.0f},{20*s_:.0f}'
          f' l{10:.0f},{-4*s_:.0f} Z" fill="#2f4a66" {o(4)}/>'
          f'<path d="M{x-2:.0f},{y+266*s_:.0f} q{2:.0f},{40*s_:.0f}'
          f' {-30:.0f},{40*s_:.0f}" fill="none" stroke="#7d5636"'
          f' stroke-width="{14*s_:.0f}"/>'
          f'<ellipse cx="{x+2:.0f}" cy="{y+272*s_+kap*90:.0f}" rx="7"'
          f' ry="{11+5*kap:.0f}" fill="#9fc4d8" opacity="{1-kap:.2f}"/>')
    return s


def _plasch_na_gvozde(x, y, h_, t, ph=.0, col="#4e5a46"):
    """Мокрый плащ на гвозде: брезентовые полы, капюшон, пояс болтается,
    по подолу стекают капли."""
    kach = 1.6 * A.w(t, 3.0, ph)
    s = (f'<g transform="rotate({kach:.1f} {x:.0f} {y:.0f})">'
         f'<rect x="{x-18:.0f}" y="{y-24:.0f}" width="36" height="14" rx="6"'
         f' fill="{ZHELEZ}" {o(3)}/>'
         f'<path d="M{x:.0f},{y:.0f} q{-78:.0f},{22:.0f} {-92:.0f},{96:.0f}'
         f' L{x-82:.0f},{y+h_:.0f} L{x+82:.0f},{y+h_:.0f} L{x+92:.0f},{y+96:.0f}'
         f' q{-14:.0f},{-74:.0f} {-92:.0f},{-96:.0f} Z" fill="{col}" {o(6)}/>'
         f'<path d="M{x-44:.0f},{y+6:.0f} q{44:.0f},{-46:.0f} {88:.0f},0'
         f' q{-20:.0f},{30:.0f} {-88:.0f},0 Z" fill="#3f4a38" {o(5)}/>'
         f'<path d="M{x:.0f},{y+30:.0f} L{x+14:.0f},{y+h_:.0f}" fill="none"'
         f' stroke="#2f3a2a" stroke-width="11"/>'
         f'<path d="M{x+70:.0f},{y+h_*.52:.0f} q{34:.0f},{54:.0f} {-6:.0f},{96:.0f}"'
         f' fill="none" stroke="#3f4a38" stroke-width="13"/></g>')
    for i in range(4):
        kap = ((t * .7 + i / 4.0) % 1.0)
        s += (f'<ellipse cx="{x-58+i*38:.0f}" cy="{y+h_+8+kap*70:.0f}" rx="6"'
              f' ry="{10+5*kap:.0f}" fill="#9fc4d8" opacity="{1-kap:.2f}"/>')
    return s


def _kaloshi(x, y, s_=1.0, t=0.0, luzhica=True):
    """Калоши в лужице: два блестящих резиновых башмака с бортиком, носки
    врозь, под ними растекается вода с кругами."""
    s = ""
    if luzhica:
        s += _luzha(x + 10 * s_, y + 16 * s_, 130 * s_, t, .3, 34 * s_, "#6a8296")
    for i, (dx, ug) in enumerate(((-56 * s_, -8), (58 * s_, 10))):
        s += (f'<g transform="rotate({ug:.0f} {x+dx:.0f} {y:.0f})">'
              f'<path d="M{x+dx-50*s_:.0f},{y:.0f} q{4*s_:.0f},{-52*s_:.0f}'
              f' {40*s_:.0f},{-56*s_:.0f} q{40*s_:.0f},{2*s_:.0f}'
              f' {56*s_:.0f},{34*s_:.0f} q{10*s_:.0f},{22*s_:.0f}'
              f' {-16*s_:.0f},{24*s_:.0f} Z" fill="#2a2726" {o(5)}/>'
              f'<path d="M{x+dx-50*s_:.0f},{y-8*s_:.0f} q{50*s_:.0f},{-12*s_:.0f}'
              f' {96*s_:.0f},{14*s_:.0f}" fill="none" stroke="#5f5a56"'
              f' stroke-width="{8*s_:.0f}"/>'
              f'<path d="M{x+dx-26*s_:.0f},{y-44*s_:.0f} q{22*s_:.0f},{-14*s_:.0f}'
              f' {44*s_:.0f},{-4*s_:.0f}" fill="none" stroke="#8f979d"'
              f' stroke-width="{7*s_:.0f}"'
              f' opacity="{.4+.3*abs(A.w(t,2.6,i*.4)):.2f}"/>'
              f'<ellipse cx="{x+dx:.0f}" cy="{y+4*s_:.0f}" rx="{52*s_:.0f}"'
              f' ry="{10*s_:.0f}" fill="#1d1a18" opacity=".8"/></g>')
    return s


def _listki_tuchki(x, y, w_, t, otgib=.0, n=6, seed=7):
    """Отогнутые листки численника: каждый лист отходит веером, и на каждом
    нарисована тучка с каплями — значит сырость до конца месяца. Цифр и букв
    на листках НЕТ, только тучка."""
    s = ""
    for i in range(n):
        p = max(0.0, min(1.0, otgib * n - i))
        ug = -8 - 74 * p
        px = x + i * 6
        s += (f'<g transform="rotate({ug:.1f} {px:.0f} {y:.0f})">'
              f'<rect x="{px-w_*.5:.0f}" y="{y:.0f}" width="{w_:.0f}"'
              f' height="{w_*1.06:.0f}" rx="8" fill="#f4eedc" {o(5)}/>'
              f'<rect x="{px-w_*.5:.0f}" y="{y:.0f}" width="{w_:.0f}"'
              f' height="{w_*.14:.0f}" fill="{TKAN}" opacity=".85"/>')
        cx, cy = px, y + w_ * .52
        s += (f'<path d="M{cx-w_*.26:.0f},{cy:.0f} q{-w_*.08:.0f},{-w_*.22:.0f}'
              f' {w_*.14:.0f},{-w_*.24:.0f} q{w_*.08:.0f},{-w_*.18:.0f}'
              f' {w_*.30:.0f},{-w_*.06:.0f} q{w_*.22:.0f},{-w_*.04:.0f}'
              f' {w_*.24:.0f},{w_*.18:.0f} q{w_*.12:.0f},{w_*.06:.0f}'
              f' {w_*.02:.0f},{w_*.16:.0f} Z" fill="#8e9ab0" {o(4)}/>')
        for j in range(3):
            kap = ((t * .9 + j / 3.0 + i * .1) % 1.0)
            s += (f'<ellipse cx="{cx-w_*.14+j*w_*.14:.0f}"'
                  f' cy="{cy+w_*.10+kap*w_*.30:.0f}" rx="{w_*.026:.0f}"'
                  f' ry="{w_*.046:.0f}" fill="#9fc4d8"'
                  f' opacity="{1-kap:.2f}"/>')
        s += "</g>"
    return s


def _perila_balkona(x, y, w_, t, h_=190, reshetka=True):
    """Перила балкона: бетонный поручень, решётка из прутьев с косыми
    вставками, плита снизу и облупленная краска."""
    s = (f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="34" rx="12"'
         f' fill="{BETON}" {o(6)}/>'
         f'<rect x="{x:.0f}" y="{y-h_+34:.0f}" width="{w_:.0f}" height="12"'
         f' fill="{BETON2}" opacity=".85"/>')
    if reshetka:
        for i in range(int(w_ / 54) + 1):
            px = x + 10 + i * 54
            if px > x + w_ - 10:
                break
            s += (f'<rect x="{px:.0f}" y="{y-h_+46:.0f}" width="12"'
                  f' height="{h_-46:.0f}" rx="5" fill="#7a8288" {o(3)}/>')
        for i in range(int(w_ / 108) + 1):
            px = x + 14 + i * 108
            s += (f'<line x1="{px:.0f}" y1="{y-6:.0f}" x2="{px+96:.0f}"'
                  f' y2="{y-h_+50:.0f}" stroke="#8f979d" stroke-width="8"'
                  f' opacity=".8"/>')
    s += (f'<rect x="{x-14:.0f}" y="{y:.0f}" width="{w_+28:.0f}" height="46"'
          f' rx="10" fill="{BETON2}" {o(6)}/>')
    rnd = random.Random(int(x) + 3)
    for i in range(7):
        s += (f'<ellipse cx="{x+rnd.uniform(20,w_-20):.0f}"'
              f' cy="{y-h_+rnd.uniform(6,28):.0f}" rx="{rnd.uniform(14,30):.0f}"'
              f' ry="{rnd.uniform(5,11):.0f}" fill="#8a9298" opacity=".6"/>')
    return s


def _yaschik_barhatcev(x, y, w_, t, seed=5):
    """Ящик с засохшими бархатцами: деревянный короб, сухая земля комьями,
    бурые стебли с пустыми головками, пара листьев ещё держится."""
    rnd = random.Random(seed)
    s = (f'{ten(x + w_ * .5, y + 8, w_ * .52, 14, .45)}'
         f'<rect x="{x:.0f}" y="{y-110:.0f}" width="{w_:.0f}" height="110"'
         f' rx="8" fill="url(#dosk)" {o(6)}/>'
         f'<rect x="{x-8:.0f}" y="{y-118:.0f}" width="{w_+16:.0f}" height="20"'
         f' rx="7" fill="#8a6038" {o(4)}/>'
         f'<rect x="{x+10:.0f}" y="{y-98:.0f}" width="{w_-20:.0f}" height="26"'
         f' rx="6" fill="#4a3a2a"/>')
    for i in range(8):
        s += (f'<ellipse cx="{x+16+i*(w_-32)/7.0:.0f}" cy="{y-96:.0f}"'
              f' rx="{rnd.uniform(12,22):.0f}" ry="{rnd.uniform(6,11):.0f}"'
              f' fill="#3f3326"/>')
    for i in range(6):
        px = x + 24 + i * (w_ - 48) / 5.0
        ug = rnd.uniform(-26, 26)
        hh = rnd.uniform(90, 150)
        s += (f'<g transform="rotate({ug + 2 * A.w(t, 2.4, i * .3):.1f}'
              f' {px:.0f} {y-96:.0f})">'
              f'<path d="M{px:.0f},{y-96:.0f} q{8:.0f},{-hh*.5:.0f}'
              f' {-4:.0f},{-hh:.0f}" fill="none" stroke="#7a6a4a"'
              f' stroke-width="8"/>'
              f'<ellipse cx="{px-4:.0f}" cy="{y-96-hh:.0f}" rx="16" ry="12"'
              f' fill="#8a6a3c" {o(3)}/>')
        for j in range(2):
            s += (f'<path d="M{px+2:.0f},{y-96-hh*.5:.0f}'
                  f' q{18-j*36:.0f},{-14:.0f} {26-j*52:.0f},{4:.0f}'
                  f' q{-18+j*36:.0f},{10:.0f} {-26+j*52:.0f},{-4:.0f} Z"'
                  f' fill="#6f7a44" opacity=".85" {o(3)}/>')
        s += "</g>"
    return s


def _prischepki(x, y, w_, t, n=6, seed=3):
    """Прищепки на верёвке: деревянные с пружинкой, часть качается, часть
    висит криво; верёвка чуть провисает."""
    rnd = random.Random(seed)
    s = (f'<path d="M{x:.0f},{y:.0f} Q{x+w_*.5:.0f},{y+28:.0f} {x+w_:.0f},{y:.0f}"'
         f' fill="none" stroke="#c9b48a" stroke-width="7"/>')
    for i in range(n):
        p = i / max(1, n - 1.0)
        px = x + w_ * p
        py = y + 28 * (1 - (2 * p - 1) ** 2)
        kol = 10 * A.w(t, 1.9, i * .35)
        s += (f'<g transform="rotate({kol:.1f} {px:.0f} {py:.0f})">'
              f'<rect x="{px-11:.0f}" y="{py-4:.0f}" width="22" height="58"'
              f' rx="7" fill="#c9a47a" {o(4)}/>'
              f'<line x1="{px:.0f}" y1="{py+8:.0f}" x2="{px:.0f}" y2="{py+52:.0f}"'
              f' stroke="#8a6038" stroke-width="4"/>'
              f'<rect x="{px-13:.0f}" y="{py+16:.0f}" width="26" height="8"'
              f' rx="4" fill="#9aa3aa" {o(3)}/></g>')
    return s


def _strelka_vetra(x, y, dl, ug, t, col="#4e8ad0", n=3):
    """Синяя стрелка ветра: древко с пунктиром и наконечник, за ней ещё две
    короткие — ветер виден направлением, а не пятном."""
    s = ""
    for i in range(n):
        p = ((t * .9 + i / float(n)) % 1.0)
        d2 = dl * (.5 + .5 * p)
        a = math.radians(ug)
        ex, ey = x + d2 * math.cos(a), y + d2 * math.sin(a)
        s += (f'<line x1="{x:.0f}" y1="{y + i * 22 - 22:.0f}" x2="{ex:.0f}"'
              f' y2="{ey + i * 22 - 22:.0f}" stroke="{col}"'
              f' stroke-width="{11-3*i:.0f}" stroke-linecap="round"'
              f' opacity="{(1-p)*.9:.2f}"/>'
              f'<path d="M{ex:.0f},{ey+i*22-22:.0f}'
              f' l{-26*math.cos(a)+13*math.sin(a):.0f},'
              f'{-26*math.sin(a)-13*math.cos(a):.0f}'
              f' l{0:.0f},{26:.0f} Z" fill="{col}"'
              f' opacity="{(1-p)*.9:.2f}"/>')
    return s


def _sharf_otletaet(x, y, dl, t, ug=0.0, col=TKAN):
    """Шарф, который относит ветром: два конца летят в одну сторону волной,
    на концах бахрома."""
    s = ""
    for i, (sm, w_) in enumerate(((0, 34), (26, 26))):
        vol = 20 * A.w(t, 1.4, i * .4)
        s += (f'<path d="M{x:.0f},{y+sm:.0f}'
              f' Q{x+dl*.4:.0f},{y+sm-40+vol:.0f} {x+dl*.72:.0f},{y+sm+10:.0f}'
              f' Q{x+dl*.9:.0f},{y+sm+40+vol:.0f} {x+dl:.0f},{y+sm-6:.0f}"'
              f' fill="none" stroke="{col}" stroke-width="{w_:.0f}"'
              f' stroke-linecap="round"/>')
        for j in range(4):
            s += (f'<line x1="{x+dl:.0f}" y1="{y+sm-20+j*11:.0f}"'
                  f' x2="{x+dl+26:.0f}" y2="{y+sm-24+j*14:.0f}" stroke="{col}"'
                  f' stroke-width="5"/>')
    s += (f'<path d="M{x-20:.0f},{y+4:.0f} q{22:.0f},{18:.0f} {44:.0f},{2:.0f}"'
          f' fill="none" stroke="{col}" stroke-width="30"/>')
    return s


def _buda_s_psom(x, y, s_=1.0, t=0.0, ph=.0):
    """Будка и пёс: двускатная конура с круглым лазом и жестяной кромкой,
    пёс лежит у входа — голова на лапах, ухо поводит, хвост постукивает,
    на колышке цепь."""
    w2, h2 = 220 * s_, 190 * s_
    s = (f'{ten(x, y + 10 * s_, w2 * .56, 16 * s_, .5)}'
         f'<rect x="{x-w2/2:.0f}" y="{y-h2:.0f}" width="{w2:.0f}"'
         f' height="{h2:.0f}" rx="8" fill="url(#dosk)" {o(7)}/>'
         f'<path d="M{x-w2*.60:.0f},{y-h2:.0f} L{x:.0f},{y-h2-80*s_:.0f}'
         f' L{x+w2*.60:.0f},{y-h2:.0f} Z" fill="#6b5340" {o(6)}/>'
         f'<circle cx="{x:.0f}" cy="{y-h2*.46:.0f}" r="{w2*.26:.0f}"'
         f' fill="#241a12" {o(5)}/>'
         f'<circle cx="{x:.0f}" cy="{y-h2*.46:.0f}" r="{w2*.26:.0f}"'
         f' fill="none" stroke="#8f979d" stroke-width="{7*s_:.0f}"/>')
    for i in range(5):
        s += (f'<line x1="{x-w2*.44+i*w2*.22:.0f}" y1="{y-h2+8*s_:.0f}"'
              f' x2="{x-w2*.44+i*w2*.22:.0f}" y2="{y-6*s_:.0f}"'
              f' stroke="#5b4428" stroke-width="{max(3,5*s_):.0f}" opacity=".7"/>')
    # пёс лежит у входа
    px = x + w2 * .72
    hv = 22 * s_ * A.w(t, 1.5, ph)
    uho = 8 * s_ * A.w(t, 2.6, ph + .3)
    s += (f'{ten(px, y + 6 * s_, 96 * s_, 16 * s_, .45)}'
          f'<ellipse cx="{px:.0f}" cy="{y-36*s_:.0f}" rx="{104*s_:.0f}"'
          f' ry="{40*s_:.0f}" fill="#8a6a4a" {o(5)}/>'
          f'<path d="M{px-104*s_:.0f},{y-30*s_:.0f} q{-40*s_:.0f},{10*s_:.0f}'
          f' {-54*s_:.0f},{hv:.0f}" fill="none" stroke="#8a6a4a"'
          f' stroke-width="{18*s_:.0f}" stroke-linecap="round"/>'
          f'<circle cx="{px+92*s_:.0f}" cy="{y-56*s_:.0f}" r="{42*s_:.0f}"'
          f' fill="#9c7a56" {o(5)}/>'
          f'<path d="M{px+120*s_:.0f},{y-44*s_:.0f} q{36*s_:.0f},{4*s_:.0f}'
          f' {38*s_:.0f},{20*s_:.0f} q{-24*s_:.0f},{12*s_:.0f}'
          f' {-44*s_:.0f},{4*s_:.0f} Z" fill="#9c7a56" {o(4)}/>'
          f'<circle cx="{px+156*s_:.0f}" cy="{y-30*s_:.0f}" r="{9*s_:.0f}"'
          f' fill="{K}"/>'
          f'<path d="M{px+64*s_:.0f},{y-86*s_:.0f} q{-10*s_:.0f},{-34*s_-uho:.0f}'
          f' {18*s_:.0f},{-40*s_:.0f} q{10*s_:.0f},{22*s_:.0f} {2*s_:.0f},{44*s_:.0f} Z"'
          f' fill="#7a5a3c" {o(4)}/>'
          f'<circle cx="{px+104*s_:.0f}" cy="{y-66*s_:.0f}" r="{7*s_:.0f}"'
          f' fill="{K}"/>'
          f'<path d="M{px+40*s_:.0f},{y-8*s_:.0f} q{30*s_:.0f},{10*s_:.0f}'
          f' {64*s_:.0f},{2*s_:.0f}" fill="none" stroke="#7a5a3c"'
          f' stroke-width="{16*s_:.0f}" stroke-linecap="round"/>')
    s += (f'<rect x="{x-w2*.74:.0f}" y="{y-40*s_:.0f}" width="{14*s_:.0f}"'
          f' height="{44*s_:.0f}" rx="6" fill="{ZHELEZ}" {o(3)}/>')
    for i in range(6):
        s += (f'<circle cx="{x-w2*.70+i*20*s_:.0f}"'
              f' cy="{y-20*s_+6*s_*math.sin(i+t):.0f}" r="{8*s_:.0f}"'
              f' fill="none" stroke="{ZHELEZ}" stroke-width="{4*s_:.0f}"/>')
    return s


def _miska_zerna(x, y, s_=1.0, t=0.0, syplet=.0):
    """Миска с зерном для кур: эмалированная чашка со сколом, зерно горкой,
    пара зёрен летит вниз, когда её наклоняют."""
    r = 76 * s_
    s = (f'{ten(x, y + 8 * s_, r * .9, 12 * s_, .45)}'
         f'<path d="M{x-r:.0f},{y-r*.40:.0f} q{r*.12:.0f},{r*.82:.0f}'
         f' {r*1.0:.0f},{r*.82:.0f} q{r*.88:.0f},0 {r*1.0:.0f},{-r*.82:.0f} Z"'
         f' fill="#e7edf0" {o(6)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-r*.40:.0f}" rx="{r:.0f}"'
         f' ry="{r*.26:.0f}" fill="#cfd8dc" {o(4)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-r*.38:.0f}" rx="{r*.84:.0f}"'
         f' ry="{r*.20:.0f}" fill="#c9a331" opacity=".95"/>'
         f'<path d="M{x+r*.84:.0f},{y-r*.46:.0f} l{r*.12:.0f},{r*.08:.0f}'
         f' l{-r*.12:.0f},{r*.10:.0f} Z" fill="#9aa3aa" {o(3)}/>')
    rnd = random.Random(int(x) + 19)
    for i in range(14):
        s += (f'<ellipse cx="{x+rnd.uniform(-r*.7,r*.7):.0f}"'
              f' cy="{y-r*.44+rnd.uniform(-r*.08,r*.06):.0f}" rx="{5*s_:.0f}"'
              f' ry="{3.4*s_:.0f}" fill="#d8c08a" opacity=".9"/>')
    if syplet > .05:
        for i in range(7):
            p = ((t * 1.4 + i / 7.0) % 1.0)
            s += (f'<ellipse cx="{x+r*.6+rnd.uniform(-14,14):.0f}"'
                  f' cy="{y-r*.3+p*140:.0f}" rx="{4*s_:.0f}" ry="{3*s_:.0f}"'
                  f' fill="#d8c08a" opacity="{(1-p)*syplet:.2f}"/>')
    return s


def _balkon_plita(x, y, w_, t, h_=40, verevki=2):
    """Балконная плита соседнего балкона: бетонная консоль, экран-отбортовка
    и верёвки с бельём — этажи повторяются, двор читается колодцем."""
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="8" fill="{BETON2}" {o(5)}/>'
         f'<rect x="{x:.0f}" y="{y-150:.0f}" width="{w_:.0f}" height="150"'
         f' rx="6" fill="{BETON}" opacity=".9" {o(4)}/>')
    for i in range(int(w_ / 46)):
        s += (f'<line x1="{x+10+i*46:.0f}" y1="{y-148:.0f}"'
              f' x2="{x+10+i*46:.0f}" y2="{y-4:.0f}" stroke="#8a9298"'
              f' stroke-width="6" opacity=".7"/>')
    return s


def _navolochka_parus(x, y, w_, t, k=1.0, col="#f4eedc"):
    """Наволочка, надувающаяся парусом: полотнище выгибается по ветру, угол
    приколот прищепкой, по кромке строчка."""
    puz = (40 + 30 * A.w(t, 1.5, .2)) * k
    s = (f'<path d="M{x:.0f},{y:.0f} L{x+w_:.0f},{y-14:.0f}'
         f' Q{x+w_+puz:.0f},{y+w_*.5:.0f} {x+w_*.92:.0f},{y+w_*1.02:.0f}'
         f' Q{x+w_*.4:.0f},{y+w_*1.14:.0f} {x+8:.0f},{y+w_*.98:.0f}'
         f' Q{x-10:.0f},{y+w_*.5:.0f} {x:.0f},{y:.0f} Z" fill="{col}" {o(6)}/>')
    for i in range(3):
        s += (f'<path d="M{x+w_*(.22+i*.26):.0f},{y-8:.0f}'
              f' q{puz*.4:.0f},{w_*.5:.0f} {puz*.2:.0f},{w_*1.0:.0f}"'
              f' fill="none" stroke="#dcd3bb" stroke-width="6" opacity=".85"/>')
    s += (f'<path d="M{x+6:.0f},{y+w_*.96:.0f} Q{x+w_*.5:.0f},{y+w_*1.10:.0f}'
          f' {x+w_*.90:.0f},{y+w_*.98:.0f}" fill="none" stroke="{TKAN2}"'
          f' stroke-width="7" opacity=".7"/>')
    return s


def _kresla_ryad(x, y, w_, t, n=3, h_=300, col="#7a2338", krupno=False):
    """Ряд бархатных кресел кинозала: спинка валиком с пуговицами, сиденье
    откинуто, подлокотники с деревянной накладкой, литые боковины на полу."""
    s = ""
    dw = w_ / float(n)
    for i in range(n):
        bx = x + i * dw
        s += (f'{ten(bx + dw * .5, y + 8, dw * .46, 14, .5)}'
              f'<path d="M{bx+10:.0f},{y-h_:.0f} q{dw*.5-10:.0f},{-40:.0f}'
              f' {dw-20:.0f},0 L{bx+dw-14:.0f},{y-h_*.40:.0f}'
              f' L{bx+14:.0f},{y-h_*.40:.0f} Z" fill="{col}" {o(6)}/>')
        for j in range(3):
            s += (f'<circle cx="{bx+dw*(.26+j*.24):.0f}" cy="{y-h_*.70:.0f}"'
                  f' r="{9 if krupno else 6:.0f}" fill="#5a1626" {o(3)}/>')
        s += (f'<rect x="{bx+8:.0f}" y="{y-h_*.42:.0f}" width="{dw-16:.0f}"'
              f' height="{h_*.16:.0f}" rx="12" fill="#8a2a40" {o(5)}/>'
              f'<rect x="{bx+4:.0f}" y="{y-h_*.28:.0f}" width="{dw-8:.0f}"'
              f' height="{h_*.10:.0f}" rx="10" fill="#6a1c30" {o(4)}/>')
        for e in (bx + 2, bx + dw - 26):
            s += (f'<rect x="{e:.0f}" y="{y-h_*.46:.0f}" width="24"'
                  f' height="{h_*.46:.0f}" rx="9" fill="#5a4530" {o(4)}/>'
                  f'<rect x="{e-4:.0f}" y="{y-h_*.50:.0f}" width="32"'
                  f' height="18" rx="8" fill="#7d5636" {o(3)}/>')
    return s


def _kepka_i_rupor(x, y, s_=1.0, t=0.0):
    """Режиссёрская кепка на рупоре: кепка с козырьком и пуговкой лежит
    поверх жестяного рупора с ремешком."""
    s = (f'<path d="M{x-96*s_:.0f},{y:.0f} L{x+10*s_:.0f},{y-54*s_:.0f}'
         f' L{x+20*s_:.0f},{y+54*s_:.0f} Z" fill="#8f979d" {o(6)}/>'
         f'<ellipse cx="{x-96*s_:.0f}" cy="{y:.0f}" rx="{14*s_:.0f}"'
         f' ry="{26*s_:.0f}" fill="#6f767c" {o(4)}/>'
         f'<ellipse cx="{x+16*s_:.0f}" cy="{y:.0f}" rx="{16*s_:.0f}"'
         f' ry="{56*s_:.0f}" fill="#b9c6cc" {o(5)}/>'
         f'<path d="M{x-60*s_:.0f},{y+30*s_:.0f} q{30*s_:.0f},{34*s_:.0f}'
         f' {66*s_:.0f},{18*s_:.0f}" fill="none" stroke="#7d5636"'
         f' stroke-width="{9*s_:.0f}"/>')
    s += (f'<path d="M{x-40*s_:.0f},{y-56*s_:.0f} q{60*s_:.0f},{-56*s_:.0f}'
          f' {120*s_:.0f},{-6*s_:.0f} q{6*s_:.0f},{30*s_:.0f}'
          f' {-50*s_:.0f},{34*s_:.0f} q{-54*s_:.0f},{4*s_:.0f}'
          f' {-70*s_:.0f},{-28*s_:.0f} Z" fill="#4a4036" {o(5)}/>'
          f'<path d="M{x+70*s_:.0f},{y-62*s_:.0f} q{54*s_:.0f},{6*s_:.0f}'
          f' {62*s_:.0f},{26*s_:.0f} q{-30*s_:.0f},{14*s_:.0f}'
          f' {-66*s_:.0f},{2*s_:.0f} Z" fill="#3d352c" {o(4)}/>'
          f'<circle cx="{x+20*s_:.0f}" cy="{y-84*s_:.0f}" r="{9*s_:.0f}"'
          f' fill="#5e5347" {o(3)}/>'
          f'<path d="M{x-24*s_:.0f},{y-70*s_:.0f} q{50*s_:.0f},{-26*s_:.0f}'
          f' {100*s_:.0f},{-10*s_:.0f}" fill="none" stroke="#6a5f52"'
          f' stroke-width="{7*s_:.0f}" opacity=".8"/>')
    return s


def _korobka_katushki(x, y, s_=1.0, t=0.0, perchatki=True):
    """Жестяная коробка с киноплёночной катушкой и пара белых перчаток:
    круглая банка с ободом, катушка с сердечником и витками плёнки, блик по
    ободу ходит."""
    r = 92 * s_
    bl = .3 + .5 * abs(A.w(t, 2.2, .2))
    s = (f'{ten(x, y + 10 * s_, r * .96, 14 * s_, .5)}'
         f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{r:.0f}" ry="{r*.30:.0f}"'
         f' fill="#8f979d" {o(6)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-18*s_:.0f}" rx="{r:.0f}"'
         f' ry="{r*.30:.0f}" fill="#b9c6cc" {o(5)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-20*s_:.0f}" rx="{r*.86:.0f}"'
         f' ry="{r*.24:.0f}" fill="#9aa3aa" opacity=".9"/>')
    s += (f'<g transform="translate({r*.30:.0f},{-r*.52:.0f})">'
          f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{r*.74:.0f}" ry="{r*.24:.0f}"'
          f' fill="#3d3a38" {o(5)}/>')
    for i in range(3):
        s += (f'<ellipse cx="{x:.0f}" cy="{y-i*7*s_:.0f}" rx="{r*(.70-i*.10):.0f}"'
              f' ry="{r*(.22-i*.03):.0f}" fill="none" stroke="#2a2726"'
              f' stroke-width="{max(2,4*s_):.0f}"/>')
    s += (f'<ellipse cx="{x:.0f}" cy="{y-24*s_:.0f}" rx="{r*.22:.0f}"'
          f' ry="{r*.08:.0f}" fill="#8f979d" {o(3)}/>'
          f'<path d="M{x-r*.62:.0f},{y-r*.10:.0f} q{r*.30:.0f},{-r*.16:.0f}'
          f' {r*.60:.0f},{-r*.02:.0f}" fill="none" stroke="#eef2f4"'
          f' stroke-width="{9*s_:.0f}" opacity="{bl:.2f}"/></g>')
    if perchatki:
        for i, (dx, ug) in enumerate(((-r * 1.10, -16), (-r * .64, 12))):
            s += (f'<g transform="rotate({ug:.0f} {x+dx:.0f} {y+r*.18:.0f})">'
                  f'<path d="M{x+dx-40*s_:.0f},{y+r*.18:.0f}'
                  f' q{6*s_:.0f},{-44*s_:.0f} {40*s_:.0f},{-46*s_:.0f}'
                  f' q{34*s_:.0f},{2*s_:.0f} {40*s_:.0f},{30*s_:.0f}'
                  f' q{4*s_:.0f},{18*s_:.0f} {-16*s_:.0f},{18*s_:.0f} Z"'
                  f' fill="#f4f8fa" {o(5)}/>'
                  f'<path d="M{x+dx-34*s_:.0f},{y+r*.10:.0f} q{34*s_:.0f},'
                  f'{-14*s_:.0f} {66*s_:.0f},{-2*s_:.0f}" fill="none"'
                  f' stroke="#cfd8dc" stroke-width="{6*s_:.0f}"/></g>')
    return s


def _ekran_kino(x, y, w_, h_, t, luch=.0):
    """Белый экран кинозала: полотно в рамке с заклёпками, по краям тёмные
    кулисы со складками, в середине слабое дежурное свечение."""
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="6" fill="#d8d2c4" {o(8)}/>'
         f'<rect x="{x+18:.0f}" y="{y+18:.0f}" width="{w_-36:.0f}"'
         f' height="{h_-36:.0f}" rx="4" fill="#e8e2d4"/>'
         f'<ellipse cx="{x+w_*.5:.0f}" cy="{y+h_*.5:.0f}" rx="{w_*.34:.0f}"'
         f' ry="{h_*.34:.0f}" fill="#f4f0e4" opacity="{.30+.30*luch:.2f}"/>')
    for i in range(14):
        s += (f'<circle cx="{x+20+i*(w_-40)/13.0:.0f}" cy="{y+9:.0f}" r="5"'
              f' fill="#9aa3aa"/>'
              f'<circle cx="{x+20+i*(w_-40)/13.0:.0f}" cy="{y+h_-9:.0f}" r="5"'
              f' fill="#9aa3aa"/>')
    for e, sg in ((x - 14, -1), (x + w_ + 14, 1)):
        for i in range(5):
            s += (f'<path d="M{e+sg*i*34:.0f},{y-30:.0f}'
                  f' q{sg*26:.0f},{h_*.5:.0f} {sg*4:.0f},{h_+40:.0f}'
                  f' l{sg*32:.0f},0 q{sg*20:.0f},{-h_*.5:.0f}'
                  f' {-sg*2:.0f},{-h_-40:.0f} Z" fill="#3a1e26"'
                  f' opacity="{.9-i*.09:.2f}" {o(3)}/>')
    return s


# ── ДЕКОРАЦИИ, ТРЕТЬЯ ПАРТИЯ ──────────────────────────────────────────────

def flyuger_na_sever(t):
    """Конёк крыши и кованый флюгер-петух крупно на ясном звёздном небе:
    флюгер разворачивается клювом на север. Хозяин в тулупе стоит на
    приставной лестнице, левой держится за тетиву, правой послюнявленным
    пальцем проверяет ветер. Внизу во дворе лужа схватывается льдом, бельё
    на верёвке деревенеет."""
    rnd = random.Random(701)
    gor = 860
    pov = A.ease(A.seg(t, .4, 1.8))
    led = A.ease(A.seg(t, 1.0, 2.2))
    s = f'<rect width="{W}" height="{H}" fill="url(#nnoch)"/>'
    s += nebo("noch", t, True, 121)
    for i in range(16):
        bx, by_ = rnd.uniform(60, W - 60), rnd.uniform(40, 420)
        mig = .4 + .6 * abs(A.w(t, 1.1 + i * .07, i * .3))
        s += SL(Z_NEBO, f'<path d="M{bx:.0f},{by_-16:.0f} l{4:.0f},{12:.0f}'
                        f' l{12:.0f},{4:.0f} l{-12:.0f},{4:.0f} l{-4:.0f},{12:.0f}'
                        f' l{-4:.0f},{-12:.0f} l{-12:.0f},{-4:.0f} l{12:.0f},{-4:.0f} Z"'
                        f' fill="#e8eef6" opacity="{mig:.2f}"/>')
    s += SL(Z_DAL, _derevnya_ryad(gor - 120, t, 123, ((120, 300), (1740, 260))))
    # КОНЁК КРЫШИ и ГЛАВНЫЙ ПРЕДМЕТ: флюгер-петух
    # сруб ПОД коньком: крыша не висит в воздухе, а стоит на стене, и центр
    # кадра занят брёвнами, а не пустым небом (замер пустоты)
    s += SL(Z_SRED, brevna(540, 740, 860, gor - 700, 88)
            + f'<rect x="520" y="726" width="900" height="26" rx="9"'
              f' fill="#5a4530" {o(5)}/>')
    s += SL(Z_SRED, okno_izby(760, 790, 290, 200, t, None, .34, True, True))
    s += SL(Z_SRED, _konek_kryshi(560, 300, 820, t, 125, True))
    s += SL(Z_SRED, _flyuger_petuh(970, 290, 1.25, t, -34 + 112 * pov, True))
    # хозяин на приставной лестнице у крыши
    s += SL(Z_SRED, _lestnica(1360, gor + 40, 700, t, 6, 9.0))
    hx, hy, hh = 1300, gor - 290, 540
    _figury_kadra((hx, hy, hh))
    hoz = figura(hx, hy, hh, t, col="#4e4036", kant="#cfe4f5", ph=.3,
                 shapka=True, tulup=True, boroda=True, naklon=4.0)
    r1, (a1x, a1y), _ = _ruka_mimo(hx, hy, hh, 1, hh * .34, 28, t,
                                   "#4e4036", "#cfe4f5", .2, 4.0)
    r2, (a2x, a2y), _ = _ruka_so_sgibom(hx, hy, hh, -1, hh * .22, -22,
                                        hh * .20, -52, t, "#4e4036",
                                        "#cfe4f5", .7, 4.0)
    hoz += r1 + r2
    s += SL(Z_SRED, hoz)
    # варежка держит тетиву лестницы (перекрытие по стойке), второй кисти нет:
    # поднятый палец читается самим рукавом, пальцев мы не рисуем
    s += SL(Z_SRED, _varezhka(a1x, a1y + 2, hh, t, .2))
    s += SL(Z_SRED, f'<ellipse cx="{a2x:.0f}" cy="{a2y-22:.0f}" rx="12"'
                    f' ry="28" fill="#e8d8c0" {o(4)}/>')
    s += SL(Z_SRED, _strelka_vetra(a2x + 40, a2y - 30, 150, 14, t, "#4e8ad0", 3))
    s += SL(Z_SRED, para_izo_rta(hx + 32, hy - hh * .80, t, .4, 1.0, .55))
    # ДВОР ВНИЗУ: земля, лужа со льдом, бельё деревенеет
    s += SL(Z_SRED, f'<rect x="0" y="{gor+40:.0f}" width="{W}"'
                    f' height="{H-gor-40:.0f}" fill="#3f4238"/>'
            + sneg_lezhit(gor + 70, 26)
            + _zemlya_faktura(gor + 100, 1072, 127, 16, "#2f3228")
            + _inej(129, 26, gor + 90, 1070))
    s += SL(Z_SRED, _luzha_so_ldom(540, 1010, 230, t, led, .2))
    s += SL(Z_SRED, _bele_na_verevke(60, 740, 520, t, .25, 4, 131, led))
    s += SL(Z_SRED, _polenica(1620, 1040, 300, 200, 133, 26)
            + _sani(1120, 1046, .8, t, True)
            + _dvorovaya_utvar(820, 1046, 240, t, 135, ["kadka", "vedro"])
            + _sledy(300, 1070, 1180, gor + 110, 7, 137, "#2a2d24", 1.0))
    s += SL(Z_SRED, dym(220, gor - 260, t, 4, .26, 260, .3, "#8e9ab0", 1.3))
    s += SL(Z_SRED, _vorona(1700, gor - 180, t, .8, .3, .4))
    s += SL(Z_LETIT, _inej(139, 20, 300, 760))
    s += SL(Z_PERED, _stolb_pered(-8, 110, "#121018", 0, H))
    s += vinetka(.46)
    return s


def flyuger_na_yug(t):
    """Тот же флюгер-петух разворачивается клювом на юг, небо затягивает
    мягкими облаками. Хозяин внизу во дворе правой рукой снимает шапку,
    левой расстёгивает верхний крючок тулупа. Лёд на луже подтаивает, с
    крыши падает капля, воробьи купаются в луже."""
    rnd = random.Random(743)
    gor = 850
    pov = A.ease(A.seg(t, .3, 1.5))
    tay = A.ease(A.seg(t, .6, 1.6))
    s = f'<rect width="{W}" height="{H}" fill="url(#nsumer)"/>'
    s += nebo("sumer", t, False, 141)
    s += oblaka(t, 150, 7, 143, .56, "#d6dde4", 9.0)
    s += oblaka(t, 300, 5, 145, .44, "#c4cdd8", 13.0)
    s += SL(Z_DAL, _derevnya_ryad(gor - 110, t, 147, ((140, 320), (1720, 280))))
    s += SL(Z_SRED, brevna(440, 700, 960, gor - 660, 88)
            + f'<rect x="420" y="686" width="1000" height="26" rx="9"'
              f' fill="#5a4530" {o(5)}/>')
    s += SL(Z_SRED, okno_izby(700, 750, 300, 210, t, None, .10, True, True))
    # сарай справа с дворовым хозяйством на стене — вещи, а не пустое небо
    s += SL(Z_SRED, _stena_ambara(1460, 420, 460, 470, t, False, 163))
    s += SL(Z_SRED, _stennoe_hozyaystvo(1560, 520, t, 165))
    s += SL(Z_SRED, _konek_kryshi(440, 240, 980, t, 149, False))
    s += SL(Z_SRED, _flyuger_petuh(930, 230, 1.15, t, 146 - 128 * pov, True))
    # капля с крыши
    for i in range(3):
        kap = ((t * .8 + i / 3.0) % 1.0)
        s += SL(Z_SRED, f'<ellipse cx="{620+i*180:.0f}"'
                        f' cy="{706+kap*260:.0f}" rx="8"'
                        f' ry="{13+7*kap:.0f}" fill="#9fc4d8"'
                        f' opacity="{(1-kap)*.9:.2f}"/>')
    # ДВОР: земля, лужа подтаивает, воробьи купаются
    s += SL(Z_SRED, f'<rect x="0" y="{gor+30:.0f}" width="{W}"'
                    f' height="{H-gor-30:.0f}" fill="#4a4a40"/>'
            + sneg_lezhit(gor + 60, 22)
            + _zemlya_faktura(gor + 96, 1072, 151, 16, "#3a3a30"))
    s += SL(Z_SRED, _luzha_so_ldom(1200, 1000, 260, t, 1.0 - tay, .3))
    for i, (bx, bs, bp) in enumerate(((1090, 1.3, .0), (1200, .68, .3),
                                      (1320, 1.1, .6))):
        s += SL(Z_SRED, ptica(bx, 960 - 30 * abs(A.w(t, 2.2, bp)), t, bs,
                              "#8a7a5c", bp, "#6b7a88"))
    s += SL(Z_SRED, _bele_na_verevke(60, 700, 480, t, 1.0, 4, 153, .0))
    # ОДНА ФИГУРА во дворе: снимает шапку, расстёгивает крючок
    hx, hy, hh = 620, 1018, 730
    _figury_kadra((hx, hy, hh))
    snim = A.ease(A.seg(t, .5, 1.1))
    hoz = figura(hx, hy, hh, t, col="#4e4036", kant="#cfe4f5", ph=.3,
                 tulup=True, boroda=True, naklon=4.0)
    r1, (b1x, b1y), _ = _ruka_so_sgibom(hx, hy, hh, 1, hh * .22, -30 - 20 * snim,
                                        hh * .20, -54, t, "#4e4036",
                                        "#cfe4f5", .2, 4.0)
    r2, (b2x, b2y), _ = _ruka_so_sgibom(hx, hy, hh, -1, hh * .20, -24,
                                        hh * .18, -44, t, "#4e4036",
                                        "#cfe4f5", .7, 4.0)
    hoz += r1 + r2
    s += SL(Z_SRED, hoz)
    # ШАПКА, снятая с головы: лежит в кисти, варежка перекрывает её околыш
    s += SL(Z_SRED, f'<g transform="rotate({-14 + 10 * snim:.1f} {b1x:.0f} {b1y:.0f})">'
                    f'<path d="M{b1x-54:.0f},{b1y+10:.0f} q{54:.0f},{-72:.0f}'
                    f' {108:.0f},0 q{-20:.0f},{26:.0f} {-108:.0f},0 Z"'
                    f' fill="#4a3f36" {o(5)}/>'
                    f'<ellipse cx="{b1x:.0f}" cy="{b1y+12:.0f}" rx="58"'
                    f' ry="20" fill="#cfc1a4" {o(4)}/></g>')
    s += SL(Z_SRED, _varezhka(b1x, b1y + 4, hh, t, .2))
    # РАССТЁГНУТЫЙ КРЮЧОК ворота: петля отходит в сторону
    s += SL(Z_SRED, f'<path d="M{hx-hh*.08:.0f},{hy-hh*.64:.0f}'
                    f' q{hh*.03:.0f},{hh*.03:.0f} {hh*.02+hh*.03*snim:.0f},'
                    f'{hh*.06:.0f}" fill="none" stroke="{ZHELEZ}"'
                    f' stroke-width="{hh*.012:.0f}"/>'
            + f'<path d="M{hx+hh*.04:.0f},{hy-hh*.64:.0f} q{hh*.02:.0f},'
              f'{hh*.03:.0f} {-hh*.01-hh*.03*snim:.0f},{hh*.06:.0f}"'
              f' fill="none" stroke="{ZHELEZ}" stroke-width="{hh*.012:.0f}"/>')
    s += SL(Z_SRED, _varezhka(b2x, b2y + 4, hh, t, .7))
    s += SL(Z_SRED, dym(240, gor - 240, t, 5, .30, 300, .34, "#cfd6de", 1.6))
    s += SL(Z_SRED, _polenica(80, 1046, 320, 200, 155, 26)
            + _dvorovaya_utvar(1600, 1046, 260, t, 157, ["kadka", "vedro"])
            + _kucha_listev(900, 1052, 300, 159, 74)
            + _sani(1700, 1040, .76, t, False))
    s += SL(Z_SRED, _kot_zhivoy(400, 1040, t, 1.1, "#4a4440", .3))
    s += SL(Z_PERED, _vetka_pered(1960, 160, 560, 156, t, 161, "#2a2318", 6))
    s += vinetka(.42)
    return s


def luna_v_dymke_nad_kolodcem(t):
    """Ночной двор: колодец с воротом крупно, в небе круглая луна в мутном
    кольце. В тёмном проёме колодезного сруба, как в зеркале, стоит настоящая
    луна в дымке. Бабка в шали обеими руками держит ворот, смотрит то на
    небо, то в колодец и качает головой. У колодца ведро, коромысло, кот на
    срубе, рядом поленница под рогожей."""
    rnd = random.Random(769)
    gor = 760
    s = f'<rect width="{W}" height="{H}" fill="url(#nnoch)"/>'
    s += nebo("noch", t, True, 167)
    s += oblaka(t, 180, 5, 169, .32, "#6f7f8c", 16.0)
    # ЛУНА В МУТНОМ КОЛЬЦЕ — мерцает
    mig = .78 + .18 * abs(A.w(t, 1.3, .2))
    s += SL(Z_NEBO, f'<circle cx="1480" cy="190" r="200" fill="#8e9ab0"'
                    f' opacity="{.16*mig:.2f}"/>'
            + f'<circle cx="1480" cy="190" r="140" fill="#cfe4f5"'
              f' opacity="{.22*mig:.2f}"/>'
            + f'<circle cx="1480" cy="190" r="92" fill="#e8eef6"'
              f' opacity="{mig:.2f}"/>'
            + f'<circle cx="1510" cy="164" r="20" fill="#cfd6de" opacity=".5"/>'
            + f'<circle cx="1452" cy="212" r="14" fill="#cfd6de" opacity=".45"/>'
            + f'<circle cx="1480" cy="190" r="168" fill="none" stroke="#cfe4f5"'
              f' stroke-width="9" opacity="{.26*mig:.2f}"/>')
    s += SL(Z_DAL, _derevnya_ryad(gor - 150, t, 171, ((140, 300), (1760, 250))))
    s += SL(Z_DAL, _zabor_dosok(-30, gor - 200, 1010, 200, 173, 54))
    s += SL(Z_DAL, goloe_derevo(1700, gor + 20, 480, t, 175, 8, "#2f3038", True))
    s += SL(Z_SRED, f'<rect x="0" y="{gor+20:.0f}" width="{W}"'
                    f' height="{H-gor-20:.0f}" fill="#2f3228"/>'
            + sneg_lezhit(gor + 50, 24)
            + _zemlya_faktura(gor + 90, 1072, 177, 16, "#262a22"))
    # ГЛАВНЫЙ ПРЕДМЕТ: колодец, в его срубе — проём под настоящий кадр
    s += SL(Z_SRED, _kolodec(560, gor + 170, 660, t, 330, True))
    px, py, pw, ph_ = 580, gor - 148, 620, 300
    # проём колодца узок по срубу, поэтому кадр ставим в ПЛОСКОСТИ воды:
    # широкий прямоугольник по горлу сруба, гейт требует от 760 px
    px, py, pw, ph_ = 500, gor - 142, 780, 310
    put = kontur_proema(px, py, pw, ph_, "pryam")
    vid = (f'<path d="{put}" fill="#101620"/>'
           f'<ellipse cx="{px+pw*.5:.0f}" cy="{py+ph_*.5:.0f}"'
           f' rx="{pw*.34:.0f}" ry="{ph_*.30:.0f}" fill="#2b3550" opacity=".9"/>'
           f'<ellipse cx="{px+pw*.5:.0f}" cy="{py+ph_*.48:.0f}"'
           f' rx="{pw*.17:.0f}" ry="{ph_*.15:.0f}" fill="#cfe4f5"'
           f' opacity="{.5+.3*abs(A.w(t,1.7,.3)):.2f}"/>')
    for i in range(4):
        vid += (f'<path d="M{px+60:.0f},{py+ph_*(.30+i*.16):.0f}'
                f' q{pw*.24:.0f},{-10 - 8 * A.w(t, 1.9, i * .3):.0f}'
                f' {pw*.46:.0f},0 q{pw*.22:.0f},{10:.0f} {pw*.42:.0f},{-4:.0f}"'
                f' fill="none" stroke="#9fc4d8" stroke-width="7" opacity=".5"/>')
    s += SL(Z_SRED, vid + mesto_stoka(px, py, pw, ph_, "pryam"))
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#4e3c2c"'
                    f' stroke-width="34"/>'
            + f'<rect x="{px-24:.0f}" y="{py-34:.0f}" width="{pw+48:.0f}"'
              f' height="40" rx="14" fill="{BREVNO}" {o(6)}/>'
            + f'<rect x="{px-24:.0f}" y="{py+ph_-8:.0f}" width="{pw+48:.0f}"'
              f' height="36" rx="14" fill="{BREVNO2}" {o(6)}/>')
    # ведро, коромысло, кот на срубе
    s += SL(Z_SRED, _koromyslo(1480, gor + 40, 1.0, t, True))
    s += SL(Z_SRED, _kot_zhivoy(1180, py - 40, t, 1.15, "#2f2a26", .3))
    # ОДНА ФИГУРА: бабка в шали, ОБЕ руки на вороте
    bx, by_, bh = 1400, gor + 250, 700
    _figury_kadra((bx, by_, bh))
    kach = A.w(t, 1.2, .2)
    bab = figura(bx, by_, bh, t, col="#54505e", kant="#cfe4f5", platok=True,
                 ph=.4, naklon=6.0)
    r1, (c1x, c1y), _ = _ruka_mimo(bx, by_, bh, -1, bh * .40, -12 + 8 * kach, t,
                                   "#54505e", "#cfe4f5", .2, 5.0)
    r2, (c2x, c2y), _ = _ruka_sgib_mimo(bx, by_, bh, -1, bh * .24, 10,
                                        bh * .24, -22, t, "#54505e",
                                        "#cfe4f5", .7, 4.0)
    bab += r1 + r2
    s += SL(Z_SRED, bab)
    # ШАЛЬ поверх платка — бахрома по плечам, узел на груди
    s += SL(Z_SRED, f'<path d="M{bx-bh*.17:.0f},{by_-bh*.62:.0f}'
                    f' q{bh*.17:.0f},{-bh*.05:.0f} {bh*.34:.0f},0'
                    f' L{bx+bh*.10:.0f},{by_-bh*.34:.0f}'
                    f' L{bx-bh*.10:.0f},{by_-bh*.34:.0f} Z" fill="#8a4a5c"'
                    f' {o(5)}/>'
            + "".join(f'<line x1="{bx-bh*.09+i*bh*.03:.0f}"'
                      f' y1="{by_-bh*.34:.0f}" x2="{bx-bh*.095+i*bh*.03:.0f}"'
                      f' y2="{by_-bh*.30:.0f}" stroke="#8a4a5c"'
                      f' stroke-width="{bh*.009:.0f}"/>' for i in range(7)))
    s += SL(Z_SRED, _varezhka(c1x, c1y + 2, bh, t, .2)
            + _varezhka(c2x, c2y + 2, bh, t, .7))
    s += SL(Z_SRED, para_izo_rta(bx - 40, by_ - bh * .80, t, .3, 1.0, .5))
    # поленница под рогожей, которую она идёт накрывать
    s += SL(Z_SRED, _polenica(120, 1040, 400, 220, 179, 27))
    s += SL(Z_SRED, _rogozha(110, 854, 420, t, 130, 181))
    s += SL(Z_SRED, _dvorovaya_utvar(760, 1046, 280, t, 183, ["vedro", "kadka"])
            + _sledy(1700, 1070, 1320, gor + 110, 7, 185, "#1f231c", 1.0)
            + _kucha_listev(1060, 1050, 280, 187, 72))
    s += SL(Z_SRED, dym(300, gor - 240, t, 4, .26, 260, .3, "#8e9ab0", 1.4))
    s += SL(Z_SRED, luchina(1240, py - 86, t, 1.0, .4)
            + teplo(1240, py - 120, 240, 200, .34))
    s += SL(Z_LETIT, tuman(t, 900, .34, "#9fb0bc"))
    s += SL(Z_PERED, _stolb_pered(1892, 118, "#10141a", 0, H))
    s += vinetka(.48)
    return s


def listki_chislennika_pod_zontom(t):
    """Стена сеней: отрывной численник крупно, на гвозде рядом мокрый зонт и
    плащ, под ними калоши в лужице. Дед в мокрой кепке правой рукой отгибает
    листки один за другим — на каждом тучка с каплями, — левой выжимает
    кепку над калошами."""
    rnd = random.Random(787)
    pol = 1012
    s = f'<rect width="{W}" height="{H}" fill="#282018"/>'
    s += SL(Z_DAL, doski(0, 0, 1920, pol, 72, True, "dosk"))
    for i in range(13):
        s += SL(Z_DAL, f'<line x1="{30+i*150:.0f}" y1="0" x2="{30+i*150:.0f}"'
                       f' y2="{pol:.0f}" stroke="#5b4428" stroke-width="7"'
                       f' opacity=".7"/>')
    s += SL(Z_DAL, _polka_s_utvaryu(1520, 170, 380, t, 189, 4)
            + _polka_s_utvaryu(60, 150, 420, t, 199, 4))
    # стенное хозяйство и лавка сеней: без них левый простенок стоит голым
    s += SL(Z_SRED, f'<rect x="120" y="226" width="1080" height="40" rx="12"'
                    f' fill="#6b5340" {o(7)}/>'
            + "".join(f'<path d="M{200+i*150:.0f},266 q{10:.0f},{26:.0f}'
                      f' {-14:.0f},{38:.0f}" fill="none" stroke="{ZHELEZ}"'
                      f' stroke-width="9"/>' for i in range(7)))
    s += SL(Z_SRED, _stennoe_hozyaystvo(300, 420, t, 201))
    s += SL(Z_SRED, _lavka_krupno(260, 1012, 420, t, 170, False))
    s += SL(Z_SRED, _venik(170, 1008, 330, t, "#b8a86a", "#5a4a2e", True,
                           .12, .2, .92, 203))
    s += SL(Z_DAL, tusklaya_lampochka(300, 30, t, .95, False))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="{H-pol+18:.0f}"'
                   f' fill="#5a4a3a"/>' + polovicy(pol + 14)
            + _pol_shvy(pol + 16, 1074, 191, 6, "#463828"))
    # ГЛАВНЫЙ ПРЕДМЕТ: отрывной численник, листки отгибаются с тучками
    otgib = A.ease(A.seg(t, .4, 2.4))
    s += SL(Z_SRED, _chislennik(520, 250, 360, 480, t, .0))
    s += SL(Z_SRED, _listki_tuchki(700, 330, 300, t, otgib, 6, 193))
    # зонт, плащ, калоши в лужице
    s += SL(Z_SRED, _plasch_na_gvozde(1240, 230, 480, t, .3, "#4e5a46"))
    s += SL(Z_SRED, _zont_mokryy(1530, 240, t, 1.0, .2))
    s += SL(Z_SRED, _kaloshi(1380, pol + 10, 1.1, t, True))
    # ОДНА ФИГУРА: дед в мокрой кепке
    dx_, dy_, dh = 1080, pol, 740
    _figury_kadra((dx_, dy_, dh))
    vyzh = A.w(t, 1.6, .2)
    ded = figura(dx_, dy_, dh, t, col="#4e4a44", kant="#cfe4f5", ph=.3,
                 boroda=True, naklon=4.0)
    r1, (e1x, e1y), _ = _ruka_mimo(dx_, dy_, dh, -1, dh * .44,
                                   -26 + 28 * otgib, t, "#4e4a44",
                                   "#cfe4f5", .2, 5.0)
    r2, (e2x, e2y), _ = _ruka_so_sgibom(dx_, dy_, dh, 1, dh * .22, 24,
                                        dh * .24, 56, t, "#4e4a44",
                                        "#cfe4f5", .7, 4.0)
    ded += r1 + r2
    s += SL(Z_SRED, ded)
    # МОКРАЯ КЕПКА, которую он выжимает: лежит в кисти, из неё текут капли
    gy_ = dy_ - dh * .845
    s += SL(Z_SRED, f'<path d="M{dx_-dh*.10:.0f},{gy_-dh*.09:.0f}'
                    f' q{dh*.10:.0f},{-dh*.07:.0f} {dh*.20:.0f},{-dh*.01:.0f}'
                    f' q{-dh*.02:.0f},{dh*.035:.0f} {-dh*.20:.0f},{dh*.008:.0f} Z"'
                    f' fill="#5e5a52" {o(5)}/>')
    s += SL(Z_SRED, f'<g transform="rotate({16 + 10 * vyzh:.1f} {e2x:.0f} {e2y:.0f})">'
                    f'<path d="M{e2x-50:.0f},{e2y+6:.0f} q{50:.0f},{-56:.0f}'
                    f' {100:.0f},{-6:.0f} q{-16:.0f},{30:.0f} {-100:.0f},{6:.0f} Z"'
                    f' fill="#5e5a52" {o(5)}/>'
                    f'<path d="M{e2x+38:.0f},{e2y:.0f} q{34:.0f},{4:.0f}'
                    f' {40:.0f},{18:.0f} q{-22:.0f},{10:.0f} {-46:.0f},{2:.0f} Z"'
                    f' fill="#4e4a44" {o(4)}/></g>')
    s += SL(Z_SRED, _varezhka(e2x, e2y + 4, dh, t, .7))
    for i in range(5):
        kap = ((t * 1.1 + i / 5.0) % 1.0)
        s += SL(Z_LETIT, f'<ellipse cx="{e2x-20+i*20:.0f}"'
                         f' cy="{e2y+40+kap*(pol-e2y-30):.0f}" rx="6"'
                         f' ry="{10+5*kap:.0f}" fill="#9fc4d8"'
                         f' opacity="{(1-kap)*.9:.2f}"/>')
    # варежки на отгибающей кисти НЕТ: листок тонкий, перекрытия не даёт
    s += SL(Z_SRED, f'<path d="M{e1x-20:.0f},{e1y-14:.0f} q{24:.0f},{-12:.0f}'
                    f' {44:.0f},{6:.0f}" fill="none" stroke="#cfe4f5"'
                    f' stroke-width="7" opacity=".3"/>')
    # нижняя треть
    s += SL(Z_SRED, _polovik(700, pol + 42, 500, 110, "#cdbf9c", "#b8352c")
            + _valenki_u_dveri(240, pol + 38, 1.1, t)
            + _dvorovaya_utvar(1700, pol + 50, 210, t, 195, ["vedro"])
            + _yaschiki(160, pol + 14, t, 197, 2, .9)
            + _kot_zhivoy(900, pol + 52, t, 1.05, "#3b3430", .4))
    s += SL(Z_SRED, _luzha(1380, pol + 60, 200, t, .3))
    s += SL(Z_SRED, teplo(300, 140, 320, 240, .28))
    s += SL(Z_PERED, _stolb_pered(-8, 116, "#171107", 0, H))
    s += vinetka(.44)
    return s


def mokryy_palec_na_vetru(t):
    """Балкон городской квартиры: перила, ящик с засохшими бархатцами,
    табурет, прищепки на верёвке. Мужчина в домашней куртке держит
    послюнявленный палец вверх над головой, левой держится за перила. С
    одной стороны палец холодеет — на ней синяя стрелка ветра, шарф
    отлетает в ту же сторону."""
    rnd = random.Random(809)
    plita = 1010
    s = f'<rect width="{W}" height="{H}" fill="#39424a"/>'
    s += nebo("sumer", t, False, 205)
    s += oblaka(t, 170, 6, 207, .42, "#c4cdd8", 11.0)
    # двор за перилами: панельные дома и дальние балконы
    s += SL(Z_DAL, panelka(60, 760, 620, t, 5, True, 209)
            + panelka(1320, 740, 580, t, 5, True, 211))
    s += SL(Z_DAL, _balkon_plita(180, 560, 300, t, 36, 2)
            + _balkon_plita(1480, 530, 290, t, 36, 2))
    s += SL(Z_DAL, _bele_na_verevke(200, 430, 260, t, 1.0, 2, 213, .0)
            + _bele_na_verevke(1500, 400, 250, t, 1.0, 2, 215, .0))
    # стена квартиры и балконная плита
    s += SL(Z_SRED, f'<rect x="0" y="0" width="420" height="{H}"'
                    f' fill="{BETON2}" {o(6)}/>'
            + _kafel(0, 120, 400, 560, t, 217, "#b0bcc0", "#8a9298"))
    s += SL(Z_SRED, dver(60, 230, 300, 740, .18, "#cfd8dc", True, False))
    s += SL(Z_SRED, tusklaya_lampochka(220, 60, t, .9, False))
    s += SL(Z_SRED, f'<rect x="0" y="{plita:.0f}" width="{W}" height="{H-plita:.0f}"'
                    f' fill="#8a9298"/>' + _asfalt(plita - 6, 1076, 219, 10))
    # ПЕРИЛА БАЛКОНА — главная конструкция плана
    s += SL(Z_SRED, _perila_balkona(420, plita, 1500, t, 210, True))
    s += SL(Z_SRED, _yaschik_barhatcev(470, plita - 6, 340, t, 221))
    s += SL(Z_SRED, _tabyret(980, plita - 4, t, 160, 180))
    s += SL(Z_SRED, _prischepki(620, 300, 900, t, 7, 223))
    s += SL(Z_SRED, _gorodskoy_hlam(1700, plita - 6, 200, t, 225,
                                    ["yaschik", "korobka"]))
    # ОДНА ФИГУРА: правая рука с поднятым пальцем, левая на перилах
    mx, my, mh = 1240, plita - 6, 780
    _figury_kadra((mx, my, mh))
    pod = A.ease(A.seg(t, .25, .9))
    muzh = figura(mx, my, mh, t, col="#3f5c7a", kant="#cfe4f5", ph=.3,
                  naklon=3.0)
    r1, (f1x, f1y), _ = _ruka_so_sgibom(mx, my, mh, 1, mh * .22,
                                        -30 - 24 * pod, mh * .22, -56, t,
                                        "#3f5c7a", "#cfe4f5", .2, 3.0)
    r2, (f2x, f2y), _ = _ruka_mimo(mx, my, mh, -1, mh * .38, 46, t,
                                   "#3f5c7a", "#cfe4f5", .7, 4.0)
    muzh += r1 + r2
    s += SL(Z_SRED, muzh)
    # ПАЛЕЦ ВВЕРХ: кисть рукавом, на конце узкий овал — пальцев не рисуем,
    # жест читается вертикалью и стрелкой ветра рядом
    s += SL(Z_SRED, f'<ellipse cx="{f1x:.0f}" cy="{f1y-30:.0f}" rx="14"'
                    f' ry="{34+10*pod:.0f}" fill="#e8d8c0" {o(4)}/>'
            + f'<ellipse cx="{f1x-5:.0f}" cy="{f1y-54-8*pod:.0f}" rx="7"'
              f' ry="12" fill="#cfe4f5" opacity=".55"/>')
    # СИНЯЯ СТРЕЛКА ветра ложится на холодеющую сторону пальца
    s += SL(Z_SRED, _strelka_vetra(f1x + 36, f1y - 36, 210, 8, t, "#4e8ad0", 3))
    s += SL(Z_SRED, f'<path d="M{f1x+8:.0f},{f1y-62:.0f} q{10:.0f},{30:.0f}'
                    f' {2:.0f},{58:.0f}" fill="none" stroke="#4e8ad0"'
                    f' stroke-width="9" opacity=".7"/>')
    # ШАРФ отлетает в ту же сторону
    s += SL(Z_SRED, _sharf_otletaet(mx + 26, my - mh * .66, 330, t, 0.0, TKAN))
    s += SL(Z_SRED, _varezhka(f2x, f2y + 2, mh, t, .7))
    s += SL(Z_SRED, para_izo_rta(mx + 40, my - mh * .80, t, .4, 1.1, .55))
    # нижняя треть
    s += SL(Z_SRED, _kucha_listev(760, plita + 46, 300, 227, 66)
            + _luzha(1460, plita + 52, 190, t, .3)
            + _dvorovaya_utvar(560, plita + 48, 200, t, 229, ["vedro"])
            + _kot_zhivoy(1060, plita + 46, t, 1.05, "#4a4440", .4))
    s += SL(Z_LETIT, mokryy_sneg(t, 26, 231, .5, 1.6))
    s += SL(Z_PERED, _stolb_pered(1894, 104, "#20262a", 0, H))
    s += vinetka(.42)
    return s


def dym_nad_pechnoy_truboy(t):
    """Двор частного дома: крыша с кирпичной трубой, чердачное окно-проём
    крупно показывает настоящий дым из трубы на ветру. Хозяйка в пуховом
    платке приложила правую ладонь козырьком ко лбу, в левой держит миску с
    зерном, смотрит на дым и кивает. Куры клюют у её ног, пёс лежит у
    будки."""
    rnd = random.Random(821)
    gor = 880
    s = f'<rect width="{W}" height="{H}" fill="url(#nden)"/>'
    s += nebo("den", t, False, 233)
    s += oblaka(t, 150, 6, 235, .46, "#c4cdd8", 12.0)
    s += SL(Z_DAL, _derevnya_ryad(gor - 140, t, 237, ((130, 280), (1800, 250))))
    s += SL(Z_DAL, _zabor_dosok(-30, gor - 180, 480, 170, 239, 54))
    # ДОМ: сруб, крыша, кирпичная труба с дымом
    s += SL(Z_SRED, brevna(360, 520, 1200, gor - 480, 92)
            + f'<rect x="340" y="506" width="1240" height="28" rx="9"'
              f' fill="#5a4530" {o(5)}/>')
    s += SL(Z_SRED, f'<path d="M300,520 L960,250 L1620,520 Z" fill="#6b5340"'
                    f' {o(8)}/>'
            + f'<path d="M300,520 L960,250 L960,286 L360,524 Z" fill="{SNEG}"'
              f' opacity=".88"/>')
    for i in range(12):
        s += SL(Z_SRED, f'<line x1="{320+i*110:.0f}" y1="518" x2="960"'
                        f' y2="254" stroke="#4e3c2c" stroke-width="6"'
                        f' opacity=".6"/>')
    s += SL(Z_SRED, f'<rect x="1230" y="150" width="130" height="200" rx="8"'
                    f' fill="{KAMEN}" {o(6)}/>' + kladka(1230, 150, 130, 200, 40, KAMEN)
            + f'<rect x="1206" y="128" width="178" height="32" rx="9"'
              f' fill="{KAMEN2}" {o(5)}/>')
    s += SL(Z_SRED, f'<g transform="rotate(54 1295 120)">'
                    + dym(1295, 120, t, 6, .34, 420, .42, "#cfd6de", 2.0)
                    + "</g>")
    # НАСТОЯЩИЙ КАДР в чердачном окне: вид, метка, наличник и переплёт поверх
    px, py, pw, ph_ = 580, 330, 780, 320
    put = kontur_proema(px, py, pw, ph_, "pryam")
    vid = (f'<path d="{put}" fill="#4a5a68"/>'
           + _vid_za_proemom(put, t, "nebo", 241, px + pw * .5))
    for i in range(4):
        vid += (f'<path d="M{px+90+i*60:.0f},{py+ph_*.80:.0f}'
                f' q{90:.0f},{-80 - 20 * A.w(t, 1.6, i * .3):.0f}'
                f' {220:.0f},{-120:.0f}" fill="none" stroke="#cfd6de"'
                f' stroke-width="{22-i*4:.0f}" opacity=".5"/>')
    s += SL(Z_SRED, vid + mesto_stoka(px, py, pw, ph_, "pryam"))
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#5f4a34"'
                    f' stroke-width="32"/>'
            + f'<line x1="{px+pw*.5:.0f}" y1="{py:.0f}" x2="{px+pw*.5:.0f}"'
              f' y2="{py+ph_:.0f}" stroke="#5f4a34" stroke-width="22"/>'
            + f'<rect x="{px-46:.0f}" y="{py-48:.0f}" width="{pw+92:.0f}"'
              f' height="42" rx="12" fill="#7d5a3c" {o(5)}/>'
            + f'<rect x="{px-34:.0f}" y="{py+ph_-10:.0f}" width="{pw+68:.0f}"'
              f' height="40" rx="12" fill="url(#dosk)" {o(6)}/>'
            + f'<path d="M{px-46:.0f},{py-48:.0f} l{-28:.0f},{-30:.0f}'
              f' l{pw+148:.0f},0 l{-28:.0f},{30:.0f} Z" fill="#6b5340" {o(5)}/>')
    # ДВОР: земля, будка с псом, куры
    s += SL(Z_SRED, f'<rect x="0" y="{gor:.0f}" width="{W}" height="{H-gor:.0f}"'
                    f' fill="#55564e"/>' + sneg_lezhit(gor + 30, 24)
            + _zemlya_faktura(gor + 70, 1072, 243, 16, "#43443c"))
    s += SL(Z_SRED, _buda_s_psom(1560, 1040, .92, t, .3))
    for i, (kx, ks, kp) in enumerate(((760, 1.45, .0), (900, .74, .3),
                                      (1030, 1.25, .6), (1150, .66, .85))):
        s += SL(Z_SRED, kura(kx, 1040 - i * 6, t, ks, kp, "#e2d6c2", True))
    # ОДНА ФИГУРА: хозяйка в пуховом платке
    hx, hy, hh = 420, 1018, 760
    _figury_kadra((hx, hy, hh))
    kiv = A.w(t, 1.3, .2)
    hoz = figura(hx, hy, hh, t, col="#8a4a5c", kant="#cfe4f5", platok=True,
                 ph=.3, naklon=3.0 + 2.0 * kiv)
    r1, (g1x, g1y), _ = _ruka_so_sgibom(hx, hy, hh, 1, hh * .22, -34,
                                        hh * .18, -56, t, "#8a4a5c",
                                        "#cfe4f5", .2, 3.0)
    r2, (g2x, g2y), _ = _ruka_mimo(hx, hy, hh, -1, hh * .34, 50, t,
                                   "#8a4a5c", "#cfe4f5", .7, 4.0)
    hoz += r1 + r2
    s += SL(Z_SRED, hoz)
    # ЛАДОНЬ КОЗЫРЬКОМ у лба: горизонтальная накладка от кисти, лицо открыто
    s += SL(Z_SRED, f'<path d="M{g1x-14:.0f},{g1y:.0f} q{40:.0f},{-20:.0f}'
                    f' {76:.0f},{-4:.0f} q{-6:.0f},{20:.0f} {-76:.0f},{16:.0f} Z"'
                    f' fill="#e8d8c0" {o(4)}/>')
    # ПУХОВЫЙ ПЛАТОК: пушистая кромка поверх убора
    gy_ = hy - hh * .845
    s += SL(Z_SRED, "".join(
        f'<circle cx="{hx+math.cos(math.radians(a)) * hh * .165:.0f}"'
        f' cy="{gy_+math.sin(math.radians(a)) * hh * .165:.0f}"'
        f' r="{hh*.022:.0f}" fill="#e8e2d6" opacity=".9"/>'
        for a in range(150, 391, 24)))
    # МИСКА С ЗЕРНОМ в левой кисти, варежка перекрывает борт
    s += SL(Z_SRED, _miska_zerna(g2x - 36, g2y + 64, .92, t, .3))
    s += SL(Z_SRED, _varezhka(g2x, g2y + 4, hh, t, .7))
    s += SL(Z_SRED, para_izo_rta(hx + 38, gy_ + 14, t, .5, 1.0, .5))
    # нижняя треть
    s += SL(Z_SRED, _polenica(80, 1046, 300, 200, 245, 26)
            + _dvorovaya_utvar(620, 1046, 240, t, 247, ["kadka", "vedro"])
            + _sani(1300, 1042, .74, t, True)
            + _sledy(240, 1070, 760, gor + 90, 7, 249, "#3a3b33", 1.0))
    s += SL(Z_SRED, teplo(1295, 200, 360, 300, .26))
    s += SL(Z_PERED, _vetka_pered(-40, 150, 540, 24, t, 251, "#2a2318", 6))
    s += vinetka(.42)
    return s


def bele_na_balkonnoy_verevke(t):
    """Двор-колодец из панельных стен: балкон крупно, верёвки. В проёме
    балконной двери — настоящий кадр, где бельё полощется на ветру. Женщина
    в халате левой рукой держит таз у бедра, правой прищепляет наволочку.
    Наволочку и халат относит в одну сторону, на соседних балконах бельё
    летит туда же."""
    rnd = random.Random(853)
    plita = 1004
    s = f'<rect width="{W}" height="{H}" fill="#4a535a"/>'
    s += nebo("den", t, False, 253)
    # ДВОР-КОЛОДЕЦ: панельные стены по трём сторонам
    s += SL(Z_DAL, panelka(-40, 820, 560, t, 6, True, 255)
            + panelka(1420, 800, 560, t, 6, True, 257))
    s += SL(Z_DAL, panelka(500, 560, 420, t, 4, True, 259)
            + panelka(940, 560, 420, t, 4, True, 261))
    # соседние балконы: бельё летит в ту же сторону
    for i, (bx, by_, bw) in enumerate(((120, 520, 320), (1500, 490, 300),
                                       (640, 330, 280), (1060, 300, 280))):
        s += SL(Z_DAL, _balkon_plita(bx, by_, bw, t, 34, 2))
        s += SL(Z_DAL, _bele_na_verevke(bx + 20, by_ - 130, bw - 40, t, 1.0,
                                        2, 263 + i * 2, .0))
    # СТЕНА КВАРТИРЫ и проём балконной двери с настоящим кадром
    s += SL(Z_SRED, f'<rect x="0" y="0" width="520" height="{H}"'
                    f' fill="{BETON2}" {o(6)}/>'
            + _kafel(0, 100, 500, 620, t, 271, "#b0bcc0", "#8a9298"))
    px, py, pw, ph_ = 60, 190, 780, 700
    put = kontur_proema(px, py, pw, ph_, "pryam")
    vid = (f'<path d="{put}" fill="#5e6a72"/>'
           + _vid_za_proemom(put, t, "dvor", 273, px + pw * .5))
    for i in range(3):
        sn = 30 * A.w(t, 1.5, i * .3)
        vid += (f'<path d="M{px+90+i*220:.0f},{py+120:.0f}'
                f' q{40+sn:.0f},{ph_*.3:.0f} {18+sn:.0f},{ph_*.56:.0f}'
                f' q{-40:.0f},{30:.0f} {-110:.0f},{10:.0f}'
                f' q{-10:.0f},{-ph_*.3:.0f} {18:.0f},{-ph_*.56:.0f} Z"'
                f' fill="#f4eedc" opacity=".92" stroke="{K}" stroke-width="5"/>')
    s += SL(Z_SRED, vid + mesto_stoka(px, py, pw, ph_, "pryam"))
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#cfd8dc"'
                    f' stroke-width="34"/>'
            + f'<line x1="{px+pw*.52:.0f}" y1="{py:.0f}" x2="{px+pw*.52:.0f}"'
              f' y2="{py+ph_:.0f}" stroke="#cfd8dc" stroke-width="26"/>'
            + f'<line x1="{px:.0f}" y1="{py+ph_*.30:.0f}" x2="{px+pw:.0f}"'
              f' y2="{py+ph_*.30:.0f}" stroke="#cfd8dc" stroke-width="20"/>'
            + f'<circle cx="{px+pw*.52+40:.0f}" cy="{py+ph_*.56:.0f}" r="16"'
              f' fill="#9aa3aa" {o(4)}/>'
            + f'<path d="M{px+120:.0f},{py+ph_*.18:.0f} L{px+pw*.42:.0f},'
              f'{py+70:.0f}" fill="none" stroke="#ffffff" stroke-width="14"'
              f' opacity="{.14+.10*abs(A.w(t,3.0,.2)):.2f}"/>')
    # БАЛКОН: плита, перила, верёвки
    s += SL(Z_SRED, f'<rect x="0" y="{plita:.0f}" width="{W}" height="{H-plita:.0f}"'
                    f' fill="{BETON}"/>' + _asfalt(plita - 4, 1076, 275, 8))
    s += SL(Z_SRED, _perila_balkona(560, plita, 1340, t, 220, True))
    s += SL(Z_SRED, _prischepki(620, 300, 1200, t, 8, 277))
    s += SL(Z_SRED, _bele_na_verevke(640, 316, 560, t, 1.0, 3, 279, .0))
    s += SL(Z_SRED, _yaschik_barhatcev(1640, plita - 6, 250, t, 281))
    # ОДНА ФИГУРА: левая держит таз у бедра, правая прищепляет наволочку
    zx, zy, zh = 1180, plita - 6, 780
    _figury_kadra((zx, zy, zh))
    prisch = A.ease(A.seg(t, .5, 1.3))
    zhen = figura(zx, zy, zh, t, col="#b8323a", kant="#cfe4f5", ph=.3,
                  naklon=4.0)
    r1, (h1x, h1y), _ = _ruka_so_sgibom(zx, zy, zh, 1, zh * .22,
                                        -34 - 16 * prisch, zh * .20, -58, t,
                                        "#b8323a", "#cfe4f5", .2, 4.0)
    r2, (h2x, h2y), _ = _ruka_mimo(zx, zy, zh, -1, zh * .30, 44, t,
                                   "#b8323a", "#cfe4f5", .7, 4.0)
    zhen += r1 + r2
    s += SL(Z_SRED, zhen)
    # ХАЛАТ относит в ту же сторону, что и бельё
    sn = 26 + 18 * A.w(t, 1.5, .2)
    s += SL(Z_SRED, f'<path d="M{zx-zh*.14:.0f},{zy-zh*.60:.0f}'
                    f' q{zh*.14:.0f},{-zh*.04:.0f} {zh*.28:.0f},0'
                    f' L{zx+zh*.20+sn:.0f},{zy-zh*.10:.0f}'
                    f' L{zx-zh*.14+sn*.4:.0f},{zy-zh*.10:.0f} Z"'
                    f' fill="#d9444c" {o(5)}/>'
            + f'<path d="M{zx-zh*.15:.0f},{zy-zh*.38:.0f} q{zh*.15:.0f},'
              f'{zh*.03:.0f} {zh*.30:.0f},0" fill="none" stroke="{TKAN2}"'
              f' stroke-width="{zh*.018:.0f}"/>')
    # НАВОЛОЧКА парусом — ровно в кисти, прищепка поверх
    s += SL(Z_SRED, _navolochka_parus(h1x - 20, h1y + 10, 230, t,
                                      .5 + .5 * prisch, "#f4eedc"))
    s += SL(Z_SRED, f'<rect x="{h1x-30:.0f}" y="{h1y-10:.0f}" width="22"'
                    f' height="56" rx="7" fill="#c9a47a" {o(4)}/>')
    s += SL(Z_SRED, _varezhka(h1x, h1y + 4, zh, t, .2))
    # ТАЗ У БЕДРА в левой кисти
    s += SL(Z_SRED, _taz_i_svertok(h2x - 40, h2y + 70, .72, t, -14))
    s += SL(Z_SRED, _varezhka(h2x, h2y + 6, zh, t, .7))
    # нижняя треть
    s += SL(Z_SRED, _gorodskoy_hlam(620, plita + 46, 280, t, 283,
                                    ["yaschik", "paket"])
            + _kucha_listev(980, plita + 50, 280, 285, 64)
            + _luzha(1500, plita + 54, 200, t, .3)
            + _kot_zhivoy(1300, plita + 46, t, 1.05, "#4a4440", .4))
    s += SL(Z_SRED, tusklaya_lampochka(300, 70, t, .9, False))
    s += SL(Z_LETIT, mokryy_sneg(t, 24, 287, .44, 1.8))
    s += SL(Z_PERED, _stolb_pered(1896, 108, "#20262a", 0, H))
    s += vinetka(.42)
    return s


def kinozal_i_dva_kresla(t):
    """Старый кинозал: ряды бархатных кресел, белый экран, из окошка будки
    бьёт тёплый луч. В первом ряду два кресла крупно — на левом режиссёрская
    кепка на рупоре, на правом жестяная коробка с катушкой и пара белых
    перчаток. Людей нет, луч скользит с одного кресла на другое, в нём
    пляшут пылинки."""
    rnd = random.Random(877)
    pol = 1010
    sk = A.ease(A.seg(t, .6, 2.0))
    s = f'<rect width="{W}" height="{H}" fill="#170f12"/>'
    s += SL(Z_DAL, f'<rect x="0" y="0" width="{W}" height="{pol:.0f}"'
                   f' fill="#2a1820"/>'
            + kladka(0, 40, 520, 620, 76, "#4a2a34")
            + kladka(1400, 40, 520, 620, 76, "#4a2a34"))
    s += SL(Z_DAL, _ekran_kino(560, 110, 800, 430, t, sk))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-16:.0f}" width="{W}"'
                   f' height="{H-pol+16:.0f}" fill="#3a2028"/>'
            + _pol_shvy(pol - 6, 1074, 289, 6, "#2a151c"))
    # БУДКА КИНОМЕХАНИКА с окошком — источник луча
    s += SL(Z_DAL, f'<rect x="1660" y="150" width="260" height="330" rx="10"'
                   f' fill="#3d2a30" {o(6)}/>'
            + f'<rect x="1700" y="210" width="150" height="120" rx="8"'
              f' fill="#1a1012" {o(5)}/>'
            + f'<rect x="1718" y="228" width="114" height="84" rx="6"'
              f' fill="{SVET}" opacity="{.7+.2*abs(A.w(t,2.2,.2)):.2f}"/>'
            + f'<circle cx="1775" cy="400" r="34" fill="none" stroke="#6f767c"'
              f' stroke-width="9"/>'
            + f'<circle cx="1860" cy="400" r="24" fill="none" stroke="#6f767c"'
              f' stroke-width="8"/>')
    # ТЁПЛЫЙ ЛУЧ скользит с кресла на кресло
    lx = 1760 - 760 * sk
    s += SL(Z_SRED, f'<g transform="rotate({10 - 16 * sk:.1f} 1775 270)">'
            + _konus_sveta(1775, 270, 560, 760, 0.0, .34, "#ffd98a") + "</g>")
    s += SL(Z_SRED, luch(900, 240, 820, 720, t, .22))
    rnd2 = random.Random(291)
    for i in range(28):
        p = ((t * .22 + rnd2.random()) % 1.0)
        pxx = 1700 - p * 900 + rnd2.uniform(-60, 60)
        pyy = 300 + p * 420 + rnd2.uniform(-70, 70)
        s += SL(Z_LETIT, f'<circle cx="{pxx:.0f}" cy="{pyy:.0f}"'
                         f' r="{rnd2.uniform(2.5,6):.0f}" fill="#ffeec2"'
                         f' opacity="{.25+.5*abs(A.w(t,1.6,i*.2)):.2f}"/>')
    # РЯДЫ КРЕСЕЛ в глубину
    s += SL(Z_DAL, _kresla_ryad(160, 700, 1600, t, 7, 200, "#6a1c30", False))
    s += SL(Z_SRED, _kresla_ryad(100, 800, 1740, t, 6, 250, "#7a2338", False))
    # ДВА КРЕСЛА ПЕРВОГО РЯДА — главный предмет плана
    s += SL(Z_SRED, _kresla_ryad(360, pol, 1240, t, 2, 420, "#8a2a40", True))
    # на левом кресле кепка на рупоре, на правом коробка с катушкой
    s += SL(Z_SRED, _kepka_i_rupor(640, pol - 300, 1.15, t))
    s += SL(Z_SRED, _korobka_katushki(1320, pol - 268, 1.0, t, True))
    # нижняя треть: проход, ковровая дорожка, урна, оброненный билетик-лоскут
    s += SL(Z_SRED, _polovik(960, pol + 40, 760, 120, "#8a2a40", "#5a1626"))
    s += SL(Z_SRED, _dvorovaya_utvar(140, pol + 48, 220, t, 293, ["vedro"])
            + _yaschiki(1740, pol + 16, t, 295, 2, .82)
            + _kucha_listev(540, pol + 52, 240, 297, 58))
    s += SL(Z_SRED, _kot_zhivoy(1540, pol + 48, t, 1.05, "#2f2a26", .3))
    s += SL(Z_SRED, svecha(120, pol - 150, t, .3, 1.2, 104)
            + teplo(130, pol - 210, 240, 200, .34))
    s += SL(Z_SRED, blik(1775, 270, t, 1.3, "#bcd8ff", "#ffd98a", .5))
    s += SL(Z_PERED, _stolb_pered(-8, 120, "#140a0e", 0, H))
    s += vinetka(.50)
    return s


# ── ПОМОЩНИКИ ЧЕТВЁРТОЙ ПАРТИИ ────────────────────────────────────────────

def _televizor_nozhki(x, y, w_, t, h_=430, ekran=None):
    """ТЕЛЕВИЗОР НА ТОНКИХ НОЖКАХ — главный предмет: деревянный корпус с
    выпуклым экраном в скруглённой рамке, решётка динамика, две круглые
    крутилки, тонкие косые ножки с латунными наконечниками. На корпусе
    салфетка. Середина экрана остаётся ВАМ — туда встаёт настоящий кадр."""
    s = (f'{ten(x + w_ * .5, y + 10, w_ * .48, 18, .5)}'
         f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="22" fill="#7d5636" {o(8)}/>'
         f'<rect x="{x+14:.0f}" y="{y-h_+14:.0f}" width="{w_-28:.0f}"'
         f' height="{h_-28:.0f}" rx="18" fill="#8a6038" opacity=".9"/>')
    # решётка динамика и крутилки справа
    gx = x + w_ - 118
    for i in range(7):
        s += (f'<rect x="{gx:.0f}" y="{y-h_*.86+i*22:.0f}" width="86"'
              f' height="11" rx="5" fill="#5b4428" opacity=".9"/>')
    for i in (0, 1):
        s += (f'<circle cx="{gx+44:.0f}" cy="{y-h_*.34+i*70:.0f}" r="26"'
              f' fill="#c9a47a" {o(5)}/>'
              f'<circle cx="{gx+44:.0f}" cy="{y-h_*.34+i*70:.0f}" r="9"'
              f' fill="#5b4428"/>')
    for i in (0, 1):
        nx = x + 60 + i * (w_ - 150)
        s += (f'<line x1="{nx:.0f}" y1="{y-6:.0f}" x2="{nx+(-34 if i == 0 else 34):.0f}"'
              f' y2="{y+150:.0f}" stroke="#5b4428" stroke-width="18"'
              f' stroke-linecap="round"/>'
              f'<ellipse cx="{nx+(-34 if i == 0 else 34):.0f}" cy="{y+152:.0f}"'
              f' rx="16" ry="8" fill="{ZOL}" {o(3)}/>')
    s += (f'<path d="M{x-10:.0f},{y-h_-6:.0f} q{w_*.5:.0f},{-26:.0f}'
          f' {w_+20:.0f},0 l{-14:.0f},{30:.0f} q{-w_*.5:.0f},{-18:.0f}'
          f' {-(w_-8):.0f},0 Z" fill="{KREM}" {o(5)}/>')
    for i in range(int(w_ / 46)):
        s += (f'<path d="M{x+12+i*46:.0f},{y-h_+8:.0f} q{11:.0f},{14:.0f}'
              f' {22:.0f},0" fill="none" stroke="#d9d0b8" stroke-width="5"/>')
    return s


def _torsher(x, y, t, s_=1.0, h_=620):
    """Торшер: трёхлапая стойка, витая нога, тканевый абажур с бахромой и
    тёплый свет из-под него."""
    s = (f'{ten(x, y + 8 * s_, 72 * s_, 14 * s_, .45)}')
    for i in (-1, 0, 1):
        s += (f'<path d="M{x:.0f},{y-14*s_:.0f} q{i*44*s_:.0f},{10*s_:.0f}'
              f' {i*62*s_:.0f},{16*s_:.0f}" fill="none" stroke="#5b4428"'
              f' stroke-width="{12*s_:.0f}" stroke-linecap="round"/>')
    s += (f'<rect x="{x-9*s_:.0f}" y="{y-h_:.0f}" width="{18*s_:.0f}"'
          f' height="{h_:.0f}" rx="{8*s_:.0f}" fill="#7d5636" {o(5)}/>')
    for i in range(5):
        s += (f'<ellipse cx="{x:.0f}" cy="{y-h_*.22-i*h_*.13:.0f}"'
              f' rx="{16*s_:.0f}" ry="{7*s_:.0f}" fill="#9c7049" {o(3)}/>')
    s += (f'<path d="M{x-96*s_:.0f},{y-h_:.0f} L{x+96*s_:.0f},{y-h_:.0f}'
          f' L{x+66*s_:.0f},{y-h_-120*s_:.0f} L{x-66*s_:.0f},{y-h_-120*s_:.0f} Z"'
          f' fill="{RUSH}" {o(6)}/>'
          f'<path d="M{x-66*s_:.0f},{y-h_-120*s_:.0f} q{66*s_:.0f},{-16*s_:.0f}'
          f' {132*s_:.0f},0" fill="none" stroke="#c9b48a"'
          f' stroke-width="{8*s_:.0f}"/>')
    for i in range(10):
        s += (f'<line x1="{x-92*s_+i*20*s_:.0f}" y1="{y-h_:.0f}"'
              f' x2="{x-94*s_+i*21*s_:.0f}" y2="{y-h_+22*s_:.0f}"'
              f' stroke="#c9b48a" stroke-width="{max(2,4*s_):.0f}"/>')
    s += (f'<ellipse cx="{x:.0f}" cy="{y-h_+14*s_:.0f}" rx="{86*s_:.0f}"'
          f' ry="{18*s_:.0f}" fill="{SVET}"'
          f' opacity="{.6+.2*abs(A.w(t,2.4,.2)):.2f}"/>'
          f'{teplo(x, y - h_ + 40 * s_, 300 * s_, 260 * s_, .36)}')
    return s


def _vyazanie(x, y, s_=1.0, t=0.0, ph=.0):
    """Вязание со спицами: начатое полотно резинкой, две спицы наперекрест
    (мелькают), клубок на нитке рядом."""
    mel = 9.0 * A.w(t, .7, ph)
    s = (f'<path d="M{x-76*s_:.0f},{y:.0f} L{x+76*s_:.0f},{y:.0f}'
         f' L{x+66*s_:.0f},{y+96*s_:.0f} L{x-66*s_:.0f},{y+96*s_:.0f} Z"'
         f' fill="#8a4a5c" {o(5)}/>')
    for i in range(6):
        s += (f'<line x1="{x-62*s_+i*25*s_:.0f}" y1="{y+6*s_:.0f}"'
              f' x2="{x-58*s_+i*23*s_:.0f}" y2="{y+90*s_:.0f}"'
              f' stroke="#6a2c3c" stroke-width="{max(2,5*s_):.0f}"/>')
    for i in (-1, 1):
        s += (f'<g transform="rotate({i*mel:.1f} {x:.0f} {y:.0f})">'
              f'<line x1="{x+i*70*s_:.0f}" y1="{y+10*s_:.0f}"'
              f' x2="{x+i*140*s_:.0f}" y2="{y-54*s_:.0f}" stroke="#cfd8dc"'
              f' stroke-width="{max(3,7*s_):.0f}" stroke-linecap="round"/>'
              f'<circle cx="{x+i*142*s_:.0f}" cy="{y-56*s_:.0f}" r="{7*s_:.0f}"'
              f' fill="#9aa3aa"/></g>')
    s += (f'<circle cx="{x+40*s_:.0f}" cy="{y+150*s_:.0f}" r="{44*s_:.0f}"'
          f' fill="#8a4a5c" {o(5)}/>')
    for i in range(4):
        s += (f'<path d="M{x+4*s_+i*6*s_:.0f},{y+150*s_:.0f}'
              f' q{40*s_:.0f},{-26*s_+i*14*s_:.0f} {76*s_:.0f},{6*s_:.0f}"'
              f' fill="none" stroke="#6a2c3c" stroke-width="{max(2,4*s_):.0f}"/>')
    s += (f'<path d="M{x+40*s_:.0f},{y+106*s_:.0f} q{-16*s_:.0f},{-30*s_:.0f}'
          f' {-50*s_:.0f},{-20*s_:.0f}" fill="none" stroke="#8a4a5c"'
          f' stroke-width="{max(2,4*s_):.0f}"/>')
    return s


def _elovaya_vetka_v_banke(x, y, s_=1.0, t=0.0, ph=.0):
    """Ёлочная ветка в банке: стеклянная банка с водой, лапа с иглами в три
    яруса и одна игрушка-шар на нитке. Ветка покачивается целиком."""
    kach = 2.6 * A.w(t, 2.2, ph)
    s = (f'{ten(x, y + 6 * s_, 44 * s_, 10 * s_, .4)}'
         f'<rect x="{x-40*s_:.0f}" y="{y-120*s_:.0f}" width="{80*s_:.0f}"'
         f' height="{120*s_:.0f}" rx="10" fill="url(#stekl)" opacity=".88" {o(5)}/>'
         f'<rect x="{x-34*s_:.0f}" y="{y-70*s_:.0f}" width="{68*s_:.0f}"'
         f' height="{64*s_:.0f}" rx="7" fill="{VODA}" opacity=".5"/>')
    s += f'<g transform="rotate({kach:.1f} {x:.0f} {y-120*s_:.0f})">'
    s += (f'<line x1="{x:.0f}" y1="{y-110*s_:.0f}" x2="{x+16*s_:.0f}"'
          f' y2="{y-330*s_:.0f}" stroke="#4e3c2c"'
          f' stroke-width="{max(3,9*s_):.0f}"/>')
    for i in range(4):
        yy = y - (150 + i * 56) * s_
        dl = (120 - i * 20) * s_
        for sg in (-1, 1):
            s += (f'<path d="M{x+i*4*s_:.0f},{yy:.0f} q{sg*dl*.5:.0f},'
                  f'{-10*s_:.0f} {sg*dl:.0f},{-26*s_:.0f}" fill="none"'
                  f' stroke="#2f5a34" stroke-width="{max(3,8*s_):.0f}"/>')
            for j in range(5):
                s += (f'<line x1="{x+i*4*s_+sg*dl*(.2+j*.18):.0f}"'
                      f' y1="{yy-6*s_-j*4*s_:.0f}"'
                      f' x2="{x+i*4*s_+sg*dl*(.2+j*.18)+sg*16*s_:.0f}"'
                      f' y2="{yy-24*s_-j*5*s_:.0f}" stroke="#3f7a44"'
                      f' stroke-width="{max(2,4*s_):.0f}"/>')
    s += (f'<line x1="{x+10*s_:.0f}" y1="{y-250*s_:.0f}" x2="{x+32*s_:.0f}"'
          f' y2="{y-212*s_:.0f}" stroke="#c9b48a" stroke-width="{max(2,3*s_):.0f}"/>'
          f'<circle cx="{x+34*s_:.0f}" cy="{y-196*s_:.0f}" r="{22*s_:.0f}"'
          f' fill="{KRAS}" {o(4)}/>'
          f'<ellipse cx="{x+26*s_:.0f}" cy="{y-206*s_:.0f}" rx="{8*s_:.0f}"'
          f' ry="{5*s_:.0f}" fill="#ffd1c0" opacity=".7"/></g>')
    return s


def _afisha(x, y, w_, h_, t, vid="chasy", podsvet=.0, seed=3):
    """РИСОВАННАЯ АФИША: рамка-планка, фон, КРУПНЫЙ ПРЕДМЕТ вместо лиц и
    пустая полоса сверху под название. Букв не рисуем вовсе — вместо текста
    волнистая строка, настоящее название кладёт `kadr.py` поверх."""
    rnd = random.Random(seed)
    fon = {"chasy": "#8a2a40", "mashinka": "#2f5a6a",
           "sakvoyazhi": "#5a4a2e", "venik": "#3f5a3a"}[vid]
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="8" fill="{fon}" {o(7)}/>'
         f'<rect x="{x+12:.0f}" y="{y+12:.0f}" width="{w_-24:.0f}"'
         f' height="{h_-24:.0f}" rx="6" fill="none" stroke="{KREM}"'
         f' stroke-width="7" opacity=".7"/>'
         f'<rect x="{x+24:.0f}" y="{y+26:.0f}" width="{w_-48:.0f}"'
         f' height="{h_*.14:.0f}" rx="6" fill="{KREM}" opacity=".9"/>')
    for i in range(2):
        s += (f'<path d="M{x+44:.0f},{y+40+i*22:.0f} q{(w_-88)*.25:.0f},{-10:.0f}'
              f' {(w_-88)*.5:.0f},0 q{(w_-88)*.25:.0f},{10:.0f}'
              f' {(w_-88)*.5:.0f},0" fill="none" stroke="#8a7a5c"'
              f' stroke-width="6"/>')
    cx, cy = x + w_ * .5, y + h_ * .60
    if vid == "chasy":
        s += (f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="{w_*.30:.0f}"'
              f' fill="{ZOL}" {o(6)}/>'
              f'<circle cx="{cx:.0f}" cy="{cy:.0f}" r="{w_*.24:.0f}"'
              f' fill="{KREM}" {o(4)}/>'
              f'<line x1="{cx:.0f}" y1="{cy:.0f}" x2="{cx+w_*.14:.0f}"'
              f' y2="{cy-w_*.10:.0f}" stroke="{K}" stroke-width="8"/>'
              f'<line x1="{cx:.0f}" y1="{cy:.0f}" x2="{cx-w_*.04:.0f}"'
              f' y2="{cy-w_*.19:.0f}" stroke="{K}" stroke-width="7"/>')
        for i in range(10):
            p = ((t * .5 + i / 10.0) % 1.0)
            s += (f'<path d="M{cx-w_*.34+i*w_*.075:.0f},{cy-w_*.36:.0f}'
                  f' q{10:.0f},{30+14*math.sin(t*3+i):.0f} {-4:.0f},{60:.0f}"'
                  f' fill="none" stroke="{["#e8c64e", "#cfe4f5", "#d6452a"][i % 3]}"'
                  f' stroke-width="7" opacity=".9"/>'
                  f'<circle cx="{cx-w_*.30+i*w_*.07:.0f}"'
                  f' cy="{cy+w_*.30+p*w_*.20:.0f}" r="7"'
                  f' fill="{["#e8c64e", "#cfe4f5", "#d6452a"][i % 3]}"'
                  f' opacity="{1-p:.2f}"/>')
    elif vid == "mashinka":
        s += (f'<path d="M{cx-w_*.32:.0f},{cy+w_*.16:.0f}'
              f' L{cx+w_*.32:.0f},{cy+w_*.16:.0f} L{cx+w_*.26:.0f},{cy-w_*.10:.0f}'
              f' L{cx-w_*.26:.0f},{cy-w_*.10:.0f} Z" fill="#3d3a38" {o(6)}/>'
              f'<rect x="{cx-w_*.22:.0f}" y="{cy-w_*.26:.0f}"'
              f' width="{w_*.44:.0f}" height="{w_*.16:.0f}" rx="6"'
              f' fill="#4e4a47" {o(4)}/>')
        for r in range(3):
            for c in range(8):
                s += (f'<circle cx="{cx-w_*.24+c*w_*.068+r*6:.0f}"'
                      f' cy="{cy+w_*.02+r*w_*.045:.0f}" r="{w_*.020:.0f}"'
                      f' fill="{KREM}" opacity=".9"/>')
        s += (f'<circle cx="{cx-w_*.20:.0f}" cy="{cy-w_*.34:.0f}"'
              f' r="{w_*.085:.0f}" fill="none" stroke="{ZOL}" stroke-width="7"/>'
              f'<circle cx="{cx-w_*.02:.0f}" cy="{cy-w_*.34:.0f}"'
              f' r="{w_*.085:.0f}" fill="none" stroke="{ZOL}" stroke-width="7"/>'
              f'<line x1="{cx-w_*.12:.0f}" y1="{cy-w_*.34:.0f}"'
              f' x2="{cx-w_*.10:.0f}" y2="{cy-w_*.34:.0f}" stroke="{ZOL}"'
              f' stroke-width="7"/>')
    elif vid == "sakvoyazhi":
        s += (f'<rect x="{x+16:.0f}" y="{cy+w_*.16:.0f}" width="{w_-32:.0f}"'
              f' height="{h_*.10:.0f}" fill="#4a4036" {o(4)}/>'
              f'<circle cx="{cx:.0f}" cy="{y+h_*.30:.0f}" r="{w_*.13:.0f}"'
              f' fill="{KREM}" {o(5)}/>'
              f'<line x1="{cx:.0f}" y1="{y+h_*.30:.0f}" x2="{cx+w_*.07:.0f}"'
              f' y2="{y+h_*.24:.0f}" stroke="{K}" stroke-width="6"/>')
        for i, (dx, sc) in enumerate(((-w_ * .18, 1.0), (w_ * .18, .78))):
            s += (f'<path d="M{cx+dx-w_*.15*sc:.0f},{cy+w_*.16:.0f}'
                  f' q{-w_*.02:.0f},{-w_*.20*sc:.0f} {w_*.15*sc:.0f},{-w_*.21*sc:.0f}'
                  f' q{w_*.16*sc:.0f},{w_*.01*sc:.0f} {w_*.15*sc:.0f},{w_*.21*sc:.0f} Z"'
                  f' fill="#7d5636" {o(5)}/>'
                  f'<path d="M{cx+dx-w_*.07*sc:.0f},{cy-w_*.06*sc:.0f}'
                  f' q{w_*.07*sc:.0f},{-w_*.09*sc:.0f} {w_*.14*sc:.0f},0"'
                  f' fill="none" stroke="#4a3522" stroke-width="7"/>')
    else:
        s += _venik(cx - w_ * .12, cy + w_ * .22, w_ * .52, t, "#cdbf9c",
                    "#b8352c", False, .14, .2, w_ * .0016, seed + 1)
        s += (f'<line x1="{cx+w_*.20:.0f}" y1="{y+h_*.26:.0f}"'
              f' x2="{cx+w_*.20:.0f}" y2="{cy-w_*.06:.0f}" stroke="{KREM}"'
              f' stroke-width="5"/>'
              f'<circle cx="{cx+w_*.20:.0f}" cy="{cy+w_*.03:.0f}"'
              f' r="{w_*.10:.0f}" fill="{KRAS}" {o(5)}/>'
              f'<ellipse cx="{cx+w_*.16:.0f}" cy="{cy-w_*.01:.0f}"'
              f' rx="{w_*.035:.0f}" ry="{w_*.022:.0f}" fill="#ffd1c0"'
              f' opacity=".75"/>')
    s += (f'<rect x="{x-10:.0f}" y="{y-16:.0f}" width="{w_+20:.0f}" height="22"'
          f' rx="8" fill="#5a4530" {o(5)}/>'
          f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
          f' rx="8" fill="{SVET}" opacity="{.26*podsvet:.2f}"/>')
    return s


def _stremyanka(x, y, h_, t, stup=4):
    """Стремянка расклейщика: две стойки под углом, ступени, распорка и
    крючок с ведёрком. Чуть переступает под весом."""
    k = .5 * A.w(t, 3.4, .2)
    s = f'<g transform="rotate({k:.1f} {x:.0f} {y:.0f})">'
    for i, sg in ((0, -1), (1, 1)):
        s += (f'<line x1="{x+sg*20:.0f}" y1="{y:.0f}" x2="{x+sg*90:.0f}"'
              f' y2="{y+h_:.0f}" stroke="#8a6038" stroke-width="22"'
              f' stroke-linecap="round"/>')
    for i in range(stup):
        p = (i + 1) / float(stup + 1)
        yy = y + h_ * p
        ww = 40 + 150 * p
        s += (f'<rect x="{x-ww*.5:.0f}" y="{yy:.0f}" width="{ww:.0f}"'
              f' height="18" rx="7" fill="url(#dosk)" {o(4)}/>')
    s += (f'<line x1="{x-70:.0f}" y1="{y+h_*.62:.0f}" x2="{x+70:.0f}"'
          f' y2="{y+h_*.62:.0f}" stroke="#5b4428" stroke-width="12"/>'
          f'<path d="M{x+24:.0f},{y+20:.0f} q{26:.0f},{-14:.0f} {30:.0f},{14:.0f}"'
          f' fill="none" stroke="{ZHELEZ}" stroke-width="8"/></g>')
    return s


def _vederko_kleya(x, y, s_=1.0, t=0.0, kist=True):
    """Ведёрко с клеем и кисть: жестяное ведро с дугой-ручкой, мутный клей,
    на борту лежит широкая кисть с деревянной ручкой."""
    s = (f'{ten(x, y + 8 * s_, 60 * s_, 12 * s_, .45)}'
         f'<path d="M{x-56*s_:.0f},{y-110*s_:.0f} q{6*s_:.0f},{110*s_:.0f}'
         f' {56*s_:.0f},{110*s_:.0f} q{50*s_:.0f},0 {56*s_:.0f},{-110*s_:.0f} Z"'
         f' fill="#9aa3aa" {o(6)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-110*s_:.0f}" rx="{56*s_:.0f}"'
         f' ry="{16*s_:.0f}" fill="#b9c6cc" {o(4)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-104*s_:.0f}" rx="{44*s_:.0f}"'
         f' ry="{11*s_:.0f}" fill="#d9d0b8" opacity=".9"/>'
         f'<path d="M{x-56*s_:.0f},{y-104*s_:.0f} q{56*s_:.0f},{-54*s_:.0f}'
         f' {112*s_:.0f},0" fill="none" stroke="{ZHELEZ}"'
         f' stroke-width="{8*s_:.0f}"/>')
    if kist:
        s += (f'<g transform="rotate(-24 {x+40*s_:.0f} {y-110*s_:.0f})">'
              f'<rect x="{x+30*s_:.0f}" y="{y-200*s_:.0f}" width="{22*s_:.0f}"'
              f' height="{90*s_:.0f}" rx="8" fill="#8a6038" {o(4)}/>'
              f'<rect x="{x+22*s_:.0f}" y="{y-116*s_:.0f}" width="{38*s_:.0f}"'
              f' height="{36*s_:.0f}" rx="6" fill="#c9b48a" {o(4)}/></g>')
    return s


def _schetka_oboynaya(x, y, s_=1.0, ug=0.0, t=0.0):
    """Щётка для афиш: деревянная колодка с ворсом и скобой-ручкой; ворс
    приминается по ходу разглаживания."""
    pr = 4 * s_ * A.w(t, 1.3, .2)
    return (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
            f'<rect x="{x-62*s_:.0f}" y="{y-26*s_:.0f}" width="{124*s_:.0f}"'
            f' height="{26*s_:.0f}" rx="{9*s_:.0f}" fill="#8a6038" {o(5)}/>'
            f'<path d="M{x-40*s_:.0f},{y-26*s_:.0f} q{40*s_:.0f},{-30*s_:.0f}'
            f' {80*s_:.0f},0" fill="none" stroke="{ZHELEZ}"'
            f' stroke-width="{11*s_:.0f}"/>'
            + "".join(f'<line x1="{x-56*s_+i*14*s_:.0f}" y1="{y:.0f}"'
                      f' x2="{x-56*s_+i*14*s_+pr:.0f}" y2="{y+30*s_:.0f}"'
                      f' stroke="#c9b48a" stroke-width="{max(2,5*s_):.0f}"/>'
                      for i in range(9))
            + "</g>")


def _setka_mandarinov(x, y, s_=1.0, t=0.0, ph=.0, n=7):
    """Сетка с мандаринами: ячейки сетки, оранжевые плоды с пупком и
    листиком, сетка оттягивается вниз и качается в руке."""
    rnd = random.Random(int(x) + 23)
    kol = 5.0 * A.w(t, 1.6, ph)
    s = f'<g transform="rotate({kol:.1f} {x:.0f} {y:.0f})">'
    s += (f'<path d="M{x-8*s_:.0f},{y:.0f} q{-54*s_:.0f},{44*s_:.0f}'
          f' {-40*s_:.0f},{110*s_:.0f} q{48*s_:.0f},{44*s_:.0f}'
          f' {100*s_:.0f},0 q{14*s_:.0f},{-66*s_:.0f} {-40*s_:.0f},{-110*s_:.0f} Z"'
          f' fill="#c24a2a" opacity=".32" {o(4)}/>')
    for i in range(n):
        a = rnd.uniform(0, 6.28)
        rr = rnd.uniform(.25, .9)
        mx = x + 8 * s_ + math.cos(a) * 42 * s_ * rr
        my = y + 60 * s_ + abs(math.sin(a)) * 54 * s_ * rr
        r = rnd.uniform(22, 30) * s_
        s += (f'<circle cx="{mx:.0f}" cy="{my:.0f}" r="{r:.0f}" fill="{ORA}"'
              f' {o(4)}/>'
              f'<circle cx="{mx:.0f}" cy="{my-r*.78:.0f}" r="{r*.17:.0f}"'
              f' fill="#8a4a1c"/>'
              f'<ellipse cx="{mx-r*.34:.0f}" cy="{my-r*.34:.0f}"'
              f' rx="{r*.22:.0f}" ry="{r*.13:.0f}" fill="#f8c27a" opacity=".6"/>')
    for i in range(6):
        s += (f'<path d="M{x-42*s_+i*18*s_:.0f},{y+10*s_:.0f}'
              f' q{8*s_:.0f},{60*s_:.0f} {2*s_:.0f},{112*s_:.0f}" fill="none"'
              f' stroke="#8a2a18" stroke-width="{max(2,3*s_):.0f}" opacity=".85"/>')
    for i in range(4):
        s += (f'<path d="M{x-44*s_:.0f},{y+30*s_+i*28*s_:.0f}'
              f' q{50*s_:.0f},{14*s_:.0f} {100*s_:.0f},{-4*s_:.0f}" fill="none"'
              f' stroke="#8a2a18" stroke-width="{max(2,3*s_):.0f}" opacity=".85"/>')
    s += (f'<ellipse cx="{x+8*s_:.0f}" cy="{y+4*s_:.0f}" rx="{22*s_:.0f}"'
          f' ry="{9*s_:.0f}" fill="#8a2a18" {o(3)}/></g>')
    return s


def _portfel(x, y, s_=1.0, t=0.0, ug=0.0):
    """Портфель: кожаный корпус со швами, два ремешка с пряжками, скобяной
    замок и ручка дугой."""
    w2, h2 = 150 * s_, 180 * s_
    return (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
            f'{ten(x, y + 8 * s_, w2 * .54, 12 * s_, .45)}'
            f'<rect x="{x-w2/2:.0f}" y="{y-h2:.0f}" width="{w2:.0f}"'
            f' height="{h2:.0f}" rx="{14*s_:.0f}" fill="#6b4a2c" {o(6)}/>'
            f'<path d="M{x-w2/2:.0f},{y-h2*.70:.0f} L{x+w2/2:.0f},{y-h2*.70:.0f}'
            f' L{x+w2*.44:.0f},{y-h2*.40:.0f} L{x-w2*.44:.0f},{y-h2*.40:.0f} Z"'
            f' fill="#7d5636" {o(5)}/>'
            + "".join(f'<g><rect x="{x+i*w2*.26-8*s_:.0f}" y="{y-h2*.52:.0f}"'
                      f' width="{16*s_:.0f}" height="{h2*.30:.0f}" rx="5"'
                      f' fill="#4a3522" {o(3)}/>'
                      f'<rect x="{x+i*w2*.26-11*s_:.0f}" y="{y-h2*.36:.0f}"'
                      f' width="{22*s_:.0f}" height="{12*s_:.0f}" rx="4"'
                      f' fill="{ZOL}" {o(3)}/></g>' for i in (-1, 1))
            + f'<rect x="{x-14*s_:.0f}" y="{y-h2*.60:.0f}" width="{28*s_:.0f}"'
              f' height="{20*s_:.0f}" rx="5" fill="{ZHELEZ}" {o(3)}/>'
            + f'<path d="M{x-42*s_:.0f},{y-h2:.0f} q{42*s_:.0f},{-56*s_:.0f}'
              f' {84*s_:.0f},0" fill="none" stroke="#4a3522"'
              f' stroke-width="{13*s_:.0f}"/>'
            + f'<path d="M{x-w2*.42:.0f},{y-h2*.16:.0f} q{w2*.42:.0f},{10*s_:.0f}'
              f' {w2*.84:.0f},0" fill="none" stroke="#4a3522"'
              f' stroke-width="{max(2,4*s_):.0f}" opacity=".8"/></g>')


def _fonar_dvorovoy(x, y, t, s_=1.0, h_=620):
    """Дворовый фонарь: чугунный столб с хомутами, кронштейн, жестяной
    колпак и лампа с живым дрожанием света; конус света на снег."""
    mig = .78 + .18 * abs(A.w(t, 2.6, .2))
    s = (f'{ten(x, y + 8 * s_, 44 * s_, 12 * s_, .45)}'
         f'<path d="M{x-30*s_:.0f},{y:.0f} q{30*s_:.0f},{-20*s_:.0f}'
         f' {60*s_:.0f},0 Z" fill="#3d3a38" {o(4)}/>'
         f'<rect x="{x-11*s_:.0f}" y="{y-h_:.0f}" width="{22*s_:.0f}"'
         f' height="{h_:.0f}" rx="{9*s_:.0f}" fill="#4e4a47" {o(5)}/>')
    for i in range(3):
        s += (f'<rect x="{x-16*s_:.0f}" y="{y-h_*(.26+i*.26):.0f}"'
              f' width="{32*s_:.0f}" height="{12*s_:.0f}" rx="5"'
              f' fill="#5f5a56" {o(3)}/>')
    s += (f'<path d="M{x:.0f},{y-h_:.0f} q{10*s_:.0f},{-54*s_:.0f}'
          f' {66*s_:.0f},{-56*s_:.0f}" fill="none" stroke="#4e4a47"'
          f' stroke-width="{14*s_:.0f}"/>'
          f'<path d="M{x+36*s_:.0f},{y-h_-56*s_:.0f} L{x+96*s_:.0f},{y-h_-56*s_:.0f}'
          f' L{x+82*s_:.0f},{y-h_-96*s_:.0f} L{x+50*s_:.0f},{y-h_-96*s_:.0f} Z"'
          f' fill="#3d3a38" {o(5)}/>'
          f'<ellipse cx="{x+66*s_:.0f}" cy="{y-h_-42*s_:.0f}" rx="{34*s_:.0f}"'
          f' ry="{24*s_:.0f}" fill="{SVET}" opacity="{mig:.2f}" {o(4)}/>'
          f'{teplo(x + 66 * s_, y - h_ - 30 * s_, 320 * s_, 280 * s_, .40)}'
          + _konus_sveta(x + 66 * s_, y - h_ - 20 * s_, 220 * s_,
                         h_ + 40 * s_, 0.0, .26))
    return s


def _okoshko_kassy(x, y, w_, h_, t, otryv=.0):
    """ОКОШКО КАССЫ — главный предмет: полукруглое окно в деревянной
    обвязке, латунная решётка, мраморный подоконничек, блюдце для монет и
    рулон билетов с отрывающимся билетом."""
    put = kontur_proema(x, y, w_, h_, "arka")
    s = (f'<path d="{put}" fill="#2a1d14"/>'
         f'<path d="{put}" fill="{SVET}" opacity=".20"/>'
         f'<path d="{put}" fill="none" stroke="#7d5636" stroke-width="34"/>')
    for i in range(7):
        s += (f'<line x1="{x+30+i*(w_-60)/6.0:.0f}" y1="{y+h_*.30:.0f}"'
              f' x2="{x+30+i*(w_-60)/6.0:.0f}" y2="{y+h_-14:.0f}"'
              f' stroke="{ZOL}" stroke-width="9" opacity=".85"/>')
    for i in range(3):
        s += (f'<path d="M{x+20:.0f},{y+h_*(.34+i*.20):.0f}'
              f' q{w_*.5:.0f},{-14:.0f} {w_-40:.0f},0" fill="none" stroke="{ZOL}"'
              f' stroke-width="8" opacity=".8"/>')
    s += (f'<rect x="{x-40:.0f}" y="{y+h_-16:.0f}" width="{w_+80:.0f}"'
          f' height="44" rx="12" fill="#cfc9bc" {o(6)}/>'
          f'<rect x="{x-40:.0f}" y="{y+h_+28:.0f}" width="{w_+80:.0f}"'
          f' height="18" rx="7" fill="#a8a299" {o(4)}/>')
    # блюдце для монет и рулон билетов
    s += (f'<ellipse cx="{x+w_*.26:.0f}" cy="{y+h_+2:.0f}" rx="64" ry="20"'
          f' fill="#dde6ea" {o(5)}/>'
          f'<ellipse cx="{x+w_*.26:.0f}" cy="{y+h_-2:.0f}" rx="50" ry="13"'
          f' fill="#b9c6cc" opacity=".9"/>')
    rx_ = x + w_ * .74
    s += (f'<circle cx="{rx_:.0f}" cy="{y+h_*.70:.0f}" r="52" fill="#e8c64e"'
          f' {o(5)}/>'
          f'<circle cx="{rx_:.0f}" cy="{y+h_*.70:.0f}" r="16" fill="#8a6038"'
          f' {o(3)}/>')
    for i in range(4):
        s += (f'<circle cx="{rx_:.0f}" cy="{y+h_*.70:.0f}" r="{46-i*10:.0f}"'
              f' fill="none" stroke="#c9a331" stroke-width="4" opacity=".8"/>')
    s += (f'<path d="M{rx_+50:.0f},{y+h_*.70:.0f} l{70+60*otryv:.0f},{-8:.0f}'
          f' l{2:.0f},{40:.0f} l{-(70+60*otryv):.0f},{8:.0f} Z"'
          f' fill="#f4eedc" {o(4)}/>'
          f'<path d="M{rx_+88+30*otryv:.0f},{y+h_*.70-6:.0f}'
          f' q{10:.0f},{20:.0f} {0:.0f},{38:.0f}" fill="none" stroke="#c9b48a"'
          f' stroke-width="5"/>')
    return s


def _naves_lampochki(x, y, w_, t, n=12, h_=70):
    """Навес кинотеатра двадцатых с бегущими лампочками: жестяной карниз,
    кронштейны и два ряда лампочек, которые загораются бегом."""
    s = (f'<rect x="{x:.0f}" y="{y:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="10" fill="#4e4a47" {o(7)}/>'
         f'<rect x="{x-16:.0f}" y="{y-16:.0f}" width="{w_+32:.0f}" height="24"'
         f' rx="9" fill="#5f5a56" {o(5)}/>')
    for i in (0, 1):
        for j in range(n):
            faza = ((t * 2.2 + j * .18 + i * .4) % 1.0)
            яр = .35 + .65 * (1 - abs(faza - .5) * 2)
            s += (f'<circle cx="{x+30+j*(w_-60)/(n-1.0):.0f}"'
                  f' cy="{y+20+i*(h_-34):.0f}" r="13" fill="{SVET}"'
                  f' opacity="{яр:.2f}" stroke="#8a7a46" stroke-width="4"/>')
    for i in range(4):
        bx = x + 60 + i * (w_ - 120) / 3.0
        s += (f'<path d="M{bx:.0f},{y+h_:.0f} q{10:.0f},{46:.0f} {-26:.0f},{64:.0f}'
              f' l{30:.0f},{6:.0f} q{16:.0f},{-30:.0f} {12:.0f},{-70:.0f} Z"'
              f' fill="#5f5a56" {o(4)}/>')
    s += (f'{teplo(x + w_ * .5, y + h_ + 40, w_ * .56, 180, .30)}')
    return s


def _tablichka_bez_cifr(x, y, w_, h_, t, ph=.0):
    """Табличка на двух крючках: жестяное поле с кромкой и ВОЛНИСТАЯ строка
    вместо года — свои буквы и цифры в декорации не рисуются, настоящий
    «1928» кладёт `kadr.py` поверх."""
    kach = 2.2 * A.w(t, 2.8, ph)
    s = (f'<g transform="rotate({kach:.1f} {x+w_*.5:.0f} {y:.0f})">'
         f'<line x1="{x+18:.0f}" y1="{y:.0f}" x2="{x+22:.0f}" y2="{y+26:.0f}"'
         f' stroke="{ZHELEZ}" stroke-width="5"/>'
         f'<line x1="{x+w_-18:.0f}" y1="{y:.0f}" x2="{x+w_-22:.0f}"'
         f' y2="{y+26:.0f}" stroke="{ZHELEZ}" stroke-width="5"/>'
         f'<rect x="{x:.0f}" y="{y+26:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="9" fill="#efe8d8" {o(5)}/>'
         f'<rect x="{x+10:.0f}" y="{y+36:.0f}" width="{w_-20:.0f}"'
         f' height="{h_-20:.0f}" rx="6" fill="none" stroke="#b8a86a"'
         f' stroke-width="5"/>'
         f'<path d="M{x+30:.0f},{y+26+h_*.5:.0f} q{(w_-60)*.25:.0f},{-14:.0f}'
         f' {(w_-60)*.5:.0f},0 q{(w_-60)*.25:.0f},{14:.0f} {(w_-60)*.5:.0f},0"'
         f' fill="none" stroke="#8a7a5c" stroke-width="8"/></g>')
    return s


def _ledenec(x, y, s_=1.0, t=0.0, ph=.0):
    """Леденец на палочке: спираль двух цветов, обёртка фантиком и блик,
    который ходит по спирали."""
    r = 34 * s_
    s = (f'<rect x="{x-5*s_:.0f}" y="{y:.0f}" width="{10*s_:.0f}"'
         f' height="{86*s_:.0f}" rx="4" fill="#efe8d8" {o(3)}/>'
         f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{r:.0f}" fill="#f4eedc" {o(5)}/>')
    for i in range(4):
        a0 = i * 90 + 14 * A.w(t, 2.2, ph)
        s += (f'<path d="M{x:.0f},{y:.0f} A{r:.0f},{r:.0f} 0 0 1'
              f' {x+r*math.cos(math.radians(a0+60)):.0f},'
              f'{y+r*math.sin(math.radians(a0+60)):.0f} L{x:.0f},{y:.0f} Z"'
              f' fill="{KRAS}" opacity=".9"/>')
    s += (f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{r:.0f}" fill="none"'
          f' stroke="{K}" stroke-width="{max(2,4*s_):.0f}"/>'
          f'<ellipse cx="{x-r*.34:.0f}" cy="{y-r*.34:.0f}" rx="{r*.22:.0f}"'
          f' ry="{r*.13:.0f}" fill="#ffffff"'
          f' opacity="{.35+.35*abs(A.w(t,1.9,ph)):.2f}"/>')
    return s


def _pianino(x, y, w_, t, h_=330, taper_igra=.0):
    """Пианино тапёра: лакированный корпус, откинутая крышка, два ряда
    клавиш с чёрными, подсвечники по бокам и педали. Клавиши проваливаются
    по ходу игры."""
    s = (f'{ten(x + w_ * .5, y + 10, w_ * .50, 18, .5)}'
         f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="10" fill="#2e2320" {o(8)}/>'
         f'<rect x="{x-14:.0f}" y="{y-h_-22:.0f}" width="{w_+28:.0f}"'
         f' height="26" rx="9" fill="#3d2f2a" {o(5)}/>'
         f'<rect x="{x+16:.0f}" y="{y-h_*.76:.0f}" width="{w_-32:.0f}"'
         f' height="{h_*.26:.0f}" rx="8" fill="#241b18" opacity=".9"/>')
    s += (f'<rect x="{x+10:.0f}" y="{y-h_*.46:.0f}" width="{w_-20:.0f}"'
          f' height="{h_*.16:.0f}" rx="6" fill="#efe8d8" {o(5)}/>')
    nk = int((w_ - 20) / 26)
    for i in range(nk):
        pr = 5 if (math.sin(t * 7 + i) > .7 and taper_igra > .3) else 0
        s += (f'<rect x="{x+12+i*26:.0f}" y="{y-h_*.46+pr:.0f}" width="22"'
              f' height="{h_*.16:.0f}" rx="3" fill="#f8f6ee" stroke="#b9b2a4"'
              f' stroke-width="3"/>')
    for i in range(nk):
        if i % 7 in (2, 6):
            continue
        s += (f'<rect x="{x+26+i*26:.0f}" y="{y-h_*.46:.0f}" width="14"'
              f' height="{h_*.10:.0f}" rx="3" fill="#1d1a18"/>')
    for i in (0, 1):
        sx = x + 40 + i * (w_ - 110)
        s += (f'<rect x="{sx:.0f}" y="{y-h_*.72:.0f}" width="18" height="34"'
              f' rx="6" fill="{ZOL}" {o(3)}/>'
              + svecha(sx + 9, y - h_ * .72, t, i * .4, .7, 60))
    for i in (0, 1):
        s += (f'<rect x="{x+w_*.40+i*60:.0f}" y="{y-34:.0f}" width="34"'
              f' height="18" rx="7" fill="{ZOL}" {o(3)}/>')
    return s


def _zatylki_ryad(x, y, w_, t, n=7, seed=5, h_baz=260, ryad=0):
    """РЯД ДЕТСКИХ ЗАТЫЛКОВ: фигуры СО СПИНЫ (lico=False) — кепки и банты.
    Рост СТРОГО ЧЕРЕЗ ОДНОГО крупный/мелкий (разница около двух раз), шаг
    рваный с перекрытиями, часть в профиль, наклон ±15°, и дети
    подпрыгивают на местах вразнобой."""
    rnd = random.Random(seed)
    s = ""
    poz = []
    for i in range(n):
        dx = x + (w_ / float(n)) * (i + rnd.uniform(-.14, .14))
        krup = (i % 2 == 0)
        hh = h_baz * (1.0 if krup else .52) * rnd.uniform(.92, 1.08)
        pryg = 14 * abs(math.sin(t * 3.4 + i * 1.1))
        pr = (i % 3 == 1)
        nak = rnd.uniform(-13, 13)
        poz.append((dx, y - pryg, hh))
        col = ["#4a5a72", "#6a5a4a", "#54505e", "#3f5c7a"][i % 4]
        s += figura(dx, y - pryg, hh, t, col=col, kant="#ffd98a",
                    platok=(i % 4 == 1), ph=i * .23, profil=pr, naklon=nak,
                    shapka=(i % 4 == 2), lico=False)
        # кепка или бант поверх затылка
        gy = y - pryg - hh * .845
        if i % 2 == 0:
            s += (f'<path d="M{dx-hh*.15:.0f},{gy:.0f} q{hh*.15:.0f},'
                  f'{-hh*.10:.0f} {hh*.30:.0f},{-hh*.01:.0f}'
                  f' q{-hh*.03:.0f},{hh*.045:.0f} {-hh*.30:.0f},{hh*.01:.0f} Z"'
                  f' fill="#3d352c" {o(4)}/>'
                  f'<path d="M{dx+hh*.13:.0f},{gy-hh*.01:.0f} q{hh*.09:.0f},'
                  f'{hh*.012:.0f} {hh*.10:.0f},{hh*.035:.0f}'
                  f' q{-hh*.06:.0f},{hh*.02:.0f} {-hh*.12:.0f},{hh*.005:.0f} Z"'
                  f' fill="#2f291f" {o(3)}/>')
        else:
            for sg in (-1, 1):
                s += (f'<path d="M{dx+sg*hh*.10:.0f},{gy-hh*.08:.0f}'
                      f' q{sg*hh*.13:.0f},{-hh*.09:.0f} {sg*hh*.15:.0f},{hh*.01:.0f}'
                      f' q{-sg*hh*.06:.0f},{hh*.05:.0f} {-sg*hh*.15:.0f},{-hh*.01:.0f} Z"'
                      f' fill="{KRAS}" {o(3)}/>')
            s += (f'<circle cx="{dx:.0f}" cy="{gy-hh*.07:.0f}" r="{hh*.03:.0f}"'
                  f' fill="{KRAS}" {o(3)}/>')
    return s, poz


def _tort_svechi(x, y, w_, t, gasnet=.0, yarusov=3):
    """ОГРОМНЫЙ ИМЕНИННЫЙ ТОРТ — главный предмет: три яруса с кремовыми
    розетками и подтёками глазури, по верхнему ярусу ЛЕС СВЕЧЕЙ, которые
    гаснут рядами и курятся дымком. Цифры на торте НЕ рисуем — её кладёт
    `kadr.py` поверх, здесь под неё оставлено чистое поле."""
    s = f'{ten(x, y + 16, w_ * .56, 26, .55)}'
    yb = y
    for i in range(yarusov):
        ww = w_ * (1.0 - i * .22)
        hh = 96 - i * 10
        s += (f'<rect x="{x-ww*.5:.0f}" y="{yb-hh:.0f}" width="{ww:.0f}"'
              f' height="{hh:.0f}" rx="16" fill="#f4e4c8" {o(7)}/>'
              f'<ellipse cx="{x:.0f}" cy="{yb-hh:.0f}" rx="{ww*.5:.0f}"'
              f' ry="{ww*.09:.0f}" fill="#fbf2de" {o(5)}/>')
        # подтёки глазури
        for j in range(int(ww / 56)):
            dx = x - ww * .5 + 24 + j * 56
            s += (f'<path d="M{dx:.0f},{yb-hh+4:.0f} q{6:.0f},{30:.0f}'
                  f' {-2:.0f},{48:.0f} q{12:.0f},{8:.0f} {18:.0f},{-6:.0f}'
                  f' q{-6:.0f},{-22:.0f} {4:.0f},{-44:.0f} Z"'
                  f' fill="#d9789c" opacity=".9" {o(3)}/>')
        # кремовые розетки по кромке
        for j in range(int(ww / 44)):
            dx = x - ww * .5 + 20 + j * 44
            s += (f'<circle cx="{dx:.0f}" cy="{yb-4:.0f}" r="13"'
                  f' fill="#fffaf0" {o(3)}/>')
        yb -= hh
    # ЛЕС СВЕЧЕЙ на верхнем ярусе, гаснут рядами
    rnd = random.Random(299)
    for r in range(3):
        for c in range(9):
            cx = x - w_ * .26 + c * (w_ * .52 / 8.0) + rnd.uniform(-6, 6)
            cy = yb + 4 + r * 16
            gor = (gasnet * 3.0) < (r + c / 9.0)
            s += (f'<rect x="{cx-5:.0f}" y="{cy-58:.0f}" width="10" height="58"'
                  f' rx="4" fill="{["#e8c64e", "#d9789c", "#8fa3c2"][c % 3]}"'
                  f' {o(3)}/>')
            if gor:
                s += (f'<ellipse cx="{cx:.0f}" cy="{cy-68:.0f}" rx="6"'
                      f' ry="{12+3*A.w(t, 1.3, c*.2):.0f}" fill="{SVET}"/>'
                      f'<ellipse cx="{cx:.0f}" cy="{cy-66:.0f}" rx="3"'
                      f' ry="7" fill="#fff6dc"/>')
            else:
                s += (f'<path d="M{cx:.0f},{cy-62:.0f} q{8:.0f},{-20:.0f}'
                      f' {-2:.0f},{-38:.0f}" fill="none" stroke="#cfd6de"'
                      f' stroke-width="5" opacity=".6"/>')
    s += teplo(x, yb - 60, 420, 300, .34)
    return s


def _kolpak_imeninnika(x, y, s_=1.0, t=0.0, ph=.0):
    """Колпак именинника на стуле: конус в полоску с кисточкой и резинкой,
    покачивается на кисточке."""
    kach = 3.0 * A.w(t, 2.4, ph)
    s = (f'<g transform="rotate({kach:.1f} {x:.0f} {y:.0f})">'
         f'{ten(x, y + 6 * s_, 54 * s_, 11 * s_, .4)}'
         f'<path d="M{x-54*s_:.0f},{y:.0f} L{x+54*s_:.0f},{y:.0f}'
         f' L{x+6*s_:.0f},{y-150*s_:.0f} Z" fill="#d9789c" {o(5)}/>')
    for i in range(4):
        s += (f'<path d="M{x-46*s_+i*8*s_:.0f},{y-i*34*s_:.0f}'
              f' L{x+46*s_-i*10*s_:.0f},{y-i*34*s_-8*s_:.0f}" fill="none"'
              f' stroke="#f4eedc" stroke-width="{max(3,8*s_):.0f}" opacity=".9"/>')
    s += (f'<circle cx="{x+6*s_:.0f}" cy="{y-158*s_:.0f}" r="{16*s_:.0f}"'
          f' fill="#e8c64e" {o(4)}/>'
          f'<ellipse cx="{x:.0f}" cy="{y:.0f}" rx="{54*s_:.0f}" ry="{13*s_:.0f}"'
          f' fill="#c05a80" {o(4)}/></g>')
    return s


def _shturval(x, y, s_=1.0, t=0.0):
    """Маленький рисованный штурвал: обод с восемью рукоятями, спицы,
    латунная ступица; медленно поворачивается."""
    r = 68 * s_
    ug = 10 * A.w(t, 3.2, .2)
    s = (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
         f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{r:.0f}" fill="none"'
         f' stroke="#8a6038" stroke-width="{16*s_:.0f}"/>'
         f'<circle cx="{x:.0f}" cy="{y:.0f}" r="{r*.22:.0f}" fill="{ZOL}"'
         f' {o(4)}/>')
    for i in range(8):
        a = math.radians(i * 45)
        s += (f'<line x1="{x+math.cos(a)*r*.2:.0f}" y1="{y+math.sin(a)*r*.2:.0f}"'
              f' x2="{x+math.cos(a)*r*.92:.0f}" y2="{y+math.sin(a)*r*.92:.0f}"'
              f' stroke="#9c7049" stroke-width="{max(3,8*s_):.0f}"/>'
              f'<path d="M{x+math.cos(a)*r*1.0:.0f},{y+math.sin(a)*r*1.0:.0f}'
              f' l{math.cos(a)*26*s_:.0f},{math.sin(a)*26*s_:.0f}" fill="none"'
              f' stroke="#7d5636" stroke-width="{max(3,11*s_):.0f}"'
              f' stroke-linecap="round"/>')
    return s + "</g>"


def _trost_nabaldashnik(x, y, s_=1.0, t=0.0, h_=300):
    """Трость с набалдашником: гнутая палка с кольцом и шаровым
    набалдашником, резиновый наконечник."""
    return (f'<line x1="{x:.0f}" y1="{y:.0f}" x2="{x+14*s_:.0f}"'
            f' y2="{y-h_*s_:.0f}" stroke="url(#derev)"'
            f' stroke-width="{16*s_:.0f}" stroke-linecap="round"/>'
            f'<circle cx="{x+16*s_:.0f}" cy="{y-h_*s_-14*s_:.0f}"'
            f' r="{26*s_:.0f}" fill="{ZOL}" {o(5)}/>'
            f'<ellipse cx="{x+8*s_:.0f}" cy="{y-h_*s_-22*s_:.0f}"'
            f' rx="{9*s_:.0f}" ry="{6*s_:.0f}" fill="#f2e2a0" opacity=".7"/>'
            f'<rect x="{x+4*s_:.0f}" y="{y-h_*s_+34*s_:.0f}" width="{20*s_:.0f}"'
            f' height="{12*s_:.0f}" rx="5" fill="{ZHELEZ}" {o(3)}/>'
            f'<ellipse cx="{x:.0f}" cy="{y+4*s_:.0f}" rx="{12*s_:.0f}"'
            f' ry="{7*s_:.0f}" fill="#2a2726" {o(3)}/>')


def _meshok_zabota(x, y, s_=1.0, t=0.0, hmur=.0):
    """Серый мешок-забота: холщовый куль с завязкой и ХМУРОЙ рожицей —
    две брови вниз и опущенный рот. Рожица хмурится вслед, когда мимо
    проходят. Это нарисованный образ, а не человек."""
    w2, h2 = 120 * s_, 150 * s_
    dysh = 4 * s_ * A.w(t, 1.7, .2)
    s = (f'{ten(x, y + 8 * s_, w2 * .58, 13 * s_, .5)}'
         f'<path d="M{x-w2*.5:.0f},{y:.0f} q{-10*s_:.0f},{-h2*.72:.0f}'
         f' {w2*.26:.0f},{-h2*.86-dysh:.0f} q{w2*.24:.0f},{-14*s_:.0f}'
         f' {w2*.48:.0f},0 q{w2*.36:.0f},{h2*.16:.0f} {w2*.26:.0f},{h2*.86+dysh:.0f} Z"'
         f' fill="#8d939a" {o(7)}/>')
    for i in range(4):
        s += (f'<path d="M{x-w2*.36+i*w2*.24:.0f},{y-h2*.72:.0f}'
              f' q{8*s_:.0f},{h2*.34:.0f} {-2*s_:.0f},{h2*.64:.0f}" fill="none"'
              f' stroke="#767c82" stroke-width="{max(2,5*s_):.0f}" opacity=".8"/>')
    s += (f'<path d="M{x-w2*.24:.0f},{y-h2*.86-dysh:.0f} q{w2*.24:.0f},'
          f'{-20*s_:.0f} {w2*.48:.0f},0" fill="none" stroke="#5f656b"'
          f' stroke-width="{14*s_:.0f}"/>'
          f'<path d="M{x-w2*.14:.0f},{y-h2*.94-dysh:.0f} q{w2*.08:.0f},'
          f'{-30*s_:.0f} {w2*.10:.0f},{-44*s_:.0f}" fill="none"'
          f' stroke="#767c82" stroke-width="{max(3,9*s_):.0f}"/>')
    # ХМУРАЯ РОЖИЦА
    cy = y - h2 * .50
    for i in (-1, 1):
        s += (f'<path d="M{x+i*w2*.22-w2*.10:.0f},{cy-18*s_-10*s_*hmur:.0f}'
              f' q{w2*.10:.0f},{-10*s_-8*s_*hmur:.0f} {w2*.20:.0f},{4*s_:.0f}"'
              f' fill="none" stroke="{K}" stroke-width="{max(3,7*s_):.0f}"'
              f' stroke-linecap="round"/>')
        s += (f'<circle cx="{x+i*w2*.18:.0f}" cy="{cy:.0f}" r="{9*s_:.0f}"'
              f' fill="{K}"/>')
    s += (f'<path d="M{x-w2*.20:.0f},{cy+44*s_+8*s_*hmur:.0f}'
          f' q{w2*.20:.0f},{-20*s_-12*s_*hmur:.0f} {w2*.40:.0f},0"'
          f' fill="none" stroke="{K}" stroke-width="{max(3,8*s_):.0f}"'
          f' stroke-linecap="round"/>')
    return s


def _bidon(x, y, s_=1.0, t=0.0, ug=0.0):
    """Бидон: конусное тулово с обручем, крышка с бортиком, дуга-ручка на
    двух ушках, вмятина и блик по боку."""
    w2, h2 = 120 * s_, 170 * s_
    return (f'<g transform="rotate({ug:.1f} {x:.0f} {y:.0f})">'
            f'{ten(x, y + 8 * s_, w2 * .54, 12 * s_, .45)}'
            f'<path d="M{x-w2*.5:.0f},{y:.0f} L{x+w2*.5:.0f},{y:.0f}'
            f' L{x+w2*.34:.0f},{y-h2*.70:.0f} L{x-w2*.34:.0f},{y-h2*.70:.0f} Z"'
            f' fill="#b6bcc2" {o(6)}/>'
            f'<rect x="{x-w2*.36:.0f}" y="{y-h2*.76:.0f}" width="{w2*.72:.0f}"'
            f' height="{h2*.10:.0f}" rx="{7*s_:.0f}" fill="#9aa3aa" {o(4)}/>'
            f'<ellipse cx="{x:.0f}" cy="{y-h2*.80:.0f}" rx="{w2*.30:.0f}"'
            f' ry="{h2*.06:.0f}" fill="#cfd5da" {o(4)}/>'
            f'<circle cx="{x:.0f}" cy="{y-h2*.86:.0f}" r="{10*s_:.0f}"'
            f' fill="{ZHELEZ}" {o(3)}/>'
            f'<path d="M{x-w2*.30:.0f},{y-h2*.74:.0f} q{w2*.30:.0f},{-h2*.26:.0f}'
            f' {w2*.60:.0f},0" fill="none" stroke="{ZHELEZ}"'
            f' stroke-width="{10*s_:.0f}"/>'
            f'<rect x="{x-w2*.5:.0f}" y="{y-h2*.34:.0f}" width="{w2:.0f}"'
            f' height="{h2*.07:.0f}" fill="#8f979d" opacity=".8"/>'
            f'<path d="M{x-w2*.26:.0f},{y-h2*.58:.0f} q{10*s_:.0f},{h2*.22:.0f}'
            f' {2*s_:.0f},{h2*.42:.0f}" fill="none" stroke="#eef2f4"'
            f' stroke-width="{10*s_:.0f}" opacity=".5"/>'
            f'<ellipse cx="{x+w2*.22:.0f}" cy="{y-h2*.40:.0f}" rx="{14*s_:.0f}"'
            f' ry="{9*s_:.0f}" fill="#9aa3aa" opacity=".7"/></g>')


def _shapka_s_bumazhkami(x, y, s_=1.0, t=0.0, tyanet=.0, n=9, seed=5):
    """Шапка, полная свёрнутых бумажек: меховая шапка тульей вверх, в ней
    трубочки бумажек с нитяной перевязью; одна бумажка тянется наружу."""
    rnd = random.Random(seed)
    s = (f'{ten(x, y + 8 * s_, 96 * s_, 14 * s_, .45)}'
         f'<path d="M{x-96*s_:.0f},{y:.0f} q{6*s_:.0f},{-104*s_:.0f}'
         f' {96*s_:.0f},{-104*s_:.0f} q{90*s_:.0f},0 {96*s_:.0f},{104*s_:.0f} Z"'
         f' fill="#4a3f36" {o(7)}/>'
         f'<ellipse cx="{x:.0f}" cy="{y-100*s_:.0f}" rx="{86*s_:.0f}"'
         f' ry="{24*s_:.0f}" fill="#2f2924" {o(5)}/>'
         f'<path d="M{x-100*s_:.0f},{y-8*s_:.0f} q{100*s_:.0f},{34*s_:.0f}'
         f' {200*s_:.0f},0" fill="none" stroke="#cfc1a4"'
         f' stroke-width="{26*s_:.0f}"/>')
    for i in range(n):
        a = -2.7 + i * (2.3 / max(1, n - 1))
        bx = x + math.cos(a) * 62 * s_
        by = y - 104 * s_ - abs(math.sin(a)) * 18 * s_
        ug = math.degrees(a) + 90 + rnd.uniform(-10, 10)
        s += (f'<g transform="rotate({ug:.0f} {bx:.0f} {by:.0f})">'
              f'<rect x="{bx-9*s_:.0f}" y="{by-48*s_:.0f}" width="{18*s_:.0f}"'
              f' height="{54*s_:.0f}" rx="{8*s_:.0f}" fill="#f4eedc" {o(3)}/>'
              f'<line x1="{bx-9*s_:.0f}" y1="{by-26*s_:.0f}" x2="{bx+9*s_:.0f}"'
              f' y2="{by-26*s_:.0f}" stroke="#c9b48a"'
              f' stroke-width="{max(2,4*s_):.0f}"/></g>')
    if tyanet > .02:
        ty = y - 120 * s_ - 90 * s_ * tyanet
        s += (f'<g transform="rotate({-12:.0f} {x+20*s_:.0f} {ty:.0f})">'
              f'<rect x="{x+10*s_:.0f}" y="{ty-56*s_:.0f}" width="{22*s_:.0f}"'
              f' height="{62*s_:.0f}" rx="{9*s_:.0f}" fill="#fbf6e6" {o(4)}/>'
              f'<line x1="{x+10*s_:.0f}" y1="{ty-30*s_:.0f}"'
              f' x2="{x+32*s_:.0f}" y2="{ty-30*s_:.0f}" stroke="#c9b48a"'
              f' stroke-width="{max(2,5*s_):.0f}"/>'
              f'<path d="M{x+14*s_:.0f},{ty-14*s_:.0f} q{11*s_:.0f},{-8*s_:.0f}'
              f' {22*s_:.0f},0" fill="none" stroke="#8a7a5c"'
              f' stroke-width="{max(2,4*s_):.0f}"/></g>')
    return s


def _romashka_v_stakane(x, y, s_=1.0, t=0.0, opali=.0):
    """Ромашка в стакане с облетевшими лепестками: гранёный стакан с водой,
    стебель, цветок (берём готовую `_romashka`), а лепестки лежат на столе
    и один ещё падает."""
    s = (f'{ten(x, y + 6 * s_, 44 * s_, 10 * s_, .4)}'
         f'<path d="M{x-40*s_:.0f},{y-130*s_:.0f} L{x+40*s_:.0f},{y-130*s_:.0f}'
         f' L{x+32*s_:.0f},{y:.0f} L{x-32*s_:.0f},{y:.0f} Z"'
         f' fill="url(#stekl)" opacity=".9" {o(5)}/>'
         f'<path d="M{x-36*s_:.0f},{y-70*s_:.0f} L{x+36*s_:.0f},{y-70*s_:.0f}'
         f' L{x+32*s_:.0f},{y-4*s_:.0f} L{x-32*s_:.0f},{y-4*s_:.0f} Z"'
         f' fill="{VODA}" opacity=".45"/>')
    for i in range(3):
        s += (f'<line x1="{x-24*s_+i*24*s_:.0f}" y1="{y-126*s_:.0f}"'
              f' x2="{x-22*s_+i*22*s_:.0f}" y2="{y-8*s_:.0f}" stroke="#ffffff"'
              f' stroke-width="{max(2,4*s_):.0f}" opacity=".35"/>')
    s += (f'<line x1="{x+4*s_:.0f}" y1="{y-120*s_:.0f}" x2="{x+12*s_:.0f}"'
          f' y2="{y-240*s_:.0f}" stroke="#56763f"'
          f' stroke-width="{max(3,9*s_):.0f}"/>')
    s += _romashka(x + 12 * s_, y - 250 * s_, t, s_ * .9,
                   max(3, int(round(8 - 5 * opali))), opali, 6.0)
    rnd = random.Random(int(x) + 31)
    for i in range(6):
        lx = x + rnd.uniform(-150, 180) * s_
        ly = y + rnd.uniform(6, 26) * s_
        s += (f'<ellipse cx="{lx:.0f}" cy="{ly:.0f}" rx="{26*s_:.0f}"'
              f' ry="{11*s_:.0f}" fill="#f8f6ee"'
              f' transform="rotate({rnd.uniform(-40,40):.0f} {lx:.0f} {ly:.0f})"'
              f' {o(3)}/>')
    p = (t * .45) % 1.0
    s += (f'<ellipse cx="{x+70*s_+40*s_*p:.0f}" cy="{y-220*s_+p*210*s_:.0f}"'
          f' rx="{24*s_:.0f}" ry="{10*s_:.0f}" fill="#f8f6ee" {o(3)}'
          f' transform="rotate({p*160:.0f} {x+70*s_:.0f} {y-220*s_:.0f})"/>')
    return s


def _svadebnaya_kartochka(x, y, w_, t, prost=.0, h_=None):
    """Свадебная карточка в рамке, которая ПРОСТУПАЕТ к концу плана: резная
    рамка, карточка с двумя фигурками в профиль (невеста с фатой, он в
    пиджаке), она уже седая и улыбается; по стеклу блик дугой. Лиц крупно
    нет — только силуэты в профиль нашим же стилем."""
    if prost <= .02:
        return ""
    h_ = h_ if h_ else int(w_ * 1.22)
    op = prost
    s = (f'<g opacity="{op:.2f}">'
         f'{ten(x + w_ * .5, y + 10, w_ * .46, 14, .4)}'
         f'<rect x="{x:.0f}" y="{y-h_:.0f}" width="{w_:.0f}" height="{h_:.0f}"'
         f' rx="10" fill="#8a6038" {o(6)}/>'
         f'<rect x="{x+20:.0f}" y="{y-h_+20:.0f}" width="{w_-40:.0f}"'
         f' height="{h_-40:.0f}" rx="6" fill="#efe8d8" {o(4)}/>')
    for i in range(4):
        s += (f'<path d="M{x+8:.0f},{y-h_+22+i*(h_-44)/4.0:.0f}'
              f' q{14:.0f},{-12:.0f} {0:.0f},{-24:.0f}" fill="none"'
              f' stroke="#a97a4e" stroke-width="5" opacity=".8"/>')
    cx = x + w_ * .5
    by = y - 40
    for i, (dx, hh, fata) in enumerate(((-w_ * .16, h_ * .60, True),
                                        (w_ * .16, h_ * .66, False))):
        col = "#cfc9bc" if fata else "#3f4a58"
        s += (f'<path d="M{cx+dx-hh*.14:.0f},{by:.0f}'
              f' q{hh*.14:.0f},{-hh*.10:.0f} {hh*.28:.0f},0'
              f' L{cx+dx+hh*.17:.0f},{by-hh*.56:.0f}'
              f' L{cx+dx-hh*.17:.0f},{by-hh*.56:.0f} Z" fill="{col}" {o(4)}/>'
              f'<circle cx="{cx+dx:.0f}" cy="{by-hh*.70:.0f}" r="{hh*.13:.0f}"'
              f' fill="#e8d8c0" {o(4)}/>')
        if fata:
            s += (f'<path d="M{cx+dx-hh*.16:.0f},{by-hh*.72:.0f}'
                  f' q{hh*.16:.0f},{-hh*.22:.0f} {hh*.32:.0f},0'
                  f' q{hh*.06:.0f},{hh*.40:.0f} {-hh*.04:.0f},{hh*.52:.0f}'
                  f' q{-hh*.28:.0f},{-hh*.10:.0f} {-hh*.28:.0f},{-hh*.52:.0f} Z"'
                  f' fill="#f4f8fa" opacity=".82" {o(3)}/>'
                  f'<path d="M{cx+dx-hh*.11:.0f},{by-hh*.78:.0f}'
                  f' q{hh*.11:.0f},{-hh*.07:.0f} {hh*.22:.0f},0" fill="none"'
                  f' stroke="#e8eef6" stroke-width="{hh*.030:.0f}"/>')
        else:
            s += (f'<path d="M{cx+dx-hh*.12:.0f},{by-hh*.80:.0f}'
                  f' q{hh*.12:.0f},{-hh*.08:.0f} {hh*.24:.0f},0" fill="none"'
                  f' stroke="#9aa3aa" stroke-width="{hh*.034:.0f}"/>')
        # улыбка в профиль — короткая дуга, без лица крупно
        s += (f'<path d="M{cx+dx+hh*.04:.0f},{by-hh*.66:.0f}'
              f' q{hh*.05:.0f},{hh*.035:.0f} {hh*.085:.0f},{-hh*.005:.0f}"'
              f' fill="none" stroke="{K}" stroke-width="{hh*.018:.0f}"'
              f' stroke-linecap="round"/>')
    s += (f'<path d="M{x+36:.0f},{y-h_*.74:.0f} L{x+w_*.56:.0f},{y-h_*.94:.0f}"'
          f' fill="none" stroke="#ffffff" stroke-width="16" opacity=".3"/>'
          f'<path d="M{x+20:.0f},{y-30:.0f} q{w_*.5-20:.0f},{-18:.0f}'
          f' {w_-40:.0f},0" fill="none" stroke="#c9b48a" stroke-width="6"/>'
          f'</g>')
    return s


# ── ДЕКОРАЦИИ, ЧЕТВЁРТАЯ ПАРТИЯ ───────────────────────────────────────────

def televizor_na_nozhkah_i_portret(t):
    """Комната: телевизор на тонких ножках с выпуклым экраном крупно, на нём
    салфетка и ваза, рядом торшер, кресло, ёлочная ветка в банке. На экране
    настоящий портрет. Бабушка сидит в кресле и обеими руками держит
    вязание, внучка на ковре у телевизора правой рукой показывает на экран,
    левой опирается о ковёр."""
    rnd = random.Random(907)
    pol = 1012
    s = f'<rect width="{W}" height="{H}" fill="#2b241e"/>'
    s += SL(Z_DAL, f'<rect x="0" y="0" width="{W}" height="{pol:.0f}"'
                   f' fill="#6a5a46"/>'
            + "".join(f'<line x1="{40+i*86:.0f}" y1="0" x2="{40+i*86:.0f}"'
                      f' y2="{pol:.0f}" stroke="#5a4a38" stroke-width="7"'
                      f' opacity=".6"/>' for i in range(23)))
    s += SL(Z_DAL, kvartira_veschi(1300, 170, 600, t, 909))
    s += SL(Z_DAL, _kover_na_stene(80, 150, 620, 380, t, 911))
    s += SL(Z_DAL, _ramki_na_stene(760, 130, 420, t, 913, 3))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}" height="{H-pol+18:.0f}"'
                   f' fill="#7a6248"/>' + polovicy(pol + 14)
            + _pol_shvy(pol + 16, 1074, 915, 6, "#5e4a34"))
    s += SL(Z_SRED, _polovik(820, pol + 36, 980, 150, "#8a4a5c", "#5a2c3c"))
    # ГЛАВНЫЙ ПРЕДМЕТ: телевизор на ножках, на экране настоящий портрет
    tx, ty, tw = 620, pol - 150, 680
    s += SL(Z_SRED, _televizor_nozhki(tx, ty, tw, t, 430))
    px, py, pw, ph_ = tx + 44, ty - 400, 780, 330
    px, py = tx - 10, ty - 400
    pw, ph_ = 780, 330
    put = kontur_proema(px, py, pw, ph_, "pryam")
    vid = (f'<path d="{put}" fill="#2a3038"/>'
           f'<ellipse cx="{px+pw*.5:.0f}" cy="{py+ph_*.52:.0f}"'
           f' rx="{pw*.30:.0f}" ry="{ph_*.34:.0f}" fill="#54606a" opacity=".9"/>'
           f'<ellipse cx="{px+pw*.5:.0f}" cy="{py+ph_*.34:.0f}"'
           f' rx="{pw*.13:.0f}" ry="{ph_*.17:.0f}" fill="#8a929a" opacity=".85"/>')
    for i in range(6):
        vid += (f'<rect x="{px+20:.0f}" y="{py+30+i*48:.0f}" width="{pw-40:.0f}"'
                f' height="{14:.0f}" fill="#cfd6de"'
                f' opacity="{.10+.08*abs(A.w(t,1.7,i*.3)):.2f}"/>')
    s += SL(Z_SRED, vid + mesto_stoka(px, py, pw, ph_, "pryam"))
    # обвязка поверх: выпуклое стекло и скруглённая рамка кинескопа
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#5b4428"'
                    f' stroke-width="44"/>'
            + f'<path d="{put}" fill="none" stroke="#8a6038" stroke-width="16"/>'
            + f'<path d="M{px+70:.0f},{py+60:.0f} Q{px+pw*.34:.0f},{py+20:.0f}'
              f' {px+pw*.56:.0f},{py+52:.0f}" fill="none" stroke="#ffffff"'
              f' stroke-width="22" opacity="{.14+.08*abs(A.w(t,3.0,.2)):.2f}"/>'
            + f'<ellipse cx="{px+pw*.5:.0f}" cy="{py+ph_*.5:.0f}"'
              f' rx="{pw*.52:.0f}" ry="{ph_*.60:.0f}" fill="none"'
              f' stroke="#4a3522" stroke-width="18" opacity=".55"/>')
    # салфетка и ваза на телевизоре
    s += SL(Z_SRED, f'<ellipse cx="{tx+tw*.72:.0f}" cy="{ty-446:.0f}" rx="96"'
                    f' ry="22" fill="{KREM}" {o(5)}/>'
            + _vaza_s_yablokami(tx + tw * .72, ty - 450, 1.0, t, 917, 5))
    s += SL(Z_DAL, tusklaya_lampochka(900, 40, t, 1.05, True))
    s += SL(Z_SRED, _torsher(1480, pol, t, 1.0, 620))
    s += SL(Z_SRED, _elovaya_vetka_v_banke(240, pol - 6, 1.1, t, .3))
    s += SL(Z_SRED, _kreslo(1620, pol, 400, t, 440, "#6c5a4a"))
    s += SL(Z_SRED, _stolik(1300, pol, 260, t, 200, True))
    # ДВЕ ФИГУРЫ: бабушка в кресле и внучка на ковре
    bx, by_, bh = 1680, pol - 170, 560
    vx, vy, vh = 1060, pol + 20, 400
    _figury_kadra((bx, by_, bh), (vx, vy, vh))
    pok = A.ease(A.seg(t, .6, 1.2))
    bab = figura(bx, by_, bh, t, col="#54505e", kant="#ffd98a", platok=True,
                 ph=.3, naklon=3.0)
    r1, (k1x, k1y), _ = _ruka_mimo(bx, by_, bh, -1, bh * .34, 44, t,
                                   "#54505e", "#ffd98a", .2, 4.0)
    r2, (k2x, k2y), _ = _ruka_sgib_mimo(bx, by_, bh, -1, bh * .22, 20,
                                        bh * .22, 50, t, "#54505e",
                                        "#ffd98a", .7, 4.0)
    bab += r1 + r2
    s += SL(Z_SRED, bab)
    s += SL(Z_SRED, _vyazanie((k1x + k2x) * .5 - 30, k1y + 16, .9, t, .2))
    s += SL(Z_SRED, _varezhka(k1x, k1y + 2, bh, t, .2)
            + _varezhka(k2x, k2y + 2, bh, t, .7))
    vnu = figura(vx, vy, vh, t, col="#b8323a", kant="#ffd98a", ph=.7,
                 naklon=5.0)
    p1, (m1x, m1y), _ = _ruka_mimo(vx, vy, vh, -1, vh * .48, 6 - 18 * pok, t,
                                   "#b8323a", "#ffd98a", .1, 5.0)
    p2, (m2x, m2y), _ = _ruka_mimo(vx, vy, vh, 1, vh * .40, 56, t,
                                   "#b8323a", "#ffd98a", .5, 3.0)
    vnu += p1 + p2
    s += SL(Z_SRED, vnu)
    # поджатые ноги на ковре: опора названа, ступни видны из-под подола
    s += SL(Z_SRED, f'<path d="M{vx-vh*.22:.0f},{vy-vh*.05:.0f}'
                    f' q{vh*.22:.0f},{vh*.06:.0f} {vh*.44:.0f},0'
                    f' q{-vh*.10:.0f},{vh*.05:.0f} {-vh*.44:.0f},0 Z"'
                    f' fill="#8fa3c2" {o(4)}/>')
    # показывающая кисть: предмета нет, варежки нет — рукав без кисти
    s += SL(Z_SRED, f'<path d="M{m1x-22:.0f},{m1y-14:.0f} q{26:.0f},{-12:.0f}'
                    f' {46:.0f},{6:.0f}" fill="none" stroke="#ffd98a"'
                    f' stroke-width="7" opacity=".3"/>')
    s += SL(Z_SRED, _varezhka(m2x, m2y + 2, vh, t, .5))
    # нижняя треть
    s += SL(Z_SRED, _kot_zhivoy(400, pol + 54, t, 1.1, "#3b3430", .3, True, True)
            + _dvorovaya_utvar(120, pol + 52, 210, t, 919, ["korzina"])
            + _yaschiki(1880, pol + 16, t, 921, 2, .76)
            + _ploshka_s_meloch(1320, pol - 196, t, .9, 6, 923))
    s += SL(Z_SRED, teplo(1480, pol - 600, 460, 380, .34))
    s += SL(Z_PERED, _stolb_pered(-8, 104, "#1a140e", 0, H))
    s += vinetka(.44)
    return s


def chetyre_afishi_u_kinoteatra(t):
    """Афишная стена кинотеатра: четыре рисованные афиши в ряд, на каждой
    крупный предмет вместо лиц — часы с лентами и конфетти, пишущая машинка
    с очками, два саквояжа на перроне под вокзальными часами, банный веник с
    ёлочной игрушкой. Расклейщик в кепке на стремянке левой рукой держит
    край четвёртой афиши, правой разглаживает её щёткой. Внизу ведёрко с
    клеем, урна, голуби. СВОИХ БУКВ НЕТ: названия кладёт `kadr.py`."""
    rnd = random.Random(929)
    pol = 1010
    s = f'<rect width="{W}" height="{H}" fill="#3a3630"/>'
    s += SL(Z_DAL, kladka(0, 0, 1920, 820, 82, "#6a5c4c"))
    s += SL(Z_DAL, f'<rect x="0" y="820" width="{W}" height="42" rx="8"'
                   f' fill="#5e5244" {o(5)}/>')
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}"'
                   f' height="{H-pol+18:.0f}" fill="#7a7268"/>'
            + _asfalt(pol - 10, 1076, 931, 12))
    # ЧЕТЫРЕ АФИШИ, подсвечиваются по очереди
    vidy = ("chasy", "mashinka", "sakvoyazhi", "venik")
    for i, vid in enumerate(vidy):
        faza = ((t * .45 + i * .25) % 1.0)
        podsvet = max(0.0, 1.0 - abs(faza - .5) * 4)
        s += SL(Z_SRED, _afisha(60 + i * 460, 180, 420, 600, t, vid,
                                podsvet, 933 + i * 2))
    s += SL(Z_SRED, _naves_lampochki(210, 80, 1500, t, 14, 64))
    # РАСКЛЕЙЩИК на стремянке у четвёртой афиши
    s += SL(Z_SRED, _stremyanka(1560, 640, 380, t, 4))
    rx_, ry_, rh = 1560, 690, 560
    _figury_kadra((rx_, ry_, rh))
    gl = A.w(t, 1.1, .2)
    rask = figura(rx_, ry_, rh, t, col="#4e5a46", kant="#ffd98a", ph=.3,
                  naklon=4.0)
    a1, (c1x, c1y), _ = _ruka_mimo(rx_, ry_, rh, -1, rh * .40, -18, t,
                                   "#4e5a46", "#ffd98a", .2, 4.0)
    a2, (c2x, c2y), _ = _ruka_mimo(rx_, ry_, rh, -1, rh * .34,
                                   16 + 26 * gl, t, "#4e5a46", "#ffd98a",
                                   .7, 7.0)
    rask += a1 + a2
    s += SL(Z_SRED, rask)
    # КЕПКА расклейщика поверх убора
    gy_ = ry_ - rh * .845
    s += SL(Z_SRED, f'<path d="M{rx_-rh*.10:.0f},{gy_-rh*.085:.0f}'
                    f' q{rh*.10:.0f},{-rh*.075:.0f} {rh*.20:.0f},{-rh*.008:.0f}'
                    f' q{-rh*.02:.0f},{rh*.04:.0f} {-rh*.20:.0f},{rh*.008:.0f} Z"'
                    f' fill="#3d352c" {o(5)}/>'
            + f'<path d="M{rx_-rh*.12:.0f},{gy_-rh*.078:.0f} q{-rh*.05:.0f},'
              f'{rh*.012:.0f} {-rh*.055:.0f},{rh*.032:.0f}'
              f' q{rh*.05:.0f},{rh*.006:.0f} {rh*.08:.0f},{-rh*.014:.0f} Z"'
              f' fill="#2f291f" {o(3)}/>')
    # край афиши в левой кисти и ЩЁТКА в правой
    s += SL(Z_SRED, f'<path d="M{c1x:.0f},{c1y-40:.0f} L{c1x-90:.0f},{c1y-60:.0f}'
                    f' L{c1x-86:.0f},{c1y+40:.0f} L{c1x+4:.0f},{c1y+28:.0f} Z"'
                    f' fill="#3f5a3a" {o(4)}/>')
    s += SL(Z_SRED, _varezhka(c1x, c1y + 2, rh, t, .2))
    s += SL(Z_SRED, para_izo_rta(rx_ - 40, gy_ + 12, t, .4, 1.0, .5))
    s += SL(Z_SRED, _schetka_oboynaya(c2x - 40, c2y + 10, 1.0, -74, t))
    s += SL(Z_SRED, _varezhka(c2x, c2y + 4, rh, t, .7))
    # внизу ведёрко с клеем, урна, голуби
    s += SL(Z_SRED, _vederko_kleya(1420, pol + 6, 1.05, t, True))
    s += SL(Z_SRED, _gorodskoy_hlam(240, pol + 6, 300, t, 941,
                                    ["urna", "yaschik"]))
    for i, (gx_, gs, gp, hod) in enumerate(((700, 1.3, .0, True),
                                            (820, .68, .3, False),
                                            (960, 1.15, .6, True))):
        s += SL(Z_SRED, _golub(gx_, pol + 46 - i * 4, t, gs, gp, hod))
    s += SL(Z_SRED, _kucha_listev(1180, pol + 50, 260, 943, 62)
            + _luzha(520, pol + 56, 210, t, .3)
            + _skameyka_podezda(1700, pol + 6, 240, t, 150))
    s += SL(Z_SRED, teplo(960, 160, 820, 260, .26))
    s += SL(Z_LETIT, mokryy_sneg(t, 22, 945, .40, 1.3))
    s += SL(Z_PERED, _stolb_pered(-8, 112, "#241f18", 0, H))
    s += vinetka(.42)
    return s


def zhenschina_s_mandarinami_i_sneg(t):
    """Зимний вечер, двор у подъезда: фонарь, скамейка в снегу, новогодние
    огоньки в окнах. Женщина в пальто и пуховом платке идёт к подъезду — в
    правой руке сетка с мандаринами, левой поправляет платок. У подъезда
    мужчина в шапке-пирожке: в левой портфель, правой неловко протягивает
    ей оброненную варежку. Она останавливается и улыбается, у калитки позади
    блестит монетка."""
    rnd = random.Random(947)
    pol = 1016
    s = f'<rect width="{W}" height="{H}" fill="url(#nnoch)"/>'
    s += nebo("noch", t, True, 949)
    # панельные дома с новогодними огоньками
    s += SL(Z_DAL, panelka(-60, 740, 1010, t, 6, True, 951)
            + panelka(1060, 720, 920, t, 6, True, 953))
    for i in range(16):
        ox_ = 60 + (i % 8) * 230
        oy_ = 300 + (i // 8) * 160
        mig = .3 + .7 * abs(A.w(t, 1.2 + i * .06, i * .4))
        s += SL(Z_DAL, "".join(
            f'<circle cx="{ox_+j*26:.0f}" cy="{oy_+8*math.sin(j+i):.0f}" r="8"'
            f' fill="{["#e8c64e", "#d6452a", "#56763f", "#cfe4f5"][j % 4]}"'
            f' opacity="{mig:.2f}"/>' for j in range(6)))
    # подъезд с козырьком
    s += SL(Z_SRED, f'<rect x="1300" y="470" width="520" height="{pol-470:.0f}"'
                    f' rx="10" fill="{BETON2}" {o(6)}/>'
            + f'<rect x="1260" y="430" width="600" height="56" rx="12"'
              f' fill="{BETON}" {o(5)}/>'
            + dver(1420, 560, 300, pol - 560, .0, "#5a4530", True, False)
            + f'<rect x="1500" y="470" width="140" height="70" rx="10"'
              f' fill="{SVET}" opacity="{.6+.2*abs(A.w(t,2.6,.2)):.2f}"/>')
    s += SL(Z_SRED, _fonar_dvorovoy(880, pol - 10, t, 1.0, 620))
    # земля в снегу, скамейка, следы
    s += SL(Z_SRED, f'<rect x="0" y="{pol-20:.0f}" width="{W}"'
                    f' height="{H-pol+20:.0f}" fill="#6a7280"/>'
            + sneg_lezhit(pol + 10, 30)
            + _inej(955, 26, pol + 20, 1070))
    s += SL(Z_SRED, _skameyka_podezda(380, pol + 4, 330, t, 160))
    s += SL(Z_SRED, f'<path d="M370,{pol-110:.0f} q170,-34 330,-6'
                    f' q-10,36 -330,30 Z" fill="url(#sneg)" opacity=".92"/>')
    s += SL(Z_SRED, _sledy(200, 1070, 1160, pol - 10, 8, 957, "#4e5664", 1.1))
    # МОНЕТКА у калитки далеко позади
    s += SL(Z_SRED, _zabor_dosok(-30, pol - 230, 360, 210, 959, 54))
    s += SL(Z_SRED, _moneta_krupno(150, pol - 44, 34, t, .2, True, False, .8))
    s += SL(Z_SRED, f'<circle cx="150" cy="{pol-44:.0f}" r="56" fill="{SVET}"'
                    f' opacity="{.14+.14*abs(A.w(t,1.6,.3)):.2f}"/>')
    # ДВЕ ФИГУРЫ: женщина идёт, мужчина протягивает варежку
    hod = A.ease(A.seg(t, .3, 3.0))
    zx = 620 + 180 * hod
    zy, zh = pol + 2, 760
    mx, my, mh = 1340, pol + 2, 780
    _figury_kadra((zx, zy, zh), (mx, my, mh))
    prot = A.ease(A.seg(t, 1.6, 1.6))
    ulyb = A.ease(A.seg(t, 3.4, 1.2))
    zhen = figura(zx, zy, zh, t, col="#54505e", kant="#cfe4f5", platok=True,
                  ph=.3, naklon=3.0 - 1.5 * ulyb)
    r1, (n1x, n1y), _ = _ruka_mimo(zx, zy, zh, 1, zh * .34, 48, t,
                                   "#54505e", "#cfe4f5", .2, 5.0)
    r2, (n2x, n2y), _ = _ruka_so_sgibom(zx, zy, zh, -1, zh * .20, -30,
                                        zh * .18, -52, t, "#54505e",
                                        "#cfe4f5", .7, 4.0)
    zhen += r1 + r2
    s += SL(Z_SRED, zhen)
    # ПУХОВЫЙ ПЛАТОК пушистой кромкой и улыбка уголком
    gyz = zy - zh * .845
    s += SL(Z_SRED, "".join(
        f'<circle cx="{zx+math.cos(math.radians(a)) * zh * .160:.0f}"'
        f' cy="{gyz+math.sin(math.radians(a)) * zh * .160:.0f}"'
        f' r="{zh*.020:.0f}" fill="#e8e2d6" opacity=".9"/>'
        for a in range(150, 391, 22)))
    s += SL(Z_SRED, f'<path d="M{zx-zh*.03:.0f},{gyz+zh*.040:.0f}'
                    f' q{zh*.03:.0f},{zh*.012+zh*.012*ulyb:.0f}'
                    f' {zh*.06:.0f},{-zh*.004*ulyb:.0f}" fill="none"'
                    f' stroke="{K}" stroke-width="{zh*.009:.0f}"'
                    f' stroke-linecap="round"/>')
    s += SL(Z_SRED, _setka_mandarinov(n1x + 20, n1y + 30, 1.0, t, .3, 7))
    s += SL(Z_SRED, _varezhka(n1x, n1y + 4, zh, t, .2))
    s += SL(Z_SRED, para_izo_rta(zx + 36, gyz + 12, t, .4, 1.0, .55))
    muzh = figura(mx, my, mh, t, col="#3f4a58", kant="#cfe4f5", ph=.7,
                  naklon=4.0)
    p1, (q1x, q1y), _ = _ruka_mimo(mx, my, mh, -1, mh * .30, 50, t,
                                   "#3f4a58", "#cfe4f5", .1, 4.0)
    p2, (q2x, q2y), _ = _ruka_mimo(mx, my, mh, -1, mh * .42,
                                   34 - 30 * prot, t, "#3f4a58",
                                   "#cfe4f5", .6, 5.0)
    muzh += p1 + p2
    s += SL(Z_SRED, muzh)
    # ШАПКА-ПИРОЖОК поверх убора
    gym = my - mh * .845
    s += SL(Z_SRED, f'<path d="M{mx-mh*.105:.0f},{gym-mh*.055:.0f}'
                    f' L{mx+mh*.105:.0f},{gym-mh*.055:.0f}'
                    f' L{mx+mh*.095:.0f},{gym-mh*.135:.0f}'
                    f' L{mx-mh*.095:.0f},{gym-mh*.135:.0f} Z" fill="#3d352c"'
                    f' {o(5)}/>'
            + f'<ellipse cx="{mx:.0f}" cy="{gym-mh*.135:.0f}"'
              f' rx="{mh*.095:.0f}" ry="{mh*.020:.0f}" fill="#4a4036" {o(3)}/>')
    s += SL(Z_SRED, _portfel(q1x - 40, q1y + 110, .82, t, -8))
    s += SL(Z_SRED, _varezhka(q1x, q1y + 6, mh, t, .1))
    # ОБРОНЕННАЯ ВАРЕЖКА, которую он протягивает: лежит в кисти внахлёст
    s += SL(Z_SRED, f'<g transform="rotate({-18 + 10 * prot:.1f} {q2x:.0f} {q2y:.0f})">'
                    f'<path d="M{q2x-54:.0f},{q2y-6:.0f} q{-8:.0f},{-46:.0f}'
                    f' {30:.0f},{-52:.0f} q{44:.0f},{-4:.0f} {52:.0f},{34:.0f}'
                    f' q{6:.0f},{26:.0f} {-16:.0f},{30:.0f} Z" fill="#b8323a"'
                    f' {o(5)}/>'
                    f'<path d="M{q2x-50:.0f},{q2y-16:.0f} q{52:.0f},{-16:.0f}'
                    f' {96:.0f},{6:.0f}" fill="none" stroke="#efe3c8"'
                    f' stroke-width="11"/>'
                    f'<path d="M{q2x+36:.0f},{q2y-40:.0f} q{26:.0f},{-6:.0f}'
                    f' {30:.0f},{14:.0f} q{-16:.0f},{14:.0f} {-34:.0f},{6:.0f} Z"'
                    f' fill="#b8323a" {o(4)}/></g>')
    s += SL(Z_SRED, _varezhka(q2x, q2y + 4, mh, t, .6))
    s += SL(Z_SRED, para_izo_rta(mx - 38, gym + 12, t, .8, 1.0, .5))
    # нижняя треть
    s += SL(Z_SRED, _gorodskoy_hlam(1760, pol + 6, 160, t, 961, ["urna"])
            + _snegovik(240, pol + 20, .66, t)
            + _kot_zhivoy(1060, pol + 46, t, 1.0, "#3b3430", .4))
    s += SL(Z_LETIT, mokryy_sneg(t, 44, 963, .78, .7))
    s += SL(Z_SRED, teplo(946, pol - 640, 420, 360, .36))
    s += SL(Z_PERED, _vetka_pered(-40, 140, 520, 22, t, 965, "#141017", 6))
    s += vinetka(.46)
    return s


def kassa_starogo_kinoteatra(t):
    """Фасад кинотеатра двадцатых: навес с бегущими лампочками, окошко кассы
    крупно, рулон билетов, табличка с годом (поле под год пустое — цифры
    кладёт `kadr.py`). Кассирша в шляпке-колоколе правой рукой отрывает
    билет, левой придерживает рулон. Мальчик в кепке-восьмиклинке стоит на
    цыпочках и правой кладёт на блюдце монетку, левой держит леденец."""
    rnd = random.Random(967)
    pol = 1012
    s = f'<rect width="{W}" height="{H}" fill="#2a2420"/>'
    s += SL(Z_DAL, kladka(0, 0, 1920, 860, 84, "#7a6a56"))
    s += SL(Z_DAL, f'<rect x="0" y="856" width="{W}" height="40" rx="8"'
                   f' fill="#6a5c4c" {o(5)}/>')
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}"'
                   f' height="{H-pol+18:.0f}" fill="#8a7f70"/>'
            + _bulyzhnik(pol - 10, 1076, 969, 84))
    s += SL(Z_SRED, _naves_lampochki(200, 110, 1520, t, 14, 66))
    # пилястры фасада по краям — ближний объём
    for px in (60, 1740):
        s += SL(Z_SRED, f'<rect x="{px:.0f}" y="190" width="120"'
                        f' height="{pol-190:.0f}" rx="8" fill="#8a7a66" {o(6)}/>'
                + "".join(f'<line x1="{px+22+i*26:.0f}" y1="220"'
                          f' x2="{px+22+i*26:.0f}" y2="{pol-20:.0f}"'
                          f' stroke="#6a5c4c" stroke-width="7" opacity=".7"/>'
                          for i in range(4)))
    # ГЛАВНЫЙ ПРЕДМЕТ: окошко кассы
    otryv = A.ease(A.seg(t, .5, 1.2))
    s += SL(Z_SRED, _okoshko_kassy(620, 330, 620, 400, t, otryv))
    s += SL(Z_SRED, _tablichka_bez_cifr(1340, 330, 300, 150, t, .2))
    s += SL(Z_SRED, _afisha(220, 330, 330, 470, t, "chasy", .4, 971))
    # ДВЕ ФИГУРЫ: кассирша в окошке и мальчик перед ним
    kx, ky, kh = 980, 1050, 620
    bx, by_, bh = 1480, pol, 430
    _figury_kadra((kx, ky, kh), (bx, by_, bh))
    cyp = A.ease(A.seg(t, .8, 1.0))
    kass = figura(kx, ky, kh, t, col="#8a4a5c", kant="#ffd98a", ph=.3,
                  naklon=3.0)
    a1, (d1x, d1y), _ = _ruka_mimo(kx, ky, kh, 1, kh * .34, 42 - 14 * otryv, t,
                                   "#8a4a5c", "#ffd98a", .2, 4.0)
    a2, (d2x, d2y), _ = _ruka_mimo(kx, ky, kh, -1, kh * .30, 48, t,
                                   "#8a4a5c", "#ffd98a", .7, 4.0)
    kass += a1 + a2
    s += SL(Z_SRED, kass)
    # ШЛЯПКА-КОЛОКОЛ поверх убора
    gyk = ky - kh * .845
    s += SL(Z_SRED, f'<path d="M{kx-kh*.11:.0f},{gyk+kh*.012:.0f}'
                    f' q{-kh*.012:.0f},{-kh*.13:.0f} {kh*.11:.0f},{-kh*.14:.0f}'
                    f' q{kh*.12:.0f},{kh*.01:.0f} {kh*.11:.0f},{kh*.14:.0f}'
                    f' q{-kh*.11:.0f},{kh*.03:.0f} {-kh*.22:.0f},0 Z"'
                    f' fill="#5a2c3c" {o(5)}/>'
            + f'<path d="M{kx-kh*.085:.0f},{gyk-kh*.055:.0f} q{kh*.085:.0f},'
              f'{kh*.016:.0f} {kh*.17:.0f},0" fill="none" stroke="{ZOL}"'
              f' stroke-width="{kh*.016:.0f}"/>')
    s += SL(Z_SRED, _varezhka(d1x, d1y + 2, kh, t, .2)
            + _varezhka(d2x, d2y + 2, kh, t, .7))
    # мальчик на цыпочках
    mal = figura(bx, by_ - 16 * cyp, bh, t, col="#4a5a72", kant="#ffd98a",
                 ph=.7, naklon=4.0)
    p1, (e1x, e1y), _ = _ruka_mimo(bx, by_ - 16 * cyp, bh, -1, bh * .46,
                                   -16 - 14 * cyp, t, "#4a5a72",
                                   "#ffd98a", .1, 5.0)
    p2, (e2x, e2y), _ = _ruka_mimo(bx, by_ - 16 * cyp, bh, 1, bh * .34, 46, t,
                                   "#4a5a72", "#ffd98a", .6, 4.0)
    mal += p1 + p2
    s += SL(Z_SRED, mal)
    # КЕПКА-ВОСЬМИКЛИНКА поверх убора: клинья сходятся к пуговке
    gyb = by_ - 16 * cyp - bh * .845
    s += SL(Z_SRED, f'<path d="M{bx-bh*.115:.0f},{gyb-bh*.055:.0f}'
                    f' q{bh*.115:.0f},{-bh*.10:.0f} {bh*.23:.0f},{-bh*.008:.0f}'
                    f' q{-bh*.02:.0f},{bh*.05:.0f} {-bh*.23:.0f},{bh*.008:.0f} Z"'
                    f' fill="#3f4a58" {o(5)}/>'
            + "".join(f'<line x1="{bx:.0f}" y1="{gyb-bh*.095:.0f}"'
                      f' x2="{bx+bh*.115*math.cos(math.radians(a)):.0f}"'
                      f' y2="{gyb-bh*.05+bh*.03*math.sin(math.radians(a)):.0f}"'
                      f' stroke="#2f3a48" stroke-width="{bh*.009:.0f}"/>'
                      for a in range(160, 381, 28))
            + f'<circle cx="{bx:.0f}" cy="{gyb-bh*.098:.0f}" r="{bh*.015:.0f}"'
              f' fill="#2f3a48" {o(3)}/>')
    # ЦЫПОЧКИ: пятки приподняты, носки на мостовой — опора названа
    s += SL(Z_SRED, "".join(
        f'<path d="M{bx+i*bh*.09-bh*.045:.0f},{by_-bh*.02:.0f}'
        f' q{bh*.045:.0f},{bh*.03:.0f} {bh*.09:.0f},{-bh*.005:.0f}'
        f' l{0:.0f},{bh*.02:.0f} l{-bh*.09:.0f},0 Z" fill="#3b2f26" {o(3)}/>'
        for i in (-1, 1)))
    # МОНЕТКА ложится на блюдце, ЛЕДЕНЕЦ в другой кисти
    s += SL(Z_SRED, _moneta_krupno(e1x - 10, e1y + 24 + 18 * cyp, 26, t, .3,
                                   True, True, .5))
    s += SL(Z_SRED, _varezhka(e1x, e1y + 4, bh, t, .1))
    s += SL(Z_SRED, para_izo_rta(bx + 34, gyb + 14, t, .5, .9, .5))
    s += SL(Z_SRED, _ledenec(e2x + 26, e2y - 36, .92, t, .4))
    s += SL(Z_SRED, _varezhka(e2x, e2y + 4, bh, t, .6))
    # нижняя треть
    s += SL(Z_SRED, _gorodskoy_hlam(300, pol + 6, 280, t, 973,
                                    ["urna", "yaschik"])
            + _golub(760, pol + 46, t, 1.2, .2, True)
            + _golub(860, pol + 52, t, .66, .6, False)
            + _kucha_listev(1700, pol + 48, 240, 975, 60)
            + _luzha(1180, pol + 54, 200, t, .3))
    s += SL(Z_SRED, teplo(960, 190, 820, 280, .30))
    s += SL(Z_LETIT, mokryy_sneg(t, 20, 977, .40, 1.2))
    s += SL(Z_PERED, _stolb_pered(1898, 108, "#1d1812", 0, H))
    s += vinetka(.44)
    return s


def ekran_s_parohodom(t):
    """Зал того же кинотеатра: белый экран крупно, на нём настоящий кадр со
    старинным колёсным пароходом. Перед экраном тапёр за пианино — обе руки
    на клавишах, — и ряды детских затылков в кепках и бантах: дети
    подпрыгивают на местах. Самого персонажа в кадре нет."""
    rnd = random.Random(977)
    pol = 1014
    s = f'<rect width="{W}" height="{H}" fill="#170f12"/>'
    s += SL(Z_DAL, f'<rect x="0" y="0" width="{W}" height="{pol:.0f}"'
                   f' fill="#2a1820"/>'
            + kladka(0, 30, 420, 640, 74, "#4a2a34")
            + kladka(1500, 30, 420, 640, 74, "#4a2a34"))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-16:.0f}" width="{W}"'
                   f' height="{H-pol+16:.0f}" fill="#3a2028"/>'
            + _pol_shvy(pol - 6, 1074, 979, 6, "#2a151c"))
    # НАСТОЯЩИЙ КАДР на экране: рисованный вид, метка, обвязка поверх
    px, py, pw, ph_ = 500, 110, 920, 430
    put = kontur_proema(px, py, pw, ph_, "pryam")
    vid = (f'<path d="{put}" fill="#8a8f92"/>'
           f'<rect x="{px:.0f}" y="{py+ph_*.60:.0f}" width="{pw:.0f}"'
           f' height="{ph_*.40:.0f}" fill="#6a7276"/>')
    hod = (t * 36.0) % (pw + 300) - 150
    vid += (f'<path d="M{px+hod:.0f},{py+ph_*.70:.0f} l{300:.0f},0'
            f' l{-30:.0f},{70:.0f} l{-240:.0f},0 Z" fill="#3d4246" {o(5)}/>'
            f'<rect x="{px+hod+60:.0f}" y="{py+ph_*.48:.0f}" width="{180:.0f}"'
            f' height="{ph_*.22:.0f}" rx="6" fill="#55595c" {o(4)}/>'
            f'<circle cx="{px+hod+150:.0f}" cy="{py+ph_*.78:.0f}" r="42"'
            f' fill="none" stroke="#2f3336" stroke-width="12"/>')
    for i in (0, 1):
        vid += (f'<rect x="{px+hod+90+i*70:.0f}" y="{py+ph_*.22:.0f}"'
                f' width="26" height="{ph_*.28:.0f}" rx="5" fill="#2f3336"/>')
        vid += dym(px + hod + 103 + i * 70, py + ph_ * .20, t, 4, .30, 200,
                   .34, "#b9c0c4", 1.2)
    for i in range(5):
        vid += (f'<path d="M{px+40:.0f},{py+ph_*(.84+i*.03):.0f}'
                f' q{pw*.25:.0f},{-8 - 5 * A.w(t, 1.6, i * .3):.0f}'
                f' {pw*.46:.0f},0 q{pw*.22:.0f},{8:.0f} {pw*.42:.0f},{-4:.0f}"'
                f' fill="none" stroke="#9aa3a8" stroke-width="7" opacity=".6"/>')
    s += SL(Z_SRED, vid + mesto_stoka(px, py, pw, ph_, "pryam"))
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#d8d2c4"'
                    f' stroke-width="30"/>'
            + "".join(f'<circle cx="{px+24+i*(pw-48)/13.0:.0f}" cy="{py+6:.0f}"'
                      f' r="6" fill="#9aa3aa"/>' for i in range(14))
            + "".join(f'<circle cx="{px+24+i*(pw-48)/13.0:.0f}"'
                      f' cy="{py+ph_-6:.0f}" r="6" fill="#9aa3aa"/>'
                      for i in range(14)))
    for e, sg in ((px - 20, -1), (px + pw + 20, 1)):
        for i in range(5):
            s += SL(Z_SRED, f'<path d="M{e+sg*i*36:.0f},{py-40:.0f}'
                            f' q{sg*28:.0f},{ph_*.5:.0f} {sg*4:.0f},{ph_+60:.0f}'
                            f' l{sg*34:.0f},0 q{sg*22:.0f},{-ph_*.5:.0f}'
                            f' {-sg*2:.0f},{-ph_-60:.0f} Z" fill="#3a1e26"'
                            f' opacity="{.9-i*.09:.2f}" {o(3)}/>')
    # ЛУЧ ПРОЕКТОРА дрожит
    s += SL(Z_LETIT, f'<g transform="rotate({8 + .8 * A.w(t, 9.0, .2):.1f}'
                     f' 1820 240)">'
            + _konus_sveta(1820, 240, 520, 740, 0.0, .26, "#ffd98a") + "</g>")
    rnd2 = random.Random(981)
    for i in range(22):
        p = ((t * .24 + rnd2.random()) % 1.0)
        s += SL(Z_LETIT, f'<circle cx="{1760-p*900+rnd2.uniform(-60,60):.0f}"'
                         f' cy="{300+p*380+rnd2.uniform(-60,60):.0f}"'
                         f' r="{rnd2.uniform(2.5,5.5):.0f}" fill="#ffeec2"'
                         f' opacity="{.22+.4*abs(A.w(t,1.6,i*.2)):.2f}"/>')
    # ПИАНИНО и ТАПЁР — главный человек плана, обе руки на клавишах
    s += SL(Z_SRED, _pianino(180, 980, 520, t, 330, 1.0))
    tx_, ty_, th = 450, 952, 520
    deti = []
    s_zat, poz = _zatylki_ryad(620, pol + 10, 1200, t, 7, 983, 300, 0)
    _figury_kadra(*([(tx_, ty_, th)] + [(p[0], p[1], p[2]) for p in poz]))
    s_zat, poz = _zatylki_ryad(620, pol + 10, 1200, t, 7, 983, 300, 0)
    s += SL(Z_SRED, _tabyret(tx_ + 30, ty_ + 6, t, 150, 160))
    tap = figura(tx_, ty_, th, t, col="#3d352c", kant="#ffd98a", ph=.3,
                 profil=True, naklon=5.0)
    r1, (f1x, f1y), _ = _ruka_mimo(tx_, ty_, th, -1, th * .34, 40, t,
                                   "#3d352c", "#ffd98a", .2, 7.0)
    r2, (f2x, f2y), _ = _ruka_mimo(tx_, ty_, th, -1, th * .28, 56, t,
                                   "#3d352c", "#ffd98a", .7, 8.0)
    tap += r1 + r2
    s += SL(Z_SRED, tap)
    # кисти тапёра на клавишах: варежки перекрывают клавиатуру внахлёст
    s += SL(Z_SRED, _varezhka(f1x, f1y + 2, th, t, .2)
            + _varezhka(f2x, f2y + 2, th, t, .7))
    # РЯДЫ ДЕТСКИХ ЗАТЫЛКОВ: со спины, рост через одного, шаг рваный
    s += SL(Z_SRED, s_zat)
    s_zat2, _ = _zatylki_ryad(520, pol + 70, 1400, t, 8, 985, 230, 1)
    s += SL(Z_SRED, s_zat2)
    # нижняя треть
    s += SL(Z_SRED, _polovik(1000, pol + 46, 720, 120, "#8a2a40", "#5a1626")
            + _kucha_listev(1780, pol + 50, 220, 987, 56)
            + _dvorovaya_utvar(100, pol + 48, 190, t, 989, ["vedro"]))
    s += SL(Z_SRED, svecha(120, pol - 230, t, .4, 1.1, 100)
            + teplo(130, pol - 290, 230, 200, .32))
    s += SL(Z_SRED, blik(1820, 240, t, 1.2, "#bcd8ff", "#ffd98a", .45))
    s += SL(Z_PERED, _stolb_pered(-8, 118, "#140a0e", 0, H))
    s += vinetka(.50)
    return s


def imeninnyy_tort_na_sto_svechey(t):
    """Стол с огромным именинным тортом крупно: лес свечек гаснет рядами, на
    стуле у торта колпак именинника и маленький рисованный штурвал. Дед в
    очках сидит за столом, обе руки на набалдашнике трости. Внук стоит на
    стуле коленями, обеими руками упирается в стол и дует на свечи. Цифры на
    торте не рисуем — их кладёт `kadr.py`."""
    rnd = random.Random(991)
    pol = 1014
    s = f'<rect width="{W}" height="{H}" fill="#2b2218"/>'
    s += SL(Z_DAL, _stena_gornicy(t, 993, True, 720, True))
    s += SL(Z_DAL, _ramki_na_stene(140, 140, 440, t, 995, 3)
            + _polka_s_utvaryu(1400, 160, 460, t, 997, 4))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}"'
                   f' height="{H-pol+18:.0f}" fill="#5e4a34"/>'
            + polovicy(pol + 14) + _pol_shvy(pol + 16, 1074, 999, 6, "#4a3824"))
    # СТОЛ с тортом
    s += SL(Z_SRED, f'{ten(960, pol + 16, 640, 26, .5)}'
                    f'<rect x="140" y="760" width="1500" height="54" rx="12"'
                    f' fill="url(#derev)" {o(8)}/>'
            + f'<rect x="170" y="814" width="1440" height="26" rx="9"'
              f' fill="#5b4428" {o(5)}/>')
    for px in (250, 1480):
        s += SL(Z_SRED, f'<rect x="{px:.0f}" y="840" width="70"'
                        f' height="{pol-840:.0f}" rx="12" fill="#5b4428"'
                        f' {o(6)}/>')
    s += SL(Z_SRED, _rushnik_vyshityy(160, 744, 900, 84, t, 1001))
    # ГЛАВНЫЙ ПРЕДМЕТ: торт со свечами, они гаснут рядами
    gasnet = A.ease(A.seg(t, 1.2, 2.2))
    s += SL(Z_SRED, _tort_svechi(700, 752, 560, t, gasnet, 3))
    # стул с колпаком и штурвалом вместо персонажа
    s += SL(Z_SRED, _venskiy_stul(1230, pol, 430, t, -6, False))
    s += SL(Z_SRED, _kolpak_imeninnika(1180, pol - 250, 1.0, t, .2))
    s += SL(Z_SRED, _shturval(1300, pol - 300, .9, t))
    # сопутствующие вещи стола
    s += SL(Z_SRED, _kruzhka(370, 752, 1.05, 0, "#e8eef0", 1)
            + _tarelka(1420, 730, 70, t, .3, False, 0, "#eef2f4")
            + _samovar(1560, 752, t, .82))
    s += SL(Z_SRED, svecha(1380, 748, t, .4, 1.15, 110)
            + teplo(1380, 690, 260, 220, .34))
    # ДВЕ ФИГУРЫ: дед за столом и внук на стуле коленями
    dx_, dy_, dh = 1680, pol - 150, 580
    vx, vy, vh = 420, pol - 180, 430
    _figury_kadra((dx_, dy_, dh), (vx, vy, vh))
    duet = A.ease(A.seg(t, .5, 1.0))
    razv = A.ease(A.seg(t, 3.4, 1.2))
    ded = figura(dx_, dy_, dh, t, col="#54505e", kant="#ffd98a", ph=.3,
                 boroda=True, naklon=4.0)
    r1, (k1x, k1y), _ = _ruka_mimo(dx_, dy_, dh, -1, dh * .32,
                                   44 - 46 * razv, t, "#54505e",
                                   "#ffd98a", .2, 4.0)
    r2, (k2x, k2y), _ = _ruka_sgib_mimo(dx_, dy_, dh, -1, dh * .22, 22,
                                        dh * .22, 48 - 40 * razv, t,
                                        "#54505e", "#ffd98a", .7, 4.0)
    ded += r1 + r2
    s += SL(Z_SRED, ded)
    s += SL(Z_SRED, _ochki(dx_ - 4, dy_ - dh * .845, 1.1, t))
    # ТРОСТЬ: обе кисти на набалдашнике, пока дед не развёл руками
    if razv < .3:
        s += SL(Z_SRED, _trost_nabaldashnik((k1x + k2x) * .5 - 10,
                                            pol - 4, .9, t, 280))
        s += SL(Z_SRED, _varezhka(k1x, k1y + 2, dh, t, .2)
                + _varezhka(k2x, k2y + 2, dh, t, .7))
    else:
        s += SL(Z_SRED, _trost_nabaldashnik(1560, pol - 4, .9, t, 280))
    vnuk = figura(vx, vy, vh, t, col="#4a5a72", kant="#ffd98a", ph=.7,
                  naklon=7.0)
    p1, (m1x, m1y), _ = _ruka_mimo(vx, vy, vh, 1, vh * .44, 28 + 14 * duet, t,
                                   "#4a5a72", "#ffd98a", .1, 4.0)
    p2, (m2x, m2y), _ = _ruka_mimo(vx, vy, vh, 1, vh * .38, 48 + 10 * duet, t,
                                   "#4a5a72", "#ffd98a", .6, 4.0)
    vnuk += p1 + p2
    s += SL(Z_SRED, _venskiy_stul(400, pol, 420, t, 4, True))
    s += SL(Z_SRED, vnuk)
    # колени на сиденье стула — опора названа
    s += SL(Z_SRED, f'<path d="M{vx-vh*.18:.0f},{vy-vh*.04:.0f}'
                    f' q{vh*.18:.0f},{vh*.07:.0f} {vh*.36:.0f},0'
                    f' q{-vh*.09:.0f},{vh*.05:.0f} {-vh*.36:.0f},0 Z"'
                    f' fill="#3f5c7a" {o(4)}/>')
    # ДУНОВЕНИЕ: струи воздуха от лица внука к свечам
    gyv = vy - vh * .845
    for i in range(3):
        p = ((t * 1.5 + i / 3.0) % 1.0)
        s += SL(Z_LETIT, f'<path d="M{vx+vh*.14:.0f},{gyv+vh*.05+i*16:.0f}'
                         f' q{120+p*120:.0f},{-20+i*14:.0f}'
                         f' {240+p*200:.0f},{-6+i*10:.0f}" fill="none"'
                         f' stroke="#cfe4f5" stroke-width="{9-3*i:.0f}"'
                         f' opacity="{(1-p)*.6*duet:.2f}"/>')
    s += SL(Z_SRED, _varezhka(m1x, m1y + 2, vh, t, .1)
            + _varezhka(m2x, m2y + 2, vh, t, .6))
    # нижняя треть
    s += SL(Z_SRED, _polovik(960, pol + 42, 620, 120, "#cdbf9c", "#b8352c")
            + _dvorovaya_utvar(130, pol + 50, 220, t, 1003, ["korzina"])
            + _kot_zhivoy(1060, pol + 54, t, 1.1, "#3b3430", .3)
            + _yaschiki(1840, pol + 14, t, 1005, 2, .78)
            + kartoshka(700, pol + 58, t, 7, 1007, 1.0))
    s += SL(Z_SRED, teplo(700, 640, 520, 380, .40))
    s += SL(Z_PERED, _stolb_pered(-8, 110, "#1a120c", 0, H))
    s += vinetka(.44)
    return s


def chetyre_chuzhih_veschi_na_doroge(t):
    """Осенняя дорога к дому: в ряд лежат четыре вещи — блестящая монета,
    растрёпанный веник с красной тряпицей, серый мешок-забота с хмурой
    рожицей и зелёная змейка-зависть кольцом. Бабушка в платке идёт по
    дороге: в правой руке бидон, левой придерживает платок. Она по очереди
    перешагивает или обходит все четыре и идёт к своей калитке, не
    оглядываясь."""
    rnd = random.Random(1009)
    gor = 700
    s = f'<rect width="{W}" height="{H}" fill="url(#nsumer)"/>'
    s += nebo("sumer", t, False, 1011)
    s += oblaka(t, 160, 6, 1013, .42, "#cdd7e4", 12.0)
    s += SL(Z_DAL, _derevnya_ryad(gor - 140, t, 1015, ((150, 300), (1700, 330))))
    s += SL(Z_DAL, goloe_derevo(420, gor - 30, 520, t, 1017, 9, "#3a3b43", True)
            + goloe_derevo(1280, gor - 10, 460, t, 1019, 8, "#3a3b43", True))
    s += SL(Z_DAL, pleten(-20, gor - 190, 560, 180, 9))
    # КАЛИТКА своего двора, к которой она идёт
    s += SL(Z_SRED, _zabor_dosok(1120, gor - 180, 800, 180, 1021, 54))
    s += SL(Z_SRED, _stena_ambara(100, gor - 300, 560, 320, t, True, 1043))
    s += SL(Z_SRED, _stennoe_hozyaystvo(200, gor - 240, t, 1045))
    s += SL(Z_DAL, izba_snaruzhi(900, gor + 20, 640, t, True, True, 1047))
    s += SL(Z_SRED, _stog(700, gor + 80, .82, t, True))
    s += SL(Z_SRED, _kalitka_hlopaet(1700, gor + 130, 200, 270, t, True))
    s += SL(Z_DAL, izba_snaruzhi(1760, gor + 60, 420, t, True, True, 1023))
    # ЗЕМЛЯ и ДОРОГА, уходящая к калитке
    s += SL(Z_SRED, f'<rect x="0" y="{gor+40:.0f}" width="{W}"'
                    f' height="{H-gor-40:.0f}" fill="#4e4638"/>'
            + _zemlya_faktura(gor + 80, 1072, 1025, 18, "#3c3529")
            + _listya(1027, 40, gor + 90, 1070))
    s += SL(Z_SRED, f'<path d="M-40,1072 Q560,900 1680,{gor+120:.0f}'
                    f' L1860,{gor+150:.0f} Q700,960 420,1076 Z"'
                    f' fill="#6a6050" {o(5)}/>'
            + _koleya(1000, 1029, 2))
    # ЧЕТЫРЕ ЧУЖИЕ ВЕЩИ в ряд по дороге
    s += SL(Z_SRED, _moneta_krupno(300, 1016, 56, t, .2, True, True, .78))
    s += SL(Z_SRED, f'<circle cx="300" cy="1016" r="92" fill="{SVET}"'
                    f' opacity="{.12+.14*abs(A.w(t,1.5,.2)):.2f}"/>')
    s += SL(Z_SRED, _venik(700, 978, 300, t, "#9c8a62", "#b8352c", True,
                           .82, .3, .92, 1031))
    s += SL(Z_SRED, _meshok_zabota(1090, 952, .96, t,
                                   A.ease(A.seg(t, 2.6, 1.2))))
    s += SL(Z_SRED, _zmeyka_zavisti(1420, 912, t, 1.25,
                                    A.ease(A.seg(t, 3.6, 1.4))))
    # ОДНА ФИГУРА: бабушка идёт мимо, перешагивая вещи
    hod = A.ease(A.seg(t, .3, 4.4))
    bx = 240 + 980 * hod
    by_ = 1040 - 160 * hod
    bh = 790 - 190 * hod
    shag = 16 * A.w(t, 1.1, .2)
    _figury_kadra((bx, by_, bh))
    bab = figura(bx, by_ - abs(shag) * .5, bh, t, col="#54505e",
                 kant="#cfe4f5", platok=True, ph=.3, naklon=4.0)
    r1, (n1x, n1y), _ = _ruka_mimo(bx, by_ - abs(shag) * .5, bh, 1,
                                   bh * .34, 50, t, "#54505e", "#cfe4f5",
                                   .2, 5.0)
    r2, (n2x, n2y), _ = _ruka_so_sgibom(bx, by_ - abs(shag) * .5, bh, -1,
                                        bh * .20, -28, bh * .18, -50, t,
                                        "#54505e", "#cfe4f5", .7, 4.0)
    bab += r1 + r2
    s += SL(Z_SRED, bab)
    s += SL(Z_SRED, _bidon(n1x + 24, n1y + 110, .68 * bh / 790.0, t, 4))
    s += SL(Z_SRED, _varezhka(n1x, n1y + 4, bh, t, .2))
    s += SL(Z_SRED, _varezhka(n2x, n2y + 2, bh, t, .7))
    s += SL(Z_SRED, para_izo_rta(bx + 34, by_ - bh * .80, t, .4, 1.0, .5))
    # нижняя треть
    s += SL(Z_SRED, _sledy(180, 1072, bx - 90, by_ + 10, 7, 1033,
                           "#352f24", 1.1)
            + _kucha_listev(900, 1056, 300, 1035, 72)
            + _luzha(520, 1050, 220, t, .3)
            + _polenica(60, 1046, 260, 190, 1037, 25)
            + _podorozhnik(1240, 1058, 1.1, t, .3, 5, "#6f7a44"))
    s += SL(Z_SRED, dym(1860, gor - 180, t, 5, .28, 300, .34, "#cfd6de", 1.5))
    s += SL(Z_SRED, _vorona(1120, gor - 300, t, .82, .3, .5))
    s += SL(Z_LETIT, mokryy_sneg(t, 22, 1039, .44, 1.1))
    s += SL(Z_PERED, _vetka_pered(-40, 150, 580, 26, t, 1041, "#241c16", 7))
    s += vinetka(.44)
    return s


def tri_devichih_gadaniya(t):
    """Девичья комната, стол у окна и три гадания: ромашка в стакане с
    облетевшими лепестками; шапка, полная свёрнутых бумажек с именами —
    девушка правой рукой тянет одну, левой держит шапку; окно, в котором
    виден первый встречный прохожий в шляпе. К концу на столе проступает
    свадебная карточка в рамке, где она уже седая и улыбается."""
    rnd = random.Random(1049)
    pol = 1014
    s = f'<rect width="{W}" height="{H}" fill="#2a2320"/>'
    s += SL(Z_DAL, _stena_gornicy(t, 1051, True, 720, True))
    s += SL(Z_DAL, _polka_s_utvaryu(100, 150, 440, t, 1053, 4)
            + _ramki_na_stene(600, 130, 380, t, 1055, 3))
    # девичья комната обжита: коврик на стене, полка с мелочью, сундук
    s += SL(Z_DAL, _kover_na_stene(420, 330, 560, 340, t, 1067))
    s += SL(Z_DAL, _polka_s_utvaryu(1020, 200, 420, t, 1091, 5))
    s += SL(Z_SRED, _yaschiki(200, 1014, t, 1093, 3, .96))
    s += SL(Z_DAL, f'<rect x="0" y="{pol-18:.0f}" width="{W}"'
                   f' height="{H-pol+18:.0f}" fill="#5e4a34"/>'
            + polovicy(pol + 14) + _pol_shvy(pol + 16, 1074, 1057, 6, "#4a3824"))
    # ОКНО с первым встречным прохожим в шляпе
    pro = ((t * .14) % 1.0)
    vid = (f'<rect x="1300" y="180" width="540" height="440" fill="{SUMER}"/>'
           + "".join(f'<rect x="{1340+i*110:.0f}" y="420" width="62"'
                     f' height="50" rx="5" fill="{SVET}"'
                     f' opacity="{.4+.25*abs(A.w(t,2.4,i*.4)):.2f}"/>'
                     for i in range(4))
           + f'<rect x="1300" y="470" width="540" height="150" fill="{SNEG}"'
             f' opacity=".7"/>')
    ppx = 1320 + pro * 480
    vid += (f'<path d="M{ppx-34:.0f},{600:.0f} q{34:.0f},{-14:.0f} {68:.0f},0'
            f' L{ppx+22:.0f},{470:.0f} L{ppx-22:.0f},{470:.0f} Z"'
            f' fill="#3f4a58" {o(5)}/>'
            f'<circle cx="{ppx:.0f}" cy="{448:.0f}" r="26" fill="#e8d8c0"'
            f' {o(4)}/>'
            f'<path d="M{ppx-36:.0f},{432:.0f} q{36:.0f},{-14:.0f} {72:.0f},0'
            f' q{-10:.0f},{10:.0f} {-72:.0f},0 Z" fill="#2f3a48" {o(4)}/>'
            f'<rect x="{ppx-20:.0f}" y="{400:.0f}" width="40" height="34"'
            f' rx="6" fill="#2f3a48" {o(4)}/>')
    s += SL(Z_DAL, okno_izby(1300, 180, 540, 440, t, vid, .16, False, True))
    s += SL(Z_SRED, zanaveska(1320, 190, 240, 130, None, t, 1)
            + zanaveska(1820, 190, 240, 130, None, t, -1))
    # СТОЛ У ОКНА
    s += SL(Z_SRED, f'{ten(760, pol + 16, 540, 24, .5)}'
                    f'<rect x="200" y="760" width="1180" height="52" rx="12"'
                    f' fill="url(#derev)" {o(8)}/>'
            + f'<rect x="230" y="812" width="1120" height="26" rx="9"'
              f' fill="#5b4428" {o(5)}/>')
    for px in (300, 1230):
        s += SL(Z_SRED, f'<rect x="{px:.0f}" y="838" width="68"'
                        f' height="{pol-838:.0f}" rx="12" fill="#5b4428"'
                        f' {o(6)}/>')
    s += SL(Z_SRED, _rushnik_vyshityy(220, 744, 700, 80, t, 1059))
    # ГАДАНИЕ ПЕРВОЕ: ромашка в стакане с облетевшими лепестками
    s += SL(Z_SRED, _romashka_v_stakane(370, 752, 1.05, t,
                                        A.ease(A.seg(t, .4, 3.0))))
    # ГАДАНИЕ ВТОРОЕ: шапка с бумажками, одна тянется наружу
    tyan = A.ease(A.seg(t, 1.4, 1.8))
    s += SL(Z_SRED, _shapka_s_bumazhkami(820, 752, 1.0, t, tyan, 9, 1061))
    # ГАДАНИЕ ТРЕТЬЕ — само окно с прохожим (выше), плюс свеча у стекла
    s += SL(Z_SRED, svecha(1180, 752, t, .3, 1.3, 118)
            + teplo(1180, 690, 300, 260, .40))
    # СВАДЕБНАЯ КАРТОЧКА проступает к концу плана
    s += SL(Z_SRED, _svadebnaya_kartochka(540, 748, 300, t,
                                          A.ease(A.seg(t, 6.6, 2.0))))
    # ОДНА ФИГУРА: девушка у стола
    dx_, dy_, dh = 1020, pol, 770
    _figury_kadra((dx_, dy_, dh))
    dev = figura(dx_, dy_, dh, t, col="#8a4a5c", kant="#ffd98a", ph=.4,
                 naklon=4.0)
    r1, (c1x, c1y), _ = _ruka_so_sgibom(dx_, dy_, dh, -1, dh * .22, 10,
                                        dh * .24, 34 - 26 * tyan, t,
                                        "#8a4a5c", "#ffd98a", .2, 5.0)
    r2, (c2x, c2y), _ = _ruka_so_sgibom(dx_, dy_, dh, -1, dh * .24, 32,
                                        dh * .24, 56, t, "#8a4a5c",
                                        "#ffd98a", .7, 4.0)
    dev += r1 + r2
    s += SL(Z_SRED, dev)
    # КОСА девушки через плечо — роль читается со стоп-кадра
    gy_ = dy_ - dh * .845
    s += SL(Z_SRED, f'<path d="M{dx_+dh*.11:.0f},{gy_+dh*.02:.0f}'
                    f' q{dh*.06:.0f},{dh*.10:.0f} {dh*.015:.0f},{dh*.22:.0f}"'
                    f' fill="none" stroke="#8a6038" stroke-width="{dh*.045:.0f}"'
                    f' stroke-linecap="round"/>'
            + "".join(f'<circle cx="{dx_+dh*(.115-i*.004):.0f}"'
                      f' cy="{gy_+dh*(.06+i*.05):.0f}" r="{dh*.020:.0f}"'
                      f' fill="#9c7049" {o(3)}/>' for i in range(4))
            + f'<path d="M{dx_+dh*.11:.0f},{gy_+dh*.245:.0f} q{dh*.03:.0f},'
              f'{dh*.03:.0f} {-dh*.01:.0f},{dh*.05:.0f}" fill="none"'
              f' stroke="{TKAN}" stroke-width="{dh*.020:.0f}"/>')
    s += SL(Z_SRED, _varezhka(c1x, c1y + 2, dh, t, .2)
            + _varezhka(c2x, c2y + 2, dh, t, .7))
    # нижняя треть
    s += SL(Z_SRED, _venskiy_stul(1420, pol, 420, t, 6, False)
            + _polovik(760, pol + 42, 560, 118, "#cdbf9c", "#b8352c")
            + _dvorovaya_utvar(130, pol + 50, 220, t, 1063, ["korzina"])
            + _kot_zhivoy(620, pol + 54, t, 1.1, "#3b3430", .3, True, True)
            + _yaschiki(1800, pol + 14, t, 1065, 2, .8))
    s += SL(Z_PERED, _stolb_pered(-8, 110, "#1a120c", 0, H))
    s += vinetka(.44)
    return s


def vecher_dnya_iony(t):
    """Вечерний двор одним кадром, четыре места по словам: монета блестит на
    тропинке у калитки, на подоконнике кухни редька на блюдце с ложкой мёда,
    над банькой дым и свет в окошке, чердачное окно дома крупно показывает
    настоящую яркую луну. Бабушка в чистом платке стоит на крыльце после
    бани, обеими руками держит кружку чая, от плеч идёт пар, смотрит на
    луну."""
    rnd = random.Random(1069)
    gor = 820
    s = f'<rect width="{W}" height="{H}" fill="url(#nnoch)"/>'
    s += nebo("noch", t, True, 1071)
    s += oblaka(t, 170, 4, 1073, .26, "#6f7f8c", 18.0)
    s += SL(Z_DAL, _derevnya_ryad(gor - 160, t, 1075, ((120, 280), (1840, 240))))
    # ДОМ с чердачным окном — в нём настоящая луна
    s += SL(Z_SRED, brevna(760, 430, 900, gor - 390, 92)
            + f'<rect x="740" y="416" width="940" height="26" rx="9"'
              f' fill="#5a4530" {o(5)}/>')
    s += SL(Z_SRED, f'<path d="M700,434 L1210,196 L1720,434 Z" fill="#6b5340"'
                    f' {o(8)}/>'
            + f'<path d="M700,434 L1210,196 L1210,228 L756,438 Z"'
              f' fill="{SNEG}" opacity=".88"/>')
    px, py, pw, ph_ = 820, 440, 780, 310
    put = kontur_proema(px, py, pw, ph_, "pryam")
    vid = (f'<path d="{put}" fill="{NOCH}"/>'
           f'<circle cx="{px+pw*.56:.0f}" cy="{py+ph_*.42:.0f}" r="96"'
           f' fill="#f2f6fa" opacity="{.88+.1*abs(A.w(t,1.9,.2)):.2f}"/>'
           f'<circle cx="{px+pw*.56:.0f}" cy="{py+ph_*.42:.0f}" r="150"'
           f' fill="#cfe4f5" opacity=".16"/>'
           f'<circle cx="{px+pw*.60:.0f}" cy="{py+ph_*.34:.0f}" r="20"'
           f' fill="#cfd6de" opacity=".45"/>')
    for i in range(14):
        sx_ = px + rnd.uniform(26, pw - 26)
        sy_ = py + rnd.uniform(24, ph_ - 24)
        vid += (f'<circle cx="{sx_:.0f}" cy="{sy_:.0f}"'
                f' r="{rnd.uniform(2.5,5):.0f}" fill="#e8eef6"'
                f' opacity="{.4+.5*abs(A.w(t,1.2+i*.08,i*.3)):.2f}"/>')
    s += SL(Z_SRED, vid + mesto_stoka(px, py, pw, ph_, "pryam"))
    s += SL(Z_SRED, f'<path d="{put}" fill="none" stroke="#5f4a34"'
                    f' stroke-width="32"/>'
            + f'<line x1="{px+pw*.5:.0f}" y1="{py:.0f}" x2="{px+pw*.5:.0f}"'
              f' y2="{py+ph_:.0f}" stroke="#5f4a34" stroke-width="22"/>'
            + f'<rect x="{px-44:.0f}" y="{py-46:.0f}" width="{pw+88:.0f}"'
              f' height="40" rx="12" fill="#7d5a3c" {o(5)}/>'
            + f'<rect x="{px-32:.0f}" y="{py+ph_-10:.0f}" width="{pw+64:.0f}"'
              f' height="38" rx="12" fill="url(#dosk)" {o(6)}/>')
    # ПОДОКОННИК КУХНИ с редькой на блюдце
    s += SL(Z_SRED, okno_izby(300, 470, 380, 300, t,
                              f'<rect x="300" y="470" width="380" height="300"'
                              f' fill="#2a1d12"/>'
                              f'<rect x="312" y="482" width="356" height="276"'
                              f' fill="{SVET}"'
                              f' opacity="{.66+.14*abs(A.w(t,2.4,.3)):.2f}"/>',
                              .14, True, True))
    s += SL(Z_SRED, f'<rect x="250" y="762" width="480" height="40" rx="12"'
                    f' fill="#cfc9bc" {o(6)}/>')
    s += SL(Z_SRED, _blyudce(430, 756, .72, .5, t))
    s += SL(Z_SRED, _redka_s_yamkoy(420, 744, .68, t, 1.0, .9))
    s += SL(Z_SRED, f'<g transform="rotate(-34 540 740)">'
                    f'<ellipse cx="540" cy="740" rx="24" ry="17"'
                    f' fill="#cfd8dc" {o(4)}/>'
                    f'<ellipse cx="540" cy="738" rx="16" ry="10" fill="{ZOL}"'
                    f' opacity=".95"/>'
                    f'<rect x="552" y="733" width="76" height="12" rx="6"'
                    f' fill="#b9c6cc" {o(3)}/></g>')
    # БАНЬКА на огороде: дым и свет в окошке
    s += SL(Z_DAL, _banya_srub(50, gor + 30, 420, t, 1077, .0))
    # ЗЕМЛЯ, тропинка и монета у калитки
    s += SL(Z_SRED, f'<rect x="0" y="{gor+40:.0f}" width="{W}"'
                    f' height="{H-gor-40:.0f}" fill="#45483e"/>'
            + sneg_lezhit(gor + 70, 26)
            + _zemlya_faktura(gor + 100, 1072, 1079, 16, "#353830"))
    s += SL(Z_SRED, f'<path d="M-40,1072 Q420,940 1180,{gor+110:.0f}'
                    f' L1340,{gor+140:.0f} Q640,1000 360,1076 Z"'
                    f' fill="#6a6a5c" {o(5)}/>')
    s += SL(Z_SRED, _zabor_dosok(1480, gor - 90, 440, 180, 1081, 54))
    s += SL(Z_SRED, _kalitka_hlopaet(1700, gor + 150, 200, 260, t, True))
    s += SL(Z_SRED, _moneta_krupno(1540, 1000, 50, t, .2, True, True, .76))
    s += SL(Z_SRED, f'<circle cx="1540" cy="1000" r="86" fill="{SVET}"'
                    f' opacity="{.12+.16*abs(A.w(t,1.4,.2)):.2f}"/>')
    # КРЫЛЬЦО и ОДНА ФИГУРА: бабушка после бани с кружкой чая
    s += SL(Z_SRED, _kryl_co(640, gor + 150, 420, 180, t, 3, True, False))
    bx, by_, bh = 820, gor + 10, 700
    _figury_kadra((bx, by_, bh))
    bab = figura(bx, by_, bh, t, col="#efe8d8", kant="#ffd98a", platok=True,
                 ph=.3, naklon=3.0)
    r1, (k1x, k1y), _ = _ruka_mimo(bx, by_, bh, -1, bh * .30, 42, t,
                                   "#efe8d8", "#ffd98a", .2, 4.0)
    r2, (k2x, k2y), _ = _ruka_mimo(bx, by_, bh, 1, bh * .28, 44, t,
                                   "#efe8d8", "#ffd98a", .7, 4.0)
    bab += r1 + r2
    s += SL(Z_SRED, bab)
    # КРУЖКА ЧАЯ в обеих кистях, от неё и от плеч идёт пар
    kx_ = (k1x + k2x) * .5
    s += SL(Z_SRED, _kruzhka(kx_, k1y + 52, 1.15, 0, "#e8eef0", 1))
    s += SL(Z_SRED, par(kx_, k1y - 12, t, 4, .56, 170, .5, 1.2))
    s += SL(Z_SRED, _varezhka(k1x, k1y + 4, bh, t, .2)
            + _varezhka(k2x, k2y + 4, bh, t, .7))
    s += SL(Z_SRED, par(bx - bh * .20, by_ - bh * .66, t, 3, .46, 150, .55)
            + par(bx + bh * .20, by_ - bh * .64, t, 3, .42, 140, .62))
    # нижняя треть
    s += SL(Z_SRED, _polenica(230, 1046, 320, 200, 1083, 26)
            + _dvorovaya_utvar(560, 1050, 230, t, 1085, ["kadka", "vedro"])
            + _sledy(1420, 1070, 900, gor + 160, 7, 1087, "#2d302a", 1.0)
            + _kot_zhivoy(1180, 1042, t, 1.1, "#3b3430", .3))
    s += SL(Z_SRED, teplo(260, gor - 120, 420, 340, .32))
    s += SL(Z_LETIT, mokryy_sneg(t, 20, 1089, .40, .9))
    s += SL(Z_PERED, _stolb_pered(-8, 112, "#121018", 0, H))
    s += vinetka(.46)
    return s


